struct BackendAssociation {
    entity: void*;
    value: void*;
}

struct BackendLoop {
    head: void*;
    after: void*;
}

struct Backend {
    context: void*;
    module: void*;
    builder: void*;
    machine: void*;
    layout: void*;
    pointer_bytes: u32;
    wasm: bool;
    foreign_profile: u32;
    i8: void*;
    i32: void*;
    i64: void*;
    size_type: void*;
    pointer_type: void*;
    functions: vector(void*);
    symbols: vector(u8*);
    source_functions: vector(void*);
    source_root: void*;
    locals: vector(void*);
    globals: vector(BackendAssociation);
    strings: vector(BackendAssociation);
    loops: vector(BackendLoop);
    labels: vector(BackendAssociation);
    current: void*;
    print_fn: void*;
    trap_fn: void*;
    allocate_fn: void*;
    reallocate_fn: void*;
    deallocate_fn: void*;
    source_offset: usize;
    error_offset: usize;
    error: vector(u8);
    raw: u8*;
    optimized: u8*;
    object: void*;
}

fn backend_fail(b: Backend*, text: u8*): void {
    if b.error.length == 0 {
        backend_text(&b.error, text);
        b.error_offset = b.source_offset;
    }
}

fn backend_require(b: Backend*, ok: bool): void {
    if !ok {
        backend_fail(b, "Unable to allocate backend storage");
    }
}

fn backend_name(n: FoundationNode*): u8* {
    if n.name.data == null {
        return "";
    }
    return n.name.data;
}

fn backend_associate(values: vector(BackendAssociation)*, entity: void*, value: void*): bool {
    var needed = values.length + 1;
    var ok = vector_reserve(values, needed);
    if ok {
        values.data[values.length].entity = entity;
        values.data[values.length].value = value;
        values.length = needed;
    }
    return ok;
}

fn backend_find(values: vector(BackendAssociation)*, entity: void*): void* {
    var i: usize = 0;
    loop {
        if i == values.length {
            return null;
        }
        if values.data[i].entity == entity {
            return values.data[i].value;
        }
        i++;
    }
}

export fn backend_error(b: Backend*): u8* {
    if b.error.data == null {
        return "";
    }
    return b.error.data;
}

export fn backend_error_offset(b: Backend*): usize {
    return b.error_offset;
}

export fn backend_pointer_bytes(b: Backend*): u32 {
    return b.pointer_bytes;
}

export fn backend_raw(b: Backend*): u8* {
    return b.raw;
}

export fn backend_optimized(b: Backend*): u8* {
    return b.optimized;
}

export fn backend_bytes(b: Backend*): u8* {
    if b.object != null {
        return LLVMGetBufferStart(b.object);
    }
    return null;
}

export fn backend_size(b: Backend*): usize {
    if b.object != null {
        return LLVMGetBufferSize(b.object);
    }
    return 0;
}

export fn backend_close(b: Backend*): void {
    var present = b == null;
    if present {
        return;
    }
    present = b.object != null;
    if present {
        LLVMDisposeMemoryBuffer(b.object);
    }
    present = b.raw != null;
    if present {
        LLVMDisposeMessage(b.raw);
    }
    present = b.optimized != null;
    if present {
        LLVMDisposeMessage(b.optimized);
    }
    present = b.builder != null;
    if present {
        LLVMDisposeBuilder(b.builder);
    }
    present = b.module != null;
    if present {
        LLVMDisposeModule(b.module);
    }
    present = b.layout != null;
    if present {
        LLVMDisposeTargetData(b.layout);
    }
    present = b.machine != null;
    if present {
        LLVMDisposeTargetMachine(b.machine);
    }
    present = b.context != null;
    if present {
        LLVMContextDispose(b.context);
    }
    foreach(var & symbol in &b.symbols) {
        free(*symbol);
    }
    vector_dispose(&b.symbols);
    vector_dispose(&b.functions);
    vector_dispose(&b.source_functions);
    vector_dispose(&b.locals);
    vector_dispose(&b.globals);
    vector_dispose(&b.strings);
    vector_dispose(&b.loops);
    vector_dispose(&b.labels);
    vector_dispose(&b.error);
    free(b);
}

export fn backend_function_name(b: Backend*, index: usize): u8* {
    // O2 may erase unused LLVM declarations. Keep result names independently
    // of LLVM value lifetimes, while Foundation entities retain source spelling.
    var name = b.symbols.data[index];
    if name == null {
        return "";
    }
    return name;
}

import target_api;
import tower;
import bindings;
import text;
import .library.vector;

// Object inspection is separate from semantics. Bytes here are platform output.
struct BackendLabel {
    address: u64;
    name: vector(u8);
    priority: u32;
}

struct BackendDecoder {
    llvm: void*;
    text: vector(u8);
    data: u8*;
    length: usize;
    offset: usize;
    end: usize;
    failed: bool;
    labels: vector(BackendLabel);
    instruction_labels: bool;
}

fn backend_label_index(d: BackendDecoder*, address: u64): usize {
    var first: usize = 0;
    var last = d.labels.length;
    loop {
        if first == last {
            return first;
        }
        var distance = last -first;
        distance = distance / 2;
        var middle = first + distance;
        if d.labels.data[middle].address < address {
            first = middle + 1;
        }
        else {
            last = middle;
        }
    }
}

fn backend_label_add(d: BackendDecoder*, address: u64, name: u8*, length: usize, priority: u32): void {
    if length == 0 {
        return;
    }
    var index = backend_label_index(d, address);
    var found = index < d.labels.length;
    found &&= d.labels.data[index].address == address;
    if found {
        if d.labels.data[index].priority > priority {
            return;
        }
        d.labels.data[index].name.length = 0;
    } else {
        var needed = d.labels.length + 1;
        var ok = vector_reserve(&d.labels, needed);
        var failed = !ok;
        if failed {
            d.failed = true;
            return;
        }
        var remaining = d.labels.length -index;
        var count = remaining *sizeof(BackendLabel);
        var next = index + 1;
        copy(&d.labels.data[next], &d.labels.data[index], count);
        fill(&d.labels.data[index], 0, sizeof(BackendLabel));
        d.labels.data[index].address = address;
        d.labels.length = needed;
    }
    backend_text_append(&d.labels.data[index].name, name, length);
    d.labels.data[index].priority = priority;
}

fn backend_label_name(d: BackendDecoder*, address: u64): u8* {
    var index = backend_label_index(d, address);
    var found = index < d.labels.length;
    found &&= d.labels.data[index].address == address;
    if found {
        return d.labels.data[index].name.data;
    }
    return null;
}

// The C object API omits SectionRef::isText. Read the standardized platform
// section flags, preserving executable sections with arbitrary user names.
fn backend_object_integer(d: BackendDecoder*, offset: u64, width: u64, little: bool): u64 {
    var length = convert(u64, d.length);
    var invalid = offset > length;
    if invalid {
        d.failed = true;
        return 0;
    }
    var remaining = length -offset;
    invalid = width > remaining;
    if invalid {
        d.failed = true;
        return 0;
    }
    var value: u64 = 0;
    var factor: u64 = 1;
    var i: u64 = 0;
    loop {
        if i == width {
            return value;
        }
        var index = i;
        if !little {
            index = width - i;
            index--;
        }
        index = offset + index;
        var byte = convert(u64, d.data[convert(usize, index)]);
        var part = byte *factor;
        value = value + part;
        factor = factor * 256;
        i++;
    }
}

fn backend_section_text(d: BackendDecoder*, kind: u32, index: u64): bool {
    var elf = kind >= 6;
    elf &&= kind <= 9;
    if elf {
        var wide = kind >= 8;
        var parity = kind % 2;
        var little = parity == 0;
        var table: u64 = 0;
        var stride: u64 = 0;
        var width: u64 = 4;
        if wide {
            table = backend_object_integer(d, 40, 8, little);
            stride = backend_object_integer(d, 58, 2, little);
            width = 8;
        } else {
            table = backend_object_integer(d, 32, 4, little);
            stride = backend_object_integer(d, 46, 2, little);
        }
        var offset = index *stride;
        offset = offset + table;
        offset = offset + 8;
        var flags = backend_object_integer(d, offset, width, little);
        flags = flags & 4;
        var text = flags != 0;
        return text;
    }
    if kind == 5 {
        var header: u64 = 0;
        var magic = backend_object_integer(d, 0, 2, true);
        if magic == 23117 {
            header = backend_object_integer(d, 60, 4, true);
            header = header + 4;
        }
        var optional_offset = header + 16;
        var optional = backend_object_integer(d, optional_offset, 2, true);
        var table = header + 20;
        table = table + optional;
        var big_object = magic == 0;
        if big_object {
            var signature = backend_object_integer(d, 2, 2, true);
            big_object = signature == 65535;
            if big_object {
                table = 56;
            }
        }
        var offset = index *40;
        offset = offset + table;
        offset = offset + 36;
        var flags = backend_object_integer(d, offset, 4, true);
        flags = flags & 32;
        var text = flags != 0;
        return text;
    }
    var wide = kind >= 12;
    var parity = kind % 2;
    var little = parity == 0;
    var commands = backend_object_integer(d, 16, 4, little);
    var cursor: u64 = 28;
    var segment: u64 = 1;
    var header: u64 = 56;
    var stride: u64 = 68;
    var flags_offset: u64 = 56;
    if wide {
        cursor = 32;
        segment = 25;
        header = 72;
        stride = 80;
        flags_offset = 64;
    }
    var command: u64 = 0;
    loop {
        var done = command == commands;
        if d.failed {
            done = true;
        }
        if done {
            return false;
        }
        var tag = backend_object_integer(d, cursor, 4, little);
        var offset = cursor + 4;
        var bytes = backend_object_integer(d, offset, 4, little);
        var selected = tag == segment;
        if selected {
            offset = cursor + header;
            offset = offset - 8;
            var count = backend_object_integer(d, offset, 4, little);
            selected = index < count;
            if selected {
                offset = index * stride;
                offset = offset + cursor;
                offset = offset + header;
                offset = offset + flags_offset;
                var flags = backend_object_integer(d, offset, 4, little);
                flags = flags & 2147483648;
                var text = flags != 0;
                return text;
            }
            index = index - count;
        }
        cursor = cursor + bytes;
        command++;
    }
}

fn backend_hex(out: vector(u8)*, value: u64, digits: usize): void {
    var buffer: u8[18];
    var i = digits;
    var alphabet: u8* = "0123456789abcdef";
    for(; i != 0; i--) {
        var remainder = value % 16;
        var digit = convert(usize, remainder);
        buffer[i] = alphabet[digit];
        value = value / 16;
    }
    backend_text(out, "0x");
    backend_text_append(out, &buffer[1], digits);
}

fn backend_decimal(out: vector(u8)*, value: u64): void {
    var buffer: u8[20];
    var i: usize = 20;
    loop {
        i--;
        var remainder = value % 10;
        var digit = convert(u8, remainder);
        buffer[i] = digit + 48;
        value = value / 10;
        if value == 0 {
            break;
        }
    }
    var length = 20 -i;
    backend_text_append(out, &buffer[i], length);
}

fn backend_instructions(d: BackendDecoder*, data: u8*, length: usize, base: u64): void {
    var offset: usize = 0;
    loop {
        var done = offset == length;
        if d.text.length >= 2097152 {
            done = true;
        }
        if done {
            return;
        }
        var line: u8[1024];
        var address = base + convert(u64, offset);
        if d.instruction_labels {
            var label = backend_label_name(d, address);
            if label != null {
                backend_text(&d.text, label);
                backend_text(&d.text, ":\n");
            }
        }
        var remaining = length -offset;
        var count = LLVMDisasmInstruction(d.llvm, &data[offset], convert(u64, remaining), address, &line[0], 1024);
        backend_hex(&d.text, address, 8);
        backend_text(&d.text, "  ");
        if count != 0 {
            backend_text(&d.text, &line[0]);
        }
        else {
            backend_text(&d.text, ".byte ");
            backend_hex(&d.text, convert(u64, data[offset]), 2);
            count = 1;
        }
        backend_text(&d.text, "\n");
        offset = offset + count;
    }
}

fn backend_wasm_byte(d: BackendDecoder*): u8 {
    if d.offset >= d.end {
        d.failed = true;
        return 0;
    }
    var value = d.data[d.offset];
    d.offset++;
    return value;
}

fn backend_wasm_u32(d: BackendDecoder*): usize {
    var value: u64 = 0;
    var factor: u64 = 1;
    var i: usize = 0;
    loop {
        var byte = backend_wasm_byte(d);
        var low = byte &127;
        var part = convert(u64, low) *factor;
        value = value + part;
        if value > 4294967295 {
            d.failed = true;
            return 0;
        }
        if byte < 128 {
            return convert(usize, value);
        }
        i++;
        if i == 5 {
            d.failed = true;
            return 0;
        }
        factor = factor * 128;
    }
}

fn backend_wasm_skip(d: BackendDecoder*, count: usize): void {
    var remaining = d.end -d.offset;
    if count > remaining {
        d.failed = true;
        d.offset = d.end;
        return;
    }
    d.offset = d.offset + count;
}

fn backend_wasm_string(d: BackendDecoder*): void {
    var count = backend_wasm_u32(d);
    backend_wasm_skip(d, count);
}

fn backend_wasm_label(d: BackendDecoder*, index: usize, priority: u32): void {
    var count = backend_wasm_u32(d);
    var begin = d.offset;
    backend_wasm_skip(d, count);
    if !d.failed {
        backend_label_add(d, convert(u64, index), &d.data[begin], count, priority);
    }
}

fn backend_wasm_labels(d: BackendDecoder*): void {
    d.offset = 8;
    loop {
        var done = d.offset >= d.length;
        if d.failed {
            done = true;
        }
        if done {
            return;
        }
        d.end = d.length;
        var section = backend_wasm_byte(d);
        var length = backend_wasm_u32(d);
        var remaining = d.end -d.offset;
        var invalid = length > remaining;
        if invalid {
            d.failed = true;
            return;
        }
        d.end = d.offset + length;
        var section_end = d.end;
        if section == 7 {
            var count = backend_wasm_u32(d);
            var i: usize = 0;
            loop {
                done = i == count;
                if d.failed {
                    done = true;
                }
                if done {
                    break;
                }
                var size = backend_wasm_u32(d);
                var name = d.offset;
                backend_wasm_skip(d, size);
                var kind = backend_wasm_byte(d);
                var index = backend_wasm_u32(d);
                var function = kind == 0;
                if function {
                    if !d.failed {
                        backend_label_add(d, convert(u64, index), &d.data[name], size, 2);
                    }
                }
                i++;
            }
        }
        if section == 0 {
            var size = backend_wasm_u32(d);
            var begin = d.offset;
            backend_wasm_skip(d, size);
            if d.failed {
                return;
            }
            var name_section = size == 4;
            name_section &&= backend_prefix(&d.data[begin], "name");
            var linking = size == 7;
            linking &&= backend_prefix(&d.data[begin], "linking");
            if linking {
                backend_wasm_u32(d);
            }
            var known = name_section;
            if linking {
                known = true;
            }
            if known {
                loop {
                    done = d.offset == section_end;
                    if d.failed {
                        done = true;
                    }
                    if done {
                        break;
                    }
                    d.end = section_end;
                    var subsection = backend_wasm_byte(d);
                    var bytes = backend_wasm_u32(d);
                    remaining = d.end - d.offset;
                    invalid = bytes > remaining;
                    if invalid {
                        d.failed = true;
                        return;
                    }
                    d.end = d.offset + bytes;
                    var names = subsection == 1;
                    names &&= name_section;
                    if names {
                        var count = backend_wasm_u32(d);
                        var i: usize = 0;
                        loop {
                            done = i == count;
                            if d.failed {
                                done = true;
                            }
                            if done {
                                break;
                            }
                            var index = backend_wasm_u32(d);
                            backend_wasm_label(d, index, 3);
                            i++;
                        }
                    }
                    var symbols = subsection == 8;
                    symbols &&= linking;
                    if symbols {
                        var count = backend_wasm_u32(d);
                        var i: usize = 0;
                        loop {
                            done = i == count;
                            if d.failed {
                                done = true;
                            }
                            if done {
                                break;
                            }
                            var kind = backend_wasm_byte(d);
                            var flags = backend_wasm_u32(d);
                            var undefined_flag = flags &16;
                            var defined = undefined_flag == 0;
                            var explicit_flag = flags &64;
                            var named = explicit_flag != 0;
                            if defined {
                                named = true;
                            }
                            var data = kind == 1;
                            var section_symbol = kind == 3;
                            if data {
                                backend_wasm_string(d);
                                if defined {
                                    backend_wasm_u32(d);
                                    backend_wasm_u32(d);
                                    backend_wasm_u32(d);
                                }
                            } else {
                                var index = backend_wasm_u32(d);
                                if !section_symbol {
                                    if named {
                                        var function = kind == 0;
                                        if function {
                                            backend_wasm_label(d, index, 1);
                                        }
                                        else {
                                            backend_wasm_string(d);
                                        }
                                    }
                                }
                            }
                            i++;
                        }
                    }
                    d.offset = d.end;
                }
            }
        }
        d.offset = section_end;
    }
}

fn backend_wasm_limits(d: BackendDecoder*): void {
    var flags = backend_wasm_u32(d);
    backend_wasm_u32(d);
    var maximum = flags &1;
    if maximum != 0 {
        backend_wasm_u32(d);
    }
    if flags > 3 {
        d.failed = true;
    }
}

fn backend_wasm_disassembly(d: BackendDecoder*): void {
    if d.length < 8 {
        d.failed = true;
        return;
    }
    var header: u8[8];
    fill(&header[0], 0, 8);
    header[1] = 97;
    header[2] = 115;
    header[3] = 109;
    header[4] = 1;
    for(var h: usize = 0; h != 8; h++) {
        if d.data[h] != header[h] {
            d.failed = true;
            return;
        }
    }
    backend_wasm_labels(d);
    if d.failed {
        return;
    }
    d.offset = 8;
    var imports: usize = 0;
    backend_text(&d.text, "; Wasm instructions; addresses are file offsets.\n");
    loop {
        var done = d.offset == d.length;
        if d.failed {
            done = true;
        }
        if done {
            return;
        }
        d.end = d.length;
        var section = backend_wasm_byte(d);
        var length = backend_wasm_u32(d);
        var remaining = d.end -d.offset;
        var invalid = length > remaining;
        if invalid {
            d.failed = true;
            return;
        }
        d.end = d.offset + length;
        if section == 2 {
            var count = backend_wasm_u32(d);
            var i: usize = 0;
            loop {
                done = i == count;
                if d.failed {
                    done = true;
                }
                if done {
                    break;
                }
                backend_wasm_string(d);
                backend_wasm_string(d);
                var kind = backend_wasm_byte(d);
                if kind == 0 {
                    imports++;
                    backend_wasm_u32(d);
                }
                if kind == 1 {
                    backend_wasm_byte(d);
                    backend_wasm_limits(d);
                }
                if kind == 2 {
                    backend_wasm_limits(d);
                }
                if kind == 3 {
                    backend_wasm_skip(d, 2);
                }
                if kind == 4 {
                    backend_wasm_byte(d);
                    backend_wasm_u32(d);
                }
                invalid = kind > 4;
                if invalid {
                    d.failed = true;
                }
                i++;
            }
        }
        if section == 10 {
            var section_end = d.end;
            var count = backend_wasm_u32(d);
            var i: usize = 0;
            loop {
                done = i == count;
                if d.failed {
                    done = true;
                }
                if d.text.length >= 2097152 {
                    done = true;
                }
                if done {
                    break;
                }
                d.end = section_end;
                var size = backend_wasm_u32(d);
                remaining = d.end - d.offset;
                invalid = size > remaining;
                if invalid {
                    d.failed = true;
                    return;
                }
                d.end = d.offset + size;
                var locals = backend_wasm_u32(d);
                var j: usize = 0;
                loop {
                    done = j == locals;
                    if d.failed {
                        done = true;
                    }
                    if done {
                        break;
                    }
                    backend_wasm_u32(d);
                    backend_wasm_byte(d);
                    j++;
                }
                if d.failed {
                    return;
                }
                backend_text(&d.text, "\nfunc[");
                var index = imports + i;
                backend_decimal(&d.text, convert(u64, index));
                backend_text(&d.text, "]");
                var name = backend_label_name(d, convert(u64, index));
                if name != null {
                    backend_text(&d.text, " <");
                    backend_text(&d.text, name);
                    backend_text(&d.text, ">");
                }
                backend_text(&d.text, ":\n");
                var bytes = d.end -d.offset;
                backend_instructions(d, &d.data[d.offset], bytes, convert(u64, d.offset));
                d.offset = d.end;
                i++;
            }
            d.end = section_end;
        }
        d.offset = d.end;
    }
}

export fn backend_disassemble(data: u8*, length: usize, triple: u8*): BackendDecoder* {
    var d = alloc(BackendDecoder, 1);
    var absent = d == null;
    if absent {
        return null;
    }
    *d = default;
    d.data = data;
    d.length = length;
    d.end = length;
    backend_initialize_targets();
    d.llvm = LLVMCreateDisasm(triple, null, 0, null, null);
    absent = d.llvm == null;
    if absent {
        backend_text(&d.text, "Disassembler unavailable for ");
        backend_text(&d.text, triple);
        return d;
    }
    var options: u64 = 2;
    if backend_prefix(triple, "x86") {
        options = options | 4;
    }
    LLVMSetDisasmOptions(d.llvm, options);
    var wasm = backend_prefix(triple, "wasm");
    if wasm {
        backend_wasm_disassembly(d);
    }
    else {
        var buffer = LLVMCreateMemoryBufferWithMemoryRangeCopy(data, length, "Tower");
        var error: u8* = null;
        var binary = LLVMCreateBinary(buffer, null, &error);
        absent = binary == null;
        if absent {
            backend_text(&d.text, error);
            LLVMDisposeMessage(error);
        }
        else {
            var kind = LLVMBinaryGetType(binary);
            var supported = kind >= 5;
            supported &&= kind <= 13;
            if !supported {
                backend_text(&d.text, "Disassembly requires a platform object or executable");
                LLVMDisposeBinary(binary);
                LLVMDisposeMemoryBuffer(buffer);
                LLVMDisasmDispose(d.llvm);
                d.llvm = null;
                return d;
            }
            d.instruction_labels = true;
            var symbol = LLVMObjectFileCopySymbolIterator(binary);
            loop {
                var done = symbol == null;
                if done {
                    break;
                }
                done = LLVMObjectFileIsSymbolIteratorAtEnd(binary, symbol) != 0;
                if done {
                    break;
                }
                var name = LLVMGetSymbolName(symbol);
                backend_label_add(d, LLVMGetSymbolAddress(symbol), name, backend_length(name), 1);
                LLVMMoveToNextSymbol(symbol);
            }
            var present = symbol != null;
            if present {
                LLVMDisposeSymbolIterator(symbol);
            }
            var section = LLVMObjectFileCopySectionIterator(binary);
            var section_index: u64 = 0;
            loop {
                var done = section == null;
                if done {
                    break;
                }
                done = LLVMObjectFileIsSectionIteratorAtEnd(binary, section) != 0;
                var full = d.text.length >= 2097152;
                if full {
                    done = true;
                }
                if done {
                    break;
                }
                var name = LLVMGetSectionName(section);
                var text = backend_section_text(d, kind, section_index);
                if text {
                    backend_text(&d.text, "\n");
                    backend_text(&d.text, name);
                    backend_text(&d.text, ":\n");
                    var contents = LLVMGetSectionContents(section);
                    var size = convert(usize, LLVMGetSectionSize(section));
                    backend_instructions(d, contents, size, LLVMGetSectionAddress(section));
                }
                LLVMMoveToNextSection(section);
                section_index++;
            }
            absent = section == null;
            present = !absent;
            if present {
                LLVMDisposeSectionIterator(section);
            }
            LLVMDisposeBinary(binary);
        }
        LLVMDisposeMemoryBuffer(buffer);
    }
    if d.failed {
        if wasm {
            backend_text(&d.text, "Invalid WebAssembly code section\n");
        }
        else {
            backend_text(&d.text, "Invalid platform object section metadata\n");
        }
    }
    var full = d.text.length >= 2097152;
    if full {
        backend_text(&d.text, "Disassembly display limited to 2 MiB.\n");
    }
    LLVMDisasmDispose(d.llvm);
    d.llvm = null;
    return d;
}

export fn backend_disassembly_text(d: BackendDecoder*): u8* {
    if d.text.data == null {
        return "";
    }
    return d.text.data;
}

export fn backend_disassembly_close(d: BackendDecoder*): void {
    if d == null {
        return;
    }
    vector_dispose(&d.text);
    foreach(var & label in &d.labels) {
        vector_dispose(&(*label).name);
    }
    vector_dispose(&d.labels);
    free(d);
}

import tower;

// Translate the former native runtime header generator into Tower. The output
// is ordinary compilable Tower with exact hex bytes and an explicit length.
extern fn fopen(path: u8*, mode: u8*): void*;

extern fn fclose(file: void*): i32;

extern fn fgetc(file: void*): i32;

extern fn fputc(byte: i32, file: void*): i32;

extern fn fputs(text: u8*, file: void*): i32;

extern fn ferror(file: void*): i32;

extern fn puts(text: u8*): i32;

fn embed_runtime_size(out: void*, value: usize): bool {
    var digits: u8[20];
    var count: usize = 0;
    loop {
        digits[count] = convert(u8, value % 10) + 48;
        count++;
        value /= 10;
        if value == 0 {
            break;
        }
    }
    while count != 0 {
        count--;
        if fputc(convert(i32, digits[count]), out) < 0 {
            return false;
        }
    }
    return true;
}

export fn main(argc: i32, argv: u8**): i32 {
    if argc != 3 {
        puts("embed-runtime object output.tower");
        return 1;
    }
    var input = fopen(argv[1], "rb");
    if input == null {
        puts("Cannot open runtime object");
        return 1;
    }
    var output = fopen(argv[2], "wb");
    if output == null {
        fclose(input);
        puts("Cannot write runtime Tower source");
        return 1;
    }
    var ok = fputs("// Generated from the selected Tower runtime target object.\nexport fn backend_worker_runtime_hex(): u8* { return \"", output) >= 0;
    var count: usize = 0;
    var hex: u8* = "0123456789abcdef";
    while ok {
        var byte = fgetc(input);
        if byte < 0 {
            break;
        }
        ok = fputc(convert(i32, hex[convert(usize, byte) / 16]), output) >= 0;
        ok &&= fputc(convert(i32, hex[convert(usize, byte) % 16]), output) >= 0;
        if count == ~convert(usize, 0) {
            ok = false;
            break;
        }
        count++;
    }
    ok &&= ferror(input) == 0;
    ok &&= fputs("\"; }\nexport fn backend_worker_runtime_size(): usize { return ", output) >= 0;
    ok &&= embed_runtime_size(output, count);
    ok &&= fputs("; }\n", output) >= 0;
    var input_status = fclose(input);
    var output_status = fclose(output);
    if !ok || input_status != 0 || output_status != 0 {
        puts("Unable to embed runtime object");
        return 1;
    }
    return 0;
}

import tower;

// The selected platform implementation exports these concrete C ABI functions.
extern fn backend_file_seek(file: void*, offset: i64, origin: i32): i32;

extern fn backend_file_position(file: void*): i64;

import tower;

// POSIX and WASI use the explicit 64-bit off_t interfaces.
extern fn fseeko(file: void*, offset: i64, origin: i32): i32;

extern fn ftello(file: void*): i64;

export fn backend_file_seek(file: void*, offset: i64, origin: i32): i32 {
    return fseeko(file, offset, origin);
}

export fn backend_file_position(file: void*): i64 {
    return ftello(file);
}

import tower;

// UCRT's explicit 64-bit interfaces avoid assuming Windows long is pointer-sized.
extern fn _fseeki64(file: void*, offset: i64, origin: i32): i32;

extern fn _ftelli64(file: void*): i64;

export fn backend_file_seek(file: void*, offset: i64, origin: i32): i32 {
    return _fseeki64(file, offset, origin);
}

export fn backend_file_position(file: void*): i64 {
    return _ftelli64(file);
}

import tower;
import foreign_itanium;
import foreign_microsoft;
import foreign_reader;
import text;

// Returns owned text/error views; release with foreign_name_close. The profile
// describes the foreign compiler, never the host running this Tower function.
fn foreign_profile(m: ForeignName*, profile: u32): void {
    if profile == foreign_windows_arm64ec {
        foreign_profile(m, foreign_windows_arm64);
        m.profile = foreign_windows_arm64ec;
        return;
    }
    m.profile = profile;
    m.abi = 1;
    m.pointer_bytes = 8;
    m.long_bytes = 8;
    m.arch = 2;
    if profile == foreign_wasi {
        m.pointer_bytes = 4;
        m.long_bytes = 4;
        m.arch = 0;
    }
    if profile == foreign_macos_x64 {
        m.object_format = 1;
    }
    if profile == foreign_macos_arm64 {
        m.object_format = 1;
        m.arch = 3;
    }
    if profile == foreign_windows_x64 {
        m.object_format = 2;
        m.long_bytes = 4;
        m.abi = 2;
    }
    if profile == foreign_windows_x86 {
        m.object_format = 2;
        m.long_bytes = 4;
        m.pointer_bytes = 4;
        m.arch = 1;
        m.abi = 2;
    }
    if profile == foreign_mingw_x64 {
        m.object_format = 2;
        m.long_bytes = 4;
    }
    if profile == foreign_linux_arm64 {
        m.arch = 3;
    }
    if profile == foreign_linux_x86 {
        m.pointer_bytes = 4;
        m.long_bytes = 4;
        m.arch = 1;
    }
    if profile == foreign_windows_arm64 {
        m.object_format = 2;
        m.long_bytes = 4;
        m.arch = 3;
        m.abi = 2;
    }
    if profile == 0 {
        foreign_fail(m, "Unknown foreign ABI profile");
    }
    if profile > foreign_windows_arm64ec {
        foreign_fail(m, "Unknown foreign ABI profile");
    }
}

fn foreign_argument_bytes(m: ForeignName*, type: ForeignType*): usize {
    if type.kind == 3 {
        return convert(usize, m.pointer_bytes);
    }
    if type.kind == 4 {
        return convert(usize, m.pointer_bytes);
    }
    if type.kind == 5 {
        return convert(usize, m.pointer_bytes);
    }
    if type.kind == 1 {
        if backend_equal(type.name, "x") {
            return 8;
        }
        if backend_equal(type.name, "y") {
            return 8;
        }
        if backend_equal(type.name, "d") {
            return 8;
        }
        if backend_equal(type.name, "e") {
            return 8;
        }
        if backend_equal(type.name, "n") {
            return 16;
        }
        if backend_equal(type.name, "o") {
            return 16;
        }
        if backend_equal(type.name, "l") {
            return convert(usize, m.long_bytes);
        }
        if backend_equal(type.name, "m") {
            return convert(usize, m.long_bytes);
        }
        return 4;
    }
    foreign_fail(m, "C byte-count decoration needs an explicit scalar/pointer ABI signature");
    return 0;
}

fn foreign_c(m: ForeignName*, object: bool): void {
    if m.name.scope != null {
        foreign_fail(m, "C linkage uses an unqualified name");
        return;
    }
    if m.name.template_id {
        foreign_fail(m, "C linkage cannot name a template");
        return;
    }
    if m.member != 0 {
        foreign_fail(m, "C linkage cannot name a member function");
        return;
    }
    var cc = m.function.convention;
    if m.function.variadic {
        cc = 1;
    }
    var decorate = m.object_format == 2;
    var counted = cc == 4;
    if m.arch == 1 {
        if cc == 2 {
            counted = true;
        }
        if cc == 3 {
            counted = true;
        }
    }
    if !decorate {
        counted = false;
    }
    if !object {
        counted = false;
    }
    if object {
        if m.profile == foreign_windows_arm64ec {
            backend_text(&m.text, "#");
        }
        if m.object_format == 1 {
            backend_text(&m.text, "_");
        }
        if decorate {
            if m.arch == 1 {
                if cc == 3 {
                    backend_text(&m.text, "@");
                }
                else {
                    if cc != 4 {
                        backend_text(&m.text, "_");
                    }
                }
            }
        }
    }
    backend_text(&m.text, m.name.name);
    if counted {
        backend_text(&m.text, "@");
        if cc == 4 {
            backend_text(&m.text, "@");
        }
        var count: usize = 0;
        foreach(var & arg in &m.function.args) {
            count = count + foreign_argument_bytes(m, *arg);
        }
        foreign_number(&m.text, count, 10);
    }
}

export fn foreign_mangle(profile: u32, declaration: u8*, cpp: bool, object: bool): ForeignName* {
    var m = alloc(ForeignName, 1);
    if m == null {
        return null;
    }
    *m = default;
    m.object_symbol = object;
    foreign_profile(m, profile);
    foreign_lex(m, declaration);
    if m.error.length == 0 {
        foreign_declaration(m);
    }
    if m.error.length == 0 {
        if cpp {
            if object {
                if m.object_format == 1 {
                    backend_text(&m.text, "_");
                }
            }
            if m.abi == 1 {
                foreign_itanium(m);
            }
            else {
                foreign_microsoft(m);
            }
        } else {
            foreign_c(m, object);
        }
    }
    if m.error.length != 0 {
        m.text.length = 0;
        if m.text.data != null {
            m.text.data[0] = 0;
        }
    }
    return m;
}

export fn cpp_name(profile: u32, declaration: u8*): ForeignName* {
    return foreign_mangle(profile, declaration, true, false);
}

export fn c_name(profile: u32, declaration: u8*): ForeignName* {
    return foreign_mangle(profile, declaration, false, false);
}

export fn foreign_name_text(m: ForeignName*): u8* {
    if m == null {
        return "";
    }
    if m.text.data == null {
        return "";
    }
    return m.text.data;
}

export fn foreign_name_error(m: ForeignName*): u8* {
    if m == null {
        return "Unable to allocate foreign name result";
    }
    if m.error.data == null {
        return "";
    }
    return m.error.data;
}

import tower;
import foreign_microsoft;
import foreign_reader;
import text;

fn foreign_array(m: ForeignName*, base: ForeignType*): ForeignType* {
    if foreign_take(m, "[") == false {
        return base;
    }
    var type = foreign_node(m, 6);
    if foreign_take(m, "]") == false {
        type.count = foreign_integer(m);
        foreign_expect(m, "]");
    }
    m.depth++;
    if m.depth > 64 {
        foreign_fail(m, "Foreign declarator nesting exceeds 64");
        type.base = base;
    }
    else {
        type.base = foreign_array(m, base);
    }
    m.depth--;
    return type;
}

fn foreign_member_owner(m: ForeignName*): ForeignType* {
    var i = m.at;
    loop {
        if i >= m.tokens.length {
            return null;
        }
        var word = m.tokens.data[i];
        if foreign_word(word[0]) == false {
            return null;
        }
        i++;
        if i >= m.tokens.length {
            return null;
        }
        if backend_equal(m.tokens.data[i], "::") == false {
            return null;
        }
        i++;
        if i >= m.tokens.length {
            return null;
        }
        if backend_equal(m.tokens.data[i], "*") {
            break;
        }
    }
    return foreign_name_parts(m);
}

fn foreign_ms_array(m: ForeignName*, type: ForeignType*): void {
    backend_text(&m.text, "Y");
    var rank: usize = 0;
    var base = type;
    loop {
        if base.kind != 6 {
            break;
        }
        rank++;
        base = base.base;
    }
    foreign_ms_number(m, convert(u64, rank));
    var dimension = type;
    loop {
        if dimension.kind != 6 {
            break;
        }
        foreign_ms_number(m, dimension.count);
        dimension = dimension.base;
    }
    if base.cv != 0 {
        backend_text(&m.text, "$$C");
        foreign_ms_cv(m, base.cv);
    }
    foreign_ms_type(m, base, false);
}

fn foreign_ms_member(m: ForeignName*, type: ForeignType*): void {
    var cv = type.cv &3;
    cv = cv + 80;
    var byte = convert(u8, cv);
    backend_text_append(&m.text, &byte, 1);
    if type.base.kind == 7 {
        backend_text(&m.text, "8");
        foreign_ms_name(m, type.scope);
        if m.pointer_bytes == 8 {
            backend_text(&m.text, "E");
        }
        if type.base.ref == 1 {
            backend_text(&m.text, "G");
        }
        if type.base.ref == 2 {
            backend_text(&m.text, "H");
        }
        foreign_ms_cv(m, type.base.cv);
        foreign_ms_cc(m, type.base.convention, true);
        foreign_ms_type(m, type.base.base, true);
        foreign_ms_parameters(m, type.base);
        if type.base.nothrow {
            backend_text(&m.text, "_E");
        }
        else {
            backend_text(&m.text, "Z");
        }
    } else {
        if m.pointer_bytes == 8 {
            backend_text(&m.text, "E");
        }
        cv = type.base.cv & 3;
        cv = cv + 81;
        byte = convert(u8, cv);
        backend_text_append(&m.text, &byte, 1);
        foreign_ms_name(m, type.scope);
        foreign_ms_type(m, type.base, false);
    }
}

import tower;
import foreign_reader;

// Optional surface syntax. A single colon separates adjacent words, so
// the shared name reader and formatter preserve their lexical boundaries:
// cpp_name(int:foo(void*:bar)). The API and quoted Foundation name accept spaces.
[contextual][identifier] token ForeignWord = /[A-Za-z_][A-Za-z0-9_]*|[0-9]+/;
parse ForeignGroup = '(' ForeignPieces ')';
parse ForeignPunctuation = ':' | '::' | '*' | '&' | '&&' | '<' | '>' | ',' | ';' | '=' | '[' | ']' | '~'
                          | '...' | '-' | '+' | '/' | '%' | '^' | '!' | '|' | '.';
// Adjacent words need a separator so they cannot silently become another type.
parse ForeignPieces = | ForeignPunctuation ForeignPieces | ForeignGroup ForeignPieces
                     | ForeignWord ForeignAfterWord;
parse ForeignAfterWord = | ForeignPunctuation ForeignPieces | ForeignGroup ForeignPieces;
parse ForeignName = 'cpp_name' '(' ForeignPieces ')' | 'c_name' '(' ForeignPieces ')';
parse CoreExternal |= 'extern' 'fn' $name:ForeignName '(' $params:CoreParameters? ')' ':' $type:CoreType ';';
parse CoreExport |= 'export' 'fn' $name:ForeignName '(' $params:CoreParameters? ')' ':' $type:CoreType $body:CoreBlock;
parse CoreCall |= $name:ForeignName '(' $args:CoreArguments? ')';

import tower;
import foreign_operators;
import foreign_reader;
import text;
import .library.vector;

fn foreign_number(out: vector(u8)*, value: usize, radix: usize): void {
    foreign_number64(out, convert(u64, value), convert(u64, radix));
}

// Itanium ABI 5.1. Substitution keys describe canonical foreign types/scopes;
// the ordered table is local to one mangling and contains no host addresses.
fn foreign_number64(out: vector(u8)*, value: u64, radix: u64): void {
    var digits: u8[64];
    var count: usize = 0;
    loop {
        var digit = value % radix;
        var byte = digit + 48;
        if digit >= 10 {
            byte = digit + 55;
        }
        digits[count] = convert(u8, byte);
        count++;
        value = value / radix;
        if value == 0 {
            break;
        }
    }
    loop {
        if count == 0 {
            break;
        }
        count--;
        backend_text_append(out, &digits[count], 1);
    }
}

fn foreign_key(out: vector(u8)*, type: ForeignType*): void {
    if type == null {
        backend_text(out, "_");
        return;
    }
    foreign_number(out, convert(usize, type.kind), 10);
    backend_text(out, ":");
    foreign_number(out, convert(usize, type.cv), 10);
    backend_text(out, ":");
    backend_text(out, type.name);
    backend_text(out, "{");
    foreign_key(out, type.scope);
    foreign_key(out, type.base);
    foreign_number64(out, type.count, 10);
    foreign_number(out, convert(usize, type.ref), 10);
    foreign_number(out, convert(usize, type.convention), 10);
    if type.nothrow {
        backend_text(out, "n");
    }
    if type.variadic {
        backend_text(out, "z");
    }
    if type.template_id {
        backend_text(out, "I");
    }
    foreach(var & arg in &type.args) {
        foreign_key(out, *arg);
    }
    backend_text(out, "}");
}

fn foreign_substitute(m: ForeignName*, type: ForeignType*, insert: bool): bool {
    var key: vector(u8);
    vector_init(&key);
    defer vector_dispose(&key);
    foreign_key(&key, type);
    var i: usize = 0;
    for(; i != m.substitutions.length; i++) {
        if backend_equal(key.data, m.substitutions.data[i]) {
            if !insert {
                backend_text(&m.text, "S");
                if i != 0 {
                    var n = i -1;
                    foreign_number(&m.text, n, 36);
                }
                backend_text(&m.text, "_");
            }
            return true;
        }
    }
    if insert {
        foreign_require(m, vector_push(&m.substitutions, foreign_copy(m, key.data, key.length)));
    }
    return false;
}

fn foreign_std(type: ForeignType*): bool {
    if type == null {
        return false;
    }
    if type.scope != null {
        return false;
    }
    return backend_equal(type.name, "std");
}

fn foreign_it_special(type: ForeignType*): u8* {
    if foreign_std(type) {
        return "St";
    }
    if foreign_std(type.scope) {
        if !type.template_id {
            if backend_equal(type.name, "allocator") {
                return "Sa";
            }
            if backend_equal(type.name, "basic_string") {
                return "Sb";
            }
        }
    }
    return "";
}

fn foreign_it_qualifiers(m: ForeignName*, cv: u32): void {
    var flag = cv &4;
    if flag != 0 {
        backend_text(&m.text, "r");
    }
    flag = cv & 2;
    if flag != 0 {
        backend_text(&m.text, "V");
    }
    flag = cv & 1;
    if flag != 0 {
        backend_text(&m.text, "K");
    }
}

fn foreign_it_arguments(m: ForeignName*, type: ForeignType*): void {
    backend_text(&m.text, "I");
    foreach(var & arg in &type.args) {
        foreign_it_type(m, *arg);
    }
    backend_text(&m.text, "E");
}

fn foreign_it_component(m: ForeignName*, type: ForeignType*): void {
    if type.operator_name {
        backend_text(&m.text, foreign_operator_code(m, type.name, false));
        return;
    }
    if type.template_id {
        var prefix = foreign_clone(m, type);
        prefix.template_id = false;
        prefix.args.length = 0;
        var special = foreign_it_special(prefix);
        if special[0] != 0 {
            backend_text(&m.text, special);
        }
        else {
            if !foreign_substitute(m, prefix, false) {
                foreign_number(&m.text, backend_length(type.name), 10);
                backend_text(&m.text, type.name);
                foreign_substitute(m, prefix, true);
            }
        }
        foreign_it_arguments(m, type);
    } else {
        foreign_number(&m.text, backend_length(type.name), 10);
        backend_text(&m.text, type.name);
    }
}

fn foreign_it_prefix(m: ForeignName*, type: ForeignType*): void {
    if type == null {
        return;
    }
    var special = foreign_it_special(type);
    if special[0] != 0 {
        backend_text(&m.text, special);
        return;
    }
    if foreign_substitute(m, type, false) {
        return;
    }
    foreign_it_prefix(m, type.scope);
    foreign_it_component(m, type);
    foreign_substitute(m, type, true);
}

fn foreign_it_name(m: ForeignName*, type: ForeignType*, function: bool): void {
    var nested = type.scope != null;
    if foreign_std(type.scope) {
        nested = false;
    }
    if nested {
        backend_text(&m.text, "N");
        if function {
            foreign_it_qualifiers(m, m.function.cv);
            if m.function.ref == 1 {
                backend_text(&m.text, "R");
            }
            if m.function.ref == 2 {
                backend_text(&m.text, "O");
            }
        }
    }
    foreign_it_prefix(m, type.scope);
    var special: u8* = "";
    if function {
        if m.special == 1 {
            special = "C1";
        }
        if m.special == 2 {
            special = "C2";
        }
        if m.special == 4 {
            special = "D1";
        }
        if m.special == 5 {
            special = "D2";
        }
        if m.special == 6 {
            special = "D0";
        }
    }
    if special[0] != 0 {
        backend_text(&m.text, special);
    }
    else {
        foreign_it_component(m, type);
    }
    if function {
        // ABI tags are explicitly supplied because a declaration does not carry
        // a header's inline-namespace attributes or inferred return-type tags.
        foreach(var & abi_tag in &m.abi_tags) {
            backend_text(&m.text, "B");
            foreign_number(&m.text, backend_length(*abi_tag), 10);
            backend_text(&m.text, *abi_tag);
        }
    }
    if nested {
        backend_text(&m.text, "E");
    }
}

fn foreign_it_parameters(m: ForeignName*, type: ForeignType*): void {
    if type.args.length == 0 {
        if !type.variadic {
            backend_text(&m.text, "v");
        }
    }
    foreach(var & arg in &type.args) {
        foreign_it_type(m, *arg);
    }
    if type.variadic {
        backend_text(&m.text, "z");
    }
}

fn foreign_it_type(m: ForeignName*, type: ForeignType*): void {
    if type.cv == 0 {
        var standard = foreign_it_standard(type);
        if standard[0] != 0 {
            backend_text(&m.text, standard);
            return;
        }
    }
    var builtin = type.kind == 1;
    builtin &&= type.cv == 0;
    if builtin {
        backend_text(&m.text, type.name);
        return;
    }
    if type.kind == 9 {
        backend_text(&m.text, "L");
        foreign_it_type(m, type.base);
        if type.ref != 0 {
            backend_text(&m.text, "n");
        }
        foreign_number64(&m.text, type.count, 10);
        backend_text(&m.text, "E");
        return;
    }
    if foreign_substitute(m, type, false) {
        return;
    }
    if type.cv != 0 {
        foreign_it_qualifiers(m, type.cv);
        var base = foreign_clone(m, type);
        base.cv = 0;
        foreign_it_type(m, base);
    } else {
        if type.kind == 2 {
            foreign_it_name(m, type, false);
        }
        else {
            if type.kind == 3 {
                backend_text(&m.text, "P");
                foreign_it_type(m, type.base);
            }
            else {
                if type.kind == 4 {
                    backend_text(&m.text, "R");
                    foreign_it_type(m, type.base);
                }
                else {
                    if type.kind == 5 {
                        backend_text(&m.text, "O");
                        foreign_it_type(m, type.base);
                    }
                    else {
                        if type.kind == 6 {
                            backend_text(&m.text, "A");
                            foreign_number64(&m.text, type.count, 10);
                            backend_text(&m.text, "_");
                            foreign_it_type(m, type.base);
                        } else {
                            if type.kind == 7 {
                                if type.nothrow {
                                    backend_text(&m.text, "Do");
                                }
                                backend_text(&m.text, "F");
                                foreign_it_type(m, type.base);
                                foreign_it_parameters(m, type);
                                if type.ref == 1 {
                                    backend_text(&m.text, "R");
                                }
                                if type.ref == 2 {
                                    backend_text(&m.text, "O");
                                }
                                backend_text(&m.text, "E");
                            } else {
                                if type.kind == 8 {
                                    backend_text(&m.text, "M");
                                    foreign_it_type(m, type.scope);
                                    foreign_it_type(m, type.base);
                                } else {
                                    if type.kind == 10 {
                                        backend_text(&m.text, "T");
                                        if type.count != 0 {
                                            var index = type.count -1;
                                            foreign_number64(&m.text, index, 10);
                                        }
                                        backend_text(&m.text, "_");
                                    } else {
                                        foreign_fail(m, "Unsupported Itanium foreign type");
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    foreign_substitute(m, type, true);
}

fn foreign_itanium(m: ForeignName*): void {
    foreign_sort_tags(m);
    if m.function.convention > 1 {
        foreign_fail(m, "This Itanium profile does not support the requested calling convention");
        return;
    }
    backend_text(&m.text, "_Z");
    foreign_it_name(m, m.name, true);
    if m.name.template_id {
        foreign_it_type(m, m.function.base);
    }
    foreign_it_parameters(m, m.function);
}

import tower;
import foreign_declarators;
import foreign_itanium;
import foreign_operators;
import foreign_reader;
import text;
import .library.vector;

// Microsoft name mangling. Source of truth/reference: upstream Clang MicrosoftMangle.
// Name backreferences and parameter backreferences have separate scopes.
fn foreign_ms_builtin(type: ForeignType*): u8* {
    var code = type.name;
    if backend_equal(code, "v") {
        return "X";
    }
    if backend_equal(code, "a") {
        return "C";
    }
    if backend_equal(code, "c") {
        return "D";
    }
    if backend_equal(code, "h") {
        return "E";
    }
    if backend_equal(code, "s") {
        return "F";
    }
    if backend_equal(code, "t") {
        return "G";
    }
    if backend_equal(code, "i") {
        return "H";
    }
    if backend_equal(code, "j") {
        return "I";
    }
    if backend_equal(code, "l") {
        return "J";
    }
    if backend_equal(code, "m") {
        return "K";
    }
    if backend_equal(code, "f") {
        return "M";
    }
    if backend_equal(code, "d") {
        return "N";
    }
    if backend_equal(code, "e") {
        return "O";
    }
    if backend_equal(code, "x") {
        return "_J";
    }
    if backend_equal(code, "y") {
        return "_K";
    }
    if backend_equal(code, "n") {
        return "_L";
    }
    if backend_equal(code, "o") {
        return "_M";
    }
    if backend_equal(code, "b") {
        return "_N";
    }
    if backend_equal(code, "Du") {
        return "_Q";
    }
    if backend_equal(code, "Ds") {
        return "_S";
    }
    if backend_equal(code, "Di") {
        return "_U";
    }
    if backend_equal(code, "w") {
        return "_W";
    }
    if backend_equal(code, "Dn") {
        return "$$T";
    }
    return "";
}

fn foreign_ms_number(m: ForeignName*, value: u64): void {
    if value == 0 {
        backend_text(&m.text, "A@");
        return;
    }
    if value <= 10 {
        var digit = value -1;
        foreign_number64(&m.text, digit, 10);
        return;
    }
    var digits: u8[32];
    var count: usize = 0;
    loop {
        var part = value % 16;
        part = part + 65;
        digits[count] = convert(u8, part);
        count++;
        value = value / 16;
        if value == 0 {
            break;
        }
    }
    loop {
        if count == 0 {
            break;
        }
        count--;
        backend_text_append(&m.text, &digits[count], 1);
    }
    backend_text(&m.text, "@");
}

fn foreign_ms_cv(m: ForeignName*, cv: u32): void {
    var value = cv &3;
    value = value + 65;
    var byte = convert(u8, value);
    backend_text_append(&m.text, &byte, 1);
}

fn foreign_ms_identifier(m: ForeignName*, name: u8*): void {
    var i: usize = 0;
    for(; i != m.ms_names.length; i++) {
        if backend_equal(m.ms_names.data[i], name) {
            foreign_number(&m.text, i, 10);
            return;
        }
    }
    backend_text(&m.text, name);
    backend_text(&m.text, "@");
    if m.ms_names.length < 10 {
        foreign_require(m, vector_push(&m.ms_names, name));
    }
}

fn foreign_ms_component(m: ForeignName*, type: ForeignType*): void {
    if type.operator_name {
        backend_text(&m.text, foreign_operator_code(m, type.name, true));
        return;
    }
    if !type.template_id {
        foreign_ms_identifier(m, type.name);
        return;
    }
    // A template-id is entered as one name into the outer backreference table.
    var outer: vector(u8*);
    copy(&outer, &m.ms_names, sizeof(vector(u8*)));
    vector_init(&m.ms_names);
    var start = m.text.length;
    backend_text(&m.text, "?$");
    foreign_ms_identifier(m, type.name);
    foreach(var argument in &type.args) {
        if argument.kind == 9 {
            backend_text(&m.text, "$0");
            if argument.ref != 0 {
                backend_text(&m.text, "?");
            }
            foreign_ms_number(m, argument.count);
        } else {
            foreign_ms_type(m, argument, false);
        }
    }
    var count = m.text.length -start;
    var encoded = foreign_copy(m, &m.text.data[start], count);
    m.text.length = start;
    m.text.data[start] = 0;
    vector_dispose(&m.ms_names);
    copy(&m.ms_names, &outer, sizeof(vector(u8*)));
    foreign_ms_identifier(m, encoded);
}

fn foreign_ms_name(m: ForeignName*, type: ForeignType*): void {
    var part = type;
    loop {
        if part == null {
            break;
        }
        foreign_ms_component(m, part);
        part = part.scope;
    }
    backend_text(&m.text, "@");
}

fn foreign_ms_cc(m: ForeignName*, cc: u32, member: bool): void {
    if cc == 0 {
        cc = 1;
        if m.arch == 1 {
            if member {
                cc = 5;
            }
        }
    }
    if m.arch != 1 {
        if cc != 4 {
            cc = 1;
        }
    }
    if cc == 1 {
        backend_text(&m.text, "A");
    }
    if cc == 2 {
        backend_text(&m.text, "G");
    }
    if cc == 3 {
        backend_text(&m.text, "I");
    }
    if cc == 4 {
        backend_text(&m.text, "Q");
    }
    if cc == 5 {
        backend_text(&m.text, "E");
    }
}

fn foreign_ms_parameters(m: ForeignName*, function: ForeignType*): void {
    var saved: vector(u8*);
    copy(&saved, &m.substitutions, sizeof(vector(u8*)));
    vector_init(&m.substitutions);
    if function.args.length == 0 {
        if !function.variadic {
            backend_text(&m.text, "X");
        }
    }
    foreach(var type in &function.args) {
        var key: vector(u8);
        vector_init(&key);
        foreign_key(&key, type);
        var j: usize = 0;
        var found = false;
        for(; j != m.substitutions.length; j++) {
            if backend_equal(key.data, m.substitutions.data[j]) {
                foreign_number(&m.text, j, 10);
                found = true;
                break;
            }
        }
        if !found {
            var start = m.text.length;
            foreign_ms_type(m, type, false);
            var length = m.text.length -start;
            if length > 1 {
                if m.substitutions.length < 10 {
                    foreign_require(m, vector_push(&m.substitutions, foreign_copy(m, key.data, key.length)));
                }
            }
        }
        vector_dispose(&key);
    }
    if function.variadic {
        backend_text(&m.text, "Z");
    }
    else {
        if function.args.length != 0 {
            backend_text(&m.text, "@");
        }
    }
    vector_dispose(&m.substitutions);
    copy(&m.substitutions, &saved, sizeof(vector(u8*)));
}

fn foreign_ms_type(m: ForeignName*, type: ForeignType*, result: bool): void {
    if type.kind == 6 {
        foreign_ms_array(m, type);
        return;
    }
    if type.kind == 8 {
        foreign_ms_member(m, type);
        return;
    }
    if type.kind == 1 {
        var code = foreign_ms_builtin(type);
        if code[0] == 0 {
            foreign_fail(m, "Unsupported Microsoft builtin type");
        }
        backend_text(&m.text, code);
        return;
    }
    if type.kind == 2 {
        if result {
            backend_text(&m.text, "?");
            foreign_ms_cv(m, type.cv);
        }
        if type.tag == 0 {
            foreign_fail(m, "Microsoft named types require struct/class/union/enum metadata");
            return;
        }
        if type.tag == 1 {
            backend_text(&m.text, "U");
        }
        if type.tag == 2 {
            backend_text(&m.text, "V");
        }
        if type.tag == 3 {
            backend_text(&m.text, "T");
        }
        if type.tag == 4 {
            backend_text(&m.text, "W4");
        }
        foreign_ms_name(m, type);
        return;
    }
    if type.kind == 3 {
        var byte = type.cv &3;
        byte = byte + 80;
        var value = convert(u8, byte);
        backend_text_append(&m.text, &value, 1);
    } else {
        if type.kind == 4 {
            backend_text(&m.text, "A");
        }
        else {
            if type.kind == 5 {
                backend_text(&m.text, "$$Q");
            }
            else {
                if type.kind == 7 {
                    backend_text(&m.text, "$$A6");
                    foreign_ms_cc(m, type.convention, false);
                    foreign_ms_type(m, type.base, true);
                    foreign_ms_parameters(m, type);
                    if type.nothrow {
                        backend_text(&m.text, "_E");
                    }
                    else {
                        backend_text(&m.text, "Z");
                    }
                    return;
                } else {
                    foreign_fail(m, "Unsupported Microsoft foreign declarator");
                    return;
                }
            }
        }
    }
    if type.base.kind == 7 {
        backend_text(&m.text, "6");
        foreign_ms_cc(m, type.base.convention, false);
        foreign_ms_type(m, type.base.base, true);
        foreign_ms_parameters(m, type.base);
        if type.base.nothrow {
            backend_text(&m.text, "_E");
        }
        else {
            backend_text(&m.text, "Z");
        }
    } else {
        if m.pointer_bytes == 8 {
            backend_text(&m.text, "E");
        }
        var restricted = type.cv &4;
        if restricted != 0 {
            backend_text(&m.text, "I");
        }
        foreign_ms_cv(m, type.base.cv);
        foreign_ms_type(m, type.base, false);
    }
}

fn foreign_microsoft(m: ForeignName*): void {
    backend_text(&m.text, "?");
    if m.special != 0 {
        if m.special <= 2 {
            backend_text(&m.text, "?0");
        }
        else {
            if m.special == 4 {
                foreign_fail(m, "Microsoft complete destructor requires virtual-base metadata; use dtor(base)");
                return;
            }
            if m.special == 6 {
                backend_text(&m.text, "?_G");
            }
            else {
                backend_text(&m.text, "?1");
            }
        }
        foreign_ms_name(m, m.name.scope);
    } else {
        foreign_ms_name(m, m.name);
    }
    if m.object_symbol {
        if m.profile == foreign_windows_arm64ec {
            backend_text(&m.text, "$$h");
        }
    }
    var instance = m.member == 1;
    if m.member == 3 {
        instance = true;
    }
    if m.member == 0 {
        backend_text(&m.text, "Y");
    }
    else {
        var code = m.access *8;
        code = code + 65;
        if m.member == 2 {
            code = code + 2;
        }
        if m.member == 3 {
            code = code + 4;
        }
        var byte = convert(u8, code);
        backend_text_append(&m.text, &byte, 1);
    }
    if instance {
        if m.pointer_bytes == 8 {
            backend_text(&m.text, "E");
        }
        if m.function.ref == 1 {
            backend_text(&m.text, "G");
        }
        if m.function.ref == 2 {
            backend_text(&m.text, "H");
        }
        foreign_ms_cv(m, m.function.cv);
    }
    foreign_ms_cc(m, m.function.convention, instance);
    if m.special == 6 {
        if m.pointer_bytes == 8 {
            backend_text(&m.text, "PEAXI@Z");
        }
        else {
            backend_text(&m.text, "PAXI@Z");
        }
        return;
    }
    if m.special != 0 {
        backend_text(&m.text, "@");
    }
    else {
        foreign_ms_type(m, m.function.base, true);
    }
    foreign_ms_parameters(m, m.function);
    backend_text(&m.text, "Z");
}

