fn foreign_operator(m: ForeignName*, part: ForeignType*): void {
    var text: vector(u8);
    vector_init(&text);
    var first = foreign_peek(m);
    m.at++;
    backend_text(&text, first);
    if backend_equal(first, "(") {
        foreign_expect(m, ")");
        backend_text(&text, ")");
    }
    else {
        if backend_equal(first, "[") {
            foreign_expect(m, "]");
            backend_text(&text, "]");
        }
        else {
            var allocate = backend_equal(first, "new");
            if backend_equal(first, "delete") {
                allocate = true;
            }
            if allocate {
                if foreign_take(m, "[") {
                    foreign_expect(m, "]");
                    backend_text(&text, "[]");
                }
            } else {
                var second = foreign_peek(m);
                var more = backend_equal(second, "=");
                if backend_equal(first, second) {
                    if backend_equal(first, "+") {
                        more = true;
                    }
                    if backend_equal(first, "-") {
                        more = true;
                    }
                    if backend_equal(first, "<") {
                        more = true;
                    }
                    if backend_equal(first, ">") {
                        more = true;
                    }
                    if backend_equal(first, "|") {
                        more = true;
                    }
                }
                if backend_equal(first, "-") {
                    if backend_equal(second, ">") {
                        more = true;
                    }
                }
                if more {
                    backend_text(&text, second);
                    m.at++;
                }
                if backend_equal(text.data, "<<") {
                    if foreign_take(m, "=") {
                        backend_text(&text, "=");
                    }
                }
                if backend_equal(text.data, ">>") {
                    if foreign_take(m, "=") {
                        backend_text(&text, "=");
                    }
                }
                if backend_equal(text.data, "<=") {
                    if foreign_take(m, ">") {
                        backend_text(&text, ">");
                    }
                }
                if backend_equal(text.data, "->") {
                    if foreign_take(m, "*") {
                        backend_text(&text, "*");
                    }
                }
            }
        }
    }
    part.name = foreign_copy(m, text.data, text.length);
    part.operator_name = true;
    vector_dispose(&text);
}

