fn bi_initializer(c: BackendImport*, address: void*, initializer: void*, type: void*): void {
    var kind = LLVMGetTypeKind(type);
    var aggregate = kind == 10;
    var array = kind == 11;
    if array {
        aggregate = true;
    }
    if aggregate {
        var count: u64 = 0;
        if array {
            count = LLVMGetArrayLength2(type);
        }
        else {
            count = convert(u64, LLVMCountStructElementTypes(type));
        }
        for(var i: u64 = 0; i != count; i++) {
            var element: void* = null;
            var offset: u64 = 0;
            if array {
                element = LLVMGetElementType(type);
                offset = LLVMABISizeOfType(c.backend.layout, element) * i;
            } else {
                element = LLVMStructGetTypeAtIndex(type, convert(u32, i));
                offset = LLVMOffsetOfElement(c.backend.layout, type, convert(u32, i));
            }
            var child = LLVMGetAggregateElement(initializer, convert(u32, i));
            var pointer = bi_offset(c, address, bi_const(c, 8, offset));
            bi_initializer(c, pointer, child, element);
        }
        return;
    }
    bi_memory_store(c, address, bi_value(c, initializer), type);
}

fn bi_function(c: BackendImport*, function: void*): void {
    c.function = backend_find(&c.values, function);
    var n = sem_get(c.function);
    c.block = n.body;
    c.declarations = bi_node(c, 12, 3);
    c.blocks.length = 0;
    c.literals.length = 0;
    var block = LLVMGetFirstBasicBlock(function);
    loop {
        var done = block == null;
        if done {
            break;
        }
        var label = bi_node(c, 31, 3);
        bi_name(c, label, "block");
        backend_require(c.backend, backend_associate(&c.blocks, block, label));
        var instruction = LLVMGetFirstInstruction(block);
        loop {
            done = instruction == null;
            if done {
                break;
            }
            var type = LLVMTypeOf(instruction);
            var valued = LLVMGetTypeKind(type) != 0;
            if valued {
                var local = bi_decl(c, bi_scalar(c, type));
                backend_require(c.backend, backend_associate(&c.values, instruction, local));
            }
            instruction = LLVMGetNextInstruction(instruction);
        }
        block = LLVMGetNextBasicBlock(block);
    }
    block = LLVMGetFirstBasicBlock(function);
    loop {
        var done = block == null;
        if done {
            break;
        }
        bi_append(c, c.block, backend_find(&c.blocks, block));
        var instruction = LLVMGetFirstInstruction(block);
        loop {
            done = instruction == null;
            if done {
                break;
            }
            if c.backend.error.length != 0 {
                return;
            }
            var locals = sem_get(c.declarations);
            var first_local = locals.items.length;
            var result = bi_instruction(c, instruction, block);
            var valued = result != null;
            if valued {
                var destination = backend_find(&c.values, instruction);
                bi_result(c, destination, result, first_local);
            }
            instruction = LLVMGetNextInstruction(instruction);
        }
        block = LLVMGetNextBasicBlock(block);
    }
    var declarations = sem_get(c.declarations);
    var body = sem_get(n.body);
    foreach(var & item in &body.items) {
        backend_require(c.backend, vector_push(&declarations.items, *item));
    }
    n.body = c.declarations;
}

export fn backend_import_foundation(b: Backend*, root: void*): bool {
    var c: BackendImport = { backend: b, root: root, block: root, declarations: root, ..default };
    var program = sem_attach(root, 0);
    semantic_collect_comments(b.source_root, root);
    program.type.scalar = 3;
    program.type.pointer_bytes = b.pointer_bytes;
    var original_root = sem_get(b.source_root);
    foreach(var entity in &original_root.items) {
        var n = sem_get(entity);
        if n.kind == 19 {
            bi_append(&c, root, entity);
        }
    }
    var function = LLVMGetFirstFunction(b.module);
    loop {
        var done = function == null;
        if done {
            break;
        }
        var length: usize = 0;
        var name = LLVMGetValueName2(function, &length);
        var builtin = backend_prefix(name, "llvm.");
        var runtime = backend_reserved(name);
        if backend_equal(name, "tower_main") {
            runtime = false;
        }
        if runtime {
            builtin = true;
        }
        if !builtin {
            var type = LLVMGetReturnType(LLVMGlobalGetValueType(function));
            var entity = bi_node(&c, 1, bi_scalar(&c, type));
            var n = sem_get(entity);
            n.external = LLVMIsDeclaration(function) != 0;
            bi_name(&c, entity, "function");
            var signature: FoundationNode* = null;
            var i: usize = 0;
            loop {
                done = i == b.symbols.length;
                if done {
                    break;
                }
                if backend_equal(name, b.symbols.data[i]) {
                    var original = sem_get(b.source_functions.data[i]);
                    var public = original.external;
                    if original.exported {
                        public = true;
                    }
                    if public {
                        signature = original;
                        copy(&n.type, &original.type, sizeof(FoundationType));
                    }
                    if original.name.length != 0 {
                        n.name.length = 0;
                        backend_text(&n.name, backend_name(original));
                        n.exported = original.exported;
                    }
                    break;
                }
                i++;
            }
            n.body = bi_node(&c, 12, 3);
            var count = LLVMCountParams(function);
            var parameter: u32 = 0;
            loop {
                done = parameter == count;
                if done {
                    break;
                }
                var value = LLVMGetParam(function, parameter);
                var p = bi_node(&c, 2, bi_scalar(&c, LLVMTypeOf(value)));
                var public = signature != null;
                if public {
                    var original_parameter = sem_get(signature.parameters.data[convert(usize, parameter)]);
                    var parameter_node = sem_get(p);
                    copy(&parameter_node.type, &original_parameter.type, sizeof(FoundationType));
                }
                bi_name(&c, p, "argument");
                backend_require(b, vector_push(&n.parameters, p));
                backend_require(b, backend_associate(&c.values, value, p));
                parameter++;
            }
            bi_append(&c, root, entity);
            backend_require(b, backend_associate(&c.values, function, entity));
        }
        function = LLVMGetNextFunction(function);
    }
    var global = LLVMGetFirstGlobal(b.module);
    loop {
        var done = global == null;
        if done {
            break;
        }
        var type = LLVMGlobalGetValueType(global);
        var storage = bi_storage(&c, LLVMABISizeOfType(b.layout, type), LLVMABIAlignmentOfType(b.layout, type), true);
        var node = sem_get(storage);
        node.global = true;
        backend_require(b, backend_associate(&c.values, global, storage));
        global = LLVMGetNextGlobal(global);
    }
    // Initialization temporaries belong to a short-lived function frame. Keeping
    // each generated byte-store temporary at module scope inflates global memory
    // and can exceed the frontend's top-level declaration budget in debug mode.
    var startup = bi_node(&c, 1, 3);
    bi_name(&c, startup, "initialize");
    var startup_node = sem_get(startup);
    startup_node.body = bi_node(&c, 12, 3);
    bi_append(&c, root, startup);
    c.block = startup_node.body;
    c.declarations = c.block;
    global = LLVMGetFirstGlobal(b.module);
    loop {
        var done = global == null;
        if done {
            break;
        }
        var initializer = LLVMGetInitializer(global);
        if initializer == null {
            backend_fail(b, "Unresolved LLVM global in foundation return path");
        }
        else {
            bi_initializer(&c, bi_value(&c, global), initializer, LLVMGlobalGetValueType(global));
        }
        global = LLVMGetNextGlobal(global);
    }
    var entry = backend_find(&c.values, LLVMGetNamedFunction(b.module, "tower_main"));
    var call = bi_node(&c, 11, 3);
    var invocation = sem_get(call);
    invocation.binding = entry;
    bi_append(&c, c.block, call);
    bi_append(&c, c.block, bi_node(&c, 18, 3));
    var start_call = bi_node(&c, 11, 3);
    var start_invocation = sem_get(start_call);
    start_invocation.binding = startup;
    bi_append(&c, root, start_call);
    function = LLVMGetFirstFunction(b.module);
    loop {
        var done = function == null;
        if done {
            break;
        }
        if LLVMIsDeclaration(function) == 0 {
            bi_function(&c, function);
        }
        function = LLVMGetNextFunction(function);
    }
    vector_dispose(&c.values);
    vector_dispose(&c.literals);
    vector_dispose(&c.blocks);
    var valid = b.error.length == 0;
    return valid;
}

export fn backend_optimize_interpreter(b: Backend*, optimize: bool): bool {
    if optimize {
        // LLVM 19/20's default<O2> parser resets vectorizer tuning options.
        // This scalar reconstruction profile also forbids implicit SIMD on each
        // function. Ordinary target emission retains its vectorizing pipeline.
        var kind = LLVMGetEnumAttributeKindForName("noimplicitfloat", 15);
        var attribute = LLVMCreateEnumAttribute(b.context, kind, 0);
        var function = LLVMGetFirstFunction(b.module);
        while function != null {
            LLVMAddAttributeAtIndex(function, BackendFunctionAttributeIndex, attribute);
            function = LLVMGetNextFunction(function);
        }
        var options = LLVMCreatePassBuilderOptions();
        LLVMPassBuilderOptionsSetVerifyEach(options, BackendVerifyEach);
        LLVMPassBuilderOptionsSetLoopVectorization(options, 0);
        LLVMPassBuilderOptionsSetSLPVectorization(options, 0);
        // A scalar portable profile. These are upstream passes, not Tower
        // peepholes. lower-switch makes target-independent CFG import explicit.
        var error = LLVMRunPasses(b.module, "function(sroa,mem2reg),default<O2>,function(lower-switch)", null, options);
        LLVMDisposePassBuilderOptions(options);
        if error != null {
            var message = LLVMGetErrorMessage(error);
            backend_fail(b, message);
            LLVMDisposeErrorMessage(message);
            return false;
        }
    }
    return backend_optimize(b, false);
}

import tower;
import bindings;
import context;
import import_bindings;
import import_foundation;
import .compiler.foundation_tags;
import .library.float_bits;

var LLVMConstantFloatValueKind: u32 = 19;

fn bi_pow2(width: u32): u64 {
    var result: u64 = 1;
    var i: u32 = 0;
    loop {
        if i == width {
            return result;
        }
        result = result * 2;
        i++;
    }
}

fn bi_narrow_memory(type: void*): bool {
    if LLVMGetTypeKind(type) == 8 {
        var width = LLVMGetIntTypeWidth(type);
        var direct = width == IntegerByteWidth || width == IntegerShortWidth;
        if direct {
            return false;
        }
        direct = width == 32;
        if direct {
            return false;
        }
        direct = width == 64;
        if direct {
            return false;
        }
        return true;
    }
    return false;
}

fn bi_memory_load(c: BackendImport*, address: void*, type: void*): void* {
    if bi_narrow_memory(type) {
        var width = LLVMGetIntTypeWidth(type);
        var count = width + 7;
        count = count / 8;
        var result = bi_const(c, 7, 0);
        for(var i: u32 = 0; i != count; i++) {
            var at = bi_offset(c, address, bi_const(c, 8, convert(u64, i)));
            var byte = bi_cast(c, bi_load(c, at, 5), 7, false);
            var shift = i *8;
            byte = bi_binary(c, 2, byte, bi_const(c, 7, bi_pow2(shift)), 7);
            result = bi_binary(c, 6, result, byte, 7);
        }
        return bi_mask(c, result, type);
    }
    return bi_load(c, address, bi_scalar(c, type));
}

fn bi_memory_store(c: BackendImport*, address: void*, value: void*, type: void*): void {
    if bi_narrow_memory(type) {
        var width = LLVMGetIntTypeWidth(type);
        var count = width + 7;
        count = count / 8;
        value = bi_cast(c, value, 7, false);
        var i: u32 = 0;
        loop {
            if i == count {
                return;
            }
            var byte = bi_binary(c, 5, value, bi_const(c, 7, 255), 7);
            byte = bi_cast(c, byte, 5, false);
            var at = bi_offset(c, address, bi_const(c, 8, convert(u64, i)));
            bi_store(c, at, byte);
            value = bi_binary(c, 3, value, bi_const(c, 7, 256), 7);
            i++;
        }
    }
    bi_store(c, address, value);
}

fn bi_mask(c: BackendImport*, value: void*, type: void*): void* {
    if LLVMGetTypeKind(type) == 8 {
        var width = LLVMGetIntTypeWidth(type);
        var scalar = bi_scalar(c, type);
        if width == 1 {
            value = bi_cast(c, value, 7, false);
            value = bi_binary(c, 5, value, bi_const(c, 7, 1), 7);
        }
        value = bi_cast(c, value, scalar, false);
        var ordinary = width == 1;
        if ordinary {
            return value;
        }
        ordinary = width == IntegerByteWidth || width == IntegerShortWidth;
        if ordinary {
            return value;
        }
        ordinary = width == 32;
        if ordinary {
            return value;
        }
        ordinary = width == 64;
        if ordinary {
            return value;
        }
        var mask = bi_pow2(width) -1;
        return bi_binary(c, 5, value, bi_const(c, scalar, mask), scalar);
    }
    return value;
}

fn bi_signed(c: BackendImport*, value: void*, type: void*): void* {
    var width = LLVMGetIntTypeWidth(type);
    value = bi_cast(c, value, 7, false);
    if !(width == 64) {
        var sign_width = width -1;
        var sign = bi_const(c, 7, bi_pow2(sign_width));
        value = bi_binary(c, 7, value, sign, 7);
        value = bi_binary(c, 1, value, sign, 7);
    }
    return bi_cast(c, value, 6, true);
}

fn bi_gep(c: BackendImport*, instruction: void*): void* {
    var value = bi_value(c, LLVMGetOperand(instruction, 0));
    var type = LLVMGetGEPSourceElementType(instruction);
    var count = LLVMGetNumOperands(instruction);
    var i: i32 = 1;
    loop {
        if i == count {
            return value;
        }
        var index = LLVMGetOperand(instruction, convert(u32, i));
        var bytes: void* = null;
        var first = i == 1;
        var record = LLVMGetTypeKind(type) == 10;
        if first {
            record = false;
        }
        if record {
            var field = convert(u32, LLVMConstIntGetZExtValue(index));
            bytes = bi_const(c, 8, LLVMOffsetOfElement(c.backend.layout, type, field));
            type = LLVMStructGetTypeAtIndex(type, field);
        } else {
            if !first {
                type = LLVMGetElementType(type);
            }
            var stride = LLVMABISizeOfType(c.backend.layout, type);
            var index_width = LLVMGetIntTypeWidth(LLVMTypeOf(index));
            var pointer_width = c.backend.pointer_bytes *8;
            var wider_pointer = pointer_width > index_width;
            bytes = bi_value(c, index);
            if wider_pointer {
                bytes = bi_signed(c, bytes, LLVMTypeOf(index));
                bytes = bi_cast(c, bytes, 7, true);
            }
            bytes = bi_cast(c, bytes, 8, false);
            bytes = bi_binary(c, 2, bytes, bi_const(c, 8, stride), 8);
        }
        value = bi_offset(c, value, bytes);
        i++;
    }
}

fn bi_value(c: BackendImport*, value: void*): void* {
    var entity = backend_find(&c.values, value);
    if entity != null {
        var n = sem_get(entity);
        if n.kind == KFunction {
            var reference = bi_node(c, KFunctionReference, SFunction);
            var result = sem_get(reference);
            result.binding = entity;
            result.type = *bi_function_type(c, &n.type, &n.parameters);
            return bi_cast(c, reference, BackendImportPointer, true);
        }
        if n.global {
            return bi_address(c, bi_ref(c, entity));
        }
        return bi_cast(c, bi_ref(c, entity), bi_scalar(c, LLVMTypeOf(value)), true);
    }
    var type = LLVMTypeOf(value);
    var scalar = bi_scalar(c, type);
    var kind = LLVMGetValueKind(value);
    if kind == LLVMConstantFloatValueKind {
        var width = scalar == SF32 ? Float32Width : Float64Width;
        var raw = LLVMConstBitCast(value, LLVMIntTypeInContext(c.backend.context, width));
        return bi_literal(c, value, scalar, LLVMConstIntGetZExtValue(raw));
    }
    var zero = LLVMIsNull(value) != 0;
    if LLVMIsUndef(value) != 0 {
        zero = true;
    }
    if LLVMIsPoison(value) != 0 {
        zero = true;
    }
    if zero {
        return bi_literal(c, value, scalar, 0);
    }
    var integer = kind == 18;
    if integer {
        return bi_literal(c, value, scalar, LLVMConstIntGetZExtValue(value));
    }
    if kind == 10 {
        var op = LLVMGetConstOpcode(value);
        if op == 29 {
            return bi_gep(c, value);
        }
        var cast = op == 39;
        var other = op == 40;
        if other {
            cast = true;
        }
        other = op == 41;
        if other {
            cast = true;
        }
        if cast {
            var operand = bi_value(c, LLVMGetOperand(value, 0));
            if scalar == BackendImportPointer {
                var input = sem_get(operand);
                var integer = input.type.pointers == 0;
                if integer {
                    operand = bi_cast(c, operand, 8, false);
                }
                return bi_cast(c, operand, scalar, true);
            }
            operand = bi_cast(c, operand, 8, true);
            return bi_cast(c, operand, scalar, false);
        }
    }
    backend_fail(c.backend, "Unsupported LLVM value in foundation return path");
    return bi_const(c, scalar, 0);
}

fn bi_select(c: BackendImport*, condition: void*, yes: void*, no: void*, scalar: u32): void* {
    var result = bi_decl(c, scalar);
    var outer = c.block;
    var entity = bi_if(c, condition);
    var branch = sem_get(entity);
    c.block = branch.body;
    bi_assign(c, bi_ref(c, result), yes);
    c.block = branch.otherwise;
    bi_assign(c, bi_ref(c, result), no);
    c.block = outer;
    return bi_ref(c, result);
}

fn bi_compare(c: BackendImport*, predicate: u32, a: void*, b: void*, type: void*): void* {
    var op: u32 = 8;
    if predicate >= 38 {
        if LLVMGetIntTypeWidth(type) == 32 {
            a = bi_cast(c, a, 0, true);
            b = bi_cast(c, b, 0, true);
        } else {
            a = bi_signed(c, a, type);
            b = bi_signed(c, b, type);
        }
        predicate = predicate - 4;
    }
    var selected = predicate == 33;
    if selected {
        op = 9;
    }
    selected = predicate == 34;
    if selected {
        op = 12;
    }
    selected = predicate == 35;
    if selected {
        op = 13;
    }
    selected = predicate == 36;
    if selected {
        op = 10;
    }
    selected = predicate == 37;
    if selected {
        op = 11;
    }
    return bi_binary(c, op, a, b, 2);
}

fn bi_shift(c: BackendImport*, op: u32, a: void*, b: void*, type: void*, shift: void*): void* {
    // Totalized LLVM shifts: out-of-range poison may choose any value. Never
    // introduce a trap into speculative, subsequently unused LLVM operations.
    var width = LLVMGetIntTypeWidth(type);
    if LLVMGetValueKind(shift) == 18 {
        // Immediate shift legalization needs a constant scale, not a runtime
        // exponentiation loop. This translates an opcode; LLVM owns folding.
        var count = LLVMConstIntGetZExtValue(shift);
        var scalar = bi_scalar(c, type);
        if count >= convert(u64, width) {
            return bi_const(c, scalar, 0);
        }
        var factor = bi_const(c, scalar, bi_pow2(convert(u32, count)));
        var left = op == 20;
        if left {
            return bi_mask(c, bi_binary(c, 2, a, factor, scalar), type);
        }
        if op == 21 {
            return bi_binary(c, 3, a, factor, scalar);
        }
        var sign_width = width -1;
        var negative = bi_binary(c, 13, a, bi_const(c, scalar, bi_pow2(sign_width)), 2);
        var mask_bits = bi_pow2(width) -1;
        var mask = bi_const(c, scalar, mask_bits);
        var inverted = bi_binary(c, 7, a, mask, scalar);
        inverted = bi_binary(c, 3, inverted, factor, scalar);
        inverted = bi_binary(c, 7, inverted, mask, scalar);
        var positive = bi_binary(c, 3, a, factor, scalar);
        return bi_select(c, negative, inverted, positive, scalar);
    }
    a = bi_cast(c, a, 7, false);
    b = bi_cast(c, b, 7, false);
    b = bi_binary(c, 5, b, bi_const(c, 7, 63), 7);
    var power = bi_decl(c, 7);
    bi_assign(c, bi_ref(c, power), bi_const(c, 7, 1));
    for(var i: u32 = 0; i != 6; i++) {
        var bit = bi_pow2(i);
        var test = bi_binary(c, 5, b, bi_const(c, 7, bit), 7);
        test = bi_binary(c, 9, test, bi_const(c, 7, 0), 2);
        var outer = c.block;
        var branch = sem_get(bi_if(c, test));
        c.block = branch.body;
        var factor = bi_const(c, 7, bi_pow2(convert(u32, bit)));
        var product = bi_binary(c, 2, bi_ref(c, power), factor, 7);
        bi_assign(c, bi_ref(c, power), product);
        c.block = outer;
    }
    var left = op == 20;
    if left {
        return bi_mask(c, bi_binary(c, 2, a, bi_ref(c, power), 7), type);
    }
    if op == 22 {
        var sign_width = width -1;
        var sign = bi_pow2(sign_width);
        var negative = bi_binary(c, 13, a, bi_const(c, 7, sign), 2);
        var mask = bi_pow2(width) -1;
        var inverted = bi_binary(c, 7, a, bi_const(c, 7, mask), 7);
        inverted = bi_binary(c, 3, inverted, bi_ref(c, power), 7);
        inverted = bi_binary(c, 7, inverted, bi_const(c, 7, mask), 7);
        var positive = bi_binary(c, 3, a, bi_ref(c, power), 7);
        return bi_mask(c, bi_select(c, negative, inverted, positive, 7), type);
    }
    return bi_mask(c, bi_binary(c, 3, a, bi_ref(c, power), 7), type);
}

import tower;
import .library.vector;

// Owned inputs/results shared by the native, WASI and in-memory link services.
// Argument strings and input names are NUL terminated; byte lengths exclude it.
struct BackendLinkInput { name: vector(u8); bytes: vector(u8); }
struct BackendLink {
    arguments: vector(u8*);
    inputs: vector(BackendLinkInput);
    error: vector(u8);
    output: vector(u8);
}

import tower;
import link_types;
import coff_import;
import context;
import file_api;
import foreign_api;
import foreign_reader;
import foreign_symbol;
import text;
