// Darwin x86_64/arm64: dispatch_once_t is intptr_t, initially zero.
// Call the synchronization primitive even after initialization has completed.
extern fn dispatch_once_f(control: i64*, context: void*, initialize: void*): void;
extern fn dlsym(handle: void*, name: u8*): void*;

export fn backend_targets_once_entry(context: void*): void { backend_register_targets(); }

export fn backend_initialize_targets(): void {
    var initialize = dlsym(bits(void*, ~convert(usize, 1)), "backend_targets_once_entry");
    if initialize == null { trap("Cannot resolve LLVM target initializer", 0); }
    dispatch_once_f(bits(i64*, backend_registry_control()), null, initialize);
}

import tower;

// The runtime binder supplies this platform object with a zero-initialized
// word. No ordinary Tower module initializer or undefined storage is substituted.
extern fn backend_registry_control(): usize*;

import tower;
import target_api;

// A backend reactor has one execution owner. Parallel browser jobs use separate
// instances/memories; this instance-local guard is not a shared-memory lock.
export fn backend_initialize_targets(): void {
    var ready = backend_registry_control();
    if *ready == 0 {
        backend_register_targets();
        *ready = 1;
    }
}

import tower;
import target_api;

// Windows x64/arm64: INIT_ONCE is one pointer-sized opaque word, initially
// zero. The synchronous protocol admits one writer and publishes its results.
extern fn InitOnceBeginInitialize(control: usize*, flags: u32, pending: i32*, context: void**): i32;
extern fn InitOnceComplete(control: usize*, flags: u32, context: void*): i32;

export fn backend_initialize_targets(): void {
    var pending: i32 = 0;
    var control = backend_registry_control();
    if InitOnceBeginInitialize(control, 0, &pending, null) == 0 {
        trap("Cannot initialize LLVM target registry", 0);
    }
    if pending != 0 {
        backend_register_targets();
        if InitOnceComplete(control, 0, null) == 0 {
            trap("Cannot publish LLVM target registry", 0);
        }
    }
}

