}

fn wasm_write_name(output: ByteBuffer*, name: WasmBytes): bool {
    return wasm_write_uleb(output, convert(u64, name.length)) && bytes_append(output, name.data, name.length);
}

fn wasm_read_message(error: WasmReadError): u8* {
    match error {
        WasmReadError.None => { return "success"; }
        WasmReadError.Truncated => { return "truncated Wasm input"; }
        WasmReadError.Integer => { return "invalid Wasm integer encoding"; }
        WasmReadError.Encoding => { return "invalid Wasm object encoding"; }
        WasmReadError.Utf8 => { return "invalid UTF-8 Wasm name"; }
        WasmReadError.Unsupported => { return "unsupported Wasm object feature"; }
        WasmReadError.Allocation => { return "Wasm linker allocation failed"; }
        WasmReadError.Index => { return "Wasm object index out of range"; }
        WasmReadError.Duplicate => { return "duplicate Wasm object metadata"; }
        _ => { return "unknown Wasm input error"; }
    }
}

import tower;
import wasm_link_types;
import wasm_link_prepare;
import wasm_link_symbols;
import wasm_link_synthetic;
import wasm_link_live;
import wasm_link_layout;
import wasm_link_emit;
import wasm_link_archives;
import wasm_bytes;

// Transport-independent static Wasm image construction. The request owns a
// world and borrows pinned object/archive bytes until close. No filesystem,
// process launching, native linker, CLI or browser objects enter this API.
fn wasm_link_run(link: WasmLink*): bool {
    if link.started || link.layout_type != null {
        link.output.length = 0;
        return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("link requests are single use"));
    }
    link.started = true;
    if link.workers == 0 || link.workers > WasmLinkMaximumWorkers || link.job_grain == 0 {
        return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("invalid linker worker budget"));
    }
    return wasm_link_extract_archives(link) && wasm_link_prepare(link) && wasm_link_symbols(link) && wasm_link_synthetics(link)
        && wasm_link_apply_wraps(link) && wasm_link_variants(link) && wasm_link_liveness(link)
        && wasm_link_layout(link) && wasm_link_emit(link);
}

import tower;
import wasm_bytes;
import wasm_names;
import wasm_object;
import wasm_object_types;
import wasm_archive;
import wasm_link_world;
import wasm_link_types;
import wasm_link_synthetic;
import wasm_link_prepare;
import wasm_link_symbols;
import .library.vector;

struct WasmArchiveCandidate { archive: u32; member: usize; next: u32; tail: u32; }
struct WasmArchiveSelection {
    definitions: WasmNameMap;
    demands: WasmNameMap;
    names: WasmNameMap;
    comdats: WasmNameMap;
    candidates: vector(WasmArchiveCandidate);
    pending: vector(WasmBytes);
    order: vector(u32);
}

fn wasm_archive_selection_close(selection: WasmArchiveSelection*): void {
    wasm_names_dispose(&selection.definitions); wasm_names_dispose(&selection.demands); wasm_names_dispose(&selection.names);
    wasm_names_dispose(&selection.comdats);
    vector_dispose(&selection.candidates); vector_dispose(&selection.pending); vector_dispose(&selection.order);
}

fn wasm_archive_reference_name(link: WasmLink*, name: WasmBytes): WasmBytes {
    foreach (var & wrap in &link.wraps) {
        if wasm_bytes_equal(name, wrap.name) { return wrap.wrapper; }
        if wasm_bytes_equal(name, wrap.real) { return wrap.name; }
    }
    return name;
}

fn wasm_archive_schedule(link: WasmLink*, selection: WasmArchiveSelection*, name: WasmBytes): bool {
    var index = wasm_names_get(&selection.names, name);
    var candidate: WasmArchiveCandidate = default;
    var payload: WasmArchivePayload* = null;
    loop {
        if index == WasmNoIndex { return true; }
        candidate = selection.candidates.data[convert(usize, index)];
        payload = link.world.archives.data[convert(usize, candidate.archive)].payload;
        if !payload.selected.data[candidate.member] { break; }
        index = candidate.next;
    }
    payload.selected.data[candidate.member] = true;
    var member = &payload.archive.members.data[candidate.member];
    var object_index = convert(u32, link.world.objects.length);
    var object = wasm_link_prepare_object_mode(&link.world, member.name, member.bytes, false);
    if object == null { return wasm_link_fail(link, WasmLinkError.Allocation, member.name); }
    if !wasm_object_read(object, member.bytes) {
        link.world.error = object.error; link.world.error_input = member.name; link.world.error_offset = object.error_offset;
        return wasm_link_fail(link, WasmLinkError.Input, member.name);
    }
    return wasm_archive_index_object(link, selection, object_index);
}

fn wasm_archive_demand(link: WasmLink*, selection: WasmArchiveSelection*, name: WasmBytes): bool {
    // Satisfied references cannot trigger a future extraction. Avoid retaining
    // their often long C++ names in the unresolved-demand index.
    if wasm_names_get(&selection.definitions, name) != WasmNoIndex || wasm_link_synthetic_kind(link, name) != WasmSynthetic.None { return true; }
    if !wasm_names_set(&selection.demands, name, 0) { return wasm_link_fail(link, WasmLinkError.Allocation, name); }
    return wasm_archive_schedule(link, selection, name);
}

fn wasm_archive_index_object(link: WasmLink*, selection: WasmArchiveSelection*, index: u32): bool {
    var object = link.world.objects.data[convert(usize, index)].object;
    if !wasm_link_push(link, &selection.order, index) { return false; }
    // Reuse final-link COMDAT selection. This scratch is discarded before any
    // member is fetched; the object's authoritative records remain unchanged.
    var layout: WasmObjectLayout = default;
    defer wasm_link_object_layout_dispose(&layout);
    if object.comdats.length != 0 {
        if !wasm_link_chunks(link, &layout.functions, object.functions.length) || !wasm_link_chunks(link, &layout.globals, object.globals.length)
            || !wasm_link_chunks(link, &layout.data, object.data.length) || !wasm_link_chunks(link, &layout.tables, object.tables.length)
            || !wasm_link_chunks(link, &layout.tags, object.tags.length)
            || !wasm_link_object_comdats(link, object, &layout, &selection.comdats, index) { return false; }
    }
    // Publish every definition before considering this object's references.
    foreach (var & symbol in &object.symbols) {
        var excluded = convert(u32, WasmSymbolFlag.Local) | convert(u32, WasmSymbolFlag.Undefined);
        if symbol.kind == convert(u8, WasmSymbolKind.Section) || (symbol.flags & excluded) != 0 { continue; }
        if object.comdats.length != 0 {
            var chunk = wasm_link_defined_chunk(&layout, symbol);
            if chunk != null && chunk.discarded { continue; }
        }
        if !wasm_names_set(&selection.definitions, symbol.name, 0) { return wasm_link_fail(link, WasmLinkError.Allocation, symbol.name); }
    }
    // Stack in reverse source order, then drain depth first without recursive
    // host calls. A member's definitions can satisfy later pending demands.
    for (var row = object.symbols.length; row != 0;) {
        var symbol = &object.symbols.data[--row];
        if symbol.kind == convert(u8, WasmSymbolKind.Section) || (symbol.flags & convert(u32, WasmSymbolFlag.Local)) != 0 { continue; }
        var name = wasm_archive_reference_name(link, symbol.name);
        var wrapped = !wasm_bytes_equal(name, symbol.name);
        var undefined = (symbol.flags & convert(u32, WasmSymbolFlag.Undefined)) != 0;
        if !undefined && object.comdats.length != 0 {
            var chunk = wasm_link_defined_chunk(&layout, symbol);
            undefined = chunk != null && chunk.discarded;
        }
        var strong_undefined = undefined && (symbol.flags & convert(u32, WasmSymbolFlag.Weak)) == 0;
        if (wrapped || strong_undefined) && !wasm_link_push(link, &selection.pending, name) { return false; }
    }
    return true;
}

fn wasm_archive_index_library(link: WasmLink*, selection: WasmArchiveSelection*, index: u32): bool {
    var entry = &link.world.archives.data[convert(usize, index)];
    var archive = &entry.payload.archive;
    if !archive.indexed {
        foreach (var & member in &archive.members) {
            if !member.special { return wasm_link_fail(link, WasmLinkError.Unsupported, wasm_text_bytes("lazy archive requires a symbol index")); }
        }
    }
    foreach (var & symbol in &archive.symbols) {
        if wasm_names_get(&selection.definitions, symbol.name) != WasmNoIndex { continue; }
        var head = wasm_names_get(&selection.names, symbol.name);
        var row = convert(u32, selection.candidates.length);
        var candidate: WasmArchiveCandidate = { archive: index, member: symbol.member, next: WasmNoIndex, tail: row };
        if !wasm_link_push(link, &selection.candidates, candidate) { return false; }
        if head == WasmNoIndex {
            if !wasm_names_set(&selection.names, symbol.name, row) {
                return wasm_link_fail(link, WasmLinkError.Allocation, symbol.name);
            }
        } else {
            var first = &selection.candidates.data[convert(usize, head)];
            selection.candidates.data[convert(usize, first.tail)].next = row;
            first.tail = row;
        }
    }
    for (var row = archive.symbols.length; row != 0;) {
        var symbol = &archive.symbols.data[--row];
        if wasm_names_get(&selection.demands, symbol.name) != WasmNoIndex && !wasm_link_push(link, &selection.pending, symbol.name) { return false; }
    }
    return true;
}

fn wasm_archive_drain(link: WasmLink*, selection: WasmArchiveSelection*): bool {
    while selection.pending.length != 0 {
        var name = selection.pending.data[--selection.pending.length];
        if !wasm_archive_demand(link, selection, name) { return false; }
    }
    return true;
}

fn wasm_link_extract_archives(link: WasmLink*): bool {
    if link.world.archives.length == 0 { return true; }
    if !wasm_link_collect_errors(&link.world) { return wasm_link_fail(link, WasmLinkError.Input, link.world.error_input); }
    var selection: WasmArchiveSelection = default;
    defer wasm_archive_selection_close(&selection);
    foreach (var & input in &link.world.inputs) {
        var ok = input.kind == WasmInputKind.Object ? wasm_archive_index_object(link, &selection, input.index) : wasm_archive_index_library(link, &selection, input.index);
        if !ok || !wasm_archive_drain(link, &selection) { return false; }
    }
    // LLD applies requested exports after ordinary inputs. Both required and
    // optional exports extract a member if present; only the former must exist.
    foreach (var & request in &link.exports) {
        if !wasm_archive_demand(link, &selection, request.name) || !wasm_archive_drain(link, &selection) { return false; }
    }
    // Physical components stay stable. Only the derived publication order moves;
    // later weak/COMDAT selection sees the same order as lazy extraction.
    var ordered: vector(WasmObjectEntry) = default;
    if !vector_reserve(&ordered, selection.order.length) { return wasm_link_fail(link, WasmLinkError.Allocation, default(WasmBytes)); }
    foreach (var index in &selection.order) { ordered.data[ordered.length++] = link.world.objects.data[convert(usize, index)]; }
    vector_dispose(&link.world.objects); link.world.objects = ordered;
    return true;
}

import tower;
import wasm_bytes;
import wasm_object_types;
import wasm_link_types;
import wasm_link_relocate;
import wasm_link_memory;
import wasm_link_jobs;
import .library.bytes_interface;
import .library.bytes_types;

fn wasm_emit_section(output: ByteBuffer*, kind: WasmSection, section: ByteBuffer*): bool {
    if section.length == 0 { return true; }
    var ok = bytes_push(output, convert(u8, kind)) && wasm_write_uleb(output, convert(u64, section.length)) && bytes_append(output, section.data, section.length);
    section.length = 0;
    return ok;
}

fn wasm_emit_i32_expression(output: ByteBuffer*, value: u64): bool {
    return bytes_push(output, convert(u8, WasmOpcode.I32Const)) && wasm_write_sleb(output, convert(i64, bits(i32, convert(u32, value))))
        && bytes_push(output, convert(u8, WasmOpcode.End));
}

fn wasm_emit_memory_limits(link: WasmLink*, section: ByteBuffer*): bool {
    var flags: u64 = link.maximum_memory != 0 ? convert(u64, WasmLimitFlag.Maximum) : 0;
    if link.shared_memory { flags |= convert(u64, WasmLimitFlag.Shared); }
    return wasm_write_uleb(section, flags) && wasm_write_uleb(section, link.initial_memory / WasmPageBytes)
        && (link.maximum_memory == 0 || wasm_write_uleb(section, link.maximum_memory / WasmPageBytes));
}

fn wasm_emit_imports(link: WasmLink*, section: ByteBuffer*): bool {
    var count = convert(u64, link.imported_functions) + convert(u64, link.imported_globals);
    if link.import_memory { count++; }
    if count == 0 { return true; }
    if !wasm_write_uleb(section, count) { return false; }
    for (var at: usize = 0; at < convert(usize, link.imported_functions); at++) {
        var output = &link.functions.data[at];
        var function = &link.world.objects.data[convert(usize, output.object)].object.functions.data[convert(usize, output.function)];
        if !wasm_write_name(section, function.module) || !wasm_write_name(section, function.name)
            || !bytes_push(section, convert(u8, WasmExternal.Function)) || !wasm_write_uleb(section, convert(u64, output.type_index)) { return false; }
    }
    for (var at: usize = 0; at < convert(usize, link.imported_globals); at++) {
        var output = &link.globals.data[at];
        var global = &link.world.objects.data[convert(usize, output.object)].object.globals.data[convert(usize, output.global)];
        if !wasm_write_name(section, global.module) || !wasm_write_name(section, global.name)
            || !bytes_push(section, convert(u8, WasmExternal.Global)) || !bytes_push(section, global.type)
            || !bytes_push(section, global.mutable ? 1 : 0) { return false; }
    }
    if link.import_memory && (!wasm_write_name(section, link.memory_module) || !wasm_write_name(section, link.memory_name)
        || !bytes_push(section, convert(u8, WasmExternal.Memory)) || !wasm_emit_memory_limits(link, section)) { return false; }
    return true;
}

fn wasm_emit_globals(link: WasmLink*, section: ByteBuffer*): bool {
    var count = link.globals.length - convert(usize, link.imported_globals);
    if count == 0 { return true; }
    if !wasm_write_uleb(section, convert(u64, count)) { return false; }
    for (var at = convert(usize, link.imported_globals); at < link.globals.length; at++) {
        var output = &link.globals.data[at];
        if output.object == WasmNoIndex {
            var symbol = &link.symbols.data[convert(usize, output.symbol)];
            var value = symbol.kind == convert(u8, WasmSymbolKind.Function) ? convert(u64, symbol.table_index) : symbol.address;
            if symbol.tls { value = 0; }
            var mutable = symbol.synthetic == WasmSynthetic.Stack || symbol.synthetic == WasmSynthetic.TlsBase || symbol.tls || symbol.global_mutable;
            if !bytes_push(section, convert(u8, WasmValueType.I32)) || !bytes_push(section, mutable ? 1 : 0)
                || !wasm_emit_i32_expression(section, value) { return false; }
        } else {
            var global = &link.world.objects.data[convert(usize, output.object)].object.globals.data[convert(usize, output.global)];
            if !bytes_push(section, global.type) || !bytes_push(section, global.mutable ? 1 : 0)
                || !bytes_append(section, global.expression.data, global.expression.length) { return false; }
        }
    }
    return true;
}

fn wasm_emit_synthetic(link: WasmLink*, output: WasmOutputFunction*, body: ByteBuffer*): bool {
    var symbol = &link.symbols.data[convert(usize, output.symbol)];
    if symbol.synthetic == WasmSynthetic.InitMemory { return wasm_emit_memory_init(link, body); }
    if symbol.synthetic == WasmSynthetic.InitTls { return wasm_emit_tls_init(link, body); }
    if !wasm_write_uleb(body, 0) { return false; }
    if symbol.synthetic == WasmSynthetic.SignatureTrap {
        if !bytes_push(body, convert(u8, WasmOpcode.Unreachable)) { return false; }
    } else {
        if symbol.synthetic != WasmSynthetic.Constructors { return wasm_link_fail(link, WasmLinkError.Unsupported, symbol.name); }
        foreach (var & initializer in &link.initializers) {
            var function = &link.symbols.data[convert(usize, initializer.symbol)];
            if !bytes_push(body, convert(u8, WasmOpcode.Call)) || !wasm_write_uleb(body, convert(u64, function.output_index)) { return false; }
        }
    }
    return bytes_push(body, convert(u8, WasmOpcode.End));
}

fn wasm_emit_code(link: WasmLink*, work: WasmLinkWork*, section: ByteBuffer*): bool {
    var count = link.functions.length - convert(usize, link.imported_functions);
    if count == 0 { return true; }
    if !wasm_write_uleb(section, convert(u64, count)) { return false; }
    var body: ByteBuffer = default;
    defer bytes_dispose(&body);
    for (var at = convert(usize, link.imported_functions); at < link.functions.length; at++) {
        var output = &link.functions.data[at];
        if output.object == WasmNoIndex {
            body.length = 0;
            if !wasm_emit_synthetic(link, output, &body) || !wasm_write_uleb(section, convert(u64, body.length))
                || !bytes_append(section, body.data, body.length) { return false; }
        } else {
            var input = convert(usize, output.object);
            var function = &link.world.objects.data[input].object.functions.data[convert(usize, output.function)];
            var chunk = &link.layouts.data[input].functions.data[convert(usize, output.function)];
            if !wasm_write_uleb(section, convert(u64, function.code.length)) { return false; }
            chunk.output_offset = convert(u64, section.length);
            if !wasm_link_copy(work, link, section, input, chunk, function.code_offset, function.code) { return false; }
        }
    }
    return wasm_link_jobs_run(work, link, section);
}

fn wasm_emit_data(link: WasmLink*, work: WasmLinkWork*, section: ByteBuffer*): bool {
    var count = link.data_count;
    if count == 0 { return true; }
    if !wasm_write_uleb(section, convert(u64, count)) { return false; }
    for (var input: usize = 0; input < link.world.objects.length; input++) {
        var object = link.world.objects.data[input].object;
        var layout = link.layouts.data[input];
        for (var row: usize = 0; row < object.data.length; row++) {
            var chunk = &layout.data.data[row];
            if !chunk.live { continue; }
            var data = &object.data.data[row];
            var passive = link.shared_memory || chunk.tls;
            var mode = passive ? WasmDataMode.Passive : WasmDataMode.Active;
            if !wasm_write_uleb(section, convert(u64, mode)) || (!passive && !wasm_emit_i32_expression(section, chunk.address))
                || !wasm_write_uleb(section, convert(u64, data.bytes.length)) { return false; }
            chunk.output_offset = convert(u64, section.length);
            if !wasm_link_copy(work, link, section, input, chunk, data.section_offset, data.bytes) { return false; }
        }
    }
    return wasm_link_jobs_run(work, link, section);
}

fn wasm_emit_names(link: WasmLink*, section: ByteBuffer*): bool {
    var names: ByteBuffer = default;
    defer bytes_dispose(&names);
    var count: usize = 0;
    foreach (var & function in &link.functions) { if function.symbol != WasmNoIndex { count++; } }
    if !wasm_write_uleb(&names, convert(u64, count)) { return false; }
    for (var at: usize = 0; at < link.functions.length; at++) {
        var function = &link.functions.data[at];
        if function.symbol == WasmNoIndex { continue; }
        if !wasm_write_uleb(&names, convert(u64, at)) || !wasm_write_name(&names, link.symbols.data[convert(usize, function.symbol)].name) { return false; }
    }
    var function_names: u8 = 1;
    return wasm_write_name(section, wasm_text_bytes("name")) && bytes_push(section, function_names)
        && wasm_write_uleb(section, convert(u64, names.length)) && bytes_append(section, names.data, names.length);
}

fn wasm_link_emit_sections(link: WasmLink*, output: ByteBuffer*): bool {
    var work: WasmLinkWork = default;
    defer wasm_link_work_close(&work);
    var header: u8[8] = default;
    header[1] = 97; header[2] = 115; header[3] = 109; header[4] = 1;
    if !bytes_append(output, &header[0], 8) { return false; }
    var section: ByteBuffer = default;
    defer bytes_dispose(&section);
    if link.types.length != 0 {
        if !wasm_write_uleb(&section, convert(u64, link.types.length)) { return false; }
        foreach (var & type in &link.types) { if !bytes_append(&section, type.data, type.length) { return false; } }
        if !wasm_emit_section(output, WasmSection.Type, &section) { return false; }
    }
    if !wasm_emit_imports(link, &section) || !wasm_emit_section(output, WasmSection.Import, &section) { return false; }
    var definitions = link.functions.length - convert(usize, link.imported_functions);
    if definitions != 0 {
        if !wasm_write_uleb(&section, convert(u64, definitions)) { return false; }
        for (var at = convert(usize, link.imported_functions); at < link.functions.length; at++) {
            if !wasm_write_uleb(&section, convert(u64, link.functions.data[at].type_index)) { return false; }
        }
        if !wasm_emit_section(output, WasmSection.Function, &section) { return false; }
    }
    if link.table_live || link.export_table {
        var count = convert(u64, link.table_functions.length) + convert(u64, WasmTableBase);
        if !wasm_write_uleb(&section, 1) || !bytes_push(&section, convert(u8, WasmValueType.FuncRef))
            || !wasm_write_uleb(&section, 1) || !wasm_write_uleb(&section, count) || !wasm_write_uleb(&section, count)
            || !wasm_emit_section(output, WasmSection.Table, &section) { return false; }
    }
    if !link.import_memory && (!wasm_write_uleb(&section, 1) || !wasm_emit_memory_limits(link, &section)
        || !wasm_emit_section(output, WasmSection.Memory, &section)) { return false; }
    if !wasm_emit_globals(link, &section)
        || !wasm_emit_section(output, WasmSection.Global, &section) { return false; }
    if link.output_exports.length != 0 {
        if !wasm_write_uleb(&section, convert(u64, link.output_exports.length)) { return false; }
        foreach (var & exported in &link.output_exports) {
            if !wasm_write_name(&section, exported.name) || !bytes_push(&section, exported.kind) || !wasm_write_uleb(&section, convert(u64, exported.index)) { return false; }
        }
        if !wasm_emit_section(output, WasmSection.Export, &section) { return false; }
    }
    if link.memory_init_symbol != WasmNoIndex {
        var start = link.symbols.data[convert(usize, link.memory_init_symbol)].output_index;
        if !wasm_write_uleb(&section, convert(u64, start)) || !wasm_emit_section(output, WasmSection.Start, &section) { return false; }
    }
    if link.table_functions.length != 0 {
        if !wasm_write_uleb(&section, 1) || !wasm_write_uleb(&section, 0) || !wasm_emit_i32_expression(&section, convert(u64, WasmTableBase))
            || !wasm_write_uleb(&section, convert(u64, link.table_functions.length)) { return false; }
        foreach (var function in &link.table_functions) { if !wasm_write_uleb(&section, convert(u64, function)) { return false; } }
        if !wasm_emit_section(output, WasmSection.Element, &section) { return false; }
    }
    if (link.shared_memory || link.has_tls) && (!wasm_write_uleb(&section, convert(u64, link.data_count)) || !wasm_emit_section(output, WasmSection.DataCount, &section)) { return false; }
    if !wasm_emit_code(link, &work, &section) || !wasm_emit_section(output, WasmSection.Code, &section)
        || !wasm_emit_data(link, &work, &section) || !wasm_emit_section(output, WasmSection.Data, &section) { return false; }
    if link.emit_names && (!wasm_emit_names(link, &section) || !wasm_emit_section(output, WasmSection.Custom, &section)) { return false; }
    if link.features.length != 0 {
        if !wasm_write_name(&section, wasm_text_bytes("target_features")) || !wasm_write_uleb(&section, convert(u64, link.features.length)) { return false; }
        foreach (var & feature in &link.features) {
            if !bytes_push(&section, feature.prefix) || !wasm_write_name(&section, feature.name) { return false; }
        }
        if !wasm_emit_section(output, WasmSection.Custom, &section) { return false; }
    }
    return true;
}

// Publish only a complete image. Failure retains the caller's previous output.
fn wasm_link_emit(link: WasmLink*): bool {
    var output: ByteBuffer = default;
    if !wasm_link_emit_sections(link, &output) {
        bytes_dispose(&output);
        return wasm_link_fail(link, WasmLinkError.Allocation, default(WasmBytes));
    }
    bytes_dispose(&link.output); link.output = output;
    return true;
}

import tower;
import wasm_bytes;
import wasm_link_types;
import wasm_link_relocate;
import .library.vector;
import .library.bytes_types;
import .library.bytes_interface;
import .library.entity_types;
import .library.entity_api;
import .library.work_graph;
import .library.work_pool;

struct WasmLinkCopy { input: usize; chunk: WasmChunkLayout*; source: WasmBytes; original_offset: u32; offset: usize; }
struct WasmLinkJob {
    owner: WasmLink*; copies: WasmLinkCopy*; count: usize; output: u8*;
    ticket: WorkTicket; error: WasmLinkError; error_name: WasmBytes;
}
struct WasmLinkWork { pool: WorkPool; copies: vector(WasmLinkCopy); cost: u64; opened: bool; }
var WasmLinkInputDomain: u64 = 1;
var WasmLinkOutputDomain: u64 = 2;
var WasmLinkJobDomain: u64 = 3;
var WasmLinkInputComponent: u64 = 1;
var WasmLinkOutputComponent: u64 = 1;
var WasmLinkPatchQuery: u32 = 1;
var WasmLinkJobsPerLane: usize = 4;

fn wasm_link_job_execute(payload: void*): void {
    var job = bits(WasmLinkJob*, payload);
    // A shallow borrowed view, not another owning world. Only the private error
    // fields may change; all vectors, symbols and entity metadata are frozen.
    var local = *job.owner;
    local.error = WasmLinkError.None; local.error_name = default;
    for (var at: usize = 0; at < job.count; at++) {
        var item = &job.copies[at];
        var target: WasmBytes = { data: job.output + item.offset, length: item.source.length };
        copy(target.data, item.source.data, target.length);
        if !wasm_link_relocate(&local, item.input, item.chunk, item.original_offset, target) { break; }
    }
    job.error = local.error; job.error_name = local.error_name;
}

fn wasm_link_work_close(work: WasmLinkWork*): void {
    if work.opened { work_pool_close(&work.pool); }
    vector_dispose(&work.copies);
    *work = default;
}

fn wasm_link_copy(work: WasmLinkWork*, link: WasmLink*, section: ByteBuffer*, input: usize,
chunk: WasmChunkLayout*, original_offset: u32, source: WasmBytes): bool {
    if source.length == 0 { return true; }
    if link.workers <= 1 {
        var offset = section.length;
        return bytes_append(section, source.data, source.length) && wasm_link_relocate(link, input, chunk, original_offset,
            init(WasmBytes) { data: section.data + offset, length: source.length });
    }
    if source.length > ~convert(usize, 0) - section.length || !bytes_reserve(section, section.length + source.length) { return false; }
    var item: WasmLinkCopy = { input: input, chunk: chunk, source: source, original_offset: original_offset, offset: section.length };
    if !vector_push(&work.copies, item) { return false; }
    section.length += source.length;
    var cost = convert(u64, source.length) + convert(u64, chunk.relocation_count) * WasmLinkRelocationCost;
    if cost > ~convert(u64, 0) - work.cost { return false; }
    work.cost += cost;
    return true;
}

fn wasm_link_jobs_cancelled(link: WasmLink*): bool {
    return link.cancel != null && link.cancel(link.cancel_context);
}

fn wasm_link_jobs_run(work: WasmLinkWork*, link: WasmLink*, section: ByteBuffer*): bool {
    if work.copies.length == 0 {
        if link.cancel == null { return true; }
        var view = entity_view_open(link.world.object_type);
        if view == null { return false; }
        defer entity_view_close(view);
        return !wasm_link_jobs_cancelled(link) || wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("link cancelled"));
    }
    if link.workers == 0 || link.workers > WasmLinkMaximumWorkers || link.job_grain == 0 { return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("invalid linker worker budget")); }
    var limit = link.workers * WasmLinkJobsPerLane;
    var grain = work.cost / convert(u64, limit);
    if grain < link.job_grain { grain = link.job_grain; }
    if work.opened && work.pool.count == 1 && work.cost >= link.job_grain && link.workers > 1 && work_thread_capacity() > 1 {
        work_pool_close(&work.pool); work.opened = false;
    }
    if !work.opened {
        var lanes = work.cost < link.job_grain ? convert(usize, 1) : link.workers;
        if !work_pool_open_kernel(&work.pool, lanes, wasm_link_job_execute) { return wasm_link_fail(link, WasmLinkError.Allocation, wasm_text_bytes("linker worker pool")); }
        work.opened = true;
    }
    var graph: WorkGraph = default;
    work_init(&graph, 1, 1);
    defer work_dispose(&graph);
    var kind = entity_create(link.world.store);
    if kind == null { return false; }
    defer entity_release(kind);
    if !entity_register(kind, sizeof(WasmLinkJob), alignof(WasmLinkJob), 0) { return false; }
    var nodes: vector(Entity*) = default;
    var jobs: vector(WasmLinkJob*) = default;
    defer { foreach (var node in &nodes) { entity_release(node); } vector_dispose(&nodes); vector_dispose(&jobs); }
    for (var first: usize = 0; first < work.copies.length;) {
        var last = first; var cost: u64 = 0;
        while last < work.copies.length && (last == first || cost < grain) {
            var item = &work.copies.data[last++];
            cost += convert(u64, item.source.length) + convert(u64, item.chunk.relocation_count) * WasmLinkRelocationCost;
        }
        var node = entity_create(link.world.store);
        if node == null { return false; }
        if !vector_push(&nodes, node) { entity_release(node); return false; }
        var component = entity_component_add(node, kind);
        if component == null { return false; }
        var job = bits(WasmLinkJob*, entity_component_data(component));
        *job = init(WasmLinkJob) { owner: link, copies: work.copies.data + first, count: last - first, output: section.data, ..default };
        if !vector_push(&jobs, job) { return false; }
        var task = work_request(&graph, bits(void*, node), WasmLinkPatchQuery, convert(u64, jobs.length));
        var begin = work.copies.data[first].offset;
        var end = work.copies.data[last - 1].offset + work.copies.data[last - 1].source.length;
        if task == 0 || !work_access(&graph, task, WasmLinkInputDomain, WasmLinkInputComponent, 0, link.world.objects.length, WorkAccessMode.Read)
            || !work_access(&graph, task, WasmLinkOutputDomain, WasmLinkOutputComponent, begin, end - begin, WorkAccessMode.Write)
            || !work_access(&graph, task, WasmLinkJobDomain, WasmLinkOutputComponent, jobs.length - 1, 1, WorkAccessMode.Write)
            || !work_seal(&graph, task) || !work_demand(&graph, task) {
            return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("linker job access graph"));
        }
        first = last;
    }
    var view = entity_view_open(kind);
    if view == null { return false; }
    // Drain before closing the view and reclaiming job payloads on every exit.
    defer { while work.pool.running != 0 { work_pool_receive(&work.pool, true); } entity_view_close(view); }
    var finished: usize = 0;
    while finished < jobs.length {
        if wasm_link_jobs_cancelled(link) {
            work_cancel(&graph);
            return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("link cancelled"));
        }
        while work.pool.running < work.pool.count {
            var ticket: WorkTicket = default;
            if !work_take(&graph, &ticket) { break; }
            var task = work_task(&graph, ticket.task);
            var job = jobs.data[convert(usize, task.argument) - 1];
            job.ticket = ticket;
            if !work_pool_submit(&work.pool, bits(void*, job)) { return false; }
        }
        if work.pool.running == 0 { return false; }
        var done = bits(WasmLinkJob*, work_pool_receive(&work.pool, true));
        // Failed independent jobs do not cancel earlier jobs. Error selection
        // occurs below in source order, never whichever thread happened to win.
        if !work_finish(&graph, &done.ticket, true) { return false; }
        finished++;
    }
    link.jobs_run += jobs.length;
    if work.pool.peak > link.jobs_peak { link.jobs_peak = work.pool.peak; }
    foreach (var job in &jobs) {
        if job.error != WasmLinkError.None { return wasm_link_fail(link, job.error, job.error_name); }
    }
    work.copies.length = 0; work.cost = 0;
    return true;
}

import tower;
import wasm_bytes;
import wasm_names;
import wasm_object_types;
import wasm_link_types;
import wasm_link_symbols;
import wasm_link_synthetic;

fn wasm_link_align(link: WasmLink*, address: u64, alignment: u64): u64 {
    if alignment != 0 && alignment <= WasmMemory32Limit && address <= WasmMemory32Limit && (address & (alignment - 1)) == 0 { return address; }
    if alignment == 0 || alignment > WasmMemory32Limit || address > WasmMemory32Limit - (alignment - 1) {
        wasm_link_fail(link, WasmLinkError.Layout, wasm_text_bytes("linear memory alignment")); return 0;
    }
    return (address + alignment - 1) & ~(alignment - 1);
}

fn wasm_link_stack(link: WasmLink*, address: u64): u64 {
    if link.stack_size % WasmStackAlignment != 0 || link.stack_size >= WasmMemory32Limit {
        wasm_link_fail(link, WasmLinkError.Layout, wasm_text_bytes("stack size")); return 0;
    }
    link.stack_low = wasm_link_align(link, address, WasmStackAlignment);
    if link.stack_low >= WasmMemory32Limit - link.stack_size {
        wasm_link_fail(link, WasmLinkError.Layout, wasm_text_bytes("stack address")); return 0;
    }
    link.stack_high = link.stack_low + link.stack_size;
    return link.stack_high;
}

fn wasm_link_memory_layout(link: WasmLink*): bool {
    var address: u64 = link.stack_first ? wasm_link_stack(link, 0) : WasmDefaultGlobalBase;
    link.global_base = address;
    for (var input: usize = 0; input < link.world.objects.length; input++) {
        var object = link.world.objects.data[input].object;
        var layout = link.layouts.data[input];
        for (var row: usize = 0; row < object.data.length; row++) {
            if !layout.data.data[row].live || !layout.data.data[row].tls { continue; }
            var data = &object.data.data[row];
            if data.alignment >= 32 { return wasm_link_fail(link, WasmLinkError.Layout, data.name); }
            var alignment = convert(u64, 1) << convert(u64, data.alignment);
            if alignment > link.tls_align { link.tls_align = alignment; }
        }
    }
    address = wasm_link_align(link, address, link.tls_align);
    link.tls_base = address;
    var layout_passes: u32 = 2;
    for (var pass: u32 = 0; pass < layout_passes; pass++) {
        for (var input: usize = 0; input < link.world.objects.length; input++) {
            var object = link.world.objects.data[input].object;
            var layout = link.layouts.data[input];
            for (var row: usize = 0; row < object.data.length; row++) {
                var chunk = &layout.data.data[row];
                if !chunk.live || chunk.tls != (pass == 0) { continue; }
                var data = &object.data.data[row];
                if data.alignment >= 32 { return wasm_link_fail(link, WasmLinkError.Layout, data.name); }
                address = wasm_link_align(link, address, convert(u64, 1) << convert(u64, data.alignment));
                var length = convert(u64, data.bytes.length);
                if address >= WasmMemory32Limit || length >= WasmMemory32Limit - address {
                    return wasm_link_fail(link, WasmLinkError.Layout, data.name);
                }
                chunk.address = address; address += length;
            }
        }
        if pass == 0 { link.tls_size = address - link.tls_base; }
    }
    // Segment indexes follow emission/input order, independently of TLS layout.
    foreach (var layout in &link.layouts) {
        foreach (var & chunk in &layout.data) {
            if !chunk.live { continue; }
            if link.data_count == WasmNoIndex { return wasm_link_fail(link, WasmLinkError.Layout, wasm_text_bytes("data segment count")); }
            chunk.output_index = link.data_count++;
        }
    }
    if link.shared_memory {
        link.memory_init_flag = wasm_link_align(link, address, WasmMemoryInitFlagBytes);
        if link.memory_init_flag >= WasmMemory32Limit - WasmMemoryInitFlagBytes { return wasm_link_fail(link, WasmLinkError.Layout, wasm_text_bytes("memory initialization flag")); }
        address = link.memory_init_flag + WasmMemoryInitFlagBytes;
    }
    link.data_end = address;
    if !link.stack_first { address = wasm_link_stack(link, address); }
    link.heap_base = wasm_link_align(link, address, WasmStackAlignment);
    address = link.heap_base;
    if link.initial_memory != 0 {
        if link.initial_memory % WasmPageBytes != 0 || address > link.initial_memory || link.initial_memory > WasmMemory32Limit {
            return wasm_link_fail(link, WasmLinkError.Layout, wasm_text_bytes("initial memory"));
        }
        address = link.initial_memory;
    }
    link.initial_memory = wasm_link_align(link, address, WasmPageBytes);
    if link.maximum_memory != 0 && (link.maximum_memory % WasmPageBytes != 0
        || link.maximum_memory < link.initial_memory || link.maximum_memory > WasmMemory32Limit) {
        return wasm_link_fail(link, WasmLinkError.Layout, wasm_text_bytes("maximum memory"));
    }
    foreach (var & symbol in &link.symbols) {
        if !symbol.live { continue; }
        match symbol.synthetic {
            WasmSynthetic.Stack | WasmSynthetic.StackHigh => { symbol.address = link.stack_high; }
            WasmSynthetic.StackLow => { symbol.address = link.stack_low; }
            WasmSynthetic.HeapBase => { symbol.address = link.heap_base; }
            WasmSynthetic.HeapEnd => { symbol.address = link.initial_memory; }
            WasmSynthetic.DataEnd => { symbol.address = link.data_end; }
            WasmSynthetic.DsoHandle | WasmSynthetic.GlobalBase => { symbol.address = link.global_base; }
            WasmSynthetic.TableBase => { symbol.address = convert(u64, WasmTableBase); }
            WasmSynthetic.FirstPageEnd => { symbol.address = WasmPageBytes; }
            WasmSynthetic.TlsBase => { symbol.address = link.shared_memory ? 0 : link.tls_base; }
            WasmSynthetic.TlsSize => { symbol.address = link.tls_size; }
            WasmSynthetic.TlsAlign => { symbol.address = link.tls_align; }
            _ => { }
        }
        if symbol.kind == convert(u8, WasmSymbolKind.Data) && symbol.defined && symbol.definition.object != WasmNoIndex {
            var input = link.world.objects.data[convert(usize, symbol.definition.object)].object;
            var original = &input.symbols.data[convert(usize, symbol.definition.symbol)];
            var chunk = wasm_link_symbol_chunk(link, symbol.definition);
            symbol.address = chunk.address + original.offset;
        }
    }
    return link.error == WasmLinkError.None;
}

fn wasm_link_function_layout(link: WasmLink*): bool {
    // Imports precede all definitions in their own Wasm index spaces.
    for (var row: usize = 0; row < link.symbols.length; row++) {
        var symbol = &link.symbols.data[row];
        if !symbol.live || symbol.defined || symbol.kind != convert(u8, WasmSymbolKind.Function) { continue; }
        symbol.output_index = convert(u32, link.functions.length);
        var reference = symbol.import_declaration;
        var object = link.world.objects.data[convert(usize, reference.object)].object;
        var original = &object.symbols.data[convert(usize, reference.symbol)];
        var output: WasmOutputFunction = { object: reference.object, function: original.index,
            symbol: convert(u32, row), type_index: wasm_link_function_type(link, convert(u32, row)) };
        if !wasm_link_push(link, &link.functions, output) { return false; }
    }
    link.imported_functions = convert(u32, link.functions.length);
    for (var input: usize = 0; input < link.world.objects.length; input++) {
        var object = link.world.objects.data[input].object;
        var layout = link.layouts.data[input];
        for (var row = convert(usize, object.imported_functions); row < object.functions.length; row++) {
            var chunk = &layout.functions.data[row];
            if !chunk.live { continue; }
            chunk.output_index = convert(u32, link.functions.length);
            var output: WasmOutputFunction = { object: convert(u32, input), function: convert(u32, row), symbol: WasmNoIndex,
                type_index: layout.types.data[convert(usize, object.functions.data[row].type_index)] };
            if !wasm_link_push(link, &link.functions, output) { return false; }
        }
    }
    for (var row: usize = 0; row < link.symbols.length; row++) {
        var symbol = &link.symbols.data[row];
        if !symbol.live || !symbol.defined || symbol.kind != convert(u8, WasmSymbolKind.Function) { continue; }
        if symbol.definition.object != WasmNoIndex {
            symbol.output_index = wasm_link_symbol_chunk(link, symbol.definition).output_index;
            var output = &link.functions.data[convert(usize, symbol.output_index)];
            if output.symbol == WasmNoIndex { output.symbol = convert(u32, row); }
        }
        else {
            symbol.output_index = convert(u32, link.functions.length);
            var output: WasmOutputFunction = { object: WasmNoIndex, function: WasmNoIndex, symbol: convert(u32, row),
                type_index: wasm_link_function_type(link, convert(u32, row)) };
            if !wasm_link_push(link, &link.functions, output) { return false; }
        }
    }
    foreach (var & symbol in &link.symbols) {
        if !symbol.live || !symbol.needs_table || symbol.synthetic == WasmSynthetic.SignatureTrap { continue; }
        var chunk = symbol.defined ? wasm_link_symbol_chunk(link, symbol.definition) : null;
        if chunk != null && chunk.table_index != 0 { symbol.table_index = chunk.table_index; continue; }
        symbol.table_index = WasmTableBase + convert(u32, link.table_functions.length);
        if !wasm_link_push(link, &link.table_functions, symbol.output_index) { return false; }
        if chunk != null { chunk.table_index = symbol.table_index; }
    }
    return true;
}

fn wasm_link_global_layout(link: WasmLink*): bool {
    foreach (var & request in &link.exports) {
        var index = wasm_names_get(&link.names, request.name);
        if index != WasmNoIndex {
            var symbol = &link.symbols.data[convert(usize, index)];
            if symbol.defined && symbol.kind == convert(u8, WasmSymbolKind.Data) { symbol.needs_global = true; }
        }
    }
    for (var row: usize = 0; row < link.symbols.length; row++) {
        var symbol = &link.symbols.data[row];
        if !symbol.live || symbol.defined || symbol.kind != convert(u8, WasmSymbolKind.Global) { continue; }
        symbol.output_index = convert(u32, link.globals.length);
        var reference = symbol.import_declaration;
        var object = link.world.objects.data[convert(usize, reference.object)].object;
        var original = &object.symbols.data[convert(usize, reference.symbol)];
        var output: WasmOutputGlobal = { object: reference.object, global: original.index, symbol: convert(u32, row) };
        if !wasm_link_push(link, &link.globals, output) { return false; }
    }
    link.imported_globals = convert(u32, link.globals.length);
    for (var input: usize = 0; input < link.world.objects.length; input++) {
        var object = link.world.objects.data[input].object;
        var layout = link.layouts.data[input];
        for (var row: usize = 0; row < object.globals.length; row++) {
            var chunk = &layout.globals.data[row];
            if !chunk.live || object.globals.data[row].imported { continue; }
            chunk.output_index = convert(u32, link.globals.length);
            var output: WasmOutputGlobal = { object: convert(u32, input), global: convert(u32, row), symbol: WasmNoIndex };
            if !wasm_link_push(link, &link.globals, output) { return false; }
        }
    }
    for (var row: usize = 0; row < link.symbols.length; row++) {
        var symbol = &link.symbols.data[row];
        if !symbol.live { continue; }
        var kind = convert(WasmSymbolKind, symbol.kind);
        if kind == WasmSymbolKind.Table {
            if symbol.synthetic != WasmSynthetic.IndirectTable { return wasm_link_fail(link, WasmLinkError.Unsupported, symbol.name); }
            symbol.output_index = 0;
        }
        if kind == WasmSymbolKind.Global && symbol.defined && symbol.definition.object != WasmNoIndex {
            symbol.output_index = wasm_link_symbol_chunk(link, symbol.definition).output_index;
        }
        var synthetic = kind == WasmSymbolKind.Global && symbol.defined && symbol.definition.object == WasmNoIndex;
        if synthetic || symbol.needs_global {
            var index = convert(u32, link.globals.length);
            if synthetic { symbol.output_index = index; } else { symbol.got_index = index; }
            var output: WasmOutputGlobal = { object: WasmNoIndex, global: WasmNoIndex, symbol: convert(u32, row) };
            if !wasm_link_push(link, &link.globals, output) { return false; }
        }
    }
    return true;
}

fn wasm_link_export_layout(link: WasmLink*): bool {
    var names: WasmNameMap = default;
    defer wasm_names_dispose(&names);
    if link.export_memory {
        var exported: WasmOutputExport = { name: wasm_text_bytes("memory"), kind: convert(u8, WasmExternal.Memory), index: 0 };
        if !wasm_names_set(&names, exported.name, convert(u32, link.output_exports.length)) || !wasm_link_push(link, &link.output_exports, exported) { return false; }
    }
    foreach (var & request in &link.exports) {
        var index = wasm_names_get(&link.names, request.name);
        if index == WasmNoIndex || !link.symbols.data[convert(usize, index)].defined { continue; }
        var symbol = &link.symbols.data[convert(usize, index)];
        var exported: WasmOutputExport = { name: request.name, index: symbol.output_index, ..default };
        var kind = convert(WasmSymbolKind, symbol.kind);
        match kind {
            WasmSymbolKind.Function => { exported.kind = convert(u8, WasmExternal.Function); }
            WasmSymbolKind.Global => { exported.kind = convert(u8, WasmExternal.Global); }
            WasmSymbolKind.Data => { exported.kind = convert(u8, WasmExternal.Global); exported.index = symbol.got_index; }
            WasmSymbolKind.Table => { exported.kind = convert(u8, WasmExternal.Table); }
            _ => { return wasm_link_fail(link, WasmLinkError.Unsupported, request.name); }
        }
        var previous = wasm_names_get(&names, request.name);
        if previous != WasmNoIndex {
            var old = &link.output_exports.data[convert(usize, previous)];
            if old.kind != exported.kind || old.index != exported.index { return wasm_link_fail(link, WasmLinkError.Duplicate, request.name); }
            continue;
        }
        if exported.index == WasmNoIndex { return wasm_link_fail(link, WasmLinkError.Layout, request.name); }
        if !wasm_names_set(&names, request.name, convert(u32, link.output_exports.length)) || !wasm_link_push(link, &link.output_exports, exported) {
            return wasm_link_fail(link, WasmLinkError.Allocation, request.name);
        }
    }
    return true;
}

fn wasm_link_layout(link: WasmLink*): bool {
    return wasm_link_memory_layout(link) && wasm_link_function_layout(link) && wasm_link_global_layout(link) && wasm_link_export_layout(link);
}

import tower;
import wasm_bytes;
import wasm_names;
import wasm_object_types;
import wasm_object_linking;
import wasm_link_types;
import wasm_link_symbols;
import .library.vector;

fn wasm_link_relocation_chunk(link: WasmLink*, input: usize, index: usize): WasmChunkLayout* {
    var object = link.world.objects.data[input].object;
    var row = object.relocation_chunks.data[index];
    if row == WasmNoIndex { return null; }
    var layout = link.layouts.data[input];
    return object.relocations.data[index].section == object.code_section ? &layout.functions.data[convert(usize, row)] : &layout.data.data[convert(usize, row)];
}

fn wasm_link_relocation_sift(object: WasmObject*, indexes: u32*, root: usize, count: usize): void {
    while root < count / 2 {
        var child = root * 2 + 1;
        if child + 1 < count && object.relocations.data[convert(usize, indexes[child])].offset < object.relocations.data[convert(usize, indexes[child + 1])].offset { child++; }
        if object.relocations.data[convert(usize, indexes[root])].offset >= object.relocations.data[convert(usize, indexes[child])].offset { return; }
        var saved = indexes[root]; indexes[root] = indexes[child]; indexes[child] = saved;
        root = child;
    }
}

fn wasm_link_sort_relocations(link: WasmLink*, input: usize, chunks: vector(WasmChunkLayout)*): bool {
    var object = link.world.objects.data[input].object;
    var layout = link.layouts.data[input];
    foreach (var & chunk in chunks) {
        var count = chunk.relocation_count;
        if count < 2 { continue; }
        var indexes = layout.relocations.data + chunk.relocation_first;
        var ordered = true;
        for (var at: usize = 1; at < count; at++) {
            if object.relocations.data[convert(usize, indexes[at - 1])].offset > object.relocations.data[convert(usize, indexes[at])].offset { ordered = false; break; }
        }
        if !ordered {
            for (var root = count / 2; root != 0;) { wasm_link_relocation_sift(object, indexes, --root, count); }
            for (var last = count; last > 1;) {
                last--; var saved = indexes[0]; indexes[0] = indexes[last]; indexes[last] = saved;
                wasm_link_relocation_sift(object, indexes, 0, last);
            }
        }
        var end: u64 = 0;
        for (var at: usize = 0; at < count; at++) {
            var relocation = &object.relocations.data[convert(usize, indexes[at])];
            if convert(u64, relocation.offset) < end { return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("overlapping relocation operands")); }
            end = convert(u64, relocation.offset) + convert(u64, wasm_relocation_width(convert(WasmRelocation, relocation.kind)));
        }
    }
    return true;
}

// Coordinator builds CSR indexes once. Readers/patchers then visit only the
// relocations belonging to their own chunk, with no global scan or shared cursor.
fn wasm_link_relocation_indexes(link: WasmLink*): bool {
    for (var input: usize = 0; input < link.world.objects.length; input++) {
        var object = link.world.objects.data[input].object;
        var layout = link.layouts.data[input];
        var total: usize = 0;
        for (var row: usize = 0; row < object.relocations.length; row++) {
            var chunk = wasm_link_relocation_chunk(link, input, row);
            if chunk != null { chunk.relocation_count++; total++; }
        }
        if !vector_reserve(&layout.relocations, total) { return wasm_link_fail(link, WasmLinkError.Allocation, default(WasmBytes)); }
        layout.relocations.length = total;
        var first: usize = 0;
        foreach (var & chunk in &layout.functions) { chunk.relocation_first = first; first += chunk.relocation_count; chunk.relocation_count = 0; }
        foreach (var & chunk in &layout.data) { chunk.relocation_first = first; first += chunk.relocation_count; chunk.relocation_count = 0; }
        for (var row: usize = 0; row < object.relocations.length; row++) {
            var chunk = wasm_link_relocation_chunk(link, input, row);
            if chunk != null { layout.relocations.data[chunk.relocation_first + chunk.relocation_count++] = convert(u32, row); }
        }
        if !wasm_link_sort_relocations(link, input, &layout.functions) || !wasm_link_sort_relocations(link, input, &layout.data) { return false; }
    }
    return true;
}

fn wasm_link_mark_chunk(link: WasmLink*, input: u32, index: u32, kind: WasmSymbolKind, chunk: WasmChunkLayout*): bool {
    if chunk.discarded || chunk.live { return true; }
    chunk.live = true;
    var reference: WasmChunkReference = { object: input, index: index, kind: kind };
    return wasm_link_push(link, &link.pending, reference);
}

fn wasm_link_mark(link: WasmLink*, index: u32): bool {
    var symbol = &link.symbols.data[convert(usize, index)];
    if symbol.live { return true; }
    symbol.live = true;
    if symbol.kind == convert(u8, WasmSymbolKind.Table) { link.table_live = true; }
    var chunk = wasm_link_symbol_chunk(link, symbol.definition);
    if !symbol.defined || symbol.definition.object == WasmNoIndex { return true; }
    var input = link.world.objects.data[convert(usize, symbol.definition.object)].object;
    var original = &input.symbols.data[convert(usize, symbol.definition.symbol)];
    return chunk == null || wasm_link_mark_chunk(link, symbol.definition.object, original.index, convert(WasmSymbolKind, symbol.kind), chunk);
}

fn wasm_link_table_relocation(kind: WasmRelocation): bool {
    return kind == WasmRelocation.TableIndexSleb || kind == WasmRelocation.TableIndexI32
        || kind == WasmRelocation.TableIndexRelativeSleb || kind == WasmRelocation.TableIndexSleb64
        || kind == WasmRelocation.TableIndexI64 || kind == WasmRelocation.TableIndexRelativeSleb64;
}

fn wasm_link_roots(link: WasmLink*): bool {
    if link.memory_init_symbol != WasmNoIndex && !wasm_link_mark(link, link.memory_init_symbol) { return false; }
    if link.tls_init_symbol != WasmNoIndex && (!wasm_link_mark(link, link.tls_init_symbol) || !wasm_link_mark(link, link.tls_base_symbol)) { return false; }
    foreach (var & request in &link.exports) {
        var index = wasm_names_get(&link.names, request.name);
        if index == WasmNoIndex || !link.symbols.data[convert(usize, index)].defined {
            if request.required { return wasm_link_fail(link, WasmLinkError.Undefined, request.name); }
            continue;
        }
        if !wasm_link_mark(link, index) { return false; }
    }
    var stack = wasm_names_get(&link.names, wasm_text_bytes("__stack_pointer"));
    if stack != WasmNoIndex && !wasm_link_mark(link, stack) { return false; }
    for (var input: usize = 0; input < link.world.objects.length; input++) {
        var object = link.world.objects.data[input].object;
        var layout = link.layouts.data[input];
        for (var row: usize = 0; row < object.data.length; row++) {
            if (object.data.data[row].flags & convert(u32, WasmSegmentFlag.Retain)) != 0
                && !wasm_link_mark_chunk(link, convert(u32, input), convert(u32, row), WasmSymbolKind.Data, &layout.data.data[row]) { return false; }
        }
        for (var row: usize = 0; row < object.symbols.length; row++) {
            var source = &object.symbols.data[row];
            var rooted = (source.flags & (convert(u32, WasmSymbolFlag.Exported) | convert(u32, WasmSymbolFlag.NoStrip))) != 0;
            if rooted || !link.garbage_collect {
                if !wasm_link_mark(link, layout.symbols.data[row]) { return false; }
            }
            if (source.flags & convert(u32, WasmSymbolFlag.Exported)) != 0 {
                var request: WasmExportRequest = { name: source.name, required: true };
                if !wasm_link_push(link, &link.exports, request) { return false; }
            }
        }
        foreach (var & initializer in &object.initializers) {
            var reference: WasmSymbolReference = { object: convert(u32, input), symbol: initializer.symbol };
            var chunk = wasm_link_symbol_chunk(link, reference);
            if chunk != null && chunk.discarded { continue; }
            var index = layout.symbols.data[convert(usize, initializer.symbol)];
            var selected: WasmLinkInitializer = { priority: initializer.priority, symbol: index };
            if !wasm_link_mark(link, index)
                || !wasm_link_push(link, &link.initializers, selected) { return false; }
        }
        if !link.garbage_collect {
            for (var row = convert(usize, object.imported_functions); row < layout.functions.length; row++) {
                if !wasm_link_mark_chunk(link, convert(u32, input), convert(u32, row), WasmSymbolKind.Function, &layout.functions.data[row]) { return false; }
            }
            for (var row: usize = 0; row < layout.data.length; row++) {
                if !wasm_link_mark_chunk(link, convert(u32, input), convert(u32, row), WasmSymbolKind.Data, &layout.data.data[row]) { return false; }
            }
        }
    }
    // Stable priority ordering retains archive/input order for equal priorities.
    for (var at: usize = 1; at < link.initializers.length; at++) {
        var value = link.initializers.data[at];
        var next = at;
        while next != 0 && link.initializers.data[next - 1].priority > value.priority {
            link.initializers.data[next] = link.initializers.data[next - 1]; next--;
        }
        link.initializers.data[next] = value;
    }
    return true;
}

fn wasm_link_liveness(link: WasmLink*): bool {
    if !wasm_link_relocation_indexes(link) || !wasm_link_roots(link) { return false; }
    for (var next: usize = 0; next < link.pending.length; next++) {
        var work = link.pending.data[next];
        var input = convert(usize, work.object);
        var layout = link.layouts.data[input];
        var object = link.world.objects.data[input].object;
        var row = convert(usize, work.index);
        var chunk: WasmChunkLayout* = null;
        if work.kind == WasmSymbolKind.Function { chunk = &layout.functions.data[row]; }
        if work.kind == WasmSymbolKind.Data { chunk = &layout.data.data[row]; }
        if work.kind == WasmSymbolKind.Global {
            var global = &object.globals.data[row];
            if !global.imported && global.expression.length != 0 {
                var opcode = convert(WasmOpcode, global.expression.data[0]);
                if opcode == WasmOpcode.GlobalGet || opcode == WasmOpcode.RefFunc {
                    return wasm_link_fail(link, WasmLinkError.Unsupported, wasm_text_bytes("referential global initializer"));
                }
            }
        }
        if chunk == null { continue; }
        for (var at: usize = 0; at < chunk.relocation_count; at++) {
            var relocation = &object.relocations.data[convert(usize, layout.relocations.data[chunk.relocation_first + at])];
            var kind = convert(WasmRelocation, relocation.kind);
            if kind == WasmRelocation.TypeIndexLeb { continue; }
            var index = layout.symbols.data[convert(usize, relocation.index)];
            if !wasm_link_mark(link, index) { return false; }
            var symbol = &link.symbols.data[convert(usize, index)];
            if wasm_link_table_relocation(kind) {
                if symbol.kind != convert(u8, WasmSymbolKind.Function) { return wasm_link_fail(link, WasmLinkError.Signature, symbol.name); }
                symbol.needs_table = true; link.table_live = true;
            }
            if kind == WasmRelocation.GlobalIndexLeb || kind == WasmRelocation.GlobalIndexI32 {
                if symbol.kind != convert(u8, WasmSymbolKind.Global) { symbol.needs_global = true; }
                if symbol.kind == convert(u8, WasmSymbolKind.Function) { symbol.needs_table = true; link.table_live = true; }
            }
        }
    }
    foreach (var & symbol in &link.symbols) {
        if !symbol.live || symbol.defined { continue; }
        if symbol.weak {
            if symbol.kind == convert(u8, WasmSymbolKind.Function) {
                symbol.defined = true; symbol.synthetic = WasmSynthetic.SignatureTrap;
                symbol.definition = init(WasmSymbolReference) { object: WasmNoIndex, symbol: WasmNoIndex };
            }
            if symbol.kind == convert(u8, WasmSymbolKind.Function) || symbol.kind == convert(u8, WasmSymbolKind.Data) { continue; }
        }
        var permitted = symbol.explicit_import || link.allow_undefined || wasm_names_get(&link.allowed, symbol.name) != WasmNoIndex;
        if !permitted { return wasm_link_fail(link, WasmLinkError.Undefined, symbol.name); }
        if symbol.kind != convert(u8, WasmSymbolKind.Function) && symbol.kind != convert(u8, WasmSymbolKind.Global) {
            return wasm_link_fail(link, WasmLinkError.Unsupported, symbol.name);
        }
    }
    return true;
}

import tower;
import wasm_bytes;
import wasm_object_types;
import wasm_link_types;
import wasm_object_linking;
import .library.bytes_interface;
import .library.bytes_types;

// Static wasm32 shared memory. Object layout components supply the same final
// addresses and segment indices used by relocation/data emission. The host must
// dedicate these ranges and initially zero the aligned synchronization word.
fn wasm_memory_opcode(body: ByteBuffer*, opcode: WasmOpcode): bool {
    return bytes_push(body, convert(u8, opcode));
}

fn wasm_memory_const(body: ByteBuffer*, value: u64): bool {
    return wasm_memory_opcode(body, WasmOpcode.I32Const)
        && wasm_write_sleb(body, convert(i64, bits(i32, convert(u32, value))));
}

fn wasm_memory_atomic(body: ByteBuffer*, opcode: WasmAtomicOpcode): bool {
    return wasm_memory_opcode(body, WasmOpcode.Atomic) && wasm_write_uleb(body, convert(u64, opcode))
        && wasm_write_uleb(body, WasmAtomic32Alignment) && wasm_write_uleb(body, 0);
}

fn wasm_memory_block(body: ByteBuffer*, opcode: WasmOpcode): bool {
    return wasm_memory_opcode(body, opcode) && bytes_push(body, WasmEmptyBlock);
}

fn wasm_emit_memory_init(link: WasmLink*, body: ByteBuffer*): bool {
    if !link.shared_memory {
        return wasm_write_uleb(body, 0) && wasm_memory_init_tls_call(link, body) && wasm_memory_opcode(body, WasmOpcode.End);
    }
    // No locals or stack memory: each instance has its own globals but all
    // instances arbitrate initialization through this shared atomic word.
    if !wasm_write_uleb(body, 0) || !wasm_memory_const(body, link.memory_init_flag)
        || !wasm_memory_const(body, convert(u64, WasmMemoryInitState.Uninitialized))
        || !wasm_memory_const(body, convert(u64, WasmMemoryInitState.Initializing))
        || !wasm_memory_atomic(body, WasmAtomicOpcode.I32CompareExchange)
        || !wasm_memory_opcode(body, WasmOpcode.I32Eqz) || !wasm_memory_block(body, WasmOpcode.If) { return false; }
    for (var input: usize = 0; input < link.world.objects.length; input++) {
        var object = link.world.objects.data[input].object;
        var layout = link.layouts.data[input];
        for (var row: usize = 0; row < object.data.length; row++) {
            var chunk = &layout.data.data[row];
            if !chunk.live || chunk.tls { continue; }
            if !wasm_memory_const(body, chunk.address) || !wasm_memory_const(body, 0)
                || !wasm_memory_const(body, convert(u64, object.data.data[row].bytes.length))
                || !wasm_memory_opcode(body, WasmOpcode.BulkMemory) || !wasm_write_uleb(body, convert(u64, WasmBulkOpcode.MemoryInit))
                || !wasm_write_uleb(body, convert(u64, chunk.output_index)) || !wasm_write_uleb(body, 0) { return false; }
        }
    }
    if !wasm_memory_init_tls_call(link, body) { return false; }
    var all_waiters: u64 = convert(u64, ~convert(u32, 0));
    if !wasm_memory_const(body, link.memory_init_flag) || !wasm_memory_const(body, convert(u64, WasmMemoryInitState.Ready))
        || !wasm_memory_atomic(body, WasmAtomicOpcode.I32Store)
        || !wasm_memory_const(body, link.memory_init_flag) || !wasm_memory_const(body, all_waiters)
        || !wasm_memory_atomic(body, WasmAtomicOpcode.Notify) || !wasm_memory_opcode(body, WasmOpcode.Drop)
        || !wasm_memory_opcode(body, WasmOpcode.Else)
        || !wasm_memory_block(body, WasmOpcode.Block) || !wasm_memory_block(body, WasmOpcode.Loop) { return false; }
    // Recheck after every wake. An unrelated notify at this address must not
    // expose partially initialized data. Waiting may block only in a worker.
    var done_depth: u64 = 1;
    var retry_depth: u64 = 0;
    var wait_forever: i64 = -1;
    if !wasm_memory_const(body, link.memory_init_flag) || !wasm_memory_atomic(body, WasmAtomicOpcode.I32Load)
        || !wasm_memory_const(body, convert(u64, WasmMemoryInitState.Ready)) || !wasm_memory_opcode(body, WasmOpcode.I32Eq)
        || !wasm_memory_opcode(body, WasmOpcode.BranchIf) || !wasm_write_uleb(body, done_depth)
        || !wasm_memory_const(body, link.memory_init_flag) || !wasm_memory_const(body, convert(u64, WasmMemoryInitState.Initializing))
        || !wasm_memory_opcode(body, WasmOpcode.I64Const) || !wasm_write_sleb(body, wait_forever)
        || !wasm_memory_atomic(body, WasmAtomicOpcode.Wait32) || !wasm_memory_opcode(body, WasmOpcode.Drop)
        || !wasm_memory_opcode(body, WasmOpcode.Branch) || !wasm_write_uleb(body, retry_depth)
        || !wasm_memory_opcode(body, WasmOpcode.End) || !wasm_memory_opcode(body, WasmOpcode.End)
        || !wasm_memory_opcode(body, WasmOpcode.End) { return false; }
    // TLS templates remain available for every later __wasm_init_tls call.
    foreach (var layout in &link.layouts) { foreach (var & chunk in &layout.data) {
        if !chunk.live || chunk.tls { continue; }
        if !wasm_memory_opcode(body, WasmOpcode.BulkMemory) || !wasm_write_uleb(body, convert(u64, WasmBulkOpcode.DataDrop))
            || !wasm_write_uleb(body, convert(u64, chunk.output_index)) { return false; }
    } }
    return wasm_memory_opcode(body, WasmOpcode.End);
}

fn wasm_memory_init_tls_call(link: WasmLink*, body: ByteBuffer*): bool {
    if link.tls_init_symbol == WasmNoIndex { return true; }
    return wasm_memory_const(body, link.tls_base) && wasm_memory_opcode(body, WasmOpcode.Call)
        && wasm_write_uleb(body, convert(u64, link.symbols.data[convert(usize, link.tls_init_symbol)].output_index));
}

fn wasm_tls_address(link: WasmLink*, body: ByteBuffer*, offset: u64): bool {
    return wasm_memory_opcode(body, WasmOpcode.GlobalGet)
        && wasm_write_uleb(body, convert(u64, link.symbols.data[convert(usize, link.tls_base_symbol)].output_index))
        && wasm_memory_const(body, offset & convert(u64, WasmNoIndex)) && wasm_memory_opcode(body, WasmOpcode.I32Add);
}

fn wasm_emit_tls_init(link: WasmLink*, body: ByteBuffer*): bool {
    if !wasm_write_uleb(body, 0) || !wasm_memory_opcode(body, WasmOpcode.LocalGet) || !wasm_write_uleb(body, 0)
        || !wasm_memory_opcode(body, WasmOpcode.GlobalSet)
        || !wasm_write_uleb(body, convert(u64, link.symbols.data[convert(usize, link.tls_base_symbol)].output_index)) { return false; }
    // Clear alignment gaps as well as .tbss. Caller owns a suitably aligned,
    // disjoint region of at least __tls_size bytes for this instance.
    if link.tls_size != 0 && (!wasm_tls_address(link, body, 0) || !wasm_memory_const(body, 0) || !wasm_memory_const(body, link.tls_size)
        || !wasm_memory_opcode(body, WasmOpcode.BulkMemory) || !wasm_write_uleb(body, convert(u64, WasmBulkOpcode.MemoryFill)) || !wasm_write_uleb(body, 0)) { return false; }
    for (var input: usize = 0; input < link.world.objects.length; input++) {
        var object = link.world.objects.data[input].object;
        var layout = link.layouts.data[input];
        for (var row: usize = 0; row < object.data.length; row++) {
            var chunk = &layout.data.data[row];
            if !chunk.live || !chunk.tls { continue; }
            var data = &object.data.data[row];
            if !wasm_tls_address(link, body, chunk.address - link.tls_base) || !wasm_memory_const(body, 0)
                || !wasm_memory_const(body, convert(u64, data.bytes.length)) || !wasm_memory_opcode(body, WasmOpcode.BulkMemory)
                || !wasm_write_uleb(body, convert(u64, WasmBulkOpcode.MemoryInit)) || !wasm_write_uleb(body, convert(u64, chunk.output_index))
                || !wasm_write_uleb(body, 0) { return false; }
            for (var at: usize = 0; at < chunk.relocation_count; at++) {
                var relocation = &object.relocations.data[convert(usize, layout.relocations.data[chunk.relocation_first + at])];
                if relocation.kind != convert(u32, WasmRelocation.MemoryAddressI32) { continue; }
                var symbol = &link.symbols.data[convert(usize, layout.symbols.data[convert(usize, relocation.index)])];
                if !symbol.tls { continue; }
                var destination = chunk.address - link.tls_base + convert(u64, relocation.offset - data.section_offset);
                var value = symbol.address - link.tls_base + bits(u64, relocation.addend);
                if !wasm_tls_address(link, body, destination) || !wasm_tls_address(link, body, value)
                    || !wasm_memory_opcode(body, WasmOpcode.I32Store) || !wasm_write_uleb(body, 0) || !wasm_write_uleb(body, 0) { return false; }
            }
        }
    }
    foreach (var & symbol in &link.symbols) {
        if !symbol.live || !symbol.tls || symbol.got_index == WasmNoIndex { continue; }
        if !wasm_tls_address(link, body, symbol.address - link.tls_base) || !wasm_memory_opcode(body, WasmOpcode.GlobalSet)
            || !wasm_write_uleb(body, convert(u64, symbol.got_index)) { return false; }
    }
    return wasm_memory_opcode(body, WasmOpcode.End);
}

import tower;
import wasm_bytes;
import wasm_names;
import wasm_object_types;
import wasm_link_world;
import wasm_link_types;
import .library.bytes_interface;
import .library.bytes_types;

// Incremental argument decoding has no transport. A caller supplies the bytes
// requested by an action from explicit inputs or its own filesystem boundary.
enum WasmOptionPending: u8 { None = 0, Output = 1, Stack = 2 }
enum WasmOptionAction: u8 { None = 0, Object = 1, AllowedNames = 2, ExportNames = 3 }
struct WasmLinkOptions { pending: WasmOptionPending; whole_archive: bool; output: WasmBytes; has_input: bool; }
struct WasmLinkOption { action: WasmOptionAction; name: WasmBytes; whole_archive: bool; }

fn wasm_option_prefix(text: WasmBytes, prefix: u8*): bool {
    var begin = wasm_text_bytes(prefix);
    return text.length >= begin.length && wasm_bytes_equal(init(WasmBytes) { data: text.data, length: begin.length }, begin);
}

fn wasm_option_suffix(text: WasmBytes, prefix: u8*): WasmBytes {
    var length = wasm_text_bytes(prefix).length;
    return init(WasmBytes) { data: text.data + length, length: text.length - length };
}

fn wasm_option_number(text: WasmBytes, output: u64*): bool {
    var zero: u8 = 48;
    var nine: u8 = 57;
    var decimal: u64 = 10;
    var value: u64 = 0;
    if text.length == 0 { return false; }
    for (var at: usize = 0; at < text.length; at++) {
        var digit = text.data[at];
        if digit < zero || digit > nine { return false; }
        var next = convert(u64, digit - zero);
        if value > (~convert(u64, 0) - next) / decimal { return false; }
        value = value * decimal + next;
    }
    *output = value; return true;
}

fn wasm_option_names(link: WasmLink*, text: WasmBytes, exports: bool): bool {
    var line_feed: u8 = 10;
    var space: u8 = 32;
    var comment: u8 = 35;
    for (var at: usize = 0; at < text.length;) {
        var first = at;
        while at < text.length && text.data[at] != line_feed { at++; }
        var last = at;
        for (var next = first; next < last; next++) { if text.data[next] == comment { last = next; break; } }
        while first < last && text.data[first] <= space { first++; }
        while last > first && text.data[last - 1] <= space { last--; }
        if last > first {
            var name: WasmBytes = { data: text.data + first, length: last - first };
            if exports {
                var request: WasmExportRequest = { name: name, required: false };
                if !wasm_link_push(link, &link.exports, request) { return false; }
            } else {
                if !wasm_names_set(&link.allowed, name, 0) { return wasm_link_fail(link, WasmLinkError.Allocation, name); }
            }
        }
        if at < text.length { at++; }
    }
    return true;
}

fn wasm_option_wrap_name(link: WasmLink*, prefix: u8*, name: WasmBytes, output: WasmBytes*): bool {
    var bytes: ByteBuffer = default;
    var start = wasm_text_bytes(prefix);
    if !bytes_append(&bytes, start.data, start.length) || !bytes_append(&bytes, name.data, name.length) {
        bytes_dispose(&bytes); return wasm_link_fail(link, WasmLinkError.Allocation, name);
    }
    if !wasm_link_push(link, &link.owned, bytes) { bytes_dispose(&bytes); return false; }
    *output = init(WasmBytes) { data: bytes.data, length: bytes.length };
    return true;
}

fn wasm_link_option(link: WasmLink*, options: WasmLinkOptions*, argument: WasmBytes, item: WasmLinkOption*): bool {
    *item = default;
    if link.started || link.error != WasmLinkError.None { return wasm_link_fail(link, WasmLinkError.Input, argument); }
    if options.pending == WasmOptionPending.Output {
        if argument.length == 0 { return wasm_link_fail(link, WasmLinkError.Input, argument); }
        options.output = argument; options.pending = WasmOptionPending.None; return true;
    }
    if options.pending == WasmOptionPending.Stack {
        options.pending = WasmOptionPending.None;
        if !wasm_option_prefix(argument, "stack-size=") { return wasm_link_fail(link, WasmLinkError.Unsupported, argument); }
        if !wasm_option_number(wasm_option_suffix(argument, "stack-size="), &link.stack_size) { return wasm_link_fail(link, WasmLinkError.Input, argument); }
        return true;
    }
    if wasm_bytes_text(argument, "-o") { options.pending = WasmOptionPending.Output; return true; }
    if wasm_bytes_text(argument, "-z") { options.pending = WasmOptionPending.Stack; return true; }
    if wasm_option_prefix(argument, "--threads=") {
        var count: u64 = 0;
        if !wasm_option_number(wasm_option_suffix(argument, "--threads="), &count) || count == 0 || count > convert(u64, WasmLinkMaximumWorkers) {
            return wasm_link_fail(link, WasmLinkError.Input, argument);
        }
        link.workers = convert(usize, count); return true;
    }
    if wasm_bytes_text(argument, "--no-entry") || wasm_bytes_text(argument, "--strip-all") || wasm_bytes_text(argument, "--threads=1") { return true; }
    if wasm_bytes_text(argument, "--whole-archive") { options.whole_archive = true; return true; }
    if wasm_bytes_text(argument, "--no-whole-archive") { options.whole_archive = false; return true; }
    if wasm_bytes_text(argument, "--export-memory") { link.export_memory = true; return true; }
    if wasm_bytes_text(argument, "--shared-memory") { link.shared_memory = true; return true; }
    if wasm_bytes_text(argument, "--import-memory") {
        link.import_memory = true; link.memory_module = wasm_text_bytes("env"); link.memory_name = wasm_text_bytes("memory"); return true;
    }
    if wasm_option_prefix(argument, "--import-memory=") {
        var name = wasm_option_suffix(argument, "--import-memory=");
        var comma: u8 = 44;
        var separator = name.length;
        for (var at: usize = 0; at < name.length; at++) {
            if name.data[at] == comma {
                if separator != name.length { return wasm_link_fail(link, WasmLinkError.Input, argument); }
                separator = at;
            }
        }
        if separator == name.length { return wasm_link_fail(link, WasmLinkError.Input, argument); }
        link.import_memory = true;
        link.memory_module = init(WasmBytes) { data: name.data, length: separator };
        link.memory_name = init(WasmBytes) { data: name.data + separator + 1, length: name.length - separator - 1 };
        return true;
    }
    if wasm_bytes_text(argument, "--export-table") { link.export_table = true; return true; }
    if wasm_bytes_text(argument, "--stack-first") { link.stack_first = true; return true; }
    if wasm_bytes_text(argument, "--debug-names") { link.emit_names = true; return true; }
    if wasm_bytes_text(argument, "--allow-undefined") { link.allow_undefined = true; return true; }
    if wasm_bytes_text(argument, "--no-gc-sections") { link.garbage_collect = false; return true; }
    if wasm_option_prefix(argument, "--export=") || wasm_option_prefix(argument, "--export-if-defined=") {
        var required = wasm_option_prefix(argument, "--export=");
        var request: WasmExportRequest = { name: wasm_option_suffix(argument, required ? "--export=" : "--export-if-defined="), required: required };
        if request.name.length == 0 { return wasm_link_fail(link, WasmLinkError.Input, argument); }
        return wasm_link_push(link, &link.exports, request);
    }
    if wasm_option_prefix(argument, "--wrap=") {
        var wrap: WasmWrapRequest = { name: wasm_option_suffix(argument, "--wrap="), ..default };
        if wrap.name.length == 0 { return wasm_link_fail(link, WasmLinkError.Input, argument); }
        return wasm_option_wrap_name(link, "__wrap_", wrap.name, &wrap.wrapper) && wasm_option_wrap_name(link, "__real_", wrap.name, &wrap.real)
            && wasm_link_push(link, &link.wraps, wrap);
    }
    if wasm_option_prefix(argument, "--allow-undefined-file=") {
        *item = init(WasmLinkOption) { action: WasmOptionAction.AllowedNames, name: wasm_option_suffix(argument, "--allow-undefined-file="), ..default }; return true;
    }
    if wasm_option_prefix(argument, "--export-if-defined-list=") {
        *item = init(WasmLinkOption) { action: WasmOptionAction.ExportNames, name: wasm_option_suffix(argument, "--export-if-defined-list="), ..default }; return true;
    }
    if wasm_option_prefix(argument, "--initial-memory=") {
        return wasm_option_number(wasm_option_suffix(argument, "--initial-memory="), &link.initial_memory) || wasm_link_fail(link, WasmLinkError.Input, argument);
    }
    if wasm_option_prefix(argument, "--max-memory=") {
        return wasm_option_number(wasm_option_suffix(argument, "--max-memory="), &link.maximum_memory) || wasm_link_fail(link, WasmLinkError.Input, argument);
    }
    var dash: u8 = 45;
    if argument.length == 0 || argument.data[0] == dash { return wasm_link_fail(link, WasmLinkError.Unsupported, argument); }
    *item = init(WasmLinkOption) { action: WasmOptionAction.Object, name: argument, whole_archive: options.whole_archive };
    options.has_input = true;
    return true;
}

fn wasm_link_option_bytes(link: WasmLink*, item: WasmLinkOption*, input: WasmBytes): bool {
    if item.action == WasmOptionAction.AllowedNames || item.action == WasmOptionAction.ExportNames {
        return wasm_option_names(link, input, item.action == WasmOptionAction.ExportNames);
    }
    if item.action != WasmOptionAction.Object { return wasm_link_fail(link, WasmLinkError.Input, item.name); }
    var archive_magic: u8 = 33;
    var archive_magic_bytes: usize = 8;
    var archive = input.length >= archive_magic_bytes && input.data[0] == archive_magic;
    var ok = true;
    if archive { ok = item.whole_archive ? wasm_link_read_archive(&link.world, item.name, input) : wasm_link_add_archive(&link.world, item.name, input); }
    else { ok = wasm_link_read_object(&link.world, item.name, input); }
    return ok || wasm_link_fail(link, WasmLinkError.Input, link.world.error_input);
}

fn wasm_link_options_finish(link: WasmLink*, options: WasmLinkOptions*): bool {
    if options.pending != WasmOptionPending.None { return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("missing linker option value")); }
    if !options.has_input { return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("provide input objects or archives")); }
    return link.error == WasmLinkError.None;
}

import tower;
import wasm_bytes;
import wasm_names;
import wasm_object_types;
import wasm_link_types;
import wasm_link_options;
import wasm_link;

struct WasmLinkInputBytes { name: WasmBytes; bytes: WasmBytes; }

// Borrow all argument/input bytes until wasm_link_close. Arguments omit the
// tool name. Input names are exact byte keys, never paths to open. This service
// performs no filesystem access, host callbacks or implicit native fallback.
fn wasm_link_plan(link: WasmLink*, arguments: WasmBytes*, count: usize, inputs: WasmLinkInputBytes*, input_count: usize): bool {
    if link.started || link.layout_type != null {
        link.output.length = 0;
        return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("link requests are single use"));
    }
    var names: WasmNameMap = default;
    defer wasm_names_dispose(&names);
    if input_count >= convert(usize, WasmNoIndex) { return wasm_link_fail(link, WasmLinkError.Layout, default(WasmBytes)); }
    for (var at: usize = 0; at < input_count; at++) {
        var name = inputs[at].name;
        if wasm_names_get(&names, name) != WasmNoIndex { return wasm_link_fail(link, WasmLinkError.Duplicate, name); }
        if !wasm_names_set(&names, name, convert(u32, at)) { return wasm_link_fail(link, WasmLinkError.Allocation, name); }
    }
    var options: WasmLinkOptions = default;
    for (var at: usize = 0; at < count; at++) {
        var item: WasmLinkOption = default;
        if !wasm_link_option(link, &options, arguments[at], &item) { return false; }
        if item.action == WasmOptionAction.None { continue; }
        var index = wasm_names_get(&names, item.name);
        if index == WasmNoIndex { return wasm_link_fail(link, WasmLinkError.Input, item.name); }
        if !wasm_link_option_bytes(link, &item, inputs[convert(usize, index)].bytes) { return false; }
    }
    return wasm_link_options_finish(link, &options) && wasm_link_run(link);
}

import tower;
import wasm_bytes;
import wasm_names;
import wasm_object_types;
import wasm_link_world;
import wasm_link_types;
import .library.vector;
import .library.bytes_interface;
import .library.bytes_types;
import .library.entity_api;

fn wasm_link_close(link: WasmLink*): bool {
    if link.world.store != null && link.world.store.views != 0 { return false; }
    foreach (var layout in &link.layouts) { wasm_link_object_layout_dispose(layout); }
    vector_dispose(&link.layouts);
    wasm_names_dispose(&link.names); wasm_names_dispose(&link.type_names);
    wasm_names_dispose(&link.comdat_names); wasm_names_dispose(&link.allowed);
    wasm_names_dispose(&link.variants); vector_dispose(&link.warnings);
    wasm_names_dispose(&link.feature_names); vector_dispose(&link.features);
    vector_dispose(&link.symbols); vector_dispose(&link.types);
    vector_dispose(&link.exports); vector_dispose(&link.wraps);
    vector_dispose(&link.functions); vector_dispose(&link.globals);
    vector_dispose(&link.output_exports); vector_dispose(&link.table_functions);
    vector_dispose(&link.pending); vector_dispose(&link.initializers);
    bytes_dispose(&link.output);
    if link.layout_type != null { entity_release(link.layout_type); link.layout_type = null; }
    if !wasm_link_world_close(&link.world) { return false; }
    foreach (var & owned in &link.owned) { bytes_dispose(owned); }
    vector_dispose(&link.owned);
    *link = default;
    return true;
}

fn wasm_link_chunks(link: WasmLink*, chunks: vector(WasmChunkLayout)*, count: usize): bool {
    if !vector_reserve(chunks, count) { return wasm_link_fail(link, WasmLinkError.Allocation, default(WasmBytes)); }
    for (var at: usize = 0; at < count; at++) { chunks.data[at] = init(WasmChunkLayout) { output_index: WasmNoIndex, ..default }; }
    chunks.length = count;
    return true;
}

fn wasm_link_type(link: WasmLink*, type: WasmFunctionTypeRecord*): u32 {
    // LLVM normally emits canonical counts. A known byte spelling can reuse
    // the interned row without allocating and normalizing another temporary.
    var index = wasm_names_get(&link.type_names, type.bytes);
    if index != WasmNoIndex { return index; }
    var source: WasmReader = { bytes: type.bytes, ..default };
    var canonical: ByteBuffer = default;
    defer bytes_dispose(&canonical);
    var ok = bytes_push(&canonical, wasm_read_byte(&source));
    var parameters = wasm_read_index(&source);
    var values = wasm_read_bytes(&source, convert(usize, parameters));
    ok &&= wasm_write_uleb(&canonical, convert(u64, parameters)) && bytes_append(&canonical, values.data, values.length);
    var results = wasm_read_index(&source);
    values = wasm_read_bytes(&source, convert(usize, results));
    ok &&= wasm_write_uleb(&canonical, convert(u64, results)) && bytes_append(&canonical, values.data, values.length);
    if !ok { wasm_link_fail(link, WasmLinkError.Allocation, default(WasmBytes)); return WasmNoIndex; }
    var key: WasmBytes = { data: canonical.data, length: canonical.length };
    index = wasm_names_get(&link.type_names, key);
    if index != WasmNoIndex { return index; }
    if link.types.length >= convert(usize, WasmNoIndex) { wasm_link_fail(link, WasmLinkError.Layout, key); return WasmNoIndex; }
    index = convert(u32, link.types.length);
    if !wasm_link_push(link, &link.owned, canonical) { return WasmNoIndex; }
    canonical = default;
    if !wasm_link_push(link, &link.types, key) || !wasm_names_set(&link.type_names, key, index) {
        wasm_link_fail(link, WasmLinkError.Allocation, default(WasmBytes)); return WasmNoIndex;
    }
    return index;
}

fn wasm_link_shared_features(link: WasmLink*): bool {
    if !link.shared_memory && !link.has_tls { return true; }
    if link.shared_memory && link.maximum_memory == 0 { return wasm_link_fail(link, WasmLinkError.Layout, wasm_text_bytes("shared memory requires a maximum")); }
    var atomics = wasm_names_get(&link.feature_names, wasm_text_bytes("atomics"));
    var bulk = wasm_names_get(&link.feature_names, wasm_text_bytes("bulk-memory"));
    var shared = wasm_names_get(&link.feature_names, wasm_text_bytes("shared-mem"));
    if link.shared_memory && shared != WasmNoIndex && link.features.data[convert(usize, shared)].prefix == convert(u8, WasmFeaturePrefix.Disallowed) {
        return wasm_link_fail(link, WasmLinkError.Unsupported, wasm_text_bytes("shared-mem is disallowed by an input"));
    }
    if atomics == WasmNoIndex || link.features.data[convert(usize, atomics)].prefix == convert(u8, WasmFeaturePrefix.Disallowed) {
        return wasm_link_fail(link, WasmLinkError.Unsupported, wasm_text_bytes("shared memory requires atomics"));
    }
    if bulk == WasmNoIndex || link.features.data[convert(usize, bulk)].prefix == convert(u8, WasmFeaturePrefix.Disallowed) {
        return wasm_link_fail(link, WasmLinkError.Unsupported, wasm_text_bytes("shared memory requires bulk-memory"));
    }
    return true;
}

fn wasm_link_prepare(link: WasmLink*): bool {
    if link.layout_type != null { return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("link request already prepared")); }
    if link.import_memory && (!wasm_bytes_utf8(link.memory_module) || !wasm_bytes_utf8(link.memory_name)) {
        return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("memory import names require UTF-8"));
    }
    if !wasm_link_collect_errors(&link.world) { return wasm_link_fail(link, WasmLinkError.Input, link.world.error_input); }
    link.layout_type = entity_create(link.world.store);
    if link.layout_type == null || !entity_register(link.layout_type, sizeof(WasmObjectLayout), alignof(WasmObjectLayout), 0) {
        return wasm_link_fail(link, WasmLinkError.Allocation, default(WasmBytes));
    }
    foreach (var & entry in &link.world.objects) {
        var object = entry.object;
        foreach (var & feature in &object.features) {
            var index = wasm_names_get(&link.feature_names, feature.name);
            if index == WasmNoIndex {
                index = convert(u32, link.features.length);
                if !wasm_names_set(&link.feature_names, feature.name, index) || !wasm_link_push(link, &link.features, *feature) {
                    return wasm_link_fail(link, WasmLinkError.Allocation, feature.name);
                }
            } else {
                var previous = &link.features.data[convert(usize, index)];
                if previous.prefix != feature.prefix {
                    if previous.prefix == convert(u8, WasmFeaturePrefix.Disallowed) || feature.prefix == convert(u8, WasmFeaturePrefix.Disallowed) {
                        return wasm_link_fail(link, WasmLinkError.Input, feature.name);
                    }
                    previous.prefix = convert(u8, WasmFeaturePrefix.Required);
                }
            }
        }
        if object.memories.length > 1 || object.tables.length > 1 || object.tags.length != 0 || object.start != WasmNoIndex {
            return wasm_link_fail(link, WasmLinkError.Unsupported, entry.name);
        }
        foreach (var & memory in &object.memories) {
            var unsupported = convert(u32, WasmLimitFlag.Memory64);
            if !link.shared_memory { unsupported |= convert(u32, WasmLimitFlag.Shared); }
            if (memory.limits.flags & unsupported) != 0 { return wasm_link_fail(link, WasmLinkError.Unsupported, entry.name); }
        }
        foreach (var & table in &object.tables) {
            if table.type != convert(u8, WasmValueType.FuncRef) || (table.limits.flags & ~convert(u32, WasmLimitFlag.Maximum)) != 0 {
                return wasm_link_fail(link, WasmLinkError.Unsupported, entry.name);
            }
        }
        foreach (var & data in &object.data) {
            var supported_flags = convert(u32, WasmSegmentFlag.Strings) | convert(u32, WasmSegmentFlag.Retain) | convert(u32, WasmSegmentFlag.ThreadLocal);
            if data.passive || (data.flags & ~supported_flags) != 0 || data.memory != 0 { return wasm_link_fail(link, WasmLinkError.Unsupported, entry.name); }
            if (data.flags & convert(u32, WasmSegmentFlag.ThreadLocal)) != 0 { link.has_tls = true; }
        }
        foreach (var & symbol in &object.symbols) {
            if symbol.kind == convert(u8, WasmSymbolKind.Data) && (symbol.flags & convert(u32, WasmSymbolFlag.Undefined)) == 0 {
                var tls = (symbol.flags & convert(u32, WasmSymbolFlag.ThreadLocal)) != 0;
                if tls != ((object.data.data[convert(usize, symbol.index)].flags & convert(u32, WasmSegmentFlag.ThreadLocal)) != 0) {
                    return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("TLS symbol and segment disagree"));
                }
            }
        }
        var component = entity_component_add(entry.node, link.layout_type);
        if component == null { return wasm_link_fail(link, WasmLinkError.Allocation, entry.name); }
        var layout = bits(WasmObjectLayout*, entity_component_data(component));
        *layout = default;
        if !wasm_link_push(link, &link.layouts, layout) { return false; }
        var ok = wasm_link_chunks(link, &layout.functions, object.functions.length)
            && wasm_link_chunks(link, &layout.globals, object.globals.length)
            && wasm_link_chunks(link, &layout.tables, object.tables.length)
            && wasm_link_chunks(link, &layout.tags, object.tags.length)
            && wasm_link_chunks(link, &layout.data, object.data.length);
        if !ok { return false; }
        for (var row: usize = 0; row < object.data.length; row++) {
            layout.data.data[row].tls = (object.data.data[row].flags & convert(u32, WasmSegmentFlag.ThreadLocal)) != 0;
        }
        foreach (var & type in &object.types) {
            var index = wasm_link_type(link, type);
            if index == WasmNoIndex || !wasm_link_push(link, &layout.types, index) { return false; }
        }
    }
    return wasm_link_shared_features(link);
}

fn wasm_link_message(error: WasmLinkError): u8* {
    match error {
        WasmLinkError.None => { return "success"; }
        WasmLinkError.Allocation => { return "Wasm linker allocation failed"; }
        WasmLinkError.Duplicate => { return "duplicate Wasm symbol"; }
        WasmLinkError.Signature => { return "incompatible Wasm symbol signatures"; }
        WasmLinkError.Undefined => { return "undefined Wasm symbol"; }
        WasmLinkError.Unsupported => { return "unsupported Wasm link feature"; }
        WasmLinkError.Layout => { return "Wasm output layout exceeds target limits"; }
        WasmLinkError.Input => { return "invalid Wasm linker input"; }
        _ => { return "unknown Wasm linker error"; }
    }
}

import tower;
import wasm_bytes;
import wasm_object_types;
import wasm_object_linking;
import wasm_link_types;

fn wasm_link_relocation_value(link: WasmLink*, input: usize, relocation: WasmRelocationRecord*, place: u64): u64 {
    var layout = link.layouts.data[input];
    var kind = convert(WasmRelocation, relocation.kind);
    if kind == WasmRelocation.TypeIndexLeb { return convert(u64, layout.types.data[convert(usize, relocation.index)]); }
    var symbol = &link.symbols.data[convert(usize, layout.symbols.data[convert(usize, relocation.index)])];
    var required_kind = WasmSymbolKind.Data;
    var value: u64 = 0;
    match kind {
        WasmRelocation.FunctionIndexLeb | WasmRelocation.FunctionIndexI32 => {
            required_kind = WasmSymbolKind.Function; value = convert(u64, symbol.output_index);
        }
        WasmRelocation.TableIndexSleb | WasmRelocation.TableIndexI32 | WasmRelocation.TableIndexSleb64 | WasmRelocation.TableIndexI64 => {
            required_kind = WasmSymbolKind.Function; value = convert(u64, symbol.table_index);
        }
        WasmRelocation.TableIndexRelativeSleb | WasmRelocation.TableIndexRelativeSleb64 => {
            required_kind = WasmSymbolKind.Function;
            value = symbol.table_index == 0 ? 0 : convert(u64, symbol.table_index - WasmTableBase);
        }
        WasmRelocation.GlobalIndexLeb | WasmRelocation.GlobalIndexI32 => {
            var index = symbol.kind == convert(u8, WasmSymbolKind.Global) ? symbol.output_index : symbol.got_index;
            if index == WasmNoIndex { wasm_link_fail(link, WasmLinkError.Layout, symbol.name); }
            return convert(u64, index);
        }
        WasmRelocation.TableNumberLeb => { required_kind = WasmSymbolKind.Table; value = convert(u64, symbol.output_index); }
        WasmRelocation.MemoryAddressLeb | WasmRelocation.MemoryAddressSleb | WasmRelocation.MemoryAddressI32
        | WasmRelocation.MemoryAddressRelativeSleb | WasmRelocation.MemoryAddressLeb64 | WasmRelocation.MemoryAddressSleb64
        | WasmRelocation.MemoryAddressI64 | WasmRelocation.MemoryAddressRelativeSleb64 => {
            // Static images have memory base zero, including PIC input chunks.
            // Undefined weak data addresses stay null regardless of the addend.
            value = symbol.defined ? symbol.address + bits(u64, relocation.addend) : 0;
            if symbol.tls {
                // Absolute TLS pointers are fixed up in each copied TLS block.
                // A shared ordinary data/code location cannot hold one address
                // that is correct for every instance.
                var data = link.world.objects.data[input].object.sections.data[convert(usize, relocation.section)].kind == convert(u8, WasmSection.Data);
                if data && kind == WasmRelocation.MemoryAddressI32 && place >= link.tls_base && place < link.tls_base + link.tls_size {
                    var offset = symbol.address - link.tls_base + bits(u64, relocation.addend);
                    var signed_minimum = ~convert(u64, WasmNoIndex >> 1);
                    if offset > convert(u64, WasmNoIndex) && offset < signed_minimum {
                        wasm_link_fail(link, WasmLinkError.Layout, wasm_text_bytes("32-bit TLS relocation overflow"));
                    }
                    value = 0;
                } else { if link.shared_memory { wasm_link_fail(link, WasmLinkError.Unsupported, wasm_text_bytes("absolute TLS address outside TLS storage")); } }
            }
        }
        WasmRelocation.MemoryAddressTlsSleb => {
            if !symbol.defined || !symbol.tls { wasm_link_fail(link, WasmLinkError.Signature, wasm_text_bytes("TLS relocation requires a defined TLS symbol")); }
            value = symbol.address - link.tls_base + bits(u64, relocation.addend);
        }
        WasmRelocation.MemoryAddressLocalRelativeI32 => {
            if symbol.tls { wasm_link_fail(link, WasmLinkError.Unsupported, wasm_text_bytes("relative TLS pointer storage")); }
            value = symbol.defined ? symbol.address + bits(u64, relocation.addend) - place : 0;
        }
        _ => { wasm_link_fail(link, WasmLinkError.Unsupported, symbol.name); return 0; }
    }
    if symbol.kind != convert(u8, required_kind) { wasm_link_fail(link, WasmLinkError.Signature, symbol.name); }
    return value;
}

fn wasm_link_relocation_signed(kind: WasmRelocation): bool {
    return kind == WasmRelocation.TableIndexSleb || kind == WasmRelocation.MemoryAddressSleb
        || kind == WasmRelocation.MemoryAddressRelativeSleb || kind == WasmRelocation.TableIndexRelativeSleb
        || kind == WasmRelocation.MemoryAddressSleb64 || kind == WasmRelocation.MemoryAddressRelativeSleb64
        || kind == WasmRelocation.TableIndexSleb64 || kind == WasmRelocation.TableIndexRelativeSleb64
        || kind == WasmRelocation.MemoryAddressTlsSleb || kind == WasmRelocation.MemoryAddressTlsSleb64;
}

fn wasm_link_patch(link: WasmLink*, kind: WasmRelocation, target: WasmBytes, value: u64): bool {
    var width = convert(usize, wasm_relocation_width(kind));
    var fixed32: usize = 4;
    var fixed64: usize = 8;
    var leb32: usize = 5;
    var byte_bits: u64 = 8;
    var byte_mask: u64 = 255;
    if target.length != width { return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("relocation destination")); }
    if width == fixed32 || width == leb32 {
        var signed_minimum = ~convert(u64, WasmNoIndex >> 1);
        if value > convert(u64, WasmNoIndex) && value < signed_minimum {
            return wasm_link_fail(link, WasmLinkError.Layout, wasm_text_bytes("32-bit relocation overflow"));
        }
    }
    if width == fixed32 || width == fixed64 {
        for (var at: usize = 0; at < width; at++) { target.data[at] = convert(u8, (value >> (convert(u64, at) * byte_bits)) & byte_mask); }
        return true;
    }
    var signed = wasm_link_relocation_signed(kind);
    var width_bits: u64 = width == leb32 ? 32 : 64;
    // The old operand's value is unused. Validate the complete padded encoding
    // directly, including unused/sign bits, rather than decoding it first.
    var valid = true;
    for (var at: usize = 0; at + 1 < width; at++) { valid &&= (target.data[at] & WasmLebContinuation) != 0; }
    var last = target.data[width - 1];
    var remaining = width_bits - convert(u64, width - 1) * WasmLebPayloadBits;
    var limit = convert(u8, convert(u64, 1) << (signed ? remaining - 1 : remaining));
    valid &&= last < limit || (signed && last >= WasmLebContinuation - limit && last < WasmLebContinuation);
    if !valid {
        return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("relocation requires a padded LEB operand"));
    }
    if width == leb32 { value &= convert(u64, WasmNoIndex); }
    if signed && width == leb32 { value = bits(u64, convert(i64, bits(i32, convert(u32, value)))); }
    for (var at: usize = 0; at < width; at++) {
        var byte = convert(u8, value & convert(u64, WasmLebPayloadMask));
        value = signed ? bits(u64, bits(i64, value) >> convert(i64, WasmLebPayloadBits)) : value >> WasmLebPayloadBits;
        if at + 1 < width { byte |= WasmLebContinuation; }
        target.data[at] = byte;
    }
    return true;
}

fn wasm_link_relocate(link: WasmLink*, input: usize, chunk: WasmChunkLayout*, original_offset: u32, output: WasmBytes): bool {
    var object = link.world.objects.data[input].object;
    var layout = link.layouts.data[input];
    for (var at: usize = 0; at < chunk.relocation_count; at++) {
        var relocation = &object.relocations.data[convert(usize, layout.relocations.data[chunk.relocation_first + at])];
        var offset = convert(usize, relocation.offset - original_offset);
        var kind = convert(WasmRelocation, relocation.kind);
        var width = convert(usize, wasm_relocation_width(kind));
        if offset > output.length || width > output.length - offset { return wasm_link_fail(link, WasmLinkError.Input, wasm_text_bytes("relocation range")); }
        var value = wasm_link_relocation_value(link, input, relocation, chunk.address + convert(u64, offset));
        if link.error != WasmLinkError.None || !wasm_link_patch(link, kind, init(WasmBytes) { data: output.data + offset, length: width }, value) { return false; }
    }
    return true;
}

import tower;
import wasm_bytes;
import wasm_names;
import wasm_object_types;
import wasm_link_world;
import wasm_link_types;
import .library.vector;
import .library.bytes_interface;
import .library.bytes_types;

fn wasm_link_object_comdats(link: WasmLink*, object: WasmObject*, layout: WasmObjectLayout*, names: WasmNameMap*, owner: u32): bool {
        foreach (var & group in &object.comdats) {
            if wasm_names_get(names, group.name) == WasmNoIndex {
                if !wasm_names_set(names, group.name, owner) {
                    return wasm_link_fail(link, WasmLinkError.Allocation, group.name);
                }
                continue;
            }
            for (var at: usize = 0; at < group.count; at++) {
                var entry = &object.comdat_entries.data[group.first + at];
                var kind = convert(WasmComdatKind, entry.kind);
                var chunks: vector(WasmChunkLayout)* = null;
                match kind {
                    WasmComdatKind.Data => { chunks = &layout.data; }
                    WasmComdatKind.Function => { chunks = &layout.functions; }
                    WasmComdatKind.Global => { chunks = &layout.globals; }
                    WasmComdatKind.Tag => { chunks = &layout.tags; }
                    WasmComdatKind.Table => { chunks = &layout.tables; }
                    WasmComdatKind.Section => { continue; }
                    _ => { return wasm_link_fail(link, WasmLinkError.Input, group.name); }
                }
                if convert(usize, entry.index) >= chunks.length { return wasm_link_fail(link, WasmLinkError.Input, group.name); }
                chunks.data[convert(usize, entry.index)].discarded = true;
            }
        }
    return true;
}

fn wasm_link_comdats(link: WasmLink*): bool {
    for (var index: usize = 0; index < link.world.objects.length; index++) {
        if !wasm_link_object_comdats(link, link.world.objects.data[index].object, link.layouts.data[index], &link.comdat_names, convert(u32, index)) { return false; }
    }
    return true;
}

fn wasm_link_defined_chunk(layout: WasmObjectLayout*, symbol: WasmSymbolRecord*): WasmChunkLayout* {
    if (symbol.flags & convert(u32, WasmSymbolFlag.Undefined)) != 0 { return null; }
    var row = convert(usize, symbol.index);
    match convert(WasmSymbolKind, symbol.kind) {
        WasmSymbolKind.Function => { return &layout.functions.data[row]; }
        WasmSymbolKind.Global => { return &layout.globals.data[row]; }
        WasmSymbolKind.Data => { return &layout.data.data[row]; }
        WasmSymbolKind.Table => { return &layout.tables.data[row]; }
        WasmSymbolKind.Tag => { return &layout.tags.data[row]; }
        _ => { return null; }
    }
}

fn wasm_link_symbol_chunk(link: WasmLink*, reference: WasmSymbolReference): WasmChunkLayout* {
    if reference.object == WasmNoIndex { return null; }
    var index = convert(usize, reference.object);
    var object = link.world.objects.data[index].object;
    var layout = link.layouts.data[index];
    var symbol = &object.symbols.data[convert(usize, reference.symbol)];
    return wasm_link_defined_chunk(layout, symbol);
}

fn wasm_link_signatures(link: WasmLink*, left: WasmSymbolReference, right: WasmSymbolReference): bool {
    if left.object == WasmNoIndex || right.object == WasmNoIndex { return true; }
    var a = link.world.objects.data[convert(usize, left.object)].object;
    var b = link.world.objects.data[convert(usize, right.object)].object;
    var x = &a.symbols.data[convert(usize, left.symbol)];
    var y = &b.symbols.data[convert(usize, right.symbol)];
    if x.kind != y.kind { return false; }
    if x.kind == convert(u8, WasmSymbolKind.Data)
        && ((x.flags ^ y.flags) & convert(u32, WasmSymbolFlag.ThreadLocal)) != 0 { return false; }
    var kind = convert(WasmSymbolKind, x.kind);
    match kind {
        WasmSymbolKind.Function => {
            var xt = a.functions.data[convert(usize, x.index)].type_index;
            var yt = b.functions.data[convert(usize, y.index)].type_index;
            return link.layouts.data[convert(usize, left.object)].types.data[convert(usize, xt)]
                == link.layouts.data[convert(usize, right.object)].types.data[convert(usize, yt)];
        }
        WasmSymbolKind.Global => {
            var ax = &a.globals.data[convert(usize, x.index)];
            var by = &b.globals.data[convert(usize, y.index)];
            var static_base = (wasm_bytes_text(x.name, "__memory_base") || wasm_bytes_text(x.name, "__table_base"))
                && (x.flags & convert(u32, WasmSymbolFlag.Undefined)) != 0 && (y.flags & convert(u32, WasmSymbolFlag.Undefined)) != 0;
            return ax.type == by.type && (ax.mutable == by.mutable || static_base);
        }
        WasmSymbolKind.Table => { return a.tables.data[convert(usize, x.index)].type == b.tables.data[convert(usize, y.index)].type; }
        _ => { return true; }
    }
}

fn wasm_link_symbols(link: WasmLink*): bool {
    if !wasm_link_comdats(link) { return false; }
    for (var input: usize = 0; input < link.world.objects.length; input++) {
        var object = link.world.objects.data[input].object;
        for (var row: usize = 0; row < object.symbols.length; row++) {
            var symbol = &object.symbols.data[row];
            var reference: WasmSymbolReference = { object: convert(u32, input), symbol: convert(u32, row) };
            var local = (symbol.flags & convert(u32, WasmSymbolFlag.Local)) != 0 || symbol.kind == convert(u8, WasmSymbolKind.Section);
            var weak = (symbol.flags & convert(u32, WasmSymbolFlag.Weak)) != 0;
            var defined = (symbol.flags & convert(u32, WasmSymbolFlag.Undefined)) == 0;
            var explicit_import = !defined && (symbol.flags & convert(u32, WasmSymbolFlag.ExplicitName)) != 0;
            var chunk = wasm_link_symbol_chunk(link, reference);
            if chunk != null && chunk.discarded { defined = false; }
            var index = local ? WasmNoIndex : wasm_names_get(&link.names, symbol.name);
            if index == WasmNoIndex {
                if link.symbols.length >= convert(usize, WasmNoIndex) { return wasm_link_fail(link, WasmLinkError.Layout, symbol.name); }
                index = convert(u32, link.symbols.length);
                var next: WasmResolvedSymbol = { name: symbol.name, definition: reference, declaration: reference, import_declaration: reference,
                    defined: defined, weak: weak, local: local, kind: symbol.kind, explicit_import: explicit_import,
                    tls: (symbol.flags & convert(u32, WasmSymbolFlag.ThreadLocal)) != 0,
                    output_index: WasmNoIndex, got_index: WasmNoIndex, ..default };
                if symbol.kind == convert(u8, WasmSymbolKind.Global) { next.global_mutable = object.globals.data[convert(usize, symbol.index)].mutable; }
                if !wasm_link_push(link, &link.symbols, next) { return false; }
                if !local && !wasm_names_set(&link.names, symbol.name, index) { return wasm_link_fail(link, WasmLinkError.Allocation, symbol.name); }
            } else {
                var previous = &link.symbols.data[convert(usize, index)];
                if symbol.kind != previous.kind || (symbol.kind != convert(u8, WasmSymbolKind.Function)
                    && !wasm_link_signatures(link, previous.declaration, reference)) { return wasm_link_fail(link, WasmLinkError.Signature, symbol.name); }
                if symbol.kind == convert(u8, WasmSymbolKind.Global) { previous.global_mutable ||= object.globals.data[convert(usize, symbol.index)].mutable; }
                if explicit_import && !previous.explicit_import { previous.import_declaration = reference; previous.explicit_import = true; }
                if symbol.kind == convert(u8, WasmSymbolKind.Function) && symbol.called_directly {
                    var declaration = &link.world.objects.data[convert(usize, previous.declaration.object)].object.symbols.data[convert(usize, previous.declaration.symbol)];
                    if !declaration.called_directly { previous.declaration = reference; }
                }
                if defined && previous.defined && !weak && !previous.weak { return wasm_link_fail(link, WasmLinkError.Duplicate, symbol.name); }
                if defined && (!previous.defined || (previous.weak && !weak)) {
                    previous.definition = reference; previous.defined = true; previous.weak = weak;
                } else {
                    if !previous.defined { previous.weak = previous.weak && weak; }
                }
            }
            if !wasm_link_push(link, &link.layouts.data[input].symbols, index) { return false; }
        }
    }
    return true;
}

fn wasm_link_wrapped(link: WasmLink*, symbol: u32): u32 {
    var name = link.symbols.data[convert(usize, symbol)].name;
    if link.symbols.data[convert(usize, symbol)].local { return symbol; }
    foreach (var & wrap in &link.wraps) {
        if wasm_bytes_equal(name, wrap.name) { return wasm_names_get(&link.names, wrap.wrapper); }
        if wasm_bytes_equal(name, wrap.real) { return wasm_names_get(&link.names, wrap.name); }
    }
    return symbol;
}

fn wasm_link_apply_wraps(link: WasmLink*): bool {
    foreach (var layout in &link.layouts) {
        foreach (var & index in &layout.symbols) {
            var wrapped = wasm_link_wrapped(link, *index);
            if wrapped == WasmNoIndex { return wasm_link_fail(link, WasmLinkError.Undefined, link.symbols.data[convert(usize, *index)].name); }
            *index = wrapped;
        }
    }
    return true;
}

// Only direct references impose the declaration's Wasm signature. Address-only
// declarations may have placeholder types (notably C++ vtables); preserve the
// selected definition and its real table address. A mismatched direct call gets
// wasm-ld's typed trap variant, whose function-pointer address is null.
fn wasm_link_variants(link: WasmLink*): bool {
    for (var input: usize = 0; input < link.world.objects.length; input++) {
        var object = link.world.objects.data[input].object;
        var layout = link.layouts.data[input];
        for (var row: usize = 0; row < object.symbols.length; row++) {
            var symbol = &object.symbols.data[row];
            if symbol.kind != convert(u8, WasmSymbolKind.Function) || !symbol.called_directly { continue; }
            var index = layout.symbols.data[row];
            var selected = &link.symbols.data[convert(usize, index)];
            var reference: WasmSymbolReference = { object: convert(u32, input), symbol: convert(u32, row) };
            var actual = selected.defined && selected.definition.object != WasmNoIndex ? selected.definition : selected.declaration;
            if wasm_link_signatures(link, actual, reference) { continue; }
            if !selected.defined { return wasm_link_fail(link, WasmLinkError.Signature, selected.name); }
            var type = layout.types.data[convert(usize, object.functions.data[convert(usize, symbol.index)].type_index)];
            var key: u8[8] = default;
            var combined = (convert(u64, index) << 32) | convert(u64, type);
            for (var at: usize = 0; at < 8; at++) { key[at] = convert(u8, (combined >> convert(u64, at * 8)) & 255); }
            var name: WasmBytes = { data: &key[0], length: 8 };
            var variant = wasm_names_get(&link.variants, name);
            if variant == WasmNoIndex {
                var stub: WasmResolvedSymbol = { name: selected.name, declaration: reference,
                    definition: { object: WasmNoIndex, symbol: WasmNoIndex }, defined: true, local: true,
                    kind: convert(u8, WasmSymbolKind.Function), synthetic: WasmSynthetic.SignatureTrap,
                    output_index: WasmNoIndex, got_index: WasmNoIndex, ..default };
                variant = convert(u32, link.symbols.length);
                var owned: ByteBuffer = default;
                if !bytes_append(&owned, name.data, name.length) { return wasm_link_fail(link, WasmLinkError.Allocation, stub.name); }
                name.data = owned.data;
                if !wasm_link_push(link, &link.owned, owned) { bytes_dispose(&owned); return false; }
                if !wasm_link_push(link, &link.symbols, stub) || !wasm_link_push(link, &link.warnings, reference)
                    || !wasm_names_set(&link.variants, name, variant) { return wasm_link_fail(link, WasmLinkError.Allocation, stub.name); }
            }
            layout.symbols.data[row] = variant;
        }
    }
    return true;
}

import tower;
import wasm_bytes;
import wasm_names;
import wasm_object_types;
import wasm_link_types;
import wasm_link_prepare;

fn wasm_link_synthetic_kind(link: WasmLink*, name: WasmBytes): WasmSynthetic {
    if wasm_bytes_text(name, "__stack_pointer") { return WasmSynthetic.Stack; }
    if wasm_bytes_text(name, "__heap_base") { return WasmSynthetic.HeapBase; }
    if wasm_bytes_text(name, "__data_end") { return WasmSynthetic.DataEnd; }
    if wasm_bytes_text(name, "__memory_base") { return WasmSynthetic.MemoryBase; }
    if wasm_bytes_text(name, "__table_base") { return WasmSynthetic.TableBase; }
    if wasm_bytes_text(name, "__wasm_call_ctors") { return WasmSynthetic.Constructors; }
    if (link.shared_memory || link.has_tls) && wasm_bytes_text(name, "__wasm_init_memory") { return WasmSynthetic.InitMemory; }
    if wasm_bytes_text(name, "__tls_base") { return WasmSynthetic.TlsBase; }
    if wasm_bytes_text(name, "__tls_size") { return WasmSynthetic.TlsSize; }
    if wasm_bytes_text(name, "__tls_align") { return WasmSynthetic.TlsAlign; }
    if wasm_bytes_text(name, "__wasm_init_tls") { return WasmSynthetic.InitTls; }
    if wasm_bytes_text(name, "__indirect_function_table") { return WasmSynthetic.IndirectTable; }
    if wasm_bytes_text(name, "__dso_handle") { return WasmSynthetic.DsoHandle; }
    if wasm_bytes_text(name, "__stack_low") { return WasmSynthetic.StackLow; }
    if wasm_bytes_text(name, "__stack_high") { return WasmSynthetic.StackHigh; }
    if wasm_bytes_text(name, "__global_base") { return WasmSynthetic.GlobalBase; }
    if wasm_bytes_text(name, "__heap_end") { return WasmSynthetic.HeapEnd; }
    if wasm_bytes_text(name, "__wasm_first_page_end") { return WasmSynthetic.FirstPageEnd; }
    return WasmSynthetic.None;
}

fn wasm_link_synthetic_symbol(link: WasmLink*, name: WasmBytes, required: bool): bool {
    var synthetic = wasm_link_synthetic_kind(link, name);
    if synthetic == WasmSynthetic.None { return true; }
    var index = wasm_names_get(&link.names, name);
    if index == WasmNoIndex {
        if !required { return true; }
        var kind = WasmSymbolKind.Data;
        if synthetic == WasmSynthetic.Stack || synthetic == WasmSynthetic.TlsBase || synthetic == WasmSynthetic.TlsSize || synthetic == WasmSynthetic.TlsAlign { kind = WasmSymbolKind.Global; }
        if synthetic == WasmSynthetic.Constructors || synthetic == WasmSynthetic.InitMemory || synthetic == WasmSynthetic.InitTls { kind = WasmSymbolKind.Function; }
        if synthetic == WasmSynthetic.IndirectTable { kind = WasmSymbolKind.Table; }
        var symbol: WasmResolvedSymbol = { name: name, kind: convert(u8, kind),
            definition: { object: WasmNoIndex, symbol: WasmNoIndex },
            declaration: { object: WasmNoIndex, symbol: WasmNoIndex },
            output_index: WasmNoIndex, got_index: WasmNoIndex, ..default };
        index = convert(u32, link.symbols.length);
        if !wasm_link_push(link, &link.symbols, symbol) || !wasm_names_set(&link.names, name, index) {
            return wasm_link_fail(link, WasmLinkError.Allocation, name);
        }
    }
    var symbol = &link.symbols.data[convert(usize, index)];
    if symbol.defined {
        if (synthetic == WasmSynthetic.InitMemory || synthetic == WasmSynthetic.InitTls || synthetic == WasmSynthetic.TlsBase
            || synthetic == WasmSynthetic.TlsSize || synthetic == WasmSynthetic.TlsAlign) && symbol.synthetic != synthetic { return wasm_link_fail(link, WasmLinkError.Duplicate, name); }
        return true;
    }
    var kind = convert(WasmSymbolKind, symbol.kind);
    var valid = kind == WasmSymbolKind.Data || kind == WasmSymbolKind.Global;
    if synthetic == WasmSynthetic.Constructors || synthetic == WasmSynthetic.InitMemory || synthetic == WasmSynthetic.InitTls { valid = kind == WasmSymbolKind.Function; }
    if synthetic == WasmSynthetic.IndirectTable { valid = kind == WasmSymbolKind.Table; }
    if synthetic == WasmSynthetic.Stack || synthetic == WasmSynthetic.TlsBase || synthetic == WasmSynthetic.TlsSize || synthetic == WasmSynthetic.TlsAlign { valid = kind == WasmSymbolKind.Global; }
    if !valid { return wasm_link_fail(link, WasmLinkError.Signature, name); }
    if kind == WasmSymbolKind.Global && symbol.declaration.object != WasmNoIndex {
        var object = link.world.objects.data[convert(usize, symbol.declaration.object)].object;
        var input = &object.symbols.data[convert(usize, symbol.declaration.symbol)];
        var global = &object.globals.data[convert(usize, input.index)];
        if global.type != convert(u8, WasmValueType.I32) || ((synthetic == WasmSynthetic.Stack || synthetic == WasmSynthetic.TlsBase) && !global.mutable) {
            return wasm_link_fail(link, WasmLinkError.Signature, name);
        }
        if (synthetic == WasmSynthetic.TlsSize || synthetic == WasmSynthetic.TlsAlign) && global.mutable {
            return wasm_link_fail(link, WasmLinkError.Signature, name);
        }
    }
    if kind == WasmSymbolKind.Function && symbol.declaration.object != WasmNoIndex {
        var object = link.world.objects.data[convert(usize, symbol.declaration.object)].object;
        var input = &object.symbols.data[convert(usize, symbol.declaration.symbol)];
        var type = &object.types.data[convert(usize, object.functions.data[convert(usize, input.index)].type_index)];
        var parameters: u32 = synthetic == WasmSynthetic.InitTls ? 1 : 0;
        if type.parameters != parameters || type.results != 0 { return wasm_link_fail(link, WasmLinkError.Signature, name); }
        if parameters != 0 {
            var reader: WasmReader = { bytes: type.bytes, ..default };
            wasm_read_byte(&reader); wasm_read_index(&reader);
            if wasm_read_byte(&reader) != convert(u8, WasmValueType.I32) { return wasm_link_fail(link, WasmLinkError.Signature, name); }
        }
    }
    symbol.defined = true; symbol.synthetic = synthetic;
    symbol.definition = init(WasmSymbolReference) { object: WasmNoIndex, symbol: WasmNoIndex };
    return true;
}

fn wasm_link_synthetics(link: WasmLink*): bool {
    if link.shared_memory || link.has_tls {
        var name = wasm_text_bytes("__wasm_init_memory");
        if !wasm_link_synthetic_symbol(link, name, true) { return false; }
        link.memory_init_symbol = wasm_names_get(&link.names, name);
    }
    if link.export_table {
        var request: WasmExportRequest = { name: wasm_text_bytes("__indirect_function_table"), required: true };
        if !wasm_link_push(link, &link.exports, request) { return false; }
    }
    // No growth while borrowing existing rows; optional symbols are synthesized
    // only if a declaration, explicit export or runtime stack contract needs it.
    for (var at: usize = 0; at < link.symbols.length; at++) {
        var name = link.symbols.data[at].name;
        if !wasm_link_synthetic_symbol(link, name, false) { return false; }
    }
    foreach (var & request in &link.exports) {
        if !wasm_link_synthetic_symbol(link, request.name, true) { return false; }
    }
    if link.has_tls || wasm_names_get(&link.names, wasm_text_bytes("__wasm_init_tls")) != WasmNoIndex {
        if !wasm_link_synthetic_symbol(link, wasm_text_bytes("__wasm_init_tls"), true)
            || !wasm_link_synthetic_symbol(link, wasm_text_bytes("__tls_base"), true) { return false; }
        link.tls_init_symbol = wasm_names_get(&link.names, wasm_text_bytes("__wasm_init_tls"));
        link.tls_base_symbol = wasm_names_get(&link.names, wasm_text_bytes("__tls_base"));
    }
    return wasm_link_synthetic_symbol(link, wasm_text_bytes("__stack_pointer"), true);
}

fn wasm_link_function_type(link: WasmLink*, index: u32): u32 {
    var symbol = &link.symbols.data[convert(usize, index)];
    var reference = symbol.defined && symbol.definition.object != WasmNoIndex ? symbol.definition : symbol.declaration;
    if reference.object == WasmNoIndex {
        var encoding: u8[4] = default;
        encoding[0] = WasmFunctionType;
        var length: usize = 3;
        var parameters: u32 = 0;
        if symbol.synthetic == WasmSynthetic.InitTls { parameters = 1; length = 4; encoding[1] = 1; encoding[2] = convert(u8, WasmValueType.I32); }
        var type: WasmFunctionTypeRecord = { bytes: { data: &encoding[0], length: length }, parameters: parameters, ..default };
        return wasm_link_type(link, &type);
    }
    var object = link.world.objects.data[convert(usize, reference.object)].object;
    var input = &object.symbols.data[convert(usize, reference.symbol)];
    return link.layouts.data[convert(usize, reference.object)].types.data[convert(usize, object.functions.data[convert(usize, input.index)].type_index)];
}

import tower;
import wasm_bytes;
import wasm_object_types;
import wasm_link_world;
import wasm_names;
import .library.vector;
import .library.bytes_types;
import .library.entity_types;

enum WasmLinkError: u32 { None = 0, Allocation = 1, Duplicate = 2, Signature = 3, Undefined = 4, Unsupported = 5, Layout = 6, Input = 7 }
enum WasmSynthetic: u8 { None = 0, Stack = 1, HeapBase = 2, DataEnd = 3, MemoryBase = 4, TableBase = 5, Constructors = 6, IndirectTable = 7, DsoHandle = 8, StackLow = 9, StackHigh = 10, GlobalBase = 11, HeapEnd = 12, FirstPageEnd = 13, SignatureTrap = 14, InitMemory = 15, TlsBase = 16, TlsSize = 17, TlsAlign = 18, InitTls = 19 }
struct WasmSymbolReference { object: u32; symbol: u32; }
struct WasmResolvedSymbol {
    name: WasmBytes;
    definition: WasmSymbolReference;
    declaration: WasmSymbolReference;
    import_declaration: WasmSymbolReference;
    defined: bool;
    weak: bool;
    local: bool;
    kind: u8;
    synthetic: WasmSynthetic;
    live: bool;
    output_index: u32;
    table_index: u32;
    got_index: u32;
    needs_table: bool;
    needs_global: bool;
    global_mutable: bool;
    explicit_import: bool;
    tls: bool;
    address: u64;
}
struct WasmChunkLayout { discarded: bool; live: bool; tls: bool; output_index: u32; table_index: u32; address: u64; output_offset: u64; relocation_first: usize; relocation_count: usize; }
struct WasmChunkReference { object: u32; index: u32; kind: WasmSymbolKind; }
struct WasmLinkInitializer { priority: u32; symbol: u32; }
struct WasmObjectLayout {
    types: vector(u32);
    symbols: vector(u32);
    functions: vector(WasmChunkLayout);
    globals: vector(WasmChunkLayout);
    tables: vector(WasmChunkLayout);
    tags: vector(WasmChunkLayout);
    data: vector(WasmChunkLayout);
    relocations: vector(u32);
}
struct WasmExportRequest { name: WasmBytes; required: bool; }
struct WasmWrapRequest { name: WasmBytes; wrapper: WasmBytes; real: WasmBytes; }
struct WasmOutputFunction { object: u32; function: u32; symbol: u32; type_index: u32; }
struct WasmOutputGlobal { object: u32; global: u32; symbol: u32; }
struct WasmOutputExport { name: WasmBytes; kind: u8; index: u32; }
struct WasmLink {
    world: WasmLinkWorld;
    layout_type: Entity*;
    layouts: vector(WasmObjectLayout*);
    names: WasmNameMap;
    type_names: WasmNameMap;
    comdat_names: WasmNameMap;
    variants: WasmNameMap;
    feature_names: WasmNameMap;
    features: vector(WasmFeatureRecord);
    warnings: vector(WasmSymbolReference);
    symbols: vector(WasmResolvedSymbol);
    types: vector(WasmBytes);
    owned: vector(ByteBuffer);
    exports: vector(WasmExportRequest);
    wraps: vector(WasmWrapRequest);
    allowed: WasmNameMap;
    functions: vector(WasmOutputFunction);
    globals: vector(WasmOutputGlobal);
    output_exports: vector(WasmOutputExport);
    table_functions: vector(u32);
    pending: vector(WasmChunkReference);
    initializers: vector(WasmLinkInitializer);
    output: ByteBuffer;
    error: WasmLinkError;
