var WasmStackAlignment: u64 = 16;
var WasmDefaultStackBytes: u64 = 65536;
var WasmDefaultMaximumBytes: u64 = 2147483648;
var WasmDefaultGlobalBase: u64 = 1024;
var WasmMemory32Limit: u64 = 4294967296;
var WasmTableBase: u32 = 1;
var WasmMemoryInitFlagBytes: u64 = 4;
enum WasmMemoryInitState: u32 { Uninitialized = 0, Initializing = 1, Ready = 2 }

fn wasm_link_fail(link: WasmLink*, error: WasmLinkError, name: WasmBytes): bool {
    if link.error == WasmLinkError.None { link.error = error; link.error_name = name; }
    return false;
}

fn wasm_link_push(T: type, link: WasmLink*, list: vector(T)*, value: T): bool {
    if link.error != WasmLinkError.None { return false; }
    if list.length >= convert(usize, WasmNoIndex) { return wasm_link_fail(link, WasmLinkError.Layout, default(WasmBytes)); }
    if !vector_push(list, value) { return wasm_link_fail(link, WasmLinkError.Allocation, default(WasmBytes)); }
    return true;
}

fn wasm_link_init(link: WasmLink*): bool {
    link.stack_size = WasmDefaultStackBytes;
    link.maximum_memory = WasmDefaultMaximumBytes;
    link.export_memory = true;
    link.garbage_collect = true;
    link.memory_module = wasm_text_bytes("env");
    link.memory_name = wasm_text_bytes("memory");
    link.memory_init_symbol = WasmNoIndex;
    link.tls_base_symbol = WasmNoIndex;
    link.tls_init_symbol = WasmNoIndex;
    link.tls_align = 1;
    link.workers = 1;
    link.job_grain = WasmLinkJobGrain;
    if !wasm_link_world_open(&link.world) { return wasm_link_fail(link, WasmLinkError.Allocation, default(WasmBytes)); }
    return true;
}

var WasmLinkJobGrain: u64 = 262144;
var WasmLinkRelocationCost: u64 = 64;
var WasmLinkMaximumWorkers: usize = 256;

fn wasm_link_object_layout_dispose(layout: WasmObjectLayout*): void {
    vector_dispose(&layout.types); vector_dispose(&layout.symbols);
    vector_dispose(&layout.functions); vector_dispose(&layout.globals);
    vector_dispose(&layout.tables); vector_dispose(&layout.tags); vector_dispose(&layout.data); vector_dispose(&layout.relocations);
}

import tower;
import wasm_bytes;
import wasm_object;
import wasm_object_types;
import wasm_archive;
import .library.vector;
import .library.entity_types;
import .library.entity_api;

struct WasmObjectEntry { node: Entity*; object: WasmObject*; name: WasmBytes; }
enum WasmInputKind: u8 { Object = 0, Archive = 1 }
struct WasmInputOrder { kind: WasmInputKind; index: u32; }
struct WasmArchivePayload { archive: WasmArchive; selected: vector(bool); }
struct WasmArchiveEntry { node: Entity*; payload: WasmArchivePayload*; name: WasmBytes; }
struct WasmLinkWorld {
    store: EntityStore*;
    object_type: Entity*;
    archive_type: Entity*;
    objects: vector(WasmObjectEntry);
    archives: vector(WasmArchiveEntry);
    inputs: vector(WasmInputOrder);
    error: WasmReadError;
    error_input: WasmBytes;
    error_offset: usize;
}

fn wasm_link_world_open(world: WasmLinkWorld*): bool {
    world.store = entity_store_create();
    if world.store == null { return false; }
    if !entity_store_set_context(world.store, bits(void*, world)) { return false; }
    world.object_type = entity_create(world.store);
    if world.object_type == null { return false; }
    if !entity_register(world.object_type, sizeof(WasmObject), alignof(WasmObject), 0) { return false; }
    world.archive_type = entity_create(world.store);
    return world.archive_type != null && entity_register(world.archive_type, sizeof(WasmArchivePayload), alignof(WasmArchivePayload), 0);
}

// Coordinator prepares nodes and component kinds before any worker dispatch.
// Workers then own one stable object payload and private vectors. No structure,
// refcounts, type identities or global symbol indexes are mutated by a reader.
fn wasm_link_prepare_object_mode(world: WasmLinkWorld*, name: WasmBytes, bytes: WasmBytes, record_input: bool): WasmObject* {
    if world.error != WasmReadError.None { return null; }
    var node = entity_create(world.store);
    if node == null { world.error = WasmReadError.Allocation; return null; }
    var component = entity_component_add(node, world.object_type);
    if component == null { entity_release(node); world.error = WasmReadError.Allocation; return null; }
    var object = bits(WasmObject*, entity_component_data(component));
    *object = default;
    object.bytes = bytes;
    var entry: WasmObjectEntry = { node: node, object: object, name: name };
    if !vector_push(&world.objects, entry) { entity_release(node); world.error = WasmReadError.Allocation; return null; }
    if record_input {
        var order: WasmInputOrder = { kind: WasmInputKind.Object, index: convert(u32, world.objects.length - 1) };
        if !vector_push(&world.inputs, order) { world.error = WasmReadError.Allocation; return null; }
    }
    return object;
}

fn wasm_link_prepare_object(world: WasmLinkWorld*, name: WasmBytes, bytes: WasmBytes): WasmObject* {
    return wasm_link_prepare_object_mode(world, name, bytes, true);
}

fn wasm_link_collect_errors(world: WasmLinkWorld*): bool {
    if world.error != WasmReadError.None { return false; }
    foreach (var & entry in &world.objects) {
        if entry.object.error != WasmReadError.None {
            world.error = entry.object.error; world.error_input = entry.name;
            world.error_offset = entry.object.error_offset; return false;
        }
    }
    return true;
}

fn wasm_link_read_object(world: WasmLinkWorld*, name: WasmBytes, bytes: WasmBytes): bool {
    var object = wasm_link_prepare_object(world, name, bytes);
    if object == null { return false; }
    if !wasm_object_read(object, bytes) {
        world.error = object.error; world.error_input = name; world.error_offset = object.error_offset;
        return false;
    }
    return true;
}

// Read-all is the explicit whole-archive contract used by compiler self-builds.
// Lazy archive extraction consumes indexed archive symbols separately.
fn wasm_link_read_archive(world: WasmLinkWorld*, name: WasmBytes, bytes: WasmBytes): bool {
    var archive: WasmArchive = default;
    defer wasm_archive_dispose(&archive);
    if !wasm_archive_read(&archive, bytes) {
        world.error = archive.error; world.error_offset = archive.error_offset;
        world.error_input = name; return false;
    }
    foreach (var & member in &archive.members) {
        if !member.special && !wasm_link_read_object(world, member.name, member.bytes) { return false; }
    }
    return true;
}

// Lazy inputs retain their indexed members on an archive component. Selection
// happens in request order before type interning and symbol publication.
fn wasm_link_add_archive(world: WasmLinkWorld*, name: WasmBytes, bytes: WasmBytes): bool {
    if world.error != WasmReadError.None { return false; }
    var node = entity_create(world.store);
    if node == null { world.error = WasmReadError.Allocation; return false; }
    var component = entity_component_add(node, world.archive_type);
    if component == null { entity_release(node); world.error = WasmReadError.Allocation; return false; }
    var payload = bits(WasmArchivePayload*, entity_component_data(component));
    *payload = default;
    var entry: WasmArchiveEntry = { node: node, payload: payload, name: name };
    if !vector_push(&world.archives, entry) { entity_release(node); world.error = WasmReadError.Allocation; return false; }
    if !wasm_archive_read(&payload.archive, bytes) {
        world.error = payload.archive.error; world.error_input = name; world.error_offset = payload.archive.error_offset; return false;
    }
    var count = payload.archive.members.length;
    if !vector_reserve(&payload.selected, count) { world.error = WasmReadError.Allocation; return false; }
    if count != 0 { fill(payload.selected.data, 0, count * sizeof(bool)); }
    payload.selected.length = count;
    var order: WasmInputOrder = { kind: WasmInputKind.Archive, index: convert(u32, world.archives.length - 1) };
    if !vector_push(&world.inputs, order) { world.error = WasmReadError.Allocation; return false; }
    return true;
}

fn wasm_link_world_close(world: WasmLinkWorld*): bool {
    if world.store == null { return true; }
    if world.store.views != 0 { return false; }
    foreach (var & entry in &world.objects) {
        wasm_object_dispose(entry.object);
        entity_release(entry.node);
    }
    vector_dispose(&world.objects);
    foreach (var & entry in &world.archives) {
        wasm_archive_dispose(&entry.payload.archive); vector_dispose(&entry.payload.selected);
        entity_release(entry.node);
    }
    vector_dispose(&world.archives); vector_dispose(&world.inputs);
    if world.object_type != null { entity_release(world.object_type); world.object_type = null; }
    if world.archive_type != null { entity_release(world.archive_type); world.archive_type = null; }
    if !entity_store_dispose(world.store) { return false; }
    *world = default;
    return true;
}

import tower;
import wasm_bytes;
import wasm_object_types;

// Derived name -> row index. Keys borrow pinned object/argument storage; row
// identities survive rehashing. Each link request owns its tables independently.
struct WasmNameSlot { name: WasmBytes; value: u32; hash: u32; }
struct WasmNameMap { slots: WasmNameSlot*; capacity: usize; count: usize; }
var WasmNameInitialCapacity: usize = 16;

fn wasm_names_dispose(map: WasmNameMap*): void { free(map.slots); *map = default; }

fn wasm_names_hash(name: WasmBytes): u32 {
    var hash = wasm_bytes_hash(name);
    // Zero marks an unused slot; full bytes still distinguish hash collisions.
    return hash == 0 ? 1 : hash;
}

fn wasm_names_slot(map: WasmNameMap*, name: WasmBytes, hash: u32): usize {
    var at = convert(usize, hash) & (map.capacity - 1);
    while map.slots[at].hash != 0 && (map.slots[at].hash != hash || !wasm_bytes_equal(map.slots[at].name, name)) {
        at = (at + 1) & (map.capacity - 1);
    }
    return at;
}

fn wasm_names_get(map: WasmNameMap*, name: WasmBytes): u32 {
    if map.capacity == 0 { return WasmNoIndex; }
    var at = wasm_names_slot(map, name, wasm_names_hash(name));
    return map.slots[at].hash != 0 ? map.slots[at].value : WasmNoIndex;
}

fn wasm_names_set(map: WasmNameMap*, name: WasmBytes, value: u32): bool {
    var hash = wasm_names_hash(name);
    var at: usize = 0;
    if map.capacity != 0 {
        at = wasm_names_slot(map, name, hash);
        if map.slots[at].hash != 0 { map.slots[at].value = value; return true; }
    }
    if map.capacity == 0 || map.count >= map.capacity / 2 {
        var capacity: usize = map.capacity == 0 ? WasmNameInitialCapacity : map.capacity * 2;
        if capacity < map.capacity || capacity > (~convert(usize, 0)) / sizeof(WasmNameSlot) { return false; }
        var next: WasmNameMap = { slots: alloc(WasmNameSlot, capacity), capacity: capacity, count: map.count };
        if next.slots == null { return false; }
        fill(next.slots, 0, capacity * sizeof(WasmNameSlot));
        for (var row: usize = 0; row < map.capacity; row++) {
            var slot = &map.slots[row];
            if slot.hash != 0 { next.slots[wasm_names_slot(&next, slot.name, slot.hash)] = *slot; }
        }
        free(map.slots); *map = next;
        at = wasm_names_slot(map, name, hash);
    }
    map.count++;
    map.slots[at] = init(WasmNameSlot) { name: name, value: value, hash: hash };
    return true;
}

import tower;
import wasm_bytes;
import wasm_object_types;
import wasm_object_sections;
import wasm_object_linking;

fn wasm_section_order(kind: u8): u8 {
    var section = convert(WasmSection, kind);
    match section {
        WasmSection.Tag => { return 6; }
        WasmSection.Global => { return 7; }
        WasmSection.Export => { return 8; }
        WasmSection.Start => { return 9; }
        WasmSection.Element => { return 10; }
        WasmSection.DataCount => { return 11; }
        WasmSection.Code => { return 12; }
        WasmSection.Data => { return 13; }
        _ => { return kind; }
    }
}

fn wasm_object_sections(object: WasmObject*, reader: WasmReader*): void {
    var magic = wasm_read_bytes(reader, 8);
    if magic.length != 8 { return; }
    if magic.data[0] != 0 || magic.data[1] != 97 || magic.data[2] != 115 || magic.data[3] != 109
        || magic.data[4] != 1 || magic.data[5] != 0 || magic.data[6] != 0 || magic.data[7] != 0 {
        wasm_read_fail(reader, WasmReadError.Encoding); return;
    }
    var order: u8 = 0;
    while reader.at < reader.bytes.length && reader.error == WasmReadError.None {
        var section: WasmObjectSection = { kind: wasm_read_byte(reader), ..default };
        var size = wasm_read_index(reader);
        section.file_offset = reader.at;
        section.bytes = wasm_read_bytes(reader, convert(usize, size));
        if reader.error != WasmReadError.None { return; }
        if section.kind > convert(u8, WasmSection.Tag) { wasm_read_fail(reader, WasmReadError.Unsupported); return; }
        var sub: WasmReader = { bytes: section.bytes, ..default };
        if section.kind == convert(u8, WasmSection.Custom) {
            section.name = wasm_read_name(&sub);
            section.content_offset = sub.at;
        } else {
            var next = wasm_section_order(section.kind);
            if next <= order { wasm_read_fail(reader, WasmReadError.Duplicate); return; }
            order = next;
            if section.kind == convert(u8, WasmSection.Code) { object.code_section = convert(u32, object.sections.length); }
            if section.kind == convert(u8, WasmSection.Data) { object.data_section = convert(u32, object.sections.length); }
            wasm_object_standard(object, &sub, section.kind);
            if sub.error == WasmReadError.None && sub.at != sub.bytes.length { wasm_read_fail(&sub, WasmReadError.Encoding); }
        }
        if sub.error != WasmReadError.None {
            reader.error = sub.error; reader.error_offset = section.file_offset + sub.error_offset; return;
        }
        wasm_object_push(reader, &object.sections, section);
    }
}

// Chunk boundaries are monotonically ordered in each input. Lookup is derived
// from those records. Consecutive relocations normally belong to the same
// chunk; shuffled records retain the bounded binary-search fallback.
fn wasm_object_relocation_chunk(object: WasmObject*, relocation: WasmRelocationRecord*, width: usize, hint: u32): u32 {
    var first: usize = 0;
    var last: usize = 0;
    var code = relocation.section == object.code_section;
    if code { first = convert(usize, object.imported_functions); last = object.functions.length; }
    else {
        if relocation.section != object.data_section { return WasmNoIndex; }
        last = object.data.length;
    }
    var begin = first;
    var previous = convert(usize, hint);
    if previous >= first && previous < last {
        var offset = code ? object.functions.data[previous].code_offset : object.data.data[previous].section_offset;
        var length = code ? object.functions.data[previous].code.length : object.data.data[previous].bytes.length;
        if relocation.offset >= offset {
            var local = convert(usize, relocation.offset - offset);
            if local <= length && width <= length - local { return hint; }
        }
    }
    while first < last {
        var middle = first + (last - first) / 2;
        var offset = code ? object.functions.data[middle].code_offset : object.data.data[middle].section_offset;
        if offset <= relocation.offset { first = middle + 1; }
        else { last = middle; }
    }
    if first == begin { return WasmNoIndex; }
    var index = first - 1;
    var offset = code ? object.functions.data[index].code_offset : object.data.data[index].section_offset;
    var length = code ? object.functions.data[index].code.length : object.data.data[index].bytes.length;
    var local = convert(usize, relocation.offset - offset);
    return local <= length && width <= length - local ? convert(u32, index) : WasmNoIndex;
}

fn wasm_object_validate(object: WasmObject*, reader: WasmReader*): void {
    if !object.linking { wasm_read_fail(reader, WasmReadError.Encoding); return; }
    if object.data_count != WasmNoIndex && convert(usize, object.data_count) != object.data.length { wasm_read_fail(reader, WasmReadError.Encoding); return; }
    foreach (var & function in &object.functions) {
        if convert(usize, function.type_index) >= object.types.length || (!function.imported && function.code.length == 0) {
            wasm_read_fail(reader, WasmReadError.Index); return;
        }
    }
    foreach (var & tag in &object.tags) {
        if convert(usize, tag.type_index) >= object.types.length { wasm_read_fail(reader, WasmReadError.Index); return; }
    }
    foreach (var & element in &object.elements) {
        if convert(usize, element.function) >= object.functions.length || convert(usize, element.table) >= object.tables.length {
            wasm_read_fail(reader, WasmReadError.Index); return;
        }
    }
    foreach (var & exported in &object.exports) {
        var limit: usize = 0;
        var kind = convert(WasmExternal, exported.kind);
        match kind {
            WasmExternal.Function => { limit = object.functions.length; }
            WasmExternal.Global => { limit = object.globals.length; }
            WasmExternal.Memory => { limit = object.memories.length; }
            WasmExternal.Table => { limit = object.tables.length; }
            WasmExternal.Tag => { limit = object.tags.length; }
            _ => { }
        }
        if convert(usize, exported.index) >= limit { wasm_read_fail(reader, WasmReadError.Index); return; }
    }
    foreach (var & entry in &object.comdat_entries) {
        var kind = convert(WasmComdatKind, entry.kind);
        var limit: usize = 0;
        var imported = false;
        var row = convert(usize, entry.index);
        match kind {
            WasmComdatKind.Data => { limit = object.data.length; }
            WasmComdatKind.Function => { limit = object.functions.length; imported = row < convert(usize, object.imported_functions); }
            WasmComdatKind.Global => { limit = object.globals.length; if row < limit { imported = object.globals.data[row].imported; } }
            WasmComdatKind.Tag => { limit = object.tags.length; if row < limit { imported = object.tags.data[row].imported; } }
            WasmComdatKind.Table => { limit = object.tables.length; if row < limit { imported = object.tables.data[row].imported; } }
            WasmComdatKind.Section => { limit = object.sections.length; }
            _ => { }
        }
        if row >= limit || imported { wasm_read_fail(reader, WasmReadError.Index); return; }
    }
    foreach (var & symbol in &object.symbols) {
        var local = (symbol.flags & convert(u32, WasmSymbolFlag.Local)) != 0;
        if local && (symbol.flags & (convert(u32, WasmSymbolFlag.Undefined) | convert(u32, WasmSymbolFlag.Exported))) != 0 {
            wasm_read_fail(reader, WasmReadError.Encoding); return;
        }
        var kind = convert(WasmSymbolKind, symbol.kind);
        var index = convert(usize, symbol.index);
        var valid = false;
        var imported = (symbol.flags & convert(u32, WasmSymbolFlag.Undefined)) != 0;
        match kind {
            WasmSymbolKind.Function => { valid = index < object.functions.length && object.functions.data[index].imported == imported; }
            WasmSymbolKind.Global => { valid = index < object.globals.length && object.globals.data[index].imported == imported; }
            WasmSymbolKind.Tag => { valid = index < object.tags.length && object.tags.data[index].imported == imported; }
            WasmSymbolKind.Table => { valid = index < object.tables.length && object.tables.data[index].imported == imported; }
            WasmSymbolKind.Section => { valid = index < object.sections.length; }
            WasmSymbolKind.Data => {
                if (symbol.flags & convert(u32, WasmSymbolFlag.Undefined)) != 0 { valid = true; }
                else {
                    if (symbol.flags & convert(u32, WasmSymbolFlag.Absolute)) != 0 { wasm_read_fail(reader, WasmReadError.Unsupported); return; }
                    if index < object.data.length {
                        var length = convert(u64, object.data.data[index].bytes.length);
                        valid = symbol.offset <= length && symbol.size <= length - symbol.offset;
                    }
                }
            }
            _ => { }
        }
        if !valid { wasm_read_fail(reader, WasmReadError.Index); return; }
    }
    foreach (var & initializer in &object.initializers) {
        var index = convert(usize, initializer.symbol);
        if index >= object.symbols.length || object.symbols.data[index].kind != convert(u8, WasmSymbolKind.Function) {
            wasm_read_fail(reader, WasmReadError.Index); return;
        }
        var function = &object.functions.data[convert(usize, object.symbols.data[index].index)];
        var type = &object.types.data[convert(usize, function.type_index)];
        if type.parameters != 0 || type.results != 0 { wasm_read_fail(reader, WasmReadError.Encoding); return; }
    }
    var code_hint = WasmNoIndex; var data_hint = WasmNoIndex;
    foreach (var & relocation in &object.relocations) {
        var section = convert(usize, relocation.section);
        if section >= object.sections.length { wasm_read_fail(reader, WasmReadError.Index); return; }
        var kind = convert(WasmRelocation, relocation.kind);
        var index = convert(usize, relocation.index);
        if (kind == WasmRelocation.TypeIndexLeb && index >= object.types.length)
            || (kind != WasmRelocation.TypeIndexLeb && index >= object.symbols.length) { wasm_read_fail(reader, WasmReadError.Index); return; }
        if kind == WasmRelocation.FunctionIndexLeb { object.symbols.data[index].called_directly = true; }
        var bytes = object.sections.data[section].bytes;
        var offset = convert(usize, relocation.offset);
        var width = convert(usize, wasm_relocation_width(kind));
        if offset > bytes.length || width > bytes.length - offset { wasm_read_fail(reader, WasmReadError.Index); return; }
        var contained = object.sections.data[section].kind == convert(u8, WasmSection.Custom);
        var row = WasmNoIndex;
        if !contained {
            var code = relocation.section == object.code_section;
            row = wasm_object_relocation_chunk(object, relocation, width, code ? code_hint : data_hint);
            if code { code_hint = row; } else { data_hint = row; }
            contained = row != WasmNoIndex;
        }
        if !contained { wasm_read_fail(reader, WasmReadError.Index); return; }
        if !wasm_object_push(reader, &object.relocation_chunks, row) { return; }
    }
}

// Destination must be fresh/empty. Failure leaves owned partial vectors there
// for wasm_object_dispose, with a stable error and offset in the original input.
fn wasm_object_read(object: WasmObject*, bytes: WasmBytes): bool {
    object.bytes = bytes;
    object.start = WasmNoIndex;
    object.data_count = WasmNoIndex;
    object.code_section = WasmNoIndex;
    object.data_section = WasmNoIndex;
    var reader: WasmReader = { bytes: bytes, ..default };
    wasm_object_sections(object, &reader);
    wasm_object_error(object, &reader, 0);
    if object.error != WasmReadError.None { return false; }
    foreach (var & section in &object.sections) {
        if section.kind != convert(u8, WasmSection.Custom) { continue; }
        var sub: WasmReader = { bytes: section.bytes, at: section.content_offset, ..default };
        if wasm_bytes_text(section.name, "linking") { wasm_object_linking(object, &sub); }
        else {
            if section.name.length >= 6 && section.name.data[0] == 114 && section.name.data[1] == 101
                && section.name.data[2] == 108 && section.name.data[3] == 111 && section.name.data[4] == 99 && section.name.data[5] == 46 {
                wasm_object_relocations(object, &sub);
            } else {
                if wasm_bytes_text(section.name, "target_features") { wasm_object_features(object, &sub); }
                else { continue; }
            }
        }
        if sub.error == WasmReadError.None && sub.at != sub.bytes.length { wasm_read_fail(&sub, WasmReadError.Encoding); }
        wasm_object_error(object, &sub, section.file_offset);
        if object.error != WasmReadError.None { return false; }
    }
    wasm_object_validate(object, &reader);
    wasm_object_error(object, &reader, 0);
    return object.error == WasmReadError.None;
}

import tower;
import wasm_bytes;
import wasm_object_types;

enum WasmRelocation: u32 {
    FunctionIndexLeb = 0, TableIndexSleb = 1, TableIndexI32 = 2,
    MemoryAddressLeb = 3, MemoryAddressSleb = 4, MemoryAddressI32 = 5,
    TypeIndexLeb = 6, GlobalIndexLeb = 7, FunctionOffsetI32 = 8,
    SectionOffsetI32 = 9, TagIndexLeb = 10, MemoryAddressRelativeSleb = 11,
    TableIndexRelativeSleb = 12, GlobalIndexI32 = 13, MemoryAddressLeb64 = 14,
    MemoryAddressSleb64 = 15, MemoryAddressI64 = 16, MemoryAddressRelativeSleb64 = 17,
    TableIndexSleb64 = 18, TableIndexI64 = 19, TableNumberLeb = 20,
    MemoryAddressTlsSleb = 21, FunctionOffsetI64 = 22, MemoryAddressLocalRelativeI32 = 23,
    TableIndexRelativeSleb64 = 24, MemoryAddressTlsSleb64 = 25, FunctionIndexI32 = 26
}

fn wasm_relocation_addend(kind: WasmRelocation): u64 {
    match kind {
        WasmRelocation.MemoryAddressLeb | WasmRelocation.MemoryAddressSleb | WasmRelocation.MemoryAddressI32
        | WasmRelocation.FunctionOffsetI32 | WasmRelocation.SectionOffsetI32 | WasmRelocation.MemoryAddressRelativeSleb
        | WasmRelocation.MemoryAddressTlsSleb | WasmRelocation.MemoryAddressLocalRelativeI32 => { return 32; }
        WasmRelocation.MemoryAddressLeb64 | WasmRelocation.MemoryAddressSleb64 | WasmRelocation.MemoryAddressI64
        | WasmRelocation.MemoryAddressRelativeSleb64 | WasmRelocation.FunctionOffsetI64 | WasmRelocation.MemoryAddressTlsSleb64 => { return 64; }
        _ => { return 0; }
    }
}

fn wasm_relocation_width(kind: WasmRelocation): u32 {
    match kind {
        WasmRelocation.TableIndexI32 | WasmRelocation.MemoryAddressI32 | WasmRelocation.FunctionOffsetI32
        | WasmRelocation.SectionOffsetI32 | WasmRelocation.GlobalIndexI32 | WasmRelocation.MemoryAddressLocalRelativeI32
        | WasmRelocation.FunctionIndexI32 => { return 4; }
        WasmRelocation.MemoryAddressI64 | WasmRelocation.TableIndexI64 | WasmRelocation.FunctionOffsetI64 => { return 8; }
        WasmRelocation.MemoryAddressLeb64 | WasmRelocation.MemoryAddressSleb64 | WasmRelocation.MemoryAddressRelativeSleb64
        | WasmRelocation.TableIndexSleb64 | WasmRelocation.TableIndexRelativeSleb64 | WasmRelocation.MemoryAddressTlsSleb64 => { return 10; }
        _ => { return 5; }
    }
}

fn wasm_object_symbol_name(object: WasmObject*, reader: WasmReader*, symbol: WasmSymbolRecord*): void {
    var index = convert(usize, symbol.index);
    var kind = convert(WasmSymbolKind, symbol.kind);
    match kind {
        WasmSymbolKind.Function => {
            if index >= object.functions.length { wasm_read_fail(reader, WasmReadError.Index); return; }
            symbol.name = object.functions.data[index].name;
        }
        WasmSymbolKind.Global => {
            if index >= object.globals.length { wasm_read_fail(reader, WasmReadError.Index); return; }
            symbol.name = object.globals.data[index].name;
        }
        WasmSymbolKind.Tag => {
            if index >= object.tags.length { wasm_read_fail(reader, WasmReadError.Index); return; }
            symbol.name = object.tags.data[index].name;
        }
        WasmSymbolKind.Table => {
            if index >= object.tables.length { wasm_read_fail(reader, WasmReadError.Index); return; }
            symbol.name = object.tables.data[index].name;
        }
        _ => { wasm_read_fail(reader, WasmReadError.Encoding); }
    }
}

fn wasm_object_symbols(object: WasmObject*, reader: WasmReader*): void {
    var count = wasm_read_index(reader);
    for (var at: u32 = 0; at < count && reader.error == WasmReadError.None; at++) {
        var symbol: WasmSymbolRecord = { kind: wasm_read_byte(reader), flags: wasm_read_index(reader), ..default };
        var undefined = (symbol.flags & convert(u32, WasmSymbolFlag.Undefined)) != 0;
        var kind = convert(WasmSymbolKind, symbol.kind);
        match kind {
            WasmSymbolKind.Data => {
                symbol.name = wasm_read_name(reader);
                if !undefined {
                    symbol.index = wasm_read_index(reader);
                    symbol.offset = wasm_read_uleb(reader, 64);
                    symbol.size = wasm_read_uleb(reader, 64);
                }
            }
            WasmSymbolKind.Section => { symbol.index = wasm_read_index(reader); }
            WasmSymbolKind.Function | WasmSymbolKind.Global | WasmSymbolKind.Tag | WasmSymbolKind.Table => {
                symbol.index = wasm_read_index(reader);
                if !undefined || (symbol.flags & convert(u32, WasmSymbolFlag.ExplicitName)) != 0 {
                    symbol.name = wasm_read_name(reader);
                } else { wasm_object_symbol_name(object, reader, &symbol); }
            }
            _ => { wasm_read_fail(reader, WasmReadError.Unsupported); }
        }
        wasm_object_push(reader, &object.symbols, symbol);
    }
}

fn wasm_object_linking(object: WasmObject*, reader: WasmReader*): void {
    if object.linking { wasm_read_fail(reader, WasmReadError.Duplicate); return; }
    object.linking = true;
    if wasm_read_index(reader) != WasmLinkingVersion { wasm_read_fail(reader, WasmReadError.Unsupported); return; }
    while reader.at < reader.bytes.length && reader.error == WasmReadError.None {
        var kind = wasm_read_byte(reader);
        var size = wasm_read_index(reader);
        var offset = reader.at;
        var sub: WasmReader = { bytes: wasm_read_bytes(reader, convert(usize, size)), ..default };
        if reader.error != WasmReadError.None { return; }
        if kind >= convert(u8, WasmLinkingSection.Segments) && kind <= convert(u8, WasmLinkingSection.Symbols) {
            var bit = convert(u32, 1) << convert(u32, kind);
            if (object.linking_sections & bit) != 0 { wasm_read_fail(reader, WasmReadError.Duplicate); return; }
            object.linking_sections |= bit;
        }
        var section = convert(WasmLinkingSection, kind);
        if section == WasmLinkingSection.Symbols { wasm_object_symbols(object, &sub); }
        else {
            var count = wasm_read_index(&sub);
            for (var at: u32 = 0; at < count && sub.error == WasmReadError.None; at++) {
                match section {
                    WasmLinkingSection.Segments => {
                        if convert(usize, count) != object.data.length { wasm_read_fail(&sub, WasmReadError.Encoding); break; }
                        var data = &object.data.data[convert(usize, at)];
                        data.name = wasm_read_name(&sub);
                        data.alignment = wasm_read_index(&sub);
                        data.flags = wasm_read_index(&sub);
                        if data.alignment > 63 { wasm_read_fail(&sub, WasmReadError.Integer); }
                    }
                    WasmLinkingSection.Initializers => {
                        var initializer: WasmInitializerRecord = { priority: wasm_read_index(&sub), symbol: wasm_read_index(&sub) };
                        wasm_object_push(&sub, &object.initializers, initializer);
                    }
                    WasmLinkingSection.Comdats => {
                        var group: WasmComdatRecord = { name: wasm_read_name(&sub), first: object.comdat_entries.length, ..default };
                        if wasm_read_index(&sub) != 0 { wasm_read_fail(&sub, WasmReadError.Encoding); }
                        group.count = convert(usize, wasm_read_index(&sub));
                        for (var entry: usize = 0; entry < group.count && sub.error == WasmReadError.None; entry++) {
                            var value: WasmComdatEntry = { kind: wasm_read_byte(&sub), index: wasm_read_index(&sub) };
                            wasm_object_push(&sub, &object.comdat_entries, value);
                        }
                        wasm_object_push(&sub, &object.comdats, group);
                    }
                    _ => { wasm_read_fail(&sub, WasmReadError.Unsupported); }
                }
            }
        }
        if sub.error == WasmReadError.None && sub.at != sub.bytes.length { wasm_read_fail(&sub, WasmReadError.Encoding); }
        if sub.error != WasmReadError.None {
            reader.error = sub.error; reader.error_offset = offset + sub.error_offset; return;
        }
    }
}

fn wasm_object_relocations(object: WasmObject*, reader: WasmReader*): void {
    var section = wasm_read_index(reader);
    var count = wasm_read_index(reader);
    for (var at: u32 = 0; at < count && reader.error == WasmReadError.None; at++) {
        var relocation: WasmRelocationRecord = { section: section, kind: wasm_read_index(reader), offset: wasm_read_index(reader), index: wasm_read_index(reader), ..default };
        if relocation.kind > convert(u32, WasmRelocation.FunctionIndexI32) { wasm_read_fail(reader, WasmReadError.Unsupported); return; }
        var width = wasm_relocation_addend(convert(WasmRelocation, relocation.kind));
        if width != 0 { relocation.addend = wasm_read_sleb(reader, width); }
        wasm_object_push(reader, &object.relocations, relocation);
    }
}

fn wasm_object_features(object: WasmObject*, reader: WasmReader*): void {
    var used: u8 = 43;
    var disallowed: u8 = 45;
    var required: u8 = 61;
    var count = wasm_read_index(reader);
    for (var at: u32 = 0; at < count && reader.error == WasmReadError.None; at++) {
        var feature: WasmFeatureRecord = { prefix: wasm_read_byte(reader), name: wasm_read_name(reader) };
        if feature.prefix != used && feature.prefix != disallowed && feature.prefix != required {
            wasm_read_fail(reader, WasmReadError.Encoding);
        }
        wasm_object_push(reader, &object.features, feature);
    }
}

import tower;
import wasm_bytes;
import wasm_object_types;

fn wasm_value_type(reader: WasmReader*): u8 {
    var type = wasm_read_byte(reader);
    if type != convert(u8, WasmValueType.I32) && type != convert(u8, WasmValueType.I64)
        && type != convert(u8, WasmValueType.F32) && type != convert(u8, WasmValueType.F64)
        && type != convert(u8, WasmValueType.V128) && type != convert(u8, WasmValueType.FuncRef)
        && type != convert(u8, WasmValueType.ExternRef) { wasm_read_fail(reader, WasmReadError.Unsupported); }
    return type;
}

fn wasm_object_limits(reader: WasmReader*): WasmLimits {
    var limits: WasmLimits = default;
    limits.flags = wasm_read_index(reader);
    var has_maximum = convert(u32, WasmLimitFlag.Maximum);
    var shared = convert(u32, WasmLimitFlag.Shared);
    var memory64 = convert(u32, WasmLimitFlag.Memory64);
    if (limits.flags & ~(has_maximum | shared | memory64)) != 0
        || ((limits.flags & shared) != 0 && (limits.flags & has_maximum) == 0) {
        wasm_read_fail(reader, WasmReadError.Unsupported);
        return limits;
    }
    var width: u64 = (limits.flags & memory64) != 0 ? 64 : 32;
    limits.minimum = wasm_read_uleb(reader, width);
    if (limits.flags & has_maximum) != 0 {
        limits.maximum = wasm_read_uleb(reader, width);
        if limits.maximum < limits.minimum { wasm_read_fail(reader, WasmReadError.Encoding); }
    }
    return limits;
}

fn wasm_object_expression(reader: WasmReader*): WasmBytes {
    var begin = reader.at;
    var opcode = convert(WasmOpcode, wasm_read_byte(reader));
    match opcode {
        WasmOpcode.I32Const => { wasm_read_sleb(reader, 32); }
        WasmOpcode.I64Const => { wasm_read_sleb(reader, 64); }
        WasmOpcode.F32Const => { wasm_read_bytes(reader, 4); }
        WasmOpcode.F64Const => { wasm_read_bytes(reader, 8); }
        WasmOpcode.GlobalGet | WasmOpcode.RefFunc => { wasm_read_index(reader); }
        WasmOpcode.RefNull => { wasm_read_sleb(reader, 33); }
        _ => { wasm_read_fail(reader, WasmReadError.Unsupported); }
    }
    if wasm_read_byte(reader) != convert(u8, WasmOpcode.End) { wasm_read_fail(reader, WasmReadError.Encoding); }
    return init(WasmBytes) { data: reader.bytes.data + begin, length: reader.at - begin };
}

fn wasm_object_offset(reader: WasmReader*): u64 {
    var opcode = wasm_read_byte(reader);
    var result: u64 = 0;
    if opcode == convert(u8, WasmOpcode.I32Const) {
        result = bits(u64, wasm_read_sleb(reader, 32)) & convert(u64, WasmNoIndex);
    } else {
        if opcode == convert(u8, WasmOpcode.I64Const) { result = bits(u64, wasm_read_sleb(reader, 64)); }
        else { wasm_read_fail(reader, WasmReadError.Unsupported); }
    }
    if wasm_read_byte(reader) != convert(u8, WasmOpcode.End) { wasm_read_fail(reader, WasmReadError.Encoding); }
    return result;
}

fn wasm_object_types(object: WasmObject*, reader: WasmReader*): void {
    var count = wasm_read_index(reader);
    for (var at: u32 = 0; at < count && reader.error == WasmReadError.None; at++) {
        var begin = reader.at;
        if wasm_read_byte(reader) != WasmFunctionType { wasm_read_fail(reader, WasmReadError.Unsupported); return; }
        var type: WasmFunctionTypeRecord = default;
        type.parameters = wasm_read_index(reader);
        for (var parameter: u32 = 0; parameter < type.parameters && reader.error == WasmReadError.None; parameter++) { wasm_value_type(reader); }
        type.results = wasm_read_index(reader);
        for (var result: u32 = 0; result < type.results && reader.error == WasmReadError.None; result++) { wasm_value_type(reader); }
        type.bytes = init(WasmBytes) { data: reader.bytes.data + begin, length: reader.at - begin };
        wasm_object_push(reader, &object.types, type);
    }
}

fn wasm_object_global(reader: WasmReader*): WasmGlobalRecord {
    var global: WasmGlobalRecord = default;
    global.type = wasm_value_type(reader);
    var mutable = wasm_read_byte(reader);
    if mutable > 1 { wasm_read_fail(reader, WasmReadError.Encoding); }
    global.mutable = mutable != 0;
    return global;
}

fn wasm_object_imports(object: WasmObject*, reader: WasmReader*): void {
    var count = wasm_read_index(reader);
    for (var at: u32 = 0; at < count && reader.error == WasmReadError.None; at++) {
        var module = wasm_read_name(reader);
        var name = wasm_read_name(reader);
        var kind = convert(WasmExternal, wasm_read_byte(reader));
        match kind {
            WasmExternal.Function => {
                var function: WasmFunctionRecord = { type_index: wasm_read_index(reader), imported: true, module: module, name: name, ..default };
                wasm_object_push(reader, &object.functions, function);
                object.imported_functions++;
            }
            WasmExternal.Table => {
                var table: WasmTableRecord = { type: wasm_value_type(reader), limits: wasm_object_limits(reader), imported: true, module: module, name: name };
                wasm_object_push(reader, &object.tables, table);
            }
            WasmExternal.Memory => {
                var memory: WasmMemoryRecord = { limits: wasm_object_limits(reader), imported: true, module: module, name: name };
                wasm_object_push(reader, &object.memories, memory);
            }
            WasmExternal.Global => {
                var global = wasm_object_global(reader);
                global.imported = true; global.module = module; global.name = name;
                wasm_object_push(reader, &object.globals, global);
            }
            WasmExternal.Tag => {
                if wasm_read_byte(reader) != 0 { wasm_read_fail(reader, WasmReadError.Encoding); }
                var tag: WasmTagRecord = { type_index: wasm_read_index(reader), imported: true, module: module, name: name };
                wasm_object_push(reader, &object.tags, tag);
            }
            _ => { wasm_read_fail(reader, WasmReadError.Unsupported); }
        }
    }
}

fn wasm_object_functions(object: WasmObject*, reader: WasmReader*): void {
    var count = wasm_read_index(reader);
    for (var at: u32 = 0; at < count && reader.error == WasmReadError.None; at++) {
        var function: WasmFunctionRecord = { type_index: wasm_read_index(reader), ..default };
        wasm_object_push(reader, &object.functions, function);
    }
}

fn wasm_object_code(object: WasmObject*, reader: WasmReader*): void {
    var count = wasm_read_index(reader);
    if convert(usize, count) != object.functions.length - convert(usize, object.imported_functions) {
        wasm_read_fail(reader, WasmReadError.Encoding); return;
    }
    for (var at: u32 = 0; at < count && reader.error == WasmReadError.None; at++) {
        var size = wasm_read_index(reader);
        var function = &object.functions.data[convert(usize, object.imported_functions) + convert(usize, at)];
        function.code_offset = convert(u32, reader.at);
        function.code = wasm_read_bytes(reader, convert(usize, size));
        if function.code.length == 0 || function.code.data[function.code.length - 1] != convert(u8, WasmOpcode.End) {
            wasm_read_fail(reader, WasmReadError.Encoding);
        }
    }
}

fn wasm_object_data(object: WasmObject*, reader: WasmReader*): void {
    var count = wasm_read_index(reader);
    for (var at: u32 = 0; at < count && reader.error == WasmReadError.None; at++) {
        var data: WasmDataRecord = default;
        var mode = wasm_read_index(reader);
        if mode > 2 { wasm_read_fail(reader, WasmReadError.Unsupported); return; }
        data.passive = mode == 1;
        if mode == 2 { data.memory = wasm_read_index(reader); }
        if !data.passive { data.initial_offset = wasm_object_offset(reader); }
        var size = wasm_read_index(reader);
        data.section_offset = convert(u32, reader.at);
        data.bytes = wasm_read_bytes(reader, convert(usize, size));
        wasm_object_push(reader, &object.data, data);
    }
}

fn wasm_object_elements(object: WasmObject*, reader: WasmReader*): void {
    var count = wasm_read_index(reader);
    for (var at: u32 = 0; at < count && reader.error == WasmReadError.None; at++) {
        var mode = wasm_read_index(reader);
        // Relocatable LLVM objects describe active function-table slots.
        // Passive/declarative reference expressions require a separate contract.
        if mode != 0 && mode != 2 { wasm_read_fail(reader, WasmReadError.Unsupported); return; }
        var table: u32 = 0;
        if mode == 2 { table = wasm_read_index(reader); }
        var offset = wasm_object_offset(reader);
        if mode == 2 && wasm_read_byte(reader) != 0 { wasm_read_fail(reader, WasmReadError.Encoding); return; }
        var functions = wasm_read_index(reader);
        for (var function: u32 = 0; function < functions && reader.error == WasmReadError.None; function++) {
            var entry: WasmElementRecord = { table: table, offset: offset + convert(u64, function), function: wasm_read_index(reader) };
            if entry.offset < offset { wasm_read_fail(reader, WasmReadError.Integer); return; }
            wasm_object_push(reader, &object.elements, entry);
        }
    }
}

fn wasm_object_standard(object: WasmObject*, reader: WasmReader*, kind: u8): void {
    var section = convert(WasmSection, kind);
    match section {
        WasmSection.Type => { wasm_object_types(object, reader); }
        WasmSection.Import => { wasm_object_imports(object, reader); }
        WasmSection.Function => { wasm_object_functions(object, reader); }
        WasmSection.Code => { wasm_object_code(object, reader); }
        WasmSection.Data => { wasm_object_data(object, reader); }
        WasmSection.Element => { wasm_object_elements(object, reader); }
        WasmSection.Start => { object.start = wasm_read_index(reader); }
        WasmSection.DataCount => { object.data_count = wasm_read_index(reader); }
        _ => {
            var count = wasm_read_index(reader);
            for (var at: u32 = 0; at < count && reader.error == WasmReadError.None; at++) {
                match section {
                    WasmSection.Table => {
                        var table: WasmTableRecord = { type: wasm_value_type(reader), limits: wasm_object_limits(reader), ..default };
                        wasm_object_push(reader, &object.tables, table);
                    }
                    WasmSection.Memory => {
                        var memory: WasmMemoryRecord = { limits: wasm_object_limits(reader), ..default };
                        wasm_object_push(reader, &object.memories, memory);
                    }
                    WasmSection.Global => {
                        var global = wasm_object_global(reader);
                        global.expression = wasm_object_expression(reader);
                        wasm_object_push(reader, &object.globals, global);
                    }
                    WasmSection.Tag => {
                        if wasm_read_byte(reader) != 0 { wasm_read_fail(reader, WasmReadError.Encoding); }
                        var tag: WasmTagRecord = { type_index: wasm_read_index(reader), ..default };
                        wasm_object_push(reader, &object.tags, tag);
                    }
                    WasmSection.Export => {
                        var exported: WasmExportRecord = { name: wasm_read_name(reader), kind: wasm_read_byte(reader), index: wasm_read_index(reader) };
                        wasm_object_push(reader, &object.exports, exported);
                    }
                    _ => { wasm_read_fail(reader, WasmReadError.Unsupported); }
                }
            }
        }
    }
}

import tower;
import wasm_bytes;
import .library.vector;

enum WasmSection: u8 {
    Custom = 0, Type = 1, Import = 2, Function = 3, Table = 4, Memory = 5,
    Global = 6, Export = 7, Start = 8, Element = 9, Code = 10, Data = 11,
    DataCount = 12, Tag = 13
}
enum WasmExternal: u8 { Function = 0, Table = 1, Memory = 2, Global = 3, Tag = 4 }
enum WasmSymbolKind: u8 { Function = 0, Data = 1, Global = 2, Section = 3, Tag = 4, Table = 5 }
enum WasmSymbolFlag: u32 {
    Weak = 1, Local = 2, Hidden = 4, Undefined = 16, Exported = 32,
    ExplicitName = 64, NoStrip = 128, ThreadLocal = 256, Absolute = 512
}
enum WasmLinkingSection: u8 { Segments = 5, Initializers = 6, Comdats = 7, Symbols = 8 }
enum WasmSegmentFlag: u32 { Strings = 1, ThreadLocal = 2, Retain = 4 }
enum WasmComdatKind: u8 { Data = 0, Function = 1, Global = 2, Tag = 3, Table = 4, Section = 5 }
enum WasmFeaturePrefix: u8 { Used = 43, Disallowed = 45, Required = 61 }
enum WasmLimitFlag: u32 { Maximum = 1, Shared = 2, Memory64 = 4 }
enum WasmOpcode: u8 {
    Unreachable = 0, Block = 2, Loop = 3, If = 4, Else = 5, End = 11,
    Branch = 12, BranchIf = 13, Call = 16, Drop = 26, LocalGet = 32, GlobalGet = 35, GlobalSet = 36, I32Store = 54,
    I32Const = 65, I64Const = 66, F32Const = 67, F64Const = 68,
    I32Eqz = 69, I32Eq = 70, I32Add = 106, RefNull = 208, RefFunc = 210,
    BulkMemory = 252, Atomic = 254
}
enum WasmAtomicOpcode: u32 { Notify = 0, Wait32 = 1, I32Load = 16, I32Store = 23, I32Add = 30, I32CompareExchange = 72 }
enum WasmBulkOpcode: u32 { MemoryInit = 8, DataDrop = 9, MemoryFill = 11 }
enum WasmDataMode: u32 { Active = 0, Passive = 1 }
var WasmEmptyBlock: u8 = 64;
var WasmAtomic32Alignment: u64 = 2;
enum WasmValueType: u8 { I32 = 127, I64 = 126, F32 = 125, F64 = 124, V128 = 123, FuncRef = 112, ExternRef = 111 }
var WasmFunctionType: u8 = 96;
var WasmNoIndex: u32 = 4294967295;
var WasmLinkingVersion: u32 = 2;
var WasmPageBytes: u64 = 65536;

struct WasmObjectSection { kind: u8; bytes: WasmBytes; name: WasmBytes; file_offset: usize; content_offset: usize; }
struct WasmFunctionTypeRecord { bytes: WasmBytes; parameters: u32; results: u32; }
struct WasmFunctionRecord {
    type_index: u32; imported: bool; module: WasmBytes; name: WasmBytes;
    code: WasmBytes; code_offset: u32;
}
struct WasmLimits { flags: u32; minimum: u64; maximum: u64; }
struct WasmTableRecord { type: u8; limits: WasmLimits; imported: bool; module: WasmBytes; name: WasmBytes; }
struct WasmMemoryRecord { limits: WasmLimits; imported: bool; module: WasmBytes; name: WasmBytes; }
struct WasmGlobalRecord { type: u8; mutable: bool; imported: bool; module: WasmBytes; name: WasmBytes; expression: WasmBytes; }
struct WasmTagRecord { type_index: u32; imported: bool; module: WasmBytes; name: WasmBytes; }
struct WasmExportRecord { kind: u8; index: u32; name: WasmBytes; }
struct WasmElementRecord { table: u32; offset: u64; function: u32; }
struct WasmDataRecord {
    bytes: WasmBytes; name: WasmBytes; section_offset: u32;
    memory: u32; initial_offset: u64; passive: bool; alignment: u32; flags: u32;
}
struct WasmSymbolRecord { kind: u8; flags: u32; name: WasmBytes; index: u32; offset: u64; size: u64; called_directly: bool; }
struct WasmRelocationRecord { section: u32; kind: u32; offset: u32; index: u32; addend: i64; }
struct WasmInitializerRecord { priority: u32; symbol: u32; }
struct WasmComdatEntry { kind: u8; index: u32; }
struct WasmComdatRecord { name: WasmBytes; first: usize; count: usize; }
struct WasmFeatureRecord { prefix: u8; name: WasmBytes; }

// One worker-owned input component. All spans borrow the same pinned input;
// dense vectors are indexes of platform-object records, never a semantic IR.
struct WasmObject {
    bytes: WasmBytes;
    sections: vector(WasmObjectSection);
    types: vector(WasmFunctionTypeRecord);
    functions: vector(WasmFunctionRecord);
    tables: vector(WasmTableRecord);
    memories: vector(WasmMemoryRecord);
    globals: vector(WasmGlobalRecord);
    tags: vector(WasmTagRecord);
    exports: vector(WasmExportRecord);
    elements: vector(WasmElementRecord);
    data: vector(WasmDataRecord);
    symbols: vector(WasmSymbolRecord);
    relocations: vector(WasmRelocationRecord);
    // Derived validated owner row, parallel to relocations. Custom/debug
    // relocations use WasmNoIndex; original platform records stay unchanged.
    relocation_chunks: vector(u32);
    initializers: vector(WasmInitializerRecord);
    comdats: vector(WasmComdatRecord);
    comdat_entries: vector(WasmComdatEntry);
    features: vector(WasmFeatureRecord);
    imported_functions: u32;
    code_section: u32;
    data_section: u32;
    start: u32;
    data_count: u32;
    linking: bool;
    linking_sections: u32;
    error: WasmReadError;
    error_offset: usize;
}

fn wasm_object_dispose(object: WasmObject*): void {
    vector_dispose(&object.sections); vector_dispose(&object.types);
    vector_dispose(&object.functions); vector_dispose(&object.tables);
    vector_dispose(&object.memories); vector_dispose(&object.globals);
    vector_dispose(&object.tags); vector_dispose(&object.exports);
    vector_dispose(&object.elements); vector_dispose(&object.data);
    vector_dispose(&object.symbols); vector_dispose(&object.relocations); vector_dispose(&object.relocation_chunks);
    vector_dispose(&object.initializers); vector_dispose(&object.comdats);
    vector_dispose(&object.comdat_entries); vector_dispose(&object.features);
    *object = default;
}

fn wasm_object_push(T: type, reader: WasmReader*, list: vector(T)*, value: T): bool {
    if reader.error != WasmReadError.None { return false; }
    if !vector_push(list, value) { wasm_read_fail(reader, WasmReadError.Allocation); return false; }
    return true;
}

fn wasm_object_error(object: WasmObject*, reader: WasmReader*, base: usize): void {
    if object.error == WasmReadError.None && reader.error != WasmReadError.None {
        object.error = reader.error;
        object.error_offset = base + reader.error_offset;
    }
}

// This bedrock.tower is loaded first, then foundation.tower.
// GrammarPattern reads /patterns/ for token and skip rules.
// GrammarTemplate reads {replacement bodies} with balanced braces.
skip Whitespace = /[ \t\r\n]+/;
[comment] skip LineComment = /\/\/[^\r\n]*/;
[comment] skip BlockComment = /\/\*([^*]|\*+[^*/])*\*+\//;
[identifier] token Identifier = /[A-Za-z_][A-Za-z0-9_]*|`([^`\\\r\n]|\\[nrt\\`])*`/;
[string] token String = /"([^"\\\r\n]|\\[nrt\\'"])*"|'([^'\\\r\n]|\\[nrt\\'"])*'/;
[contextual][pattern] token GrammarPattern = /\/([^/\\\[\r\n]|\\[^\r\n]|\[([^\\\]\r\n]|\\[^\r\n])*\])*\//;
[contextual][operator] token GrammarCharacter = /[^{}\r\n]/;
[contextual][number] token AttributeInteger = /[0-9]+/;
parse Attributes = $list:AttributeList | ;
parse AttributeList = $previous:AttributeList $attribute:Attribute | $attribute:Attribute;
parse Attribute = '[' $name:Identifier ']' | '[' $name:Identifier '(' $args:AttributeArguments ')' ']';
parse AttributeArguments = $previous:AttributeArguments ',' $argument:AttributeArgument | $argument:AttributeArgument;
parse AttributeArgument = $name:Identifier | $string:String | $integer:AttributeInteger;
parse GrammarDeclaration = $attributes:Attributes 'parse' $name:Identifier $op:GrammarAssignment $alternatives:GrammarAlternatives $replacement:GrammarReplacement ';';
parse GrammarTemplate = '{' GrammarTemplateItems '}';
parse GrammarTemplateItems = GrammarTemplateItems GrammarTemplateItem | ;
parse GrammarTemplateItem = GrammarTemplate | [^'{' '}'] | GrammarCharacter;
parse GrammarTokenDeclaration = $attributes:Attributes 'token' $name:Identifier '=' $pattern:GrammarPattern $mode:GrammarTokenMode $style:GrammarStyle ';';
parse GrammarSkipDeclaration = $attributes:Attributes 'skip' $name:Identifier '=' $pattern:GrammarPattern $mode:GrammarTokenMode $style:GrammarStyle ';';
parse GrammarTokenMode = | 'when' 'expected';
parse GrammarAssignment = '=' | '|=';
parse GrammarReplacement = | '=>' 'replace' $body:GrammarTemplate;
parse GrammarAlternatives = $previous:GrammarAlternatives '|' $sequence:GrammarSequence
                           | $sequence:GrammarSequence;
parse GrammarSequence = $previous:GrammarSequence $term:GrammarTerm | ;
parse GrammarTerm = $atom:GrammarAtom $suffix:GrammarSuffix;
parse GrammarSuffix = '*' | '+' | '?' | ;
parse GrammarAtom = $literal:String | $reference:Identifier | '$' $capture:Identifier
                   | '$' $capture:Identifier ':' $reference:Identifier | '[^' $set:GrammarTokenSet ']';
parse GrammarTokenSet = $previous:GrammarTokenSet $literal:String | ;
parse GrammarStyle = | 'as' $kind:Identifier;
parse ImportPath = $previous:ImportPath '.' $segment:Identifier | $segment:Identifier;
parse ImportName = '.' $parent:ImportName | $segments:ImportPath;
parse ImportDeclaration = 'import' $name:ImportName ';' | 'import' $name:String ';'
                         | 'import' $name:ImportName 'as' $alias:Identifier ';'
                         | 'import' $name:String 'as' $alias:Identifier ';';

// Optional production binding power. Larger numbers bind more tightly.
// Ordinary recursive/chained grammars need no annotation.
[contextual][number] token GrammarPrecedenceNumber = /[0-9]+/;
[contextual][keyword] token GrammarAssociativity = /left|right|nonassoc|L>R|R<L/;
parse GrammarPrecedence = | '@' $level:GrammarPrecedenceNumber $direction:GrammarAssociativity;
parse GrammarDeclaration = $attributes:Attributes 'parse' $name:Identifier $op:GrammarAssignment $alternatives:GrammarAlternatives $precedence:GrammarPrecedence $replacement:GrammarReplacement ';';

import tower;
import lr_types;
import lexer_table;
import syntax_types;
import .library.vector;

// Derived automata over integer symbols, shared by character and token grammars.
// The source grammar/entities remain authoritative. Limits bound compilation work.
struct AutomatonState {
    kind: u32;
    out: i32;
    other: i32;
    negated: bool;
    ranges: vector(SymbolRange);
}

struct Automaton {
    states: AutomatonState*;
    count: usize;
    limit: u32;
    error: u32;
}

struct AutomatonSubset {
    bits: u64[8];
}

struct AutomatonWork {
    masks: u64[64];
    visited: u8[512];
    pending: i32[1024];
    seeds: i32[512];
    subsets: vector(AutomatonSubset);
    links: vector(i32);
    buckets: i32[2039];
    row: vector(i32);
    alphabet: vector(u32);
}

export fn automaton_create(symbol_limit: u32): Automaton* {
    var result = alloc(Automaton, 1);
    var failed = result == null;
    if failed {
        return null;
    }
    *result = default;
    result.states = alloc(AutomatonState, 512);
    failed = result.states == null;
    if failed {
        free(result);
        return null;
    }
    var bytes = sizeof(AutomatonState) *512;
    fill(result.states, 0, bytes);
    result.limit = symbol_limit;
    return result;
}

export fn automaton_destroy(value: Automaton*): void {
    if value == null {
        return;
    }
    var i: usize = 0;
    for(; i != value.count; i++) {
        vector_dispose(&value.states[i].ranges);
    }
    free(value.states);
    free(value);
}

export fn automaton_error(value: Automaton*): u32 {
    return value.error;
}

// Kinds: 0 = consuming range, 1 = epsilon split, 2 = accepting state.
export fn automaton_add(value: Automaton*, kind: u32, out: i32, other: i32, negated: bool): i32 {
    if value.count >= 512 {
        value.error = 1;
        return -1;
    }
    var index = value.count;
    value.states[index].kind = kind;
    value.states[index].out = out;
    value.states[index].other = other;
    value.states[index].negated = negated;
    value.count = index + 1;
    return convert(i32, index);
}

export fn automaton_range(value: Automaton*, index: i32, first: u32, last: u32): bool {
    if index < 0 {
        return false;
    }
    var state = &value.states[index];
    var size = state.ranges.length + 1;
    var ok = vector_reserve(&state.ranges, size);
    if ok {
        state.ranges.data[state.ranges.length].first = first;
        state.ranges.data[state.ranges.length].last = last;
        state.ranges.length = size;
    } else {
        value.error = 2;
    }
    return ok;
}

export fn automaton_patch(value: Automaton*, index: i32, other: bool, target: i32): void {
    if index < 0 {
        return;
    }
    if other {
        value.states[index].other = target;
    }
    else {
        value.states[index].out = target;
    }
}

fn automaton_sift(values: u32*, size: usize, start: usize): void {
    var root = start;
    loop {
        var child = root *2;
        child++;
        if child >= size {
            return;
        }
        var right = child + 1;
        if right < size {
            if values[right] > values[child] {
                child = right;
            }
        }
        if values[root] >= values[child] {
            return;
        }
        var saved = values[root];
        values[root] = values[child];
        values[child] = saved;
        root = child;
    }
}

fn automaton_sort(values: u32*, size: usize): void {
    var start = size / 2;
    loop {
        var done = start == 0;
        if done {
            break;
        }
        start--;
        automaton_sift(values, size, start);
    }
    var end = size;
    loop {
        var done = end <= 1;
        if done {
            return;
        }
        end--;
        var saved = values[0];
        values[0] = values[end];
        values[end] = saved;
        automaton_sift(values, end, 0);
    }
}

fn automaton_has(work: AutomatonWork*, subset: AutomatonSubset*, index: usize): bool {
    var word = index / 64;
    var bit = index % 64;
    var masked = subset.bits[word] &work.masks[bit];
    var present = masked != 0;
    return present;
}

fn automaton_closure(value: Automaton*, work: AutomatonWork*, count: usize, result: AutomatonSubset*): bool {
    *result = default;
    fill(&work.visited, 0, value.count);
    var bytes = count *sizeof(i32);
    copy(&work.pending, &work.seeds, bytes);
    var any = false;
    loop {
        if count == 0 {
            return any;
        }
        count--;
        var index = work.pending[count];
        if index < 0 {
            continue;
        }
        if work.visited[index] != 0 {
            continue;
        }
        work.visited[index] = 1;
        var state = &value.states[index];
        if state.kind == 1 {
            work.pending[count] = state.out;
            count++;
            work.pending[count] = state.other;
            count++;
        } else {
            var word = index / 64;
            var bit = index % 64;
            result.bits[word] = result.bits[word] | work.masks[bit];
            any = true;
        }
    }
}

fn automaton_intern(value: Automaton*, work: AutomatonWork*, subset: AutomatonSubset*): i32 {
    var hash: u64 = 2166136261;
    var words = value.count + 63;
    words = words / 64;
    var i: usize = 0;
    for(; i != words; i++) {
        hash = hash ^ subset.bits[i];
        hash = hash * 16777619;
    }
    var bucket = hash % 2039;
    var found = work.buckets[bucket];
    loop {
        var done = found < 0;
        if done {
            break;
        }
        var same = true;
        i = 0;
        loop {
            done = i == words;
            if done {
                break;
            }
            if subset.bits[i] != work.subsets.data[found].bits[i] {
                same = false;
                break;
            }
            i++;
        }
        if same {
            return found;
        }
        found = work.links.data[found];
    }
    var index = work.subsets.length;
    var count = index + 1;
    var complexity = count *work.alphabet.length;
    var large = index >= 1024;
    if large {
        value.error = 3;
        return -1;
    }
    large = complexity > 262144;
    if large {
        value.error = 3;
        return -1;
    }
    var ok = vector_reserve(&work.subsets, count);
    if !ok {
        value.error = 2;
        return -1;
    }
    ok = vector_push(&work.links, work.buckets[bucket]);
    if !ok {
        value.error = 2;
        return -1;
    }
    var result = convert(i32, index);
    copy(&work.subsets.data[result], subset, sizeof(AutomatonSubset));
    work.subsets.length = count;
    work.buckets[bucket] = result;
    return result;
}

fn automaton_build(value: Automaton*, start: i32, accepting: usize, table: LexerTable*, work: AutomatonWork*, reject_empty: bool): u32 {
    var failed = value.error != 0;
    if failed {
        return value.error;
    }
    var mask: u64 = 1;
    var i: usize = 0;
    for(; i != 64; i++) {
        work.masks[i] = mask;
        mask = mask * 2;
    }
    var bucket_bytes = sizeof(i32) *2039;
    fill(&work.buckets, 255, bucket_bytes);
    var count: usize = 2;
    i = 0;
    for(; i != value.count; i++) {
        var ranges = value.states[i].ranges.length *2;
        count = count + ranges;
    }
    var ok = vector_reserve(&work.alphabet, count);
    if !ok {
        return 2;
    }
    work.alphabet.data[0] = 0;
    work.alphabet.data[1] = value.limit;
    count = 2;
    i = 0;
    loop {
        var done = i == value.count;
        if done {
            break;
        }
        var state = &value.states[i];
        var j: usize = 0;
        loop {
            done = j == state.ranges.length;
            if done {
                break;
            }
            work.alphabet.data[count] = state.ranges.data[j].first;
            count++;
            work.alphabet.data[count] = state.ranges.data[j].last + 1;
            count++;
            j++;
        }
        i++;
    }
    automaton_sort(work.alphabet.data, count);
    work.alphabet.length = 1;
    i = 1;
    for(; i != count; i++) {
        var previous = i -1;
        if work.alphabet.data[i] != work.alphabet.data[previous] {
            work.alphabet.data[work.alphabet.length] = work.alphabet.data[i];
            work.alphabet.length++;
        }
    }
    ok = lex_table_set_alphabet(table, work.alphabet.data, work.alphabet.length);
    if !ok {
        return 2;
    }
    work.seeds[0] = start;
    var initial: AutomatonSubset;
    automaton_closure(value, work, 1, &initial);
    var nullable = automaton_has(work, &initial, accepting);
    if reject_empty {
        if nullable {
            return 4;
        }
    }
    var first = automaton_intern(value, work, &initial);
    failed = first < 0;
    if failed {
        return value.error;
    }
    var columns = work.alphabet.length -1;
    ok = vector_reserve(&work.row, columns);
    if !ok {
        return 2;
    }
    var row: usize = 0;
    loop {
        var done = row == work.subsets.length;
        if done {
            return 0;
        }
        var accepted = automaton_has(work, &work.subsets.data[row], accepting);
        var column: usize = 0;
        loop {
            done = column == columns;
            if done {
                break;
            }
            var symbol = work.alphabet.data[column];
            var seeds: usize = 0;
            i = 0;
            loop {
                done = i == value.count;
                if done {
                    break;
                }
                var present = automaton_has(work, &work.subsets.data[row], i);
                var state = &value.states[i];
                var character = state.kind == 0;
                if present {
                    if character {
                        var inside = false;
                        var j: usize = 0;
                        loop {
                            done = j == state.ranges.length;
                            if done {
                                break;
                            }
                            var above = symbol >= state.ranges.data[j].first;
                            var below = symbol <= state.ranges.data[j].last;
                            if above {
                                if below {
                                    inside = true;
                                    break;
                                }
                            }
                            j++;
                        }
                        if inside != state.negated {
                            work.seeds[seeds] = state.out;
                            seeds++;
                        }
                    }
                }
                i++;
            }
            var subset: AutomatonSubset;
            var nonempty = automaton_closure(value, work, seeds, &subset);
            var next: i32 = -1;
            if nonempty {
                next = automaton_intern(value, work, &subset);
                failed = next < 0;
                if failed {
                    return value.error;
                }
            }
            work.row.data[column] = next;
            column++;
        }
        ok = lex_table_append(table, work.row.data, columns, accepted);
        if !ok {
            return 2;
        }
        row++;
    }
}

// Returns 0 on success, 1 for NFA size, 2 allocation, 3 DFA size, 4 nullable.
export fn automaton_compile(value: Automaton*, start: i32, accepting: usize, table: LexerTable*, reject_empty: bool): u32 {
    var work = alloc(AutomatonWork, 1);
    if work == null {
        return 2;
    }
    *work = default;
    var result = automaton_build(value, start, accepting, table, work, reject_empty);
    vector_dispose(&work.subsets);
    vector_dispose(&work.links);
    vector_dispose(&work.row);
    vector_dispose(&work.alphabet);
    free(work);
    return result;
}

import tower;
import fast_interpreter;
import interpreter;

var BytecodeContainerVersion: u64 = 1;
var BytecodeSemanticsVersion: u64 = 6;
var BytecodeExecutionCacheVersion: u64 = 5;

// .towerbc v1: portable, versioned distribution envelope. Canonical Foundation
// is the semantic authority; packed words/constants are a verified execution
// cache. A loader rebuilds the graph and checks the cache before any execution.
// This makes reconstruction exact without inventing a second type/binding ABI.
// All integer fields and payload words are little endian, regardless of host.
fn bc_read(data: u8*, at: usize, size: usize): u64 {
    var result: u64 = 0;
    var factor: u64 = 1;
    var i: usize = 0;
    loop {
        if i == size {
            return result;
        }
        var index = at + i;
        var byte = convert(u64, data[index]);
        byte = byte * factor;
        result = result | byte;
        factor = factor * 256;
        i++;
    }
}

fn bc_write(data: u8*, at: usize, value: u64, size: usize): void {
    var i: usize = 0;
    loop {
        if i == size {
            return;
        }
        var index = at + i;
        data[index] = im_byte(value);
        value = value / 256;
        i++;
    }
}

fn bc_checksum(data: u8*, length: usize): u64 {
    // FNV-1a detects corruption; it is not authentication. The cache comparison
    // against freshly checked Foundation, not this hash, validates instructions.
    var hash: u64 = 14695981039346656037;
    var i: usize = 0;
    loop {
        if i == length {
            return hash;
        }
        var byte: u64 = 0;
        var prefix = i < 48;
        var payload = i >= 56;
        if im_or(prefix, payload) {
            byte = convert(u64, data[i]);
        }
        hash = hash ^ byte;
        hash = hash * 1099511628211;
        i++;
    }
}

export fn bytecode_validate(data: u8*, length: usize): u32 {
    if length < 56 {
        return 1;
    }
    if length > 268435456 {
        return 1;
    }
    var magic = "TOWERBC";
    for(var i: usize = 0; i != 8; i++) {
        if data[i] != magic[i] {
            return 2;
        }
    }
    var version = bc_read(data, 8, 4) != BytecodeContainerVersion;
    if version {
        return 3;
    }
    version = bc_read(data, 12, 4) != BytecodeSemanticsVersion;
    if version {
        return 4;
    }
    version = bc_read(data, 16, 4) != BytecodeExecutionCacheVersion;
    if version {
        return 5;
    }
    var width = bc_read(data, 20, 4);
    var invalid = width != 4;
    var not64 = width != 8;
    invalid = im_and(invalid, not64);
    if invalid {
        return 6;
    }
    invalid = bc_read(data, 24, 4) > 2;
    if invalid {
        return 7;
    }
    invalid = bc_read(data, 44, 4) != 0;
    if invalid {
        return 7;
    }
    var source = bc_read(data, 28, 4);
    invalid = source > 8388608;
    if invalid {
        return 1;
    }
    var words = bc_read(data, 32, 4);
    words = words * 4;
    var constants = bc_read(data, 36, 4);
    constants = constants * 8;
    var total = source + words;
    total = total + constants;
    total = total + 56;
    invalid = total != convert(u64, length);
    if invalid {
        return 1;
    }
    invalid = bc_read(data, 40, 4) != total;
    if invalid {
        return 1;
    }
    var checksum = bc_checksum(data, length);
    invalid = bc_read(data, 48, 8) != checksum;
    if invalid {
        return 8;
    }
    return 0;
}

export fn bytecode_error(code: u32): u8* {
    var selected = code == 1;
    if selected {
        return "Invalid .towerbc length or section bounds";
    }
    selected = code == 2;
    if selected {
        return "Invalid .towerbc magic";
    }
    selected = code == 3;
    if selected {
        return "Unsupported .towerbc container version";
    }
    selected = code == 4;
    if selected {
        return "Unsupported .towerbc semantics version";
    }
    selected = code == 5;
    if selected {
        return "Unsupported .towerbc cache version";
    }
    selected = code == 6;
    if selected {
        return "Unsupported .towerbc target layout";
    }
    selected = code == 7;
    if selected {
        return "Unsupported .towerbc optimization profile or flags";
    }
    selected = code == 8;
    if selected {
        return ".towerbc checksum mismatch";
    }
    return ".towerbc cache disagrees with checked Foundation";
}

export fn bytecode_source_size(data: u8*): usize {
    return convert(usize, bc_read(data, 28, 4));
}

export fn bytecode_pointer_bytes(data: u8*): usize {
    return convert(usize, bc_read(data, 20, 4));
}

export fn bytecode_encode(f: FMState*, source: u8*, source_size: usize, width: usize, profile: u32, length: usize*): u8* {
    if profile > 2 {
        return null;
    }
    var words = f.words.length *4;
    var constants = f.constants.length *8;
    var total = source_size + words;
    total = total + constants;
    total = total + 56;
    var invalid = source_size > 8388608;
    var large = total > 268435456;
    invalid = im_or(invalid, large);
    if invalid {
        *length = 0;
        return null;
    }
    var data = alloc(u8, total);
    if data == null {
        *length = 0;
        return null;
    }
    fill(data, 0, 56);
    copy(data, "TOWERBC", 8);
    bc_write(data, 8, BytecodeContainerVersion, 4);
    bc_write(data, 12, BytecodeSemanticsVersion, 4);
    bc_write(data, 16, BytecodeExecutionCacheVersion, 4);
    bc_write(data, 20, convert(u64, width), 4);
    bc_write(data, 24, convert(u64, profile), 4);
    bc_write(data, 28, convert(u64, source_size), 4);
    bc_write(data, 32, convert(u64, f.words.length), 4);
    bc_write(data, 36, convert(u64, f.constants.length), 4);
    bc_write(data, 40, convert(u64, total), 4);
    copy(&data[56], source, source_size);
    var at = source_size + 56;
    var i: usize = 0;
    for(; i != f.words.length; i++) {
        bc_write(data, at, convert(u64, f.words.data[i]), 4);
        at = at + 4;
    }
    i = 0;
    for(; i != f.constants.length; i++) {
        bc_write(data, at, f.constants.data[i], 8);
        at = at + 8;
    }
    bc_write(data, 48, bc_checksum(data, total), 8);
    *length = total;
    return data;
}

export fn bytecode_free(data: u8*): void {
    free(data);
}

export fn bytecode_matches(f: FMState*, data: u8*): bool {
    var different = bc_read(data, 32, 4) != convert(u64, f.words.length);
    if different {
        return false;
    }
    different = bc_read(data, 36, 4) != convert(u64, f.constants.length);
    if different {
        return false;
    }
    var at = bytecode_source_size(data);
    at = at + 56;
    var i: usize = 0;
    for(; i != f.words.length; i++) {
        different = bc_read(data, at, 4) != convert(u64, f.words.data[i]);
        if different {
            return false;
        }
        at = at + 4;
    }
    i = 0;
    loop {
        if i == f.constants.length {
            return true;
        }
        different = bc_read(data, at, 8) != f.constants.data[i];
        if different {
            return false;
        }
        at = at + 8;
        i++;
    }
}

import tower;
import c_emitter;
import foundation_tags;
import semantic_context;

// Monotone reachability over the existing entities. Incoming jumps may expose
// another label on the next pass; no independent instruction graph is created.
fn ce_reach(c: CEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if n == null {
        return;
    }
    var index = ce_id(c, entity);
    if c.active.data[index] == false {
        c.active.data[index] = true;
        c.changed = true;
    }
    if n.kind == KIf {
        var condition = sem_get(n.value);
        if condition.constant {
            if condition.bits != 0 {
                ce_reach(c, n.body);
            } else {
                ce_reach(c, n.otherwise);
            }
        } else {
            ce_reach(c, n.body);
            ce_reach(c, n.otherwise);
        }
        return;
    }
    if n.kind == KLoop {
        ce_reach(c, n.body);
        return;
    }
    var list = n.kind == KBlock;
    if n.kind == KProgram {
        list = true;
    }
    if list {
        var falls = true;
        foreach(var child in &n.items) {
            var item = sem_get(child);
            if item.kind == KLabel {
                if ce_label_used(c, child) {
                    falls = true;
                }
            }
            if falls {
                ce_reach(c, child);
                falls = ce_falls(c, child);
            }
        }
    }
}

fn ce_reach_pass(c: CEmitter*, root: void*): void {
    loop {
        c.changed = false;
        ce_reach(c, root);
        foreach(var & node in &c.nodes) {
            var n = sem_get(*node);
            if n.kind == KFunction {
                ce_reach(c, n.body);
            }
        }
        if !c.changed {
            break;
        }
    }
}

fn ce_reachable(c: CEmitter*, root: void*): void {
    // Propagate functions which cannot return (for example an optimized trap).
    // Rebuild statement reachability after each refinement, so no manufactured
    // return remains after a call which MSVC correctly recognizes as terminal.
    loop {
        var i: usize = 0;
        for(; i != c.nodes.length; i++) {
            c.active.data[i] = false;
        }
        ce_reach_pass(c, root);
        var changed = false;
        i = 0;
        for(; i != c.nodes.length; i++) {
            var entity = c.nodes.data[i];
            var n = sem_get(entity);
            var function = n.kind == KFunction;
            if n.external {
                function = false;
            }
            if function {
                var returns = ce_falls(c, n.body);
                for(var j: usize = 0; j != c.nodes.length; j++) {
                    if c.owners.data[j] == entity {
                        var item = sem_get(c.nodes.data[j]);
                        var returning = item.kind == KReturn;
                        if returning {
                            if c.active.data[j] {
                                returns = true;
                            }
                        }
                    }
                }
                if c.returning.data[i] != returns {
                    c.returning.data[i] = returns;
                    changed = true;
                }
            }
        }
        if !changed {
            break;
        }
    }
}

// Even when a constant branch or unreachable statement emits no C, its source
// comments remain available unless the user explicitly strips them.
fn ce_notes(c: CEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if n == null {
        return;
    }
    if n.kind == KFunction {
        return;
    }
    ce_comments(c, n);
    if n.kind == KIf {
        ce_notes(c, n.body);
        ce_notes(c, n.otherwise);
        return;
    }
    if n.kind == KLoop {
        ce_notes(c, n.body);
        return;
    }
    if n.kind == KBlock {
        foreach(var & item in &n.items) {
            ce_notes(c, *item);
        }
    }
}

// Derived control-flow queries over Foundation nodes. Avoid manufacturing dead
// C statements/labels: several C compilers warn about them even without -Wextra.
fn ce_label_used(c: CEmitter*, entity: void*): bool {
    var i: usize = 0;
    loop {
        if i == c.nodes.length {
            return false;
        }
        var n = sem_get(c.nodes.data[i]);
        var jump = n.kind == KJump;
        jump &&= c.active.data[i];
        if jump {
            if n.binding == entity {
                return true;
            }
        }
        i++;
    }
}

fn ce_breaks(c: CEmitter*, entity: void*): bool {
    var n = sem_get(entity);
    if n == null {
        return false;
    }
    var index = ce_id(c, entity);
    if c.active.data[index] == false {
        return false;
    }
    if n.kind == KBreak {
        return true;
    }
    if n.kind == KLoop {
        return false;
    }
    if n.kind == KIf {
        if ce_breaks(c, n.body) {
            return true;
        }
        return ce_breaks(c, n.otherwise);
    }
    if n.kind == KBlock {
        foreach(var & item in &n.items) {
            if ce_breaks(c, *item) {
                return true;
            }
        }
    }
    return false;
}

fn ce_falls(c: CEmitter*, entity: void*): bool {
    var n = sem_get(entity);
    if n == null {
        return true;
    }
    if n.kind == KCall {
        var index = ce_id(c, n.binding);
        return c.returning.data[index];
    }
    var terminal = n.kind == KReturn;
    if n.kind == KJump {
        terminal = true;
    }
    if n.kind == KTrap {
        terminal = true;
    }
    if n.kind == KBreak {
        terminal = true;
    }
    if n.kind == KContinue {
        terminal = true;
    }
    if terminal {
        return false;
    }
    if n.kind == KIf {
        var condition = sem_get(n.value);
        if condition.constant {
            if condition.bits != 0 {
                return ce_falls(c, n.body);
            }
            return ce_falls(c, n.otherwise);
        }
        if ce_falls(c, n.body) {
            return true;
        }
        return ce_falls(c, n.otherwise);
    }
    if n.kind == KLoop {
        return ce_breaks(c, n.body);
    }
    var list = n.kind == KBlock;
    if n.kind == KProgram {
        list = true;
    }
    if list {
        var falls = true;
        var i: usize = 0;
        loop {
            if i == n.items.length {
                return falls;
            }
            var child = n.items.data[i];
            var item = sem_get(child);
            if item.kind == KLabel {
                if ce_label_used(c, child) {
                    falls = true;
                }
            }
            falls &&= ce_falls(c, child);
            i++;
        }
    }
    return true;
}

import tower;
import c_runtime;
import c_control;
import foundation_tags;
import foundation_types;
import frontend_compilation;
import semantic_context;
import semantic_definitions;
import semantic_support;
import .library.vector;

// C89-style output over the shared Foundation entities. The vectors below are
// disposable name/storage indexes, not a second semantic representation.
struct CEmitter {
    text: vector(u8)*;
    error: vector(u8)*;
    nodes: vector(void*);
    owners: vector(void*);
    active: vector(bool);
    returning: vector(bool);
    changed: bool;
    owner: void*;
    depth: usize;
    pointer_bytes: u32;
    comments: bool;
}

fn ce_text(c: CEmitter*, text: u8*): void {
    sem_require(bytes_append(c.text, text, frontend_source_length(text)));
}

fn ce_number(c: CEmitter*, number: u64): void {
    var digits: u8[20];
    var at: usize = 20;
    loop {
        at--;
        var c_step1 = number % 10;
        digits[at] = convert(u8, c_step1) + 48;
        number = number / 10;
        if number == 0 {
            break;
        }
    }
    var c_step3 = 20 -at;
    sem_require(bytes_append(c.text, &digits[at], c_step3));
}

fn ce_fail(c: CEmitter*, message: u8*): void {
    if c.error.length == 0 {
        sem_require(bytes_append(c.error, message, frontend_source_length(message)));
    }
}

fn ce_indent(c: CEmitter*): void {
    var i: usize = 0;
    loop {
        if i == c.depth {
            break;
        }
        ce_text(c, "    ");
        i++;
    }
}

fn ce_id(c: CEmitter*, node: void*): usize {
    var i: usize = 0;
    loop {
        if i == c.nodes.length {
            return i;
        }
        if c.nodes.data[i] == node {
            return i;
        }
        i++;
    }
}

fn ce_name(c: CEmitter*, node: void*, prefix: u8*): void {
    ce_text(c, prefix);
    ce_number(c, convert(u64, ce_id(c, node)));
}

fn ce_reserved(name: vector(u8)*): bool {
    var words = "auto break case char const continue default do double else enum extern float for goto if int long register return short signed sizeof static struct switch typedef union unsigned void volatile while asm bool catch class delete explicit export false friend inline mutable namespace new operator private protected public reinterpret_cast static_cast dynamic_cast const_cast template this throw true try typeid typename using virtual wchar_t and and_eq bitand bitor compl not not_eq or or_eq xor xor_eq alignas alignof char16_t char32_t constexpr decltype noexcept nullptr static_assert thread_local main uint8_t uint16_t uint32_t uint64_t int8_t int16_t int32_t int64_t uintptr_t size_t NULL UINT64_C UINT64_MAX INT64_MAX INT64_MIN UINT32_MAX INT32_MAX INT32_MIN SIZE_MAX CHAR_BIT stdout stderr fputs fputc putchar puts printf exit memcpy memmove memset malloc realloc free fwrite _setmode _fileno";
    var at: usize = 0;
    loop {
        if words[at] == 0 {
            break;
        }
        var start = at;
        loop {
            var stop = words[at] == 0;
            var space = words[at] == 32;
            if space {
                stop = true;
            }
            if stop {
                break;
            }
            at++;
        }
        var length = at -start;
        var equal = length == name.length;
        var i: usize = 0;
        if equal {
            for(; i != length; i++) {
                var p = start + i;
                if words[p] != name.data[i] {
                    equal = false;
                    break;
                }
            }
        }
        if equal {
            return true;
        }
        var space = words[at] == 32;
        if space {
            at++;
        }
    }
    if name.length >= 3 {
        var first = name.data[0] == 116;
        if name.data[0] == 84 {
            first = true;
        }
        if first {
            var second = name.data[1] == 99;
            if name.data[1] == 67 {
                second = true;
            }
            if second {
                if name.data[2] == 95 {
                    return true;
                }
            }
        }
    }
    if name.length >= 2 {
        var first = name.data[0] == 118;
        if name.data[0] == 116 {
            first = true;
        }
        if first {
            var digit = name.data[1] >= 48;
            digit &&= name.data[1] <= 57;
            if digit {
                return true;
            }
        }
    }
    return false;
}

fn ce_function_name(c: CEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if n.external {
        if sem_equal(sem_name(n), "platform_write") {
            ce_text(c, "tc_platform_write");
            return;
        }
    }
    var public = n.external;
    if n.exported {
        public = true;
    }
    if public {
        if ce_reserved(&n.name) {
            ce_fail(c, "C target external name conflicts with a reserved word or generated support symbol; use a C ABI wrapper");
        }
        var i: usize = 0;
        if n.name.length == 0 {
            ce_fail(c, "C target requires a nonempty foreign symbol");
        }
        loop {
            if i == n.name.length {
                break;
            }
            var b = n.name.data[i];
            var valid = b >= 65;
            valid &&= b <= 90;
            if b >= 97 {
                if b <= 122 {
                    valid = true;
                }
            }
            if b == 95 {
                valid = true;
            }
            if i != 0 {
                if b >= 48 {
                    if b <= 57 {
                        valid = true;
                    }
                }
            }
            if !valid {
                ce_fail(c, "C target needs a plain C identifier for extern/export; namespace or member declarations require a C ABI wrapper");
            }
            i++;
        }
        // Preserve the explicit link name. C keywords/reserved names are rejected
        // below instead of silently changing an external ABI.
        if sem_equal(sem_name(n), "main") {
            ce_fail(c, "C target reserves main for the program entry point");
        }
        ce_text(c, sem_name(n));
        return;
    }
    ce_name(c, entity, "tc_fn_");
    ce_text(c, "_");
    var i: usize = 0;
    loop {
        if i == n.name.length {
            break;
        }
        var b = n.name.data[i];
        var valid = b >= 65;
        valid &&= b <= 90;
        if b >= 97 {
            if b <= 122 {
                valid = true;
            }
        }
        if b >= 48 {
            if b <= 57 {
                valid = true;
            }
        }
        if valid {
            sem_require(vector_push(c.text, b));
        }
        else {
            ce_text(c, "_");
        }
        i++;
    }
}

fn ce_type(c: CEmitter*, t: FoundationType*): void {
    if t.pointers != 0 {
        ce_text(c, "unsigned char *");
        return;
    }
    if t.scalar == SVoid {
        ce_text(c, "void");
        return;
    }
    if t.scalar == SBool {
        ce_text(c, "uint8_t");
        return;
    }
    if t.scalar == SU8 || t.scalar == SI8 {
        ce_text(c, "uint8_t");
        return;
    }
    if t.scalar == SI16 || t.scalar == SU16 {
        ce_text(c, "uint16_t");
        return;
    }
    if t.scalar == SI32 {
        ce_text(c, "uint32_t");
        return;
    }
    if t.scalar == SU32 {
        ce_text(c, "uint32_t");
        return;
    }
    if t.scalar == SUSize {
        ce_text(c, "uintptr_t");
        return;
    }
    if t.scalar == SI64 {
        ce_text(c, "uint64_t");
        return;
    }
    if t.scalar == SU64 {
        ce_text(c, "uint64_t");
        return;
    }
    ce_fail(c, "C target does not pass aggregate values by value");
}

fn ce_abi_type(c: CEmitter*, t: FoundationType*): void {
    // Function declarations keep their signed C ABI types. Locals/temporaries
    // still store unsigned bits; calls and returns convert explicitly.
    if semantic_signed(t) {
        ce_text(c, "int");
        ce_number(c, convert(u64, semantic_width(t)));
        ce_text(c, "_t");
    } else {
        ce_type(c, t);
    }
}

fn ce_suffix(c: CEmitter*, t: FoundationType*): void {
    if t.pointers != 0 {
        ce_text(c, "ptr");
        return;
    }
    ce_number(c, convert(u64, semantic_width(t)));
}

fn ce_temp(c: CEmitter*, entity: void*): void {
    ce_name(c, entity, "t");
}

fn ce_value_kind(n: FoundationNode*): bool {
    if semantic_aggregate(&n.type) {
        return false;
    }
    if n.kind == KOperand {
        return true;
    }
    if n.kind == KBinary {
        return true;
    }
    if n.kind == KAddress {
        return true;
    }
    if n.kind == KLoad {
        return true;
    }
    if n.kind == KConvert {
        return true;
    }
    if n.kind == KBits {
        return true;
    }
    if n.kind == KCall {
        if n.type.pointers != 0 {
            return true;
        }
        return n.type.scalar != SVoid;
    }
    if n.kind == KField {
        return true;
    }
    if n.kind == KIndex {
        return true;
    }
    if n.kind == KString {
        return true;
    }
    if n.kind == KSizeOf {
        return true;
    }
    if n.kind == KAlignOf {
        return true;
    }
    if n.kind == KAllocate {
        return true;
    }
    return n.kind == KReallocate;
}

fn ce_collect(c: CEmitter*, entity: void*, owner: void*): void {
    if entity == null {
        return;
    }
    if ce_id(c, entity) < c.nodes.length {
        return;
    }
    var n = sem_get(entity);
    if n == null {
        return;
    }
    if n.kind != KType && (semantic_float(&n.type) || semantic_float(&n.element)) {
        ce_fail(c, "This source backend does not yet implement strict floating-point values; use LLVM native/Wasm output");
    }
    if n.kind == KFunctionReference || n.kind == KCall && n.value != null || n.type.scalar == SFunction || n.element.scalar == SFunction {
        ce_fail(c, "This source backend does not yet implement function values; use LLVM native/Wasm output");
    }
    if n.kind == KFunction {
        owner = entity;
    }
    sem_require(vector_push(&c.nodes, entity));
    sem_require(vector_push(&c.owners, owner));
    sem_require(vector_push(&c.active, false));
    sem_require(vector_push(&c.returning, true));
    // Labels point back to their block. Types contain recursive nominal edges.
    if n.kind == KLabel {
        return;
    }
    if n.kind == KType {
        return;
    }
    ce_collect(c, n.left, owner);
    ce_collect(c, n.right, owner);
    ce_collect(c, n.value, owner);
    ce_collect(c, n.target, owner);
    ce_collect(c, n.body, owner);
    ce_collect(c, n.otherwise, owner);
    var i: usize = 0;
    loop {
        if i == n.parameters.length {
            break;
        }
        ce_collect(c, n.parameters.data[i], owner);
        i++;
    }
    i = 0;
    loop {
        if i == n.items.length {
            break;
        }
        ce_collect(c, n.items.data[i], owner);
        i++;
    }
}

fn ce_comments(c: CEmitter*, n: FoundationNode*): void {
    if !c.comments {
        return;
    }
    var i: usize = 0;
    loop {
        if i == n.comments.length {
            break;
        }
        var b = n.comments.data[i];
        if b == 92 {
            ce_text(c, "\\x5c");
        }
        else {
            sem_require(vector_push(c.text, b));
        }
        // Prevent preprocessing trigraphs and backslash/newline splicing in C.
        if b == 63 {
            ce_text(c, " ");
        }
        i++;
    }
}

fn ce_quote(c: CEmitter*, text: vector(u8)*): void {
    // C89 only requires 509 characters after string literal concatenation.
    // Large constants use a byte initializer with short physical lines instead.
    if text.length > 96 {
        ce_text(c, "{\n    ");
        var at: usize = 0;
        loop {
            if at == text.length {
                break;
            }
            ce_number(c, convert(u64, text.data[at]));
            ce_text(c, ", ");
            at++;
            var column = at % 16;
            if column == 0 {
                ce_text(c, "\n    ");
            }
        }
        ce_text(c, "0\n}");
        return;
    }
    ce_text(c, "\"");
    var i: usize = 0;
    loop {
        if i == text.length {
            break;
        }
        // Fixed-width octal escapes avoid source encoding, trigraphs and hex
        // escape greediness. The C compiler adds the required terminating NUL.
        var b = convert(u32, text.data[i]);
        ce_text(c, "\\");
        var c_step59 = b / 64;
        ce_number(c, convert(u64, c_step59));
        var c_step60 = b / 8;
        var c_step61 = c_step60 % 8;
        ce_number(c, convert(u64, c_step61));
        var c_step62 = b % 8;
        ce_number(c, convert(u64, c_step62));
        i++;
    }
    ce_text(c, "\"");
}

fn ce_prepare_address(c: CEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if n.kind == KLoad {
        ce_prepare(c, n.value);
        return;
    }
    var place = n.kind == KField;
    if n.kind == KIndex {
        place = true;
    }
    if place {
        if n.indirect {
            ce_prepare(c, n.left);
        }
        else {
            ce_prepare_address(c, n.left);
        }
        if n.kind == KIndex {
            ce_prepare(c, n.right);
        }
    }
}

fn ce_signed_value(c: CEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if semantic_signed(&n.type) {
        ce_text(c, "tc_signed(");
        ce_temp(c, entity);
        ce_text(c, ", ");
        ce_suffix(c, &n.type);
        ce_text(c, ")");
    }
    else {
        ce_temp(c, entity);
    }
}

fn ce_address(c: CEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if n.kind == KLoad {
        ce_temp(c, n.value);
        return;
    }
    var place = n.kind == KField;
    if n.kind == KIndex {
        place = true;
    }
    if place {
        ce_text(c, "tc_offset(");
        if n.indirect {
            ce_temp(c, n.left);
        }
        else {
            ce_address(c, n.left);
        }
        ce_text(c, ", ");
        if n.kind == KIndex {
            ce_text(c, "(uintptr_t)(");
            ce_signed_value(c, n.right);
            ce_text(c, ") * ");
            ce_number(c, convert(u64, semantic_size(&n.type)));
        }
        else {
            ce_number(c, convert(u64, n.byte_offset));
        }
        ce_text(c, ")");
        return;
    }
    var binding = n.binding;
    if binding == null {
        binding = entity;
    }
    ce_text(c, "(unsigned char *)&");
    ce_name(c, binding, "v");
}

fn ce_bit_value(c: CEmitter*, entity: void*, signed_extend: bool): void {
    var n = sem_get(entity);
    if n.type.pointers != 0 {
        ce_text(c, "(uintptr_t)");
    }
    if signed_extend {
        ce_signed_value(c, entity);
    }
    else {
        ce_temp(c, entity);
    }
}

fn ce_expression(c: CEmitter*, entity: void*): void {
    var n = sem_get(entity);
    if n.kind == KOperand {
        if n.constant {
            if n.type.pointers != 0 {
                ce_text(c, "NULL");
            }
            else {
                ce_text(c, "UINT64_C(");
                var c_step73 = n.bits &semantic_mask(&n.type);
                ce_number(c, c_step73);
                ce_text(c, ")");
            }
        }
        else {
            ce_name(c, n.binding, "v");
        }
        return;
    }
    if n.kind == KString {
        ce_name(c, entity, "tc_string_");
        return;
    }
    if n.kind == KAddress {
        ce_address(c, n.value);
        return;
    }
    var load = n.kind == KLoad;
    if n.kind == KField {
        load = true;
    }
    if n.kind == KIndex {
        load = true;
    }
    if load {
        ce_text(c, "tc_load");
        ce_suffix(c, &n.type);
        ce_text(c, "(");
        ce_address(c, entity);
        ce_text(c, ")");
        return;
    }
    if n.kind == KCall {
        ce_function_name(c, n.binding);
        ce_text(c, "(");
        var i: usize = 0;
        loop {
            if i == n.items.length {
                break;
            }
            if i != 0 {
                ce_text(c, ", ");
            }
            ce_signed_value(c, n.items.data[i]);
            i++;
        }
        ce_text(c, ")");
        return;
    }
    if n.kind == KSizeOf {
        ce_number(c, convert(u64, semantic_size(&n.element)));
        return;
    }
    if n.kind == KAlignOf {
        ce_number(c, convert(u64, semantic_alignment(&n.element)));
        return;
    }
    if n.kind == KAllocate {
        ce_text(c, "tc_alloc(");
        ce_temp(c, n.right);
        ce_text(c, ", ");
        ce_number(c, convert(u64, semantic_size(&n.element)));
        ce_text(c, ")");
        return;
    }
    if n.kind == KReallocate {
        ce_text(c, "tc_realloc(");
        ce_temp(c, n.left);
        ce_text(c, ", ");
        ce_temp(c, n.right);
        ce_text(c, ", ");
        ce_number(c, convert(u64, semantic_size(&n.element)));
        ce_text(c, ")");
        return;
    }
    if n.kind == KBits {
        ce_text(c, "(");
        ce_type(c, &n.type);
        ce_text(c, ")");
        if n.type.pointers != 0 {
            ce_text(c, "(uintptr_t)");
        }
        ce_bit_value(c, n.value, true);
        return;
    }
    if n.kind == KConvert {
        if n.type.scalar == SBool {
            ce_text(c, "(");
            ce_temp(c, n.value);
            ce_text(c, " != 0)");
            return;
        }
        var from = sem_get(n.value);
        ce_text(c, "(");
        ce_type(c, &n.type);
        ce_text(c, ")tc_convert(");
        ce_temp(c, n.value);
        ce_text(c, ", ");
        ce_number(c, convert(u64, semantic_width(&from.type)));
        ce_text(c, ", ");
        ce_number(c, convert(u64, semantic_signed(&from.type)));
        ce_text(c, ", ");
        ce_number(c, convert(u64, semantic_width(&n.type)));
        ce_text(c, ", ");
        ce_number(c, convert(u64, semantic_signed(&n.type)));
        ce_text(c, ")");
        return;
    }
    if n.kind == KBinary {
        var from = sem_get(n.left);
        if from.type.pointers != 0 {
            var arithmetic = n.op == OAdd;
            if n.op == OSub {
                arithmetic = true;
            }
            if arithmetic {
                var element: FoundationType;
                copy(&element, &from.type, sizeof(FoundationType));
                element.pointers--;
                ce_text(c, "tc_offset(");
                ce_temp(c, n.left);
                ce_text(c, ", ");
                if n.op == OSub {
                    ce_text(c, "(uintptr_t)0 - ");
                }
                ce_text(c, "(uintptr_t)(");
                ce_signed_value(c, n.right);
                ce_text(c, ") * ");
                ce_number(c, convert(u64, semantic_size(&element)));
                ce_text(c, ")");
                return;
            }
            ce_text(c, "((uintptr_t)");
            ce_temp(c, n.left);
            ce_text(c, " ");
            ce_text(c, semantic_operator(n.op));
            ce_text(c, " (uintptr_t)");
            ce_temp(c, n.right);
            ce_text(c, ")");
            return;
        }
        var division = n.op == ODiv;
        if n.op == ORem {
            division = true;
        }
        if division {
            ce_text(c, "tc_div(");
            ce_temp(c, n.left);
            ce_text(c, ", ");
            ce_temp(c, n.right);
            ce_text(c, ", ");
            ce_number(c, convert(u64, semantic_width(&from.type)));
            ce_text(c, ", ");
            ce_number(c, convert(u64, semantic_signed(&from.type)));
            ce_text(c, ", ");
            var c_step94 = n.op == ORem;
            ce_number(c, convert(u64, c_step94));
            ce_text(c, ")");
            return;
        }
        if n.op >= OEq {
            ce_text(c, "(");
            ce_signed_value(c, n.left);
            ce_text(c, " ");
            ce_text(c, semantic_operator(n.op));
            ce_text(c, " ");
            ce_signed_value(c, n.right);
            ce_text(c, ")");
            return;
        }
        // Promote u8/bool before arithmetic to avoid signed-int multiplication.
        ce_text(c, "((uint64_t)");
        ce_temp(c, n.left);
        ce_text(c, " ");
        ce_text(c, semantic_operator(n.op));
        ce_text(c, " (uint64_t)");
        ce_temp(c, n.right);
        ce_text(c, ")");
        return;
    }
    ce_fail(c, "Unsupported Foundation value in C emitter");
    ce_text(c, "0");
}

fn ce_prepare(c: CEmitter*, entity: void*): void {
    if entity == null {
        return;
    }
    var n = sem_get(entity);
    if n.kind == KAddress {
        ce_prepare_address(c, n.value);
    }
    else {
        var place = n.kind == KField;
        if n.kind == KIndex {
            place = true;
        }
        if n.kind == KLoad {
            place = true;
        }
        if place {
            ce_prepare_address(c, entity);
        }
        else {
            ce_prepare(c, n.left);
            ce_prepare(c, n.right);
            ce_prepare(c, n.value);
            var i: usize = 0;
            loop {
                if i == n.items.length {
                    break;
                }
                ce_prepare(c, n.items.data[i]);
                i++;
            }
        }
    }
    ce_indent(c);
    if ce_value_kind(n) {
        ce_temp(c, entity);
        ce_text(c, " = ");
        ce_text(c, "(");
        ce_type(c, &n.type);
        ce_text(c, ")(");
    }
    ce_expression(c, entity);
    if ce_value_kind(n) {
        ce_text(c, ")");
    }
    ce_text(c, ";\n");
}

fn ce_store(c: CEmitter*, target: void*, value: void*): void {
    var n = sem_get(target);
    ce_indent(c);
    ce_text(c, "tc_store");
    ce_suffix(c, &n.type);
    ce_text(c, "(");
    ce_address(c, target);
    ce_text(c, ", ");
    ce_temp(c, value);
    ce_text(c, ");\n");
}

fn ce_statement(c: CEmitter*, entity: void*): void {
    if entity == null {
        return;
    }
    var n = sem_get(entity);
    if n.kind == KFunction {
        return;
    }
    if n.kind == KType {
        ce_comments(c, n);
        return;
    }
    ce_comments(c, n);
    var list = n.kind == KProgram;
    if n.kind == KBlock {
        list = true;
    }
    if list {
        var i: usize = 0;
        loop {
            if i == n.items.length {
                break;
            }
            var child = n.items.data[i];
            var index = ce_id(c, child);
            if c.active.data[index] {
                ce_statement(c, child);
            } else {
                ce_notes(c, child);
            }
            i++;
        }
        return;
    }
    if n.kind == KDeclare {
        if n.value != null {
            ce_prepare(c, n.value);
            ce_store(c, entity, n.value);
        }
        else {
            ce_indent(c);
            ce_text(c, "memset(&");
            ce_name(c, entity, "v");
            ce_text(c, ", 0, ");
            ce_number(c, convert(u64, semantic_size(&n.type)));
            ce_text(c, ");\n");
        }
        return;
    }
    if n.kind == KAssign {
        ce_prepare_address(c, n.target);
        ce_prepare(c, n.value);
        ce_store(c, n.target, n.value);
        return;
    }
    if n.kind == KIf {
        var condition = sem_get(n.value);
        if condition.constant {
            if condition.bits != 0 {
                ce_statement(c, n.body);
                ce_notes(c, n.otherwise);
            } else {
                ce_notes(c, n.body);
                ce_statement(c, n.otherwise);
            }
            return;
        }
        ce_prepare(c, n.value);
        ce_indent(c);
        ce_text(c, "if (");
        ce_temp(c, n.value);
        ce_text(c, ") {\n");
        c.depth++;
        ce_statement(c, n.body);
        c.depth--;
        ce_indent(c);
        ce_text(c, "}");
        if n.otherwise != null {
            ce_text(c, " else {\n");
            c.depth++;
            ce_statement(c, n.otherwise);
            c.depth--;
            ce_indent(c);
            ce_text(c, "}");
        }
        ce_text(c, "\n");
        return;
    }
    if n.kind == KLoop {
        ce_indent(c);
        ce_text(c, "for (;;) {\n");
        c.depth++;
        ce_statement(c, n.body);
        c.depth--;
        ce_indent(c);
        ce_text(c, "}\n");
        return;
    }
    if n.kind == KBreak {
        ce_indent(c);
        ce_text(c, "break;\n");
        return;
    }
    if n.kind == KContinue {
        ce_indent(c);
        ce_text(c, "continue;\n");
        return;
    }
    if n.kind == KReturn {
        ce_prepare(c, n.value);
        ce_indent(c);
        ce_text(c, "return");
        if n.value != null {
            ce_text(c, " ");
            ce_signed_value(c, n.value);
        }
        ce_text(c, ";\n");
        return;
    }
    if n.kind == KLabel {
        if ce_label_used(c, entity) == false {
            return;
        }
        ce_indent(c);
        ce_name(c, entity, "label_");
        ce_text(c, ":;\n");
        return;
    }
    if n.kind == KJump {
        ce_indent(c);
        ce_text(c, "goto ");
        ce_name(c, n.binding, "label_");
        ce_text(c, ";\n");
        return;
    }
    if n.kind == KPrint {
        ce_prepare(c, n.value);
        var value = sem_get(n.value);
        ce_indent(c);
        if value.type.pointers != 0 {
            ce_text(c, "tc_print_pointer((uintptr_t)");
            ce_temp(c, n.value);
            ce_text(c, ");\n");
            return;
        }
        if value.type.scalar == SBool {
            ce_text(c, "puts(");
            ce_temp(c, n.value);
            ce_text(c, " ? \"true\" : \"false\");\n");
            return;
        }
        if semantic_signed(&value.type) {
            ce_text(c, "tc_print_signed((int64_t)");
            ce_signed_value(c, n.value);
        }
        else {
            ce_text(c, "tc_print_unsigned((uint64_t)");
            ce_temp(c, n.value);
        }
        ce_text(c, ");\n");
        return;
    }
    if n.kind == KFree {
        ce_prepare(c, n.left);
        ce_indent(c);
        ce_text(c, "free(");
        ce_temp(c, n.left);
        ce_text(c, ");\n");
        return;
    }
    var memory = n.kind == KCopy;
    if n.kind == KFill {
        memory = true;
    }
    if memory {
        ce_prepare(c, n.left);
        ce_prepare(c, n.right);
        ce_prepare(c, n.value);
        ce_indent(c);
        ce_text(c, "if (");
        ce_temp(c, n.value);
        ce_text(c, ") ");
        if n.kind == KCopy {
            ce_text(c, "memmove(");
        }
        else {
            ce_text(c, "memset(");
        }
        ce_temp(c, n.left);
        ce_text(c, ", ");
        ce_temp(c, n.right);
        ce_text(c, ", ");
        ce_temp(c, n.value);
        ce_text(c, ");\n");
        return;
    }
    if n.kind == KTrap {
        ce_prepare(c, n.left);
        ce_prepare(c, n.right);
        ce_indent(c);
        ce_text(c, "tc_trap((const char *)");
        ce_temp(c, n.left);
        ce_text(c, ");\n");
        return;
    }
    if n.kind == KCall {
        ce_prepare(c, entity);
        return;
    }
    ce_fail(c, "Unsupported Foundation statement in C emitter");
}

fn ce_declaration(c: CEmitter*, entity: void*, variable: bool): void {
    var n = sem_get(entity);
    ce_indent(c);
    if semantic_aggregate(&n.type) {
        ce_text(c, "union { uint64_t alignment; unsigned char bytes[");
        var size = semantic_size(&n.type);
        if size == 0 {
            size = 1;
        }
        ce_number(c, convert(u64, size));
        ce_text(c, "]; } ");
    }
    else {
        ce_type(c, &n.type);
        ce_text(c, " ");
    }
    if variable {
        ce_name(c, entity, "v");
    }
    else {
        ce_temp(c, entity);
    }
    ce_text(c, ";\n");
}

fn ce_signature(c: CEmitter*, entity: void*): void {
    var n = sem_get(entity);
    var index = ce_id(c, entity);
    if c.returning.data[index] == false {
        ce_text(c, "TC_NORETURN ");
    }
    ce_abi_type(c, &n.type);
    ce_text(c, " ");
    ce_function_name(c, entity);
    ce_text(c, "(");
    if n.parameters.length == 0 {
        ce_text(c, "void");
    }
    var i: usize = 0;
    loop {
        if i == n.parameters.length {
            break;
        }
        if i != 0 {
            ce_text(c, ", ");
        }
        var parameter = sem_get(n.parameters.data[i]);
        ce_abi_type(c, &parameter.type);
        ce_text(c, " ");
        ce_name(c, n.parameters.data[i], "v");
        i++;
    }
    ce_text(c, ")");
}

fn ce_body(c: CEmitter*, entity: void*, program: bool): void {
    c.owner = entity;
    c.depth = 1;
    var i: usize = 0;
    loop {
        if i == c.nodes.length {
            break;
        }
        if c.owners.data[i] == entity {
            var item = c.nodes.data[i];
            var n = sem_get(item);
            var local = n.kind == KDeclare;
            if n.global {
                local = false;
            }
            if local {
                ce_declaration(c, item, true);
            }
            if ce_value_kind(n) {
                ce_declaration(c, item, false);
            }
        }
        i++;
    }
    i = 0;
    loop {
        if i == c.nodes.length {
            break;
        }
        if c.owners.data[i] == entity {
            var item = c.nodes.data[i];
            var n = sem_get(item);
            var variable = n.kind == KDeclare;
            if n.kind == KParameter {
                variable = true;
            }
            var temp = ce_value_kind(n);
            if n.kind == KString {
                ce_indent(c);
                ce_text(c, "(void)");
                ce_name(c, item, "tc_string_");
                ce_text(c, ";\n");
            }
            if variable {
                ce_indent(c);
                ce_text(c, "(void)&");
                ce_name(c, item, "v");
                ce_text(c, ";\n");
            }
            if temp {
                ce_indent(c);
                ce_text(c, "(void)&");
                ce_temp(c, item);
                ce_text(c, ";\n");
            }
        }
        i++;
    }
    if program {
        ce_text(c, "    tc_environment();\n");
        ce_text(c, "    { const uint32_t endian = 1; if (*(const unsigned char *)&endian != 1) tc_trap(\"C target requires little endian storage\"); }\n");
        ce_statement(c, entity);
        if ce_falls(c, entity) {
            ce_text(c, "    return 0;\n");
        } else {
            ce_text(c, "    TC_MAIN_END\n");
        }
    }
    else {
        var n = sem_get(entity);
        ce_statement(c, n.body);
    }
    ce_text(c, "}\n\n");
    c.depth = 0;
}

export fn c_emit(text: vector(u8)*, error: vector(u8)*, root: void*, pointer_bytes: u32, comments: bool): void {
    var c: CEmitter = { text: text, error: error, pointer_bytes: pointer_bytes, comments: comments, ..default };
    ce_collect(&c, root, root);
    ce_reachable(&c, root);
    ce_text(&c, "/* Tower generated C. Compile: cc -std=c89 -pedantic -Wall -Wextra -O2 program.c */\n");
    ce_text(&c, "#define TC_POINTER_BYTES ");
    ce_number(&c, convert(u64, pointer_bytes));
    ce_text(&c, "\n");
    ce_runtime(&c);
    ce_text(&c, "typedef char tc_pointer_width[(sizeof(void *) == ");
    ce_number(&c, convert(u64, pointer_bytes));
    ce_text(&c, ") ? 1 : -1];\n\n");
    var i: usize = 0;
    loop {
        if i == c.nodes.length {
            break;
        }
        var entity = c.nodes.data[i];
        var n = sem_get(entity);
        if n.kind == KString {
            ce_text(&c, "static unsigned char ");
            ce_name(&c, entity, "tc_string_");
            ce_text(&c, "[] = ");
            ce_quote(&c, &n.name);
            ce_text(&c, ";\n");
        }
        if n.kind == KDeclare {
            if n.global {
                ce_declaration(&c, entity, true);
            }
        }
        if n.kind == KFunction {
            var platform = n.external;
            platform &&= sem_equal(sem_name(n), "platform_write");
            if !platform {
                ce_signature(&c, entity);
                ce_text(&c, ";\n");
            }
            if n.external {
                ce_comments(&c, n);
            }
        }
        i++;
    }
    ce_text(&c, "\n");
    i = 0;
    loop {
        if i == c.nodes.length {
            break;
        }
        var entity = c.nodes.data[i];
        var n = sem_get(entity);
        if n.kind == KFunction {
            if !n.external {
                ce_comments(&c, n);
                ce_signature(&c, entity);
                ce_text(&c, "\n{\n");
                ce_body(&c, entity, false);
            }
        }
        i++;
    }
    ce_text(&c, "int main(void)\n{\n");
    ce_body(&c, root, true);
    ce_text(&c, "#ifdef __cplusplus\n}\n#endif\n");
    vector_dispose(&c.nodes);
    vector_dispose(&c.owners);
    vector_dispose(&c.active);
    vector_dispose(&c.returning);
    if error.length != 0 {
        text.length = 0;
    }
}

import tower;
import c_emitter;

// Standard C runtime text; no external Tower runtime or compiler extensions
// outside the legacy integer and optional non-returning function adapters.
fn ce_runtime(c: CEmitter*): void {
    ce_text(c, "#include <stddef.h>
");
    ce_text(c, "#include <limits.h>
");
    ce_text(c, "#include <stdio.h>
");
    ce_text(c, "#include <stdlib.h>
");
    ce_text(c, "#include <string.h>
");
    ce_text(c, "#ifdef _WIN32
#include <io.h>
#include <fcntl.h>
#endif
");
    ce_text(c, "
");
    ce_text(c, "
");
    ce_text(c, "/* Prefer standard integer types; older compilers use this small data-model adapter. */
");
    ce_text(c, "#if (defined(__STDC_VERSION__) && __STDC_VERSION__ >= 199901L) || \
");
