extern fn syntax_completion_create(source: u8*, mode: u32): void*;

extern fn syntax_session_open(world: void*, environment: void*, source: u8*, module: void*, mode: u32): SyntaxSession*;

extern fn frontend_modules_bind_world(environment: void*, world: void*): bool;

extern fn compiler_world_store(world: void*): void*;

extern fn entity_create(store: void*): void*;

extern fn compiler_node_get(node: void*, kind: u32): void*;

// The query borrows its world/environment until disposal. Legacy callers select
// that owner once at their boundary; recovery never switches an ambient world.
fn completion_session(q: CompletionQuery*, source: u8*, mode: u32): void* {
    return bits(void*, syntax_session_open(q.world, q.environment, source, null, mode));
}

extern fn syntax_destroy(session: void*): void;

extern fn syntax_completion_module(session: void*): void*;

extern fn syntax_completion_enable(session: void*): void;

extern fn syntax_completion_accepts(session: void*, text: u8*, literal: bool): bool;

extern fn syntax_completion_callable(session: void*): bool;

extern fn syntax_completion_identifier(session: void*, text: u8*): bool;

extern fn syntax_completion_close(session: void*, type_name: u8*): u8*;

export fn completion_from(q: CompletionQuery*): usize {
    return q.from;
}

fn completion_attach(q: CompletionQuery*, root: void*, base: usize): void {
    var node = sem_child(root, 0);
    if sem_is(node, "Statement") {
        node = sem_unwrap(node);
    }
    sem_require(entity_attach(root, q.program.root, ""));
    var target = sem_get(q.program.root);
    sem_push(&target.items, node);
    sem_push(&q.roots, root);
    sem_require(vector_push(&q.bases, base));
}

fn completion_parse(q: CompletionQuery*, source: u8*, mode: u32, future: bool): bool {
    var first_root = q.roots.length;
    var base = q.input.length;
    var length = sem_length(source);
    sem_require(bytes_append(&q.input, source, length));
    sem_require(vector_push(&q.input, 10));
    var session = completion_session(q, source, mode);
    var entries: vector(void*);
    vector_init(&entries);
    var count: usize = 0;
    loop {
        if count == 1024 {
            q.truncated = true;
            break;
        }
        var revision = syntax_get_revision(session);
        var root = syntax_next(session);
        if root == null {
            break;
        }
        var keep = revision == syntax_get_revision(session);
        if future {
            var span = sem_match(root);
            if span.start < q.cursor {
                keep = false;
            }
        }
        if keep {
            if q.inspection {
                language_match_snapshot(q, root, session, 0);
            }
            sem_push(&entries, root);
        } else {
            if q.inspection {
                language_snapshot(q, root, session, 0);
                language_templates_refresh(q, session);
                // Keep grammar entities for inspection without adding them to
                // the executable statement list consumed by ordinary checking.
                sem_require(entity_attach(root, q.program.root, ""));
                sem_push(&q.roots, root);
                sem_require(vector_push(&q.bases, base));
            }
            entity_release(root);
        }
        count++;
    }
    var error = syntax_get_error(session);
    var clean = error[0] == 0;
    var parsed_module = syntax_completion_module(session);
    if parsed_module != null {
        sem_module_graph(&q.program, parsed_module);
        // Entry statements collected during recovery may not be in the normal
        // module roots yet; retain their same explicit owner before teardown.
        var owner = sem_module_scope(&q.program, parsed_module);
        sem_module_position(&q.program, parsed_module, base);
        var root_index: usize = 0;
        for(; root_index < entries.length; root_index++) {
            sem_module_link(entries.data[root_index], q.program.modules.owner_kind, owner);
        }
        // Grammar declarations also carry a definition scope for replacement
        // inspection, without modifying cached template trees.
        root_index = first_root;
        for(; root_index < q.roots.length; root_index++) {
            sem_module_link(q.roots.data[root_index], q.program.modules.owner_kind, owner);
        }
    }
    // Only the entry's actual import closure contributes external declarations.
    // These are fresh ordinary module entities, retained before session teardown.
    if !future {
        var module = syntax_completion_module(session);
        var present = module != null;
        if present {
            var i: usize = 0;
            var total = frontend_module_count(module);
            loop {
                var done = i == total;
                if done {
                    break;
                }
                var dependency = frontend_module_at(module, i);
                if dependency != module {
                    var dependency_base = q.input.length;
                    sem_module_position(&q.program, dependency, dependency_base);
                    if q.inspection {
                        sem_push(&q.comment_modules, dependency);
                        sem_require(vector_push(&q.comment_bases, dependency_base));
                    }
                    var data = frontend_module_source(dependency);
                    var bytes = frontend_module_size(dependency);
                    sem_require(bytes_append(&q.input, data, bytes));
                    sem_require(vector_push(&q.input, 10));
                    var n: usize = 0;
                    var trees = frontend_module_roots(dependency);
                    loop {
                        done = n == trees;
                        if done {
                            break;
                        }
                        completion_attach(q, frontend_module_tree(dependency, n), dependency_base);
                        n++;
                    }
                }
                i++;
            }
        }
    }
    foreach(var & entry in &entries) {
        completion_attach(q, *entry, base);
        entity_release(*entry);
    }
    vector_dispose(&entries);
    if q.inspection {
        // Keep the normal module/lexer metadata alive until semantic checking
        // has attached Foundation components for the shared comment pass.
        q.inspection_session = session;
        var module = syntax_completion_module(session);
        var present = module != null;
        if present {
            syntax_capture_comments(session, module);
            sem_push(&q.comment_modules, module);
            sem_require(vector_push(&q.comment_bases, base));
        }
    } else {
        syntax_destroy(session);
    }
    return clean;
}

export fn completion_analyze(q: CompletionQuery*, active: void*, mode: u32, files: u8**, lengths: usize*, count: usize): void {
    var owner = bits(SyntaxSession*, active);
    if owner is null || owner.inputs.world != q.world || owner.inputs.environment != q.environment {
        return;
    }
    q.active = active;
    if q.hidden {
        return;
    }
    if mode != 0 {
        return;
    }
    if q.mode == 2 {
        return;
    }
    // Select a concrete identifier through the current lexer. Its coordinates,
    // not its spelling, mark the query, including under local token overrides.
    var hole: vector(u8);
    vector_init(&hole);
    var prefix_length = q.cursor -q.from;
    var preferred = &q.source[q.from];
    sem_require(bytes_append(&hole, preferred, prefix_length));
    sem_require(host_text_terminate(&hole));
    var attempt: usize = 0;
    loop {
        if syntax_completion_identifier(active, hole.data) {
            break;
        }
        if attempt == 6 {
            vector_dispose(&hole);
            return;
        }
        var spelling: u8* = "a";
        if attempt == 1 {
            spelling = "A";
        }
        if attempt == 2 {
            spelling = "aa";
        }
        if attempt == 3 {
            spelling = "AA";
        }
        if attempt == 4 {
            spelling = "_";
        }
        if attempt == 5 {
            spelling = "`a`";
        }
        hole.length = 0;
        completion_text(&hole, spelling);
        sem_require(host_text_terminate(&hole));
        attempt++;
    }
    q.editor.length = hole.length;
    var text: vector(u8);
    vector_init(&text);
    sem_require(bytes_append(&text, q.source, q.from));
    completion_text(&text, hole.data);
    vector_dispose(&hole);
    var prefix_end = text.length;
    var suffix_length = q.length -q.to;
    sem_require(bytes_append(&text, &q.source[q.to], suffix_length));
    sem_require(host_text_terminate(&text));
    var root = entity_create(compiler_world_store(q.world));
    semantic_initialize(&q.program, root, 4);
    q.semantic = true;
    var valid = completion_parse(q, text.data, mode, false);
    // Prefer the actual suffix, so later operands and declarations participate
    // in resolution. Fall back to a bounded LR continuation for incomplete edits.
    if !valid {
        semantic_program_dispose(&q.program);
        entity_release(root);
        root = entity_create(compiler_world_store(q.world));
        semantic_initialize(&q.program, root, 4);
        q.roots.length = 0;
        q.bases.length = 0;
        q.input.length = 0;
        text.length = prefix_end;
        sem_require(host_text_terminate(&text));
        var probe = completion_session(q, text.data, mode);
        syntax_completion_enable(probe);
        for(var i: usize = 0; i != 1024; i++) {
            var root = syntax_next(probe);
            if root == null {
                break;
            }
            entity_release(root);
        }
        var suffix = syntax_completion_close(probe, semantic_scalar_name(SVoid));
        if suffix == null {
            syntax_destroy(probe);
            vector_dispose(&text);
            return;
        }
        // host_text_terminate writes beyond length; append replaces that terminator.
        completion_text(&text, suffix);
        sem_require(host_text_terminate(&text));
        syntax_destroy(probe);
        valid = completion_parse(q, text.data, mode, false);
        if !valid {
            vector_dispose(&text);
            return;
        }
        completion_parse(q, q.recovered.data, mode, true);
    }
    vector_dispose(&text);
    var i: usize = 0;
    sem_require(host_text_terminate(&q.input));
    var c = &q.context;
    sem_context_init(c, &q.program);
    q.analyzed = true;
    c.source = q.input.data;
    c.editor = &q.editor;
    q.editor.offset = q.from;
    c.generics = generic_begin(root);
    i = 0;
    for(; i != q.roots.length; i++) {
        var entry = sem_state(c, c.source_bases, q.roots.data[i]);
        entry.number = q.bases.data[i];
    }
    sem_run(c);
    // Observed scope tables borrow real entities and remain valid until dispose.
    if q.editor.found {
        c.scope = q.editor.scope;
    }
    c.editor = null;
    q.program.error.length = 0;
}

extern fn host_json_quote(out: vector(u8)*, source: u8*, count: usize): bool;

extern fn host_json_unsigned(out: vector(u8)*, value: u64): bool;

extern fn host_text_terminate(out: vector(u8)*): bool;

fn completion_word(byte: u8): bool {
    var yes = byte >= 65;
    yes &&= byte <= 90;
    if yes {
        return true;
    }
    yes = byte >= 97;
    yes &&= byte <= 122;
    if yes {
        return true;
    }
    yes = byte >= 48;
    yes &&= byte <= 57;
    if yes {
        return true;
    }
    var underscore = byte == 95;
    return underscore;
}

fn completion_slice(source: u8*, start: usize, end: usize, word: u8*): bool {
    var size = end -start;
    var same = size == sem_length(word);
    if !same {
        return false;
    }
    var i: usize = 0;
    loop {
        if i == size {
            return true;
        }
        var at = start + i;
        same = source[at] == word[i];
        if !same {
            return false;
        }
        i++;
    }
}

fn completion_text(out: vector(u8)*, text: u8*): void {
    sem_require(bytes_append(out, text, sem_length(text)));
}

// Offsets and lexer spans use UTF-8 bytes, including quoted identifiers.
// mode 2 marks declaration-reader queries. Value/type/member roles come from
// semantic resolution, not adjacent punctuation.
export fn completion_begin(source: u8*, length: usize, cursor: usize, spans: CompletionSpan*, count: usize): CompletionQuery* {
    var session = syntax_completion_create("", 0);
    var owner = bits(SyntaxSession*, session);
    var result = completion_begin_world(owner.inputs.world, owner.inputs.environment, source, length, cursor, spans, count);
    syntax_destroy(session);
    return result;
}

export fn completion_begin_world(world: void*, environment: void*, source: u8*, length: usize, cursor: usize, spans: CompletionSpan*, count: usize): CompletionQuery* {
    if world is null || !frontend_modules_bind_world(environment, world) {
        return null;
    }
    var q = alloc(CompletionQuery, 1);
    if q == null {
        return null;
    }
    *q = default;
    q.world = world;
    q.environment = environment;
    q.source = source;
    q.length = length;
    q.cursor = cursor;
    q.from = cursor;
    q.to = cursor;
    var i: usize = 0;
    var grammar: bool = false;
    for(; i != count; i++) {
        var s = &spans[i];
        var inside = s.start < cursor;
        inside &&= cursor <= s.end;
        if inside {
            if s.opaque {
                if !(source[s.start] <= 32) {
                    q.hidden = true;
                }
            } else {
                var word = completion_word(source[s.start]);
                if source[s.start] == 96 {
                    word = true;
                }
                if word {
                    q.from = s.start;
                    q.to = s.end;
                }
            }
        }
        if s.start >= q.from {
            break;
        }
        if !s.opaque {
            var start = completion_slice(source, s.start, s.end, "parse");
            var token_decl = completion_slice(source, s.start, s.end, "token");
            var skip_decl = completion_slice(source, s.start, s.end, "skip");
            if token_decl {
                start = true;
            }
            if skip_decl {
                start = true;
            }
            if start {
                grammar = true;
            }
            var semi = completion_slice(source, s.start, s.end, ";");
            var brace = completion_slice(source, s.start, s.end, "{");
            var close = completion_slice(source, s.start, s.end, "}");
            if semi {
                grammar = false;
                q.boundary = s.end;
            }
            if !grammar {
                if brace {
                    q.boundary = s.end;
                }
                if close {
                    q.boundary = s.end;
                }
            }
        }
    }
    if grammar {
        q.mode = 2;
    }
    // The normal lexer reports incomplete quotes/comments as invalid tokens.
    // Suppress completion in those unfinished default-language regions too.
    i = 0;
    loop {
        var done = i == count;
        if done {
            break;
        }
        var s = &spans[i];
        done = s.start >= cursor;
        if done {
            break;
        }
        if !s.opaque {
            var byte = source[s.start];
            var quote = byte == 34;
            if byte == 39 {
                quote = true;
            }
            if quote {
                q.hidden = true;
            }
            var slash = byte == 47;
            var next = s.start + 1;
            slash &&= next < length;
            slash &&= source[next] == 42;
            if slash {
                q.hidden = true;
            }
        }
        i++;
    }
    sem_require(bytes_append(&q.recovered, source, length));
    // Blank the unfinished statement without shifting source coordinates. The
    // parser then gives us ordinary shared nodes for the enclosing function.
    var end = length;
    i = 0;
    for(; i != count; i++) {
        var s = &spans[i];
        if s.start >= cursor {
            if !s.opaque {
                var close = completion_slice(source, s.start, s.end, "}");
                if close {
                    end = s.start;
                    break;
                }
                var semi = completion_slice(source, s.start, s.end, ";");
                if semi {
                    end = s.end;
                    break;
                }
            }
        }
    }
    i = q.boundary;
    for(; i < end; i++) {
        if !(source[i] == 10) {
            q.recovered.data[i] = 32;
        }
    }
    var depth: usize = 0;
    i = 0;
    for(; i != count; i++) {
        var s = &spans[i];
        var kept = s.start < q.boundary;
        if s.start >= end {
            kept = true;
        }
        if s.opaque {
            kept = false;
        }
        if kept {
            var open = completion_slice(source, s.start, s.end, "{");
            var close = completion_slice(source, s.start, s.end, "}");
            if open {
                depth++;
            }
            if depth != 0 {
                if close {
                    depth--;
                }
            }
        }
    }
    // Bounded recovery; deeply malformed input still gets grammar suggestions.
    if depth < 256 {
        for(; depth != 0; depth--) {
            sem_require(vector_push(&q.recovered, 125));
        }
    }
    sem_require(host_text_terminate(&q.recovered));
    completion_text(&q.output, "{\"from\":");
    sem_require(host_json_unsigned(&q.output, convert(u64, q.from)));
    completion_text(&q.output, ",\"to\":");
    sem_require(host_json_unsigned(&q.output, convert(u64, q.to)));
    completion_text(&q.output, ",\"options\":[");
    return q;
}

fn completion_name(node: void*): u8* {
    var name = sem_member(node, "name");
    loop {
        if !(sem_child_count(name) == 1) {
            break;
        }
        name = sem_child(name, 0);
    }
    return sem_label(name);
}

fn completion_fold(byte: u8): u8 {
    var upper = byte >= 65;
    upper &&= byte <= 90;
    if upper {
        byte = byte + 32;
    }
    return byte;
}

export fn completion_offer(q: CompletionQuery*, name: u8*, kind: u8*, detail: u8*, category: u32): void {
    if q.hidden {
        return;
    }
    if name == null {
        return;
    }
    var keyword = sem_equal(kind, "keyword");
    if !syntax_completion_accepts(q.active, name, keyword) {
        return;
    }
    if sem_equal(kind, "function") {
        if !syntax_completion_callable(q.active) {
            return;
        }
    }
    if keyword {
        var value_literal = sem_equal(name, "true");
        if sem_equal(name, "false") {
            value_literal = true;
        }
        if sem_equal(name, "null") {
            value_literal = true;
        }
        if value_literal {
            if !q.editor.found {
                return;
            }
            if q.editor.kind == 2 {
                return;
            }
            if q.editor.require_pointer {
                if !sem_equal(name, "null") {
                    return;
                }
            }
        }
        if q.editor.found {
            if sem_equal(name, "return") {
                var scope_node = q.editor.node;
                while scope_node != null {
                    if sem_is(scope_node, "TowerDefer") {
                        return;
                    }
                    scope_node = sem_parent(scope_node);
                }
            }
            var loop_control = sem_equal(name, "break");
            if sem_equal(name, "continue") {
                loop_control = true;
            }
            if loop_control {
                if q.editor.loops == 0 {
                    return;
                }
            }
            if q.editor.current != q.program.root {
                if sem_equal(name, "fn") {
                    return;
                }
                if sem_equal(name, "struct") {
                    return;
                }
                if sem_equal(name, "enum") {
                    return;
                }
                if sem_equal(name, "export") {
                    return;
                }
                if sem_equal(name, "extern") {
                    return;
                }
            }
        }
        // LR legality is necessary; literal values also obey the expected type.
        if q.editor.found {
            if q.editor.has_expected {
                var boolean = sem_equal(name, "true");
                if sem_equal(name, "false") {
                    boolean = true;
                }
                if boolean {
                    if q.editor.type.scalar != SBool {
                        return;
                    }
                    if q.editor.type.pointers != 0 {
                        return;
                    }
                }
                if sem_equal(name, "null") {
                    if q.editor.type.pointers == 0 {
                        return;
                    }
                }
            }
        }
    } else {
        if category != 2 {
            if !q.editor.found {
                return;
            }
        }
    }
    var mode = q.mode;
    if keyword {
        mode = 4;
    }
    if q.editor.found {
        if !keyword {
            mode = 0;
            if q.editor.kind == 2 {
                mode = 1;
            }
            var editor_condition17 = q.editor.kind == 3;
            if q.editor.kind == EditorEnumMembers {
                editor_condition17 = true;
            }
            if editor_condition17 {
                mode = 3;
            }
        }
    }
    if mode == 3 {
        var wrong = category != 3;
        if wrong {
            return;
        }
    }
    if mode == 2 {
        var wrong = category != 2;
        if wrong {
            return;
        }
    }
    if mode == 1 {
        var wrong = category != 1;
        if wrong {
            return;
        }
    }
    if mode == 0 {
        var wrong = category == 2;
        if category == 3 {
            wrong = true;
        }
        if category == 1 {
            wrong = true;
        }
        if wrong {
            return;
        }
    }
    var size = sem_length(name);
    if size == 0 {
        return;
    }
    var prefix = q.cursor -q.from;
    if size < prefix {
        return;
    }
    var i: usize = 0;
    for(; i != prefix; i++) {
        var at = q.from + i;
        if completion_fold(name[i]) != completion_fold(q.source[at]) {
            return;
        }
    }
    i = 0;
    for(; i != q.names.length; i++) {
        if sem_equal(name, q.names.data[i]) {
            return;
        }
    }
    if q.count >= 128 {
        return;
    }
    sem_require(vector_push(&q.names, name));
    if q.count != 0 {
        completion_text(&q.output, ",");
    }
    completion_text(&q.output, "{\"label\":");
    sem_require(host_json_quote(&q.output, name, size));
    completion_text(&q.output, ",\"type\":");
    sem_require(host_json_quote(&q.output, kind, sem_length(kind)));
    completion_text(&q.output, ",\"detail\":");
    sem_require(host_json_quote(&q.output, detail, sem_length(detail)));
    completion_text(&q.output, "}");
    q.count++;
}

fn completion_semantic_node(q: CompletionQuery*, node: void*, kind: u8*, category: u32): void {
    var value = sem_get(node);
    if value == null {
        return;
    }
    if sem_equal(kind, "variable") {
        var name = sem_name(value);
        foreach(var & binding in &q.bindings) {
            if sem_equal(name, *binding) {
                return;
            }
        }
        sem_require(vector_push(&q.bindings, name));
    }
    if category != 1 {
        if q.editor.value_required {
            if value.type.pointers == 0 {
                if value.type.scalar == SVoid {
                    return;
                }
            }
        }
        if q.editor.require_pointer {
            if value.type.pointers == 0 {
                return;
            }
        }
        if q.editor.require_integer {
            if !semantic_integer(&value.type) {
                return;
            }
            if semantic_enum(&value.type) {
                return;
            }
        }
        if q.editor.has_expected {
            if !semantic_type_equal(&value.type, &q.editor.type) {
                return;
            }
        }
    }
    var name = sem_name(value);
    // Source identifiers keep their compilable quoted spelling when present.
    var syntax_name = completion_name(node);
    if syntax_name != null {
        if syntax_name[0] != 0 {
            name = syntax_name;
        }
    }
    completion_offer(q, name, kind, sem_type_name(&q.context, &value.type), category);
}

fn completion_table(q: CompletionQuery*, table: SemanticTable*, kind: u8*, category: u32): void {
    var scope: SemanticScope;
    scope.parent = null;
    scope.names = table;
    var nodes: vector(void*);
    vector_init(&nodes);
    sem_scope_locals(&q.context, &scope, &nodes);
    foreach(var candidate in &nodes) {
        var lexical = table == q.context.functions;
        lexical ||= table == q.context.globals;
        lexical ||= table == q.context.types;
        var visible = true;
        if lexical {
            visible = sem_completion_visible(&q.context, &q.editor, table, candidate);
        }
        if visible {
            completion_semantic_node(q, candidate, kind, category);
        }
    }
    vector_dispose(&nodes);
}

fn completion_templates(q: CompletionQuery*, table: SemanticTable*, kind: u8*, detail: u8*, category: u32): void {
    var scope: SemanticScope;
    scope.parent = null;
    scope.names = table;
    var nodes: vector(void*);
    vector_init(&nodes);
    sem_scope_locals(&q.context, &scope, &nodes);
    foreach(var node in &nodes) {
        var eligible = sem_completion_visible(&q.context, &q.editor, table, node);
        if category == 0 {
            // Resolve return annotations with the ordinary type resolver when
            // possible. An unbound type parameter remains unknown, never guessed.
            q.program.error.length = 0;
            var result = sem_type(&q.context, sem_member(node, "type"));
            var known = sem_ok(&q.context);
            q.program.error.length = 0;
            if known {
                if q.editor.value_required {
                    var is_void = result.scalar == SVoid;
                    is_void &&= result.pointers == 0;
                    if is_void {
                        eligible = false;
                    }
                }
                if q.editor.has_expected {
                    eligible &&= semantic_type_equal(result, &q.editor.type);
                }
                if q.editor.require_pointer {
                    if !(result.pointers != 0) {
                        eligible = false;
                    }
                }
            }
        }
        if eligible {
            completion_offer(q, completion_name(node), kind, detail, category);
        }
    }
    vector_dispose(&nodes);
}

export fn completion_symbols(q: CompletionQuery*): void {
    if !q.editor.found {
        return;
    }
    if q.editor.module == null {
        var owner = sem_owner(&q.context, q.editor.node);
        var imports = sem_child_count(owner);
        var i: usize = 0;
        var category: u32 = 0;
        var types = q.editor.kind == 2;
        if types {
            category = 1;
        }
        for(; i < imports; i++) {
            var name = sem_import_alias(owner, i);
            if name[0] != 0 {
                completion_offer(q, name, "namespace", "module", category);
            }
        }
    }
    if q.editor.kind == 2 {
        completion_table(q, q.context.types, "type", 1);
        completion_templates(q, q.context.type_functions, "type", "type function", 1);
        return;
    }
    var editor_condition25 = q.editor.kind == 3;
    var enum_members = q.editor.kind == EditorEnumMembers;
    if enum_members {
        editor_condition25 = true;
    }
    if editor_condition25 {
        var editor_condition26 = q.editor.receiver.scalar != SStruct;
        if enum_members {
            editor_condition26 = semantic_enum(&q.editor.receiver) == false;
        }
        if editor_condition26 {
            return;
        }
        if q.editor.receiver.pointers > 1 {
            return;
        }
        var record = sem_get(q.editor.receiver.record);
        if record == null {
            return;
        }
        foreach(var & item in &record.items) {
            completion_semantic_node(q, *item, "property", 3);
        }
        return;
    }
    var editor_condition30 = q.editor.kind != 4;
    var qualified = q.editor.module != null;
    if editor_condition30 {
        var scope = q.editor.scope;
        if qualified {
            scope = null;
        }
        loop {
            if scope == null {
                break;
            }
            completion_table(q, scope.names, "variable", 0);
            scope = scope.parent;
        }
        completion_table(q, q.context.globals, "variable", 0);
    }
    completion_table(q, q.context.functions, "function", 0);
    completion_templates(q, q.context.templates, "function", "generic function", 0);
    if qualified {
        return;
    }
    var i: usize = 0;
    loop {
        var builtin = semantic_builtin_at(i);
        if builtin == 0 {
            break;
        }
        var eligible: bool = true;
        if q.editor.value_required {
            if builtin == KPrint {
                eligible = false;
            }
            if builtin == KFree {
                eligible = false;
            }
            if builtin == KCopy {
                eligible = false;
            }
            if builtin == KFill {
                eligible = false;
            }
        }
        if q.editor.require_pointer {
            eligible = builtin == KAllocate;
            if builtin == KReallocate {
                eligible = true;
            }
            if builtin == KBits {
                eligible = true;
            }
        }
        if q.editor.has_expected {
            // Void operations cannot supply a required value. Polymorphic
            // operations retain their normal semantic checks after insertion.
            if builtin == KPrint {
                eligible = false;
            }
            if builtin == KFree {
                eligible = false;
            }
            if builtin == KCopy {
                eligible = false;
            }
            if builtin == KFill {
                eligible = false;
            }
            if builtin == KSizeOf {
                eligible = q.editor.type.scalar == SUSize;
                if q.editor.type.pointers != 0 {
                    eligible = false;
                }
            }
            if builtin == KAlignOf {
                eligible = q.editor.type.scalar == SUSize;
                if q.editor.type.pointers != 0 {
                    eligible = false;
                }
            }
            if builtin == KAllocate {
                eligible = q.editor.type.pointers != 0;
            }
            if builtin == KReallocate {
                eligible = q.editor.type.pointers != 0;
            }
        }
        var label = builtin == KLabel;
        var jump = builtin == KJump;
        var control = label;
        if jump {
            control = true;
        }
        if control {
            if q.editor.current == q.program.root {
                eligible = false;
            }
            if label {
                if q.editor.blocks != 1 {
                    eligible = false;
                }
            }
            if jump {
                if q.context.labels == null {
                    eligible = false;
                } else {
                    if q.context.labels.count == 0 {
                        eligible = false;
                    }
                }
            }
        }
        var no_value = control;
        if builtin == KTrap {
            no_value = true;
        }
        if no_value {
            if q.editor.value_required {
                eligible = false;
            }
            if q.editor.has_expected {
                eligible = false;
            }
        }
        if eligible {
            completion_offer(q, semantic_builtin_name(builtin), "function", "foundation operation", 0);
        }
        i++;
    }
}

export fn completion_end(q: CompletionQuery*): u8* {
    completion_text(&q.output, "]}");
    sem_require(host_text_terminate(&q.output));
    return q.output.data;
}

export fn completion_dispose(q: CompletionQuery*): void {
    language_grammar_dispose(q);
    if q.analyzed {
        sem_context_dispose(&q.context);
    }
    if q.semantic {
        semantic_program_dispose(&q.program);
        entity_release(q.program.root);
    }
    if q.inspection_session != null {
        syntax_destroy(q.inspection_session);
    }
    vector_dispose(&q.comment_modules);
    vector_dispose(&q.comment_bases);
    vector_dispose(&q.input);
    vector_dispose(&q.roots);
    vector_dispose(&q.bases);
    vector_dispose(&q.recovered);
    vector_dispose(&q.names);
    vector_dispose(&q.bindings);
    vector_dispose(&q.output);
    free(q);
}

import tower;

// Private component slots and lifecycle IDs, not Foundation operation numbers.
var CompilerParserRule: u32 = 0;
var CompilerParserReference: u32 = 1;
var CompilerParserString: u32 = 2;
var CompilerParserRange: u32 = 3;
var CompilerParserMatch: u32 = 4;
var CompilerSyntax: u32 = 5;
var CompilerFoundation: u32 = 6;
var CompilerSyntaxOrigin: u32 = 7;
var CompilerSyntaxExpansion: u32 = 8;
var CompilerComponentCount: u32 = 9;

fn compiler_foundation_lifecycle(): usize {
    var last: usize = 0;
    last--;
    return last;
}

fn compiler_syntax_lifecycle(): usize {
    var value = compiler_foundation_lifecycle() -1;
    return value;
}

fn compiler_parser_lifecycle(kind: u32): usize {
    var value = compiler_syntax_lifecycle() -1;
    value = value - convert(usize, kind);
    return value;
}

fn compiler_origin_lifecycle(): usize {
    var value = compiler_parser_lifecycle(CompilerParserMatch) -1;
    return value;
}

fn compiler_expansion_lifecycle(): usize {
    var value = compiler_origin_lifecycle() -1;
    return value;
}

import tower;

extern fn abort(): void;

// Infallible compiler ownership operations use the existing fatal allocation
// contract. Recoverable entity-library operations continue to return failure.
fn compiler_entity_require(ok: bool): void {
    if !ok {
        abort();
    }
}

import tower;
import component_kinds;
import execution_session;
import semantic_program_types;
import format_types;
import .library.bytes_types;
import .library.bytes_interface;

extern fn compiler_node_type(node: void*, kind: u32): void*;

extern fn format_entity(out: FormatResult*, root: void*, syntax: void*, foundation: void*, match_kind: void*): void;

extern fn format_dispose(out: FormatResult*): void;

extern fn bytecode_validate(data: u8*, size: usize): u32;

extern fn bytecode_error(code: u32): u8*;

extern fn bytecode_source_size(data: u8*): usize;

extern fn bytecode_pointer_bytes(data: u8*): usize;

extern fn bytecode_encode(fast: void*, source: u8*, size: usize, width: usize, profile: u32, length: usize*): u8*;

extern fn bytecode_matches(fast: void*, data: u8*): bool;

extern fn bytecode_free(data: u8*): void;

// The caller installs the canonical bundled grammar before reconstruction.
// Envelope validation precedes every section read; the cache is verified against
// a newly checked Foundation graph before it can execute.
fn execution_package_load(execution: ExecutionSession*, data: u8*, size: usize, modules: void*): bool {
    execution_session_close(execution);
    var invalid = bytecode_validate(data, size);
    if invalid != 0 {
        execution_session_fail(execution, bytecode_error(invalid), 0);
        return false;
    }
    var length = bytecode_source_size(data);
    var source = data + 56;
    for(var i: usize = 0; i < length; i++) {
        if source[i] == 0 {
            execution_session_fail(execution, "NUL in .towerbc Foundation source", 0);
            return false;
        }
    }
    var text: ByteBuffer = default;
    if !bytes_assign_text(&text, source, length) {
        execution_session_fail(execution, "Unable to allocate .towerbc Foundation source", 0);
        return false;
    }
    var ok = execution_session_compile(execution, text.data, text.length, convert(u32, bytecode_pointer_bytes(data)), modules);
    bytes_dispose(&text);
    if !ok {
        return false;
    }
    if !execution_session_fast(execution) || !bytecode_matches(execution.fast, data) {
        execution_session_fail(execution, bytecode_error(9), 0);
        return false;
    }
    return true;
}

// Serialize the canonical reconstruction, never the original parse provenance
// or a host-address-dependent cache. The temporary session owns all resources.
fn execution_package_encode(program: SemanticProgram*, modules: void*, profile: u32, output: ByteBuffer*, error: ByteBuffer*): bool {
    output.length = 0;
    error.length = 0;
    if program.error.length != 0 {
        if !bytes_assign_text(error, program.error.data, program.error.length) {
            abort();
        }
        return false;
    }
    var formatted: FormatResult = default;
    format_entity(&formatted, program.root, compiler_node_type(program.root, CompilerSyntax), null,
    compiler_node_type(program.root, CompilerParserMatch));
    var canonical: ExecutionSession = default;
    var ok = !formatted.failed;
    if !ok {
        execution_session_fail(&canonical, "Unable to allocate canonical formatted source", 0);
    }
    ok &&= execution_session_compile(&canonical, formatted.text.data, formatted.text.length, program.pointer_bytes, modules);
    if ok {
        ok = execution_session_fast(&canonical);
        if !ok {
            execution_session_fail(&canonical, "Unable to allocate interpreter cache", 0);
        }
    }
    if ok {
        var size: usize = 0;
        var data = bytecode_encode(canonical.fast, formatted.text.data, formatted.text.length, convert(usize, program.pointer_bytes), profile, &size);
        ok = data != null;
        if ok {
            ok = bytes_append(output, data, size);
            bytecode_free(data);
        }
        if !ok {
            execution_session_fail(&canonical, "Cannot allocate .towerbc package", 0);
        }
    }
    if !ok && !bytes_assign_text(error, canonical.error.data, canonical.error.length) {
        abort();
    }
    execution_session_close(&canonical);
    format_dispose(&formatted);
    return ok;
}

import tower;
import interpreter_types;
import semantic_program_types;
import foundation_types;
import format_types;
import .library.bytes_types;
import .library.bytes_interface;

// One request owns its checked Foundation entities, derived execution cache and
// guest storage. The module environment is borrowed only during compilation.
// Hosts supply the existing im_* callbacks; this service has no CLI/IDE transport.
struct ExecutionSession {
    machine: IMState;
    program: SemanticProgram;
    fast: void*;
    error: ByteBuffer;
    output: ByteBuffer;
    started: bool;
}

extern fn compiler_host_world(): void*;
extern fn compiler_world_store(world: void*): void*;
extern fn frontend_modules_world(modules: void*): void*;
extern fn entity_create(store: void*): void*;

extern fn entity_release(node: void*): usize;

extern fn semantic_initialize(program: SemanticProgram*, root: void*, width: u32): void;

extern fn semantic_program_dispose(program: SemanticProgram*): void;

extern fn frontend_compile_sources(program: SemanticProgram*, sources: FrontendSource*, count: usize, environment: void*): void;

extern fn interpreter_init(machine: IMState*): void;

extern fn interpreter_storage_dispose(machine: IMState*): void;

extern fn interpreter_step(machine: IMState*, budget: usize): void;

extern fn fast_interpreter_create(machine: IMState*): void*;

extern fn fast_interpreter_dispose(fast: void*): void;

extern fn fast_interpreter_step(machine: IMState*, fast: void*, budget: usize): void;

extern fn strlen(text: u8*): usize;

extern fn abort(): void;

extern fn bytes_assign_text(out: ByteBuffer*, text: u8*, length: usize): bool;

fn execution_session_close(execution: ExecutionSession*): void {
    if execution.fast != null {
        fast_interpreter_dispose(execution.fast);
    }
    interpreter_storage_dispose(&execution.machine);
    var root = execution.program.root;
    semantic_program_dispose(&execution.program);
    if root != null {
        entity_release(root);
    }
    bytes_dispose(&execution.error);
    bytes_dispose(&execution.output);
    *execution = default;
}

fn execution_session_fail(execution: ExecutionSession*, text: u8*, offset: usize): void {
    if execution.error.length == 0 {
        if !bytes_assign_text(&execution.error, text, strlen(text)) {
            abort();
        }
        execution.machine.failed = true;
        execution.machine.error_offset = offset;
    }
}

fn execution_session_compile_sources(execution: ExecutionSession*, sources: FrontendSource*, count: usize, width: u32, modules: void*): bool {
    // Compatibility callers may supply an unbound environment. A bound one
    // selects its own world; no process-wide current-world switch is needed.
    var world = frontend_modules_world(modules) ?? compiler_host_world();
    return execution_session_compile_sources_world(execution, world, sources, count, width, modules);
}

fn execution_session_compile_sources_world(execution: ExecutionSession*, world: void*, sources: FrontendSource*, count: usize, width: u32, modules: void*): bool {
    execution_session_close(execution);
    var root = world is null ? null : entity_create(compiler_world_store(world));
    if root is null {
        execution_session_fail(execution, "Unable to allocate compiler root", 0);
        execution.machine.done = true;
        return false;
    }
    semantic_initialize(&execution.program, root, width);
    // The remaining frontend boundary reads NUL-terminated source. Preserve the
    // request's explicit bounds even for formatter buffers and package sections.
    var inputs = alloc(FrontendSource, count);
    var snapshots = alloc(ByteBuffer, count);
    if count != 0 &&(inputs == null || snapshots == null) {
        free(inputs);
        free(snapshots);
        execution_session_fail(execution, "Unable to allocate compiler input storage", 0);
        execution.machine.done = true;
        return false;
    }
    fill(snapshots, 0, count *sizeof(ByteBuffer));
    var copied = true;
    for(var i: usize = 0; i < count; i++) {
        if !bytes_assign_text(&snapshots[i], sources[i].data, sources[i].length) {
            copied = false;
            break;
        }
        inputs[i].data = snapshots[i].data;
        inputs[i].length = snapshots[i].length;
    }
    if copied {
        frontend_compile_sources(&execution.program, inputs, count, modules);
    }
    for(var i: usize = 0; i < count; i++) {
        bytes_dispose(&snapshots[i]);
    }
    free(snapshots);
    free(inputs);
    if !copied {
        execution_session_fail(execution, "Unable to allocate compiler input storage", 0);
        execution.machine.done = true;
        return false;
    }
    if !bytes_assign_text(&execution.error, execution.program.error.data, execution.program.error.length) {
        execution_session_fail(execution, "Unable to allocate compiler diagnostic", execution.program.error_offset);
    }
    execution.machine.error_offset = execution.program.error_offset;
    execution.machine.failed = execution.error.length != 0;
    execution.machine.done = execution.machine.failed;
    execution.machine.stack = 16;
    execution.machine.heap = 4194304;
    return !execution.machine.failed;
}

fn execution_session_compile(execution: ExecutionSession*, text: u8*, length: usize, width: u32, modules: void*): bool {
    var input: FrontendSource;
    input.data = text;
    input.length = length;
    return execution_session_compile_sources(execution, &input, 1, width, modules);
}

fn execution_session_start(execution: ExecutionSession*): bool {
    if !execution.started {
        execution.started = true;
        interpreter_init(&execution.machine);
    }
    return !execution.machine.failed;
}

fn execution_session_fast(execution: ExecutionSession*): bool {
    if execution.machine.steps != 0 || !execution_session_start(execution) {
        return false;
    }
    if execution.fast == null {
        execution.fast = fast_interpreter_create(&execution.machine);
    }
    return execution.fast != null;
}

fn execution_session_step(execution: ExecutionSession*, budget: usize): void {
    if !execution_session_start(execution) {
        return;
    }
    if execution.fast != null {
        fast_interpreter_step(&execution.machine, execution.fast, budget);
    }
    else {
        interpreter_step(&execution.machine, budget);
    }
}

fn execution_session_append(execution: ExecutionSession*, text: u8*, count: usize): void {
    if !bytes_append(&execution.output, text, count) {
        abort();
    }
    execution.machine.output_bytes += count;
}

import interpreter_types;
import tower;
import foundation_tags;
import foundation_types;
import interpreter_abi;
import interpreter_storage;
import interpreter;
import .library.vector;
import .library.float_bits;

var FMIntegerBinaryBase: usize = 64;
var FMIntegerTypeCount: usize = 8;
var FMUInt8: usize = 0;
var FMUInt32: usize = 1;
var FMInt32: usize = 2;
var FMUInt64: usize = 3;
var FMInt64: usize = 4;
var FMInt8: usize = 5;
var FMUInt16: usize = 6;
var FMInt16: usize = 7;
var FMFloat32BinaryBase: usize = 192;
var FMFloat64BinaryBase: usize = 208;
var FMIndirectCall: usize = 25;
var FMCheckFunction: usize = 26;
var FMDirectCall: usize = 15;

// Private, disposable execution cache of checked foundation nodes. This is not
// an interchange format or a second semantic IR. No graph pointers or compiler
// metadata occur in the instruction words. Cold provenance/type/binding tables
// retain references to the owning program. The entire compiler and runner here
// use ordinary Foundation operations, with no computed goto, JIT or native ABI.
struct FMFunction {
    node: void*;
    entry: usize;
    registers: usize;
    frame_size: usize;
    parameters: usize;
    parameter_count: usize;
    external: bool;
    pinned: usize;
}

struct FMParameter {
    offset: usize;
    size: usize;
    register_slot: usize;
}

struct FMConversion {
    from: FoundationType*;
    to: FoundationType*;
}

struct FMSource {
    pc: usize;
    offset: usize;
}

struct FMFrame {
    pc: usize;
    base: usize;
    registers: usize;
    result: usize;
    count: usize;
}

struct FMState {
    words: vector(u32);
    constants: vector(u64);
    functions: vector(FMFunction);
    function_indices: vector(usize);
    parameters: vector(FMParameter);
    types: vector(FoundationType*);
    conversions: vector(FMConversion);
    strings: vector(void*);
    sources: vector(FMSource);
    registers: vector(u64);
    frames: vector(FMFrame);
    labels: vector(IMEntry);
    jumps: vector(IMEntry);
    locals: vector(IMEntry);
    escaped: vector(u64);
    pinned: usize;
    next_register: usize;
    max_register: usize;
    pc: usize;
    base: usize;
    register_base: usize;
    register_count: usize;
    current_offset: usize;
    instructions: usize;
    wide_instructions: usize;
    preserve_error_offset: bool;
}

fn fm_push(T: type, values: vector(T)*, value: T*): void {
    var needed = values.length + 1;
    im_storage_require(vector_reserve(values, needed));
    copy(&values.data[values.length], value, sizeof(T));
    values.length = needed;
}

fn fm_trim(T: type, values: vector(T)*): void {
    if values.length == 0 {
        vector_dispose(values);
        return;
    }
    if values.length == values.capacity {
        return;
    }
    var data = realloc(T, values.data, values.length);
    var ok = data != null;
    im_storage_require(ok);
    values.data = data;
    values.capacity = values.length;
}

fn fm_register(f: FMState*): usize {
    var result = f.next_register;
    f.next_register = result + 1;
    if f.next_register > f.max_register {
        f.max_register = f.next_register;
    }
    return result;
}

fn fm_word(f: FMState*, value: usize): void {
    im_storage_require(vector_push(&f.words, convert(u32, value)));
}

fn fm_emit(f: FMState*, op: usize, a: usize, b: usize, c: usize): usize {
    var at = f.words.length;
    var mark = true;
    if f.sources.length != 0 {
        var last = f.sources.length -1;
        mark = f.sources.data[last].offset != f.current_offset;
    }
    if mark {
        var source: FMSource;
        source.pc = at;
        source.offset = f.current_offset;
        fm_push(FMSource, &f.sources, &source);
    }
    f.instructions++;
    // Branch target extensions are one full word; common branch registers still
    // fit in the header. Patching never changes instruction boundaries.
    if op == 13 {
        fm_word(f, 13);
        fm_word(f, a);
        return at;
    }
    var branch = op == 14;
    var small_register = a <= 255;
    branch = im_and(branch, small_register);
    if branch {
        var header = a *256;
        header = header + 14;
        fm_word(f, header);
        fm_word(f, b);
        return at;
    }
    var wide = a > 255;
    var fm_condition_1 = b > 255;

    wide = im_or(wide, fm_condition_1);
    var fm_condition_2 = c > 255;

    wide = im_or(wide, fm_condition_2);
    var fm_condition_3 = op == 13;

    // Branch patches always occupy five words so relocation never shifts code.
    wide = im_or(wide, fm_condition_3);
    var fm_condition_4 = op == 14;

    wide = im_or(wide, fm_condition_4);
    if wide {
        f.wide_instructions++;
        fm_word(f, 255);
        fm_word(f, op);
        fm_word(f, a);
        fm_word(f, b);
        fm_word(f, c);
    } else {
        var word = c *256;
        word = word + b;
        word = word * 256;
        word = word + a;
        word = word * 256;
        word = word + op;
        fm_word(f, word);
    }
    return at;
}

fn fm_patch(f: FMState*, at: usize, operand: usize, target: usize): void {
    var index = at + operand;
    var header = f.words.data[at] &255;
    if header != 255 {
        index = at + 1;
    }
    f.words.data[index] = convert(u32, target);
}

fn fm_constant(f: FMState*, value: u64): usize {
    var index: usize = 0;
    for(; index != f.constants.length; index++) {
        if f.constants.data[index] == value {
            break;
        }
    }
    if index == f.constants.length {
        im_storage_require(vector_push(&f.constants, value));
    }
    var result = fm_register(f);
    fm_emit(f, 0, result, index, 0);
    return result;
}

fn fm_type(f: FMState*, type: FoundationType*): usize {
    var index: usize = 0;
    for(; index != f.types.length; index++) {
        var other = f.types.data[index];
        var same = semantic_type_equal(type, other);
        if same {
            return index;
        }
    }
    im_storage_require(vector_push(&f.types, type));
    return index;
}

fn fm_tag(type: FoundationType*): usize {
    var width = semantic_width(type);
    var signed = im_type_signed(type);
    if width == IntegerByteWidth { return signed ? FMInt8 : FMUInt8; }
    if width == IntegerShortWidth { return signed ? FMInt16 : FMUInt16; }
    if width == IntegerWordWidth { return signed ? FMInt32 : FMUInt32; }
    return signed ? FMInt64 : FMUInt64;
}

fn fm_function(f: FMState*, node: void*): usize {
    var index: usize = 0;
    for(; index != f.functions.length; index++) {
        if f.functions.data[index].node == node {
            return index;
        }
    }
    var n = im_node(node);
    var function: FMFunction = {
        node: node, external: n.external, frame_size: im_align(n.frame_size),
        parameters: f.parameters.length, parameter_count: n.parameters.length, ..default
    };
    foreach(var & parameter in &n.parameters) {
        var param = im_node(*parameter);
        var value: FMParameter = { offset: param.byte_offset, size: im_type_size(&param.type), register_slot: 0 };
        fm_push(FMParameter, &f.parameters, &value);
    }
    fm_push(FMFunction, &f.functions, &function);
    if f.function_indices.length <= n.index {
        var previous = f.function_indices.length;
        im_storage_require(vector_reserve(&f.function_indices, n.index + 1));
        f.function_indices.length = n.index + 1;
        for(var i = previous; i <= n.index; i++) { f.function_indices.data[i] = 0; }
    }
    f.function_indices.data[n.index] = index + 1;
    return index;
}

fn fm_local(f: FMState*, node: void*): usize {
    var n = im_node(node);
    if n.binding != null {
        node = n.binding;
    }
    var key = im_key(node);
    var i: usize = 0;
    loop {
        if i == f.locals.length {
            return 0;
        }
        if f.locals.data[i].key == key {
            return convert(usize, f.locals.data[i].value);
        }
        i++;
    }
}

fn fm_collect_addresses(f: FMState*, node: void*): void {
    if node == null {
        return;
    }
    var n = im_node(node);
    if n.kind == KAddress {
        var place = n.value;
        loop {
            var target = im_node(place);
            var compound = target.kind == KField;
            var indexed = target.kind == KIndex;
            compound = im_or(compound, indexed);
            if compound {
                // Addressing through a pointer does not expose the local that
                // holds the pointer. Direct aggregate fields do expose storage.
                if target.indirect {
                    break;
                }
                place = target.left;
                continue;
            }
            if target.binding != null {
                place = target.binding;
            }
            im_storage_require(vector_push(&f.escaped, im_key(place)));
            break;
        }
    }
    var leaf = n.kind == KLabel;
    if leaf {
        return;
    }
    leaf = n.kind == KJump;
    if leaf {
        return;
    }
    leaf = n.kind == KFunction;
    if leaf {
        return;
    }
    leaf = n.kind == KType;
    if leaf {
        return;
    }
    fm_collect_addresses(f, n.value);
    fm_collect_addresses(f, n.target);
    fm_collect_addresses(f, n.left);
    fm_collect_addresses(f, n.right);
    fm_collect_addresses(f, n.body);
    fm_collect_addresses(f, n.otherwise);
    var i: usize = 0;
    loop {
        if i == n.items.length {
            return;
        }
        fm_collect_addresses(f, n.items.data[i]);
        i++;
    }
}

fn fm_pin_locals(f: FMState*, index: usize, body: void*): void {
    // Register placement for scalar CFG functions. This is code generation,
    // not an optimizer: no operation, effect or control-flow edge is removed.
    // Address-bearing locals retain the ordinary target-memory layout.
    var block = im_node(body);
    var labeled = false;
    var i: usize = 0;
    for(; i != block.items.length; i++) {
        var n = im_node(block.items.data[i]);
        if n.kind == KLabel {
            labeled = true;
        }
    }
    if !labeled {
        return;
    }
    f.escaped.length = 0;
    fm_collect_addresses(f, body);
    var node = im_node(f.functions.data[index].node);
    var all_registers = true;
    i = 0;
    loop {
        var done = i == node.locals.length;
        if done {
            break;
        }
        var local = im_node(node.locals.data[i]);
        var memory = local.global;
        var aggregate = local.type.scalar == 4;
        var array = local.type.scalar == 9;
        aggregate = im_or(aggregate, array);
        var value = local.type.pointers == 0;
        aggregate = im_and(aggregate, value);
        memory = im_or(memory, aggregate);
        var entry: IMEntry;
        entry.key = im_key(node.locals.data[i]);
        var j: usize = 0;
        loop {
            done = j == f.escaped.length;
            if done {
                break;
            }
            var escaped = f.escaped.data[j] == entry.key;
            memory = im_or(memory, escaped);
            j++;
        }
        if memory {
            all_registers = false;
        }
        else {
            var register = fm_register(f);
            register++;
            entry.value = convert(u64, register);
            fm_push(IMEntry, &f.locals, &entry);
        }
        i++;
    }
    f.pinned = f.next_register;
    f.functions.data[index].pinned = f.pinned;
    if all_registers {
        f.functions.data[index].frame_size = 0;
    }
    i = 0;
    for(; i != node.parameters.length; i++) {
        var parameter = f.functions.data[index].parameters + i;
        f.parameters.data[parameter].register_slot = fm_local(f, node.parameters.data[i]);
    }
}

fn fm_address(f: FMState*, node: void*): usize {
    var n = im_node(node);
    if n.kind == KLoad {
        return fm_value(f, n.value);
    }
    var fm_condition_8 = n.kind == KField;
    var fm_condition_9 = n.kind == KIndex;

    if im_or(fm_condition_8, fm_condition_9) {
        var base: usize = 0;
        if n.indirect {
            base = fm_value(f, n.left);
        }
        else {
            base = fm_address(f, n.left);
        }
        var delta: usize = 0;
        if n.kind == KField {
            delta = fm_constant(f, convert(u64, n.byte_offset));
        }
        else {
            delta = fm_value(f, n.right);
            var right = im_node(n.right);
            if im_type_signed(&right.type) {
                var copied = fm_register(f);
                fm_emit(f, 1, copied, delta, 0);
                delta = copied;
                fm_emit(f, 21, delta, fm_tag(&right.type), 0);
            }
            var size = fm_constant(f, convert(u64, im_type_size(&n.type)));
            var scaled = fm_register(f);
            fm_emit(f, FMIntegerBinaryBase + convert(usize, OMul) * FMIntegerTypeCount + FMUInt64, scaled, delta, size);
            delta = scaled;
        }
        var tag = n.type.pointer_bytes == 8 ? FMUInt64 : FMUInt32;
        var op = FMIntegerBinaryBase + convert(usize, OAdd) * FMIntegerTypeCount + tag;
        var result = fm_register(f);
        fm_emit(f, op, result, base, delta);
        return result;
    }
    var binding = n;
    if n.binding != null {
        binding = im_node(n.binding);
    }
    var op: usize = 2;
    if binding.global {
        op = 3;
    }
    var result = fm_register(f);
    fm_emit(f, op, result, binding.byte_offset, 0);
    return result;
}

fn fm_value(f: FMState*, node: void*): usize {
    if node == null {
        return fm_constant(f, 0);
    }
    var n = im_node(node);
    if n.kind == KFunctionReference {
        fm_function(f, n.binding);
        return fm_constant(f, convert(u64, im_node(n.binding).index) + 1);
    }
    var fm_condition_10 = n.kind == KOperand;

    var constant = im_and(fm_condition_10, n.constant);
    if constant {
        return fm_constant(f, n.bits);
    }
    var address = n.kind == KAddress;
    if address {
        return fm_address(f, n.value);
    }
    var query = n.kind == KSizeOf;
    if query {
        return fm_constant(f, convert(u64, im_type_size(&n.element)));
    }
    query = n.kind == KAlignOf;
    if query {
        return fm_constant(f, convert(u64, im_type_alignment(&n.element)));
    }
    if n.kind == KString {
        var index = f.strings.length;
        im_storage_require(vector_push(&f.strings, node));
        var result = fm_register(f);
        fm_emit(f, 18, result, index, 0);
        return result;
    }
    if n.kind == KOperand {
        var slot = fm_local(f, node);
        if slot != 0 {
            slot--;
            return slot;
        }
        var binding = n;
        if n.binding != null {
            binding = im_node(n.binding);
        }
        var result = fm_register(f);
        var op: usize = 19;
        if binding.global {
            op = 23;
        }
        fm_emit(f, op, result, binding.byte_offset, im_type_size(&n.type));
        return result;
    }
    var fm_condition_11 = n.kind == KField;
    var fm_condition_12 = n.kind == KIndex;

    var place = im_or(fm_condition_11, fm_condition_12);
    var fm_condition_13 = n.kind == KLoad;

    place = im_or(place, fm_condition_13);
    if place {
        var address = fm_address(f, node);
        var result = fm_register(f);
        fm_emit(f, 4, result, address, im_type_size(&n.type));
        return result;
    }
    if n.kind == KCall {
        var callee: usize = 0;
        if n.value != null { callee = fm_value(f, n.value); }
        var result = fm_register(f);
        var first = f.next_register;
        var i: usize = 0;
        for(; i != n.items.length; i++) {
            fm_register(f);
        }
        i = 0;
        for(; i != n.items.length; i++) {
            var arg = fm_value(f, n.items.data[i]);
            var dest = first + i;
            fm_emit(f, 1, dest, arg, 0);
        }
        if n.value == null { fm_emit(f, FMDirectCall, result, fm_function(f, n.binding), first); }
        else {
            fm_emit(f, FMCheckFunction, callee, fm_type(f, &im_node(n.value).type), 0);
            fm_emit(f, FMIndirectCall, result, callee, first);
        }
        return result;
    }
    var fm_condition_14 = n.kind == KAllocate;
    var fm_condition_15 = n.kind == KReallocate;

    if im_or(fm_condition_14, fm_condition_15) {
        var pointer = fm_value(f, n.left);
        var count = fm_value(f, n.right);
        var result = fm_register(f);
        fm_emit(f, 1, result, pointer, 0);
        var op: usize = 8;
        if n.kind == KReallocate {
            op = 9;
        }
        fm_emit(f, op, result, count, im_type_size(&n.element));
        return result;
    }
    if n.kind == KBinary {
        var left = fm_value(f, n.left);
        var right = fm_value(f, n.right);
        var input = im_node(n.left);
        var pointer = input.type.pointers != 0;
        var fm_condition_16 = n.op == OAdd;
        var fm_condition_17 = n.op == OSub;

        var arithmetic = im_or(fm_condition_16, fm_condition_17);
        pointer = im_and(pointer, arithmetic);
        if pointer {
            var scaled = fm_register(f);
            fm_emit(f, 1, scaled, right, 0);
            right = scaled;
            var right_node = im_node(n.right);
            if im_type_signed(&right_node.type) {
                fm_emit(f, 21, right, fm_tag(&right_node.type), 0);
            }
            var size = fm_constant(f, convert(u64, im_pointee_size(&input.type)));
            fm_emit(f, FMIntegerBinaryBase + convert(usize, OMul) * FMIntegerTypeCount + FMUInt64, right, right, size);
        }
        var op = convert(usize, n.op) * FMIntegerTypeCount;
        op = op + FMIntegerBinaryBase;
        op = op + fm_tag(&input.type);
        if semantic_float(&input.type) {
            op = convert(usize, n.op) + (input.type.scalar == SF32 ? FMFloat32BinaryBase : FMFloat64BinaryBase);
        }
        var result = fm_register(f);
        fm_emit(f, op, result, left, right);
        return result;
    }
    var value = fm_value(f, n.value);
    if n.kind == KConvert {
        var input = im_node(n.value);
        var descriptor: FMConversion;
        descriptor.from = &input.type;
        descriptor.to = &n.type;
        var index = f.conversions.length;
        fm_push(FMConversion, &f.conversions, &descriptor);
        var result = fm_register(f);
        fm_emit(f, 7, result, value, index);
        return result;
    }
    // Bits preserves exactly the same width by the foundation verifier.
    return value;
}

fn fm_statement(f: FMState*, node: void*, breaks: vector(usize)*, continue_pc: usize): void {
    var n = im_node(node);
    f.current_offset = n.start;
    f.next_register = f.pinned;
    if n.kind == KLabel {
        var entry: IMEntry;
        entry.key = im_key(node);
        entry.value = convert(u64, f.words.length);
        fm_push(IMEntry, &f.labels, &entry);
        return;
    }
    if n.kind == KJump {
        var entry: IMEntry;
        entry.key = im_key(n.binding);
        var at = fm_emit(f, 13, 0, 0, 0);
        entry.value = convert(u64, at);
        fm_push(IMEntry, &f.jumps, &entry);
        return;
    }
    if n.kind == KTrap {
        var message = fm_value(f, n.left);
        var offset = fm_value(f, n.right);
        fm_emit(f, 22, message, offset, 0);
        return;
    }
    var fm_condition_18 = n.kind == KBlock;
    var fm_condition_19 = n.kind == KProgram;

    if im_or(fm_condition_18, fm_condition_19) {
        foreach(var & item in &n.items) {
            fm_statement(f, *item, breaks, continue_pc);
        }
        return;
    }
    var fm_condition_20 = n.kind == KFunction;
    var fm_condition_21 = n.kind == KType;

    if im_or(fm_condition_20, fm_condition_21) {
        return;
    }
    var declaration = n.kind == KDeclare;
    var fm_condition_22 = n.kind == KAssign;

    if im_or(declaration, fm_condition_22) {
        if n.value != null {
            var target = n.target;
            if declaration {
                target = node;
            }
            var slot = fm_local(f, target);
            if slot != 0 {
                var value = fm_value(f, n.value);
                slot--;
                fm_emit(f, 1, slot, value, 0);
                return;
            }
            var dest = fm_address(f, target);
            var value = fm_value(f, n.value);
            var target_node = im_node(target);
            fm_emit(f, 5, dest, value, im_type_size(&target_node.type));
        }
        return;
    }
    if n.kind == KIf {
        var value = fm_value(f, n.value);
        var branch = fm_emit(f, 14, value, 0, 0);
        fm_statement(f, n.body, breaks, continue_pc);
        var jump = fm_emit(f, 13, 0, 0, 0);
        fm_patch(f, branch, 3, f.words.length);
        if n.otherwise != null {
            fm_statement(f, n.otherwise, breaks, continue_pc);
        }
        fm_patch(f, jump, 2, f.words.length);
        return;
    }
    if n.kind == KLoop {
        var local_breaks: vector(usize);
        vector_init(&local_breaks);
        var start = f.words.length;
        fm_statement(f, n.body, &local_breaks, start);
        fm_emit(f, 13, start, 0, 0);
        foreach(var & local_break in &local_breaks) {
            fm_patch(f, *local_break, 2, f.words.length);
        }
        vector_dispose(&local_breaks);
        return;
    }
    if n.kind == KBreak {
        var at = fm_emit(f, 13, 0, 0, 0);
        im_storage_require(vector_push(breaks, at));
        return;
    }
    if n.kind == KContinue {
        fm_emit(f, 13, continue_pc, 0, 0);
        return;
    }
    if n.kind == KReturn {
        fm_emit(f, 16, fm_value(f, n.value), 0, 0);
        return;
    }
    if n.kind == KPrint {
        var value = fm_value(f, n.value);
        var input = im_node(n.value);
        fm_emit(f, 17, value, fm_type(f, &input.type), 0);
        return;
    }
    if n.kind == KFree {
        fm_emit(f, 10, fm_value(f, n.left), 0, 0);
        return;
    }
    var fm_condition_23 = n.kind == KCopy;
    var fm_condition_24 = n.kind == KFill;

    if im_or(fm_condition_23, fm_condition_24) {
        var left = fm_value(f, n.left);
        var right = fm_value(f, n.right);
        var count = fm_value(f, n.value);
        var op: usize = 11;
        if n.kind == KFill {
            op = 12;
        }
        fm_emit(f, op, left, right, count);
        return;
    }
    fm_value(f, node);
}

export fn fast_interpreter_create(m: IMState*): FMState* {
    var f = alloc(FMState, 1);
    *f = default;
    var failed = m.failed;
    if failed {
        return f;
    }
    fm_function(f, im_root(m));
    var i: usize = 0;
    for(; i != f.functions.length; i++) {
        var node = f.functions.data[i].node;
        var n = im_node(node);
        f.functions.data[i].entry = f.words.length;
        f.max_register = 1;
        f.next_register = 0;
        f.pinned = 0;
        f.locals.length = 0;
        var external = n.external;
        if !external {
            var body = n.body;
            if i == 0 {
                body = node;
            }
            fm_pin_locals(f, i, body);
            fm_statement(f, body, null, 0);
            f.next_register = f.pinned;
            fm_emit(f, 16, fm_constant(f, 0), 0, 0);
        }
        f.functions.data[i].registers = f.max_register;
    }
    i = 0;
    for(; i != f.jumps.length; i++) {
        var j: usize = 0;
        loop {
            var end = j == f.labels.length;
            var available = !end;
            im_storage_require(available);
            if f.labels.data[j].key == f.jumps.data[i].key {
                fm_patch(f, convert(usize, f.jumps.data[i].value), 2, convert(usize, f.labels.data[j].value));
                break;
            }
            j++;
        }
    }
    vector_dispose(&f.labels);
    vector_dispose(&f.jumps);
    vector_dispose(&f.locals);
    vector_dispose(&f.escaped);
    f.base = 16;
    f.register_count = f.functions.data[0].registers;
    im_storage_require(vector_reserve(&f.registers, f.register_count));
    f.registers.length = f.register_count;
    fm_trim(u32, &f.words);
    fm_trim(u64, &f.constants);
    fm_trim(FMFunction, &f.functions);
    fm_trim(usize, &f.function_indices);
    fm_trim(FMParameter, &f.parameters);
    fm_trim(FoundationType*, &f.types);
    fm_trim(FMConversion, &f.conversions);
    fm_trim(void*, &f.strings);
    fm_trim(FMSource, &f.sources);
    // Release graph scheduling storage for this execution. The graph itself is
    // still the program and is available to formatting/reflection outside us.
    im_frame_pop(m);
    var graph_frame = &m.frames.data[0];
    vector_dispose(&graph_frame.tasks);
    vector_dispose(&graph_frame.values);
    vector_dispose(&graph_frame.addresses);
    vector_dispose(&m.frames);
    vector_dispose(&m.node_cache);
    return f;
}

export fn fast_interpreter_dispose(f: FMState*): void {
    vector_dispose(&f.escaped);
    vector_dispose(&f.labels);
    vector_dispose(&f.jumps);
    vector_dispose(&f.locals);
    vector_dispose(&f.words);
    vector_dispose(&f.constants);
    vector_dispose(&f.functions);
    vector_dispose(&f.function_indices);
    vector_dispose(&f.parameters);
    vector_dispose(&f.types);
    vector_dispose(&f.conversions);
    vector_dispose(&f.strings);
    vector_dispose(&f.sources);
    vector_dispose(&f.registers);
    vector_dispose(&f.frames);
    free(f);
}

fn fm_offset(f: FMState*, pc: usize): usize {
    var begin: usize = 0;
    var end = f.sources.length;
    loop {
        if begin == end {
            break;
        }
        var middle = end -begin;
        middle = middle / 2;
        middle = middle + begin;
        if f.sources.data[middle].pc <= pc {
            begin = middle + 1;
        } else {
            end = middle;
        }
    }
    if begin == 0 {
        return 0;
    }
    begin--;
    return f.sources.data[begin].offset;
}

fn fm_mask(tag: usize): u64 {
    var width = IntegerLongWidth;
    if tag == FMUInt8 || tag == FMInt8 { width = IntegerByteWidth; }
    if tag == FMUInt16 || tag == FMInt16 { width = IntegerShortWidth; }
    if tag == FMUInt32 || tag == FMInt32 { width = IntegerWordWidth; }
    return ~convert(u64, 0) >> (IntegerLongWidth - width);
}

fn fm_sign(value: u64, tag: usize): i64 {
    return im_sign_mask(value, fm_mask(tag));
}

fn fm_binary(m: IMState*, opcode: usize, x: u64, y: u64): u64 {
    if opcode >= FMFloat32BinaryBase {
        var wide = opcode >= FMFloat64BinaryBase;
        var base = wide ? FMFloat64BinaryBase : FMFloat32BinaryBase;
        return tower_float_binary(x, y, convert(u32, opcode - base), wide ? Float64Width : Float32Width);
    }
    var instruction = opcode - FMIntegerBinaryBase;
    var op = instruction / FMIntegerTypeCount;
    var tag = instruction % FMIntegerTypeCount;
    var mask = fm_mask(tag);
    var signed = tag == FMInt8 || tag == FMInt16 || tag == FMInt32 || tag == FMInt64;
    var result = im_binary_scalar(m, convert(u32, op), x, y, mask, signed, 0);
    result = result & mask;
    return result;
}

export fn fast_interpreter_step(m: IMState*, f: FMState*, budget: usize): void {
    var count: usize = 0;
    loop {
        var stop = im_or(m.done, m.failed);
        var fm_condition_27 = count == budget;

        stop = im_or(stop, fm_condition_27);
        if stop {
            break;
        }
        var pc = f.pc;
        var word = f.words.data[pc];
        f.pc++;
        var fm_condition_28 = word &255;

        var op = convert(usize, fm_condition_28);
        var unpacked = word / 256;
        var a = convert(usize, unpacked);
        a = a & 255;
        unpacked = word / 65536;
        var b = convert(usize, unpacked);
        b = b & 255;
        unpacked = word / 16777216;
        var c = convert(usize, unpacked);
        if op == 255 {
            var at = pc + 1;
            op = convert(usize, f.words.data[at]);
            at++;
            a = convert(usize, f.words.data[at]);
            at++;
            b = convert(usize, f.words.data[at]);
            at++;
            c = convert(usize, f.words.data[at]);
            f.pc = at + 1;
        } else {
            var jump = op == 13;
            var branch = op == 14;
            if jump {
                a = convert(usize, f.words.data[f.pc]);
                f.pc++;
            }
            if branch {
                b = convert(usize, f.words.data[f.pc]);
                f.pc++;
            }
        }
        var r = &f.registers.data[f.register_base];
        count++;
        m.steps++;
        if op == FMCheckFunction || op == FMIndirectCall {
            var reference = r[op == FMCheckFunction ? a : b];
            var encoded: usize = 0;
            if reference != 0 && reference <= convert(u64, f.function_indices.length) {
                encoded = f.function_indices.data[convert(usize, reference - 1)];
            }
            var offset = fm_offset(f, pc);
            if reference == 0 { im_fail(m, "Cannot call a null function", offset); }
            else { if encoded == 0 { im_fail(m, "Invalid function reference", offset); }
            else { if op == FMCheckFunction {
                if !im_function_matches(f.functions.data[encoded - 1].node, f.types.data[b]) { im_fail(m, "Function reference signature mismatch", offset); }
            } else { fm_call(m, f, a, encoded - 1, c, offset); } } }
            if m.failed { m.done = true; }
            continue;
        }
        if op == 22 {
            f.preserve_error_offset = true;
            im_raise(m, r[a], r[b]);
            m.done = true;
            continue;
        }
        if op >= FMIntegerBinaryBase {
            r[a] = fm_binary(m, op, r[b], r[c]);
        }
        else {
            var selected = op == 0;
            if selected {
                r[a] = f.constants.data[b];
            }
            else {
                selected = op == 1;
                if selected {
                    r[a] = r[b];
                }
                else {
                    selected = op == 2;
                    if selected {
                        var address = f.base + b;
                        r[a] = convert(u64, address);
                    }
                    else {
                        selected = op == 3;
                        if selected {
                            var address = b + 16;
                            r[a] = convert(u64, address);
                        }
                        else {
                            selected = op == 4;
                            if selected {
                                r[a] = im_load_size(m, r[b], c, 0);
                            }
                            else {
                                selected = op == 5;
                                if selected {
                                    im_write_size(m, r[a], r[b], c, 0);
                                }
                                else {
                                    selected = op == 7;
                                    if selected {
                                        var conversion = &f.conversions.data[c];
                                        var result = im_convert_value(m, r[b], conversion.from, conversion.to, 0);
                                        r[a] = result & im_type_mask(conversion.to);
                                    }
                                    else {
                                        var fm_condition_29 = op == 8;
                                        var fm_condition_30 = op == 9;

                                        selected = im_or(fm_condition_29, fm_condition_30);
                                        if selected {
                                            var size = convert(u64, c);
                                            var limit = convert(u64, im_host_max());
                                            if im_pointer_bytes(m) == 4 {
                                                limit = 4294967295;
                                            }
                                            limit = limit / size;
                                            if r[b] > limit {
                                                r[a] = 0;
                                            }
                                            else {
                                                size = size * r[b];
                                                var result: u64 = 0;
                                                if op == 8 {
                                                    result = interpreter_allocate(m, convert(usize, size));
                                                }
                                                else {
                                                    result = interpreter_reallocate(m, r[a], convert(usize, size));
                                                }
                                                r[a] = result;
                                            }
                                        }
                                        else {
                                            selected = op == 10;
                                            if selected {
                                                interpreter_deallocate(m, r[a]);
                                            }
                                            else {
                                                var fm_condition_31 = op == 11;
                                                var fm_condition_32 = op == 12;

                                                selected = im_or(fm_condition_31, fm_condition_32);
                                                if selected {
                                                    var fm_condition_33 = op == 11;
                                                    im_copy_values(m, r[a], r[b], r[c], fm_condition_33, 0);
                                                }
                                                else {
                                                    selected = op == 13;
                                                    if selected {
                                                        f.pc = a;
                                                    }
                                                    else {
                                                        selected = op == 14;
                                                        if selected {
                                                            if r[a] == 0 {
                                                                f.pc = b;
                                                            }
                                                        }
                                                        else {
                                                            selected = op == FMDirectCall;
                                                            if selected {
                                                                fm_call(m, f, a, b, c, 0);
                                                            }
                                                            else {
                                                                selected = op == 16;
                                                                if selected {
                                                                    var value = r[a];
                                                                    m.stack = f.base;
                                                                    if f.frames.length == 0 {
                                                                        m.done = true;
                                                                    }
                                                                    else {
                                                                        f.frames.length--;
                                                                        var frame = &f.frames.data[f.frames.length];
                                                                        f.pc = frame.pc;
                                                                        f.base = frame.base;
                                                                        f.register_base = frame.registers;
                                                                        f.register_count = frame.count;
                                                                        f.registers.length = f.register_base + f.register_count;
                                                                        var dest = f.register_base + frame.result;
                                                                        f.registers.data[dest] = value;
                                                                    }
                                                                }
                                                                else {
                                                                    selected = op == 17;
                                                                    if selected {
                                                                        im_print_value(m, r[a], f.types.data[b]);
                                                                    }
                                                                    else {
                                                                        selected = op == 18;
                                                                        if selected {
                                                                            var node = f.strings.data[b];
                                                                            r[a] = im_read_uncached(m, node, im_node(node), 0);
                                                                        }
                                                                        else {
                                                                            var fm_condition_34 = op == 19;
                                                                            var fm_condition_35 = op == 23;

                                                                            selected = im_or(fm_condition_34, fm_condition_35);
                                                                            if selected {
                                                                                var base = f.base;
                                                                                if op == 23 {
                                                                                    base = 16;
                                                                                }
                                                                                var address = base + b;
                                                                                r[a] = im_load_size(m, convert(u64, address), c, 0);
                                                                            }
                                                                            else {
                                                                                selected = op == 21;
                                                                                if selected {
                                                                                    r[a] = bits(u64, fm_sign(r[a], b));
                                                                                }
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        if m.failed {
            if !f.preserve_error_offset {
                m.error_offset = fm_offset(f, pc);
            }
            m.done = true;
        }
    }
}

fn fm_call(m: IMState*, f: FMState*, dest: usize, index: usize, first: usize, offset: usize): void {
    var function = &f.functions.data[index];
    var arg_index = f.register_base + first;
    if function.external {
        if im_has_foreign(m) == false {
            im_missing_foreign(m, function.node, offset);
            return;
        }
        var value = im_foreign(m, function.node, &f.registers.data[arg_index], function.parameter_count);
        if m.failed {
            f.preserve_error_offset = true;
        }
        var at = f.register_base + dest;
        f.registers.data[at] = value;
        return;
    }
    var remaining: usize = 4194304;
    remaining = remaining - m.stack;
    var exhausted = f.frames.length >= 127;
    var fm_condition_36 = function.frame_size > remaining;

    exhausted = im_or(exhausted, fm_condition_36);
    if exhausted {
        im_fail(m, "Tower call stack limit exceeded", offset);
        return;
    }
    var frame: FMFrame = { pc: f.pc, base: f.base, registers: f.register_base, result: dest, count: f.register_count };
    fm_push(FMFrame, &f.frames, &frame);
    var register_base = f.register_base + f.register_count;
    var needed = register_base + function.registers;
    im_storage_require(vector_reserve(&f.registers, needed));
    f.registers.length = needed;
    f.register_count = function.registers;
    f.register_base = register_base;
    f.base = m.stack;
    m.stack = m.stack + function.frame_size;
    var pinned_bytes = function.pinned *8;
    fill(&f.registers.data[register_base], 0, pinned_bytes);
    var i: usize = 0;
    for(; i != function.parameter_count; i++) {
        var param_index = function.parameters + i;
        var parameter = &f.parameters.data[param_index];
        var address = f.base + parameter.offset;
        var arg = arg_index + i;
        var pinned = parameter.register_slot != 0;
        if pinned {
            var destination = register_base + parameter.register_slot;
            destination--;
            f.registers.data[destination] = f.registers.data[arg];
        } else {
            im_write_size(m, convert(u64, address), f.registers.data[arg], parameter.size, offset);
        }
    }
    f.pc = function.entry;
}

export fn fast_interpreter_stat(f: FMState*, key: usize): usize {
    var selected = key == 0;
    if selected {
        var bytes = f.words.length *4;
        return bytes;
    }
    selected = key == 1;
    if selected {
        return f.instructions;
    }
    selected = key == 2;
    if selected {
        return f.wide_instructions;
    }
    selected = key == 3;
    if selected {
        var bytes = f.registers.capacity *8;
        return bytes;
    }
    var bytes = f.constants.capacity *sizeof(u64);
    var extra = f.functions.capacity *sizeof(FMFunction);
    bytes = bytes + extra;
    bytes += f.function_indices.capacity * sizeof(usize);
    extra = f.parameters.capacity * sizeof(FMParameter);
    bytes = bytes + extra;
    extra = f.types.capacity * sizeof(FoundationType*);
    bytes = bytes + extra;
    extra = f.conversions.capacity * sizeof(FMConversion);
    bytes = bytes + extra;
    extra = f.strings.capacity * sizeof(void*);
    bytes = bytes + extra;
    extra = f.sources.capacity * sizeof(FMSource);
    bytes = bytes + extra;
    extra = f.frames.capacity * sizeof(FMFrame);
    bytes = bytes + extra;
    extra = f.words.capacity * sizeof(u32);
    bytes = bytes + extra;
    extra = f.registers.capacity * sizeof(u64);
    bytes = bytes + extra;
    bytes = bytes + sizeof(FMState);
    return bytes;
}

import format_types;
import format_dependent;
import tower;
