// An invocation context belongs to its evaluation request, which may be a
// shared compiler entity. No ambient world, host address table or TLS lookup is
// needed. The existing IMState ABI remains unchanged for retained host clients.
struct IMContext {
    root: void*;
    pointer_bytes: usize;
    error: vector(u8);
    output: vector(u8);
    result: u64;
    returned: bool;
    strict: bool;
    fuel: u64;
    initialized: vector(u8);
    dependency_kind: void*;
    value_inputs: void*;
    require_relocatable: bool;
    waiting: void*;
    retain_result_storage: bool;
}

// Shared query metadata; the evaluator reads readiness, while only the
// coordinator materializes the Foundation constant and publishes readiness.
struct IMDependency {
    ready: bool;
    failed: bool;
    subject: void*;
    source: IMDependency*;
}

// Explicit immutable inputs for a staged invocation. The producer is an ordinary
// Foundation scalar value published through the dependency graph. A local's own
// invocation still reads its normal stack storage, including mutable computation.
struct IMValueInput { producer: void*; owner: void*; }

struct IMExecution {
    state: IMState*;
    context: IMContext*;
}

