// Derived lexer tables only: token declarations remain on shared syntax entities.
// Flat transition rows and maximal-prefix matching are owned and executed by Tower.
// A finite-state chain over arbitrary integer symbols. State n accepts; each
// earlier state has one range transition to its successor. No parse stack.
struct SymbolSequence {
    symbols: SymbolRange*;
    count: usize;
}

export fn symbol_sequence_create(count: usize): SymbolSequence* {
    var sequence = alloc(SymbolSequence, 1);
    var failed = sequence == null;
    if failed {
        return null;
    }
    sequence.symbols = alloc(SymbolRange, count);
    failed = sequence.symbols == null;
    if failed {
        free(sequence);
        return null;
    }
    sequence.count = count;
    return sequence;
}

export fn symbol_sequence_destroy(sequence: SymbolSequence*): void {
    if sequence == null {
        return;
    }
    free(sequence.symbols);
    free(sequence);
}

export fn symbol_sequence_set(sequence: SymbolSequence*, state: usize, first: u32, last: u32): void {
    sequence.symbols[state].first = first;
    sequence.symbols[state].last = last;
}

export fn symbol_sequence_accepts(sequence: SymbolSequence*, state: usize, symbol: u32): bool {
    if state >= sequence.count {
        return false;
    }
    if symbol < sequence.symbols[state].first {
        return false;
    }
    var accepted = symbol <= sequence.symbols[state].last;
    return accepted;
}

export fn lex_table_create(): LexerTable* {
    var table = alloc(LexerTable, 1);
    if table != null {
        *table = default;
    }
    return table;
}

export fn lex_table_destroy(table: LexerTable*): void {
    if table == null {
        return;
    }
    vector_dispose(&table.alphabet);
    vector_dispose(&table.transitions);
    vector_dispose(&table.accepting);
    free(table);
}

export fn lex_table_set_alphabet(table: LexerTable*, values: u32*, count: usize): bool {
    if count < 2 {
        return false;
    }
    if table.accepting.length != 0 {
        return false;
    }
    var ok = vector_reserve(&table.alphabet, count);
    if ok {
        var bytes = count *sizeof(u32);
        copy(table.alphabet.data, values, bytes);
        table.alphabet.length = count;
    }
    return ok;
}

export fn lex_table_append(table: LexerTable*, transitions: i32*, count: usize, accepting: bool): bool {
    if table.alphabet.length < 2 {
        return false;
    }
    var columns = table.alphabet.length -1;
    if count != columns {
        return false;
    }
    var end = table.transitions.length + count;
    var wrapped = end < table.transitions.length;
    if wrapped {
        return false;
    }
    var rows = table.accepting.length + 1;
    wrapped = rows == 0;
    if wrapped {
        return false;
    }
    var ok = vector_reserve(&table.transitions, end);
    if !ok {
        return false;
    }
    ok = vector_reserve(&table.accepting, rows);
    if ok {
        var destination = table.transitions.data + table.transitions.length;
        var bytes = count *sizeof(i32);
        copy(destination, transitions, bytes);
        table.transitions.length = end;
        table.accepting.data[table.accepting.length] = convert(u8, accepting);
        table.accepting.length = rows;
    }
    return ok;
}

// The transition engine knows integer IDs, not UTF-8. Character decoding is one
// stream adapter; token grammar automata use these same rows directly.
export fn lex_table_step(table: LexerTable*, state: usize, symbol: u32): i32 {
    var invalid = state >= table.accepting.length;
    if invalid {
        return -1;
    }
    var columns = table.alphabet.length -1;
    invalid = symbol >= table.alphabet.data[columns];
    if invalid {
        return -1;
    }
    invalid = symbol < table.alphabet.data[0];
    if invalid {
        return -1;
    }
    var first: usize = 0;
    var count = table.alphabet.length;
    loop {
        if count == 0 {
            break;
        }
        var half = count / 2;
        var middle = first + half;
        if symbol < table.alphabet.data[middle] {
            count = half;
        }
        else {
            first = middle + 1;
            count = count - half;
            count--;
        }
    }
    var column = first -1;
    var index = state *columns;
    index = index + column;
    return table.transitions.data[index];
}

export fn lex_table_accepts(table: LexerTable*, state: usize): bool {
    if state >= table.accepting.length {
        return false;
    }
    var accepted = table.accepting.data[state] != 0;
    return accepted;
}

export fn lex_table_match(table: LexerTable*, source: u8*, length: usize, start: usize): usize {
    var position = start;
    var longest: usize = 0;
    var state: usize = 0;
    loop {
        var done = position >= length;
        if done {
            return longest;
        }
        var scalar: u32;
        var begin = source + position;
        var remaining = length -position;
        var bytes = tower_utf8_decode(begin, remaining, &scalar);
        if bytes == 0 {
            return longest;
        }
        var next = lex_table_step(table, state, scalar);
        done = next < 0;
        if done {
            return longest;
        }
        state = convert(usize, next);
        position = position + bytes;
        if table.accepting.data[state] != 0 {
            longest = position - start;
        }
    }
}

import tower;
import lr_types;
import lexer_table;
import .library.vector;

// Disposable FIRST/nullable and LR item indexes over the shared grammar entities.
// Character and token streams use the same integer ranges and closure algorithm.
struct LRNonterminal {
    nullable: bool;
    order: usize;
    first: vector(SymbolRange);
    productions: vector(usize);
}

struct LRAnalysis {
    rules: LRProduction*;
    rule_count: usize;
    symbols: LRSymbol*;
    symbol_count: usize;
    nonterminals: LRNonterminal*;
    nonterminal_count: usize;
    failed: bool;
}

struct LRItems {
    values: vector(LRItem);
    pending: vector(LRItem);
    failed: bool;
}

fn lr_none(): usize {
    var value: usize = 0;
    value--;
    return value;
}

fn lr_append(T: type, values: vector(T)*, value: T*): bool {
    var count = values.length + 1;
    if count == 0 {
        return false;
    }
    var ok = vector_reserve(values, count);
    if ok {
        copy(&values.data[values.length], value, sizeof(T));
        values.length = count;
    }
    return ok;
}

// Preserve distinct range identities here: overlapping ranges can represent
// different parse actions. Union/partition belongs to action construction.
fn lr_range_insert(values: vector(SymbolRange)*, first: u32, last: u32, changed: bool*): bool {
    var low: usize = 0;
    var high = values.length;
    loop {
        if low == high {
            break;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = middle + low;
        var value = &values.data[middle];
        var less = value.first < first;
        if value.first == first {
            less = value.last < last;
        }
        if less {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if low < values.length {
        var value = &values.data[low];
        var same = value.first == first;
        var end_same = value.last == last;
        same &&= end_same;
        if same {
            return true;
        }
    }
    var count = values.length + 1;
    if !vector_reserve(values, count) {
        return false;
    }
    var moved = values.length -low;
    var bytes = moved *sizeof(SymbolRange);
    var next = low + 1;
    copy(&values.data[next], &values.data[low], bytes);
    values.data[low].first = first;
    values.data[low].last = last;
    values.length = count;
    *changed = true;
    return true;
}

fn lr_range_merge(destination: vector(SymbolRange)*, source: vector(SymbolRange)*, changed: bool*): bool {
    if destination == source {
        return true;
    }
    var index: usize = 0;
    loop {
        if index == source.length {
            return true;
        }
        var range = &source.data[index];
        if !lr_range_insert(destination, range.first, range.last, changed) {
            return false;
        }
        index++;
    }
}

export fn lr_analysis_destroy(value: LRAnalysis*): void {
    if value == null {
        return;
    }
    var index: usize = 0;
    for(; index != value.nonterminal_count; index++) {
        var item = &value.nonterminals[index];
        vector_dispose(&item.first);
        vector_dispose(&item.productions);
    }
    free(value.nonterminals);
    free(value);
}

// Production/symbol arrays are borrowed and immutable for this analysis lifetime.
export fn lr_analysis_create(rules: LRProduction*, rule_count: usize, symbols: LRSymbol*, symbol_count: usize, nonterminal_count: usize): LRAnalysis* {
    var result = alloc(LRAnalysis, 1);
    var failed = result == null;
    if failed {
        return null;
    }
    *result = default;
    result.rules = rules;
    result.rule_count = rule_count;
    result.symbols = symbols;
    result.symbol_count = symbol_count;
    result.nonterminals = alloc(LRNonterminal, nonterminal_count);
    failed = result.nonterminals == null;
    if failed {
        free(result);
        return null;
    }
    result.nonterminal_count = nonterminal_count;
    var bytes = sizeof(LRNonterminal) *nonterminal_count;
    fill(result.nonterminals, 0, bytes);
    var index: usize = 0;
    for(; index != nonterminal_count; index++) {
        result.nonterminals[index].order = index;
    }
    index = 0;
    loop {
        if index == rule_count {
            return result;
        }
        var rule = &rules[index];
        var invalid = rule.owner >= nonterminal_count;
        if rule.begin > symbol_count {
            invalid = true;
        }
        if invalid {
            lr_analysis_destroy(result);
            return null;
        }
        var available = symbol_count -rule.begin;
        invalid = rule.count > available;
        if invalid {
            lr_analysis_destroy(result);
            return null;
        }
        if !vector_push(&result.nonterminals[rule.owner].productions, index) {
            lr_analysis_destroy(result);
            return null;
        }
        index++;
    }
}

export fn lr_analysis_compute(value: LRAnalysis*): bool {
    loop {
        var changed: bool = false;
        var index: usize = 0;
        loop {
            var done = index == value.rule_count;
            if done {
                break;
            }
            var rule = &value.rules[index];
            var owner = &value.nonterminals[rule.owner];
            var nullable: bool = true;
            var position: usize = 0;
            loop {
                done = position == rule.count;
                if done {
                    break;
                }
                var symbol_index = rule.begin + position;
                var symbol = &value.symbols[symbol_index];
                var terminal = symbol.nonterminal == lr_none();
                var ok: bool = true;
                if terminal {
                    ok = lr_range_insert(&owner.first, symbol.first, symbol.last, &changed);
                    nullable = false;
                } else {
                    if symbol.nonterminal >= value.nonterminal_count {
                        value.failed = true;
                        return false;
                    }
                    var referenced = &value.nonterminals[symbol.nonterminal];
                    ok = lr_range_merge(&owner.first, &referenced.first, &changed);
                    nullable = referenced.nullable;
                }
                if !ok {
                    value.failed = true;
                    return false;
                }
                if !nullable {
                    break;
                }
                position++;
            }
            if nullable {
                if !owner.nullable {
                    owner.nullable = true;
                    changed = true;
                }
            }
            index++;
        }
        if !changed {
            return true;
        }
    }
}

export fn lr_analysis_failed(value: LRAnalysis*): bool {
    return value.failed;
}

export fn lr_analysis_order(value: LRAnalysis*, index: usize, order: usize): void {
    value.nonterminals[index].order = order;
}

export fn lr_analysis_nullable(value: LRAnalysis*, index: usize): bool {
    return value.nonterminals[index].nullable;
}

export fn lr_analysis_first_count(value: LRAnalysis*, index: usize): usize {
    return value.nonterminals[index].first.length;
}

export fn lr_analysis_first_data(value: LRAnalysis*, index: usize): SymbolRange* {
