struct LRFirstResult {
    ranges: vector(SymbolRange);
    nullable: bool;
    changed: bool;
}

struct LRFirstTask {
    kernel: CompilerKernel;
    ticket: WorkTicket;
    analysis: LRAnalysis*;
    frontier: usize*;
    results: LRFirstResult*;
    begin: usize;
    count: usize;
    success: bool;
}

// Scheduling grain, not a grammar limit. Narrow waves retain the serial solver.
var LRFirstGrain: usize = 64;

// Each nonterminal owns its output. References always read the preceding
// joined snapshot, including self references and nullable cycles.
export fn compiler_lr_first_kernel(payload: void*): void {
    var task = bits(LRFirstTask*, payload);
    var value = task.analysis;
    task.success = true;
    for(var i = task.begin; i < task.begin + task.count; i++) {
        var index = task.frontier[i];
        var source = &value.nonterminals[index];
        var result = &task.results[index];
        result.ranges.length = 0;
        result.nullable = source.nullable;
        result.changed = false;
        if !vector_reserve(&result.ranges, source.first.length) { task.success = false; return; }
        if source.first.length != 0 { copy(result.ranges.data, source.first.data, source.first.length * sizeof(SymbolRange)); }
        result.ranges.length = source.first.length;
        foreach(var production in &source.productions) {
            var rule = &value.rules[production];
            var nullable = true;
            for(var position: usize = 0; position < rule.count && nullable; position++) {
                var symbol = &value.symbols[rule.begin + position];
                if symbol.nonterminal == lr_none() {
                    if !lr_range_insert(&result.ranges, symbol.first, symbol.last, &result.changed) { task.success = false; return; }
                    nullable = false;
                } else {
                    if symbol.nonterminal >= value.nonterminal_count { task.success = false; return; }
                    var referenced = &value.nonterminals[symbol.nonterminal];
                    if !lr_range_merge(&result.ranges, &referenced.first, &result.changed) { task.success = false; return; }
                    nullable = referenced.nullable;
                }
            }
            if nullable && !result.nullable { result.nullable = true; result.changed = true; }
        }
    }
}

fn lr_analysis_work(value: LRAnalysis*, anchor: void*, capacity: usize): bool {
    var owner = entity_create_related(anchor);
    if owner == null { return false; }
    defer entity_release(owner);
    var results = alloc(LRFirstResult, value.nonterminal_count);
    var dependents = alloc(vector(usize), value.nonterminal_count);
    var queued = alloc(bool, value.nonterminal_count);
    if results == null || dependents == null || queued == null {
        free(results); free(dependents); free(queued); return false;
    }
    fill(results, 0, value.nonterminal_count * sizeof(LRFirstResult));
    fill(dependents, 0, value.nonterminal_count * sizeof(vector(usize)));
    defer {
        for(var i: usize = 0; i < value.nonterminal_count; i++) {
            vector_dispose(&results[i].ranges);
            vector_dispose(&dependents[i]);
        }
        free(results); free(dependents); free(queued);
    }
    // Any reference can become relevant when an earlier prefix becomes nullable.
    // Invalid references are diagnosed only if reached, just as in the serial
    // algorithm; an unreachable tail must not change analysis behavior.
    for(var i: usize = 0; i < value.rule_count; i++) {
        var rule = &value.rules[i];
        for(var j: usize = 0; j < rule.count; j++) {
            var referenced = value.symbols[rule.begin + j].nonterminal;
            if referenced < value.nonterminal_count && !vector_push(&dependents[referenced], rule.owner) { return false; }
        }
    }
    var frontier: vector(usize);
    var next: vector(usize);
    vector_init(&frontier);
    vector_init(&next);
    defer { vector_dispose(&frontier); vector_dispose(&next); }
    for(var i: usize = 0; i < value.nonterminal_count; i++) {
        if !vector_push(&frontier, i) { return false; }
    }
    var kind = lr_work_node(owner);
    if kind == null || !entity_register(kind, sizeof(LRFirstTask), alignof(LRFirstTask), 0) { return false; }
    var nodes: void*[256];
    var jobs: LRFirstTask*[256];
    for(var i: usize = 0; i < capacity; i++) {
        nodes[i] = lr_work_node(owner);
        if nodes[i] == null { return false; }
        var job = bits(LRFirstTask*, entity_component_data(entity_component_add(nodes[i], kind)));
        if job == null { return false; }
        fill(job, 0, sizeof(LRFirstTask));
        job.kernel.kind = CompilerKernelKind.LRFirst;
        job.kernel.payload = bits(void*, job);
        job.analysis = value;
        job.results = results;
        jobs[i] = job;
    }
    var graph: WorkGraph;
    work_init(&graph, 1, 0);
    defer work_dispose(&graph);
    var workers: ParserWorkers;
    if !parser_workers_open(&workers, anchor, capacity) { return false; }
    defer parser_workers_close(&workers);
    var pool = workers.pool;
    while frontier.length != 0 {
        var count = frontier.length / LRFirstGrain;
        // A retained world pool may be wider than this analysis's job array.
        if count > capacity { count = capacity; }
        if count > pool.count { count = pool.count; }
        if count < 2 { return lr_analysis_compute(value); }
        if !work_reset(&graph, graph.revision + 1, graph.profile) { return false; }
        var position: usize = 0;
        for(var i: usize = 0; i < count; i++) {
            var job = jobs[i];
            job.frontier = frontier.data;
            job.begin = position;
            job.count = frontier.length / count + (i < frontier.length % count ? 1 : 0);
            position += job.count;
            var id = work_request(&graph, nodes[i], 1, convert(u64, job.begin));
            var ok = id != 0;
            ok &&= work_access(&graph, id, 1, 1, job.begin, job.count, WorkAccessMode.Write);
            ok &&= work_access(&graph, id, 1, 2, 0, 1, WorkAccessMode.Read);
            ok &&= work_seal(&graph, id);
            ok &&= work_demand(&graph, id);
            ok &&= work_take(&graph, &job.ticket);
            if !ok { return false; }
        }
        var view = entity_view_open(owner);
        if view == null { return false; }
        var ok = true;
        var admitted: usize = 0;
        for(; admitted < count; admitted++) {
            if !work_pool_submit(pool, bits(void*, &jobs[admitted].kernel)) { ok = false; break; }
        }
        for(var i: usize = 0; i < admitted; i++) {
            if work_pool_receive(pool, true) == null { ok = false; }
        }
        entity_view_close(view);
        for(var i: usize = 0; i < admitted; i++) {
            if !work_finish(&graph, &jobs[i].ticket, jobs[i].success) || !jobs[i].success { ok = false; }
        }
        if !ok { return false; }
        next.length = 0;
        fill(queued, 0, value.nonterminal_count * sizeof(bool));
        foreach(var index in &frontier) {
            var result = &results[index];
            if !result.changed { continue; }
            var target = &value.nonterminals[index];
            var previous: vector(SymbolRange);
            copy(&previous, &target.first, sizeof(vector(SymbolRange)));
            copy(&target.first, &result.ranges, sizeof(vector(SymbolRange)));
            copy(&result.ranges, &previous, sizeof(vector(SymbolRange)));
            target.nullable = result.nullable;
            foreach(var dependent in &dependents[index]) {
                if !queued[dependent] {
                    if !vector_push(&next, dependent) { return false; }
                    queued[dependent] = true;
                }
            }
        }
        var previous: vector(usize);
        copy(&previous, &frontier, sizeof(vector(usize)));
        copy(&frontier, &next, sizeof(vector(usize)));
        copy(&next, &previous, sizeof(vector(usize)));
    }
    return true;
}

export fn lr_analysis_compute_parallel(value: LRAnalysis*, anchor: void*): bool {
    var capacity = compiler_worker_capacity(anchor);
    if capacity < 2 || anchor == null || value.nonterminal_count < 2 * LRFirstGrain { return lr_analysis_compute(value); }
    var useful = value.nonterminal_count / LRFirstGrain;
    if capacity > useful { capacity = useful; }
    var ok = lr_analysis_work(value, anchor, capacity);
    if !ok { value.failed = true; }
    return ok;
}

import tower;
import lr_analysis;
import parser_nodes;
import parser_types;
import regex_lowering;
import .library.vector;
import lr_types;

// Derived indexes over ordinary grammar entities. Names/captures are snapshots
// for this table revision; source entities and declaration order remain intact.
struct LRGrammarName {
    text: vector(u8);
    hash: usize;
    next: usize;
    order: usize;
}

struct LRGrammarRule {
    node: void*;
    generated: bool;
}

struct LRGrammarSymbol {
    node: void*;
    capture: vector(u8);
}

struct LRUnresolved {
    name: u8*;
    symbol: usize;
}

struct LRGrammar {
    names: vector(LRGrammarName*);
    buckets: vector(usize);
    rules: vector(LRProduction);
    rule_metadata: vector(LRGrammarRule);
    symbols: vector(LRSymbol);
    symbol_metadata: vector(LRGrammarSymbol);
    unresolved: vector(LRUnresolved);
}

fn lr_name_hash(text: u8*): usize {
    var hash: usize = 2166136261;
    var index: usize = 0;
    loop {
        if text[index] == 0 {
            return hash;
        }
        var byte = convert(usize, text[index]);
        hash = hash ^ byte;
        hash = hash * 16777619;
        index++;
    }
}

fn lr_name_equal(left: u8*, right: u8*): bool {
    var index: usize = 0;
    loop {
        if left[index] != right[index] {
            return false;
        }
        if left[index] == 0 {
            return true;
        }
        index++;
    }
}

fn lr_grammar_lookup(value: LRGrammar*, name: u8*, hash: usize): usize {
    var size = value.buckets.length;
    if size == 0 {
        return lr_none();
    }
    var bucket = hash % size;
    var index = value.buckets.data[bucket];
    loop {
        if index == lr_none() {
            return index;
        }
        var entry = value.names.data[index];
        var same = entry.hash == hash;
        if same {
            same = lr_name_equal(name, node_text_get(&entry.text));
            if same {
                return index;
            }
        }
        index = entry.next;
    }
}

fn lr_grammar_name_add(value: LRGrammar*, name: u8*, index: usize*): bool {
    var hash = lr_name_hash(name);
    *index = lr_grammar_lookup(value, name, hash);
    if *index != lr_none() {
        return true;
    }
    var entry = alloc(LRGrammarName, 1);
    if entry == null {
        return false;
    }
    *entry = default;
    var ok = node_text_set(&entry.text, name);
    ok &&= vector_push(&value.names, entry);
    if !ok {
        vector_dispose(&entry.text);
        free(entry);
        return false;
    }
    *index = value.names.length - 1;
    entry.hash = hash;
    // The augmented start name is diagnostic text, not a source-name binding.
    if *index == 0 {
        return true;
    }
    var size = value.buckets.length;
    if size == 0 {
        return false;
    }
    var bucket = hash % size;
    entry.next = value.buckets.data[bucket];
    value.buckets.data[bucket] = *index;
    return true;
}

fn lr_grammar_name_less(value: LRGrammar*, a: usize, b: usize): bool {
    var left = node_text_get(&value.names.data[a].text);
    var right = node_text_get(&value.names.data[b].text);
    var index: usize = 0;
    loop {
        if left[index] != right[index] {
            var less = left[index] < right[index];
            return less;
        }
        if left[index] == 0 {
            var less = a < b;
            return less;
        }
        index++;
    }
}

fn lr_grammar_name_sift(value: LRGrammar*, order: usize*, count: usize, start: usize): void {
    var root = start;
    loop {
        var child = root *2;
        child++;
        if child >= count {
            return;
        }
        var next = child + 1;
        if next < count {
            var less = lr_grammar_name_less(value, order[child], order[next]);
            if less {
                child = next;
            }
        }
        var less = lr_grammar_name_less(value, order[root], order[child]);
        if !less {
            return;
        }
        var swap = order[root];
        order[root] = order[child];
        order[child] = swap;
        root = child;
    }
}

fn lr_grammar_order(value: LRGrammar*): bool {
    var count = value.names.length;
    var order = alloc(usize, count);
    if order == null {
        return false;
    }
    var index: usize = 0;
    for(; index != count; index++) {
        order[index] = index;
    }
    var start = count / 2;
    loop {
        var end = start == 0;
        if end {
            break;
        }
        start--;
        lr_grammar_name_sift(value, order, count, start);
    }
    var remaining = count;
    loop {
        var end = remaining <= 1;
        if end {
            break;
        }
        remaining--;
        var swap = order[0];
        order[0] = order[remaining];
        order[remaining] = swap;
        lr_grammar_name_sift(value, order, remaining, 0);
    }
    index = 0;
    for(; index != count; index++) {
        var original = order[index];
        value.names.data[original].order = index;
    }
    free(order);
    return true;
}

export fn lr_grammar_destroy(value: LRGrammar*): void {
    if value == null {
        return;
    }
    var index: usize = 0;
    for(; index != value.names.length; index++) {
        var name = value.names.data[index];
        vector_dispose(&name.text);
        free(name);
    }
    index = 0;
    for(; index != value.symbol_metadata.length; index++) {
        vector_dispose(&value.symbol_metadata.data[index].capture);
    }
    vector_dispose(&value.names);
    vector_dispose(&value.buckets);
    vector_dispose(&value.rules);
    vector_dispose(&value.rule_metadata);
    vector_dispose(&value.symbols);
    vector_dispose(&value.symbol_metadata);
    vector_dispose(&value.unresolved);
    free(value);
}

fn lr_grammar_payload(node: void*, kind: void*): void* {
    var component = entity_component_get(node, kind);
    return entity_component_data(component);
}

fn lr_grammar_add_symbol(value: LRGrammar*, symbol: LRSymbol*, node: void*, capture: u8*): bool {
    var metadata: LRGrammarSymbol = default;
    metadata.node = node;
    var ok = true;
    if *capture != 0 {
        ok = node_text_set(&metadata.capture, capture);
    }
    ok &&= lr_append(LRGrammarSymbol, &value.symbol_metadata, &metadata);
    if !ok {
        vector_dispose(&metadata.capture);
        return false;
    }
    return lr_append(LRSymbol, &value.symbols, symbol);
}

fn lr_grammar_rules(value: LRGrammar*, root: void*, kind: void*): bool {
    var count = entity_child_count(root);
    var size = count *2;
    size++;
    var ok = vector_reserve(&value.buckets, size);
    if !ok {
        return false;
    }
    value.buckets.length = size;
    var bytes = size *sizeof(usize);
    fill(value.buckets.data, 255, bytes);
    var index: usize;
    ok = lr_grammar_name_add(value, "S'", &index);
    if !ok {
        return false;
    }
    var rule: LRProduction = default;
    var metadata: LRGrammarRule = default;
    ok = lr_append(LRProduction, &value.rules, &rule);
    ok &&= lr_append(LRGrammarRule, &value.rule_metadata, &metadata);
    if !ok {
        return false;
    }
    index = 0;
    loop {
        if index == count {
            return lr_grammar_order(value);
        }
        metadata.node = entity_child_at(root, index);
        var data = lr_grammar_payload(metadata.node, kind);
        var source = bits(ParserRuleData*, data);
        if source == null {
            return false;
        }
        metadata.generated = source.generated;
        rule.precedence = source.precedence;
        rule.associativity = source.associativity;
        ok = lr_grammar_name_add(value, node_rule_name(source), &rule.owner);
        ok &&= lr_append(LRProduction, &value.rules, &rule);
        ok &&= lr_append(LRGrammarRule, &value.rule_metadata, &metadata);
        if !ok {
            return false;
        }
        index++;
    }
}

fn lr_grammar_symbols(value: LRGrammar*, reference_kind: void*, string_kind: void*, range_kind: void*): bool {
    var symbol: LRSymbol = { first: LRTokenEnd, last: LRTokenEnd, nonterminal: 1 };
    var present = value.names.length > 1;
    if present {
        var ok = lr_grammar_add_symbol(value, &symbol, null, "");
        if !ok {
            return false;
        }
        value.rules.data[0].count = 1;
    }
    var rule_index: usize = 1;
    loop {
        var done = rule_index == value.rules.length;
        if done {
            return true;
        }
        var rule = &value.rules.data[rule_index];
        var source = value.rule_metadata.data[rule_index].node;
        rule.begin = value.symbols.length;
        var count = entity_child_count(source);
        var index: usize = 0;
        loop {
            done = index == count;
            if done {
                break;
            }
            var node = entity_child_at(source, index);
            var data = lr_grammar_payload(node, reference_kind);
            var reference = bits(ParserReferenceData*, data);
            present = reference != null;
            if present {
                var name = node_reference_name(reference);
                var hash = lr_name_hash(name);
                symbol.nonterminal = lr_grammar_lookup(value, name, hash);
                symbol.first = LRTokenEnd;
                symbol.last = LRTokenEnd;
                var unresolved = symbol.nonterminal == lr_none();
                if unresolved {
                    var pending: LRUnresolved;
                    pending.name = name;
                    pending.symbol = value.symbols.length;
                    var ok = lr_append(LRUnresolved, &value.unresolved, &pending);
                    if !ok {
                        return false;
                    }
                }
                var capture = node_reference_capture(reference);
                var ok = lr_grammar_add_symbol(value, &symbol, node, capture);
                if !ok {
                    return false;
                }
            }
            data = lr_grammar_payload(node, string_kind);
            var string = bits(ParserStringData*, data);
            present = string != null;
            if present {
                var position: usize = 0;
                loop {
                    done = position == string.ids.length;
                    if done {
                        break;
                    }
                    symbol.nonterminal = lr_none();
                    symbol.first = string.ids.data[position];
                    symbol.last = symbol.first;
                    var ok = lr_grammar_add_symbol(value, &symbol, node, "");
                    if !ok {
                        return false;
                    }
                    position++;
                }
            }
            data = lr_grammar_payload(node, range_kind);
            var range = bits(ParserRangeData*, data);
            present = range != null;
            if present {
                symbol.nonterminal = lr_none();
                symbol.first = range.start;
                symbol.last = range.end;
                if symbol.first > symbol.last {
                    symbol.first = range.end;
                    symbol.last = range.start;
                }
                var ok = lr_grammar_add_symbol(value, &symbol, node, "");
                if !ok {
                    return false;
                }
            }
            index++;
        }
        rule.count = value.symbols.length - rule.begin;
        rule_index++;
    }
}

export fn lr_grammar_create(root: void*, rule_kind: void*, reference_kind: void*, string_kind: void*, range_kind: void*): LRGrammar* {
    var value = alloc(LRGrammar, 1);
    if value == null {
        return null;
    }
    *value = default;
    var ok = lr_grammar_rules(value, root, rule_kind);
    ok &&= lr_grammar_symbols(value, reference_kind, string_kind, range_kind);
    if ok {
        // Name lookup is finished. Runtime tables only need the ordered names.
        vector_dispose(&value.buckets);
        return value;
    }
    lr_grammar_destroy(value);
    return null;
}

export fn lr_grammar_rule_count(value: LRGrammar*): usize {
    return value.rules.length;
}

export fn lr_grammar_rule_data(value: LRGrammar*): LRProduction* {
    return value.rules.data;
}

export fn lr_grammar_rule_node(value: LRGrammar*, index: usize): void* {
    return value.rule_metadata.data[index].node;
}

export fn lr_grammar_generated(value: LRGrammar*, index: usize): bool {
    return value.rule_metadata.data[index].generated;
}

export fn lr_grammar_symbol_count(value: LRGrammar*): usize {
    return value.symbols.length;
}

export fn lr_grammar_symbol_data(value: LRGrammar*): LRSymbol* {
    return value.symbols.data;
}

export fn lr_grammar_symbol_node(value: LRGrammar*, index: usize): void* {
    return value.symbol_metadata.data[index].node;
}

export fn lr_grammar_capture(value: LRGrammar*, index: usize): u8* {
    return node_text_get(&value.symbol_metadata.data[index].capture);
}

export fn lr_grammar_name_count(value: LRGrammar*): usize {
    return value.names.length;
}

export fn lr_grammar_name(value: LRGrammar*, index: usize): u8* {
    return node_text_get(&value.names.data[index].text);
}

export fn lr_grammar_name_order(value: LRGrammar*, index: usize): usize {
    return value.names.data[index].order;
}

export fn lr_grammar_missing_count(value: LRGrammar*): usize {
    return value.unresolved.length;
}

export fn lr_grammar_missing_name(value: LRGrammar*, index: usize): u8* {
    return value.unresolved.data[index].name;
}

export fn lr_grammar_resolve(value: LRGrammar*, index: usize, id: u32): bool {
    var invalid = index >= value.unresolved.length;
    if invalid {
        return false;
    }
    invalid = id == LRTokenEnd;
    if invalid {
        return false;
    }
    var position = value.unresolved.data[index].symbol;
    value.symbols.data[position].first = id;
    value.symbols.data[position].last = id;
    return true;
}

// First unresolved name, or lr_none(). Share this check across table owners.
export fn lr_grammar_pending(value: LRGrammar*): usize {
    for(var index: usize = 0; index < value.unresolved.length; index++) {
        var symbol = value.unresolved.data[index].symbol;
        if value.symbols.data[symbol].first == LRTokenEnd {
            return index;
        }
    }
    return lr_none();
}

// Source-node addresses are construction-only. Keep numeric records when the
// table's diagnostics/trace views still consume them; never rebuild native copies.
export fn lr_grammar_detach(value: LRGrammar*): void {
    vector_dispose(&value.unresolved);
    var index: usize = 0;
    for(; index != value.rule_metadata.length; index++) {
        value.rule_metadata.data[index].node = null;
    }
    index = 0;
    for(; index != value.symbol_metadata.length; index++) {
        value.symbol_metadata.data[index].node = null;
    }
}

// Compact readers only need generated flags, labels and captures after build.
export fn lr_grammar_finish(value: LRGrammar*): void {
    lr_grammar_detach(value);
    vector_dispose(&value.rules);
    vector_dispose(&value.symbols);
}

import tower;
import lr_analysis;
import lr_states;
import .library.vector;
import lr_types;

// Build LALR lookahead dependencies from LR(1) closures of LR(0) kernels.
// Grammar order determines indices, never conflict priority or a shift bias.
fn lr_lalr_index(value: LRStates*, state_index: usize, item: LRItem*): usize {
    var state = value.states.data[state_index];
    var key: LRItem = { rule: item.rule, position: item.position, first: 0, last: 0 };
    var low: usize = 0;
    var high = state.items.values.length;
    loop {
        if low == high {
            break;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = middle + low;
        if lr_item_less(&state.items.values.data[middle], &key) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    var missing = low == state.items.values.length;
    if missing {
        return lr_none();
    }
    missing = lr_item_less(&key, &state.items.values.data[low]);
    if missing {
        return lr_none();
    }
    var result = state.base + low;
    return result;
}

// Transient publication records for the existing derived lookahead graph.
// A worker owns its ordered vector; serial construction writes the same link
// directly. Neither representation adds grammar or Foundation semantics.
struct LRPropagationLink {
    source: usize;
    destination: usize;
    first: u32;
    last: u32;
}

struct LRLinkOutput {
    graph: LRPropagation*;
    links: vector(LRPropagationLink)*;
}

fn lr_lalr_apply(graph: LRPropagation*, link: LRPropagationLink*): bool {
    if link.first == LRTokenPropagation {
        return lr_propagation_edge(graph, link.source, link.destination);
    }
    return lr_propagation_seed(graph, link.destination, link.first, link.last);
}

fn lr_lalr_link(value: LRStates*, output: LRLinkOutput*, source: usize, state: usize, item: LRItem*): bool {
    var destination = lr_lalr_index(value, state, item);
    if destination == lr_none() {
        return false;
    }
    var link: LRPropagationLink = { source: source, destination: destination, first: item.first, last: item.last };
    if output.links != null {
        return lr_append(output.links, &link);
    }
    return lr_lalr_apply(output.graph, &link);
}

fn lr_lalr_destination(value: LRStates*, state: LRState*, symbol: usize): usize {
    var low: usize = 0;
    var high = state.edges.length;
    loop {
        if low == high {
            break;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = middle + low;
        if lr_symbol_less(value.analysis, state.edges.data[middle].symbol, symbol) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    var missing = low == state.edges.length;
    if missing {
        return lr_none();
    }
    missing = lr_symbol_less(value.analysis, symbol, state.edges.data[low].symbol);
    if missing {
        return lr_none();
    }
    return state.edges.data[low].state;
}

// Closure and goto sets depend on a dotted production, not its LR state.
// Memoize them only while building this table; shared grammar nodes remain the
// authority. This avoids repeating wide operator closures in every state.
struct LRKernelClosure {
    state: LRState;
    next: vector(LRItems*);
}

fn lr_kernel_closure_destroy(value: LRKernelClosure*): void {
    if value == null {
        return;
    }
    foreach(var & next_item in &value.next) {
        lr_items_destroy(*next_item);
    }
    vector_dispose(&value.next);
    vector_dispose(&value.state.symbols);
    lr_items_destroy(value.state.items);
    free(value);
}

// Scatter the sorted closure into its outgoing kernels once. Rescanning the
// entire closure for every symbol makes wide expression grammars quadratic.
// Range containment matches lr_items_shift, including overlapping terminals.
// Advancing a dotted position preserves item order and cannot create duplicates.
fn lr_kernel_shift(analysis: LRAnalysis*, cached: LRKernelClosure*): bool {
    var closure = &cached.state;
    foreach (var &item in &closure.items.values) {
        var rule = &analysis.rules[item.rule];
        if item.position >= rule.count { continue; }
        var symbol_index = rule.begin + item.position;
        var symbol = &analysis.symbols[symbol_index];
        var terminal = symbol.nonterminal == lr_none();
        var low: usize = 0;
        var high = closure.symbols.length;
        while low < high {
            var middle = low + (high - low) / 2;
            var candidate = &analysis.symbols[closure.symbols.data[middle]];
            var before = terminal ? candidate.nonterminal != lr_none() || candidate.first < symbol.first
                : lr_symbol_less(analysis, closure.symbols.data[middle], symbol_index);
            if before { low = middle + 1; } else { high = middle; }
        }
        var advanced = *item;
        ++advanced.position;
        for (var i = low; i < closure.symbols.length; ++i) {
            var candidate = &analysis.symbols[closure.symbols.data[i]];
            if terminal {
                if candidate.nonterminal != lr_none() || candidate.first > symbol.last { break; }
                if candidate.last > symbol.last { continue; }
            } else {
                if candidate.nonterminal != symbol.nonterminal { break; }
            }
            // These immutable kernels are consumed by propagation, never closed
            // again. They need neither sorted insertion nor a pending work copy.
            if !vector_push(&cached.next.data[i].values, advanced) { return false; }
        }
    }
    return true;
}

fn lr_kernel_closure(analysis: LRAnalysis*, kernel: LRItem*): LRKernelClosure* {
    var cached = alloc(LRKernelClosure, 1);
    var missing = cached == null;
    if missing {
        return null;
    }
    *cached = default;
    var closure = &cached.state;
    closure.items = lr_items_create();
    missing = closure.items == null;
    if missing {
        lr_kernel_closure_destroy(cached);
        return null;
    }
    var seed = *kernel;
    seed.first = LRTokenPropagation;
    seed.last = LRTokenPropagation;
    var ok = lr_items_insert(closure.items, &seed);
    ok &&= lr_items_close(analysis, closure.items, true);
    var index: usize = 0;
    loop {
        if !ok {
            break;
        }
        var done = index == closure.items.values.length;
        if done {
            break;
        }
        var item = &closure.items.values.data[index];
        var rule = &analysis.rules[item.rule];
        if item.position < rule.count {
            var symbol = rule.begin + item.position;
            ok = lr_state_symbol(analysis, closure, symbol);
        }
        index++;
    }
    index = 0;
    loop {
        if !ok {
            break;
        }
        var done = index == closure.symbols.length;
        if done {
            break;
        }
        var next = lr_items_create();
        missing = next == null;
        if missing {
            ok = false;
            break;
        }
        ok = vector_push(&cached.next, next);
        if !ok {
            lr_items_destroy(next);
            break;
        }
        index++;
    }
    ok &&= lr_kernel_shift(analysis, cached);
    if ok {
        return cached;
    }
    lr_kernel_closure_destroy(cached);
    return null;
}

// All closures and state bases are immutable before a worker enters here.
// Cache construction is deliberately outside this helper.
fn lr_lalr_kernel_cached(value: LRStates*, output: LRLinkOutput*, state_index: usize,
source: usize, cached: LRKernelClosure*): bool {
    var closure = &cached.state;
    var state = value.states.data[state_index];
    var index: usize = 0;
    for(; index != closure.items.values.length; index++) {
        var item = &closure.items.values.data[index];
        if value.analysis.rules[item.rule].count == 0 {
            var ok = lr_lalr_link(value, output, source, state_index, item);
            if !ok {
                return false;
            }
        }
    }
    index = 0;
    loop {
        var done = index == closure.symbols.length;
        if done {
            return true;
        }
        var symbol = closure.symbols.data[index];
        var destination = lr_lalr_destination(value, state, symbol);
        var missing = destination == lr_none();
        if missing {
            return false;
        }
        var next = cached.next.data[index];
        var position: usize = 0;
        loop {
            done = position == next.values.length;
            if done {
                break;
            }
            var item = &next.values.data[position];
            if lr_kernel(value.analysis, item) {
                var ok = lr_lalr_link(value, output, source, destination, item);
                if !ok {
                    return false;
                }
            }
            position++;
        }
        index++;
    }
}

fn lr_lalr_kernel(value: LRStates*, graph: LRPropagation*, state_index: usize, source: usize,
kernel: LRItem*, cache: LRKernelClosure**): bool {
    var key = value.analysis.rules[kernel.rule].begin + kernel.rule + kernel.position;
    if cache[key] == null {
        cache[key] = lr_kernel_closure(value.analysis, kernel);
    }
    if cache[key] == null {
        return false;
    }
    var output: LRLinkOutput = default;
    output.graph = graph;
    return lr_lalr_kernel_cached(value, &output, state_index, source, cache[key]);
}

fn lr_lalr_state_links(value: LRStates*, cache: LRKernelClosure**, state_index: usize,
links: vector(LRPropagationLink)*): bool {
    var state = value.states.data[state_index];
    var output: LRLinkOutput = default;
    output.links = links;
    for(var i: usize = 0; i < state.items.values.length; i++) {
        var item = &state.items.values.data[i];
        if !lr_kernel(value.analysis, item) {
            continue;
        }
        var key = value.analysis.rules[item.rule].begin + item.rule + item.position;
        // Missing immutable input is a failed job, never lazy cache mutation.
        if cache[key] == null || !lr_lalr_kernel_cached(value, &output, state_index,
        state.base + i, cache[key]) {
            return false;
        }
    }
    return true;
}

// The same ordered algorithm serves serial construction and private worker output.
fn lr_lalr_state_actions(value: LRStates*, graph: LRPropagation*, state_index: usize,
actions: vector(LRAction)*): bool {
    var state = value.states.data[state_index];
    actions.length = 0;
    foreach(var & edge in &state.edges) {
        var symbol = &value.analysis.symbols[edge.symbol];
        if symbol.nonterminal == lr_none() {
            var action: LRAction = { first: symbol.first, last: symbol.last, rule: lr_none(), state: edge.state };
            if !lr_append(actions, &action) {
                return false;
            }
        }
    }
    for(var index: usize = 0; index < state.items.values.length; index++) {
        var item = &state.items.values.data[index];
        if item.position == value.analysis.rules[item.rule].count {
            var ranges = &graph.nodes[state.base + index].ranges;
            foreach(var & range in ranges) {
                var action: LRAction = { first: range.first, last: range.last, rule: item.rule, state: lr_none() };
                if !lr_append(actions, &action) {
                    return false;
                }
            }
        }
    }
    return true;
}

fn lr_lalr_actions(value: LRStates*, graph: LRPropagation*): bool {
    for(var i: usize = 0; i < value.states.length; i++) {
        if !lr_lalr_state_actions(value, graph, i, &value.states.data[i].actions) {
            return false;
        }
    }
    return true;
}

fn lr_lalr_seed(value: LRStates*, graph: LRPropagation*, constructs: bool): bool {
    var seed: LRItem = default;
    var start = lr_lalr_index(value, 0, &seed);
    if start == lr_none() {
        return false;
    }
    var ok = lr_propagation_seed(graph, start, LRTokenEnd, LRTokenEnd);
    if !ok {
        return false;
    }
    if constructs {
        var owner = value.analysis.rules[0].owner;
        var first = &value.analysis.nonterminals[owner].first;
        foreach(var & range in first) {
            ok = lr_propagation_seed(graph, start, range.first, range.last);
            if !ok {
                return false;
            }
        }
    }
    return true;
}

fn lr_states_propagation_begin(value: LRStates*, constructs: bool): LRPropagation* {
    var count: usize = 0;
    foreach(var state in &value.states) {
        state.base = count;
        count += state.items.values.length;
    }
    var graph = lr_propagation_create(count);
    if graph == null {
        return null;
    }
    if !lr_lalr_seed(value, graph, constructs) {
        lr_propagation_destroy(graph);
        return null;
    }
    return graph;
}

fn lr_states_propagation_cached(value: LRStates*, constructs: bool, cache: LRKernelClosure**): LRPropagation* {
    var graph = lr_states_propagation_begin(value, constructs);
    if graph == null {
        return null;
    }
    var ok = true;
    var index: usize = 0;
    var state_index: usize = 0;
    loop {
        if !ok {
            break;
        }
        var done = state_index == value.states.length;
        if done {
            break;
        }
        var state = value.states.data[state_index];
        index = 0;
        loop {
            if !ok {
                break;
            }
            done = index == state.items.values.length;
            if done {
                break;
            }
            var item = &state.items.values.data[index];
            if lr_kernel(value.analysis, item) {
                var source = state.base + index;
                ok = lr_lalr_kernel(value, graph, state_index, source, item, cache);
            }
            index++;
        }
        state_index++;
    }
    if !ok {
        lr_propagation_destroy(graph);
        return null;
    }
    return graph;
}

export fn lr_states_lalr_cached(value: LRStates*, constructs: bool, cache: LRKernelClosure**): bool {
    var graph = lr_states_propagation_cached(value, constructs, cache);
    if graph == null {
        return false;
    }
    defer lr_propagation_destroy(graph);
    return lr_propagation_solve(graph) && lr_lalr_actions(value, graph);
}

export fn lr_states_lalr(value: LRStates*, constructs: bool): bool {
    var count = value.analysis.symbol_count + value.analysis.rule_count;
    var cache = alloc(LRKernelClosure*, count);
    if cache == null {
        return false;
    }
    fill(cache, 0, count *sizeof(LRKernelClosure*));
    var ok = lr_states_lalr_cached(value, constructs, cache);
    for(var i: usize = 0; i < count; ++i) {
        lr_kernel_closure_destroy(cache[i]);
    }
    free(cache);
    return ok;
}

export fn lr_states_action_count(value: LRStates*, index: usize): usize {
    return value.states.data[index].actions.length;
}

export fn lr_states_actions(value: LRStates*, index: usize): LRAction* {
    return value.states.data[index].actions.data;
}

import tower;
import lexer_table;
import lr_analysis;
import lr_runtime;
import lr_states;
import .library.vector;
import lr_types;

// LR and proven finite-sequence control over integer symbols. Frames borrow
// forest handles; the shared entity forest retains ownership of syntax nodes.
// A pull protocol keeps stream callbacks outside the deterministic control loop.
struct LRParser {
    runtime: LRRuntime*;
    stack: vector(LRFrame);
    work: LRWork;
    prefix: bool;
    shifted: bool;
    finishing: bool;
    consumed: usize;
    sequence: bool;
    evidence: vector(u8);
    sequence_first: usize;
    sequence_last: usize;
    sequence_start: usize;
    sequence_end: usize;
}

export fn lr_parser_destroy(value: LRParser*): void {
    if value == null {
        return;
    }
    vector_dispose(&value.stack);
    vector_dispose(&value.evidence);
    free(value);
}

export fn lr_parser_create(runtime: LRRuntime*, prefix: bool, specialize: bool): LRParser* {
    var value = alloc(LRParser, 1);
    if value == null {
        return null;
    }
    *value = default;
    value.runtime = runtime;
    value.prefix = prefix;
    if specialize {
        value.sequence = runtime.sequence != null;
    }
    value.sequence_first = lr_none();
    value.sequence_last = lr_none();
    var frame: LRFrame = default;
    frame.first = lr_none();
    frame.last = lr_none();
    if lr_append(LRFrame, &value.stack, &frame) {
        return value;
    }
    lr_parser_destroy(value);
    return null;
}

// Statuses are the private host pull protocol, not Foundation instructions:
// input, shift, reduce, accept, unexpected, empty-prefix, DFA shift/reduce, invalid.
fn lr_parser_sequence_step(value: LRParser*, ready: bool, id: u32, error: bool, result: LRStep*): u32 {
    var runtime = value.runtime;
    var position = value.evidence.length;
    var rule = &runtime.rules.data[runtime.sequence_rule];
    var complete = position == rule.count;
    var needs_input = true;
    if complete {
        if value.prefix {
            needs_input = false;
        }
    }
    if needs_input {
        if !ready {
            return 0;
        }
    }
    value.work.actions++;
    result.rule = runtime.sequence_rule;
    if complete {
        if needs_input {
            if id != LRTokenEnd {
                return 4;
            }
            if error {
                return 4;
            }
        }
        result.next = lr_runtime_goto(runtime, 0, rule.owner);
        result.start = value.sequence_start;
        result.end = value.sequence_end;
        return 7;
    }
    if error {
        return 4;
    }
    if !symbol_sequence_accepts(runtime.sequence, position, id) {
        return 4;
    }
    var next = position + 1;
    result.next = runtime.sequence_states.data[next];
    result.pop = position;
    return 6;
}

fn lr_parser_decide(value: LRParser*, ready: bool, id: u32, error: bool, result: LRStep*): u32 {
    if value.sequence {
        return lr_parser_sequence_step(value, ready, id, error, result);
    }
    var top = value.stack.length -1;
    var state = value.stack.data[top].state;
    var action: LRAction;
    action.rule = lr_none();
    action.state = lr_none();
    var use_default = false;
    if value.prefix {
        if !ready {
            action.rule = lr_runtime_default(value.runtime, state);
            use_default = action.rule != lr_none();
        }
    }
    var found = use_default;
    if use_default {
        value.work.actions++;
    } else {
        if !ready {
            if !value.finishing {
                return 0;
            }
        }
        if value.finishing {
            id = LRTokenEnd;
            error = false;
        }
        if !error {
            value.work.actions++;
            found = lr_runtime_action(value.runtime, state, id, &action);
        }
        if !found {
            if value.prefix {
                if value.shifted {
                    if !value.finishing {
                        value.work.actions++;
                        found = lr_runtime_action(value.runtime, state, LRTokenEnd, &action);
                        if found {
                            value.finishing = true;
                            id = LRTokenEnd;
                        }
                    }
                }
            }
        }
    }
    if !found {
        return 4;
    }
    result.id = id;
    result.rule = action.rule;
    result.next = action.state;
    if action.state != lr_none() {
        return 1;
    }
    if action.rule == 0 {
        if value.prefix {
            if !value.shifted {
                return 5;
            }
        }
        return 3;
    }
    var rule = &value.runtime.rules.data[action.rule];
    var invalid = rule.count >= value.stack.length;
    if invalid {
        return 8;
    }
    result.pop = rule.count;
    if !ready {
        result.start = value.consumed;
    }
    if value.finishing {
        result.start = value.consumed;
    }
    result.end = result.start;
    var begin = value.stack.length -rule.count;
    if rule.count != 0 {
        result.start = value.stack.data[begin].start;
        result.end = result.start;
        var index = begin;
        for(; index != value.stack.length; index++) {
            var frame = &value.stack.data[index];
            var end = frame.start + frame.length;
            if end > result.end {
                result.end = end;
            }
        }
    }
    var previous = begin -1;
    result.next = lr_runtime_goto(value.runtime, value.stack.data[previous].state, rule.owner);
    invalid = result.next == lr_none();
    if invalid {
        return 8;
    }
    return 2;
}

export fn lr_parser_step(value: LRParser*, ready: bool, id: u32, error: bool, start: usize, length: usize, result: LRStep*): u32 {
    *result = default;
    result.rule = lr_none();
    result.next = lr_none();
    result.id = id;
    result.start = start;
    result.end = start + length;
    result.kind = lr_parser_decide(value, ready, id, error, result);
    return result.kind;
}

export fn lr_parser_commit(value: LRParser*, step: LRStep*, first: usize, last: usize): bool {
    if step.kind == 6 {
        var evidence = step.end != step.start;
        var byte = convert(u8, evidence);
        var ok = vector_push(&value.evidence, byte);
        if !ok {
            return false;
        }
        if value.evidence.length == 1 {
            value.sequence_start = step.start;
        }
        if step.end > value.sequence_end {
            value.sequence_end = step.end;
        }
        value.sequence_first = first;
        value.sequence_last = last;
        value.consumed = step.end;
        value.shifted = true;
        value.work.shifts++;
        return true;
    }
    var length = value.stack.length -step.pop;
    var count = length + 1;
    var ok = vector_reserve(&value.stack, count);
    if !ok {
        return false;
    }
    var frame = &value.stack.data[length];
    frame.state = step.next;
    frame.first = first;
    frame.last = last;
    frame.start = step.start;
    frame.length = step.end - step.start;
    value.stack.length = count;
    if step.kind == 1 {
        value.consumed = step.end;
        value.shifted = true;
        value.work.shifts++;
    } else {
        value.work.reductions++;
        value.work.popped = value.work.popped + step.pop;
        value.sequence = false;
    }
    return true;
}

export fn lr_parser_frame_count(value: LRParser*): usize {
    if value.sequence {
        var count = value.evidence.length + 1;
        return count;
    }
    return value.stack.length;
}

export fn lr_parser_frame(value: LRParser*, index: usize, result: LRFrame*): void {
    if value.sequence {
        *result = default;
        result.first = lr_none();
        result.last = lr_none();
        result.state = value.runtime.sequence_states.data[index];
        if index != 0 {
            var previous = index -1;
            result.length = convert(usize, value.evidence.data[previous]);
        }
    } else {
        copy(result, &value.stack.data[index], sizeof(LRFrame));
    }
}

export fn lr_parser_frames(value: LRParser*): LRFrame* {
    return value.stack.data;
}

export fn lr_parser_sequence_forest(value: LRParser*, result: LRFrame*): void {
    *result = default;
    result.first = value.sequence_first;
    result.last = value.sequence_last;
    result.start = value.sequence_start;
    result.length = value.sequence_end - value.sequence_start;
}

export fn lr_parser_consumed(value: LRParser*): usize {
    return value.consumed;
}

export fn lr_parser_shifted(value: LRParser*): bool {
    return value.shifted;
}

export fn lr_parser_work(value: LRParser*, result: LRWork*): void {
    copy(result, &value.work, sizeof(LRWork));
}

// Error-path probes share one explicit work budget. They never execute semantic
// actions, consume a source stream, or mutate the real recognizer's stack.
struct LRProbe {
    runtime: LRRuntime*;
    budget: LRProbeBudget*;
    frames: vector(LRProbeFrame);
}

export fn lr_probe_destroy(value: LRProbe*): void {
    if value == null {
        return;
    }
    vector_dispose(&value.frames);
    free(value);
}

fn lr_probe_allocate(runtime: LRRuntime*, budget: LRProbeBudget*, count: usize): LRProbe* {
    var value = alloc(LRProbe, 1);
    if value == null {
        budget.complete = false;
        return null;
    }
    *value = default;
    value.runtime = runtime;
    value.budget = budget;
    if vector_reserve(&value.frames, count) {
        value.frames.length = count;
        return value;
    }
    budget.complete = false;
    lr_probe_destroy(value);
    return null;
}

export fn lr_probe_create(parser: LRParser*, budget: LRProbeBudget*): LRProbe* {
    var count = lr_parser_frame_count(parser);
    var value = lr_probe_allocate(parser.runtime, budget, count);
    if value == null {
        return null;
    }
    var index: usize = 0;
    loop {
        if index == count {
            return value;
        }
        var frame: LRFrame;
        lr_parser_frame(parser, index, &frame);
        value.frames.data[index].state = frame.state;
        value.frames.data[index].consumed = frame.length != 0;
        index++;
    }
}

export fn lr_probe_clone(source: LRProbe*): LRProbe* {
    var count = source.frames.length;
    var value = lr_probe_allocate(source.runtime, source.budget, count);
    if value != null {
        var bytes = count *sizeof(LRProbeFrame);
        copy(value.frames.data, source.frames.data, bytes);
    }
    return value;
}

export fn lr_probe_reset(value: LRProbe*): void {
    value.frames.length = 1;
    value.frames.data[0].state = 0;
    value.frames.data[0].consumed = false;
}

export fn lr_probe_count(value: LRProbe*): usize {
    return value.frames.length;
}

export fn lr_probe_frames(value: LRProbe*): LRProbeFrame* {
    return value.frames.data;
}

export fn lr_probe_accepts(value: LRProbe*, id: u32): bool {
    var top = value.frames.length -1;
    var action: LRAction;
    return lr_runtime_action(value.runtime, value.frames.data[top].state, id, &action);
}

export fn lr_probe_step(value: LRProbe*, id: u32, before: usize*): u32 {
    *before = lr_none();
    var steps: usize = 0;
    loop {
        var exhausted = steps == 128;
        if exhausted {
            break;
        }
        exhausted = value.budget.remaining == 0;
        if exhausted {
            break;
        }
        value.budget.remaining--;
        var top = value.frames.length -1;
        var state = value.frames.data[top].state;
        var action: LRAction;
        if !lr_runtime_action(value.runtime, state, id, &action) {
            return 0;
        }
        var frame: LRProbeFrame;
        frame.state = action.state;
        frame.consumed = false;
        if action.state != lr_none() {
            *before = state;
            var ok = lr_append(LRProbeFrame, &value.frames, &frame);
            if ok {
                return 1;
            }
            break;
        }
        if action.rule == 0 {
            return 2;
        }
        var rule = &value.runtime.rules.data[action.rule];
        var invalid = rule.count >= value.frames.length;
        if invalid {
            return 0;
        }
        var begin = value.frames.length -rule.count;
        for(var index = begin; index != value.frames.length; index++) {
            if value.frames.data[index].consumed {
                frame.consumed = true;
            }
        }
        value.frames.length = begin;
        var previous = begin -1;
        frame.state = lr_runtime_goto(value.runtime, value.frames.data[previous].state, rule.owner);
        invalid = frame.state == lr_none();
        if invalid {
            return 0;
        }
        var ok = lr_append(LRProbeFrame, &value.frames, &frame);
        if !ok {
            break;
        }
        steps++;
    }
    value.budget.complete = false;
    return 0;
}

// Editor lookahead snapshots are derived indexes over the live LR stack. They
// never run semantic actions or alter the recognizer. Every query is bounded.
struct LRCompletion {
    budget: LRProbeBudget;
    original: LRProbe*;
}

struct LRCompletionPath {
    probe: LRProbe*;
    parent: usize;
    choice: usize;
    depth: usize;
}

export fn lr_completion_create(parser: LRParser*): LRCompletion* {
    var c = alloc(LRCompletion, 1);
    if c == null {
        return null;
    }
    *c = default;
    c.budget.complete = true;
    c.original = lr_probe_create(parser, &c.budget);
    if c.original == null {
        free(c);
        return null;
    }
    return c;
}

export fn lr_completion_destroy(c: LRCompletion*): void {
    if c == null {
        return;
    }
    lr_probe_destroy(c.original);
    free(c);
}

export fn lr_completion_runtime(c: LRCompletion*): LRRuntime* {
    return c.original.runtime;
}

export fn lr_completion_state(c: LRCompletion*): usize {
    var top = c.original.frames.length -1;
    return c.original.frames.data[top].state;
}

export fn lr_completion_accepts(c: LRCompletion*, id: u32): bool {
    if c == null {
        return false;
    }
    if c.original == null {
        return false;
