            break;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = middle + low;
        if lr_action_less(&values.data[middle], value) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if low < values.length {
        if !lr_action_less(value, &values.data[low]) {
            return true;
        }
    }
    var count = values.length + 1;
    if !vector_reserve(values, count) {
        return false;
    }
    var moved = values.length -low;
    var bytes = moved *sizeof(LRAction);
    var next = low + 1;
    copy(&values.data[next], &values.data[low], bytes);
    copy(&values.data[low], value, sizeof(LRAction));
    values.length = count;
    return true;
}

fn lr_row_destroy(value: LRRow*): void {
    vector_dispose(&value.actions);
    vector_dispose(&value.direct);
    free(value);
