        var item = &items.values.data[index];
        index++;
        var candidate = &source.analysis.rules[item.rule];
        var eligible = item.position < candidate.count;
        if !eligible {
            continue;
        }
        var position = candidate.begin + item.position;
        var symbol = &source.analysis.symbols[position];
        eligible = symbol.nonterminal == lr_none();
        eligible &&= symbol.first == a.first;
        eligible &&= symbol.last == a.last;
        if !eligible {
            continue;
        }
        var missing = candidate.precedence == 0;
        if missing {
            return 0;
        }
        if power != 0 {
            var incompatible = power != candidate.precedence;
            incompatible ||= direction != candidate.associativity;
            if incompatible {
                return 0;
            }
        }
        power = candidate.precedence;
        direction = candidate.associativity;
    }
    var missing = power == 0;
    if missing {
        return 0;
    }
    var reduce = rule.precedence > power;
    if rule.precedence == power {
        var incompatible = rule.associativity != direction;
        if incompatible {
            return 0;
        }
        if direction == 3 {
            return 3;
        }
        reduce = direction == 1;
    }
    if reduce != a_shift {
        return 1;
    }
    return 2;
}

fn lr_row_normalize(row: LRRow*, conflict: LRConflict*, state: usize, source: LRStates*): void {
