    var sequence = symbol_sequence_create(rule.count);
    missing = sequence == null;
    if missing {
        return;
    }
    value.sequence_states.data[0] = 0;
    index = 0;
    loop {
        if index == rule.count {
            break;
        }
        var position = rule.begin + index;
        var symbol = &source.analysis.symbols[position];
        var action: LRAction;
        ok = lr_runtime_action(value, value.sequence_states.data[index], symbol.first, &action);
        ok &&= action.state != lr_none();
        if !ok {
            symbol_sequence_destroy(sequence);
            return;
        }
        var next = index + 1;
        value.sequence_states.data[next] = action.state;
        symbol_sequence_set(sequence, index, symbol.first, symbol.last);
        index = next;
    }
    value.sequence_states.length = count;
    value.sequence = sequence;
    value.sequence_rule = root;
}

export fn lr_runtime_sequence(value: LRRuntime*): usize {
    return value.sequence_rule;
}

import tower;
import worker_policy;
import compiler_kernel;
import lr_runtime;
import lr_states;
import lr_analysis;
import lr_types;
import lr_work;
import parser_workers;
import .library.vector;
import .library.work_graph;
import .library.work_pool;

// Private derived table rows. Grammar entities remain authoritative; worker
// results publish in source-state order, including the first conflict.
struct LRRuntimeResult {
    row: LRRow*;
    state: LRRuntimeState;
    conflict: LRConflict;
    success: bool;
}

struct LRRuntimeTask {
    kernel: CompilerKernel;
    ticket: WorkTicket;
    source: LRStates*;
    results: LRRuntimeResult*;
    begin: usize;
    count: usize;
    success: bool;
}

var LRRuntimeGrain: usize = 128;

export fn compiler_lr_runtime_kernel(payload: void*): void {
    var task = bits(LRRuntimeTask*, payload);
    task.success = false;
    for(var i = task.begin; i < task.begin + task.count; i++) {
        var result = &task.results[i];
        var row = alloc(LRRow, 1);
        if row == null { return; }
        *row = default;
        result.row = row;
        result.conflict.state = lr_none();
        var input = task.source.states.data[i];
        foreach(var &action in &input.actions) {
            if !lr_action_insert(&row.actions, action) { return; }
        }
        lr_row_normalize(row, &result.conflict, i, task.source);
        if result.conflict.state == lr_none() {
            row.hash = lr_row_hash(row);
            if !lr_row_index(row) || !lr_runtime_gotos(&result.state, input, task.source.analysis) { return; }
        }
        result.success = true;
    }
    task.success = true;
}

// Hash interning is deterministic publication. Sorting, precedence/conflict
// checks, direct lookup indexes and goto construction all use private workers.
export fn lr_runtime_create_parallel(source: LRStates*, anchor: void*): LRRuntime* {
    var capacity = compiler_worker_capacity(anchor);
    var count = source.states.length / LRRuntimeGrain;
    if count > capacity { count = capacity; }
    if count < 2 || anchor == null { return lr_runtime_create(source); }
    return lr_runtime_create_work(source, anchor, count);
}

// Explicit executor width also exercises this ownership path with the serial
// instrumented transport. Production admission keeps its measured-size policy.
export fn lr_runtime_create_work(source: LRStates*, anchor: void*, count: usize): LRRuntime* {
    if count == 0 || count > 256 || count > source.states.length || anchor == null { return null; }
    var value = alloc(LRRuntime, 1);
    if value == null { return null; }
    *value = default;
    value.conflict.state = lr_none();
    value.sequence_rule = lr_none();
    defer lr_runtime_destroy(value);
    if !vector_reserve(&value.rules, source.analysis.rule_count)
        || !vector_reserve(&value.states, source.states.length)
        || !vector_reserve(&value.rows, source.states.length) { return null; }
    copy(value.rules.data, source.analysis.rules, source.analysis.rule_count * sizeof(LRProduction));
    value.rules.length = source.analysis.rule_count;
    fill(value.states.data, 0, source.states.length * sizeof(LRRuntimeState));
    value.states.length = source.states.length;
    var results = alloc(LRRuntimeResult, source.states.length);
    if results == null { return null; }
    fill(results, 0, source.states.length * sizeof(LRRuntimeResult));
    defer {
        for(var i: usize = 0; i < source.states.length; i++) {
            if results[i].row != null { lr_row_destroy(results[i].row); }
            vector_dispose(&results[i].state.gotos);
        }
        free(results);
    }
    var buckets: vector(usize) = default;
    defer vector_dispose(&buckets);
    buckets.length = source.states.length * 2 + 1;
    if !vector_reserve(&buckets, buckets.length) { return null; }
    fill(buckets.data, 255, buckets.length * sizeof(usize));
    var owner = entity_create_related(anchor);
    if owner == null { return null; }
    defer entity_release(owner);
    var kind = lr_work_node(owner);
    if kind == null || !entity_register(kind, sizeof(LRRuntimeTask), alignof(LRRuntimeTask), 0) { return null; }
    var workers: ParserWorkers = default;
    if !parser_workers_open(&workers, anchor, count) { return null; }
    defer parser_workers_close(&workers);
    if count > workers.pool.count { count = workers.pool.count; }
    var graph: WorkGraph;
    work_init(&graph, 1, 0);
    defer work_dispose(&graph);
    var jobs: LRRuntimeTask*[256];
    var position: usize = 0;
    for(var i: usize = 0; i < count; i++) {
        var node = lr_work_node(owner);
        if node == null { return null; }
        var job = bits(LRRuntimeTask*, entity_component_data(entity_component_add(node, kind)));
        if job == null { return null; }
        *job = default;
        job.kernel.kind = CompilerKernelKind.LRRuntime;
        job.kernel.payload = bits(void*, job);
        job.source = source;
        job.results = results;
        job.begin = position;
        job.count = source.states.length / count + (i < source.states.length % count ? 1 : 0);
        position += job.count;
        jobs[i] = job;
        var id = work_request(&graph, node, 1, convert(u64, job.begin));
        var ok = id != 0;
        ok &&= work_access(&graph, id, 1, 1, job.begin, job.count, WorkAccessMode.Write);
        ok &&= work_access(&graph, id, 1, 2, 0, 1, WorkAccessMode.Read);
        ok &&= work_seal(&graph, id);
        ok &&= work_demand(&graph, id);
        ok &&= work_take(&graph, &job.ticket);
        if !ok { return null; }
    }
    var view = entity_view_open(owner);
    if view == null { return null; }
    var admitted: usize = 0;
    var ok = true;
    for(; admitted < count; admitted++) {
        if !work_pool_submit(workers.pool, bits(void*, &jobs[admitted].kernel)) { ok = false; break; }
    }
    for(var i: usize = 0; i < admitted; i++) {
        if work_pool_receive(workers.pool, true) == null { ok = false; }
    }
    entity_view_close(view);
    for(var i: usize = 0; i < admitted; i++) {
        if !work_finish(&graph, &jobs[i].ticket, jobs[i].success) { ok = false; }
    }
    if !ok { return null; }
    // Consume each result in serial order. A later allocation failure cannot
    // replace an earlier grammar conflict; no partially built table escapes.
    for(var i: usize = 0; i < source.states.length; i++) {
        var result = &results[i];
        if !result.success { return null; }
        if result.conflict.state != lr_none() {
            copy(&value.conflict, &result.conflict, sizeof(LRConflict));
            var published = value;
            value = null;
            return published;
        }
        var row = result.row;
        var bucket = row.hash % buckets.length;
        var existing = buckets.data[bucket];
        while existing != lr_none() {
            var other = value.rows.data[existing];
            if lr_row_equal(row, other) {
                lr_row_destroy(row);
                row = other;
                break;
            }
            existing = other.next;
        }
        if existing == lr_none() {
            if !vector_push(&value.rows, row) { return null; }
            row.next = buckets.data[bucket];
            buckets.data[bucket] = value.rows.length - 1;
        }
        result.row = null;
        var state = &value.states.data[i];
        state.row = row;
        copy(&state.gotos, &result.state.gotos, sizeof(vector(LRGoto)));
        result.state.gotos = default;
    }
    var published = value;
    value = null;
    return published;
}

import tower;
import worker_policy;
import compiler_kernel;
import lr_analysis;
import lr_states;
import lr_types;
import lr_work;
import parser_workers;
import .library.vector;
import .library.work_graph;
import .library.work_pool;

struct LRStateTask {
    kernel: CompilerKernel;
    ticket: WorkTicket;
    analysis: LRAnalysis*;
    source: LRItems*;
    symbols: usize*;
    results: LRItems**;
    begin: usize;
    count: usize;
    success: bool;
}

var LRStateGrain: usize = 128;
var LRStateFanout: usize = 4;

export fn compiler_lr_state_kernel(payload: void*): void {
    var task = bits(LRStateTask*, payload);
    var analysis: LRAnalysis;
    copy(&analysis, task.analysis, sizeof(LRAnalysis));
    task.success = true;
    for(var i = task.begin; i < task.begin + task.count; i++) {
        var result = lr_items_create();
        task.results[i] = result;
        if result == null || !lr_items_goto(&analysis, task.source,
            &analysis.symbols[task.symbols[i]], result, false) {
            task.success = false;
            return;
        }
    }
}

// Outgoing closures of one state are independent. Only the coordinator interns
// kernels, publishes transition IDs and pops the pending stack, in exactly the
// serial order. Workers never mutate the state index or share failed flags.
export fn lr_states_create_parallel(analysis: LRAnalysis*, anchor: void*): LRStates* {
    var capacity = compiler_worker_capacity(anchor);
    if capacity <= 1 || anchor == null || analysis.symbol_count + analysis.rule_count < 32 {
        return lr_states_create(analysis);
    }
    var value = lr_states_begin(analysis);
    if value == null { return null; }
    defer lr_states_destroy(value);
    var owner = entity_create_related(anchor);
    if owner == null { return null; }
    defer entity_release(owner);
    var kind = lr_work_node(owner);
    if kind == null || !entity_register(kind, sizeof(LRStateTask), alignof(LRStateTask), 0) { return null; }
    var nodes: void*[256];
    var jobs: LRStateTask*[256];
    fill(&jobs, 0, 256 * sizeof(void*));
    for(var i: usize = 0; i < capacity; i++) {
        nodes[i] = lr_work_node(owner);
        if nodes[i] == null { return null; }
        jobs[i] = bits(LRStateTask*, entity_component_data(entity_component_add(nodes[i], kind)));
        if jobs[i] == null { return null; }
        fill(jobs[i], 0, sizeof(LRStateTask));
        jobs[i].analysis = analysis;
        jobs[i].kernel.kind = CompilerKernelKind.LRState;
        jobs[i].kernel.payload = bits(void*, jobs[i]);
    }
    var workers: ParserWorkers = default;
    defer parser_workers_close(&workers);
    var graph: WorkGraph;
    work_init(&graph, 1, 0);
    defer work_dispose(&graph);
    var results: vector(LRItems*);
    vector_init(LRItems*, &results);
    defer {
        for(var i: usize = 0; i < results.length; i++) { lr_items_destroy(results.data[i]); }
        vector_dispose(LRItems*, &results);
    }
    var ok = true;
    while value.pending.length != 0 && ok {
        value.pending.length--;
        var state = value.states.data[value.pending.data[value.pending.length]];
        if !lr_state_symbols(analysis, state) { return null; }
        // A single outgoing edge exposes no parallel work; tiny closures cost
        // less than the handoff. Keep the same transition algorithm in both
        // paths and start platform threads only for a useful ready batch.
        if state.symbols.length < LRStateFanout || state.items.values.length < LRStateGrain {
            for(var i: usize = 0; i < state.symbols.length && ok; i++) {
                ok = lr_state_transition(value, state, state.symbols.data[i]);
            }
            continue;
        }
        if workers.pool == null && !parser_workers_open(&workers, anchor, capacity) { return null; }
        var pool = workers.pool;
        if !vector_reserve(LRItems*, &results, state.symbols.length) { return null; }
        results.length = state.symbols.length;
        fill(results.data, 0, results.length * sizeof(LRItems*));
        var count = results.length < pool.count ? results.length : pool.count;
        var position: usize = 0;
        // One joined wave per state. Each worker owns a contiguous output range,
        // amortizing dispatch over several closures instead of one tiny edge.
        for(var i: usize = 0; i < count && ok; i++) {
            var job = jobs[i];
            job.source = state.items;
            job.symbols = state.symbols.data;
            job.results = results.data;
            job.begin = position;
            job.count = results.length / count + (i < results.length % count ? 1 : 0);
            position += job.count;
            var id = work_request(&graph, nodes[i], 1, convert(u64, job.begin));
            ok = id != 0;
            ok &&= work_access(&graph, id, 1, 1, job.begin, job.count, WorkAccessMode.Write);
            ok &&= work_access(&graph, id, 1, 2, 0, 1, WorkAccessMode.Read);
            ok &&= work_seal(&graph, id);
            ok &&= work_demand(&graph, id);
            ok &&= work_take(&graph, &job.ticket);
        }
        if !ok { break; }
        var view = entity_view_open(owner);
        if view == null { return null; }
        var admitted: usize = 0;
        for(; admitted < count; admitted++) {
            if !work_pool_submit(pool, bits(void*, &jobs[admitted].kernel)) { ok = false; break; }
        }
        for(var i: usize = 0; i < admitted; i++) {
            if work_pool_receive(pool, true) == null { ok = false; }
        }
        entity_view_close(view);
        for(var i: usize = 0; i < admitted; i++) {
            if !work_finish(&graph, &jobs[i].ticket, jobs[i].success) || !jobs[i].success { ok = false; }
        }
        for(var i: usize = 0; i < results.length; i++) {
            var items = results.data[i];
            results.data[i] = null;
            if !ok { lr_items_destroy(items); continue; }
            var edge: LRTransition;
            edge.symbol = state.symbols.data[i];
            edge.state = lr_states_intern(value, items, edge.symbol);
            ok = edge.state != lr_none();
            ok &&= lr_append(LRTransition, &state.edges, &edge);
        }
        results.length = 0;
        // No consumer crosses this joined wave. Retain capacity while rejecting
        // every prior ticket, including when a component slot is reused.
        if !work_reset(&graph, graph.revision + 1, 0) { ok = false; }
    }
    if !ok { return null; }
    var result = value;
    value = null;
    return result;
}

import tower;
import lr_types;
import lr_analysis;
import .library.vector;

// LR(0) state construction and kernel interning. The same item operations handle
// character ranges and token IDs; all records are disposable grammar indexes.
struct LRState {
    items: LRItems*;
    symbols: vector(usize);
    edges: vector(LRTransition);
    actions: vector(LRAction);
    base: usize;
    origin: usize;
    hash: usize;
    next: usize;
}

struct LRStates {
    analysis: LRAnalysis*;
    states: vector(LRState*);
    pending: vector(usize);
    buckets: vector(usize);
}

export fn lr_kernel(analysis: LRAnalysis*, item: LRItem*): bool {
    if item.position != 0 {
        return true;
    }
    if item.rule == 0 {
        return true;
    }
    var empty = analysis.rules[item.rule].count == 0;
    return empty;
}

fn lr_state_hash(analysis: LRAnalysis*, items: LRItems*): usize {
    var hash: usize = 2166136261;
    var index: usize = 0;
    loop {
        if index == items.values.length {
            return hash;
        }
        var item = &items.values.data[index];
        if lr_kernel(analysis, item) {
            hash = hash ^ item.rule;
            hash = hash * 16777619;
            hash = hash ^ item.position;
            hash = hash * 16777619;
        }
        index++;
    }
}

fn lr_state_equal(analysis: LRAnalysis*, a: LRItems*, b: LRItems*): bool {
    var left: usize = 0;
    var right: usize = 0;
    loop {
        for(; left != a.values.length; left++) {
            var kernel = lr_kernel(analysis, &a.values.data[left]);
            if kernel {
                break;
            }
        }
        for(; right != b.values.length; right++) {
            var kernel = lr_kernel(analysis, &b.values.data[right]);
            if kernel {
                break;
            }
        }
        var end = left == a.values.length;
        if end {
            var same = right == b.values.length;
            return same;
        }
        end = right == b.values.length;
        if end {
            return false;
        }
        var different = a.values.data[left].rule != b.values.data[right].rule;
        if different {
            return false;
        }
        different = a.values.data[left].position != b.values.data[right].position;
        if different {
            return false;
        }
        left++;
        right++;
    }
}

fn lr_symbol_less(analysis: LRAnalysis*, a: usize, b: usize): bool {
    var left = &analysis.symbols[a];
    var right = &analysis.symbols[b];
    var left_terminal = left.nonterminal == lr_none();
    var right_terminal = right.nonterminal == lr_none();
    var different = left_terminal != right_terminal;
    if different {
        return right_terminal;
    }
    if left_terminal {
        different = left.first != right.first;
        if different {
            var less = left.first < right.first;
            return less;
        }
        var less = left.last < right.last;
        return less;
    }
    var less = analysis.nonterminals[left.nonterminal].order < analysis.nonterminals[right.nonterminal].order;
    return less;
}

fn lr_state_symbol(analysis: LRAnalysis*, state: LRState*, symbol: usize): bool {
    var low: usize = 0;
    var high = state.symbols.length;
    loop {
        if low == high {
            break;
        }
        var middle = high -low;
        middle = middle / 2;
        middle = middle + low;
        if lr_symbol_less(analysis, state.symbols.data[middle], symbol) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    if low < state.symbols.length {
        if !lr_symbol_less(analysis, symbol, state.symbols.data[low]) {
            return true;
        }
    }
    var count = state.symbols.length + 1;
    if !vector_reserve(&state.symbols, count) {
        return false;
    }
    var moved = state.symbols.length -low;
    var bytes = moved *sizeof(usize);
    var next = low + 1;
    copy(&state.symbols.data[next], &state.symbols.data[low], bytes);
    state.symbols.data[low] = symbol;
    state.symbols.length = count;
    return true;
}

fn lr_state_destroy(state: LRState*): void {
    lr_items_destroy(state.items);
    vector_dispose(&state.symbols);
    vector_dispose(&state.edges);
    vector_dispose(&state.actions);
    free(state);
}

export fn lr_states_destroy(value: LRStates*): void {
    if value == null {
        return;
    }
    foreach(var & state in &value.states) {
        lr_state_destroy(*state);
    }
    vector_dispose(&value.states);
    vector_dispose(&value.pending);
    vector_dispose(&value.buckets);
    free(value);
}

fn lr_states_rehash(value: LRStates*): bool {
    var needed = value.states.length *2;
    if value.buckets.length > needed {
        return true;
    }
    needed = value.buckets.length * 2;
    needed = needed + 17;
    if !vector_reserve(&value.buckets, needed) {
        return false;
    }
    value.buckets.length = needed;
    var index: usize = 0;
    for(; index != needed; index++) {
        value.buckets.data[index] = lr_none();
    }
    index = 0;
    loop {
        if index == value.states.length {
            return true;
        }
        var state = value.states.data[index];
        var bucket = state.hash % needed;
        state.next = value.buckets.data[bucket];
        value.buckets.data[bucket] = index;
        index++;
    }
}

// Takes ownership of items on every path, including an existing kernel match.
fn lr_states_intern(value: LRStates*, items: LRItems*, origin: usize): usize {
    defer lr_items_destroy(items);
    var ok = lr_states_rehash(value);
    if !ok {
        return lr_none();
    }
    var hash = lr_state_hash(value.analysis, items);
    var bucket_count = value.buckets.length;
    if bucket_count == 0 {
        return lr_none();
    }
    var bucket = hash % bucket_count;
    var index = value.buckets.data[bucket];
    loop {
        if index == lr_none() {
            break;
        }
        var state = value.states.data[index];
        var same = hash == state.hash;
        if same {
            same = lr_state_equal(value.analysis, items, state.items);
            if same {
                return index;
            }
        }
        index = state.next;
    }
    var state = alloc(LRState, 1);
    if state == null {
        return lr_none();
    }
    fill(state, 0, sizeof(LRState));
    state.items = items;
    items = null; // Ownership moved to the state.
    state.origin = origin;
    state.hash = hash;
    state.next = value.buckets.data[bucket];
    index = value.states.length;
    ok = vector_push(&value.pending, index);
    ok &&= vector_push(&value.states, state);
    if !ok {
        lr_state_destroy(state);
        return lr_none();
    }
    value.buckets.data[bucket] = index;
    return index;
}

fn lr_states_begin(analysis: LRAnalysis*): LRStates* {
    var value = alloc(LRStates, 1);
    var missing = value == null;
    if missing {
        return null;
    }
    *value = default;
    defer lr_states_destroy(value);
    value.analysis = analysis;
    var items = lr_items_create();
    missing = items == null;
    if missing {
        return null;
    }
    var seed: LRItem = default;
    var ok = lr_items_insert(items, &seed);
    ok &&= lr_items_close(analysis, items, false);
    if !ok {
        lr_items_destroy(items);
        return null;
    }
    var start = lr_states_intern(value, items, lr_none());
    missing = start == lr_none();
    if missing {
        return null;
    }
    var result = value;
    value = null;
    return result;
}

fn lr_state_symbols(analysis: LRAnalysis*, state: LRState*): bool {
    var done = false;
    var ok = true;
    // Kernel items precede closure items, as in the ordinary LR builder.
    var pass: usize = 0;
    loop {
        done = pass == 2;
        if done {
            break;
        }
        var position: usize = 0;
        loop {
            done = position == state.items.values.length;
            if done {
                break;
            }
            var item = &state.items.values.data[position];
            var kernel = lr_kernel(analysis, item);
            var want_kernel = pass == 0;
            var include = kernel == want_kernel;
            var rule = &analysis.rules[item.rule];
            var present = item.position < rule.count;
            if include {
                if present {
                    var symbol = rule.begin + item.position;
                    ok = lr_state_symbol(analysis, state, symbol);
                    if !ok {
                        return false;
                    }
                }
            }
            position++;
        }
        pass++;
    }
    return true;
}

fn lr_state_transition(value: LRStates*, state: LRState*, symbol: usize): bool {
    var analysis = value.analysis;
    var ok = true;
    var missing = false;
    var next = lr_items_create();
    missing = next == null;
    if missing {
        return false;
    }
    ok = lr_items_goto(analysis, state.items, &analysis.symbols[symbol], next, false);
    if !ok {
        lr_items_destroy(next);
        return false;
    }
    var edge: LRTransition;
    edge.symbol = symbol;
    edge.state = lr_states_intern(value, next, symbol);
    missing = edge.state == lr_none();
    if missing {
        return false;
    }
    ok = lr_append(LRTransition, &state.edges, &edge);
    if !ok {
        return false;
    }
    return true;
}

export fn lr_states_create(analysis: LRAnalysis*): LRStates* {
    var value = lr_states_begin(analysis);
    if value == null { return null; }
    defer lr_states_destroy(value);
    loop {
        var done = value.pending.length == 0;
        if done {
            var result = value;
            value = null; // Transfer ownership to the caller.
            return result;
        }
        value.pending.length--;
        var index = value.pending.data[value.pending.length];
        var state = value.states.data[index];
        if !lr_state_symbols(analysis, state) { return null; }
        var position: usize = 0;
        loop {
            done = position == state.symbols.length;
            if done {
                break;
            }
            if !lr_state_transition(value, state, state.symbols.data[position]) { return null; }
            position++;
        }
    }
}

export fn lr_states_count(value: LRStates*): usize {
    return value.states.length;
}

export fn lr_states_items(value: LRStates*, index: usize): LRItems* {
    return value.states.data[index].items;
}

export fn lr_states_origin(value: LRStates*, index: usize): usize {
    return value.states.data[index].origin;
}

export fn lr_states_edge_count(value: LRStates*, index: usize): usize {
    return value.states.data[index].edges.length;
}

export fn lr_states_edges(value: LRStates*, index: usize): LRTransition* {
    return value.states.data[index].edges.data;
}

