import semantic_evaluation_work;
import semantic_evaluation_aggregates;
import semantic_defer;
import compiler_kernel;
import semantic_work_ids;
import foundation_tags;
import foundation_types;
import interpreter_context_types;
import .library.vector;
import .library.work_graph;
import .library.work_pool;

extern fn interpreter_invocation_init(invocation: IMInvocation*, function: void*, width: usize, arguments: u64*, count: usize, strict: bool, fuel: u64): bool;
extern fn interpreter_invocation_dispose(invocation: IMInvocation*): void;
extern fn interpreter_function_result(invocation: IMInvocation*, reference: u64, type: FoundationType*, offset: usize): void*;
extern fn entity_view_open(anchor: void*): void*;
extern fn entity_view_close(view: void*): void;

var EvaluationQuery: u32 = 2;
var EvaluationFuel: u64 = 1000000;

struct SemanticEvaluation {
    kernel: CompilerKernel;
    ticket: WorkTicket;
    subject: void*;
    owner: void*;
    literal: void*;
    expression: void*;
    function: void*;
    ready: IMDependency*;
    invocation: IMInvocation;
    requested: bool;
    started: bool;
    inferred: bool;
    aliases: vector(SemanticEvaluationAlias);
    leaves: vector(SemanticEvaluationLeaf);
    aggregate_type: FoundationType;
    aggregate: bool;
}

fn sem_evaluation_dependency(c: SemanticContext*, node: void*): IMDependency* {
    if c.evaluation_ready == null { return null; }
    var dependency = bits(IMDependency*, entity_component_data(entity_component_get(node, c.evaluation_ready)));
    if dependency != null && dependency.source != null { return dependency.source; }
    return dependency;
}

// Deferred cleanup clones canonical operations before stages run. Keep their
// literal results linked to the original producer instead of copying its zero
// placeholder as if it were a completed compile-time value.
fn sem_evaluation_clone(c: SemanticContext*, original: void*, clone: void*): void {
    var dependency = sem_evaluation_dependency(c, original);
    if dependency == null { return; }
    var result = sem_evaluation_get(c, dependency.subject);
    sem_require(result != null);
    var alias: SemanticEvaluationAlias = default;
    alias.producer = dependency.subject;
    alias.original = original;
    alias.clone = clone;
    if c.evaluation_aliases != null {
        sem_require(vector_push(c.evaluation_aliases, alias));
    } else { sem_require(vector_push(&result.aliases, alias)); }
    var link = bits(IMDependency*, entity_component_data(entity_component_add(clone, c.evaluation_ready)));
    sem_require(link != null);
    fill(link, 0, sizeof(IMDependency));
    link.subject = clone;
    link.source = dependency;
}

// Workers never append to another producer's alias vector. Publish these links
// only after every stage in the wave has released its component leases.
fn sem_evaluation_aliases(c: SemanticContext*, aliases: vector(SemanticEvaluationAlias)*): void {
    foreach(var &alias in aliases) {
        var result = sem_evaluation_get(c, alias.producer);
        sem_require(result != null);
        sem_require(vector_push(&result.aliases, *alias));
    }
    aliases.length = 0;
}

fn sem_evaluation_get(c: SemanticContext*, subject: void*): SemanticEvaluation* {
    if c.evaluation_results == null { return null; }
    var component = entity_component_get(subject, c.evaluation_results);
    return bits(SemanticEvaluation*, entity_component_data(component));
}

fn sem_evaluation_begin(c: SemanticContext*): void {
    if c.evaluation_results != null { return; }
    c.evaluation_results = sem_create(c.program.root);
    sem_require(entity_register(c.evaluation_results, sizeof(SemanticEvaluation), alignof(SemanticEvaluation), 0));
    c.evaluation_ready = sem_create(c.program.root);
    sem_require(entity_register(c.evaluation_ready, sizeof(IMDependency), alignof(IMDependency), 0));
}

fn sem_evaluation_request(c: SemanticContext*, result: SemanticEvaluation*): void {
    var id = work_request(&c.queries, result.subject, EvaluationQuery, 0);
    sem_require(id != 0);
    var preparation = work_request(&c.queries, result.subject, EvaluationPrepareQuery, 0);
    sem_require(preparation != 0 && work_depend(&c.queries, id, preparation));
    var body = work_find(&c.queries, result.owner, convert(u32, SemanticQuery.Body), 0);
    if body != 0 { sem_require(work_depend(&c.queries, preparation, body)); }
    if result.inferred {
        var proof = work_find(&c.queries, c.program.root, convert(u32, SemanticQuery.KnownProof), 0);
        var clone = work_request(&c.queries, result.subject, convert(u32, SemanticQuery.KnownClone), 0);
        sem_require(proof != 0 && clone != 0 && work_depend(&c.queries, clone, proof));
        sem_require(work_depend(&c.queries, preparation, clone));
    }
    sem_require(work_access(&c.queries, id, 1, 2, id, 1, WorkAccessMode.Write));
    sem_require(work_access(&c.queries, id, 1, 3, 0, ~convert(usize, 0), WorkAccessMode.Read));
    sem_require(work_seal(&c.queries, id));
}

fn sem_comptime(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    var existing = sem_get(n);
    if existing != null { return sem_surface_expected(c, n, expected_type); }
    c.evaluation_depth++;
    var expression = sem_operand(c, sem_member(n, "value"), expected_type);
    c.evaluation_depth--;
    if !sem_ok(c) || expression == null { return n; }
    var input = sem_get(expression);
    var value = sem_node(c, n, KOperand);
    sem_set_type(&value.type, &input.type);
    value.constant = true;
    // This typed placeholder cannot leave compilation. The query result replaces
    // it before any formatter, runtime or backend can consume the checked graph.
    value.bits = 0;
    var literal = n;
    if input.type.pointers == 0 && semantic_enum(&input.type) {
        var underlying = sem_type_copy(c, &input.type);
        underlying.record = null;
        literal = sem_surface_constant(c, n, underlying, 0);
        value.kind = KConvert;
        value.constant = false;
        value.value = literal;
    }
    if c.unevaluated { return n; }
    if input.type.pointers != 0 || input.type.scalar == SVoid {
        sem_fail(c, n, "Compile-time results require a relocatable value, not a raw pointer or void");
        return n;
    }
    sem_evaluation_begin(c);
    var result = bits(SemanticEvaluation*, entity_component_data(entity_component_add(n, c.evaluation_results)));
    sem_require(result != null);
    fill(result, 0, sizeof(SemanticEvaluation));
    result.subject = n;
    result.owner = c.current;
    result.literal = literal;
    result.expression = expression;
    result.requested = c.evaluation_depth == 0;
    result.ready = bits(IMDependency*, entity_component_data(entity_component_add(n, c.evaluation_ready)));
    sem_require(result.ready != null);
    fill(result.ready, 0, sizeof(IMDependency));
    result.ready.subject = n;
    result.aggregate = semantic_aggregate(&input.type);
    if result.aggregate {
        result.aggregate_type = input.type;
        sem_evaluation_aggregate(c, result, n, &input.type, EvaluationRootProjection);
    }
    if literal != n {
        // Lowering may materialize the typed integer before its enum conversion.
        // That initializer must suspend too, before it can capture a stale zero.
        var link = bits(IMDependency*, entity_component_data(entity_component_add(literal, c.evaluation_ready)));
        sem_require(link != null);
        *link = default;
        link.subject = literal;
        link.source = result.ready;
    }
    result.kernel.kind = CompilerKernelKind.Evaluate;
    result.kernel.payload = bits(void*, &result.invocation);
    sem_require(vector_push(void*, &c.evaluation_jobs, bits(void*, result)));
    // Interpreter state is private to this subject; shared input entities are
    // immutable for a dispatch wave and publication happens after all joins.
    // Body workers attach canonical result components under their entity lease;
    // the coordinator registers dependencies after publication at the barrier.
    if c.entity_stage == null { sem_evaluation_request(c, result); }
    return n;
}

fn sem_evaluation_function(c: SemanticContext*, result: SemanticEvaluation*): void* {
    if result.function == null {
        result.function = sem_control_node(c, result.subject, KFunction);
        sem_set_type(&sem_get(result.function).type, &sem_get(result.subject).type);
        if result.aggregate {
            sem_get(result.function).type = result.aggregate_type;
            sem_get(result.function).type.pointers++;
        }
    }
    return result.function;
}

fn sem_evaluation_clone_expression(c: SemanticContext*, result: SemanticEvaluation*): void {
    // Capture validity follows executed interpreter reads, after ordinary
    // lowering has preserved lazy branches. This clone computes no values.
    var function = sem_evaluation_function(c, result);
    var previous = c.current;
    c.current = function;
    var clones = sem_table(c);
    var nodes = sem_list(c);
    result.expression = sem_defer_clone(c, function, result.expression, clones, nodes);
    foreach(var node in nodes) {
        var value = sem_get(node);
        if value.binding != null {
            var local = sem_find(clones, null, value.binding);
            if local != null { value.binding = local.value; }
        }
    }
    c.current = previous;
}

fn sem_evaluation_prepare(c: SemanticContext*, result: SemanticEvaluation*): void {
    if result.aggregate { sem_evaluation_aggregate_prepare(c, result); return; }
    var function = sem_evaluation_function(c, result);
    var definition = sem_get(function);
    definition.body = sem_control_node(c, function, KBlock);
    var returned = sem_control_node(c, definition.body, KReturn);
    sem_get(returned).value = result.expression;
    sem_push(&sem_get(definition.body).items, returned);
    var previous = c.current;
    c.current = function;
    sem_lift_block(c, definition.body);
    c.current = previous;
}

fn sem_evaluation_cycle(c: SemanticContext*, id: usize): void {
    var cycle: vector(usize);
    vector_init(usize, &cycle);
    var found = work_cycle(&c.queries, id, &cycle);
    sem_require(found);
    var text: u8* = "Compile-time dependency cycle";
    var index: usize = 0;
    while index < cycle.length {
        var task = work_task(&c.queries, cycle.data[index]);
        text = sem_cat(c, text, index == 0 ? ": " : " -> ");
        text = sem_cat(c, text, sem_decimal(c, convert(u64, sem_get(task.subject).start)));
        index++;
    }
    vector_dispose(usize, &cycle);
    sem_fail(c, work_task(&c.queries, id).subject, text);
}

fn sem_evaluations(c: SemanticContext*): void {
    if !sem_ok(c) || c.evaluation_jobs.length == 0 { return; }
    sem_evaluation_prepare_all(c);
    if !sem_ok(c) { return; }
    var index: usize = 0;
    while index < c.evaluation_jobs.length && sem_ok(c) {
        var result = bits(SemanticEvaluation*, c.evaluation_jobs.data[index]);
        if result.requested {
            sem_require(work_demand(&c.queries, work_request(&c.queries, result.subject, EvaluationQuery, 0)));
        }
        index++;
    }
    if !sem_ok(c) { return; }
    if c.workers.count == 0 { sem_require(sem_workers_open(c)); }
    var view = entity_view_open(c.program.root);
    sem_require(view != null);
    var batch: SemanticEvaluation*[256];
    loop {
        var count: usize = 0;
        var ticket: WorkTicket;
        while count < c.workers.count && work_take_query(&c.queries, &ticket, EvaluationQuery) {
            var task = work_task(&c.queries, ticket.task);
            sem_require(task.query == EvaluationQuery);
            var result = sem_evaluation_get(c, task.subject);
            sem_require(result != null);
            result.ticket = ticket;
            if !result.started {
                interpreter_invocation_init(&result.invocation, result.function, convert(usize, c.program.pointer_bytes), null, 0, true, EvaluationFuel);
                result.invocation.context.dependency_kind = c.evaluation_ready;
                result.invocation.context.value_inputs = c.value_inputs;
                result.invocation.context.require_relocatable = result.inferred;
                result.invocation.context.retain_result_storage = result.aggregate;
                result.started = true;
            }
            batch[count] = result;
            sem_require(work_pool_submit(&c.workers, bits(void*, &result.kernel)));
            count++;
        }
        if count == 0 { break; }
        index = 0;
        while index < count {
            sem_require(work_pool_receive(&c.workers, true) != null);
            index++;
        }
        index = 0;
        while index < count {
            var result = batch[index];
            var invocation = &result.invocation;
            if invocation.state.failed {
                result.ready.failed = true;
                result.ready.ready = true;
                if !result.inferred { sem_fail(c, result.subject, invocation.context.error.data); }
                sem_require(work_finish(&c.queries, &result.ticket, result.inferred));
                interpreter_invocation_dispose(invocation);
            } else {
                if invocation.state.done {
                    if result.aggregate { sem_evaluation_aggregate_publish(c, result); }
                    else {
                        sem_evaluation_value(result.subject, invocation, invocation.context.result);
                        sem_evaluation_value(result.literal, invocation, invocation.context.result);
                    }
                    if invocation.state.failed && !result.inferred { sem_fail(c, result.subject, invocation.context.error.data); }
                    foreach(var &alias in &result.aliases) {
                        var original = sem_get(alias.original);
                        if original.constant || original.kind == KFunctionReference {
                            var target = sem_get(alias.clone);
                            target.bits = original.bits;
                            target.binding = original.binding;
                            target.kind = original.kind;
                            target.constant = original.constant;
                        }
                    }
                    result.ready.failed = invocation.state.failed || !sem_ok(c);
                    result.ready.ready = true;
                    sem_require(work_finish(&c.queries, &result.ticket, sem_ok(c) && (result.inferred || !invocation.state.failed)));
                    interpreter_invocation_dispose(invocation);
                } else {
                    var waiting = invocation.context.waiting;
                    if waiting != null {
                        var dependency = work_request(&c.queries, waiting, EvaluationQuery, 0);
                        sem_require(work_suspend(&c.queries, &result.ticket, dependency));
                    } else {
                        sem_require(work_yield(&c.queries, &result.ticket));
                    }
                }
            }
            index++;
        }
        if !sem_ok(c) { break; }
    }
    entity_view_close(view);
    index = 0;
    while index < c.queries.tasks.length && sem_ok(c) {
        var task = work_task(&c.queries, index + 1);
        if task.query == EvaluationQuery && task.demanded && task.state != WorkState.Succeeded {
            var result = sem_evaluation_get(c, task.subject);
            if result != null && result.inferred {
                result.ready.failed = true;
                result.ready.ready = true;
            } else { sem_evaluation_cycle(c, index + 1); }
        }
        index++;
    }
}

// Function results relocate through their bound Foundation declaration. The
// interpreter's private numeric reference never becomes a serialized constant.
fn sem_evaluation_value(node: void*, invocation: IMInvocation*, bits_value: u64): void {
    if invocation.state.failed { return; }
    var value = sem_get(node);
    value.bits = bits_value;
    if value.type.scalar == SFunction && value.type.pointers == 0 && value.bits != 0 {
        value.binding = interpreter_function_result(invocation, value.bits, &value.type, value.start);
        if invocation.state.failed { return; }
        value.kind = KFunctionReference;
        value.constant = false;
        value.bits = 0;
    }
}

fn sem_evaluation_dispose(c: SemanticContext*): void {
    var index: usize = 0;
    while index < c.evaluation_jobs.length {
        var result = bits(SemanticEvaluation*, c.evaluation_jobs.data[index]);
        interpreter_invocation_dispose(&result.invocation);
        vector_dispose(&result.aliases);
        vector_dispose(&result.leaves);
        index++;
    }
    vector_dispose(void*, &c.evaluation_jobs);
}

import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_evaluation;
import semantic_control;
import semantic_types;
import semantic_support;
import semantic_expressions;
import semantic_expression_lowering;
import semantic_aggregates;
import interpreter_context_types;
import .library.vector;

extern fn ix_load(m: IMExecution*, address: u64, type: FoundationType*, offset: usize): u64;

var EvaluationRootProjection: usize = ~convert(usize, 0);
struct SemanticEvaluationLeaf {
    subject: void*;
    field: void*;
    parent: usize;
    index: usize;
    type: FoundationType;
    byte_offset: usize;
}

// A pending aggregate is a tree of ordinary field initializers. Only scalar
// leaves are shared between consuming lowering jobs and the staged producer;
// each leaf carries the producer's dependency. No interpreter address or padding
// byte is ever published in the canonical Foundation graph.
fn sem_evaluation_aggregate(c: SemanticContext*, result: SemanticEvaluation*, node: void*, type: FoundationType*, parent: usize): void {
    var value = sem_get(node);
    value.type = *type;
    value.constant = false;
    value.kind = SurfaceInitializer;
    var record = sem_get(type.record);
    var count = type.scalar == SArray ? record.length : record.items.length;
    for(var index: usize = 0; index < count && sem_ok(c); index++) {
        var field = type.scalar == SArray ? null : record.items.data[index];
        var element = field == null ? &record.element : &sem_get(field).type;
        // Declaration inference can discover this result before layout runs.
        // Retain field identity, not an unpublished numeric byte offset.
        var projection: SemanticEvaluationLeaf = default;
        projection.field = field;
        projection.parent = parent;
        projection.index = index;
        projection.type = *element;
        var projection_index = result.leaves.length;
        sem_require(vector_push(&result.leaves, projection));
        var entry = sem_control_node(c, node, KAssign);
        var assignment = sem_get(entry);
        assignment.type = *element;
        assignment.binding = field;
        assignment.index = index;
        if field != null { sem_set_name(assignment, sem_name(sem_get(field))); }
        if semantic_aggregate(element) {
            assignment.value = sem_control_node(c, entry, SurfaceInitializer);
            sem_evaluation_aggregate(c, result, assignment.value, element, projection_index);
        } else {
            assignment.value = sem_surface_constant(c, entry, element, 0);
            var leaf = assignment.value;
            if sem_get(leaf).kind == KConvert { leaf = sem_get(leaf).value; }
            result.leaves.data[projection_index].subject = leaf;
            var dependency = bits(IMDependency*, entity_component_data(entity_component_add(leaf, c.evaluation_ready)));
            sem_require(dependency != null);
            *dependency = default;
            dependency.subject = leaf;
            dependency.source = result.ready;
        }
        sem_push(&value.items, entry);
    }
    c.surface_expressions = true;
}

// Evaluate once into a private root-frame local. The interpreter retains that
// frame only until publication. Returning its address is an implementation detail
// of the staged query, never a public Foundation constant or a guest lifetime rule.
fn sem_evaluation_aggregate_prepare(c: SemanticContext*, result: SemanticEvaluation*): void {
    var function = sem_evaluation_function(c, result);
    var definition = sem_get(function);
    definition.body = sem_control_node(c, function, KBlock);
    var previous = c.current;
    c.current = function;
    var local = sem_aggregate_local(c, definition.body, &result.aggregate_type);
    sem_lift_initialization(c, definition.body, local, result.expression);
    var returned = sem_control_node(c, definition.body, KReturn);
    sem_get(returned).value = sem_get(sem_lift_target(c, definition.body, local)).value;
    sem_lift_append(definition.body, returned);
    c.current = previous;
}

fn sem_evaluation_aggregate_publish(c: SemanticContext*, result: SemanticEvaluation*): void {
    var invocation = &result.invocation;
    var execution: IMExecution = { state: &invocation.state, context: &invocation.context };
    foreach(var &leaf in &result.leaves) {
        var parent_offset = leaf.parent == EvaluationRootProjection ? 0 : result.leaves.data[leaf.parent].byte_offset;
        leaf.byte_offset = parent_offset + (leaf.field == null ? leaf.index * semantic_size(&leaf.type) : sem_get(leaf.field).byte_offset);
        if leaf.subject == null { continue; }
        var value = sem_get(leaf.subject);
        var bits_value = ix_load(&execution, invocation.context.result + convert(u64, leaf.byte_offset), &value.type, value.start);
        if invocation.state.failed { sem_fail(c, result.subject, invocation.context.error.data); return; }
        if value.type.pointers != 0 && bits_value != 0 {
            sem_fail(c, result.subject, "Compile-time aggregate contains a non-relocatable raw pointer");
            return;
        }
        sem_evaluation_value(leaf.subject, invocation, bits_value);
        if invocation.state.failed { sem_fail(c, result.subject, invocation.context.error.data); return; }
    }
}

import tower;
import compiler_kernel;
import semantic_context;
import semantic_program_types;
import semantic_evaluation;
import semantic_control;
import semantic_support;
import semantic_work_ids;
import .library.vector;
import .library.stack;
import .library.work_graph;
import .library.work_pool;

var EvaluationPrepareQuery: u32 = 8;

struct SemanticEvaluationWork {
    kernel: CompilerKernel;
    ticket: WorkTicket;
    context: SemanticContext*;
    evaluation: SemanticEvaluation*;
    stage: void*;
    ordinal: usize;
    count: usize;
    error: vector(u8);
    error_offset: usize;
    query_reads: vector(usize);
    aliases: vector(SemanticEvaluationAlias);
    cloning: bool;
}

// Each stage expression owns its checked semantic tree. Nested stages share
// immutable type/readiness information and integer literal placeholders; their
// hidden producer expressions belong to different jobs. Enum conversions belong
// to the consuming expression and lower around those same pending literals.
fn semantic_evaluation_prepare_kernel(result: SemanticEvaluationWork*): void {
    var context = *result.context;
    var program = *context.program;
    context.program = &program;
    context.editor = null;
    context.entity_stage = result.stage;
    context.query_reads = &result.query_reads;
    context.evaluation_aliases = &result.aliases;
    context.control_reserved = context.control_names;
    context.control_names = null;
    context.count = 0;
    context.node_limit -= result.context.count;
    vector_init(&context.allocations);
    vector_init(&context.lists);
    vector_init(&context.token_text);
    fill(&context.scan, 0, sizeof(stack(void*)));
    vector_init(&program.error);
    context.control_prefix = sem_cat(&context, result.cloning ? "control clone " : "control stage ",
        sem_cat(&context, sem_decimal(&context, convert(u64, result.ordinal)), "."));
    if result.cloning { sem_evaluation_clone_expression(&context, result.evaluation); }
    else { sem_evaluation_prepare(&context, result.evaluation); }
    result.count = context.count;
    result.error = program.error;
    result.error_offset = program.error_offset;
    stack_dispose(&context.scan);
    vector_dispose(&context.token_text);
    foreach(var list in &context.lists) { vector_dispose(bits(vector(void*)*, list)); }
    vector_dispose(&context.lists);
    foreach(var allocation in &context.allocations) { free(allocation); }
    vector_dispose(&context.allocations);
}

fn sem_evaluation_prepare_all(c: SemanticContext*): void {
    sem_evaluation_work_all(c, false);
}

fn sem_evaluation_clone_all(c: SemanticContext*): void {
    sem_evaluation_work_all(c, true);
}

fn sem_evaluation_work_all(c: SemanticContext*, cloning: bool): void {
    if !sem_ok(c) { return; }
    sem_control_names(c);
    var kind: void* = null;
    var query_kind = convert(u32, cloning ? SemanticQuery.KnownClone : SemanticQuery.EvaluationPrepare);
    for(var i: usize = 0; i < c.evaluation_jobs.length; i++) {
        var evaluation = bits(SemanticEvaluation*, c.evaluation_jobs.data[i]);
        if cloning && !evaluation.inferred { continue; }
        if kind == null {
            kind = sem_create(c.program.root);
            sem_require(entity_register(kind, sizeof(SemanticEvaluationWork), alignof(SemanticEvaluationWork), 0));
        }
        var component = entity_component_add(evaluation.subject, kind);
        var result = bits(SemanticEvaluationWork*, entity_component_data(component));
        sem_require(result != null);
        fill(result, 0, sizeof(SemanticEvaluationWork));
        result.context = c;
        result.evaluation = evaluation;
        result.ordinal = i;
        result.cloning = cloning;
        result.kernel.kind = CompilerKernelKind.PrepareEvaluation;
        result.kernel.payload = bits(void*, result);
        var id = work_find(&c.queries, evaluation.subject, query_kind, 0);
        sem_require(id != 0);
        // Disjoint expression output, immutable types and nested placeholders.
        // Evaluation reads component 3 and writes component 2, so the graph
        // also excludes evaluation while a preparation wave owns these inputs.
        var domain = convert(u64, SemanticWorkDomain.Compiler);
        sem_require(work_access(&c.queries, id, domain, convert(u64, SemanticAccess.Expression), i, 1, WorkAccessMode.Write));
        sem_require(work_access(&c.queries, id, domain, convert(u64, SemanticAccess.Layout), 0, ~convert(usize, 0), WorkAccessMode.Read));
        sem_require(work_access(&c.queries, id, domain, convert(u64, SemanticAccess.Evaluation), 0, ~convert(usize, 0), WorkAccessMode.Read));
        sem_require(work_access(&c.queries, id, domain, convert(u64, SemanticAccess.KnownBinding), 0, ~convert(usize, 0), WorkAccessMode.Read));
        sem_require(work_access(&c.queries, id, domain, convert(u64, SemanticAccess.Body), 0, ~convert(usize, 0), WorkAccessMode.Read));
        sem_require(work_access(&c.queries, id, domain,
            convert(u64, SemanticAccess.Aggregate), 0, ~convert(usize, 0), WorkAccessMode.Read));
        sem_require(work_seal(&c.queries, id));
        sem_require(work_demand(&c.queries, id));
    }
    if kind == null { return; }
    if c.workers.count == 0 { sem_require(sem_workers_open(c)); }
    var batch: vector(SemanticEvaluationWork*) = default;
    defer vector_dispose(&batch);
    sem_require(vector_reserve(&batch, SemanticPreparationWindow));
    while sem_ok(c) {
        var count: usize = 0;
        var ticket: WorkTicket;
        while count < SemanticPreparationWindow && work_take_query(&c.queries, &ticket, query_kind) {
            var subject = work_task(&c.queries, ticket.task).subject;
            var result = bits(SemanticEvaluationWork*, entity_component_data(entity_component_get(subject, kind)));
            result.ticket = ticket;
            result.stage = entity_stage_open(c.program.root);
            sem_require(result.stage != null);
            sem_require(entity_stage_lease(result.stage, result.evaluation.subject));
            if result.evaluation.function != null {
                sem_require(entity_stage_lease(result.stage, result.evaluation.function));
            }
            batch.data[count] = result;
            count++;
        }
        if count == 0 { break; }
        var view = entity_view_open(c.program.root);
        sem_require(view != null);
        var context = *c;
        var next: usize = 0;
        while next < count || c.workers.running != 0 {
            while next < count && c.workers.running < c.workers.count {
                var result = batch.data[next++];
                result.context = &context;
                sem_require(work_pool_submit(&c.workers, bits(void*, &result.kernel)));
            }
            sem_require(work_pool_receive(&c.workers, true) != null);
        }
        entity_view_close(view);
        for(var i: usize = 0; i < count; i++) {
            var result = batch.data[i];
            // Failed preparations can still own generated nodes. Publish after
            // every worker joins so normal program cleanup owns all references.
            sem_require(entity_stage_publish(result.stage));
            result.stage = null;
            result.context = null;
        }
        for(var i: usize = 0; i < count; i++) {
            var result = batch.data[i];
            sem_query_observe(c, &result.ticket, &result.query_reads);
            sem_evaluation_aliases(c, &result.aliases);
            c.count += result.count;
            if result.error.length != 0 && sem_ok(c) {
                sem_require(vector_reserve(&c.program.error, result.error.length + 1));
                copy(c.program.error.data, result.error.data, result.error.length + 1);
                c.program.error.length = result.error.length;
                c.program.error_offset = result.error_offset;
            }
            if c.count > c.node_limit { sem_fail(c, result.evaluation.subject, "Foundation component memory budget exceeded"); }
            sem_require(work_finish(&c.queries, &result.ticket, result.error.length == 0 && c.count <= c.node_limit));
            vector_dispose(&result.error);
            vector_dispose(&result.query_reads);
            vector_dispose(&result.aliases);
        }
    }
    foreach(var job in &c.evaluation_jobs) {
        var evaluation = bits(SemanticEvaluation*, job);
        var data = entity_component_data(entity_component_get(evaluation.subject, kind));
        if data != null { bits(SemanticEvaluationWork*, data).context = null; }
    }
}

import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_control;
import semantic_definitions;
import semantic_expressions;
import semantic_support;
import semantic_types;
import .library.vector;
import semantic_lowering_work;
import semantic_aggregates;
import semantic_known_bindings;
import semantic_evaluation;
import .library.float_bits;

// Expressions are normalized on the shared ECS entities into ordinary bound
// locals, calls, loads/stores and control flow. No backend sees surface tags.
fn sem_lift_append(block: void*, n: void*): void {
    var owner = sem_get(block);
    var value = sem_get(n);
    if value != null && value.kind == KLabel {
        // Expression lifting can insert several statements before a label.
        // Keep the derived jump position aligned with the canonical block.
        value.body = block;
        value.index = owner.items.length;
    }
    sem_push(&owner.items, n);
}

fn sem_lift_result(source: void*, result: void*): void* {
    // Keep the source entity useful to reflection after normalization. Its
    // syntax children/provenance remain; its semantic value is the bound result.
    var value = sem_get(source);
    var read = sem_get(result);
    value.kind = read.kind;
    value.binding = read.binding;
    value.constant = read.constant;
    value.bits = read.bits;
    value.op = read.op;
    value.left = null;
    value.right = null;
    value.value = null;
    value.target = null;
    sem_set_type(&value.type, &read.type);
    return result;
}

fn sem_lift_snapshot(c: SemanticContext*, block: void*, n: void*): void* {
    var value = sem_get(n);
    if value.constant {
        return n;
    }
    if value.kind == KString {
        return n;
    }
    var local = sem_control_local(c, block, n);
    return sem_control_read(c, block, local);
}

fn sem_lift_binary(c: SemanticContext*, block: void*, op: u32, left: void*, right: void*, type: FoundationType*): void* {
    var entity = sem_control_node(c, block, KBinary);
    var value = sem_get(entity);
    value.op = op;
    value.left = left;
    value.right = right;
    sem_set_type(&value.type, type);
    return sem_lift_snapshot(c, block, entity);
}

fn sem_lift_store(c: SemanticContext*, block: void*, target: void*, value: void*): void {
    var entity = sem_control_node(c, block, KAssign);
    var assignment = sem_get(entity);
    assignment.target = target;
    assignment.value = value;
    sem_lift_append(block, entity);
}

fn sem_lift_place(c: SemanticContext*, block: void*, n: void*): void* {
    var value = sem_get(n);
    if semantic_aggregate(&value.type) && value.kind != KOperand && value.kind != KLoad
        && value.kind != KField && value.kind != KIndex {
        return sem_lift_value(c, block, n);
    }
    if value.kind == KLoad {
        value.value = sem_lift_value(c, block, value.value);
        return n;
    }
    var field = value.kind == KField;
    var index = value.kind == KIndex;
    var projection = field;
    if index {
        projection = true;
    }
    if projection {
        if value.indirect {
            value.left = sem_lift_value(c, block, value.left);
        }
        else {
            value.left = sem_lift_place(c, block, value.left);
            var base = sem_get(value.left);
            if base.kind == KLoad {
                // Foundation field paths already dereference a struct pointer.
                // An array dereference needs an explicit element pointer so its
                // indexed spelling reconstructs the same element type/stride.
                value.left = base.value;
                if index {
                    var pointer = sem_control_node(c, block, KBits);
                    var cast = sem_get(pointer);
                    cast.value = value.left;
                    sem_set_type(&cast.type, &value.type);
                    cast.type.pointers++;
                    value.left = sem_lift_snapshot(c, block, pointer);
                }
                value.indirect = true;
            }
        }
        if index {
            value.right = sem_lift_value(c, block, value.right);
        }
    }
    return n;
}

fn sem_lift_target(c: SemanticContext*, block: void*, n: void*): void* {
    n = sem_lift_place(c, block, n);
    var source = sem_get(n);
    if source.kind == KLoad {
        return n;
    }
    var address = sem_control_node(c, block, KAddress);
    var pointer = sem_get(address);
    pointer.value = n;
    sem_set_type(&pointer.type, &source.type);
    pointer.type.pointers++;
    var saved = sem_lift_snapshot(c, block, address);
    var target = sem_control_node(c, block, KLoad);
    var load = sem_get(target);
    load.value = saved;
    sem_set_type(&load.type, &source.type);
    return target;
}

// Total shifts: counts are masked by (width - 1), signed right shift extends
// the sign, left shift wraps. This portable expansion uses Foundation integers;
// LLVM's existing optimization may recognize it, but no machine-code claim is made.
fn sem_lift_shift(c: SemanticContext*, block: void*, left: void*, right: void*, operation: u32): void* {
    var input = sem_get(left);
    var backwards = operation != SurfaceShiftLeft;
    if operation == SurfaceShiftUnsigned && semantic_signed(&input.type) {
        var original = &input.type;
        var type = sem_type_copy(c, original);
        type.scalar = semantic_unsigned_scalar(original.scalar);
        var converted = sem_control_node(c, block, KBits);
        sem_get(converted).value = left;
        sem_set_type(&sem_get(converted).type, type);
        var shifted = sem_lift_shift(c, block, sem_lift_snapshot(c, block, converted), right, SurfaceShiftRight);
        var result = sem_control_node(c, block, KBits);
        sem_get(result).value = shifted;
        sem_set_type(&sem_get(result).type, original);
        return sem_lift_snapshot(c, block, result);
    }
    var count_type = sem_get(right);
    var width = semantic_size(&input.type) *8;
    var mask = convert(u64, width) -1;
    var count_mask = sem_surface_constant(c, block, &count_type.type, mask);
    var count = sem_lift_binary(c, block, OAnd, right, count_mask, &count_type.type);
    var remaining = sem_control_local(c, block, count);
    var result = sem_control_local(c, block, left);
    var loop_node = sem_control_node(c, block, KLoop);
    var loop_value = sem_get(loop_node);
    var body = sem_control_node(c, loop_node, KBlock);
    loop_value.body = body;
    sem_lift_append(block, loop_node);
    var zero = sem_surface_constant(c, body, &count_type.type, 0);
    var current_count = sem_control_read(c, body, remaining);
    var boolean = sem_type_new(c, SBool, 0, null);
    var finished = sem_lift_binary(c, body, OEq, current_count, zero, boolean);
    var stop = sem_control_node(c, body, KBlock);
    sem_lift_append(stop, sem_control_node(c, stop, KBreak));
    sem_control_branch(c, body, finished, stop);
    var current = sem_control_read(c, body, result);
    var two = sem_surface_constant(c, body, &input.type, 2);
    var op = OMul;
    if backwards {
        op = ODiv;
    }
    var next = sem_lift_binary(c, body, op, current, two, &input.type);
    if backwards {
        if semantic_signed(&input.type) {
            // Truncating division differs from arithmetic shift for negative odd values.
            var one = sem_surface_constant(c, body, &input.type, 1);
            var low = sem_lift_binary(c, body, OAnd, current, one, &input.type);
            var negative = sem_lift_binary(c, body, OLt, current,
            sem_surface_constant(c, body, &input.type, 0), boolean);
            var adjusted = sem_control_local(c, body, next);
            var correction = sem_control_node(c, body, KBlock);
            var rounded = sem_lift_binary(c, correction, OSub, next, low, &input.type);
            sem_lift_store(c, correction, sem_control_read(c, correction, adjusted), rounded);
            sem_control_branch(c, body, negative, correction);
            next = sem_control_read(c, body, adjusted);
        }
    }
    sem_lift_store(c, body, sem_control_read(c, body, result), next);
    var one_count = sem_surface_constant(c, body, &count_type.type, 1);
    var next_count = sem_lift_binary(c, body, OSub, current_count, one_count, &count_type.type);
    sem_lift_store(c, body, sem_control_read(c, body, remaining), next_count);
    return sem_control_read(c, block, result);
}

fn sem_lift_nonnull(c: SemanticContext*, block: void*, value: void*): void* {
    var zero = sem_surface_constant(c, block, &sem_get(value).type, 0);
    return sem_lift_binary(c, block, ONe, value, zero, sem_type_new(c, SBool, 0, null));
}

// Follow a null-conditional chain inside nested success blocks. Index operands
// and later receivers are evaluated only after the preceding guard succeeds.
// Intermediate struct fields remain places, so no aggregate copy is introduced.
fn sem_lift_guarded_path(c: SemanticContext*, selected: void**, n: void*): void* {
    var value = sem_get(n);
    if !sem_surface_optional(value) {
        return sem_lift_value(c, *selected, n);
    }
    var indexed = value.kind == SurfaceNullIndex;
    var left = sem_lift_guarded_path(c, selected, value.left);
    if sem_get(left).type.pointers != 0 {
        left = sem_lift_value(c, *selected, left);
    }
    if value.op != 0 {
        var present = sem_lift_nonnull(c, *selected, left);
        var yes = sem_control_node(c, *selected, KBlock);
        sem_control_branch(c, *selected, present, yes);
        *selected = yes;
    }
    value.kind = KField;
    if indexed {
        value.kind = KIndex;
    }
    value.op = 0;
    value.left = left;
    if indexed {
        value.right = sem_lift_value(c, *selected, value.right);
    }
    var projection = sem_control_node(c, *selected, value.kind);
    var data = sem_get(projection);
    data.left = value.left;
    data.right = value.right;
    data.binding = value.binding;
    data.indirect = value.indirect;
    data.byte_offset = value.byte_offset;
    sem_set_name(data, sem_name(value));
    sem_set_type(&data.type, &value.type);
    return projection;
}

fn sem_lift_coalesce(c: SemanticContext*, block: void*, left: void*, right: void*, target: void*): void* {
    var type = &sem_get(left).type;
    var result = sem_control_local(c, block, sem_surface_constant(c, block, type, 0));
    var boolean = sem_type_new(c, SBool, 0, null);
    var found = sem_control_local(c, block, sem_surface_constant(c, block, boolean, 0));
    var selected = block;
    var first = sem_lift_guarded_path(c, &selected, left);
    first = sem_lift_value(c, selected, first);
    if type.pointers != 0 || type.scalar == SFunction {
        var present = sem_lift_nonnull(c, selected, first);
        var yes = sem_control_node(c, selected, KBlock);
        sem_control_branch(c, selected, present, yes);
        selected = yes;
    }
    sem_lift_store(c, selected, sem_control_read(c, selected, result), first);
    sem_lift_store(c, selected, sem_control_read(c, selected, found), sem_surface_constant(c, selected, boolean, 1));
    var missing = sem_lift_binary(c, block, OEq, sem_control_read(c, block, found),
    sem_surface_constant(c, block, boolean, 0), boolean);
    var fallback = sem_control_node(c, block, KBlock);
    sem_control_branch(c, block, missing, fallback);
    var second = sem_lift_value(c, fallback, right);
    sem_lift_store(c, fallback, sem_control_read(c, fallback, result), second);
    if target != null {
        sem_lift_store(c, fallback, target, second);
    }
    return sem_control_read(c, block, result);
}

fn sem_lift_logical(c: SemanticContext*, block: void*, left: void*, right: void*, operation: u32, target: void*): void* {
    var first = sem_lift_value(c, block, left);
    var result = sem_control_local(c, block, first);
    var yes = sem_control_node(c, block, KBlock);
    var no = sem_control_branch(c, block, first, yes);
    var chosen = yes;
    if operation == SurfaceOr {
        chosen = no;
    }
    var second = sem_lift_value(c, chosen, right);
    sem_lift_store(c, chosen, sem_control_read(c, chosen, result), second);
    if target != null {
        sem_lift_store(c, chosen, target, second);
    }
    return sem_control_read(c, block, result);
}

// The ordinary fill operation defines byte initialization, including padding.
// Capture a destination once; sizeof consumes its explicit target layout.
fn sem_lift_default(c: SemanticContext*, block: void*, target: void*): void* {
    target = sem_lift_target(c, block, target);
    var type = &sem_get(target).type;
    var count = sem_control_node(c, block, KSizeOf);
    sem_set_type(&sem_get(count).element, type);
    sem_set_type(&sem_get(count).type, sem_type_new(c, SUSize, 0, null));
    var result = sem_control_node(c, block, KFill);
    var value = sem_get(result);
    value.left = sem_get(target).value;
    value.right = sem_surface_constant(c, result, sem_type_new(c, SU8, 0, null), 0);
    value.value = sem_lift_value(c, block, count);
    sem_set_type(&value.type, sem_type_new(c, SVoid, 0, null));
    sem_lift_append(block, result);
    return result;
}

// Lower construction into the existing destination. Field stores stay ordered;
// explicit ..default establishes zero storage before those writes. A field's
// source node becomes its ordinary bound assignment, retaining provenance.
fn sem_lift_initialization(c: SemanticContext*, block: void*, target: void*, n: void*): void {
    var initial = sem_get(n);
    if initial.kind != SurfaceDefault && initial.kind != SurfaceInitializer {
        target = sem_lift_target(c, block, target);
        var source = sem_lift_value(c, block, n);
        sem_aggregate_copy(c, block, target, source);
        return;
    }
    if initial.kind == SurfaceDefault {
        sem_lift_default(c, block, target);
    } else {
        target = sem_lift_target(c, block, target);
        if initial.op != 0 { sem_lift_default(c, block, target); }
        foreach(var entry in &initial.items) {
            var field = sem_get(entry);
            var array = initial.type.scalar == SArray;
            var place = sem_control_node(c, entry, array ? KIndex : KField);
            var location = sem_get(place);
            location.left = sem_get(target).value;
            location.indirect = true;
            location.binding = field.binding;
            if array {
                var cast = sem_control_node(c, entry, KBits);
                sem_get(cast).value = location.left;
                sem_get(cast).type = field.type;
                sem_get(cast).type.pointers++;
                location.left = sem_lift_snapshot(c, block, cast);
                location.right = sem_surface_constant(c, entry, sem_type_new(c, SUSize, 0, null), convert(u64, field.index));
            } else { location.byte_offset = sem_get(field.binding).byte_offset; }
            sem_set_name(location, sem_name(field));
            sem_set_type(&location.type, &field.type);
            if semantic_aggregate(&field.type) {
                sem_lift_initialization(c, block, place, field.value);
                field.kind = KBlock;
                field.value = null;
                sem_set_type(&field.type, sem_type_new(c, SVoid, 0, null));
            } else {
                field.target = sem_lift_target(c, block, place);
                field.value = sem_lift_value(c, block, field.value);
                field.binding = null;
                sem_set_name(field, "");
                sem_set_type(&field.type, sem_type_new(c, SVoid, 0, null));
                sem_lift_append(block, entry);
            }
        }
    }
    initial.items.length = 0;
    initial.op = 0;
    initial.kind = KBlock;
    sem_set_type(&initial.type, sem_type_new(c, SVoid, 0, null));
}

fn sem_lift_value(c: SemanticContext*, block: void*, n: void*): void* {
    var absent = n == null;
    if absent {
        return null;
    }
    var value = sem_get(n);
    if value.constant {
        return n;
    }
    // A nested staged enum exposes a conversion around its pending integer
    // literal. The producer owns that conversion, including its component lease.
    // Lower a consumer-owned projection while sharing the immutable/readiness-
    // tracked literal; never rewrite the producer from another worker.
    if value.kind == KConvert && sem_evaluation_dependency(c, n) != null {
        var projection = sem_control_node(c, block, KConvert);
        var local = sem_get(projection);
        sem_set_type(&local.type, &value.type);
        local.value = value.value;
        n = projection;
        value = local;
    }
    if semantic_aggregate(&value.type) {
        return sem_aggregate_value(c, block, n);
    }
    if value.kind == SurfaceInitializerStore {
        sem_lift_initialization(c, block, value.target, value.value);
        value.kind = KBlock;
        value.target = null;
        value.value = null;
        return n;
    }
    if value.kind == SurfaceDefaultStore {
        var result = sem_lift_default(c, block, value.target);
        value.kind = KBlock;
        value.target = null;
        value.value = null;
        return result;
    }
    if sem_surface_optional(value) {
        var absent = sem_surface_constant(c, block, &value.type, 0);
        return sem_lift_result(n, sem_lift_coalesce(c, block, n, absent, null));
    }
    if value.kind == SurfaceCoalesce {
        return sem_lift_result(n, sem_lift_coalesce(c, block, value.left, value.right, null));
    }
    if value.kind == SurfaceComma {
        sem_lift_value(c, block, value.left);
        return sem_lift_result(n, sem_lift_value(c, block, value.right));
    }
    var select = value.kind == SurfaceSelect;
    var logical_and = value.kind == SurfaceAnd;
    var logical_or = value.kind == SurfaceOr;
    if logical_and || logical_or {
        return sem_lift_result(n, sem_lift_logical(c, block, value.left, value.right, value.kind, null));
    }
    if select {
        var condition = sem_lift_value(c, block, value.value);
        if value.type.scalar == SVoid && value.type.pointers == 0 {
            var yes = sem_control_node(c, block, KBlock);
            var no = sem_control_branch(c, block, condition, yes);
            sem_lift_value(c, yes, value.left);
            sem_lift_value(c, no, value.right);
            value.kind = KBlock;
            value.left = null;
            value.right = null;
            value.value = null;
            return n;
        }
        var initial = sem_surface_constant(c, block, &value.type, 0);
        var result = sem_control_local(c, block, initial);
        var yes = sem_control_node(c, block, KBlock);
        var no = sem_control_branch(c, block, condition, yes);
        var left = sem_lift_value(c, yes, value.left);
        sem_lift_store(c, yes, sem_control_read(c, yes, result), left);
        var right = sem_lift_value(c, no, value.right);
        sem_lift_store(c, no, sem_control_read(c, no, result), right);
        return sem_lift_result(n, sem_control_read(c, block, result));
    }
    var assign = value.kind == SurfaceAssign;
    var modify = value.kind == SurfaceModify;
    var writes = assign;
    if modify {
        writes = true;
    }
    if writes {
        var target = sem_lift_target(c, block, value.target);
        var previous: void* = null;
        var compound = value.op != SurfaceSet;
        if compound {
            previous = sem_lift_snapshot(c, block, target);
        }
        if value.op == SurfaceCoalesce {
            return sem_lift_result(n, sem_lift_coalesce(c, block, previous, value.value, target));
        }
        if value.op == SurfaceAnd || value.op == SurfaceOr {
            return sem_lift_result(n, sem_lift_logical(c, block, previous, value.value, value.op, target));
        }
        var next: void* = null;
        if modify {
            var type = &value.type;
            if type.pointers != 0 {
                type = sem_type_new(c, SUSize, 0, null);
            }
            next = sem_surface_constant(c, block, type, 1);
              if semantic_float(type) {
                  sem_get(next).bits = tower_float_from_integer(1, Float32Width, false, semantic_width(type));
              }
        } else {
            next = sem_lift_value(c, block, value.value);
        }
        if compound {
            var shift = value.op >= SurfaceShiftLeft && value.op <= SurfaceShiftUnsigned;
            if shift {
                next = sem_lift_shift(c, block, previous, next, value.op);
            }
            else {
                next = sem_lift_binary(c, block, value.op, previous, next, &value.type);
            }
        }
        sem_lift_store(c, block, target, next);
        if modify {
            if value.indirect {
                return sem_lift_result(n, previous);
            }
        }
        return sem_lift_result(n, next);
    }
    var shift = value.kind == SurfaceShift;
    var threeway = value.kind == SurfaceCompare;
    var binary = value.kind == KBinary;
    var pair = binary;
    if shift {
        pair = true;
    }
    if threeway {
        pair = true;
    }
    if pair {
        value.left = sem_lift_value(c, block, value.left);
        value.right = sem_lift_value(c, block, value.right);
        if shift {
            return sem_lift_result(n, sem_lift_shift(c, block, value.left, value.right, value.op));
        }
        if threeway {
            var boolean = sem_type_new(c, SBool, 0, null);
            var less = sem_lift_binary(c, block, OLt, value.left, value.right, boolean);
            var more = sem_lift_binary(c, block, OGt, value.left, value.right, boolean);
            var low = sem_control_node(c, block, KConvert);
            var a = sem_get(low);
            a.value = less;
            sem_set_type(&a.type, &value.type);
            low = sem_lift_snapshot(c, block, low);
            var high = sem_control_node(c, block, KConvert);
            var b = sem_get(high);
            b.value = more;
            sem_set_type(&b.type, &value.type);
            high = sem_lift_snapshot(c, block, high);
            return sem_lift_result(n, sem_lift_binary(c, block, OSub, high, low, &value.type));
        }
        return sem_lift_snapshot(c, block, n);
    }
    if value.kind == KAddress {
        value.value = sem_lift_place(c, block, value.value);
        var location = sem_get(value.value);
        if location.kind == KLoad {
            return location.value;
        }
    }
    else {
        var location = value.kind == KField;
        location ||= value.kind == KIndex;
        if location {
            sem_lift_place(c, block, n);
        }
        else {
            value.left = sem_lift_value(c, block, value.left);
            value.right = sem_lift_value(c, block, value.right);
            value.value = sem_lift_value(c, block, value.value);
        }
    }
    if value.kind == KCall {
        sem_aggregate_arguments(c, block, n);
    }
    var discarded = value.type.pointers == 0;
    discarded &&= value.type.scalar == SVoid;
    if discarded {
        sem_lift_append(block, n);
        return n;
    }
    return sem_lift_snapshot(c, block, n);
}

fn sem_lift_block(c: SemanticContext*, block: void*): void {
    var value = sem_get(block);
    var source = sem_list(c);
    var index: usize = 0;
    for(; index != value.items.length; index++) {
        sem_push(source, value.items.data[index]);
    }
    value.items.length = 0;
    index = 0;
    loop {
        if index == source.length {
            return;
        }
        var n = source.data[index];
        index++;
        var statement = sem_get(n);
        if statement == null {
            sem_lift_append(block, n);
            continue;
        }
        if statement.kind == SurfaceDiscard {
            sem_lift_value(c, block, statement.value);
            statement.kind = KBlock;
            statement.value = null;
            continue;
        }
        if statement.kind == KBlock {
            sem_lift_block(c, n);
        }
        if statement.kind == KLoop {
            sem_lift_block(c, statement.body);
        }
        if statement.kind == KIf {
            statement.value = sem_lift_value(c, block, statement.value);
            sem_lift_block(c, statement.body);
            var otherwise = statement.otherwise != null;
            if otherwise {
                sem_lift_block(c, statement.otherwise);
            }
        }
        var declaration = statement.kind == KDeclare;
        var known = declaration ? sem_known_binding(c, n) : null;
        if known != null && known.evaluation != null {
            known.block = block;
            known.begin = value.items.length;
        }
        if declaration && statement.value != null && semantic_aggregate(&statement.type) {
            var initial = statement.value;
            statement.value = null;
            sem_lift_append(block, n);
            sem_lift_initialization(c, block, sem_control_read(c, n, n), initial);
            continue;
        }
        var assignment = statement.kind == KAssign;
        var returned = statement.kind == KReturn;
        if assignment && semantic_aggregate(&sem_get(statement.target).type) {
            sem_lift_initialization(c, block, statement.target, statement.value);
            statement.kind = KBlock;
            statement.target = null;
            statement.value = null;
            continue;
        }
        if returned && statement.value != null && semantic_aggregate(&sem_get(statement.value).type) {
            var signature = sem_aggregate_signature(c, c.current);
            sem_require(signature != null && signature.result_parameter != null);
            var source = sem_lift_value(c, block, statement.value);
            var destination = sem_control_read(c, block, signature.result_parameter);
            var from = sem_get(sem_lift_target(c, block, source)).value;
            sem_aggregate_transfer(c, block, destination, from, &signature.result_type);
            statement.value = null;
        }
        if assignment {
            statement.target = sem_lift_target(c, block, statement.target);
        }
        var initializer = declaration;
        if assignment {
            initializer = true;
        }
        if returned {
            initializer = true;
        }
        if initializer {
            statement.value = sem_lift_value(c, block, statement.value);
        }
        var call = statement.kind == KCall;
        call ||= statement.kind == KPrint;
        call ||= statement.kind == KFree;
        call ||= statement.kind == KCopy;
        call ||= statement.kind == KFill;
        if call {
            sem_lift_value(c, block, n);
        }
        else {
            sem_lift_append(block, n);
        }
        if known != null && known.evaluation != null { known.end = value.items.length; }
    }
}

fn sem_lower_expressions(c: SemanticContext*): void {
    sem_aggregate_prepare(c);
    sem_lower_parallel(c);
}

import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_control;
import semantic_definitions;
import semantic_support;
import semantic_types;
import semantic_layout;
import semantic_values;

// Transient surface classifications on the same entities. These are eliminated
// before publishing a Foundation graph; they have no interpreter/cache encoding.
var SurfaceSelect: u32 = 100;
var SurfaceAnd: u32 = 101;
var SurfaceOr: u32 = 102;
var SurfaceAssign: u32 = 103;
var SurfaceModify: u32 = 104;
var SurfaceComma: u32 = 105;
var SurfaceShift: u32 = 106;
var SurfaceCompare: u32 = 107;
var SurfaceDiscard: u32 = 108;
var SurfaceCoalesce: u32 = 109;
var SurfaceNullField: u32 = 110;
var SurfaceNullIndex: u32 = 111;
var SurfaceDefault: u32 = 112;
var SurfaceDefaultStore: u32 = 113;
var SurfaceInitializer: u32 = 114;
var SurfaceInitializerStore: u32 = 115;
var SurfaceShiftLeft: u32 = 14;
var SurfaceShiftRight: u32 = 15;
var SurfaceShiftUnsigned: u32 = 16;
var SurfaceSet: u32 = 4294967295;
var SurfaceFirstDigit: u8 = 48;
var SurfaceLastDigit: u8 = 57;

fn sem_surface_unwrap(n: void*): void* {
    loop {
        var wrapper = sem_is(n, "TowerExpression");
        wrapper ||= sem_is(n, "TowerComma");
        wrapper ||= sem_is(n, "CoreOperand");
        wrapper ||= sem_is(n, "CoreCallArgument");
        wrapper ||= sem_is(n, "CoreValue");
        wrapper ||= sem_is(n, "CoreMetadataOperand");
        if !wrapper {
            return n;
        }
        if sem_child_count(n) == 1 {
            n = sem_child(n, 0);
        }
        else {
            var group = sem_member(n, "value");
            if group != null {
                n = group;
            } else {
                return n;
            }
        }
    }
}

fn sem_surface_expected(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    if !sem_ok(c) {
        return n;
    }
    var value = sem_get(n);
    if value == null {
        return n;
    }
    if expected_type != null {
        if !semantic_type_equal(&value.type, expected_type) {
            sem_fail(c, n, sem_cat(c, "Expected ", sem_cat(c, sem_type_name(c, expected_type),
            sem_cat(c, ", got ", sem_type_name(c, &value.type)))));
        }
    }
    return n;
}

// Aggregate defaults initialize destination storage, including value temporaries.
fn sem_default(c: SemanticContext*, n: void*, expected_type: FoundationType*, destination: bool): void* {
    var value = sem_node(c, n, KOperand);
    var type = expected_type;
    var annotation = sem_member(n, "type");
    if annotation != null { type = sem_type(c, annotation); }
    if !sem_ok(c) { return n; }
    if type == null {
        sem_fail(c, n, "default requires a target type or an explicit default(Type)");
        return n;
    }
    sem_set_type(&value.type, type);
    if type.pointers == 0 && type.scalar == SVoid {
        sem_fail(c, n, "default requires a non-void type");
        return n;
    }
    if semantic_aggregate(type) {
        if !destination {
            sem_fail(c, n, "Aggregate default requires a complete declaration initializer or reset destination");
            return n;
        }
        value.kind = SurfaceDefault;
        c.surface_expressions = true;
    } else {
        if type.pointers == 0 && semantic_enum(type) {
            // Zero need not name an enum member. Preserve its ordinary compilable
            // conversion spelling instead of creating an unnamed enum constant.
            var underlying = sem_type_copy(c, type);
            underlying.record = null;
            value.kind = KConvert;
            value.value = sem_surface_constant(c, n, underlying, 0);
            c.surface_expressions = true;
        } else {
            value.constant = true;
            value.bits = 0;
        }
    }
    return sem_surface_expected(c, n, expected_type);
}

// Construction checking is independent of storage lowering. The initializer's
// ordered field nodes bind the same declarations used by ordinary field access.
// Stronger source policies can inspect completeness/default coverage here, and
// analyze the resulting ordinary stores without changing Foundation semantics.
fn sem_named_initialization(c: SemanticContext*, n: void*, expected_type: FoundationType*, destination: bool): void* {
    var initial = sem_node(c, n, SurfaceInitializer);
    var type = expected_type;
    var annotation = sem_member(n, "type");
    if annotation != null { type = sem_type(c, annotation); }
    if !sem_ok(c) { return n; }
    if type == null {
        sem_fail(c, n, "Named initialization requires a target type or init(Type)");
        return n;
    }
    sem_set_type(&initial.type, type);
    if type.pointers != 0 || type.scalar != SStruct || semantic_enum(type) {
        sem_fail(c, n, "Named initialization requires a struct type");
        return n;
    }
    sem_surface_expected(c, n, expected_type);
    if !sem_ok(c) { return n; }
    if !destination {
        sem_fail(c, n, "Named initialization requires a complete declaration initializer or reset destination");
        return n;
    }
    sem_layout(c, type.record);
    if !sem_ok(c) { return n; }
    var fields = &sem_get(type.record).items;
    var supplied = sem_table(c);
    var entries = sem_collect(c, sem_member(n, "fields"), "TowerInitializerEntry");
    for(var i: usize = 0; i < entries.length && sem_ok(c); i++) {
        var entry = sem_child(entries.data[i], 0);
        if sem_is(entry, "TowerInitializerDefault") {
            if initial.op != 0 || i + 1 != entries.length {
                sem_fail(c, entry, "The ..default initializer must occur once, at the end");
            }
            initial.op = 1;
            continue;
        }
        var field = sem_node(c, entry, KAssign);
        var name = sem_identifier(c, sem_member(entry, "name"));
        sem_set_name(field, name);
        foreach(var declaration in fields) {
            if sem_equal(name, sem_name(sem_get(declaration))) { field.binding = declaration; }
        }
        if field.binding == null {
            sem_fail(c, entry, sem_cat(c, "Unknown initializer field '", sem_cat(c, name, "'")));
            break;
        }
        if !sem_put(c, supplied, name, entry) {
            sem_fail(c, entry, sem_cat(c, "Duplicate initializer field '", sem_cat(c, name, "'")));
            break;
        }
        sem_set_type(&field.type, &sem_get(field.binding).type);
        field.value = sem_initial_value(c, sem_member(entry, "value"), &field.type);
        sem_push(&initial.items, entry);
    }
    if sem_ok(c) && initial.op == 0 {
        foreach(var declaration in fields) {
            var name = sem_name(sem_get(declaration));
            if sem_lookup_table(supplied, name) == null {
                sem_fail(c, n, sem_cat(c, "Missing initializer field '", sem_cat(c, name, "'; provide it or use ..default")));
                break;
            }
        }
    }
    c.surface_expressions = true;
    return n;
}

fn sem_initial_value(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    var source = sem_surface_unwrap(n);
    if sem_is(source, "TowerDefault") { return sem_default(c, source, expected_type, true); }
    if sem_is(source, "TowerInitializer") {
        if c.value_depth >= 128 {
            sem_fail(c, source, "Foundation expression nesting limit is 128");
            return source;
        }
        c.value_depth++;
        var result = sem_named_initialization(c, source, expected_type, true);
        c.value_depth--;
        return result;
    }
    return sem_expression(c, n, expected_type);
}

fn sem_surface_integer(c: SemanticContext*, n: void*): bool {
    var value = sem_get(n);
    var ok = semantic_integer(&value.type);
    if ok {
        if semantic_enum(&value.type) {
            ok = false;
        }
    }
    if !ok {
        sem_fail(c, n, "This operation requires integer operands");
    }
    return ok;
}

fn sem_surface_constant(c: SemanticContext*, parent: void*, type: FoundationType*, bits_value: u64): void* {
    var n = sem_control_node(c, parent, KOperand);
    var value = sem_get(n);
    sem_set_type(&value.type, type);
    if type.pointers == 0 && semantic_enum(type) {
        // Internal zero temporaries need not name a member. Use the same
        // ordinary Foundation conversion as an enum default initializer.
        var underlying = sem_type_copy(c, type);
        underlying.record = null;
        value.kind = KConvert;
        value.value = sem_surface_constant(c, n, underlying, bits_value);
    } else {
        value.constant = true;
        value.bits = bits_value;
    }
    return n;
}

fn sem_surface_pointee(c: SemanticContext*, n: void*, pointer: FoundationType*): void {
    var element = sem_type_copy(c, pointer);
    element.pointers--;
    // Pointee layout is an execution/lowering input, not an inference input.
    if !semantic_aggregate(element) && semantic_size(element) == 0 {
        sem_fail(c, n, "Cannot offset a void pointer");
    }
}

fn sem_surface_optional(value: FoundationNode*): bool {
    return value.kind == SurfaceNullField || value.kind == SurfaceNullIndex;
}

fn sem_surface_nullable(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    if c.value_depth > 128 {
        sem_fail(c, n, "Foundation expression nesting limit is 128");
        return n;
    }
    c.value_depth++;
    var result = sem_surface_nullable_impl(c, n, expected_type);
    c.value_depth--;
    return result;
}

fn sem_surface_nullable_impl(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    n = sem_surface_unwrap(n);
    if !sem_is(n, "TowerNullAccess") {
        return sem_operand(c, n, expected_type);
    }
    if sem_get(n) != null {
        return n;
    }
    c.surface_expressions = true;
    var source = sem_surface_unwrap(sem_member(n, "base"));
    var base: void* = null;
    if sem_is(source, "CoreLocation") {
        base = sem_location(c, source, 0);
    }
    else {
        base = sem_surface_nullable(c, source, null);
    }
    if !sem_ok(c) {
        return n;
    }
    var guarded = sem_tokens(c, sem_child(n, 1))[0] == 63;
    if guarded && sem_get(base).type.pointers == 0 {
        sem_fail(c, n, "Null-conditional access requires a pointer receiver");
        return n;
    }
    sem_location(c, n, 0);
    if !sem_ok(c) {
        return n;
    }
    var value = sem_get(n);
    value.kind = SurfaceNullField;
    if sem_member(n, "index") != null {
        value.kind = SurfaceNullIndex;
    }
    value.op = convert(u32, guarded);
    return n;
}

// One operator classification is shared by binary and compound syntax.
// Compound assignment strips '=' and uses this same operation/type contract.
fn sem_surface_code(operation: u8*): u32 {
    if sem_equal(operation, "&&") {
        return SurfaceAnd;
    }
    if sem_equal(operation, "||") {
        return SurfaceOr;
    }
    if sem_equal(operation, "??") {
        return SurfaceCoalesce;
    }
    if sem_equal(operation, "<<") {
        return SurfaceShiftLeft;
    }
    if sem_equal(operation, ">>") {
        return SurfaceShiftRight;
    }
    if sem_equal(operation, ">>>") {
        return SurfaceShiftUnsigned;
    }
    for(var code: u32 = 0; code <= OGe; code++) {
        if sem_equal(operation, semantic_operator(code)) {
            return code;
        }
    }
    return SurfaceSet;
}

fn sem_surface_compound(op: u8*): bool {
    var length = sem_length(op);
    if length < 2 || op[length -1] != 61 {
        return false;
    }
    return !sem_equal(op, "==") && !sem_equal(op, "!=")
    && !sem_equal(op, "<=") && !sem_equal(op, ">=");
}

fn sem_surface_binary(c: SemanticContext*, n: void*, left: void*, right: void*, op: u32, expected_type: FoundationType*): void* {
    var value = sem_node(c, n, KBinary);
    value.op = op;
    var comparison = op >= OEq;
    var input = expected_type;
    var infer = comparison;
    infer ||= input == null;
    if infer {
        var anchor = left;
        if sem_literal(c, left) {
            if !sem_literal(c, right) || sem_float_literal(c, right) {
                anchor = right;
            }
        }
        var known = sem_operand(c, anchor, null);
        if !sem_ok(c) {
            return n;
        }
        input = &sem_get(known).type;
    }
    value.left = sem_operand(c, left, input);
    if !sem_ok(c) {
        return n;
    }
    if semantic_aggregate(input) {
        sem_fail(c, n, "Binary operators require scalar or pointer operands");
        return n;
    }
    var offset = input.pointers != 0;
    if offset {
        offset = op == OAdd;
        offset ||= op == OSub;
    }
    var right_type = input;
    if offset {
        right_type = null;
        if sem_literal(c, right) {
            right_type = sem_type_new(c, SUSize, 0, null);
        }
    }
    value.right = sem_operand(c, right, right_type);
    if !sem_ok(c) {
        return n;
    }
    if comparison {
        sem_set_type(&value.type, sem_type_new(c, SBool, 0, null));
    }
    else {
        sem_set_type(&value.type, input);
    }
    if offset {
        sem_surface_integer(c, value.right);
        sem_surface_pointee(c, n, input);
    } else {
        var equality = op == OEq;
        equality ||= op == ONe;
        if !equality {
            if semantic_enum(input) {
                sem_fail(c, n, "Enum operations require equality or inequality");
            } else {
                if !semantic_numeric_binary(input, op) {
                    sem_surface_integer(c, value.left);
                }
            }
        }
    }
    return sem_surface_expected(c, n, expected_type);
}

fn sem_surface_addressable(n: void*): bool {
    var value = sem_get(n);
    if value == null { return false; }
    if value.kind == KOperand { return value.binding != null && !value.constant; }
    if value.kind == KLoad { return true; }
    if value.kind == KField || value.kind == KIndex {
        return value.indirect || sem_surface_addressable(value.left);
    }
    return false;
}

fn sem_surface_place(c: SemanticContext*, n: void*): void* {
    n = sem_surface_unwrap(n);
    var value: void* = null;
    var dereference = sem_is(n, "TowerExpression") && sem_member(n, "left") == null
    && sem_member(n, "right") != null && sem_equal(sem_tokens(c, sem_child(n, 0)), "*");
    if sem_is(n, "CoreLocation") {
        value = sem_location(c, n, 0);
    } else { if dereference {
        value = sem_surface(c, n, null);
    }
    else {
        value = sem_operand(c, n, null);
    } }
    if !sem_ok(c) {
        return value;
    }
    if !sem_surface_addressable(value) {
        sem_fail(c, n, "Operator requires an addressable location");
    }
    return value;
}

fn sem_surface_operator(c: SemanticContext*, n: void*, left: void*): u8* {
    var index: usize = 0;
    if left != null {
        index = 1;
    }
    var op = sem_tokens(c, sem_child(n, index));
    if sem_equal(op, "not") {
        return "!";
    }
    if sem_equal(op, "compl") {
        return "~";
    }
    if sem_equal(op, "bitand") {
        return "&";
    }
    if sem_equal(op, "bitor") {
        return "|";
    }
    if sem_equal(op, "xor") {
        return "^";
    }
    if sem_equal(op, "and") {
        return "&&";
    }
    if sem_equal(op, "or") {
        return "||";
    }
    if sem_equal(op, "not_eq") {
        return "!=";
    }
    if sem_equal(op, "and_eq") {
        return "&=";
    }
    if sem_equal(op, "or_eq") {
        return "|=";
    }
    if sem_equal(op, "xor_eq") {
        return "^=";
    }
    return op;
}

// A discarded/comma-left expression may be void. Value contexts still use the
// ordinary operand checker, so a void branch cannot initialize a local or argument.
fn sem_surface_discard(c: SemanticContext*, n: void*): void* {
    n = sem_surface_unwrap(n);
    if sem_is(n, "CoreCall") {
        return sem_call(c, n);
    }
    var condition = sem_member(n, "condition");
    var comma = sem_is(n, "TowerComma") && sem_member(n, "left") != null;
    if condition == null && !comma {
        var result = sem_operand(c, n, null);
        // Bare and module-qualified names can grow into void calls, including
        // for updates. Holes inside operands or arguments still need values.
        if c.editor != null && c.editor.found && sem_is(n, "CoreLocation") {
            var bare_name = c.editor.node == sem_member(n, "name");
            var module_name = c.editor.node == n && c.editor.module != null;
            if bare_name || module_name {
                c.editor.value_required = false;
            }
        }
        return result;
    }
    c.surface_expressions = true;
    var kind = SurfaceSelect;
    if comma {
        kind = SurfaceComma;
    }
    var value = sem_node(c, n, kind);
    var left = sem_member(n, "body");
    var right = sem_member(n, "otherwise");
    if comma {
        left = sem_member(n, "left");
        right = sem_member(n, "right");
    } else {
        value.value = sem_operand(c, condition, sem_type_new(c, SBool, 0, null));
    }
    value.left = sem_surface_discard(c, left);
    if !sem_ok(c) {
        return n;
    }
    value.right = sem_surface_discard(c, right);
    if !sem_ok(c) {
        return n;
    }
    var left_value = sem_get(value.left);
    var right_value = sem_get(value.right);
    if !comma && !semantic_type_equal(&left_value.type, &right_value.type) {
        sem_fail(c, n, "Conditional branches must have the same type");
    }
    sem_set_type(&value.type, &right_value.type);
    return n;
}

fn sem_surface(c: SemanticContext*, n: void*, expected_type: FoundationType*): void* {
    var original = n;
    n = sem_surface_unwrap(n);
    if n != original {
        return sem_operand(c, n, expected_type);
    }
    var existing = sem_get(n);
    if existing != null {
        return sem_surface_expected(c, n, expected_type);
    }
    c.surface_expressions = true;
    var group = sem_member(n, "value");
    if group != null {
        return sem_operand(c, group, expected_type);
    }
    var left = sem_member(n, "left");
    var right = sem_member(n, "right");
    var condition = sem_member(n, "condition");
    if condition != null {
        var value = sem_node(c, n, SurfaceSelect);
        value.value = sem_operand(c, condition, sem_type_new(c, SBool, 0, null));
        var body = sem_member(n, "body");
        var otherwise = sem_member(n, "otherwise");
        var input = expected_type;
        if input == null && sem_literal(c, body) && !sem_literal(c, otherwise) {
            var known = sem_operand(c, otherwise, null);
            if !sem_ok(c) {
                return n;
            }
            input = &sem_get(known).type;
        }
        value.left = sem_operand(c, body, input);
        if !sem_ok(c) {
            return n;
        }
        value.right = sem_operand(c, otherwise, &sem_get(value.left).type);
        sem_set_type(&value.type, &sem_get(value.left).type);
        return sem_surface_expected(c, n, expected_type);
    }
    var op = sem_surface_operator(c, n, left);
    if sem_equal(op, ",") {
        var value = sem_node(c, n, SurfaceComma);
        value.left = sem_surface_discard(c, left);
        if !sem_ok(c) {
            return n;
        }
        value.right = sem_operand(c, right, expected_type);
        if sem_ok(c) {
            sem_set_type(&value.type, &sem_get(value.right).type);
        }
        return n;
    }
    var postfix = left != null;
    var increment = sem_equal(op, "++");
    var decrement = sem_equal(op, "--");
    var modify = increment;
    if decrement {
        modify = true;
    }
    if modify {
        var place = right;
        if postfix {
            place = left;
        }
        var value = sem_node(c, n, SurfaceModify);
        value.target = sem_surface_place(c, place);
        if !sem_ok(c) {
            return n;
        }
        sem_set_type(&value.type, &sem_get(value.target).type);
        var pointer = value.type.pointers != 0;
        if pointer {
            sem_surface_pointee(c, n, &value.type);
        }
        else { if !semantic_float(&value.type) {
            sem_surface_integer(c, value.target);
        } }
        value.op = OAdd;
        if decrement {
            value.op = OSub;
        }
        value.indirect = postfix;
        return sem_surface_expected(c, n, expected_type);
    }
    if left == null {
        var missing = right == null;
        if missing {
            sem_fail(c, n, "A pointer type spelling cannot be used as a value");
            return n;
        }
        var address = sem_equal(op, "&");
        var load = sem_equal(op, "*");
        var indirect = address;
        if load {
            indirect = true;
        }
        if indirect {
            if address && sem_function_reference(c, n, right) {
                return sem_surface_expected(c, n, expected_type);
            }
            var kind = KLoad;
            if address {
                kind = KAddress;
            }
            var value = sem_node(c, n, kind);
            if address {
                value.value = sem_surface_place(c, right);
            }
            else {
                value.value = sem_operand(c, right, null);
            }
            if !sem_ok(c) {
                return n;
            }
            sem_set_type(&value.type, &sem_get(value.value).type);
            if address {
                value.type.pointers++;
            }
            else {
                if value.type.pointers == 0 {
                    sem_fail(c, n, "Load requires a pointer");
                }
                else {
                    value.type.pointers--;
                    if value.type.pointers == 0 && value.type.scalar == SVoid {
                        sem_fail(c, n, "Cannot load a void pointer");
                    }
                }
            }
            return sem_surface_expected(c, n, expected_type);
        }
        var negate = sem_equal(op, "!");
        var input = expected_type;
        if negate {
            input = sem_type_new(c, SBool, 0, null);
        }
        var operand: void* = null;
        // The signed minimum's positive magnitude needs unsigned storage while
        // checking the literal. Negation itself remains an ordinary operation;
        // neither this path nor the literal reader evaluates the unary minus.
        if sem_equal(op, "-") {
            var type = input ?? sem_type_new(c, SI32, 0, null);
            if semantic_signed(type) && !semantic_enum(type) {
                var text = sem_tokens(c, sem_surface_unwrap(right));
                var literal = text[0] != 0;
                for(var index: usize = 0; text[index] != 0; index++) {
                    if text[index] < SurfaceFirstDigit || text[index] > SurfaceLastDigit { literal = false; break; }
                }
                if literal {
                    var storage = sem_type_new(c, semantic_unsigned_scalar(type.scalar), 0, null);
                    var magnitude = sem_operand(c, right, storage);
                    if !sem_ok(c) { return n; }
                    var maximum = semantic_mask(type) >> 1;
                    if sem_get(magnitude).bits > maximum + 1 {
                        sem_fail(c, n, sem_cat(c, "Integer literal out of range for ", sem_type_name(c, type)));
                        return n;
                    }
                    if sem_get(magnitude).bits <= maximum {
                        sem_set_type(&sem_get(magnitude).type, type);
                        operand = magnitude;
                    } else {
                        operand = sem_surface_constant(c, n, type, 0);
                        var cast = sem_get(operand);
                        cast.kind = KBits;
                        cast.constant = false;
                        cast.value = magnitude;
                    }
                }
            }
        }
        if operand == null { operand = sem_operand(c, right, input); }
        if !sem_ok(c) {
            return n;
        }
        if semantic_float(&sem_get(operand).type) && (sem_equal(op, "-") || sem_equal(op, "+")) {
            if sem_equal(op, "+") { return sem_surface_expected(c, operand, expected_type); }
            var type = &sem_get(operand).type;
            var storage = sem_type_new(c, type.scalar == SF32 ? SU32 : SU64, 0, null);
            var raw = sem_surface_constant(c, n, storage, 0);
            sem_get(raw).kind = KBits;
            sem_get(raw).constant = false;
            sem_get(raw).value = operand;
            var toggle = sem_surface_constant(c, n, storage, 0);
            sem_get(toggle).kind = KBinary;
            sem_get(toggle).constant = false;
            sem_get(toggle).op = OXor;
            sem_get(toggle).left = raw;
            sem_get(toggle).right = sem_surface_constant(c, n, storage, (semantic_mask(storage) >> 1) + 1);
            var value = sem_node(c, n, KBits);
            sem_set_type(&value.type, type);
            value.value = toggle;
            return sem_surface_expected(c, n, expected_type);
        }
        if !negate {
            sem_surface_integer(c, operand);
        }
        if sem_equal(op, "+") {
            return sem_surface_expected(c, operand, expected_type);
        }
        var value = sem_node(c, n, KBinary);
        sem_set_type(&value.type, &sem_get(operand).type);
        value.op = OSub;
        value.left = sem_surface_constant(c, n, &value.type, 0);
        value.right = operand;
        if negate {
            value.op = OEq;
        }
        if sem_equal(op, "~") {
            value.op = OXor;
            sem_get(value.left).bits = semantic_mask(&value.type);
        }
        return sem_surface_expected(c, n, expected_type);
    }
    var missing = right == null;
    if missing {
        sem_fail(c, n, "A pointer type spelling cannot be used as a value");
        return n;
    }
    var logical_and = sem_equal(op, "&&");
    var logical_or = sem_equal(op, "||");
    var logical = logical_and;
    if logical_or {
        logical = true;
    }
    if logical {
        var kind = SurfaceAnd;
        if logical_or {
            kind = SurfaceOr;
        }
        var value = sem_node(c, n, kind);
        var boolean = sem_type_new(c, SBool, 0, null);
        value.left = sem_operand(c, left, boolean);
        value.right = sem_operand(c, right, boolean);
        sem_set_type(&value.type, boolean);
        return sem_surface_expected(c, n, expected_type);
    }
    var length = sem_length(op);
    var assignment = sem_equal(op, "=");
    var compound = sem_surface_compound(op);
    var assign = assignment;
    if compound {
        assign = true;
    }
    var operation = op;
    if compound {
        var count = length -1;
        operation = sem_text(c, op, count);
    }
    var shift_left = sem_equal(operation, "<<");
    var shift_right = sem_equal(operation, ">>");
    var shift_unsigned = sem_equal(operation, ">>>");
    var shift = shift_left;
    if shift_right {
        shift = true;
    }
    if shift_unsigned {
        shift = true;
    }
    var threeway = sem_equal(operation, "<=>");
    var code = sem_surface_code(operation);
    if !assign && code == SurfaceCoalesce {
        var value = sem_node(c, n, SurfaceCoalesce);
        var infer = sem_equal(sem_tokens(c, left), "null") && expected_type == null;
        var input = expected_type;
        if infer {
            var known = sem_operand(c, right, null);
            if !sem_ok(c) {
                return n;
            }
            input = &sem_get(known).type;
        }
        value.left = sem_surface_nullable(c, left, input);
        if !sem_ok(c) {
            return n;
        }
        var first = sem_get(value.left);
        if !sem_surface_optional(first) && first.type.pointers == 0 && first.type.scalar != SFunction {
            sem_fail(c, n, "Null coalescing requires a pointer or null-conditional access");
            return n;
        }
        value.right = sem_operand(c, right, &first.type);
        sem_set_type(&value.type, &first.type);
        return sem_surface_expected(c, n, expected_type);
    }
    if assign {
        var value = sem_node(c, n, SurfaceAssign);
        value.target = sem_surface_place(c, left);
        if !sem_ok(c) {
            return n;
        }
        sem_set_type(&value.type, &sem_get(value.target).type);
        value.op = SurfaceSet;
        var input = &value.type;
        if compound {
            value.op = code;
            var pointer = input.pointers != 0;
            if code == SurfaceAnd || code == SurfaceOr {
                if input.scalar != SBool || pointer {
                    sem_fail(c, n, "Logical compound assignment requires bool operands");
                }
            } else {
                if code == SurfaceCoalesce {
                    if !pointer && input.scalar != SFunction {
                        sem_fail(c, n, "Null-coalescing assignment requires a pointer location");
                    }
                } else {
                    if pointer {
                        var offset = code == OAdd;
                        offset ||= code == OSub;
                        if offset {
                            sem_surface_pointee(c, n, input);
                            input = null;
                        }
                        else {
                            sem_fail(c, n, "Only += and -= (or ??=) apply to pointers");
                        }
                    } else {
                        if !semantic_numeric_binary(input, code) || shift {
                            sem_surface_integer(c, value.target);
                        }
                    }
                    if shift {
                        input = null;
                    }
                }
            }
        }
        var initial = sem_surface_unwrap(right);
        var named = sem_is(initial, "TowerInitializer");
        if !compound && semantic_aggregate(input) && (sem_is(initial, "TowerDefault") || named) {
            value.value = sem_initial_value(c, initial, input);
            value.kind = named ? SurfaceInitializerStore : SurfaceDefaultStore;
            sem_set_type(&value.type, sem_type_new(c, SVoid, 0, null));
        } else { value.value = sem_operand(c, right, input); }
        if sem_ok(c) {
            if input == null {
                sem_surface_integer(c, value.value);
            }
        }
        return sem_surface_expected(c, n, expected_type);
    }
    var special = shift;
    if threeway {
        special = true;
    }
    if special {
        var kind = SurfaceShift;
        if threeway {
            kind = SurfaceCompare;
        }
        var value = sem_node(c, n, kind);
        var input = expected_type;
        if threeway {
            input = null;
        }
        value.left = sem_operand(c, left, input);
        if !sem_ok(c) {
            return n;
        }
        sem_surface_integer(c, value.left);
        input = null;
        if threeway {
            input = &sem_get(value.left).type;
        }
        value.right = sem_operand(c, right, input);
        if !sem_ok(c) {
            return n;
        }
        sem_surface_integer(c, value.right);
        value.op = code;
        sem_set_type(&value.type, &sem_get(value.left).type);
        if threeway {
            sem_set_type(&value.type, sem_type_new(c, SI32, 0, null));
        }
        return sem_surface_expected(c, n, expected_type);
    }
    return sem_surface_binary(c, n, left, right, code, expected_type);
}

import tower;
import compiler_kernel;
import component_kinds;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_control;
import semantic_evaluation;
import semantic_aggregates;
import semantic_support;
import .library.vector;
import .library.work_graph;
import .library.work_pool;

extern fn entity_view_tables(view: void*, terms: void**, count: usize): void*;
extern fn entity_table_query_count(query: void*): usize;
extern fn entity_table_query_ranges(query: void*): usize;
extern fn entity_table_query_range_count(query: void*, index: usize): usize;
extern fn entity_table_query_column(query: void*, index: usize, term: usize): void**;

var FlowQuery: u32 = 7;

struct SemanticFlow {
    kernel: CompilerKernel;
    ticket: WorkTicket;
    subject: void*;
    ordinal: usize;
    invalid_label: void*;
    excessive_depth: void*;
    flow: u32;
}

// This is a readiness check, not evaluation of a constant expression. Only the
// ordinary interpreter publishes the producer's value. Conservative initial
// flow keeps cleanup paths until the dependent result is available.
fn sem_flow_known(c: SemanticContext*, node: void*): bool {
    if !sem_get(node).constant { return false; }
    var dependency = sem_evaluation_dependency(c, node);
    if dependency != null && !dependency.ready {
        if !sem_has(&c.flow_dependencies, dependency.subject) {
            sem_push(&c.flow_dependencies, dependency.subject);
        }
        return false;
    }
    return true;
}

fn sem_flow_request(c: SemanticContext*, subject: void*, dependencies: vector(void*)*): void {
    if !sem_ok(c) { return; }
    if c.flow_results == null {
        c.flow_results = sem_create(c.program.root);
        sem_require(entity_register(c.flow_results, sizeof(SemanticFlow), alignof(SemanticFlow), 0));
    }
    var result = bits(SemanticFlow*, entity_component_data(entity_component_add(subject, c.flow_results)));
    sem_require(result != null);
    fill(result, 0, sizeof(SemanticFlow));
    result.subject = subject;
    result.ordinal = c.flow_count;
    result.kernel.kind = CompilerKernelKind.Flow;
    result.kernel.payload = bits(void*, result);
    var query = work_request(&c.queries, subject, FlowQuery, 0);
    sem_require(query != 0);
    for(var i: usize = 0; i < dependencies.length; i++) {
        var dependency = work_find(&c.queries, dependencies.data[i], EvaluationQuery, 0);
        sem_require(dependency != 0 && work_depend(&c.queries, query, dependency));
    }
    sem_require(work_access(&c.queries, query, 1, 8, c.flow_count, 1, WorkAccessMode.Write));
    sem_require(work_access(&c.queries, query, 1, 3, 0, ~convert(usize, 0), WorkAccessMode.Read));
    sem_require(work_seal(&c.queries, query));
    c.flow_count++;
}

// Read-only return/reachability validation of the already-lowered Foundation
// tree. It neither rewrites nodes nor computes expression values. Labels and
// loop exits retain the same flow contract as the initial body checker.
fn sem_flow_node(result: SemanticFlow*, node: void*, depth: usize): u32 {
    if node == null { return FlowNext; }
    if depth > 1024 { result.excessive_depth = node; return FlowNext; }
    var value = sem_get(node);
    if value == null { return FlowNext; }
    if value.kind == KReturn { return FlowReturn; }
    if value.kind == KBreak { return FlowBreak; }
    if value.kind == KContinue { return FlowContinue; }
    if value.kind == KTrap || value.kind == KJump { return 0; }
    if value.kind == KBlock || value.kind == KProgram {
        var flow = FlowNext;
        var labeled = false;
        for(var i: usize = 0; i < value.items.length; i++) {
            var item = value.items.data[i];
            var child = sem_get(item);
            if child != null && child.kind == KLabel {
                if labeled && (flow & FlowNext) != 0 && result.invalid_label == null {
                    result.invalid_label = item;
                }
                labeled = true;
                flow = FlowNext;
            }
            var next = sem_flow_node(result, item, depth + 1);
            if (flow & FlowNext) != 0 { flow = (flow & ~FlowNext) | next; }
        }
        return flow;
    }
    if value.kind == KIf {
        var yes = sem_flow_node(result, value.body, depth + 1);
        var no = sem_flow_node(result, value.otherwise, depth + 1);
        var condition = sem_get(value.value);
        if condition != null && condition.constant { return condition.bits != 0 ? yes : no; }
        return yes | no;
    }
    if value.kind == KLoop {
        var body = sem_flow_node(result, value.body, depth + 1);
        return (body & FlowReturn) | ((body & FlowBreak) != 0 ? FlowNext : 0);
    }
    return FlowNext;
}

fn semantic_flow_kernel(result: SemanticFlow*): void {
    result.flow = sem_flow_node(result, sem_get(result.subject).body, 0);
}

fn sem_flows(c: SemanticContext*): void {
    if !sem_ok(c) || c.flow_count == 0 { return; }
    if c.workers.count == 0 { sem_require(sem_workers_open(c)); }
    var view = entity_view_open(c.program.root);
    sem_require(view != null);
    defer entity_view_close(view);
    // Discover jobs from their canonical Foundation and flow components. The
    // cached table plan is immutable under this pin, including across workers.
    var terms: void*[2];
    terms[0] = compiler_node_type(c.program.root, CompilerFoundation);
    terms[1] = c.flow_results;
    var query = entity_view_tables(view, &terms[0], 2);
    sem_require(query != null && entity_table_query_count(query) == c.flow_count);
    var jobs: vector(SemanticFlow*);
    vector_init(&jobs);
    defer vector_dispose(&jobs);
    sem_require(vector_reserve(&jobs, c.flow_count));
    jobs.length = c.flow_count;
    fill(jobs.data, 0, jobs.length * sizeof(SemanticFlow*));
    for(var index: usize = 0; index < entity_table_query_ranges(query); index++) {
        var column = entity_table_query_column(query, index, 1);
        var length = entity_table_query_range_count(query, index);
        for(var row: usize = 0; row < length; row++) {
            var result = bits(SemanticFlow*, entity_component_data(column[row]));
            sem_require(result.ordinal < jobs.length && jobs.data[result.ordinal] == null);
            jobs.data[result.ordinal] = result;
        }
    }
    // Archetype/row order is an execution detail. Demand, admission and errors
    // retain the source ordinal recorded when each dependency query was created.
    for(var i: usize = 0; i < c.flow_count; i++) {
        var result = jobs.data[i];
        sem_require(work_demand(&c.queries, work_find(&c.queries, result.subject, FlowQuery, 0)));
    }
    var next: usize = 0;
    while next < c.flow_count {
        var count = c.flow_count - next;
        if count > c.workers.count { count = c.workers.count; }
        for(var i: usize = 0; i < count; i++) {
            var result = jobs.data[next + i];
            sem_require(work_take_query(&c.queries, &result.ticket, FlowQuery));
            sem_require(work_task(&c.queries, result.ticket.task).subject == result.subject);
            sem_require(work_pool_submit(&c.workers, bits(void*, &result.kernel)));
        }
        for(var i: usize = 0; i < count; i++) { sem_require(work_pool_receive(&c.workers, true) != null); }
        for(var i: usize = 0; i < count; i++) {
            var result = jobs.data[next + i];
            var function = sem_get(result.subject);
            var returns = function.type.pointers != 0 || function.type.scalar != SVoid;
            var signature = sem_aggregate_signature(c, result.subject);
            returns ||= signature != null && signature.result_parameter != null;
            var missing = returns && (result.flow & FlowNext) != 0;
            if result.invalid_label != null {
                sem_fail(c, result.invalid_label, "A labeled block must end with jump or return before the next label");
            } else {
                if result.excessive_depth != null {
                    sem_fail(c, result.excessive_depth, "Foundation control-flow analysis nesting exceeds 1024");
                } else {
                    if missing {
                        sem_fail(c, result.subject, sem_cat(c, "Function '", sem_cat(c, sem_name(function),
                            "' can finish without returning a value")));
                    }
                }
            }
            sem_require(work_finish(&c.queries, &result.ticket,
                !missing && result.invalid_label == null && result.excessive_depth == null));
        }
        next += count;
    }
}

import tower;
import compiler_kernel;
import generic_body_types;
import semantic_context;
import semantic_program_types;
import semantic_declarations;
import semantic_support;
import semantic_body_work;
import .library.work_graph;
import .library.work_pool;

var GenericBodyQuery: u32 = 10;

extern fn generic_body_pending(context: void*, node: void*): bool;
extern fn generic_body_limit(context: void*): usize;
extern fn generic_body_complete(context: void*, node: void*, copied: usize): void;
extern fn compiler_generic_body_kernel(payload: void*): void;
extern fn entity_stage_hold(stage: void*): void;
extern fn entity_stage_discard(stage: void*): void;

struct SemanticGenericBodyWork {
    kernel: CompilerKernel;
    ticket: WorkTicket;
    request: GenericBodyCopy;
}

fn sem_generic_body_dependency(c: SemanticContext*, subject: void*, id: usize): void {
    var cloned = work_find(&c.queries, subject, GenericBodyQuery, 0);
    if cloned != 0 { sem_require(work_depend(&c.queries, id, cloned)); }
}

// Demand only bodies that ordinary checked calls require. Signature-only
// decltype use leaves the body descendants unmaterialized. A source window
// bounds retained work independently of the host's worker capacity.
fn sem_generic_bodies(c: SemanticContext*, next: usize, kind: void*): void {
    var batch: SemanticGenericBodyWork*[256];
    var count: usize = 0;
    var end = next + BodyPreparationWindow;
    if end > c.program.functions.length { end = c.program.functions.length; }
    for(var i = next; i < end; i++) {
        var subject = c.program.functions.data[i];
        if !sem_body_needed(c, subject) || !generic_body_pending(c.generics, subject) { continue; }
        var result = &sem_body_work(c, subject, kind).cloning;
        result.kernel.kind = CompilerKernelKind.GenericBody;
        result.kernel.payload = bits(void*, &result.request);
        result.request.context = c.generics;
        result.request.node = subject;
        var id = work_request(&c.queries, subject, GenericBodyQuery, 0);
        sem_require(id != 0);
        var signature = sem_declaration_query(c, subject);
        if signature != 0 { sem_require(work_depend(&c.queries, id, signature)); }
        // Immutable syntax/type inputs, one private output per function.
        sem_require(work_access(&c.queries, id, 1, 1, 0, ~convert(usize, 0), WorkAccessMode.Read));
        sem_require(work_access(&c.queries, id, 1, 9, 0, ~convert(usize, 0), WorkAccessMode.Read));
        sem_require(work_access(&c.queries, id, 1, 10, i, 1, WorkAccessMode.Write));
        sem_require(work_seal(&c.queries, id) && work_demand(&c.queries, id));
        batch[count++] = result;
    }
    for(var first: usize = 0; first < count && sem_ok(c);) {
        var stop = first + c.workers.count;
        if stop > count { stop = count; }
        for(var i = first; i < stop; i++) {
            var result = batch[i];
            var subject = result.request.node;
            sem_require(work_take_task(&c.queries, &result.ticket,
                work_find(&c.queries, subject, GenericBodyQuery, 0)));
            result.request.stage = entity_stage_open(c.program.root);
            sem_require(result.request.stage != null);
            result.request.limit = generic_body_limit(c.generics);
        }
        var view = entity_view_open(c.program.root);
        sem_require(view != null);
        for(var i = first; i < stop; i++) {
            sem_require(work_pool_submit(&c.workers, bits(void*, &batch[i].kernel)));
        }
        for(var i = first; i < stop; i++) { sem_require(work_pool_receive(&c.workers, true) != null); }
        // Histories can have zero references pending reclamation under this pin.
        // Acquire their queued payload ownership before releasing the last view.
        for(var i = first; i < stop; i++) { entity_stage_hold(batch[i].request.stage); }
        entity_view_close(view);
        for(var i = first; i < stop; i++) {
            var result = batch[i];
            var request = &result.request;
            var accepted = sem_ok(c) && request.success && request.copied <= generic_body_limit(c.generics);
            if accepted {
                sem_require(entity_stage_publish(request.stage));
                generic_body_complete(c.generics, request.node, request.copied);
            } else {
                entity_stage_discard(request.stage);
                if sem_ok(c) {
                    sem_fail(c, request.node, "Template expansion exceeds 65536 nodes or could not allocate its work stack");
                }
            }
            request.stage = null;
            sem_require(work_finish(&c.queries, &result.ticket, accepted));
        }
        first = stop;
    }
}

import tower;
import inspection_policy;
import semantic_context;
import semantic_support;
import semantic_statements;
import semantic_types;
import semantic_modules;
import semantic_generic_values;
import .library.vector;

// Optional, disposable analysis on the original shared entities. The annotation
// is the actual type-expression tree, whose name leaves bind to declarations;
// it is not a second type language or a partially instantiated Foundation graph.
enum GenericInfoKind: u32 {
    Function, Constructor, TypeParameter, ConstantParameter, Parameter,
    Structure, Field, Variable, TypeExpression, Return,
    Member, Index, Binary, Value, Load, Assignment
}

enum GenericShapeState: u32 {
    Uninspected, Fixed, Unknown
}

// Query-local substitutions bind declaration entities to existing argument
// trees. They are a view of the shared graph, not another type representation.
struct GenericBinding {
    parameter: void*;
    argument: void*;
    bindings: GenericBinding*;
    next: GenericBinding*;
}

struct GenericInfo {
    kind: GenericInfoKind;
    definition: void*;
    declaration: void*;
    annotation: void*;
    resolved: void*;
    dependent: bool;
    bindings: GenericBinding*;
    shape_state: GenericShapeState;
    fixed_record: void*;
}

struct GenericAnalysis {
    context: SemanticContext*;
    component: void*;
    definition: void*;
    constructor: bool;
    resolve_types: bool;
    budget: usize;
    truncated: bool;
}

fn generic_info(node: void*, component: void*): GenericInfo* {
    if node == null {
        return null;
    }
    return bits(GenericInfo*, entity_component_data(entity_component_get(node, component)));
}

fn generic_info_add(a: GenericAnalysis*, node: void*, declaration: void*, kind: GenericInfoKind): GenericInfo* {
    var result = bits(GenericInfo*, entity_component_data(entity_component_add(node, a.component)));
    var allocated = result != null;
    sem_require(allocated);
    fill(result, 0, sizeof(GenericInfo));
    result.kind = kind;
    result.definition = a.definition;
    result.declaration = declaration;
    result.annotation = sem_member(declaration, "type");
    return result;
}

fn generic_info_bind(a: GenericAnalysis*, node: void*, declaration: void*): void {
    var meaning = generic_info(declaration, a.component);
    if meaning == null {
        return;
    }
    var result = generic_info_add(a, node, declaration, meaning.kind);
    copy(result, meaning, sizeof(GenericInfo));
}

fn generic_info_lookup(scope: SemanticScope*, name: u8*): void* {
    while scope != null {
        var found = sem_lookup_table(scope.names, name);
        if found != null {
            return found;
        }
        scope = scope.parent;
    }
    return null;
}

fn generic_info_name(a: GenericAnalysis*, scope: SemanticScope*, node: void*): void {
    var name = sem_member(node, "name");
    if name != null {
        // Duplicate/invalid unused bodies remain for ordinary instantiation to
        // diagnose. Never make a failed speculative check a document error.
        sem_put(a.context, scope.names, sem_identifier(a.context, name), node);
    }
}

fn generic_info_dependent(node: void*, component: void*, depth: usize): bool {
    var next = depth + 1;
    if node == null {
        return false;
    }
    if depth == InspectionDepthLimit {
        return true;
    }
    var meaning = generic_info(node, component);
    if meaning != null {
        if meaning.kind == GenericInfoKind.TypeParameter {
            return true;
        }
        if meaning.kind == GenericInfoKind.ConstantParameter {
            return true;
        }
        if meaning.kind == GenericInfoKind.Structure {
            return true;
        }
    }
    for(var i: usize = 0; i < sem_child_count(node); i++) {
        if generic_info_dependent(sem_child(node, i), component, next) {
            return true;
        }
    }
    return false;
}

fn generic_info_type(a: GenericAnalysis*, meaning: GenericInfo*): void {
    var annotation = meaning.annotation;
    if annotation == null {
        return;
    }
    meaning.dependent = generic_info_dependent(annotation, a.component, 0);
    if meaning.dependent {
        return;
    }
    // A failed check may leave a named type with an unfinished layout in the
    // ordinary registry. Its written annotation/bindings remain useful, but
    // querying that partial registry must not turn zeroed fields into a layout.
    if !a.resolve_types {
        return;
    }
    if sem_equal(sem_tokens(a.context, annotation), "type") {
        return;
    }
    var type = sem_type(a.context, annotation);
    if sem_ok(a.context) {
        meaning.resolved = sem_type_entity(a.context, type);
    }
    a.context.program.error.length = 0;
}

fn generic_info_walk(a: GenericAnalysis*, node: void*, values: SemanticScope*, types: SemanticScope*, depth: usize): void {
    var next = depth + 1;
    if node == null {
        return;
    }
    if depth == InspectionDepthLimit {
        a.truncated = true;
        return;
    }
    if a.budget == 0 {
        a.truncated = true;
        return;
    }
    a.budget--;
    var c = a.context;
    var declaration = generic_info(node, a.component);
    var name: void* = null;
    if sem_is(node, "CoreStruct") {
        declaration = generic_info_add(a, node, node, GenericInfoKind.Structure);
        declaration.dependent = true;
        generic_info_name(a, types, node);
        name = sem_member(node, "name");
    }
    if sem_is(node, "CoreField") {
        declaration = generic_info_add(a, node, node, GenericInfoKind.Field);
        name = sem_member(node, "name");
    }
    var local = sem_is(node, "CoreDeclare");
    if local {
        declaration = generic_info_add(a, node, node, GenericInfoKind.Variable);
        name = sem_member(node, "name");
    }
    if sem_is(node, "CoreParameter") {
        name = sem_member(node, "name");
    }
    if node == a.definition {
        name = sem_member(node, "name");
    }
    if sem_is(node, "CoreType") {
        declaration = generic_info_add(a, node, node, GenericInfoKind.TypeExpression);
        declaration.annotation = node;
    }
    if sem_is(node, "CoreReturn") {
        declaration = generic_info_add(a, node, a.definition, GenericInfoKind.Return);
    }
    // Bind names by their semantic tree roles, not token spelling. In particular
    // a member name is never mistaken for a same-named parameter or local.
    var reference: void* = null;
    var type_name = sem_is(node, "CoreTypeName");
    var location = sem_is(node, "CoreLocation");
    var reference_role = type_name;
    if location {
        reference_role = true;
    }
    if reference_role {
        if sem_member(node, "base") == null {
            reference = sem_member(node, "name");
        }
    }
    if sem_is(node, "CoreArrayCount") {
        reference = node;
    }
    if reference != null {
        var text = sem_identifier(c, reference);
        var binding: void* = null;
        if type_name {
            binding = generic_info_lookup(types, text);
            // A type application's argument can name a compile-time integer.
            if binding == null {
                var value = generic_info_lookup(values, text);
                var meaning = generic_info(value, a.component);
                var constant = meaning != null;
                constant &&= meaning.kind == GenericInfoKind.ConstantParameter;
                if constant {
                    binding = value;
                }
            }
        }
        else {
            binding = generic_info_lookup(values, text);
            if binding == null {
                binding = generic_info_lookup(types, text);
            }
        }
        if binding != null {
            generic_info_bind(a, node, binding);
        }
    }
    if sem_is(node, "CoreBlock") {
        values = sem_scope(c, values);
        types = sem_scope(c, types);
    }
    for(var i: usize = 0; i < sem_child_count(node); i++) {
        var child = sem_child(node, i);
        if child != name {
            generic_info_walk(a, child, values, types, next);
        }
    }
    if declaration != null {
        generic_info_type(a, declaration);
        if name != null {
            generic_info_bind(a, name, node);
        }
    }
    // Local scope begins after the initializer, preserving lexical shadowing.
    if local {
        generic_info_name(a, values, node);
    }
}

// Query clients opt into this pass; executable compilation still checks each
// concrete instance normally. Type/value bindings stay on the source entities.
fn sem_generic_inspect(c: SemanticContext*, resolve_types: bool, truncated: bool*): void* {
    var component = sem_create(c.program.root);
    sem_require(entity_register(component, sizeof(GenericInfo), alignof(GenericInfo), 0));
    var a: GenericAnalysis;
    a.context = c;
    a.component = component;
    a.resolve_types = resolve_types;
    a.budget = InspectionNodeLimit;
    a.truncated = false;
    var i: usize = 0;
    for(; i < c.template_nodes.length; i++) {
        var definition = c.template_nodes.data[i];
        a.definition = definition;
        a.constructor = sem_equal(sem_tokens(c, sem_member(definition, "type")), "type");
        var kind = GenericInfoKind.Function;
        if a.constructor {
            kind = GenericInfoKind.Constructor;
        }
        generic_info_add(&a, definition, definition, kind);
        var values = sem_scope(c, null);
        var types = sem_scope(c, null);
        var parameters = sem_collect(c, sem_member(definition, "params"), "CoreParameter");
        var p: usize = 0;
        for(; p < parameters.length; p++) {
            var parameter = parameters.data[p];
            var parameter_kind = GenericInfoKind.Parameter;
            if a.constructor {
                parameter_kind = GenericInfoKind.ConstantParameter;
            }
            var is_type = generic_type_parameter(c.generics, definition, p);
            if is_type {
                parameter_kind = GenericInfoKind.TypeParameter;
            }
            generic_info_add(&a, parameter, parameter, parameter_kind);
            if is_type {
                generic_info_name(&a, types, parameter);
            }
            else {
                generic_info_name(&a, values, parameter);
            }
        }
        generic_info_walk(&a, definition, values, types, 0);
    }
    // Bind every definition before following type applications. This preserves
    // module forward references and makes inspection independent of file order.
    i = 0;
    for(; i < c.template_nodes.length; i++) {
        a.definition = c.template_nodes.data[i];
        generic_value_walk(&a, a.definition, 0);
    }
    *truncated = a.truncated;
    return component;
}

import tower;
import semantic_generic_info;
import semantic_context;
import semantic_support;
import semantic_types;
import semantic_values;
import semantic_expressions;
import semantic_modules;
import foundation_tags;
import foundation_types;
import format_types;
import inspection_policy;
import .library.vector;

extern fn compiler_clone_tree(source: void*, limit: usize, copied: usize*): void*;

fn generic_step(a: GenericAnalysis*, depth: usize): bool {
    if depth >= InspectionDepthLimit {
        a.truncated = true;
        return false;
    }
    if a.budget == 0 {
        a.truncated = true;
        return false;
    }
    a.budget--;
    return true;
}

fn generic_view(a: GenericAnalysis*, annotation: void*, bindings: GenericBinding*): GenericInfo* {
    var result = bits(GenericInfo*, sem_allocate(a.context, sizeof(GenericInfo)));
    fill(result, 0, sizeof(GenericInfo));
    result.kind = GenericInfoKind.TypeExpression;
    result.annotation = annotation;
    result.bindings = bindings;
    return result;
}

fn generic_view_copy(result: GenericInfo*, source: GenericInfo*): void {
    if source == null {
        return;
    }
    result.annotation = source.annotation;
    result.bindings = source.bindings;
    result.resolved = source.resolved;
    result.dependent = source.dependent;
}

fn generic_unwrap(node: void*): void* {
    loop {
        if sem_child_count(node) != 1 {
            return node;
        }
        // Unnamed single-child relationships are transparent, including the
        // parser's generated optional-capture wrappers. Named roles retain the
        // semantic node (e.g. a location's name or a type's base).
        var role = entity_child_name(node, 0);
        var named = role != null;
        named &&= role[0] != 0;
        if named {
            return node;
        }
        node = sem_child(node, 0);
    }
}

fn generic_literal(a: GenericAnalysis*, node: void*): bool {
    node = generic_unwrap(node);
    if node == null {
        return false;
    }
    if sem_is(node, "CoreBinary") {
        return false;
    }
    if sem_is(node, "TowerExpression") {
        return false;
    }
    if sem_is(node, "TowerComma") {
        return false;
    }
    if sem_is(node, "CoreLocation") {
        return false;
    }
    if sem_is(node, "CoreCall") {
        return false;
    }
    if sem_is(node, "CoreAddress") {
        return false;
    }
    if sem_is(node, "CoreLoad") {
        return false;
    }
    return sem_literal(a.context, node);
}

fn generic_binding(a: GenericAnalysis*, node: void*, bindings: GenericBinding*): GenericBinding* {
    var original = generic_info(node, a.component);
    var candidate = bindings;
    if original != null {
        while candidate != null {
            if candidate.parameter == original.declaration {
                return candidate;
            }
            candidate = candidate.next;
        }
    }
    node = generic_unwrap(node);
    if sem_is(node, "CoreType") {
        if sem_member(node, "base") != null {
            return null;
        }
        if sem_child_count(node) != 1 {
            return null;
        }
        node = sem_member(node, "name");
    }
    var info = generic_info(node, a.component);
    if info == null {
        return null;
    }
    while bindings != null {
        if bindings.parameter == info.declaration {
            return bindings;
        }
        bindings = bindings.next;
    }
    return null;
}

fn generic_normalize(a: GenericAnalysis*, view: GenericInfo*, depth: usize): void {
    for(; view.annotation != null; depth++) {
        if !generic_step(a, depth) {
            return;
        }
        view.annotation = generic_unwrap(view.annotation);
        var binding = generic_binding(a, view.annotation, view.bindings);
        if binding == null {
            return;
        }
        view.annotation = binding.argument;
        view.bindings = binding.bindings;
    }
}

fn generic_view_dependent(a: GenericAnalysis*, node: void*, bindings: GenericBinding*, depth: usize): bool {
    if node == null {
        return false;
    }
    if !generic_step(a, depth) {
        return true;
    }
    var next = depth + 1;
    var binding = generic_binding(a, node, bindings);
    if binding != null {
        return generic_view_dependent(a, binding.argument, binding.bindings, next);
    }
    var info = generic_info(node, a.component);
    if info != null {
        if info.kind == GenericInfoKind.TypeParameter {
            return true;
        }
        if info.kind == GenericInfoKind.ConstantParameter {
            return true;
        }
        if info.kind == GenericInfoKind.Structure {
            return true;
        }
    }
    for(var i: usize = 0; i < sem_child_count(node); i++) {
        if generic_view_dependent(a, sem_child(node, i), bindings, next) {
            return true;
        }
    }
    return false;
}

fn generic_resolve_view(a: GenericAnalysis*, view: GenericInfo*, depth: usize): void {
    generic_normalize(a, view, depth);
    view.resolved = null;
    view.dependent = generic_view_dependent(a, view.annotation, view.bindings, depth);
    if view.dependent {
        return;
    }
    // After a document error, only the already registered primitive type
    // objects are trustworthy. Never query or expose unfinished nominal layouts.
    if !a.resolve_types {
        view.resolved = generic_primitive(a, view.annotation);
        return;
    }
    if view.annotation == null {
        return;
    }
    var substitutions = generic_format_substitutions(a, view.annotation, view.bindings, depth);
    if substitutions != null {
        return;
    }
    var type = sem_type(a.context, view.annotation);
    if sem_ok(a.context) {
        view.resolved = sem_type_entity(a.context, type);
    }
    a.context.program.error.length = 0;
}

fn generic_primitive(a: GenericAnalysis*, node: void*): void* {
    if !sem_is(node, "CoreType") {
        return null;
    }
    if !(sem_child_count(node) == 1) {
        return null;
    }
    var name = sem_member(node, "name");
    var found = sem_resolve(a.context, a.context.types, name, sem_identifier(a.context, name));
    a.context.program.error.length = 0;
    var value = sem_get(found);
    if value == null {
        return null;
    }
    var primitive = value.kind == KType;
    primitive &&= value.type.record == null;
    if primitive {
        return found;
    }
    return null;
}

// Accept only a fixed record returned directly by a type function: declarations
// followed by one return. No speculative execution, branch selection, effects,
// or first-specialization fallback. More general type programs remain unknown.
fn generic_record_result(a: GenericAnalysis*, definition: void*): void* {
    var meaning = generic_info(definition, a.component);
    if meaning == null {
        return null;
    }
    if meaning.shape_state != GenericShapeState.Uninspected {
        return meaning.fixed_record;
    }
    meaning.shape_state = GenericShapeState.Unknown;
    var statements = sem_collect(a.context, sem_member(definition, "body"), "Statement");
    var record: void* = null;
    var i: usize = 0;
    for(; i < statements.length; i++) {
        var node = generic_unwrap(statements.data[i]);
        var after = i + 1;
        if after == statements.length {
            if !sem_is(node, "CoreReturn") {
                return null;
            }
            var value = generic_unwrap(sem_member(node, "value"));
            var info = generic_info(value, a.component);
            if info == null {
                return null;
            }
            if info.kind != GenericInfoKind.Structure {
                return null;
            }
            record = info.declaration;
        } else {
            if !sem_is(node, "CoreStruct") {
                return null;
            }
        }
    }
    // The returned declaration must be one of those direct declarations.
    i = 0;
    for(; i < statements.length; i++) {
        if generic_unwrap(statements.data[i]) == record {
            meaning.shape_state = GenericShapeState.Fixed;
            meaning.fixed_record = record;
            return record;
        }
    }
    return null;
}

fn generic_record(a: GenericAnalysis*, source: GenericInfo*, depth: usize): GenericInfo* {
    if source == null {
        return null;
    }
    if !generic_step(a, depth) {
        return null;
    }
    var view = generic_view(a, source.annotation, source.bindings);
    generic_normalize(a, view, depth);
    var node = view.annotation;
    // Member access permits exactly one pointer indirection, as sem_location does.
    if sem_is(node, "CoreType") {
        var base = sem_member(node, "base");
        if base != null {
            if sem_member(node, "count") != null {
                return null;
            }
            view.annotation = base;
            generic_normalize(a, view, depth);
            node = view.annotation;
            if sem_member(node, "base") != null {
                return null;
            }
        }
    }
    var name = sem_member(node, "name");
    if name == null {
        return null;
    }
    if sem_child_count(node) > 1 {
        var definition = sem_resolve(a.context, a.context.type_functions, name, sem_identifier(a.context, name));
        a.context.program.error.length = 0;
        if definition == null {
            return null;
        }
        var record = generic_record_result(a, definition);
        if record == null {
            return null;
        }
        var parameters = sem_collect(a.context, sem_member(definition, "params"), "CoreParameter");
        var arguments = sem_collect(a.context, sem_member(node, "args"), "CoreTypeArgument");
        if parameters.length != arguments.length {
            return null;
        }
        var bindings: GenericBinding* = null;
        for(var i: usize = 0; i < parameters.length; i++) {
            var binding = bits(GenericBinding*, sem_allocate(a.context, sizeof(GenericBinding)));
            binding.parameter = parameters.data[i];
            binding.argument = arguments.data[i];
            binding.bindings = view.bindings;
            binding.next = bindings;
            bindings = binding;
        }
        return generic_view(a, record, bindings);
    }
    var meaning = generic_info(name, a.component);
    if meaning != null {
        if meaning.kind == GenericInfoKind.Structure {
            return generic_view(a, meaning.declaration, view.bindings);
        }
    }
    var record = sem_resolve(a.context, a.context.types, name, sem_identifier(a.context, name));
    a.context.program.error.length = 0;
    if sem_is(record, "CoreStruct") {
        return generic_view(a, record, view.bindings);
    }
    return null;
}

fn generic_member(a: GenericAnalysis*, node: void*, source: GenericInfo*, depth: usize): void {
    var info = generic_info_add(a, node, node, GenericInfoKind.Member);
    var record = generic_record(a, source, depth);
    if record == null {
        return;
    }
    var name = sem_identifier(a.context, sem_member(node, "field"));
    var fields = sem_collect(a.context, sem_member(record.annotation, "fields"), "CoreField");
    var field: void* = null;
    foreach(var candidate in fields) {
        if sem_equal(name, sem_identifier(a.context, sem_member(candidate, "name"))) {
            if field != null {
                return;
            }
            field = candidate;
        }
    }
    if field == null {
        return;
    }
    info.kind = GenericInfoKind.Field;
    info.declaration = field;
    info.annotation = sem_member(field, "type");
    info.bindings = record.bindings;
    generic_resolve_view(a, info, depth);
    generic_info_bind(a, sem_member(node, "field"), node);
}

fn generic_element(a: GenericAnalysis*, info: GenericInfo*, source: GenericInfo*, depth: usize): void {
    if source == null {
        return;
    }
    var view = generic_view(a, source.annotation, source.bindings);
    generic_normalize(a, view, depth);
    var indexing = info.kind == GenericInfoKind.Index;
    if sem_is(view.annotation, "CoreType") {
        var base = sem_member(view.annotation, "base");
        if base != null {
            var array = sem_member(view.annotation, "count") != null;
            if array {
                if !indexing {
                    return;
                }
            }
            info.annotation = base;
            info.bindings = view.bindings;
            generic_resolve_view(a, info, depth);
            return;
        }
    }
    if source.resolved == null {
        return;
    }
    var resolved = sem_get(source.resolved);
    var type = sem_type_copy(a.context, &resolved.type);
    if type.pointers != 0 {
        type.pointers--;
    } else {
        if !indexing {
            return;
        }
        if type.scalar != SArray {
            return;
        }
        var array = sem_get(type.record);
        type = &array.element;
    }
    info.resolved = sem_type_entity(a.context, type);
}

// Reuse the ordinary checker for concrete subexpressions. Only the temporary
// cloned query subtree receives Foundation components; original template nodes
// retain their symbolic metadata and are never partly lowered or executed.
fn generic_expression_seed(a: GenericAnalysis*, source: void*, copy: void*, depth: usize): bool {
    if !generic_step(a, depth) {
        return false;
    }
    if generic_literal(a, source) {
        return true;
    }
    if sem_is(source, "CoreLocation") {
        var info = generic_info(source, a.component);
        if info == null {
            return false;
        }
        if info.resolved == null {
            return false;
        }
        var value = sem_attach(copy, KOperand);
        var resolved = sem_get(info.resolved);
        sem_set_type(&value.type, &resolved.type);
        return true;
    }
    if sem_is(source, "CoreCall") {
        return false;
    }
    var i: usize = 0;
    var next = depth + 1;
    for(; i < sem_child_count(source); i++) {
        if !generic_expression_seed(a, sem_child(source, i), sem_child(copy, i), next) {
            return false;
        }
    }
    return true;
}

fn generic_expression_result(a: GenericAnalysis*, source: void*, copy: void*, depth: usize): void {
    if !generic_step(a, depth) {
        return;
    }
    var value = sem_get(copy);
    if value != null {
        var info = generic_info(source, a.component);
        if info != null {
            info.resolved = sem_type_entity(a.context, &value.type);
            info.dependent = false;
        }
    }
    var i: usize = 0;
    var next = depth + 1;
    for(; i < sem_child_count(source); i++) {
        generic_expression_result(a, sem_child(source, i), sem_child(copy, i), next);
    }
}

fn generic_expression_check(a: GenericAnalysis*, node: void*, expected_type: void*, depth: usize): void {
    node = generic_unwrap(node);
    var eligible = sem_is(node, "CoreBinary");
    if sem_is(node, "TowerExpression") {
        eligible = true;
    }
    if sem_is(node, "TowerComma") {
        eligible = true;
    }
    if generic_literal(a, node) {
        eligible = true;
    }
    if !eligible {
        return;
    }
    var copied: usize = 0;
    var clone = compiler_clone_tree(node, a.budget, &copied);
    a.budget = a.budget - copied;
    if clone == null {
        a.truncated = true;
        return;
    }
    if generic_expression_seed(a, node, clone, depth) {
        var type: FoundationType* = null;
        if expected_type != null {
            var resolved = sem_get(expected_type);
            type = &resolved.type;
        }
        var result: void* = null;
        if sem_is(node, "CoreBinary") {
            result = sem_expression(a.context, clone, type);
        } else {
            result = sem_operand(a.context, clone, type);
        }
        if sem_ok(a.context) {
            generic_expression_result(a, node, clone, depth);
            var info = generic_info(node, a.component);
            if info != null {
                if result != null {
                    var resolved = sem_get(result);
                    info.resolved = sem_type_entity(a.context, &resolved.type);
                }
            }
        }
        a.context.program.error.length = 0;
    }
    entity_release(clone);
}

fn generic_value_walk(a: GenericAnalysis*, node: void*, depth: usize): void {
    if node == null {
        return;
    }
    if !generic_step(a, depth) {
        return;
    }
    var next = depth + 1;
    for(var i: usize = 0; i < sem_child_count(node); i++) {
        generic_value_walk(a, sem_child(node, i), next);
    }
    var info = generic_info(node, a.component);
    if info != null {
        var reference = info.kind == GenericInfoKind.Variable;
        if info.kind == GenericInfoKind.Parameter {
            reference = true;
        }
        if reference {
            if info.declaration != node {
                generic_view_copy(info, generic_info(info.declaration, a.component));
            }
        }
    }
    if sem_is(node, "CoreLocation") {
        var base = sem_member(node, "base");
        if base != null {
            var source = generic_info(base, a.component);
            if sem_member(node, "index") != null {
                info = generic_info_add(a, node, node, GenericInfoKind.Index);
                generic_element(a, info, source, next);
            } else {
                generic_member(a, node, source, next);
            }
        }
    }
    if sem_is(node, "CoreLoad") {
        info = generic_info_add(a, node, node, GenericInfoKind.Load);
        generic_element(a, info, generic_info(sem_member(node, "name"), a.component), next);
    }
    if sem_is(node, "CoreBinary") {
        generic_info_add(a, node, node, GenericInfoKind.Binary);
        generic_expression_check(a, node, null, next);
    }
    if sem_is(node, "TowerExpression") {
        var left = sem_member(node, "left");
        var right = sem_member(node, "right");
        if left != null && right != null {
            var op = sem_surface_operator(a.context, node, left);
            var assignment = sem_equal(op, "=") || sem_surface_compound(op);
            var kind = GenericInfoKind.Binary;
            if assignment {
                kind = GenericInfoKind.Assignment;
            }
            info = generic_info_add(a, node, node, kind);
            if assignment {
                generic_view_copy(info, generic_info(left, a.component));
            }
            generic_expression_check(a, node, null, next);
        } else {
            if sem_child_count(node) != 1 {
                info = generic_info_add(a, node, node, GenericInfoKind.Value);
                if left == null && right != null && sem_equal(sem_surface_operator(a.context, node, null), "*") {
                    info.kind = GenericInfoKind.Load;
                    generic_element(a, info, generic_info(right, a.component), next);
                }
                generic_expression_check(a, node, null, next);
            }
        }
    }
    var wrapper = sem_is(node, "CoreOperand");
    if sem_is(node, "TowerExpression") {
        wrapper = true;
    }
    if sem_is(node, "TowerComma") {
        wrapper = true;
    }
    if sem_is(node, "CoreValue") {
        wrapper = true;
    }
    if wrapper {
        if generic_literal(a, node) {
            var bare = generic_unwrap(node);
            generic_info_add(a, bare, bare, GenericInfoKind.Value);
            generic_expression_check(a, bare, null, next);
            if bare != node {
                generic_info_bind(a, node, bare);
            }
        } else {
            if sem_child_count(node) == 1 {
                generic_info_bind(a, node, sem_child(node, 0));
            }
        }
    }
    if sem_is(node, "CoreTarget") {
        var name = sem_member(node, "name");
        if sem_child_count(node) == 1 {
            generic_info_bind(a, node, name);
        } else {
            info = generic_info_add(a, node, node, GenericInfoKind.Assignment);
            generic_element(a, info, generic_info(name, a.component), next);
        }
    }
    if sem_is(node, "CoreAssign") {
        info = generic_info_add(a, node, node, GenericInfoKind.Assignment);
        var target = generic_info(sem_member(node, "target"), a.component);
        generic_view_copy(info, target);
        generic_expression_check(a, sem_member(node, "value"), info.resolved, next);
    }
    if sem_is(node, "CoreDeclare") {
        var value = sem_member(node, "value");
        info = generic_info(node, a.component);
        generic_expression_check(a, value, info.resolved, next);
        if info.annotation == null {
            generic_view_copy(info, generic_info(generic_unwrap(value), a.component));
            generic_info_bind(a, sem_member(node, "name"), node);
        }
    }
}

fn generic_format_substitutions(a: GenericAnalysis*, node: void*, bindings: GenericBinding*, depth: usize): FormatSubstitution* {
    if node == null {
        return null;
    }
    if bindings == null {
        return null;
    }
    if !generic_step(a, depth) {
        return null;
    }
    var next = depth + 1;
    // The list formatter skips transparent wrappers. Bind the actual type/name
    // or count entity it visits, rather than a generated list/capture parent.
    var bindable = sem_is(node, "CoreType");
    if sem_is(node, "CoreTypeName") {
        bindable = true;
    }
    if sem_is(node, "CoreArrayCount") {
        bindable = true;
    }
    var binding: GenericBinding* = null;
    if bindable {
        binding = generic_binding(a, node, bindings);
    }
    if binding != null {
        var result = bits(FormatSubstitution*, sem_allocate(a.context, sizeof(FormatSubstitution)));
        result.node = node;
        result.replacement = binding.argument;
        result.nested = generic_format_substitutions(a, binding.argument, binding.bindings, next);
        result.next = null;
        return result;
    }
    var result: FormatSubstitution* = null;
    for(var i: usize = 0; i < sem_child_count(node); i++) {
        var child = generic_format_substitutions(a, sem_child(node, i), bindings, next);
        if child != null {
            var last = child;
            while last.next != null {
                last = last.next;
            }
            last.next = result;
            result = child;
        }
    }
    return result;
}

import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_control;
import semantic_defer;
import semantic_declarations;
import semantic_statements;
import semantic_support;
import semantic_types;
import semantic_values;
import semantic_modules;
import semantic_layout;
import semantic_call_inference;
import .library.vector;

// The source's nominal declaration owns a statically resolved iteration protocol
// in its module. Each compilation exclusively owns its scratch and ECS graph. These are ordinary functions, with no container-name cases or
// independent iterator opcodes. The source pointer is evaluated exactly once.
fn sem_iteration_function(c: SemanticContext*, module: void*, name: u8*, use: void*, source: void*): void* {
    var function = sem_owned(c.functions, module, name);
    var definition = sem_owned(c.templates, module, name);
    if definition != null {
        var count = generic_parameter_count(c.generics, definition);
        var runtime: usize = 0;
        for(var i: usize = 0; i < count; i++) {
            if !generic_type_parameter(c.generics, definition, i) {
                runtime++;
            }
        }
        if runtime != 2 {
            sem_fail(c, use, "An iteration protocol function requires source and state pointer parameters");
            return null;
        }
        var values = sem_list(c);
        sem_push(values, source);
        sem_push(values, null);
        var arguments = sem_infer_arguments(c, definition, use, values);
        if !sem_ok(c) {
            return null;
        }
        function = sem_call_specialization(c, definition, use, arguments);
    }
    if function == null && sem_ok(c) {
        sem_fail(c, use, sem_cat(c, "Missing iteration protocol function '", sem_cat(c, name, "' in the source type's module")));
    }
    if !sem_ok(c) {
        return null;
    }
    if sem_get(function).parameters.length != 2 {
        sem_fail(c, use, "An iteration protocol function requires source and state pointer parameters");
        return null;
    }
    return function;
}

fn sem_iteration_address(c: SemanticContext*, parent: void*, local: void*): void* {
    var result = sem_control_node(c, parent, KAddress);
    var value = sem_get(result);
    value.value = sem_control_read(c, result, local);
    sem_set_type(&value.type, &sem_get(local).type);
    value.type.pointers++;
    return result;
}

fn sem_iteration_call(c: SemanticContext*, parent: void*, function: void*, source: void*, state: void*): void* {
    var result = sem_control_node(c, parent, KCall);
    var value = sem_get(result);
    var signature = sem_get(function);
    value.binding = function;
    sem_set_type(&value.type, &signature.type);
    sem_push(&value.items, sem_control_read(c, result, source));
    sem_push(&value.items, sem_iteration_address(c, result, state));
    for(var i: usize = 0; i < 2; i++) {
        if !semantic_type_equal(&sem_get(value.items.data[i]).type, &sem_get(signature.parameters.data[i]).type) {
            sem_fail(c, parent, "Iteration protocol source/state parameter types must agree exactly");
        }
    }
    return result;
}

struct SemanticIterationCursor {
    scope: SemanticScope*;
    deferred: void*;
    iteration: void*;
    cleanup: void*;
}

fn sem_iteration_begin(c: SemanticContext*, n: void*, depth: u32, cursor: SemanticIterationCursor*): bool {
    *cursor = default;
    if depth > 123 {
        sem_fail(c, n, "foreach lowering exceeds Foundation block nesting limit of 128");
        return false;
    }
    if c.labels != null && c.labels.count != 0 {
        sem_fail(c, n, "foreach cleanup cannot be combined with explicit function labels or jumps");
        return false;
    }
    var initial = sem_operand(c, sem_member(n, "source"), null);
    if !sem_ok(c) {
        return false;
    }
    var type = &sem_get(initial).type;
    if type.scalar != SStruct || type.pointers != 1 {
        sem_fail(c, n, "foreach requires a pointer to a nominal collection; use &collection");
        return false;
    }
    var declaration = generic_specialization(c.generics, type.record);
    if declaration == null {
        declaration = type.record;
    }
    declaration = generic_definition(c.generics, declaration);
    var module = sem_owner(c, declaration);
    var prefix = sem_cat(c, sem_identifier(c, sem_member(declaration, "name")), "_iterate_");
    var begin = sem_iteration_function(c, module, sem_cat(c, prefix, "begin"), n, initial);
    var next = sem_iteration_function(c, module, sem_cat(c, prefix, "next"), n, initial);
    var element = sem_iteration_function(c, module, sem_cat(c, prefix, "element"), n, initial);
    var end = sem_iteration_function(c, module, sem_cat(c, prefix, "end"), n, initial);
    if !sem_ok(c) {
        return false;
    }
    var state_type = sem_type_copy(c, &sem_get(sem_get(begin).parameters.data[1]).type);
    if state_type.pointers != 1 {
        sem_fail(c, n, "iterate_begin requires a pointer to its local iterator state");
        return false;
    }
    state_type.pointers--;
    var nothing = sem_type_new(c, SVoid, 0, null);
    var boolean = sem_type_new(c, SBool, 0, null);
    if !semantic_type_equal(&sem_get(begin).type, nothing) || !semantic_type_equal(&sem_get(end).type, nothing) ||
    !semantic_type_equal(&sem_get(next).type, boolean) || sem_get(element).type.pointers == 0 ||
    (sem_get(element).type.pointers == 1 && sem_get(element).type.scalar == SVoid) ||
    (state_type.pointers == 0 && state_type.scalar == SVoid) {
        sem_fail(c, n, "Iteration requires begin/end: void, next: bool, element: pointer, and concrete state storage");
        return false;
    }
    if semantic_aggregate(state_type) {
        sem_layout(c, state_type.record);
    }
    if !sem_ok(c) {
        return false;
    }
    var value = sem_node(c, n, KBlock);
    var source = sem_control_local(c, n, initial);
    var state = sem_control_node(c, n, KDeclare);
    sem_set_name(sem_get(state), sem_control_name(c));
    sem_set_type(&sem_get(state).type, state_type);
    sem_add_local(c, state);
    sem_push(&value.locals, state);
    sem_push(&value.items, state);
    sem_push(&value.items, sem_iteration_call(c, n, begin, source, state));
    var cleanup = sem_control_node(c, n, KBlock);
    sem_push(&sem_get(cleanup).items, sem_iteration_call(c, cleanup, end, source, state));
    if !sem_ok(c) {
        return false;
    }
    var saved = c.deferred;
    var pending = bits(SemanticDeferred*, sem_allocate(c, sizeof(SemanticDeferred)));
    pending.previous = bits(SemanticDeferred*, saved);
    pending.body = cleanup;
    pending.loops = c.loops;
    pending.flow = FlowNext;
    c.deferred = bits(void*, pending);
    c.has_defer = true;

    var loop_node = sem_control_node(c, n, KLoop);
    var loop_body = sem_control_node(c, loop_node, KBlock);
    sem_get(loop_node).body = loop_body;
    sem_push(&value.items, loop_node);
    var test = sem_iteration_call(c, loop_body, next, source, state);
    var condition = sem_control_read(c, loop_body, sem_control_local(c, loop_body, test));
    var iteration = sem_control_node(c, loop_body, KBlock);
    var otherwise = sem_control_branch(c, loop_body, condition, iteration);
    sem_push(&sem_get(otherwise).items, sem_control_node(c, otherwise, KBreak));
    var address = sem_iteration_call(c, iteration, element, source, state);
    var initializer = address;
    if sem_tokens(c, sem_member(n, "borrow"))[0] == 0 {
        initializer = sem_control_node(c, iteration, KLoad);
        sem_get(initializer).value = address;
        sem_set_type(&sem_get(initializer).type, &sem_get(address).type);
        sem_get(initializer).type.pointers--;
        if semantic_aggregate(&sem_get(initializer).type) {
            sem_fail(c, n, "Aggregate iteration requires an explicit borrow: foreach (var &item in &collection)");
        }
    }
    var item = sem_control_local(c, iteration, initializer);
    // A generated declaration has a checked initializer but no source type/value
    // capture. Publish its resolved type before exposing the lexical binding.
    sem_declaration_state(c, item).number = 2;
    var name = sem_identifier(c, sem_member(n, "name"));
    if name[0] == 0 {
        sem_fail(c, n, "foreach requires a nonempty item name");
    }
    sem_set_name(sem_get(item), name);
    var scope = c.scope;
    c.scope = sem_scope(c, scope);
    sem_put(c, c.scope.names, name, item);
    cursor.scope = scope;
    cursor.deferred = saved;
    cursor.iteration = iteration;
    cursor.cleanup = cleanup;
    return true;
}

fn sem_iteration_finish(c: SemanticContext*, n: void*, cursor: SemanticIterationCursor*, flow: u32): u32 {
    c.scope = cursor.scope;
    c.deferred = cursor.deferred;
    sem_push(&sem_get(cursor.iteration).items, sem_member(n, "body"));
    sem_push(&sem_get(n).items, cursor.cleanup);
    return FlowNext |(flow &FlowReturn);
}

fn sem_iteration(c: SemanticContext*, n: void*, depth: u32): u32 {
    var cursor: SemanticIterationCursor;
    if !sem_iteration_begin(c, n, depth, &cursor) { return FlowNext; }
    c.loops++;
    var flow = sem_block(c, sem_member(n, "body"), depth + 3);
    c.loops--;
    return sem_iteration_finish(c, n, &cursor, flow);
}

import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_control;
import semantic_defer;
import semantic_evaluation;
import semantic_evaluation_work;
import semantic_support;
import semantic_types;
import semantic_expressions;
import interpreter_context_types;
import compiler_kernel;
import semantic_known_work;
import semantic_work_ids;
import .library.vector;
import .library.work_graph;

// Independent facts: mutation/escape analysis proves a fixed binding; ordinary
// interpreter execution may then prove its value. Neither fact implies the other.
struct SemanticKnownBinding {
    owner: void*;
    ordinal: usize;
    immutable: bool;
    ordered: bool;
    input_query: usize;
    evaluation: void*;
    block: void*;
    begin: usize;
    end: usize;
}

fn sem_known_binding(c: SemanticContext*, declaration: void*): SemanticKnownBinding* {
    if declaration == null || c.known_bindings == null { return null; }
    return bits(SemanticKnownBinding*, entity_component_data(entity_component_get(declaration, c.known_bindings)));
}

// Only owned executable edges; never follow declaration/type back references.
fn sem_known_edges(pending: vector(void*)*, node: FoundationNode*): void {
    if node.kind == KFunction || node.kind == KType || node.kind == KLabel { return; }
    sem_push(pending, node.left);
    sem_push(pending, node.right);
    sem_push(pending, node.value);
    sem_push(pending, node.target);
    sem_push(pending, node.body);
    sem_push(pending, node.otherwise);
    foreach(var item in &node.items) { sem_push(pending, item); }
}

fn sem_known_register(c: SemanticContext*, subject: void*, owner: void*, ordinal: usize): void {
    if !sem_known_candidate(subject) { return; }
    if c.known_bindings == null {
        c.known_bindings = sem_create(c.program.root);
        sem_require(entity_register(c.known_bindings, sizeof(SemanticKnownBinding), alignof(SemanticKnownBinding), 0));
        c.value_inputs = sem_create(c.program.root);
        sem_require(entity_register(c.value_inputs, sizeof(IMValueInput), alignof(IMValueInput), 0));
    }
    var binding = bits(SemanticKnownBinding*, entity_component_data(entity_component_add(subject, c.known_bindings)));
    sem_require(binding != null);
    fill(binding, 0, sizeof(SemanticKnownBinding));
    binding.owner = owner;
    binding.ordinal = ordinal;
    binding.immutable = true;
    binding.ordered = true;
}

// Reuse Foundation's declaration rule. The initializer's existing surface
// expression metadata identifies Tower analysis without another var grammar or
// treating canonical Foundation reconstruction as a fresh surface optimization.
fn sem_known_surface(node: void*): bool {
    while node != null {
        if sem_is(node, "TowerExpression") { return true; }
        if sem_child_count(node) != 1 { return false; }
        node = sem_child(node, 0);
    }
    return false;
}

// Refuse obvious runtime captures before allocating cloned expressions or jobs.
// This is an eligibility check, never an evaluator: calls and arithmetic still
// execute only through ordinary staged interpreter work. Inputs with unresolved
// eligible producers remain dependencies for that work to discover.
fn sem_known_inputs(c: SemanticContext*, expression: void*, pending: vector(void*)*): bool {
    pending.length = 0;
    sem_push(pending, expression);
    for(var index: usize = 0; index < pending.length; index++) {
        var node = pending.data[index];
        if node == null { continue; }
        var value = sem_get(node);
        if value == null { continue; }
        if value.kind == KOperand && value.binding != null && !value.constant {
            var input = sem_known_binding(c, value.binding);
            if input == null || !input.immutable || !input.ordered { return false; }
        }
        // Optional arms are evaluated only if ordinary interpreter control flow
        // selects them. This bounded admission scan checks mandatory inputs;
        // it neither chooses a branch nor computes a constant.
        if value.kind == SurfaceSelect {
            sem_push(pending, value.value);
        } else {
            if value.kind == SurfaceAnd || value.kind == SurfaceOr || value.kind == SurfaceCoalesce {
                sem_push(pending, value.left);
            } else {
                sem_known_edges(pending, value);
            }
        }
    }
    return true;
}

fn sem_known_infer(c: SemanticContext*): void {
    if !sem_ok(c) || c.editor != null || !sem_known_needed(c) { return; }
    // Absence of writes is a whole-program fact. One joined proof query records
    // that prerequisite without a functions-times-bindings dependency cross product.
    var proof = work_request(&c.queries, c.program.root, convert(u32, SemanticQuery.KnownProof), 0);
    sem_require(proof != 0);
    var nodes = sem_list(c);
    var root = sem_get(c.program.root);
    for(var index: usize = 0; index < root.items.length; index++) {
        sem_known_register(c, root.items.data[index], null, index);
    }
    var kind = sem_known_kind(c);
    var count: usize = 0;
    for(var index: usize = 0; index < c.program.functions.length; index++) {
        var function = c.program.functions.data[index];
        var block = index == 0 ? function : sem_get(function).body;
        if block != null { sem_known_job(c, kind, function, block, index == 0 ? null : function, count++, SemanticKnownAction.Scan); }
    }
    foreach(var job in &c.evaluation_jobs) {
        var evaluation = bits(SemanticEvaluation*, job);
        sem_known_job(c, kind, evaluation.subject, evaluation.expression, null, count++, SemanticKnownAction.Scan);
    }
    var scans = sem_known_jobs(c, kind, count, SemanticQuery.KnownScan);
    foreach(var job in &scans) {
        foreach(var &candidate in &job.candidates) {
            if job.owner != null { sem_known_register(c, candidate.subject, job.owner, candidate.ordinal); }
            sem_push(nodes, candidate.subject);
        }
    }
    foreach(var job in &scans) {
        foreach(var declaration in &job.mutations) {
            var binding = sem_known_binding(c, declaration);
            if binding != null { binding.immutable = false; }
        }
    }
    if c.known_bindings == null {
        sem_known_jobs_dispose(&scans);
        return;
    }
    var scan_kind = kind;
    kind = sem_known_kind(c);
    count = 0;
    for(var index: usize = 0; index < root.items.length; index++) {
        var subject = root.items.data[index];
        var value = sem_get(subject);
        if value == null || value.kind == KFunction || value.kind == KType || value.kind == KLabel { continue; }
        var job = sem_known_job(c, kind, subject, subject, null, count++, SemanticKnownAction.Order);
        job.source_ordinal = index;
    }
    var orders = sem_known_jobs(c, kind, count, SemanticQuery.KnownOrder);
    foreach(var job in &orders) {
        foreach(var declaration in &job.mutations) { sem_known_binding(c, declaration).ordered = false; }
    }
    sem_known_jobs_dispose(&orders);
    sem_require(work_seal(&c.queries, proof) && work_demand(&c.queries, proof));
    var proof_ticket: WorkTicket = default;
    sem_require(work_take_task(&c.queries, &proof_ticket, proof));
    sem_require(work_finish(&c.queries, &proof_ticket, sem_ok(c)));
    // Reuse the per-function candidate components after mutation/order facts
    // publish. Each worker owns its eligibility scratch and candidate output.
    foreach(var job in &scans) { job.action = SemanticKnownAction.Inputs; }
    var inputs = sem_known_jobs(c, scan_kind, scans.length, SemanticQuery.KnownInputs);
    vector_dispose(&scans);
    foreach(var job in &inputs) {
        var query = work_find(&c.queries, job.subject, convert(u32, SemanticQuery.KnownInputs), 0);
        foreach(var &candidate in &job.candidates) { sem_known_binding(c, candidate.subject).input_query = query; }
    }
    sem_known_jobs_dispose(&inputs);
    foreach(var node in nodes) {
        var binding = sem_known_binding(c, node);
        if binding == null || binding.input_query == 0 { continue; }
        sem_evaluation_begin(c);
        var subject = sem_control_node(c, node, KOperand);
        var literal = sem_get(subject);
        sem_set_type(&literal.type, &sem_get(node).type);
        literal.constant = true;
        var result = bits(SemanticEvaluation*, entity_component_data(entity_component_add(subject, c.evaluation_results)));
        sem_require(result != null);
        fill(result, 0, sizeof(SemanticEvaluation));
        result.subject = subject;
        result.owner = binding.owner == null ? c.program.root : binding.owner;
        result.literal = subject;
        result.requested = true;
        result.inferred = true;
        result.ready = bits(IMDependency*, entity_component_data(entity_component_add(subject, c.evaluation_ready)));
        sem_require(result.ready != null);
        fill(result.ready, 0, sizeof(IMDependency));
        result.ready.subject = subject;
        result.kernel.kind = CompilerKernelKind.Evaluate;
        result.kernel.payload = bits(void*, &result.invocation);
        sem_push(&c.evaluation_jobs, bits(void*, result));
        sem_evaluation_request(c, result);
        sem_require(work_depend(&c.queries,
            work_find(&c.queries, subject, convert(u32, SemanticQuery.KnownClone), 0), binding.input_query));
        binding.evaluation = subject;
        var input = bits(IMValueInput*, entity_component_data(entity_component_add(node, c.value_inputs)));
        sem_require(input != null);
        input.producer = subject;
        input.owner = binding.owner;
        // Borrow until the clone wave joins. Runtime lowering starts only after
        // every eligible stage owns its independent canonical expression.
        result.expression = sem_get(node).value;
        c.surface_expressions = true;
    }
    sem_evaluation_clone_all(c);
}

fn sem_known_publish(c: SemanticContext*): void {
    if !sem_ok(c) || c.known_bindings == null { return; }
    var kind = sem_known_kind(c);
    var count: usize = 0;
    for(var index: usize = 0; index < c.program.functions.length; index++) {
        var function = c.program.functions.data[index];
        var block = index == 0 ? function : sem_get(function).body;
        if block != null { sem_known_job(c, kind, function, block, function, count++, SemanticKnownAction.Publish); }
    }
    var jobs = sem_known_jobs(c, kind, count, SemanticQuery.KnownPublish);
    foreach(var job in &jobs) {
        foreach(var &patch in &job.patches) {
            var value = sem_get(patch.subject);
            if patch.declaration { value.value = patch.literal; }
            else {
                var literal = sem_get(patch.literal);
                value.kind = literal.kind;
                value.constant = literal.constant;
                value.bits = literal.bits;
                value.binding = literal.binding;
            }
        }
    }
    foreach(var job in &jobs) { sem_known_storage_publish(job); }
    sem_known_jobs_dispose(&jobs);
}

import tower;
import compiler_kernel;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_evaluation;
import semantic_expressions;
import semantic_known_bindings;
import semantic_support;
import semantic_work_ids;
import .library.vector;
import .library.work_graph;
import .library.work_pool;

enum SemanticKnownAction: u32 { Scan, Order, Publish, Inputs }

struct SemanticKnownCandidate { subject: void*; ordinal: usize; }
struct SemanticKnownPatch { subject: void*; literal: void*; declaration: bool; }

struct SemanticKnownStorage {
    subject: void*;
    items: vector(void*);
    locals: vector(void*);
    replace_items: bool;
    replace_locals: bool;
}

// Facts belong to the query's ECS component. Workers read a pinned graph and
// own their traversal scratch; only the coordinator attaches binding metadata
// or applies the returned patches, after every reader has joined.
struct SemanticKnownWork {
    kernel: CompilerKernel;
    ticket: WorkTicket;
    context: SemanticContext*;
    subject: void*;
    root: void*;
    owner: void*;
    ordinal: usize;
    source_ordinal: usize;
    action: SemanticKnownAction;
    candidates: vector(SemanticKnownCandidate);
    mutations: vector(void*);
    patches: vector(SemanticKnownPatch);
    query_reads: vector(usize);
    storage: vector(SemanticKnownStorage);
}

extern fn entity_view_tables(view: void*, terms: void**, count: usize): void*;
extern fn entity_table_query_count(query: void*): usize;
extern fn entity_table_query_ranges(query: void*): usize;
extern fn entity_table_query_range_count(query: void*, index: usize): usize;
extern fn entity_table_query_column(query: void*, index: usize, term: usize): void**;

fn sem_known_candidate(subject: void*): bool {
    var value = sem_get(subject);
    return value != null && value.kind == KDeclare && value.value != null
        && value.type.pointers == 0 && !semantic_aggregate(&value.type)
        && !semantic_enum(&value.type) && sem_known_surface(sem_member(subject, "value"));
}

// Avoid attaching analysis metadata to Foundation-only reconstructions. The
// existing declaration index suffices for this short-circuit eligibility check.
fn sem_known_needed(c: SemanticContext*): bool {
    foreach(var node in &sem_get(c.program.root).items) {
        if sem_known_candidate(node) { return true; }
    }
    foreach(var function in &c.program.functions) {
        foreach(var node in &sem_get(function).locals) {
            if sem_known_candidate(node) { return true; }
        }
    }
    return false;
}

fn sem_known_write(result: SemanticKnownWork*, place: void*): void {
    while place != null {
        var value = sem_get(place);
        if value == null { return; }
        if value.kind == KOperand {
            if value.binding != null { sem_push(&result.mutations, value.binding); }
            return;
        }
        if (value.kind != KField && value.kind != KIndex) || value.indirect { return; }
        place = value.left;
    }
}

fn semantic_known_kernel(result: SemanticKnownWork*): void {
    if result.action == SemanticKnownAction.Inputs {
        var pending: vector(void*) = default;
        defer vector_dispose(&pending);
        var selected: usize = 0;
        foreach(var &candidate in &result.candidates) {
            var binding = sem_known_binding(result.context, candidate.subject);
            if binding != null && binding.immutable && binding.ordered
                && sem_known_inputs(result.context, sem_get(candidate.subject).value, &pending) {
                result.candidates.data[selected++] = *candidate;
            }
        }
        result.candidates.length = selected;
        return;
    }
    var context = *result.context;
    context.allocations = default;
    context.lists = default;
    context.query_reads = &result.query_reads;
    var pending = sem_list(&context);
    var seen = sem_table(&context);
    if result.action == SemanticKnownAction.Publish { sem_push(pending, result.subject); }
    sem_push(pending, result.root);
    for(var at: usize = 0; at < pending.length; at++) {
        var subject = pending.data[at];
        if subject == null { continue; }
        var visit = sem_state(&context, seen, subject);
        if visit.number != 0 { continue; }
        visit.number = 1;
        var value = sem_get(subject);
        if value == null { continue; }
        sem_known_edges(pending, value);
        if result.action == SemanticKnownAction.Scan {
            if result.owner != null ? sem_known_candidate(subject) : sem_known_binding(&context, subject) != null {
                var candidate: SemanticKnownCandidate = default;
                candidate.subject = subject;
                candidate.ordinal = at;
                sem_require(vector_push(&result.candidates, candidate));
            }
            if value.kind == KAddress { sem_known_write(result, value.value); }
            if value.kind == KAssign || value.kind == SurfaceAssign || value.kind == SurfaceModify
                || value.kind == SurfaceDefaultStore || value.kind == SurfaceInitializerStore {
                sem_known_write(result, value.target);
            }
        }
        if result.action == SemanticKnownAction.Order {
            if value.kind == KOperand && !value.constant {
                var binding = sem_known_binding(&context, value.binding);
                if binding != null && binding.owner == null && binding.ordinal >= result.source_ordinal {
                    sem_push(&result.mutations, value.binding);
                }
            }
            if value.kind == KCall && value.binding != null {
                sem_query_input(&context, value.binding, convert(u32, SemanticQuery.Body));
                sem_push(pending, sem_get(value.binding).body);
            }
        }
        if result.action == SemanticKnownAction.Publish {
            var declaration = value.kind == KDeclare;
            var binding = sem_known_binding(&context, declaration ? subject : value.kind == KOperand ? value.binding : null);
            if binding == null || binding.evaluation == null { continue; }
            var evaluation = sem_evaluation_get(&context, binding.evaluation);
            sem_query_input(&context, binding.evaluation, convert(u32, SemanticQuery.Evaluation));
            if !evaluation.ready.ready || evaluation.ready.failed { continue; }
            var patch: SemanticKnownPatch = default;
            patch.subject = subject;
            patch.literal = evaluation.literal;
            patch.declaration = declaration;
            sem_require(vector_push(&result.patches, patch));
        }
    }
    if result.action == SemanticKnownAction.Publish { sem_known_storage(&context, result, pending); }
    foreach(var list in &context.lists) { vector_dispose(bits(vector(void*)*, list)); }
    vector_dispose(&context.lists);
    foreach(var allocation in &context.allocations) { free(allocation); }
    vector_dispose(&context.allocations);
}

// A successful ordinary interpreter result permits removal of its runtime
// initializer. Build compacted indexes privately, keeping every lowered range
// intact until all ranges have been inspected. Rejected/effectful candidates
// retain their storage and execution order.
fn sem_known_storage(c: SemanticContext*, result: SemanticKnownWork*, nodes: vector(void*)*): void {
    var dropped = sem_table(c);
    var removed = sem_table(c);
    var dead = sem_list(c);
    foreach(var &patch in &result.patches) {
        if !patch.declaration { continue; }
        // Retain the declaration and its metadata without disabling the normal
        // immutability/staging proof or substituting its executable uses.
        if sem_get(patch.subject).attributes.length != 0 { continue; }
        var binding = sem_known_binding(c, patch.subject);
        if binding.block == null { continue; }
        var block = sem_get(binding.block);
        for(var at = binding.begin; at < binding.end; at++) {
            var item = block.items.data[at];
            if item != null {
                sem_state(c, dropped, item).number = 1;
                sem_push(dead, item);
            }
        }
    }
    for(var at: usize = 0; at < dead.length; at++) {
        var node = dead.data[at];
        if node == null { continue; }
        var mark = sem_state(c, removed, node);
        if mark.number != 0 { continue; }
        mark.number = 1;
        var value = sem_get(node);
        if value != null { sem_known_edges(dead, value); }
    }
    var containers = sem_table(c);
    foreach(var node in nodes) {
        if node == null { continue; }
        var value = sem_get(node);
        if value == null || (value.kind != KProgram && value.kind != KFunction && value.kind != KBlock) { continue; }
        var visit = sem_state(c, containers, node);
        if visit.number != 0 { continue; }
        visit.number = 1;
        var update: SemanticKnownStorage = default;
        update.subject = node;
        foreach(var item in &value.items) {
            update.replace_items ||= item == null || sem_find(dropped, null, item) != null;
        }
        foreach(var local in &value.locals) { update.replace_locals ||= sem_find(removed, null, local) != null; }
        if update.replace_items {
            foreach(var item in &value.items) {
                if item != null && sem_find(dropped, null, item) == null { sem_push(&update.items, item); }
            }
        }
        if update.replace_locals {
            foreach(var local in &value.locals) {
                if sem_find(removed, null, local) == null { sem_push(&update.locals, local); }
            }
        }
        if update.replace_items || update.replace_locals { sem_require(vector_push(&result.storage, update)); }
    }
}

fn sem_known_storage_publish(result: SemanticKnownWork*): void {
    foreach(var &update in &result.storage) {
        var value = sem_get(update.subject);
        if update.replace_items {
            vector_dispose(&value.items);
            value.items = update.items;
            update.items = default;
        }
        if update.replace_locals {
            vector_dispose(&value.locals);
            value.locals = update.locals;
            update.locals = default;
            if value.kind == KProgram || value.kind == KFunction {
                for(var at: usize = 0; at < value.locals.length; at++) { sem_get(value.locals.data[at]).index = at; }
            }
        }
    }
}

fn sem_known_kind(c: SemanticContext*): void* {
    var kind = sem_create(c.program.root);
    sem_require(entity_register(kind, sizeof(SemanticKnownWork), alignof(SemanticKnownWork), 0));
    return kind;
}

fn sem_known_job(c: SemanticContext*, kind: void*, subject: void*, root: void*, owner: void*, ordinal: usize,
    action: SemanticKnownAction): SemanticKnownWork* {
    var result = bits(SemanticKnownWork*, entity_component_data(entity_component_add(subject, kind)));
    sem_require(result != null);
    *result = default;
    result.context = c;
    result.subject = subject;
    result.root = root;
    result.owner = owner;
    result.ordinal = ordinal;
    result.action = action;
    result.kernel.kind = CompilerKernelKind.KnownBinding;
    result.kernel.payload = bits(void*, result);
    return result;
}

fn sem_known_jobs(c: SemanticContext*, kind: void*, count: usize, query_kind: SemanticQuery): vector(SemanticKnownWork*) {
    var jobs: vector(SemanticKnownWork*) = default;
    sem_require(vector_reserve(&jobs, count));
    jobs.length = count;
    fill(jobs.data, 0, count * sizeof(SemanticKnownWork*));
    var view = entity_view_open(c.program.root);
    sem_require(view != null);
    var query = entity_view_tables(view, &kind, 1);
    sem_require(query != null && entity_table_query_count(query) == count);
    for(var index: usize = 0; index < entity_table_query_ranges(query); index++) {
        var column = entity_table_query_column(query, index, 0);
        for(var row: usize = 0; row < entity_table_query_range_count(query, index); row++) {
            var result = bits(SemanticKnownWork*, entity_component_data(column[row]));
            sem_require(result.ordinal < count && jobs.data[result.ordinal] == null);
            jobs.data[result.ordinal] = result;
        }
    }
    entity_view_close(view);
    if count != 0 && c.workers.count == 0 { sem_require(sem_workers_open(c)); }
    foreach(var result in &jobs) {
        var id = work_request(&c.queries, result.subject, convert(u32, query_kind), 0);
        sem_require(id != 0);
        if query_kind == SemanticQuery.KnownScan || query_kind == SemanticQuery.KnownOrder {
            var proof = work_find(&c.queries, c.program.root, convert(u32, SemanticQuery.KnownProof), 0);
            sem_require(proof != 0 && work_depend(&c.queries, proof, id));
        }
        if query_kind == SemanticQuery.KnownInputs {
            var proof = work_find(&c.queries, c.program.root, convert(u32, SemanticQuery.KnownProof), 0);
            sem_require(proof != 0 && work_depend(&c.queries, id, proof));
        }
        var input_kind = query_kind == SemanticQuery.KnownPublish ? SemanticQuery.Lowering : SemanticQuery.Body;
        var input = work_find(&c.queries, result.subject, convert(u32, input_kind), 0);
        if input != 0 { sem_require(work_depend(&c.queries, id, input)); }
        sem_require(work_access(&c.queries, id, convert(u64, SemanticWorkDomain.Compiler),
            convert(u64, SemanticAccess.KnownAnalysis), result.ordinal, 1, WorkAccessMode.Write));
        sem_require(work_access(&c.queries, id, convert(u64, SemanticWorkDomain.Compiler),
            convert(u64, SemanticAccess.Body), 0, ~convert(usize, 0), WorkAccessMode.Read));
        sem_require(work_access(&c.queries, id, convert(u64, SemanticWorkDomain.Compiler),
            convert(u64, SemanticAccess.KnownBinding), 0, ~convert(usize, 0), WorkAccessMode.Read));
        sem_require(work_access(&c.queries, id, convert(u64, SemanticWorkDomain.Compiler),
            convert(u64, SemanticAccess.Expression), 0, ~convert(usize, 0), WorkAccessMode.Read));
        sem_require(work_access(&c.queries, id, convert(u64, SemanticWorkDomain.Compiler),
            convert(u64, SemanticAccess.Evaluation), 0, ~convert(usize, 0), WorkAccessMode.Read));
        sem_require(work_seal(&c.queries, id) && work_demand(&c.queries, id));
    }
    // Workers copy this frozen context, never the coordinator's changing
    // scheduler fields. Their only graph reads resolve already-published body
    // or evaluation inputs through the fixed task index. No tasks are added
    // until every worker joins; dependency receipts may grow the edge index.
    var context = *c;
    foreach(var result in &jobs) { result.context = &context; }
    view = entity_view_open(c.program.root);
    sem_require(view != null);
    var next: usize = 0;
    while next < count || c.workers.running != 0 {
        while next < count && c.workers.running < c.workers.count {
            var result = jobs.data[next++];
            sem_require(work_take_task(&c.queries, &result.ticket,
                work_find(&c.queries, result.subject, convert(u32, query_kind), 0)));
            sem_require(work_pool_submit(&c.workers, bits(void*, &result.kernel)));
        }
        var completed = bits(CompilerKernel*, work_pool_receive(&c.workers, true));
        sem_require(completed != null);
        var result = bits(SemanticKnownWork*, completed.payload);
        sem_query_observe(c, &result.ticket, &result.query_reads);
        sem_require(work_finish(&c.queries, &result.ticket, true));
    }
    entity_view_close(view);
    // Component results stay private until the caller publishes this stable
    // source-ordered vector. A slow job no longer stalls unrelated ready jobs.
    foreach(var result in &jobs) { result.context = null; }
    return jobs;
}

fn sem_known_jobs_dispose(jobs: vector(SemanticKnownWork*)*): void {
    foreach(var job in jobs) {
        vector_dispose(&job.candidates);
        vector_dispose(&job.mutations);
        vector_dispose(&job.patches);
        vector_dispose(&job.query_reads);
        foreach(var &update in &job.storage) {
            vector_dispose(&update.items);
            vector_dispose(&update.locals);
        }
        vector_dispose(&job.storage);
        job.context = null;
    }
    vector_dispose(jobs);
}

import tower;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_support;
import semantic_types;
import semantic_layout_kernel;
import semantic_work_ids;
import compiler_kernel;
import .library.vector;
import .library.work_graph;
import .library.work_pool;

extern fn entity_view_open(anchor: void*): void*;
extern fn entity_view_close(view: void*): void;

fn sem_layout_dependency(c: SemanticContext*, consumer: usize, type: FoundationType*): void {
    if semantic_aggregate(type) {
        var dependency = work_request(&c.queries, type.record, convert(u32, SemanticQuery.Layout), 0);
        sem_require(dependency != 0);
        sem_require(work_depend(&c.queries, consumer, dependency));
        sem_require(work_access(&c.queries, consumer, convert(u64, SemanticWorkDomain.Compiler), convert(u64, SemanticAccess.Layout), dependency, 1, WorkAccessMode.Read));
    }
}

fn sem_layout_discover(c: SemanticContext*, n: void*): usize {
    var graph = &c.queries;
    var first = graph.tasks.length;
    var root = work_request(graph, n, convert(u32, SemanticQuery.Layout), 0);
    sem_require(root != 0);
    if c.layout_results == null {
        c.layout_results = sem_create(c.program.root);
        sem_require(entity_register(c.layout_results, sizeof(SemanticLayoutWork), alignof(SemanticLayoutWork), 0));
    }
    var index = first;
    while index < graph.tasks.length {
        var id = index + 1;
        var task = work_task(graph, id);
        var subject = task.subject;
        var type = sem_get(subject);
        var component = entity_component_add(subject, c.layout_results);
        var result = bits(SemanticLayoutWork*, entity_component_data(component));
        sem_require(result != null);
        fill(result, 0, sizeof(SemanticLayoutWork));
        result.subject = subject;
        result.kernel.kind = CompilerKernelKind.Layout;
        result.kernel.payload = bits(void*, result);
        if type.type.scalar == SStruct && !semantic_enum(&type.type) {
            sem_require(vector_reserve(usize, &result.offsets, type.items.length));
            result.offsets.length = type.items.length;
        }
        sem_require(vector_push(void*, &c.layout_jobs, bits(void*, result)));
        sem_require(work_access(graph, id, convert(u64, SemanticWorkDomain.Compiler), convert(u64, SemanticAccess.Layout), id, 1, WorkAccessMode.Write));
        if type.type.scalar == SArray {
            sem_layout_dependency(c, id, &type.element);
        } else {
            if !semantic_enum(&type.type) {
                foreach(var & item in &type.items) {
                    var field = sem_get(*item);
                    sem_layout_dependency(c, id, &field.type);
                }
            }
        }
        sem_require(work_seal(graph, id));
        index++;
    }
    sem_require(work_demand(graph, root));
    return root;
}

fn sem_layout_cycle(c: SemanticContext*, root: usize): void {
    var graph = &c.queries;
    var task = work_task(graph, root);
    if task.state == WorkState.Succeeded { return; }
    var subject = task.subject;
    var cycle: vector(usize);
    vector_init(&cycle);
    var found = work_cycle(graph, root, &cycle);
    sem_require(work_ok(graph));
    var chain: u8* = "";
    var index: usize = 0;
    while found && index < cycle.length {
        task = work_task(graph, cycle.data[index]);
        if index != 0 { chain = sem_cat(c, chain, " -> "); }
        chain = sem_cat(c, chain, sem_name(sem_get(task.subject)));
        index++;
    }
    vector_dispose(&cycle);
    sem_fail(c, subject, sem_cat(c, "Recursive by-value layout: ", sem_cat(c, chain, "; use a pointer")));
}

fn sem_layout_execute(c: SemanticContext*): void {
    if c.workers.count == 0 {
        sem_require(sem_workers_open(c));
    }
    // All component allocation occurs before pinning. No worker performs an
    // entity mutation or uses the coordinator's semantic scratch/diagnostics.
    var view = entity_view_open(c.program.root);
    sem_require(view != null);
    var failed: SemanticLayoutWork* = null;
    loop {
        var ticket: WorkTicket;
        while c.workers.running < c.workers.count
            && work_take_query(&c.queries, &ticket, convert(u32, SemanticQuery.Layout)) {
            var task = work_task(&c.queries, ticket.task);
            sem_require(task.query == convert(u32, SemanticQuery.Layout));
            var component = entity_component_get(task.subject, c.layout_results);
            var result = bits(SemanticLayoutWork*, entity_component_data(component));
            result.ticket = ticket;
            sem_require(work_pool_submit(&c.workers, bits(void*, &result.kernel)));
        }
        if c.workers.running == 0 { break; }
        var completed = bits(CompilerKernel*, work_pool_receive(&c.workers, true));
        sem_require(completed != null);
        var result = bits(SemanticLayoutWork*, completed.payload);
        var success = result.error == null;
        if success {
            // The query owns this layout's write range. Its consumers cannot
            // run until these fields publish and work_finish releases them;
            // unrelated layouts can keep running under the same pinned view.
            var type = sem_get(result.subject);
            type.size = result.size;
            type.alignment = result.alignment;
            for(var field: usize = 0; field < result.offsets.length; field++) {
                sem_get(type.items.data[field]).byte_offset = result.offsets.data[field];
            }
        } else {
            // Completion order must not choose the diagnostic. Drain every
            // independent ready query and select the first discovery ordinal.
            if failed == null || result.ticket.task < failed.ticket.task { failed = result; }
        }
        sem_require(work_finish(&c.queries, &result.ticket, success));
    }
    entity_view_close(view);
    if failed != null { sem_fail(c, failed.error_node, failed.error); }
}

fn sem_layout(c: SemanticContext*, n: void*): void {
    if !sem_ok(c) { return; }
    // Body workers only consume completed layouts. Avoid touching the shared
    // demand scratch/index for an already-published result.
    var known = work_find(&c.queries, n, convert(u32, SemanticQuery.Layout), 0);
    if known != 0 && work_task(&c.queries, known).state == WorkState.Succeeded {
        sem_query_read(c, known);
        return;
    }
    // A worker can only consume a published layout. Structural construction
    // belongs to its coordinator continuation, including failed-type retries.
    sem_require(c.entity_stage == null);
    var root = sem_layout_discover(c, n);
    if work_task(&c.queries, root).state == WorkState.Succeeded {
        sem_query_read(c, root);
        return;
    }
    sem_layout_execute(c);
    if sem_ok(c) { sem_layout_cycle(c, root); }
    if sem_ok(c) { sem_query_read(c, root); }
}

fn sem_layout_all(c: SemanticContext*): void {
    if !sem_ok(c) { return; }
    // The registry is append-only within a compilation. Inspect each new type
    // once, including queries discovered earlier by declarations. This is an
    // admission frontier, never a cross-revision/type-identity cache.
    var pending: vector(usize) = default;
    defer vector_dispose(&pending);
    var index = c.layout_checked;
    while index < c.program.types.length {
        var type = c.program.types.data[index];
        if sem_get(type).type.record != null && sem_get(type).type.scalar != SFunction {
            var query = sem_layout_discover(c, type);
            if work_task(&c.queries, query).state != WorkState.Succeeded {
                sem_require(vector_push(&pending, query));
            }
        }
        index++;
    }
    if pending.length != 0 { sem_layout_execute(c); }
    foreach(var query in &pending) { if sem_ok(c) { sem_layout_cycle(c, query); } }
    if sem_ok(c) { c.layout_checked = index; }
}

fn sem_layout_dispose(c: SemanticContext*): void {
    work_pool_close(&c.workers);
    var index: usize = 0;
    while index < c.layout_jobs.length {
        var result = bits(SemanticLayoutWork*, c.layout_jobs.data[index]);
        vector_dispose(&result.offsets);
        index++;
    }
    vector_dispose(&c.layout_jobs);
}

import tower;
import compiler_kernel;
import foundation_types;
import foundation_tags;
import .library.vector;
import .library.work_graph;

extern fn sem_get(node: void*): FoundationNode*;
extern fn semantic_size(type: FoundationType*): usize;
extern fn semantic_alignment(type: FoundationType*): usize;
extern fn semantic_enum(type: FoundationType*): bool;

var LayoutMaximumBytes: usize = 4194304;

// A derived pending result component on the same type entity. FoundationNode
// remains authoritative; the coordinator publishes this result before releasing
// dependents. Workers cannot mutate diagnostics, entity structure or scheduler.
struct SemanticLayoutWork {
    kernel: CompilerKernel;
    ticket: WorkTicket;
    subject: void*;
    size: usize;
    alignment: usize;
    offsets: vector(usize);
    error: u8*;
    error_node: void*;
}

fn layout_round(size: usize, alignment: usize): usize {
    var extra = size % alignment;
    return extra == 0 ? size : size + alignment - extra;
}

fn semantic_layout_kernel(result: SemanticLayoutWork*): void {
    var type = sem_get(result.subject);
    result.size = 0;
    result.alignment = 1;
    result.error = null;
    result.error_node = result.subject;
    if semantic_enum(&type.type) {
        result.size = semantic_size(&type.element);
        result.alignment = semantic_alignment(&type.element);
        return;
    }
    if type.type.scalar == SArray {
        var size = semantic_size(&type.element);
        if type.length == 0 {
            result.error = "An array needs a positive length";
            return;
        }
        if size > LayoutMaximumBytes / type.length {
            result.error = "Array storage exceeds 4 MiB";
            return;
        }
        result.size = size * type.length;
        result.alignment = semantic_alignment(&type.element);
        return;
    }
    var index: usize = 0;
    while index < type.items.length {
        var field = sem_get(type.items.data[index]);
        var alignment = semantic_alignment(&field.type);
        if alignment > result.alignment { result.alignment = alignment; }
        var offset = layout_round(result.size, alignment);
        var size = semantic_size(&field.type);
        if offset > LayoutMaximumBytes || size > LayoutMaximumBytes - offset {
            result.error = "Foundation struct storage exceeds 4 MiB";
            result.error_node = type.items.data[index];
            return;
        }
        result.offsets.data[index] = offset;
        result.size = offset + size;
        index++;
    }
    result.size = layout_round(result.size, result.alignment);
    if result.size == 0 { result.size = 1; }
}

import semantic_program_types;
import tower;
import semantic_attributes;
import foundation_tags;
import foundation_types;
import semantic_context;
import semantic_definitions;
import semantic_statements;
import semantic_defer;
import semantic_support;
import semantic_expression_lowering;
import semantic_layout;
import semantic_evaluation;
