// Semantic compiler over shared Foundation components.
// Temporary indexes and scratch allocations are scoped to one compilation.

fn sem_track(c: SemanticContext*, data: u8*): void {
    var step1 = bits(void*, data);
    sem_require(vector_push(&c.allocations, step1));
}

fn sem_context_init(c: SemanticContext*, program: SemanticProgram*): void {
    var step1 = sizeof(SemanticContext);
    fill(c, 0, step1);
    c.program = program;
    c.current = program.root;
    c.node_limit = SemanticComponentBudgetBytes / sizeof(FoundationNode);
    var step2 = sem_table(c);
    c.functions = step2;
    var step3 = sem_table(c);
    c.types = step3;
    var step4 = sem_table(c);
    c.globals = step4;
    var step5 = sem_table(c);
    c.templates = step5;
    var step6 = sem_table(c);
    c.type_functions = step6;
    var step7 = sem_table(c);
    c.type_results = step7;
    var step8 = sem_table(c);
    c.source_names = step8;
    var step9 = sem_table(c);
    c.source_bases = step9;
    c.output_names = sem_table(c);
    var step10 = sem_table(c);
    c.fields_done = step10;
    work_init(&c.queries, 1, convert(u64, program.pointer_bytes));
    var step13 = sem_scope(c, null);
    c.scope = step13;
    foreach(var n in &program.types) {
        var step17 = sem_name(sem_get(n));
        sem_put(c, c.types, step17, n);
    }
}

fn sem_context_dispose(c: SemanticContext*): void {
    sem_layout_dispose(c);
    sem_evaluation_dispose(c);
    vector_dispose(&c.flow_dependencies);
    sem_declaration_dispose(c);
    stack_dispose(&c.scan);
    vector_dispose(&c.token_text);
    work_dispose(&c.queries);
    var i: usize = 0;
    for(; i < c.lists.length; i++) {
        var step3 = bits(vector(void*)*, c.lists.data[i]);
        vector_dispose(step3);
    }
    vector_dispose(&c.lists);
    vector_dispose(&c.type_arguments);
    vector_dispose(&c.constant_arguments);
    vector_dispose(&c.generated);
    vector_dispose(&c.template_nodes);
    vector_dispose(&c.inferring);
    i = 0;
    for(; i < c.allocations.length; i++) {
        free(c.allocations.data[i]);
    }
    vector_dispose(&c.allocations);
}

export fn semantic_initialize(program: SemanticProgram*, root: void*, width: u32): void {
    var step1 = sizeof(SemanticProgram);
    fill(program, 0, step1);
    program.pointer_bytes = width;
    program.root = root;
    var n: FoundationNode* = sem_attach(root, KProgram);
    n.type.scalar = SVoid;
    sem_push(&program.functions, root);
    var scalar: u32 = 0;
    loop {
        if scalar >= FoundationScalarLimit {
            break;
        }
        if scalar == SStruct || scalar == SArray || scalar == SFunction {
            scalar++;
            continue;
        }
        var entity: void* = sem_create(root);
        var t: FoundationNode* = sem_attach(entity, KType);
        t.type.scalar = scalar;
        t.type.pointer_bytes = width;
        var step8 = semantic_scalar_name(scalar);
        sem_set_name(t, step8);
        var step9 = semantic_size(&t.type);
        t.size = step9;
        var step10 = semantic_alignment(&t.type);
        t.alignment = step10;
        sem_push(&program.types, entity);
        scalar++;
    }
}

export fn semantic_compile_budget(program: SemanticProgram*, roots: void**, bases: usize*, count: usize, source: u8*, component_bytes: usize): void {
    var context: SemanticContext;
    var c: SemanticContext* = &context;
    sem_context_init(c, program);
    c.node_limit = component_bytes / sizeof(FoundationNode);
    c.source = source;
    var step1 = generic_begin(program.root);
    c.generics = step1;
    for(var i: usize = 0; i < count; i++) {
        var step4 = sem_state(c, c.source_bases, roots[i]);
        step4.number = bases[i];
    }
    sem_run(c);
    sem_defer_hygiene(c);
    sem_known_infer(c);
    sem_lower_expressions(c);
    sem_defer_validate(c);
    sem_evaluations(c);
    sem_attributes_publish(c);
    sem_known_publish(c);
    sem_module_initializers(c);
    sem_flows(c);
    sem_context_dispose(c);
}

export fn semantic_compile(program: SemanticProgram*, roots: void**, bases: usize*, count: usize, source: u8*): void {
    semantic_compile_budget(program, roots, bases, count, source, SemanticComponentBudgetBytes);
}

export fn semantic_program_dispose(program: SemanticProgram*): void {
    vector_dispose(&program.functions);
    vector_dispose(&program.types);
    vector_dispose(&program.error);
}

export fn semantic_format_type(t: FoundationType*, output: vector(u8)*): void {
    var context: SemanticContext;
    var program: SemanticProgram;
    var step1 = sizeof(SemanticContext);
    fill(&context, 0, step1);
    var step2 = sizeof(SemanticProgram);
    fill(&program, 0, step2);
    context.program = &program;
    var text: u8* = sem_type_name(&context, t);
    var count: usize = sem_length(text);
    var step5 = count + 1;
    sem_require(vector_reserve(output, step5));
    var step7 = count + 1;
    copy(output.data, text, step7);
    output.length = count;
    sem_context_dispose(&context);
}

export fn semantic_format_number(value: u64, t: FoundationType*, output: vector(u8)*): void {
    var context: SemanticContext;
    var step1 = sizeof(SemanticContext);
    fill(&context, 0, step1);
    var text: u8* = sem_number(&context, value, t);
    var count: usize = sem_length(text);
    var step4 = count + 1;
    sem_require(vector_reserve(output, step4));
    var step6 = count + 1;
    copy(output.data, text, step6);
    output.length = count;
    sem_context_dispose(&context);
}

import tower;
import compiler_kernel;
import semantic_context;
import semantic_program_types;
import semantic_control;
import semantic_support;
import semantic_expression_lowering;
import semantic_aggregates;
import semantic_evaluation;
import semantic_work_ids;
import .library.vector;
import .library.stack;
import .library.work_graph;
import .library.work_pool;

struct SemanticLowering {
    kernel: CompilerKernel;
    ticket: WorkTicket;
    context: SemanticContext*;
    subject: void*;
    block: void*;
    stage: void*;
    ordinal: usize;
    count: usize;
    error: vector(u8);
    error_offset: usize;
    query_reads: vector(usize);
    signature: bool;
    evaluation_aliases: vector(SemanticEvaluationAlias);
}

extern fn entity_view_open(anchor: void*): void*;
extern fn entity_view_close(view: void*): void;

fn semantic_lowering_kernel(result: SemanticLowering*): void {
    var context = *result.context;
    var program = *context.program;
    context.program = &program;
    context.editor = null;
    context.current = result.subject;
    context.entity_stage = result.stage;
    context.query_reads = &result.query_reads;
    context.evaluation_aliases = &result.evaluation_aliases;
    context.control_reserved = context.control_names;
    context.control_names = null;
    context.count = 0;
    context.node_limit -= result.context.count;
    vector_init(void*, &context.allocations);
    vector_init(void*, &context.lists);
    vector_init(u8, &context.token_text);
    fill(&context.scan, 0, sizeof(stack(void*)));
    vector_init(u8, &program.error);
    context.control_prefix = sem_cat(&context, result.signature ? "aggregate value " : "control value ",
        sem_cat(&context, sem_decimal(&context, convert(u64, result.ordinal)), "."));
    if result.signature { sem_aggregate_function(&context, result.subject); }
    else { sem_lift_block(&context, result.block); }
    result.count = context.count;
    result.error = program.error;
    result.error_offset = program.error_offset;
    stack_dispose(void*, &context.scan);
    vector_dispose(u8, &context.token_text);
    for(var i: usize = 0; i < context.lists.length; ++i) {
        vector_dispose(void*, bits(vector(void*)*, context.lists.data[i]));
    }
    vector_dispose(void*, &context.lists);
    for(var i: usize = 0; i < context.allocations.length; ++i) { free(context.allocations.data[i]); }
    vector_dispose(void*, &context.allocations);
}

fn sem_lower_parallel(c: SemanticContext*): void {
    sem_lower_transform(c, false);
}

fn sem_lower_transform(c: SemanticContext*, signature: bool): void {
    if !sem_ok(c) || (!signature && !c.surface_expressions) { return; }
    // Source spellings and names produced by earlier control lowering are frozen
    // before dispatch. Every function owns its generated-name table and prefix.
    sem_control_names(c);
    var kind: void* = null;
    var query_kind = convert(u32, signature ? SemanticQuery.AggregatePrepare : SemanticQuery.Lowering);
    for(var i: usize = 0; i < c.program.functions.length; ++i) {
        var subject = c.program.functions.data[i];
        var block = i == 0 ? subject : sem_get(subject).body;
        if block == null { continue; }
        if signature && (i == 0 || !sem_aggregate_needed(subject)) { continue; }
        if kind == null {
            kind = sem_create(c.program.root);
            sem_require(entity_register(kind, sizeof(SemanticLowering), alignof(SemanticLowering), 0));
        }
        if signature {
            if c.aggregate_signatures == null {
                c.aggregate_signatures = sem_create(c.program.root);
                sem_require(entity_register(c.aggregate_signatures, sizeof(SemanticAggregateSignature), alignof(SemanticAggregateSignature), 0));
            }
            var metadata = bits(SemanticAggregateSignature*, entity_component_data(entity_component_add(subject, c.aggregate_signatures)));
            sem_require(metadata != null);
            *metadata = default;
        }
        var result = bits(SemanticLowering*, entity_component_data(entity_component_add(subject, kind)));
        sem_require(result != null);
        fill(result, 0, sizeof(SemanticLowering));
        result.context = c;
        result.subject = subject;
        result.block = block;
        result.ordinal = i;
        result.signature = signature;
        result.kernel.kind = CompilerKernelKind.Lower;
        result.kernel.payload = bits(void*, result);
        var id = work_request(&c.queries, subject, query_kind, 0);
        sem_require(id != 0);
        var body = work_find(&c.queries, subject, convert(u32, SemanticQuery.Body), 0);
        if body != 0 { sem_require(work_depend(&c.queries, id, body)); }
        if !signature {
            var preparation = work_find(&c.queries, subject, convert(u32, SemanticQuery.AggregatePrepare), 0);
            if preparation != 0 { sem_require(work_depend(&c.queries, id, preparation)); }
        }
        // Disjoint function payload ranges; layout/type inputs are immutable.
        // Generated entities remain private until the publication barrier.
        var domain = convert(u64, SemanticWorkDomain.Compiler);
        sem_require(work_access(&c.queries, id, domain,
            convert(u64, signature ? SemanticAccess.Aggregate : SemanticAccess.Lowering), i, 1, WorkAccessMode.Write));
        sem_require(work_access(&c.queries, id, domain, convert(u64, SemanticAccess.Body), i, 1, WorkAccessMode.Write));
        sem_require(work_access(&c.queries, id, domain, convert(u64, SemanticAccess.Layout), 0, ~convert(usize, 0), WorkAccessMode.Read));
        if !signature {
            sem_require(work_access(&c.queries, id, domain, convert(u64, SemanticAccess.Aggregate), 0, ~convert(usize, 0), WorkAccessMode.Read));
        }
        sem_require(work_seal(&c.queries, id));
        sem_require(work_demand(&c.queries, id));
    }
    if kind == null { return; }
    if signature { c.surface_expressions = true; }
    if c.workers.count == 0 { sem_require(sem_workers_open(c)); }
    var batch: vector(SemanticLowering*) = default;
    defer vector_dispose(&batch);
    sem_require(vector_reserve(&batch, SemanticPreparationWindow));
    while sem_ok(c) {
        var count: usize = 0;
        var ticket: WorkTicket;
        while count < SemanticPreparationWindow && work_take_query(&c.queries, &ticket, query_kind) {
            var subject = work_task(&c.queries, ticket.task).subject;
            var result = bits(SemanticLowering*, entity_component_data(entity_component_get(subject, kind)));
            result.ticket = ticket;
            // The immutable work-kind entity anchors this wave. The program
            // root can itself be leased by its own lowering job.
            result.stage = entity_stage_open(kind);
            sem_require(result.stage != null);
            sem_require(entity_stage_lease(result.stage, result.subject));
            if signature {
                foreach(var parameter in &sem_get(result.subject).parameters) {
                    sem_require(entity_stage_lease(result.stage, parameter));
                }
            }
            batch.data[count] = result;
            count++;
        }
        if count == 0 { break; }
        var view = entity_view_open(kind);
        sem_require(view != null);
        var context = *c;
        var next: usize = 0;
        while next < count || c.workers.running != 0 {
            while next < count && c.workers.running < c.workers.count {
                var result = batch.data[next++];
                result.context = &context;
                sem_require(work_pool_submit(&c.workers, bits(void*, &result.kernel)));
            }
            sem_require(work_pool_receive(&c.workers, true) != null);
        }
        entity_view_close(view);
        for(var i: usize = 0; i < count; ++i) {
            sem_require(entity_stage_publish(batch.data[i].stage));
            batch.data[i].stage = null;
            batch.data[i].context = null;
        }
        for(var i: usize = 0; i < count; ++i) {
            var result = batch.data[i];
            sem_query_observe(c, &result.ticket, &result.query_reads);
            // Even a failed function owns its generated nodes until the failed
            // program is destroyed. Publish them so ordinary lifecycle cleanup
            // handles all canonical links without dangling staged references.
            sem_evaluation_aliases(c, &result.evaluation_aliases);
            c.count += result.count;
            if result.error.length != 0 && sem_ok(c) {
                sem_require(vector_reserve(u8, &c.program.error, result.error.length + 1));
                copy(c.program.error.data, result.error.data, result.error.length + 1);
                c.program.error.length = result.error.length;
                c.program.error_offset = result.error_offset;
            }
            if c.count > c.node_limit { sem_fail(c, result.subject, "Foundation component memory budget exceeded"); }
            var success = result.error.length == 0 && c.count <= c.node_limit;
            sem_require(work_finish(&c.queries, &result.ticket, success));
            vector_dispose(u8, &result.error);
            vector_dispose(&result.query_reads);
            vector_dispose(&result.evaluation_aliases);
        }
    }
    for(var i: usize = 0; i < c.program.functions.length; ++i) {
        var data = entity_component_data(entity_component_get(c.program.functions.data[i], kind));
        if data != null { bits(SemanticLowering*, data).context = null; }
    }

}

import tower;
import foundation_tags;
import frontend_compilation;
import semantic_context;
import semantic_definitions;
import semantic_support;
import semantic_known_bindings;
import semantic_evaluation;

// Ownership/import components live on the same retained parse entities. The
// registry and lookup tables are compilation-local indexes, not another IR.
// Text is owned by ordinary entity relationship names; no context allocation
// escapes into a retained component. Foundation output encodes resolved bindings.
import semantic_program_types;

struct SemanticModuleLink {
    module: void*;
    base: usize;
    cyclic: bool;
}

extern fn frontend_module_name(module: void*): u8*;
extern fn frontend_module_cyclic(module: void*): bool;

extern fn frontend_module_import_count(module: void*): usize;

extern fn frontend_module_import_at(module: void*, index: usize): void*;

extern fn frontend_module_dependency_at(module: void*, index: usize): void*;

extern fn frontend_module_alias(module: void*, index: usize): u8*;

extern fn entity_child_name(node: void*, index: usize): u8*;

fn sem_module_kind(parent: void*, size: usize, alignment: usize): void* {
    var kind = sem_create(parent);
    sem_require(entity_register(kind, size, alignment, 0));
    return kind;
}

fn sem_modules_begin(program: SemanticProgram*): SemanticModules* {
    if program.modules != null {
        return program.modules;
    }
    var registry = entity_create_related(program.root);
    sem_require(entity_register(registry, sizeof(SemanticModules), alignof(SemanticModules), 0));
    var component = entity_component_add(program.root, registry);
    var modules = bits(SemanticModules*, entity_component_data(component));
    var present = modules != null;
    sem_require(present);
    fill(modules, 0, sizeof(SemanticModules));
    modules.root = registry;
    modules.owner_kind = sem_module_kind(registry, sizeof(SemanticModuleLink), alignof(SemanticModuleLink));
    modules.import_kind = sem_module_kind(registry, sizeof(SemanticModuleLink), alignof(SemanticModuleLink));
    modules.scopes = sem_create(registry);
    program.modules = modules;
    entity_release(registry);
    return modules;
}

fn sem_module_scope(program: SemanticProgram*, module: void*): void* {
    var registry = sem_modules_begin(program);
    var path = frontend_module_name(module);
    var scope = sem_member(registry.scopes, path);
    var missing = scope == null;
    if missing {
        scope = entity_create_related(registry.scopes);
        sem_require(entity_attach(scope, registry.scopes, path));
        entity_release(scope);
    }
    return scope;
}

fn sem_module_link(node: void*, kind: void*, scope: void*): void {
    var component = entity_component_add(node, kind);
    var link = bits(SemanticModuleLink*, entity_component_data(component));
    var present = link != null;
    sem_require(present);
    link.module = scope;
    link.base = 0;
    link.cyclic = false;
}

fn sem_module_position(program: SemanticProgram*, module: void*, base: usize): void {
    var scope = sem_module_scope(program, module);
    sem_module_link(scope, program.modules.owner_kind, scope);
    var component = entity_component_get(scope, program.modules.owner_kind);
    var link = bits(SemanticModuleLink*, entity_component_data(component));
    link.base = base;
    link.cyclic = frontend_module_cyclic(module);
}

// Parsing defers ordinary variable initialization in cycles to the same semantic
// proof used everywhere else. Metadata-bearing fixed bindings retain their
// declarations; their proved values have no initialization-order dependency.
fn sem_module_initializers(c: SemanticContext*): void {
    if !sem_ok(c) || c.program.modules == null { return; }
    foreach(var node in &sem_get(c.program.root).items) {
        if sem_get(node).kind != KDeclare { continue; }
        var owner = sem_owner(c, node);
        if owner == null { continue; }
        var link = bits(SemanticModuleLink*, entity_component_data(entity_component_get(owner, c.program.modules.owner_kind)));
        if link != null && link.cyclic {
            var binding = sem_known_binding(c, node);
            if binding != null && binding.immutable && binding.ordered && binding.evaluation != null {
                var evaluation = sem_evaluation_get(c, binding.evaluation);
                if evaluation.ready.ready && !evaluation.ready.failed { continue; }
            }
            sem_fail(c, node, "Import cycle requires fixed compile-time variable initializers; runtime initialization has no dependency-first order");
            return;
        }
    }
}

fn sem_module_record(program: SemanticProgram*, module: void*): void {
    var registry = sem_modules_begin(program);
    var scope = sem_module_scope(program, module);
    var count = frontend_module_roots(module);
    var i: usize = 0;
    for(; i < count; i++) {
        sem_module_link(frontend_module_tree(module, i), registry.owner_kind, scope);
    }
    count = frontend_module_import_count(module);
    i = 0;
    for(; i < count; i++) {
        var declaration = frontend_module_import_at(module, i);
        // Recovered editor parses may contribute a second source snapshot.
        // Each actual declaration keeps its own components and source spans.
        if entity_component_get(declaration, registry.import_kind) == null {
            var dependency = frontend_module_dependency_at(module, i);
            var target = sem_module_scope(program, dependency);
            var alias = frontend_module_alias(module, i);
            // Inspection retains the source wrapper too. Move the complete
            // tree so its children, roles and hover spans stay intact.
            var tree = sem_parent(declaration);
            if tree == null {
                tree = declaration;
            }
            sem_require(entity_attach(tree, scope, alias));
            sem_module_link(tree, registry.import_kind, target);
            sem_module_link(declaration, registry.import_kind, target);
            sem_module_link(declaration, registry.owner_kind, scope);
        }
    }
}

fn sem_module_graph(program: SemanticProgram*, module: void*): void {
    sem_module_record(program, module);
    var count = frontend_module_count(module);
    for(var i: usize = 0; i < count; i++) {
        var dependency = frontend_module_at(module, i);
        sem_module_record(program, dependency);
    }
}

fn sem_owner(c: SemanticContext*, node: void*): void* {
    var registry = c.program.modules;
    if registry == null {
        return null;
    }
    while node != null {
        var component = entity_component_get(node, registry.owner_kind);
        var link = bits(SemanticModuleLink*, entity_component_data(component));
        if link != null {
            return link.module;
        }
        if c.generics != null {
            var original = generic_definition(c.generics, node);
            if original != node {
                node = original;
                continue;
            }
        }
        node = sem_parent(node);
    }
    return null;
}

fn sem_module_path(c: SemanticContext*, module: void*): u8* {
    var scopes = c.program.modules.scopes;
    var count = sem_child_count(scopes);
    for(var i: usize = 0; i < count; i++) {
        if sem_child(scopes, i) == module {
            return entity_child_name(scopes, i);
        }
    }
    return "";
}

fn sem_owned(table: SemanticTable*, module: void*, name: u8*): void* {
    var entry = sem_find(table, name, module);
    if entry != null {
        return entry.value;
    }
    return null;
}

fn sem_define(c: SemanticContext*, table: SemanticTable*, node: void*, name: u8*): bool {
    var owner = sem_owner(c, node);
    var entry = sem_entry(c, table, name, owner);
    if entry.value != null {
        return false;
    }
    entry.value = node;
    return true;
}

fn sem_local(c: SemanticContext*, name: u8*): void* {
    var scope = c.scope;
    while scope != null {
        var found = sem_lookup_table(scope.names, name);
        if found != null {
            return found;
        }
        scope = scope.parent;
    }
    return null;
}

fn sem_import_target(c: SemanticContext*, edge: void*): void* {
    var component = entity_component_get(edge, c.program.modules.import_kind);
    var link = bits(SemanticModuleLink*, entity_component_data(component));
    if link != null {
        return link.module;
    }
    return null;
}

fn sem_import_alias(owner: void*, index: usize): u8* {
    var name = entity_child_name(owner, index);
    if name == null {
        return "";
    }
    return name;
}

fn sem_alias(c: SemanticContext*, owner: void*, name: u8*): void* {
    var i: usize = 0;
    var count = sem_child_count(owner);
    for(; i < count; i++) {
        var alias = sem_import_alias(owner, i);
        if sem_equal(alias, name) {
            return sem_import_target(c, sem_child(owner, i));
        }
    }
    return null;
}

fn sem_visible(c: SemanticContext*, table: SemanticTable*, node: void*, owner: void*, name: u8*): void* {
    var found = sem_owned(table, owner, name);
    if found != null {
        return found;
    }
    if owner == null {
        return null;
    }
    var count = sem_child_count(owner);
    for(var i: usize = 0; i < count; i++) {
        var alias = sem_import_alias(owner, i);
        if alias[0] == 0 {
            var target = sem_import_target(c, sem_child(owner, i));
            var candidate = sem_owned(table, target, name);
            if candidate != null {
                var different = found != null;
                different &&= found != candidate;
                if different {
                    sem_fail(c, node, sem_cat(c, "Ambiguous imported name '", sem_cat(c, name, "'; use an import alias")));
                    return null;
                }
                found = candidate;
            }
        }
    }
    if found == null {
        // Only the reflected Foundation primitive types are ownerless.
        var types = table == c.types;
        if types {
            found = sem_owned(table, null, name);
        }
    }
    return found;
}

fn sem_name_node(node: void*): void* {
    loop {
        var base = sem_member(node, "base");
        if base != null {
            return node;
        }
        var name = sem_member(node, "name");
        if name != null {
            node = name;
        } else {
            return node;
        }
    }
}

fn sem_callable_owned(c: SemanticContext*, owner: void*, name: u8*): void* {
    var found = sem_owned(c.functions, owner, name);
    var missing = found == null;
    if missing {
        found = sem_owned(c.templates, owner, name);
    }
    missing = found == null;
    if missing {
        found = sem_owned(c.type_functions, owner, name);
    }
    return found;
}

fn sem_foreign_same_name(left: void*, right: void*): bool {
    var a = sem_get(left);
    var b = sem_get(right);
    if a == null || b == null { return false; }
    return a.kind == KFunction && b.kind == KFunction
        && (a.external || a.exported) && (b.external || b.exported)
        && sem_equal(sem_name(a), sem_name(b));
}

fn sem_callable_visible(c: SemanticContext*, table: SemanticTable*, node: void*, owner: void*, name: u8*): void* {
    var local = sem_callable_owned(c, owner, name);
    var present = local != null;
    if present {
        return sem_owned(table, owner, name);
    }
    var selected: void* = null;
    var found: void* = null;
    var i: usize = 0;
    var count = sem_child_count(owner);
    for(; i < count; i++) {
        var alias = sem_import_alias(owner, i);
        if alias[0] == 0 {
            var dependency = sem_import_target(c, sem_child(owner, i));
            var candidate = sem_callable_owned(c, dependency, name);
            present = candidate != null;
            if present {
                var different = found != null;
                different &&= found != candidate;
                // Foreign declarations of one link symbol are validated and
                // coalesced after signature queries finish. They must remain
                // name-resolvable while those queries are still pending.
                if different && sem_foreign_same_name(found, candidate) { different = false; }
                if different {
                    sem_fail(c, node, sem_cat(c, "Ambiguous imported name '", sem_cat(c, name, "'; use an import alias")));
                    return null;
                }
                found = candidate;
                selected = dependency;
            }
        }
    }
    return sem_owned(table, selected, name);
}

fn sem_resolve(c: SemanticContext*, table: SemanticTable*, node: void*, spelling: u8*): void* {
    return sem_resolve_from(c, table, node, spelling, sem_owner(c, node));
}

fn sem_resolve_from(c: SemanticContext*, table: SemanticTable*, node: void*, spelling: u8*, owner: void*): void* {
    var name = sem_name_node(node);
    if sem_member(name, "index") != null {
        return null;
    }
    var base = sem_member(name, "base");
    var field = sem_member(name, "field");
    var qualified = base != null;
    qualified &&= field != null;
    if qualified {
        var target = sem_namespace_from(c, name, owner);
        if target != null {
            return sem_owned(table, target, sem_identifier(c, field));
        }
        return null;
    }
    var callable = table == c.functions;
    callable ||= table == c.templates;
    callable ||= table == c.type_functions;
    if callable {
        return sem_callable_visible(c, table, node, owner, spelling);
    }
    return sem_visible(c, table, node, owner, spelling);
}

fn sem_namespace(c: SemanticContext*, node: void*): void* {
    return sem_namespace_from(c, node, sem_owner(c, node));
}

fn sem_namespace_from(c: SemanticContext*, node: void*, owner: void*): void* {
    node = sem_name_node(node);
    var base = sem_member(node, "base");
    var field = sem_member(node, "field");
    var possible = base != null;
    possible &&= field != null;
    if !possible {
        return null;
    }
    base = sem_name_node(base);
    if sem_member(base, "base") != null {
        return null;
    }
    var name = sem_identifier(c, base);
    var shadowed = sem_local(c, name) != null;
    if c.generics != null {
        var parameter = generic_lookup(c.generics, base, base);
        if parameter != null {
            shadowed = true;
        }
    }
    if shadowed {
        return null;
    }
    return sem_alias(c, owner, name);
}

fn sem_editor_symbol(c: SemanticContext*, node: void*, kind: u32): bool {
    var name = sem_name_node(node);
    var field = sem_member(name, "field");
    var qualified = field != null;
    var target = name;
    if qualified {
        target = field;
    }
    var captured = sem_editor_capture(c, target, kind, null);
    if captured {
        c.editor.node = node;
        c.editor.module = sem_namespace(c, name);
    }
    return captured;
}

fn sem_completion_visible(c: SemanticContext*, editor: SemanticEditor*, table: SemanticTable*, node: void*): bool {
    var name = sem_identifier(c, sem_member(node, "name"));
    var value = sem_get(node);
    if name[0] == 0 {
        if value != null {
            name = sem_name(value);
        }
    }
    var found: void* = null;
    if editor.module != null {
        found = sem_owned(table, editor.module, name);
    } else {
        var callable = table == c.functions;
        callable ||= table == c.templates;
        callable ||= table == c.type_functions;
        if callable {
            found = sem_callable_visible(c, table, editor.node, sem_owner(c, editor.node), name);
        } else {
            found = sem_visible(c, table, editor.node, sem_owner(c, editor.node), name);
        }
    }
    var clean = sem_ok(c);
    c.program.error.length = 0;
    if clean {
        var same = found == node;
        return same;
    }
    return false;
}

// Keep familiar names when unique. Colliding module-local declarations get a
// deterministic, escaped Foundation spelling; bindings still point to entities.
fn sem_output_name(c: SemanticContext*, node: void*, name: u8*): u8* {
    var saved = sem_find(c.output_names, null, node);
    if saved != null {
        return bits(u8*, saved.value);
    }
    var spelling = name;
    var original = sem_find(c.source_names, name, null);
    var collision = original != null;
    collision &&= original.number != 0;
    if collision {
        var owner = sem_owner(c, node);
        if owner != null {
            spelling = sem_cat(c, name, sem_cat(c, "@", sem_module_path(c, owner)));
        }
    }
    var candidate = spelling;
    var suffix: u64 = 1;
    loop {
        var taken = sem_lookup_table(c.output_names, candidate);
        var available = taken == null;
        if sem_equal(candidate, name) == false {
            if sem_find(c.source_names, candidate, null) != null {
                available = false;
            }
        }
        if available {
            break;
        }
        suffix++;
        candidate = sem_cat(c, spelling, sem_cat(c, "_", sem_decimal(c, suffix)));
    }
    sem_put(c, c.output_names, candidate, node);
    saved = sem_state(c, c.output_names, node);
    saved.value = bits(void*, candidate);
    return candidate;
}

fn sem_validate_aliases(c: SemanticContext*): void {
    var registry = c.program.modules;
    if registry == null {
        return;
    }
    var root = sem_get(c.program.root);
    var count = sem_child_count(registry.scopes);
    for(var i: usize = 0; i < count; i++) {
        var scope = sem_child(registry.scopes, i);
        var imports = sem_child_count(scope);
        for(var edge: usize = 0; edge < imports; edge++) {
            var alias = sem_import_alias(scope, edge);
            if alias[0] != 0 {
                var conflict = semantic_builtin_kind(alias) != 0;
                conflict ||= sem_owned(c.types, null, alias) != null;
                foreach(var declaration in &root.items) {
                    if sem_owner(c, declaration) == scope {
                        var name = sem_member(declaration, "name");
                        if name != null {
                            if sem_equal(alias, sem_identifier(c, name)) {
                                conflict = true;
                            }
                        }
                    }
                }
                if conflict {
                    sem_fail(c, sem_child(scope, edge), sem_cat(c, "Import alias conflicts with declaration: ", alias));
                    return;
                }
            }
        }
    }
}

// Foreign declarations still denote explicit link symbols. Merge identical
// declarations (and their Tower export, if supplied) after checked signatures
// exist. Local Tower names never acquire foreign visibility from this step.
fn sem_link_functions(c: SemanticContext*): void {
    if !sem_ok(c) {
        return;
    }
    var symbols = sem_table(c);
    var i: usize = 1;
    for(; i < c.program.functions.length; i++) {
        var node = c.program.functions.data[i];
        var function = sem_get(node);
        var foreign = function.external;
        if function.exported {
            foreign = true;
        }
        if foreign {
            var name = sem_name(function);
            var entry = sem_entry(c, symbols, name, null);
            var previous = entry.value;
            var duplicate = previous != null;
            if duplicate {
                var old = sem_get(previous);
                var compatible = semantic_type_equal(&function.type, &old.type);
                compatible &&= function.parameters.length == old.parameters.length;
                var p: usize = 0;
                for(; p < function.parameters.length; p++) {
                    if compatible {
                        var left = sem_get(function.parameters.data[p]);
                        var right = sem_get(old.parameters.data[p]);
                        compatible = semantic_type_equal(&left.type, &right.type);
                    }
                }
                if !compatible {
                    sem_fail(c, node, sem_cat(c, "Incompatible declarations of foreign symbol '", sem_cat(c, name, "'")));
                    return;
                }
                var definitions = old.exported;
                definitions &&= function.exported;
                if definitions {
                    sem_fail(c, node, sem_cat(c, "Duplicate foreign export '", sem_cat(c, name, "'")));
                    return;
                }
                if function.exported {
                    old.binding = node;
                    entry.value = node;
                } else {
                    function.binding = previous;
                }
            } else {
                entry.value = node;
            }
        }
    }
    i = 0;
    for(; i < c.functions.capacity; i++) {
        var entry = c.functions.entries[i];
        if entry != null {
            var node = sem_get(entry.value);
            while node.binding != null {
                entry.value = node.binding;
                node = sem_get(entry.value);
            }
        }
    }
    var count: usize = 0;
    i = 0;
    for(; i < c.program.functions.length; i++) {
        var node = c.program.functions.data[i];
        var value = sem_get(node);
        if value.binding == null {
            value.index = count;
            c.program.functions.data[count] = node;
            count++;
        }
    }
    c.program.functions.length = count;
    var root = sem_get(c.program.root);
    count = 0;
    i = 0;
    for(; i < root.items.length; i++) {
        var node = root.items.data[i];
        var value = sem_get(node);
        var duplicate = value != null;
        duplicate &&= value.kind == KFunction;
        duplicate &&= value.binding != null;
        if !duplicate {
            root.items.data[count] = node;
            count++;
        }
    }
    root.items.length = count;
    // Inference/decltype can check a call before all foreign signatures have
    // resolved. Retarget those existing shared call components after merging.
    var pending = sem_list(c);
    sem_push(pending, c.program.root);
    while pending.length != 0 {
        pending.length--;
        var node = pending.data[pending.length];
        var value = sem_get(node);
        if value != null && value.kind == KCall && value.binding != null {
            var function = sem_get(value.binding);
            while function.binding != null {
                value.binding = function.binding;
                function = sem_get(value.binding);
            }
        }
        var child: usize = 0;
        while child < sem_child_count(node) { sem_push(pending, sem_child(node, child)); child++; }
    }
}

