// Semantic compiler over shared Foundation components.
// Temporary indexes and scratch allocations are scoped to one compilation.

fn sem_function_declare(c: SemanticContext*, n: void*, name: u8*): void {
    var external = sem_is(n, "CoreExternal");
    if !sem_shape(c, n, "name") || !sem_shape(c, n, "type") {
        return;
    }
    if !external && !sem_shape(c, n, "body") {
        return;
    }
    var function_node: FoundationNode* = sem_node(c, n, KFunction);
    if name[0] == 0 {
        var step15 = sem_member(n, "name");
        name = sem_identifier(c, step15);
    }
    var published = external;
    if sem_is(n, "CoreExport") {
        published = true;
    }
    if published {
        sem_set_name(function_node, name);
    } else {
        sem_set_name(function_node, sem_output_name(c, n, name));
    }
    var step26 = name[0] == 0;
    if !step26 {
        var step28 = sem_owned(c.functions, sem_owner(c, n), name);
        var step29 = step28 != null;
        step26 = step29;
    }
    if !step26 {
        var step31 = sem_owned(c.templates, sem_owner(c, n), name);
        var step32 = step31 != null;
        step26 = step32;
    }
    if !step26 {
        var step34 = sem_owned(c.type_functions, sem_owner(c, n), name);
        var step35 = step34 != null;
        step26 = step35;
    }
    if step26 {
        var step36 = sem_cat(c, "Missing or duplicate function '", name);
        var step37 = sem_cat(c, step36, "'");
        sem_fail(c, n, step37);
        return;
    }
    function_node.index = c.program.functions.length;
    sem_define(c, c.functions, n, name);
    sem_push(&c.program.functions, n);
    function_node.external = external;
    function_node.exported = sem_is(n, "CoreExport");
}

// Bind the entire signature before requesting its types. Parameter entities
// participate in the same declaration graph as globals, fields and returns.
fn sem_parameters(c: SemanticContext*, n: void*, definition: void*): SemanticScope* {
    var state = sem_declaration_state(c, n);
    if state.scope != null {
        return state.scope;
    }
    state.scope = sem_scope(c, null);
    var function_node = sem_get(n);
    var params = sem_collect(c, sem_member(n, "params"), "CoreParameter");
    for(var i: usize = 0; i < params.length && sem_ok(c); ++i) {
        if definition != null && generic_type_parameter(c.generics, definition, i) {
            continue;
        }
        var p = params.data[i];
        if !sem_shape(c, p, "name") || !sem_shape(c, p, "type") {
            break;
        }
        var param = sem_node(c, p, KParameter);
        var name = sem_identifier(c, sem_member(p, "name"));
        sem_set_name(param, name);
        if name[0] == 0 || !sem_put(c, state.scope.names, name, p) {
            sem_fail(c, p, "Invalid or duplicate function parameter");
            break;
        }
        sem_declaration_state(c, p).scope = state.scope;
        sem_push(&function_node.parameters, p);
    }
    if function_node.parameters.length > FoundationParameterLimit {
        sem_fail(c, n, "Foundation parameter limit is 64");
    }
    return state.scope;
}

fn sem_header(c: SemanticContext*, n: void*, name: u8*, definition: void*): void {
    var external = sem_is(n, "CoreExternal");
    if !sem_shape(c, n, "name") || !sem_shape(c, n, "type") {
        return;
    }
    if !external && !sem_shape(c, n, "body") {
        return;
    }
    if sem_get(n) == null {
        sem_function_declare(c, n, name);
    }
    if !sem_ok(c) {
        return;
    }
    var function_node = sem_get(n);
    var saved_scope = c.scope;
    var saved_current = c.current;
    c.scope = sem_parameters(c, n, definition);
    c.current = n;
    for(var i: usize = 0; i < function_node.parameters.length && sem_ok(c); ++i) {
        var p = function_node.parameters.data[i];
        if !sem_declaration_type(c, p) {
            break;
        }
        if sem_get(p).type.pointers == 0 && sem_get(p).type.scalar == SArray {
            sem_fail(c, p, "Array parameters require a pointer; wrap an array in a struct for value passing");
            break;
        }
        if semantic_aggregate(&sem_get(p).type) {
            c.surface_expressions = true;
            if external || function_node.exported {
                sem_fail(c, p, "Foreign/exported aggregate signatures require an explicit pointer ABI");
                break;
            }
        }
        sem_add_local(c, p);
    }
    if sem_ok(c) {
        sem_set_type(&function_node.type, sem_type(c, sem_member(n, "type")));
        name = sem_name(function_node);
        if semantic_builtin_kind(name) != 0 {
            sem_fail(c, n, sem_cat(c, "Function name '", sem_cat(c, name, "' already names a foundation builtin")));
        }
        if semantic_aggregate(&function_node.type) {
            c.surface_expressions = true;
            if function_node.type.scalar == SArray {
                sem_fail(c, n, "Array returns require a pointer; wrap an array in a struct for value returning");
            }
            if external || function_node.exported {
                sem_fail(c, n, "Foreign/exported aggregate signatures require an explicit pointer ABI");
            }
        }
    }
    function_node.external = external;
    function_node.exported = sem_is(n, "CoreExport");
    c.scope = saved_scope;
    c.current = saved_current;
}

fn sem_scope(c: SemanticContext*, parent: SemanticScope*): SemanticScope* {
    var step2 = sem_allocate(c, sizeof(SemanticScope));
    var scope: SemanticScope* = bits(SemanticScope*, step2);
    scope.parent = parent;
    var step4 = sem_table(c);
    scope.names = step4;
    return scope;
}

fn sem_text_less(a: u8*, b: u8*): bool {
    var i: usize = 0;
    loop {
        if !(a[i] == b[i] && a[i] != 0) {
            break;
        }
        i++;
    }
    return a[i] < b[i];
}

fn sem_order_name(c: SemanticContext*, node: void*, value: FoundationNode*): u8* {
    if value != null {
        return sem_name(value);
    }
    return sem_identifier(c, sem_member(node, "name"));
}

fn sem_scope_locals(c: SemanticContext*, scope: SemanticScope*, locals: vector(void*)*): void {
    var i: usize = 0;
    for(; i < scope.names.capacity; i++) {
        var entry: SemanticEntry* = scope.names.entries[i];
        if entry != null && entry.value != null {
            sem_push(locals, entry.value);
        }
    }
    i = 1;
    for(; i < locals.length; i++) {
        var value: void* = locals.data[i];
        var j: usize = i;
        loop {
            var step9 = j != 0;
            if step9 {
                var step11 = sem_order_name(c, value, sem_get(value));
                var step12 = j -1;
                var step13 = sem_get(locals.data[step12]);
                step9 = sem_text_less(step11, sem_order_name(c, locals.data[step12], step13));
            }
            if !step9 {
                break;
            }
            var step17 = j -1;
            locals.data[j] = locals.data[step17];
            j--;
        }
        locals.data[j] = value;
    }
}

fn sem_control_call(c: SemanticContext*, statement: void*, name: u8*): void* {
    if sem_is(statement, "TowerExpressionStatement") {
        var call = sem_surface_unwrap(sem_member(statement, "value"));
        if sem_is(call, "CoreCall") {
            var spelling = sem_identifier(c, sem_member(call, "name"));
            if sem_equal(spelling, name) {
                return call;
            }
        }
    }
    if sem_is(statement, "CoreCallStatement") {
        var call = sem_member(statement, "call");
        var identifier = sem_member(call, "name");
        var spelling = sem_identifier(c, identifier);
        if sem_equal(spelling, name) {
            return call;
        }
    }
    return null;
}

fn sem_label_name(c: SemanticContext*, call: void*): u8* {
    var arguments = sem_collect(c, sem_member(call, "args"), "CoreCallArgument");
    var one = arguments.length == 1;
    if one {
        var argument = arguments.data[0];
        var names = sem_collect(c, argument, "CoreLocation");
        one = names.length == 1;
        if one {
            var whole = sem_tokens(c, argument);
            var identifier = sem_member(names.data[0], "name");
            var name = sem_tokens(c, identifier);
            if sem_equal(whole, name) {
                return sem_identifier(c, identifier);
            }
        }
    }
    sem_fail(c, call, "label/jump require one label identifier");
    return "";
}

fn sem_labels(c: SemanticContext*, body: void*): void {
    c.labels = sem_table(c);
    var index: usize = 0;
    var i: usize = 0;
    loop {
        if i == sem_child_count(body) {
            return;
        }
        var item = sem_child(body, i);
        if sem_is(item, "Statement") {
            item = sem_unwrap(item);
            var call = sem_control_call(c, item, "label");
            if call != null {
                var label = sem_node(c, call, KLabel);
                var name = sem_label_name(c, call);
                sem_set_name(label, name);
                label.body = body;
                label.index = index;
                if !sem_put(c, c.labels, name, call) {
                    sem_fail(c, item, "Duplicate function label");
                }
            }
            index++;
        }
        i++;
    }
}

// Private checking continuation. The block entity remains the canonical program;
// this cursor records progress and lexical cleanup boundaries, never operations.
struct SemanticBlockCursor {
    subject: void*;
    next: usize;
    depth: u32;
    flow: u32;
    labeled: bool;
    deferred: void*;
}

fn sem_block_begin(c: SemanticContext*, n: void*, depth: u32, cursor: SemanticBlockCursor*): bool {
    *cursor = default;
    cursor.subject = n;
    cursor.depth = depth;
    cursor.flow = FlowNext;
    cursor.deferred = c.deferred;
    if n == null || !sem_is(n, "CoreBlock") {
        sem_fail(c, n, "Expected a CoreBlock tree");
        return false;
    }
    sem_node(c, n, KBlock);
    c.scope = sem_scope(c, c.scope);
    return true;
}

// Completion is shared by immediate statements and resumed nested blocks.
fn sem_block_accept(c: SemanticContext*, cursor: SemanticBlockCursor*, at: void*, next: u32): void {
    if sem_is(at, "CoreCallStatement") {
        at = sem_member(at, "call");
    }
    var control = sem_control_call(c, at, "label");
    if control == null {
        control = sem_control_call(c, at, "jump");
    }
    if control != null {
        at = control;
    }
    sem_push(&sem_get(cursor.subject).items, at);
    if(cursor.flow &FlowNext) != 0 {
        cursor.flow =(cursor.flow & ~FlowNext) | next;
    }
}

fn sem_block_step(c: SemanticContext*, cursor: SemanticBlockCursor*): void {
    var at = sem_child(cursor.subject, cursor.next);
    cursor.next++;
    if sem_is(at, "Statement") {
        at = sem_unwrap(at);
        var label_call = sem_control_call(c, at, "label");
        if label_call != null {
            if cursor.labeled {
                if(cursor.flow &FlowNext) != 0 && c.flow_dependencies.length == 0 {
                    sem_fail(c, at, "A labeled block must end with jump or return before the next label");
                }
            }
            cursor.labeled = true;
            cursor.flow = FlowNext;
        }
        var next = sem_statement(c, at, cursor.depth + 1);
        sem_block_accept(c, cursor, at, next);
    } else {
        if !sem_is(at, "{") && !sem_is(at, "}") {
            sem_fail(c, at, "Malformed CoreBlock tree");
        }
    }
}

fn sem_block_finish(c: SemanticContext*, cursor: SemanticBlockCursor*): u32 {
    var value = sem_get(cursor.subject);
    sem_scope_locals(c, c.scope, &value.locals);
    if(cursor.flow &FlowNext) != 0 && c.deferred != cursor.deferred && sem_ok(c) {
        cursor.flow =(cursor.flow & ~FlowNext) | sem_defer_emit(c, cursor.subject, cursor.deferred, 0);
    }
    c.deferred = cursor.deferred;
    c.scope = c.scope.parent;
    return cursor.flow;
}

fn sem_block(c: SemanticContext*, n: void*, depth: u32): u32 {
    var cursor: SemanticBlockCursor;
    if !sem_block_begin(c, n, depth, &cursor) {
        return FlowNext;
    }
    while cursor.next < sem_child_count(n) && sem_ok(c) {
        sem_block_step(c, &cursor);
    }
    return sem_block_finish(c, &cursor);
}

// The ordinary recursive checker and worker continuations share these phases.
// Cursors are private scheduling state; the same entities carry all semantics.
fn sem_if_begin(c: SemanticContext*, n: void*): bool {
    if !sem_shape(c, n, "condition") || !sem_shape(c, n, "body") {
        return false;
    }
    var value = sem_node(c, n, KIf);
    value.value = sem_operand(c, sem_member(n, "condition"), sem_type_new(c, SBool, 0, null));
    value.body = sem_member(n, "body");
    value.otherwise = sem_member(n, "otherwise");
    return true;
}

fn sem_if_finish(c: SemanticContext*, n: void*, yes: u32, no: u32): u32 {
    var value = sem_get(n);
    var condition = sem_get(value.value);
    if condition != null && sem_flow_known(c, value.value) {
        return condition.bits != 0 ? yes: no;
    }
    return yes | no;
}

fn sem_loop_finish(flow: u32): u32 {
    return(flow &FlowReturn) |((flow &FlowBreak) != 0 ? FlowNext: 0);
}

// Binding precedes type/initializer queries, including a self-reference. A
// suspended declaration resumes completion without rebinding or replaying it.
fn sem_declaration_bind(c: SemanticContext*, n: void*): bool {
    if !sem_shape(c, n, "name") { return false; }
    var value = sem_node(c, n, KDeclare);
    var name = sem_identifier(c, sem_member(n, "name"));
    if !value.global { sem_set_name(value, name); }
    if name[0] == 0 || !value.global && sem_lookup_table(c.scope.names, name) != null {
        sem_fail(c, n, sem_cat(c, "Missing or duplicate local '", sem_cat(c, name, "'")));
        return false;
    }
    if !value.global { sem_put(c, c.scope.names, name, n); }
    return true;
}

fn sem_declaration_finish(c: SemanticContext*, n: void*): void {
    var value = sem_get(n);
    if !value.global { sem_add_local(c, n); }
    var initial = sem_member(n, "value");
    if initial != null && value.value == null {
        value.value = sem_initial_value(c, initial, &value.type);
    }
}

fn sem_statement(c: SemanticContext*, n: void*, depth: u32): u32 {
    if c.deferring != 0 && sem_control_call(c, n, "jump") != null {
        sem_fail(c, n, "A deferred cleanup cannot jump out of its scope");
        return FlowNext;
    }
    return sem_statement_complete(c, n, sem_statement_impl(c, n, depth));
}

fn sem_statement_complete(c: SemanticContext*, n: void*, flow: u32): u32 {
    if(c.deferred != null || c.deferring != 0) && sem_ok(c) {
        return sem_defer_exit(c, n, flow);
    }
    return flow;
}

fn sem_statement_impl(c: SemanticContext*, n: void*, depth: u32): u32 {
    var label_call = sem_control_call(c, n, "label");
    if label_call != null {
        var direct = depth == 1;
        var found = sem_get(label_call) != null;
        if direct {
            if found {
                return 1;
            }
        }
        sem_fail(c, n, "Labels must be direct statements in a function body");
        return 1;
    }
    var jump_call = sem_control_call(c, n, "jump");
    if jump_call != null {
        var value = sem_node(c, jump_call, KJump);
        var name = sem_label_name(c, jump_call);
        sem_set_name(value, name);
        var labels = c.labels != null;
        if labels {
            value.binding = sem_lookup_table(c.labels, name);
        }
        if value.binding == null {
            sem_fail(c, n, "Unknown function label");
        }
        return 0;
    }
    if depth > 128 {
        sem_fail(c, n, "Foundation block nesting limit is 128");
        return 1;
    }
    if !sem_ok(c) {
        return 1;
    }
    if sem_is(n, "TowerMatch") {
        return sem_control_match(c, n, depth);
    }
    if sem_is(n, "TowerWhile") {
        return sem_control_while(c, n, depth);
    }
    if sem_is(n, "TowerDefer") {
        return sem_defer_register(c, n, depth);
    }
    if sem_is(n, "TowerForeach") {
        return sem_iteration(c, n, depth);
    }
    if sem_is(n, "TowerFor") {
        return sem_control_for(c, n, depth);
    }
    if sem_is(n, "TowerExpressionStatement") {
        c.surface_expressions = true;
        var expression = sem_surface_unwrap(sem_member(n, "value"));
        var value = sem_node(c, n, SurfaceDiscard);
        value.value = sem_surface_discard(c, expression);
        if sem_ok(c) {
            var operation = sem_get(value.value);
            if operation.kind == KTrap {
                return 0;
            }
        }
        return FlowNext;
    }
    if sem_is(n, "CoreEnum") {
        sem_fail(c, n, "Enum types must be declared at top level");
        return FlowNext;
    }
    var kind: u8* = sem_label(n);
    if sem_equal(kind, "CoreDeclare") {
        if !sem_declaration_bind(c, n) || !sem_declaration_type(c, n) { return FlowNext; }
        sem_declaration_finish(c, n);
    } else {
        if sem_equal(kind, "CoreAssign") {
            if !sem_shape(c, n, "target") || !sem_shape(c, n, "value") || !sem_shape(c, sem_member(n, "target"), "name") {
                return 1;
            }
            var value: FoundationNode* = sem_node(c, n, KAssign);
            var target: void* = sem_member(n, "target");
            var step43 = sem_location(c, sem_member(target, "name"), 0);
            value.target = step43;
            if !sem_ok(c) {
                return 1;
            }
            var step46 = sem_get(value.target);
            var expected_type: FoundationType* = sem_type_copy(c, &step46.type);
            if sem_equal(sem_tokens(c, sem_child(target, 0)), "*") {
                var dest: FoundationNode* = sem_node(c, target, KLoad);
                dest.value = value.target;
                if expected_type.pointers == 0 {
                    sem_fail(c, target, "Store requires a pointer");
                } else {
                    expected_type.pointers--;
                }
                sem_set_type(&dest.type, expected_type);
                value.target = target;
            }
            if expected_type.pointers == 0 && expected_type.scalar == SArray {
                sem_fail(c, target, "Array values require indexing or a pointer; wrap an array in a struct for copying");
            }
            var step55 = sem_expression(c, sem_member(n, "value"), expected_type);
            value.value = step55;
        } else {
            if sem_equal(kind, "CoreCallStatement") {
                var step57 = sem_member(n, "call");
                sem_call(c, step57);
                var call_node = sem_get(step57);
                if call_node != null {
                    if call_node.kind == 33 {
                        return 0;
                    }
                }
            } else {
                if sem_equal(kind, "CoreReturn") {
                    var value: FoundationNode* = sem_node(c, n, KReturn);
                    var returned: void* = sem_member(n, "value");
                    var present: bool = sem_length(sem_tokens(c, returned)) != 0;
                    var function: FoundationNode* = sem_get(c.current);
                    if function.type.pointers == 0 && function.type.scalar == SVoid {
                        if present {
                            sem_fail(c, n, "A void function cannot return a value");
                        }
                    } else {
                        if !present {
                            sem_fail(c, n, "A non-void function must return a value");
                        } else {
                            var operands = sem_collect(c, returned, "CoreOperand");
                            if operands.length == 1 {
                                value.value = sem_initial_value(c, operands.data[0], &function.type);
                            }
                            else {
                                sem_fail(c, n, "A return value must contain one Foundation operand");
                            }
                        }
                    }
                    return 8;
                } else {
                    if sem_function_syntax(n) {
                        sem_fail(c, n, "Functions must be declared at top level");
                    } else {
                        if sem_equal(kind, "CoreStruct") {
                            sem_fail(c, n, "Struct types must be declared at top level");
                        } else {
                            if sem_equal(kind, "CoreBlock") {
                                return sem_block(c, n, depth);
                            } else {
                                if sem_equal(kind, "CoreIf") {
                                    if !sem_if_begin(c, n) {
                                        return FlowNext;
                                    }
                                    var value = sem_get(n);
                                    var yes = sem_block(c, value.body, depth);
                                    var no = FlowNext;
                                    if value.otherwise != null {
                                        no = sem_block(c, value.otherwise, depth);
                                    }
                                    return sem_if_finish(c, n, yes, no);
                                } else {
                                    if sem_equal(kind, "CoreLoop") {
                                        var value: FoundationNode* = sem_node(c, n, KLoop);
                                        var step99 = sem_member(n, "body");
                                        value.body = step99;
                                        c.loops++;
                                        var flow: u32 = sem_block(c, value.body, depth);
                                        c.loops--;
                                        return sem_loop_finish(flow);
                                    } else {
                                        if sem_equal(kind, "CoreBreak") || sem_equal(kind, "CoreContinue") {
                                            var op: u32 = 16;
                                            var result: u32 = 4;
                                            if sem_equal(kind, "CoreBreak") {
                                                op = 15;
                                                result = 2;
                                            }
                                            sem_node(c, n, op);
                                            if c.loops == 0 {
                                                sem_fail(c, n, sem_cat(c, kind, " requires an enclosing loop"));
                                            }
                                            return result;
                                        } else {
                                            var step112 = sem_cat(c, "No execution semantics for '", kind);
                                            sem_fail(c, n, sem_cat(c, step112, "'; replace it with a foundation operation"));
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    return 1;
}

fn sem_function_syntax(n: void*): bool {
    return sem_is(n, "CoreFunction") || sem_is(n, "CoreExternal") || sem_is(n, "CoreExport");
}

fn sem_function_begin(c: SemanticContext*, n: void*, cursor: SemanticBlockCursor*): bool {
    var function_node = sem_get(n);
    c.current = n;
    if c.editor != null && !sem_editor_contains(c, n) {
        return false;
    }
    if function_node.external {
        return false;
    }
    c.scope = sem_scope(c, null);
    c.loops = 0;
    c.flow_dependencies.length = 0;
    foreach(var parameter in &function_node.parameters) {
        sem_put(c, c.scope.names, sem_name(sem_get(parameter)), parameter);
    }
    function_node.body = sem_member(n, "body");
    sem_labels(c, function_node.body);
    return sem_block_begin(c, function_node.body, 0, cursor);
}

fn sem_function_finish(c: SemanticContext*, n: void*, cursor: SemanticBlockCursor*): void {
    var function_node = sem_get(n);
    var flow = sem_block_finish(c, cursor);
    if c.flow_dependencies.length != 0 {
        if c.entity_stage == null {
            sem_flow_request(c, n, &c.flow_dependencies);
        }
        return;
    }
    if(function_node.type.pointers != 0 || function_node.type.scalar != SVoid) &&(flow &1) != 0 {
        sem_fail(c, n, sem_cat(c, "Function '", sem_cat(c, sem_name(function_node),
        "' can finish without returning a value")));
    }
}

fn sem_function_body(c: SemanticContext*, n: void*): void {
    var cursor: SemanticBlockCursor;
    if !sem_function_begin(c, n, &cursor) {
        return;
    }
    while cursor.next < sem_child_count(cursor.subject) && sem_ok(c) {
        sem_block_step(c, &cursor);
    }
    sem_function_finish(c, n, &cursor);
}

fn sem_run(c: SemanticContext*): void {
    sem_attributes_declarations(c);
    sem_validate_aliases(c);
    var step1 = sem_get(c.program.root);
    var statements: vector(void*)* = &step1.items;
    var i: usize = 0;
    for(; i < statements.length; i++) {
        var n: void* = statements.data[i];
        var name: void* = sem_member(n, "name");
        if name != null {
            var step6 = sem_identifier(c, name);
            var entry = sem_entry(c, c.source_names, step6, null);
            if entry.value != null {
                if sem_owner(c, entry.value) != sem_owner(c, n) {
                    entry.number = 1;
                }
            } else {
                entry.value = n;
            }
        }
        if sem_ok(c) && sem_function_syntax(n) {
            sem_register_template(c, n);
        }
    }
    i = 0;
    var count: usize = 0;
    for(; i < statements.length; i++) {
        var n: void* = statements.data[i];
        if !sem_has(&c.template_nodes, n) {
            statements.data[count] = n;
            count++;
        }
    }
    statements.length = count;
    i = 0;
    loop {
        if !(i < statements.length && sem_ok(c)) {
            break;
        }
        var n: void* = statements.data[i];
        if sem_is(n, "CoreStruct") {
            sem_type_header(c, n, "");
        }
        if sem_is(n, "CoreEnum") {
            sem_enum_header(c, n);
        }
        i++;
    }
    i = 0;
    loop {
        if !(i < statements.length && sem_ok(c)) {
            break;
        }
        var n: void* = statements.data[i];
        if sem_is(n, "CoreDeclare") {
            if !sem_shape(c, n, "name") {
                break;
            }
            var value: FoundationNode* = sem_node(c, n, KDeclare);
            value.global = true;
            var step42 = sem_member(n, "name");
            var name: u8* = sem_identifier(c, step42);
            sem_set_name(value, sem_output_name(c, n, name));
            if !sem_define(c, c.globals, n, name) {
                var step46 = sem_cat(c, "Duplicate module variable '", name);
                var step47 = sem_cat(c, step46, "'");
                sem_fail(c, n, step47);
                break;
            }
        }
        i++;
    }
    i = 0;
    while i < statements.length && sem_ok(c) {
        var n = statements.data[i];
        if sem_function_syntax(n) {
            sem_function_declare(c, n, "");
        }
        i++;
    }
    sem_declarations(c, statements);
    sem_link_functions(c);
    sem_layout_all(c);
    i = 0;
    loop {
        if !(i < statements.length && sem_ok(c)) {
            break;
        }
        var n: void* = statements.data[i];
        if sem_is(n, "CoreDeclare") {
            if !sem_declaration_type(c, n) {
                break;
            }
            sem_add_local(c, n);
        }
        i++;
    }
    i = 0;
    for(; i < statements.length; i++) {
        var n: void* = statements.data[i];
        var step59 = !sem_function_syntax(n);
        if step59 {
            var step60 = sem_is(n, "CoreStruct");
            if sem_is(n, "CoreEnum") {
                step60 = true;
            }
            step59 = !step60;
        }
        if step59 {
            sem_statement(c, n, 0);
            if sem_is(n, "CoreCallStatement") {
                var step63 = sem_member(n, "call");
                statements.data[i] = step63;
            }
        }
    }
    sem_defer_emit(c, c.program.root, null, 0);
    c.deferred = null;
    sem_attributes_check(c);
    sem_bodies(c);
    sem_layout_all(c);
    var step90 = foundation_nodes_prepend(statements, c.generated.data, c.generated.length);
    sem_require(step90);
}

import tower;
import foundation_tags;
import foundation_types;
import frontend_compilation;
import parser_types;
import semantic_context;
import semantic_definitions;
import semantic_lifecycle;
import semantic_modules;
import .library.stack;
import .library.vector;
import .library.float_text;

// Semantic compiler over shared Foundation components.
// Temporary indexes and scratch allocations are scoped to one compilation.

export fn semantic_type_equal(a: FoundationType*, b: FoundationType*): bool {
    if a.scalar != b.scalar || a.pointers != b.pointers {
        return false;
    }
    if a.record != b.record {
        if a.scalar != SFunction || a.record == null || b.record == null { return false; }
        var left = sem_get(a.record);
        var right = sem_get(b.record);
        if !semantic_type_equal(&left.element, &right.element) || left.parameters.length != right.parameters.length { return false; }
        for(var i: usize = 0; i < left.parameters.length; i++) {
            if !semantic_type_equal(&sem_get(left.parameters.data[i]).type, &sem_get(right.parameters.data[i]).type) { return false; }
        }
    }
    if a.pointers != 0 || a.scalar == SUSize || a.scalar == SFunction {
        return a.pointer_bytes == b.pointer_bytes;
    }
    return true;
}

// Scalar representation plus nominal entity identity; pointers retain that
// identity too. Built-in scalars have no record, aggregates have their own tags.
export fn semantic_enum(t: FoundationType*): bool {
    var nominal = t.record != null;
    nominal &&= t.scalar != SStruct;
    nominal &&= t.scalar != SArray;
    nominal &&= t.scalar != SFunction;
    return nominal;
}

export fn semantic_aggregate(t: FoundationType*): bool {
    return t.pointers == 0 &&(t.scalar == SStruct || t.scalar == SArray);
}

export fn semantic_integer(t: FoundationType*): bool {
    var step2 = t.pointers == 0 &&(t.scalar == SI32 || t.scalar == SU32 || t.scalar == SU8 || t.scalar == SI64 || t.scalar == SU64 || t.scalar == SUSize || t.scalar == SI8 || t.scalar == SI16 || t.scalar == SU16);
    return step2;
}

export fn semantic_float(t: FoundationType*): bool {
    return t.pointers == 0 && (t.scalar == SF32 || t.scalar == SF64);
}

fn semantic_numeric_binary(t: FoundationType*, operation: u32): bool {
    if semantic_integer(t) { return true; }
    return semantic_float(t) && (operation <= ODiv || operation >= OEq && operation <= OGe);
}

fn sem_float_literal(c: SemanticContext*, node: void*): bool {
    if !sem_literal(c, node) { return false; }
    var text = sem_tokens(c, node);
    var start: usize = text[0] == FloatDecimalMinus ? 1 : 0;
    if !float_decimal_digit(text[start]) { return false; }
    for (var i: usize = 0; text[i] != 0; i++) {
        if text[i] == FloatDecimalPoint || text[i] == FloatDecimalExponent || text[i] == FloatDecimalUpperExponent { return true; }
    }
    return false;
}

export fn semantic_signed(t: FoundationType*): bool {
    return t.pointers == 0 &&(t.scalar == SI32 || t.scalar == SI64 || t.scalar == SI8 || t.scalar == SI16);
}

export fn semantic_unsigned_scalar(scalar: u32): u32 {
    if scalar == SI8 { return SU8; }
    if scalar == SI16 { return SU16; }
    if scalar == SI32 { return SU32; }
    if scalar == SI64 { return SU64; }
    return scalar;
}

export fn semantic_size(t: FoundationType*): usize {
    if t.pointers != 0 || t.scalar == SUSize || t.scalar == SFunction {
        return convert(usize, t.pointer_bytes);
    }
    if semantic_aggregate(t) {
        var step7 = sem_get(t.record);
        return step7.size;
    }
    if t.scalar == SVoid {
        return 0;
    }
    if t.scalar == SBool || t.scalar == SU8 || t.scalar == SI8 {
        return 1;
    }
    if t.scalar == SI16 || t.scalar == SU16 {
        return convert(usize, IntegerShortWidth / IntegerByteWidth);
    }
    if t.scalar == SI64 || t.scalar == SU64 || t.scalar == SF64 {
        return 8;
    }
    return 4;
}

export fn semantic_alignment(t: FoundationType*): usize {
    if t.pointers != 0 || t.scalar == SUSize || t.scalar == SFunction {
        return convert(usize, t.pointer_bytes);
    }
    if semantic_aggregate(t) {
        var step7 = sem_get(t.record);
        return step7.alignment;
    }
    var result: usize = semantic_size(t);
    if result == 0 {
        return 1;
    }
    return result;
}

export fn semantic_width(t: FoundationType*): u32 {
    var step2 = semantic_size(t) *8;
    return convert(u32, step2);
}

export fn semantic_mask(t: FoundationType*): u64 {
    var width: u32 = semantic_width(t);
    var result: u64 = 1;
    for(var i: u32 = 0; i < width; i++) {
        result = result * 2;
    }
    return result -1;
}

fn sem_length(s: u8*): usize {
    var i: usize = 0;
    if s != null {
        for(; s[i] != 0; i++) {}
    }
    return i;
}

fn sem_equal(a: u8*, b: u8*): bool {
    for(var i: usize = 0; a[i] == b[i]; i++) {
        if a[i] == 0 {
            return true;
        }
    }
    return false;
}

fn sem_allocate(c: SemanticContext*, count: usize): u8* {
    var result: u8* = alloc(u8, count);
    sem_require(result != null);
    sem_track(c, result);
    return result;
}

fn sem_text(c: SemanticContext*, s: u8*, count: usize): u8* {
    var result: u8* = sem_allocate(c, count + 1);
    if count != 0 {
        copy(result, s, count);
    }
    result[count] = 0;
    return result;
}

fn sem_cat(c: SemanticContext*, a: u8*, b: u8*): u8* {
    var x: usize = sem_length(a);
    var y: usize = sem_length(b);
    var result: u8* = sem_allocate(c, x + y + 1);
    copy(result, a, x);
    copy(&result[x], b, y);
    var step6 = x + y;
    result[step6] = 0;
    return result;
}

fn sem_decimal(c: SemanticContext*, value: u64): u8* {
    var buffer: u8[21];
    var i: usize = 20;
    buffer[i] = 0;
    loop {
        if !true {
            break;
        }
        i--;
        var digit: u64 = value % 10;
        var step3 = digit + 48;
        var step4 = convert(u8, step3);
        buffer[i] = step4;
        value = value / 10;
        if value == 0 {
            break;
        }
    }
    var step7 = 20 -i;
    return sem_text(c, &buffer[i], step7);
}

fn sem_type_new(c: SemanticContext*, scalar: u32, pointers: u32, record: void*): FoundationType* {
    var step2 = sem_allocate(c, sizeof(FoundationType));
    var t: FoundationType* = bits(FoundationType*, step2);
    var step4 = sizeof(FoundationType);
    fill(t, 0, step4);
    t.scalar = scalar;
    t.pointers = pointers;
    t.record = record;
    t.pointer_bytes = c.program.pointer_bytes;
    return t;
}

fn sem_type_copy(c: SemanticContext*, t: FoundationType*): FoundationType* {
    var result: FoundationType* = sem_type_new(c, SI32, 0, null);
    *result = *t;
    return result;
}

fn sem_set_type(out: FoundationType*, t: FoundationType*): void {
    *out = *t;
}

fn sem_type_name(c: SemanticContext*, t: FoundationType*): u8* {
    var name: u8* = "";
    if t.scalar == SFunction {
        var signature = sem_get(t.record);
        name = sem_cat(c, "function(", sem_type_name(c, &signature.element));
        foreach(var parameter in &signature.parameters) {
            name = sem_cat(c, name, sem_cat(c, ", ", sem_type_name(c, &sem_get(parameter).type)));
        }
        name = sem_cat(c, name, ")");
    } else { if t.scalar == SArray {
        var a: FoundationNode* = sem_get(t.record);
        var step4 = sem_cat(c, sem_type_name(c, &a.element), "[");
        var step6 = sem_decimal(c, convert(u64, a.length));
        name = sem_cat(c, sem_cat(c, step4, step6), "]");
    } else {
        var step9 = t.scalar == SStruct;
        if semantic_enum(t) {
            step9 = true;
        }
        if step9 {
            name = sem_name(sem_get(t.record));
        } else {
            name = semantic_scalar_name(t.scalar);
        }
    }
    }
    for(var i: u32 = 0; i < t.pointers; i++) {
        name = sem_cat(c, name, "*");
    }
    return name;
}

fn sem_number(c: SemanticContext*, value: u64, t: FoundationType*): u8* {
    var mask: u64 = semantic_mask(t);
    value = value & mask;
    var sign: u64 = mask / 2;
    sign++;
    if semantic_signed(t) &&(value &sign) != 0 {
        var negative: u64 = 0;
        negative = negative - value;
        var step9 = sem_decimal(c, negative &mask);
        return sem_cat(c, "-", step9);
    }
    return sem_decimal(c, value);
}

fn sem_name(n: FoundationNode*): u8* {
    if n.name.data == null {
        return "";
    }
    return n.name.data;
}

fn sem_set_name(n: FoundationNode*, name: u8*): void {
    var count: usize = sem_length(name);
    var step2 = count + 1;
    sem_require(vector_reserve(&n.name, step2));
    var step4 = count + 1;
    copy(n.name.data, name, step4);
    n.name.length = count;
}

fn sem_push(v: vector(void*)*, n: void*): void {
    sem_require(vector_push(v, n));
}

fn sem_list(c: SemanticContext*): vector(void*)* {
    var step1 = sizeof(vector(void*));
    var step2 = sem_allocate(c, step1);
    var v: vector(void*)* = bits(vector(void*)*, step2);
    var step4 = sizeof(vector(void*));
    fill(v, 0, step4);
    var step5 = bits(void*, v);
    sem_require(vector_push(&c.lists, step5));
    return v;
}

fn sem_has(v: vector(void*)*, n: void*): bool {
    foreach(var & v_item in v) {
        if *v_item == n {
            return true;
        }
    }
    return false;
}

// Push in reverse so popping visits source children in their original order.
// Neither scan calls semantic resolution or another scan while scratch is live.
fn sem_scan_children(c: SemanticContext*, n: void*): void {
    var i = sem_child_count(n);
    while i != 0 {
        i--;
        sem_require(stack_push(&c.scan, sem_child(n, i)));
    }
}

fn sem_collect(c: SemanticContext*, n: void*, wanted: u8*): vector(void*)* {
    var result = sem_list(c);
    if n != null {
        sem_require(stack_push(&c.scan, n));
    }
    var at: void* = null;
    while stack_pop(&c.scan, &at) {
        if sem_is(at, wanted) {
            sem_push(result, at);
        } else {
            sem_scan_children(c, at);
        }
    }
    return result;
}

fn sem_tokens(c: SemanticContext*, n: void*): u8* {
    c.token_text.length = 0;
    if n != null {
        sem_require(stack_push(&c.scan, n));
    }
    var at: void* = null;
    while stack_pop(&c.scan, &at) {
        var parsed = sem_match(at);
        var is_token = parsed != null;
        is_token &&= parsed.rule == sem_maximum();
        if is_token {
            sem_require(bytes_append(&c.token_text, parsed.label.data, parsed.label.length));
        } else {
            sem_scan_children(c, at);
        }
    }
    // Identifier decoding mutates this owned copy, never the parsed token or
    // scratch storage subsequently reused by another query.
    return sem_text(c, c.token_text.data, c.token_text.length);
}

fn sem_identifier(c: SemanticContext*, n: void*): u8* {
    var text: u8* = sem_tokens(c, n);
    sem_decode_identifier(text);
    return text;
}

fn sem_literal(c: SemanticContext*, n: void*): bool {
    // Rich expressions can start with digits or '-'; that does not make the
    // whole expression an untyped literal. Only unwrap transparent/group nodes.
    loop {
        var wrapper = sem_is(n, "TowerExpression") || sem_is(n, "TowerComma")
        || sem_is(n, "CoreOperand") || sem_is(n, "CoreValue") || sem_is(n, "CoreCallArgument");
        if !wrapper {
            break;
        }
        if sem_child_count(n) == 1 {
            n = sem_child(n, 0);
        }
        else {
            var group = sem_member(n, "value");
            if group != null {
                n = group;
            }
            else {
                break;
            }
        }
    }
    if sem_is(n, "TowerDefault") { return sem_member(n, "type") == null; }
    if sem_is(n, "TowerInitializer") { return sem_member(n, "type") == null; }
    if sem_is(n, "TowerExpression") || sem_is(n, "TowerComma") {
        var right = sem_member(n, "right");
        if right == null || sem_member(n, "left") != null {
            return false;
        }
        if !sem_equal(sem_tokens(c, sem_child(n, 0)), "-") {
            return false;
        }
        return sem_literal(c, right);
    }
    var text: u8* = sem_tokens(c, n);
    var step3 = sem_equal(text, "true") || sem_equal(text, "false") || sem_equal(text, "null") || text[0] == 39 || text[0] == 34 || text[0] == 45 || text[0] >= 48 && text[0] <= 57;
    return step3;
}

fn sem_unwrap(n: void*): void* {
    if sem_is(n, "Statement") && sem_child_count(n) == 1 {
        return sem_child(n, 0);
    }
    return n;
}

fn sem_maximum(): usize {
    var n: usize = 0;
    return n -1;
}

fn sem_hash(key: u8*): usize {
    var h: usize = 2166136261;
    for(var i: usize = 0; key[i] != 0; i++) {
        var step3 = convert(usize, key[i]);
        h = h ^ step3;
        h = h * 16777619;
    }
    return h;
}

fn sem_table(c: SemanticContext*): SemanticTable* {
    var step2 = sem_allocate(c, sizeof(SemanticTable));
    var t: SemanticTable* = bits(SemanticTable*, step2);
    var step4 = sizeof(SemanticTable);
    fill(t, 0, step4);
    return t;
}

fn sem_find(t: SemanticTable*, text: u8*, entity: void*): SemanticEntry* {
    if t.capacity == 0 {
        return null;
    }
    var h: usize = bits(usize, entity);
    if text != null {
        h = sem_hash(text) ^ h;
    } else {
        h = h / 8;
    }
    var i: usize = h % t.capacity;
    loop {
        if t.entries[i] == null {
            break;
        }
        var entry: SemanticEntry* = t.entries[i];
        if text != null {
            var step11 = entry.text != null;
            if step11 {
                step11 = sem_equal(entry.text, text);
                step11 &&= entry.entity == entity;
            }
            if step11 {
                return entry;
            }
        } else {
            if entry.text == null && entry.entity == entity {
                return entry;
            }
        }
        i =(i + 1) % t.capacity;
    }
    return null;
}

fn sem_insert(t: SemanticTable*, entry: SemanticEntry*): void {
    var h: usize = bits(usize, entry.entity);
    if entry.text != null {
        h = sem_hash(entry.text) ^ h;
    } else {
        h = h / 8;
    }
    var i: usize = h % t.capacity;
    loop {
        if t.entries[i] == null {
            break;
        }
        i =(i + 1) % t.capacity;
    }
    t.entries[i] = entry;
}

fn sem_entry(c: SemanticContext*, t: SemanticTable*, text: u8*, entity: void*): SemanticEntry* {
    var found: SemanticEntry* = sem_find(t, text, entity);
    if found != null {
        return found;
    }
    if(t.count + 1) *2 >= t.capacity {
        var capacity: usize = t.capacity *2;
        if capacity < 16 {
            capacity = 16;
        }
        var old: SemanticEntry** = t.entries;
        var count: usize = t.capacity;
        var step8 = sizeof(SemanticEntry*);
        var step10 = sem_allocate(c, capacity *step8);
        var step11 = bits(SemanticEntry **, step10);
        t.entries = step11;
        var step12 = sizeof(SemanticEntry*);
        var step13 = capacity *step12;
        fill(t.entries, 0, step13);
        t.capacity = capacity;
        for(var i: usize = 0; i < count; i++) {
            if old[i] != null {
                sem_insert(t, old[i]);
            }
        }
    }
    var step18 = sem_allocate(c, sizeof(SemanticEntry));
    var result: SemanticEntry* = bits(SemanticEntry*, step18);
    var step20 = sizeof(SemanticEntry);
    fill(result, 0, step20);
    result.text = text;
    result.entity = entity;
    sem_insert(t, result);
    t.count++;
    return result;
}

fn sem_lookup_table(t: SemanticTable*, text: u8*): void* {
    var found: SemanticEntry* = sem_find(t, text, null);
    if found == null {
        return null;
    }
    return found.value;
}

fn sem_put(c: SemanticContext*, t: SemanticTable*, text: u8*, value: void*): bool {
    var found: SemanticEntry* = sem_entry(c, t, text, null);
    if found.value != null {
        return false;
    }
    found.value = value;
    return true;
}

fn sem_state(c: SemanticContext*, t: SemanticTable*, n: void*): SemanticEntry* {
    return sem_entry(c, t, null, n);
}

fn sem_source_base(c: SemanticContext*, n: void*): usize {
    loop {
        if n == null {
            break;
        }
        var found: SemanticEntry* = sem_find(c.source_bases, null, n);
        if found != null {
            return found.number;
        }
        if c.program.modules != null {
            var component = entity_component_get(n, c.program.modules.owner_kind);
            var link = bits(SemanticModuleLink*, entity_component_data(component));
            if link != null {
                if link.module == n {
                    return link.base;
                }
            }
        }
        n = sem_parent(n);
    }
    return 0;
}

fn sem_offset(c: SemanticContext*, n: void*): usize {
    var m: ParserMatchData* = sem_match(n);
    var at: usize = sem_source_base(c, n);
    if m != null {
        at = at + m.start;
    }
    return at;
}

fn sem_ok(c: SemanticContext*): bool {
    return c.program.error.length == 0;
}

fn sem_instantiation_use(c: SemanticContext*, n: void*): void* {
    var use = generic_origin(c.generics, n);
    if use == null || c.body_demands == null { return use; }
    var function = n;
    while function != null && !sem_is(function, "CoreFunction") { function = sem_parent(function); }
    if function != null {
        var demand = bits(SemanticBodyDemand*, entity_component_data(entity_component_get(function, c.body_demands)));
        if demand != null { return demand.source; }
    }
    return use;
}

fn sem_fail(c: SemanticContext*, n: void*, text: u8*): void {
    if !sem_ok(c) {
        return;
    }
    var step3 = sem_offset(c, n);
    c.program.error_offset = step3;
    var seen: vector(void*)* = sem_list(c);
    var use: void* = sem_instantiation_use(c, n);
    loop {
        if !(use != null && seen.length < 8 && !sem_has(seen, use)) {
            break;
        }
        sem_push(seen, use);
        var at: usize = sem_offset(c, use);
        var line: u64 = 1;
        var column: u64 = 1;
        var i: usize = 0;
        loop {
            if !(i < at && c.source[i] != 0) {
                break;
            }
            if c.source[i] == 10 {
                line++;
                column = 1;
            } else {
                column++;
            }
            i++;
        }
        var step18 = sem_tokens(c, use);
        var step19 = sem_cat(c, "\nInstantiated by ", step18);
        text = sem_cat(c, text, step19);
        var step21 = sem_decimal(c, line);
        var step22 = sem_cat(c, " at line ", step21);
        text = sem_cat(c, text, step22);
        var step24 = sem_decimal(c, column);
        var step25 = sem_cat(c, step24, ".");
        var step26 = sem_cat(c, ", column ", step25);
        text = sem_cat(c, text, step26);
        use = sem_instantiation_use(c, use);
    }
    var count: usize = sem_length(text);
    var step30 = count + 1;
    sem_require(vector_reserve(&c.program.error, step30));
    var step32 = count + 1;
    copy(c.program.error.data, text, step32);
    c.program.error.length = count;
}

fn sem_generic_ok(c: SemanticContext*, n: void*): bool {
    var error: u8* = generic_error(c.generics);
    if error != null {
        sem_fail(c, n, error);
    }
    return sem_ok(c);
}

fn sem_shape(c: SemanticContext*, n: void*, capture: u8*): bool {
    if n == null {
        sem_fail(c, n, "Missing foundation tree");
        return false;
    }
    if sem_member(n, capture) == null {
        var step4 = sem_label(n);
        var step6 = sem_cat(c, sem_cat(c, "Malformed ", step4), " tree: missing capture '");
        var step7 = sem_cat(c, capture, "'");
        sem_fail(c, n, sem_cat(c, step6, step7));
        return false;
    }
    return true;
}

fn sem_node(c: SemanticContext*, n: void*, kind: u32): FoundationNode* {
    var fresh: bool = sem_get(n) == null;
    var result: FoundationNode* = sem_attach(n, kind);
    var step4 = sem_offset(c, n);
    result.start = step4;
    result.end = result.start;
    var m: ParserMatchData* = sem_match(n);
    if m != null {
        result.end = result.end + m.length;
    }
    if fresh {
        c.count++;
        if c.count > c.node_limit {
            sem_fail(c, n, "Foundation component memory budget exceeded");
        }
    }
    return result;
}

