fn syntax_highlight_style(value: SyntaxHighlights*, text: u8*): u8* {
    var length = syntax_text_length(text);
    if length == 0 {
        return "";
    }
    foreach(var & style in &value.styles) {
        if syntax_bytes_compare(style.data, style.length, text, length) == 0 {
            return style.data;
        }
    }
    if !vector_reserve(&value.styles, value.styles.length + 1) {
        return null;
    }
    var style = &value.styles.data[value.styles.length];
    vector_init(style);
    if !node_text_set(style, text) {
        return null;
    }
    value.styles.length++;
    return style.data;
}

export fn syntax_highlights_clear(value: SyntaxHighlights*): void {
    foreach(var & style in &value.styles) {
        vector_dispose(style);
    }
    value.styles.length = 0;
    value.items.length = 0;
}

export fn syntax_highlights_dispose(value: SyntaxHighlights*): void {
    syntax_highlights_clear(value);
    vector_dispose(&value.styles);
    vector_dispose(&value.items);
}

export fn syntax_highlights_push(value: SyntaxHighlights*, start: usize, end: usize, revision: usize, style: u8*, id: u32, opaque: bool): bool {
    var name = syntax_highlight_style(value, style);
    if name is null || !vector_reserve(&value.items, value.items.length + 1) {
        return false;
    }
    var row = &value.items.data[value.items.length++];
    row.start = start;
    row.end = end;
    row.revision = revision;
    row.kind = name;
    row.opaque = opaque;
    row.id = id;
    return true;
}

// Existing void scanner callback cannot report allocation failure. Preserve its
// former fatal allocation policy; fallible owner operations are tested directly.
export fn syntax_scan_highlight(host: void*, start: usize, end: usize, revision: usize, style: u8*, id: u32, skipped: bool): void {
    if !syntax_highlights_push(bits(SyntaxHighlights*, host), start, end, revision, style, id,
    skipped || id == convert(u32, SyntaxTokenId.String)) {
        abort();
    }
}

export fn syntax_highlights_style(value: SyntaxHighlights*, index: usize, style: u8*): void {
    var name = syntax_highlight_style(value, style);
    if name is null {
        abort();
    }
    value.items.data[index].kind = name;
}

export fn syntax_highlights_copy(target: SyntaxHighlights*, source: SyntaxHighlights*): bool {
    if target == source {
        return true;
    }
    var prepared: SyntaxHighlights = default;
    defer syntax_highlights_dispose(&prepared);
    foreach(var & row in &source.items) {
        if !syntax_highlights_push(&prepared, row.start, row.end, row.revision, row.kind, row.id, row.opaque) {
            return false;
        }
    }
    syntax_highlights_dispose(target);
    copy(target, &prepared, sizeof(SyntaxHighlights));
    prepared = default;
    return true;
}

import tower;
import frontend_revision_types;
import parser_types;
import syntax_emission_types;
import syntax_replacement_types;
import syntax_session_types;
import syntax_view;

extern fn entity_component_get(node: void*, kind: void*): void*;
extern fn entity_component_data(component: void*): void*;
extern fn syntax_revision_reference(revision: FrontendRevision*, text: u8*, length: usize, index: usize, count: usize*, kind: void*): void*;
extern fn syntax_revision_rule(revision: FrontendRevision*, name: u8*, length: usize): SyntaxRuleView*;
extern fn syntax_emission_find_index(emission: void*, index: usize): SyntaxEmissionProduction*;
extern fn syntax_replacement_inspect(owner: void*, grammar: FrontendRevision*, body: void*): SyntaxReplacement*;

// Read-only borrowed views. The caller keeps the session revision pinned and
// retains returned entities before advancing or destroying that session.
export fn syntax_inspection_reference(session: SyntaxSession*, text: u8*, length: usize, index: usize, count: usize*): void* {
    *count = 0;
    var version = session.pins.version;
    if version is null { return null; }
    return syntax_revision_reference(version.grammar, text, length, index, count, version.kinds.syntax);
}

export fn syntax_inspection_match(session: SyntaxSession*, node: void*): void* {
    var version = session.pins.version;
    if version is null { return null; }
    var span = bits(ParserMatchData*, entity_component_data(entity_component_get(node, version.kinds.`match`)));
    if span is null { return null; }
    var production = syntax_emission_find_index(version.emission, span.rule);
    if production is null { return null; }
    var length: usize = 0;
    while production.name[length] != 0 {
        if length >= span.label.length || production.name[length] != span.label.data[length] { return null; }
        ++length;
    }
    if length != span.label.length { return null; }
    var found = syntax_revision_rule(version.grammar, production.name, length);
    return found is not null && production.alternative < found.count ? found.alternatives[production.alternative] : null;
}

fn inspection_replacement(session: SyntaxSession*, body: void*): SyntaxReplacement* {
    var version = session.pins.version;
    return version is null ? null : syntax_replacement_inspect(version.replacements, version.grammar, body);
}

export fn syntax_inspection_template(session: SyntaxSession*, body: void*, category: u8**, captures: usize*): void* {
    *category = "";
    *captures = 0;
    var replacement = inspection_replacement(session, body);
    if replacement is null { return null; }
    *category = replacement.category.data ?? "";
    *captures = replacement.captures.length;
    return replacement.tree;
}

export fn syntax_inspection_capture(session: SyntaxSession*, body: void*, index: usize): void* {
    var replacement = inspection_replacement(session, body);
    return replacement is null || index >= replacement.captures.length ? null : replacement.captures.data[index].source;
}

import tower;
import lexer_table;
import lr_analysis;
import lr_runtime;
import lr_states;
import syntax_types;
import .library.vector;
import lr_types;

// A revision's disposable lexical index. Patterns and text borrow its immutable
// declaration entities; declarations remain the authoritative grammar nodes.
struct LexiconToken {
    table: LexerTable*;
    id: u32;
    style: u8*;
    skipped: bool;
    contextual: bool;
    identifier: bool;
}

struct LexiconLiteral {
    text: u8*;
    length: usize;
    id: u32;
    word: bool;
    declaration: bool;
}

struct SyntaxLexicon {
    tokens: vector(LexiconToken);
    literals: vector(LexiconLiteral);
    starts: vector(LexiconLiteral);
}

struct LexiconChoice {
    length: usize;
    id: u32;
    style: u8*;
    skipped: bool;
    checks: usize;
}

fn lexicon_letter(byte: u8): bool {
    var valid = byte >= 97;
    valid &&= byte <= 122;
    if valid {
        return true;
    }
    valid = byte >= 65;
    valid &&= byte <= 90;
    if valid {
        return true;
    }
    valid = byte == 95;
    return valid;
}

fn lexicon_word(text: u8*, length: usize): bool {
    if length == 0 {
        return false;
    }
    var valid = lexicon_letter(text[0]);
    if !valid {
        return false;
    }
    var index: usize = 1;
    loop {
        if index == length {
            return true;
        }
        var byte = text[index];
        valid = lexicon_letter(byte);
        if !valid {
            valid = byte >= 48;
            valid &&= byte <= 57;
            if !valid {
                return false;
            }
        }
        index++;
    }
}

fn lexicon_prefix(source: u8*, length: usize, start: usize, text: u8*, count: usize): bool {
    var invalid = start > length;
    if invalid {
        return false;
    }
    var remaining = length -start;
    invalid = count > remaining;
    if invalid {
        return false;
    }
    var index: usize = 0;
    loop {
        if index == count {
            return true;
        }
        var at = start + index;
        if source[at] != text[index] {
            return false;
        }
        index++;
    }
}

export fn lexicon_create(): SyntaxLexicon* {
    var value = alloc(SyntaxLexicon, 1);
    if value != null {
        *value = default;
    }
    return value;
}

export fn lexicon_destroy(value: SyntaxLexicon*): void {
    if value == null {
        return;
    }
    vector_dispose(&value.tokens);
    vector_dispose(&value.literals);
    vector_dispose(&value.starts);
    free(value);
}

export fn lexicon_token(value: SyntaxLexicon*, table: LexerTable*, id: u32, style: u8*, skipped: bool, contextual: bool, identifier: bool): bool {
    var entry: LexiconToken = {
        table: table, id: id, style: style, skipped: skipped, contextual: contextual, identifier: identifier
    };
    return lr_append(LexiconToken, &value.tokens, &entry);
}

export fn lexicon_literal(value: SyntaxLexicon*, text: u8*, length: usize, id: u32, declaration: bool): bool {
    var literal: LexiconLiteral = { text: text, length: length, id: id, word: lexicon_word(text, length), declaration: declaration };
    return lr_append(LexiconLiteral, &value.literals, &literal);
}

export fn lexicon_start(value: SyntaxLexicon*, text: u8*, length: usize): bool {
    var literal: LexiconLiteral = default;
    literal.text = text;
    literal.length = length;
    return lr_append(LexiconLiteral, &value.starts, &literal);
}

fn lexicon_choice_init(choice: LexiconChoice*): void {
    *choice = default;
    choice.id = 4294967294;
    choice.style = "";
}

fn lexicon_accepts(runtime: LRRuntime*, state: usize, id: u32, choice: LexiconChoice*): bool {
    if runtime == null {
        return false;
    }
    if state >= runtime.states.length {
        return false;
    }
    choice.checks++;
    var action: LRAction;
    return lr_runtime_action(runtime, state, id, &action);
}

// Longest match, then declaration order. Contextual ties prefer an accepted
// token; equal-length literals win. The exact same path serves diagnostic peeks.
export fn lexicon_choose(value: SyntaxLexicon*, source: u8*, length: usize, start: usize, declaration: bool, runtime: LRRuntime*, state: usize, choice: LexiconChoice*): void {
    lexicon_choice_init(choice);
    var index: usize = 0;
    for(; index != value.tokens.length; index++) {
        var entry = &value.tokens.data[index];
        var eligible = true;
        if entry.contextual {
            eligible = lexicon_accepts(runtime, state, entry.id, choice);
        }
        if eligible {
            var count = lex_table_match(entry.table, source, length, start);
            var selected = count > choice.length;
            if !selected {
                var tie = count != 0;
                tie &&= count == choice.length;
                if tie {
                    if entry.contextual {
                        selected = lexicon_accepts(runtime, state, choice.id, choice);
                        selected = !selected;
                    }
                }
            }
            if selected {
                choice.length = count;
                choice.id = entry.id;
                choice.style = entry.style;
                choice.skipped = entry.skipped;
            }
        }
    }
    index = 0;
    for(; index != value.literals.length; index++) {
        var literal = &value.literals.data[index];
        var eligible = !declaration;
        if literal.declaration {
            eligible = true;
        }
        eligible ||= lexicon_accepts(runtime, state, literal.id, choice);
        if eligible {
            eligible = literal.length >= choice.length;
            eligible &&= lexicon_prefix(source, length, start, literal.text, literal.length);
            if eligible {
                choice.length = literal.length;
                choice.id = literal.id;
                choice.style = "operator";
                if literal.word {
                    choice.style = "keyword";
                }
                choice.skipped = false;
            }
        }
    }
}

export fn lexicon_skip(value: SyntaxLexicon*, source: u8*, length: usize, start: usize, choice: LexiconChoice*): void {
    lexicon_choice_init(choice);
    var index: usize = 0;
    loop {
        if index == value.tokens.length {
            return;
        }
        var entry = &value.tokens.data[index];
        if entry.skipped {
            var count = lex_table_match(entry.table, source, length, start);
            if count > choice.length {
                choice.length = count;
                choice.id = entry.id;
                choice.style = entry.style;
                choice.skipped = true;
            }
        }
        index++;
    }
}

export fn lexicon_identifier(value: SyntaxLexicon*, source: u8*, length: usize, start: usize): usize {
    var index: usize = 0;
    loop {
        if index == value.tokens.length {
            return 0;
        }
        var entry = &value.tokens.data[index];
        if entry.identifier {
            return lex_table_match(entry.table, source, length, start);
        }
        index++;
    }
}

export fn lexicon_declaration(value: SyntaxLexicon*, source: u8*, length: usize, start: usize): bool {
    var index: usize = 0;
    loop {
        var done = index == value.starts.length;
        if done {
            return false;
        }
        var keyword = &value.starts.data[index];
        if lexicon_prefix(source, length, start, keyword.text, keyword.length) {
            var position: usize = 0;
            loop {
                done = position == value.tokens.length;
                if done {
                    return true;
                }
                var entry = &value.tokens.data[position];
                var eligible = !entry.skipped;
                if entry.contextual {
                    eligible = false;
                }
                if eligible {
                    var count = lex_table_match(entry.table, source, length, start);
                    if count > keyword.length {
                        break;
                    }
                }
                position++;
            }
        }
        index++;
    }
}

import tower;
import syntax_types;
import lexer_table;
import lr_tree;
import regex_lowering;
import syntax_source;
import .library.vector;

// Grammar declarations augment the same entities used by syntax and foundation.
// Source entities are authoritative; lexer tables and comparison work lists are derived.
extern fn entity_retain(node: void*): usize;

export fn syntax_pattern_size(): usize {
    return sizeof(SyntaxPattern);
}

export fn syntax_pattern_retain(value: SyntaxPattern*): void {
    if value != null {
        value.references++;
    }
}

export fn syntax_pattern_release(value: SyntaxPattern*): void {
    if value == null {
        return;
    }
    value.references--;
    if value.references == 0 {
        lex_table_destroy(value.table);
        if value.grammar != null {
            entity_release(value.grammar);
        }
        free(value);
    }
}

export fn syntax_pattern_create(grammar: void*): SyntaxPattern* {
    var value = alloc(SyntaxPattern, 1);
    var failed = value == null;
    if failed {
        return null;
    }
    *value = default;
    value.references = 1;
    value.table = lex_table_create();
    failed = value.table == null;
    if failed {
        syntax_pattern_release(value);
        return null;
    }
    if grammar != null {
        entity_retain(grammar);
    }
    value.grammar = grammar;
    return value;
}

export fn syntax_node_size(): usize {
    return sizeof(SyntaxNode);
}

export fn syntax_node_init(value: SyntaxNode*): void {
    *value = default;
    value.start = 0;
    value.start--;
    value.end = value.start;
}

export fn syntax_node_source(value: SyntaxNode*, source: SyntaxSource*): void {
    syntax_source_retain(source);
    syntax_source_release(value.source);
    value.source = source;
}

export fn syntax_node_pattern(value: SyntaxNode*, pattern: SyntaxPattern*): void {
    syntax_pattern_retain(pattern);
    syntax_pattern_release(value.compiled);
    value.compiled = pattern;
}

export fn syntax_node_replacement(value: SyntaxNode*, replacement: void*): void {
    var present = replacement != null;
    if present {
        entity_retain(replacement);
    }
    present = value.replacement != null;
    if present {
        entity_release(value.replacement);
    }
    value.replacement = replacement;
}

// Copy before growing the list: text may refer to an existing comment.
// On failure retain all existing entries and dispose the temporary copy.
export fn syntax_comments_push(comments: vector(vector(u8))*, text: u8*, length: usize): bool {
    var needed = length + 1;
    var overflow = needed == 0;
    if overflow {
        return false;
    }
    var count = comments.length + 1;
    overflow = count == 0;
    if overflow {
        return false;
    }
    var snapshot: vector(u8);
    vector_init(&snapshot);
    var ok = vector_reserve(&snapshot, needed);
    if ok {
        if length != 0 {
            copy(snapshot.data, text, length);
        }
        snapshot.data[length] = 0;
        snapshot.length = length;
        ok = vector_reserve(comments, count);
    }
    if ok {
        var target = &comments.data[comments.length];
        target.data = snapshot.data;
        target.length = snapshot.length;
        target.capacity = snapshot.capacity;
        comments.length = count;
    } else {
        vector_dispose(&snapshot);
    }
    return ok;
}

export fn syntax_node_dispose(value: SyntaxNode*): void {
    vector_dispose(&value.name);
    vector_dispose(&value.text);
    vector_dispose(&value.capture);
    vector_dispose(&value.style);
    vector_dispose(&value.items);
    vector_dispose(&value.attributes);
    foreach(var & comment in &value.comments) {
        vector_dispose(comment);
    }
    vector_dispose(&value.comments);
    syntax_node_source(value, null);
    syntax_node_pattern(value, null);
    syntax_node_replacement(value, null);
}

fn syntax_text_equal(left: vector(u8)*, right: vector(u8)*): bool {
    var different = left.length != right.length;
    if different {
        return false;
    }
    var index: usize = 0;
    loop {
        if index == left.length {
            return true;
        }
        different = left.data[index] != right.data[index];
        if different {
            return false;
        }
        index++;
    }
}

struct SyntaxComparison {
    left: void*;
    right: void*;
}

fn syntax_comparison_push(pending: vector(SyntaxComparison)*, left: void*, right: void*): bool {
    var count = pending.length + 1;
    if count == 0 {
        return false;
    }
    var ok = vector_reserve(pending, count);
    if ok {
        pending.data[pending.length].left = left;
        pending.data[pending.length].right = right;
        pending.length = count;
    }
    return ok;
}

// 1 equal, 0 different, -1 allocation failure. Metadata and cache addresses do
// not affect parser identity. Template coordinates matter only when requested.
export fn syntax_nodes_equal(left: void*, right: void*, kind: void*, locations: bool): i32 {
    if left == right {
        return 1;
    }
    var pending: vector(SyntaxComparison);
    vector_init(&pending);
    var ok = syntax_comparison_push(&pending, left, right);
    var result: i32 = 1;
    loop {
        if !ok {
            result = -1;
            break;
        }
        if pending.length == 0 {
            break;
        }
        pending.length--;
        left = pending.data[pending.length].left;
        right = pending.data[pending.length].right;
        var same = left == right;
        if same {
            continue;
        }
        var missing = left == null;
        if missing {
            result = 0;
            break;
        }
        missing = right == null;
        if missing {
            result = 0;
            break;
        }
        var component = entity_component_get(left, kind);
        var x = bits(SyntaxNode*, entity_component_data(component));
        component = entity_component_get(right, kind);
        var y = bits(SyntaxNode*, entity_component_data(component));
        missing = x == null;
        if missing {
            result = 0;
            break;
        }
        missing = y == null;
        if missing {
            result = 0;
            break;
        }
        same = x.kind == y.kind;
        same &&= x.precedence == y.precedence;
        same &&= x.associativity == y.associativity;
        same &&= syntax_text_equal(&x.name, &y.name);
        same &&= syntax_text_equal(&x.text, &y.text);
        same &&= syntax_text_equal(&x.capture, &y.capture);
        same &&= syntax_text_equal(&x.style, &y.style);
        same &&= x.literal == y.literal;
        same &&= x.append == y.append;
        same &&= x.contextual == y.contextual;
        same &&= x.terminal_set == y.terminal_set;
        same &&= x.repetition == y.repetition;
        same &&= x.items.length == y.items.length;
        same &&= x.attributes.length == y.attributes.length;
        if locations {
            if x.kind == 6 {
                same &&= x.start == y.start;
                same &&= x.end == y.end;
            }
        }
        if !same {
            result = 0;
            break;
        }
        var index: usize = 0;
        for(; index != x.items.length; index++) {
            ok = syntax_comparison_push(&pending, x.items.data[index], y.items.data[index]);
            if !ok {
                break;
            }
        }
        ok &&= syntax_comparison_push(&pending, x.replacement, y.replacement);
        for(var index: usize = 0; index < x.attributes.length && ok; index++) {
            ok = syntax_comparison_push(&pending, x.attributes.data[index], y.attributes.data[index]);
        }
    }
    vector_dispose(&pending);
    return result;
}

// Temporary native ABI verification under each explicit target layout.
export fn syntax_node_offset(field: usize): usize {
    var value: SyntaxNode;
    var base = bits(usize, &value);
    var address = base;
    var selected: bool;
    selected = field == 0;
    if selected {
        address = bits(usize, &value.kind);
    }
    selected = field == 1;
    if selected {
        address = bits(usize, &value.name);
    }
    selected = field == 2;
    if selected {
        address = bits(usize, &value.text);
    }
    selected = field == 3;
    if selected {
        address = bits(usize, &value.capture);
    }
    selected = field == 4;
    if selected {
        address = bits(usize, &value.style);
    }
    selected = field == 5;
    if selected {
        address = bits(usize, &value.source);
    }
    selected = field == 6;
    if selected {
        address = bits(usize, &value.literal);
    }
    selected = field == 7;
    if selected {
        address = bits(usize, &value.append);
    }
    selected = field == 8;
    if selected {
        address = bits(usize, &value.contextual);
    }
    selected = field == 9;
    if selected {
        address = bits(usize, &value.terminal_set);
    }
    selected = field == 10;
    if selected {
        address = bits(usize, &value.repetition);
    }
    selected = field == 11;
    if selected {
        address = bits(usize, &value.items);
    }
    selected = field == 12;
    if selected {
        address = bits(usize, &value.replacement);
    }
    selected = field == 13;
    if selected {
        address = bits(usize, &value.comments);
    }
    selected = field == 14;
    if selected {
        address = bits(usize, &value.start);
    }
    selected = field == 15;
    if selected {
        address = bits(usize, &value.end);
    }
    selected = field == 16;
    if selected {
        address = bits(usize, &value.compiled);
    }
    var offset = address -base;
    return offset;
}

import tower;
import frontend_cache;
import frontend_revision_types;
import format_api;
import format_types;
import syntax_reader;
import syntax_validation;
import syntax_view;
import syntax_types;
import lr_analysis;
import lr_tree;
import regex_lowering;
import .library.vector;

// Frozen analysis over retained grammar entities, not a second grammar graph.
// Construction owns all mutation; queries borrow stable names and diagnostics.
struct SyntaxPendingRevision {
    owner: FrontendRevision*;
    terms: void**;
    count: usize;
    message: vector(u8);
    offset: usize;
}

export fn syntax_pending_destroy(value: SyntaxPendingRevision*): void {
    if value is null {
        return;
    }
    frontend_revision_release(value.owner);
    free(value.terms);
    vector_dispose(&value.message);
    free(value);
}

fn syntax_pending_format(value: SyntaxPendingRevision*, kind: void*): bool {
    var result: FormatResult = default;
    defer format_dispose(&result);
    var format: FormatEngine = default;
    format.result = &result;
    format_text(&format, "Unresolved grammar reference at end of module: ");
    var rules = &value.owner.rules;
    var name = rules.data[0].name;
    var length = rules.data[0].name_length;
    format_write(&format, name, length);
    var index: usize = 0;
    var visited: usize = 0;
    while index != lr_none() {
        // Successful validation cannot produce a cyclic missing-reference chain.
        if visited == value.count {
            return false;
        }
        ++visited;
        var component = entity_component_get(value.terms[index], kind);
        var term = bits(SyntaxNode*, entity_component_data(component));
        if term.start != lr_none() {
            value.offset = term.start;
        }
        name = term.text.data;
        length = term.text.length;
        format_text(&format, " -> ");
        format_write(&format, name, length);
        index = syntax_rule_find(rules.data, rules.length, name, length);
    }
    format_text(&format, " (undefined rule '");
    format_write(&format, name, length);
    format_text(&format, "')");
    var ok = !result.failed && vector_push(&result.text, 0);
    if ok {
        copy(&value.message, &result.text, sizeof(vector(u8)));
        fill(&result.text, 0, sizeof(vector(u8)));
    }
    return ok;
}

// rules are sorted by name; waiting contains the validator's source-term views.
// Copy only pending rules and retain their alternatives through FrontendRevision.
// An empty successful revision is null: the common ready path allocates nothing.
export fn syntax_pending_create(rules: SyntaxRuleView*, count: usize, waiting: void**, kind: void*, out: SyntaxPendingRevision**): bool {
    *out = null;
    var total: usize = 0;
    var index: usize = 0;
    while index < count {
        if waiting[index] is not null {
            ++total;
        }
        ++index;
    }
    if total == 0 {
        return true;
    }
    if total > ~convert(usize, 0) / sizeof(SyntaxRuleView) {
        return false;
    }
    var value = alloc(SyntaxPendingRevision, 1);
    if value is null {
        return false;
    }
    *value = default;
    value.offset = lr_none();
    var selected = alloc(SyntaxRuleView, total);
    value.terms = alloc(void*, total);
    if selected is null || value.terms is null {
        free(selected);
        syntax_pending_destroy(value);
        return false;
    }
    index = 0;
    while index < count {
        if waiting[index] is not null {
            copy(&selected[value.count], &rules[index], sizeof(SyntaxRuleView));
            value.terms[value.count] = waiting[index];
            ++value.count;
        }
        ++index;
    }
    value.owner = frontend_revision_create(selected, total, null, 0);
    free(selected);
    if value.owner is null || !syntax_pending_format(value, kind) {
        syntax_pending_destroy(value);
        return false;
    }
    *out = value;
    return true;
}

export fn syntax_pending_count(value: SyntaxPendingRevision*): usize {
    return value ?. count ?? 0;
}

export fn syntax_pending_name(value: SyntaxPendingRevision*, index: usize): u8* {
    if value is null || index >= value.count {
        return null;
    }
    return value.owner.rules.data[index].name;
}

export fn syntax_pending_contains(value: SyntaxPendingRevision*, name: u8*): bool {
    if value is null || value.count == 0 {
        return false;
    }
    return syntax_rule_find(value.owner.rules.data, value.count, name, syntax_text_length(name)) != lr_none();
}

export fn syntax_pending_message(value: SyntaxPendingRevision*, offset: usize*): u8* {
    if value is null || value.count == 0 {
        return "";
    }
    if offset is not null && value.offset != lr_none() {
        *offset = value.offset;
    }
    return value.message.data;
}

import tower;
import world;
import component_kinds;
import parser_types;
import syntax_types;
import .library.entities;
import .library.entity_types;
import .library.entity_stage;
import .library.vector;

extern fn bytes_assign_text(value: vector(u8)*, source: u8*, length: usize): bool;

fn provenance_owner(trace: SyntaxExpansion*): Entity* {
    var component = entity_component_from_data(bits(u8*, trace));
    return entity_component_owner(component);
}

export fn syntax_trace_retain(trace: SyntaxExpansion*): void {
    if trace != null {
        entity_retain(provenance_owner(trace));
    }
}

// Detach a uniquely owned chain before reclaiming each entity, avoiding recursive
// destruction. A pinned trace remains unchanged until the view drains.
export fn syntax_trace_release(trace: SyntaxExpansion*): void {
    loop {
        if trace == null {
            return;
        }
        var owner = provenance_owner(trace);
        var unique = entity_references(owner) == 1;
        var unpinned = owner.store.views == 0;
        if unique {
            if unpinned {
                var previous = trace.previous;
                trace.previous = null;
                entity_release(owner);
                trace = previous;
                continue;
            }
        }
        entity_release(owner);
        return;
    }
}

export fn syntax_trace_dispose(trace: SyntaxExpansion*): void {
    var previous = trace.previous;
    trace.previous = null;
    vector_dispose(&trace.rule);
    syntax_trace_release(previous);
}

export fn syntax_origin_dispose(origin: SyntaxOrigin*): void {
    syntax_trace_release(origin.expansion);
    origin.expansion = null;
    foreach(var & splice in &origin.splices) {
        syntax_trace_release(*splice);
    }
    vector_dispose(&origin.splices);
}

export fn syntax_origin_get(world: CompilerWorld*, node: Entity*): SyntaxOrigin* {
    return bits(SyntaxOrigin*, compiler_world_get(world, node, CompilerSyntaxOrigin));
}

export fn syntax_trace_create(world: CompilerWorld*, invocation: Entity*, rule: u8*, definition_start: usize, definition_end: usize): SyntaxExpansion* {
    var span = bits(ParserMatchData*, compiler_world_get(world, invocation, CompilerParserMatch));
    var missing = span == null;
    if missing {
        return null;
    }
    var owner = entity_create(world.store);
    missing = owner == null;
    if missing {
        return null;
    }
    var trace = bits(SyntaxExpansion*, compiler_world_component(world, owner, CompilerSyntaxExpansion));
    missing = trace == null;
    if missing {
        entity_release(owner);
        return null;
    }
    var length: usize = 0;
    for(; rule[length] != 0; length++) {}
    if !bytes_assign_text(&trace.rule, rule, length) {
        entity_release(owner);
        return null;
    }
    trace.start = span.start;
    trace.end = span.start + span.length;
    trace.definition_start = definition_start;
    trace.definition_end = definition_end;
    var prior = syntax_origin_get(world, invocation);
    if prior != null {
        trace.previous = prior.expansion;
        syntax_trace_retain(trace.previous);
    }
    return trace;
}

// Copies own their splice storage and retain shared immutable history. Prepare
// all allocations before replacing destination state, including self-copy.
export fn syntax_origin_copy(world: CompilerWorld*, source: Entity*, destination: Entity*): bool {
    var prior = syntax_origin_get(world, source);
    var missing = prior == null;
    if missing {
        return true;
    }
    if source == destination {
        return true;
    }
    missing = destination == null;
    if missing {
        return false;
    }
    if destination.store != world.store {
        return false;
    }
    var pending: vector(SyntaxExpansion*);
    vector_init(&pending);
    if !vector_reserve(&pending, prior.splices.length) {
        return false;
    }
    var target = bits(SyntaxOrigin*, compiler_world_component(world, destination, CompilerSyntaxOrigin));
    missing = target == null;
    if missing {
        vector_dispose(&pending);
        return false;
    }
    for(var index: usize = 0; index < prior.splices.length; index++) {
        var trace = prior.splices.data[index];
        syntax_trace_retain(trace);
        pending.data[index] = trace;
    }
    pending.length = prior.splices.length;
    syntax_trace_retain(prior.expansion);
    syntax_origin_dispose(target);
    target.template_start = prior.template_start;
    target.template_end = prior.template_end;
    target.generated = prior.generated;
    target.expansion = prior.expansion;
    copy(&target.splices, &pending, sizeof(vector(SyntaxExpansion*)));
    return true;
}

// Worker copy into a new private node only. The source history is immutable and
// pinned; shared reference counts transfer on the coordinator after join.
// Allocate everything before queuing ownership, then install without failure.
export fn syntax_origin_copy_staged(world: CompilerWorld*, source: Entity*, destination: Entity*, stage: EntityStage*): bool {
    if world == null || destination == null || stage == null
        || destination.store != world.store || destination.stage != bits(void*, stage)
        || destination.id != 0 { return false; }
    if syntax_origin_get(world, destination) != null { return false; }
    var prior = syntax_origin_get(world, source);
    if prior == null { return true; }
    if prior.splices.length == ~convert(usize, 0) { return false; }
    var pending: vector(SyntaxExpansion*) = default;
    defer vector_dispose(&pending);
    var references: vector(Entity*) = default;
    defer vector_dispose(&references);
    if !vector_reserve(&pending, prior.splices.length)
        || !vector_reserve(&references, prior.splices.length + 1) { return false; }
    var target = bits(SyntaxOrigin*, compiler_world_component(world, destination, CompilerSyntaxOrigin));
    if target == null { return false; }
    references.data[0] = prior.expansion == null ? null : provenance_owner(prior.expansion);
    for(var i: usize = 0; i < prior.splices.length; i++) {
        var trace = prior.splices.data[i];
        pending.data[i] = trace;
        references.data[i + 1] = trace == null ? null : provenance_owner(trace);
    }
    if !entity_stage_references(stage, references.data, prior.splices.length + 1) { return false; }
    pending.length = prior.splices.length;
    target.template_start = prior.template_start;
    target.template_end = prior.template_end;
    target.generated = prior.generated;
    target.expansion = prior.expansion;
    copy(&target.splices, &pending, sizeof(vector(SyntaxExpansion*)));
    pending = default;
    return true;
}

export fn syntax_origin_mark(world: CompilerWorld*, trace: SyntaxExpansion*, node: Entity*, source: Entity*, generated: bool): bool {
    var missing = trace == null;
    if missing {
        return false;
    }
    var owner = provenance_owner(trace);
    if owner.store != world.store {
        return false;
    }
    var existing = syntax_origin_get(world, node);
    var splice = !generated;
    splice &&= existing != null;
    if splice {
        var ok = vector_push(&existing.splices, trace);
        if ok {
            syntax_trace_retain(trace);
        }
        return ok;
    }
    var span = bits(ParserMatchData*, compiler_world_get(world, source, CompilerParserMatch));
    missing = span == null;
    if missing {
        return false;
    }
    var origin = bits(SyntaxOrigin*, compiler_world_component(world, node, CompilerSyntaxOrigin));
    missing = origin == null;
    if missing {
        return false;
    }
    syntax_trace_retain(trace);
    syntax_trace_release(origin.expansion);
    origin.expansion = trace;
    origin.generated = generated;
    origin.template_start = span.start;
    origin.template_end = span.start + span.length;
    return true;
}

import tower;
import foundation_nodes;
import parser_nodes;
import parser_types;
import regex_lowering;
import syntax_lexer;
import syntax_nodes;
import syntax_types;
import syntax_validation;
import grammar_attributes;
import .library.vector;

// Interpret declaration parse trees on their existing shared entities.
// Temporary native registration supplies component kinds; all reading is Tower.
extern fn entity_component_add(node: void*, kind: void*): void*;

extern fn bytes_assign_text(value: vector(u8)*, source: u8*, length: usize): bool;

extern fn bytes_append(value: vector(u8)*, source: u8*, length: usize): bool;

struct SyntaxReader {
    source: SyntaxSource*;
    match_kind: void*;
    syntax_kind: void*;
    error: u8*;
    detail: u8*;
    detail_length: usize;
    suffix: u8*;
}

fn syntax_reader_fail(reader: SyntaxReader*, message: u8*): bool {
    if reader.error == null {
        reader.error = message;
    }
    return false;
}

fn syntax_reader_detail(reader: SyntaxReader*, message: u8*, detail: u8*, length: usize, suffix: u8*): bool {
    if reader.error == null {
        reader.detail = detail;
        reader.detail_length = length;
        reader.suffix = suffix;
    }
    return syntax_reader_fail(reader, message);
}

fn syntax_reader_ok(reader: SyntaxReader*, ok: bool): bool {
    if ok {
        return true;
    }
    return syntax_reader_fail(reader, "Unable to allocate grammar declaration");
}

fn syntax_text_length(text: u8*): usize {
    var length: usize = 0;
    loop {
        if text[length] == 0 {
            return length;
        }
        length++;
    }
}

fn syntax_reader_finish(reader: SyntaxReader*, error: vector(u8)*): bool {
    if reader.error == null {
        return true;
    }
    var ok = node_text_set(error, reader.error);
    ok &&= bytes_append(error, reader.detail, reader.detail_length);
    var suffix = reader.suffix != null;
    if suffix {
        if ok {
            var length = syntax_text_length(reader.suffix);
            ok = bytes_append(error, reader.suffix, length);
        }
    }
    if ok {
        ok = foundation_name_append(error, 0);
        if ok {
            error.length--;
        }
    }
    if !ok {
        vector_dispose(error);
    }
    return false;
}

fn syntax_reader_member(node: void*, name: u8*): void* {
    if node == null {
        return null;
    }
    var index = entity_member_index(node, name);
    return entity_child_at(node, index);
}

fn syntax_reader_required(reader: SyntaxReader*, node: void*, name: u8*): void* {
    var result = syntax_reader_member(node, name);
    if result == null {
        var length = syntax_text_length(name);
        syntax_reader_detail(reader, "Malformed bedrock tree: missing capture '", name, length, "'");
    }
    return result;
}

fn syntax_reader_span(reader: SyntaxReader*, node: void*): ParserMatchData* {
    var component = entity_component_get(node, reader.match_kind);
    var span = bits(ParserMatchData*, entity_component_data(component));
    if span == null {
        syntax_reader_fail(reader, "Malformed bedrock tree: missing source span");
        return null;
    }
    var outside = span.start > reader.source.text.length;
    if !outside {
        var remaining = reader.source.text.length -span.start;
        outside = span.length > remaining;
    }
    if outside {
        syntax_reader_fail(reader, "Malformed bedrock tree: source span outside source");
        return null;
    }
    return span;
}

fn syntax_reader_attach(reader: SyntaxReader*, node: void*, kind: u32): SyntaxNode* {
    var component = entity_component_get(node, reader.syntax_kind);
    var fresh = component == null;
    if fresh {
        component = entity_component_add(node, reader.syntax_kind);
    }
    var value = bits(SyntaxNode*, entity_component_data(component));
    var missing = value == null;
    if missing {
        syntax_reader_fail(reader, "Unable to allocate grammar declaration");
        return null;
    }
    if fresh {
        syntax_node_init(value);
    }
    value.kind = kind;
    var span = syntax_reader_span(reader, node);
    missing = span == null;
    if missing {
        return null;
    }
    value.start = span.start;
    value.end = span.start + span.length;
    syntax_node_source(value, reader.source);
    return value;
}

// The same decoder is used by semantic lookup and source formatting. Decode in
// the destination after the shared byte-buffer copy, including overlapping input.
export fn syntax_identifier_decode(text: u8*, length: usize, result: vector(u8)*): bool {
    if !bytes_assign_text(result, text, length) {
        return false;
    }
    result.length = syntax_identifier_decode_in_place(result.data, length);
    return true;
}

// Borrow a writable, NUL-terminated buffer so existing callers can reuse their
// own storage rather than allocating a second string solely to decode a name.
export fn syntax_identifier_decode_in_place(text: u8*, length: usize): usize {
    var quoted = length >= 2;
    quoted &&= text[0] == 96;
    var end = length -1;
    quoted &&= text[end] == 96;
    if !quoted {
        return length;
    }
    var read: usize = 1;
    var write: usize = 0;
    for(; read != end; write++) {
        var byte = text[read];
        read++;
        var escape = byte == 92;
        escape &&= read < end;
        if escape {
            byte = text[read];
            read++;
            var selected = byte == 110;
            if selected {
                byte = 10;
            } else {
                selected = byte == 114;
                if selected {
                    byte = 13;
                } else {
                    selected = byte == 116;
                    if selected {
                        byte = 9;
                    }
                }
            }
        }
        text[write] = byte;
    }
    text[write] = 0;
    return write;
}

fn syntax_reader_name(reader: SyntaxReader*, node: void*, result: vector(u8)*): bool {
    var span = syntax_reader_span(reader, node);
    if span == null {
        return false;
    }
    var text = reader.source.text.data + span.start;
    var ok = syntax_identifier_decode(text, span.length, result);
    return syntax_reader_ok(reader, ok);
}

// 0 valid, 1 empty, 2 unsupported. Preserve the existing literal category policy.
export fn syntax_literal_check(text: u8*, length: usize): u32 {
    if length == 0 {
        return 1;
    }
    var letters: bool = false;
    for(var index: usize = 0; index != length; index++) {
        var byte = text[index];
        var invalid = byte == 0;
        invalid ||= byte == 32;
        invalid ||= byte == 10;
        invalid ||= byte == 13;
        invalid ||= byte == 9;
        invalid ||= byte == 34;
        invalid ||= byte == 39;
        if invalid {
            return 2;
        }
        var alpha = lexicon_letter(byte);
        if !alpha {
            alpha = byte >= 48;
            alpha &&= byte <= 57;
        }
        if alpha {
            letters = true;
        }
    }
    if letters {
        if !lexicon_word(text, length) {
            return 2;
        }
    }
    var comment = length >= 2;
    if comment {
        comment = text[0] == 47;
        if comment {
            comment = text[1] == 47;
            comment ||= text[1] == 42;
        }
    }
    if comment {
        return 2;
    }
    return 0;
}

fn syntax_reader_literal(reader: SyntaxReader*, value: vector(u8)*): bool {
    var status = syntax_literal_check(value.data, value.length);
    if status == 1 {
        return syntax_reader_fail(reader, "Token literal is empty. Expected at least one character between the quotes.");
    }
    if status == 2 {
        return syntax_reader_detail(reader, "Unsupported token literal: ", value.data, value.length, "");
    }
    return true;
}

fn syntax_reader_quoted(reader: SyntaxReader*, node: void*, result: vector(u8)*): bool {
    var span = syntax_reader_span(reader, node);
    if span == null {
        return false;
    }
    var cursor = span.start;
    var end = reader.source.text.length;
    if cursor == end {
        return syntax_reader_fail(reader, "Unterminated quoted literal");
    }
    var quote = reader.source.text.data[cursor];
    cursor++;
    loop {
        var done = cursor == end;
        if done {
            return syntax_reader_fail(reader, "Unterminated quoted literal");
        }
        var byte = reader.source.text.data[cursor];
        cursor++;
        if byte == quote {
            return true;
        }
        var newline = byte == 10;
        newline ||= byte == 13;
        if newline {
            return syntax_reader_fail(reader, "Newline in quoted literal");
        }
        if byte == 92 {
            done = cursor == end;
            if done {
                return syntax_reader_fail(reader, "Unterminated quoted literal");
            }
            byte = reader.source.text.data[cursor];
            cursor++;
            var selected = byte == 110;
            if selected {
                byte = 10;
            } else {
                selected = byte == 114;
                if selected {
                    byte = 13;
                } else {
                    selected = byte == 116;
                    if selected {
                        byte = 9;
                    } else {
                        selected = byte == 92;
                        selected ||= byte == 39;
                        selected ||= byte == 34;
                        if !selected {
                            return syntax_reader_fail(reader, "Unsupported literal escape");
                        }
                    }
                }
            }
        }
        if !foundation_name_append(result, byte) {
            return syntax_reader_ok(reader, false);
        }
    }
}

fn syntax_reader_reverse(items: vector(void*)*): void {
    var left: usize = 0;
    var right = items.length;
    loop {
        if left >= right {
            return;
        }
        right--;
        var saved = items.data[left];
        items.data[left] = items.data[right];
        items.data[right] = saved;
        left++;
    }
}

fn syntax_reader_term(reader: SyntaxReader*, node: void*): bool {
    var term = syntax_reader_attach(reader, node, 5);
    var failed = term == null;
    if failed {
        return false;
    }
    var atom = syntax_reader_required(reader, node, "atom");
    var suffix = syntax_reader_required(reader, node, "suffix");
    failed = reader.error != null;
    if failed {
        return false;
    }
    var literal = syntax_reader_member(atom, "literal");
    var reference = syntax_reader_member(atom, "reference");
    var capture = syntax_reader_member(atom, "capture");
    var exclusions = syntax_reader_member(atom, "set");
    var present = exclusions != null;
    if present {
        term.terminal_set = true;
        loop {
            var done = exclusions == null;
            if done {
                break;
            }
            var count = entity_child_count(exclusions);
            done = count == 0;
            if done {
                break;
            }
            var item = syntax_reader_required(reader, exclusions, "literal");
            failed = item == null;
            if failed {
                return false;
            }
            var value = syntax_reader_attach(reader, item, 5);
            failed = value == null;
            if failed {
                return false;
            }
            value.literal = true;
            var ok = syntax_reader_quoted(reader, item, &value.text);
            ok &&= syntax_reader_literal(reader, &value.text);
            if ok {
                ok = vector_push(&term.items, item);
                ok = syntax_reader_ok(reader, ok);
            }
            if !ok {
                return false;
            }
            exclusions = syntax_reader_member(exclusions, "previous");
        }
        syntax_reader_reverse(&term.items);
    } else {
        present = literal != null;
        if present {
            term.literal = true;
            var ok = syntax_reader_quoted(reader, literal, &term.text);
            if !ok {
                return false;
            }
        } else {
            present = reference != null;
            if !present {
                reference = capture;
            }
            present = reference != null;
            if !present {
                return syntax_reader_fail(reader, "Malformed bedrock atom: expected literal, reference or capture");
            }
            var ok = syntax_reader_name(reader, reference, &term.text);
            present = capture != null;
            if present {
                ok &&= syntax_reader_name(reader, capture, &term.capture);
            }
            if !ok {
                return false;
            }
        }
    }
    var repetition = syntax_reader_span(reader, suffix);
    failed = repetition == null;
    if failed {
        return false;
    }
    if repetition.length != 0 {
        var text = reader.source.text.data + repetition.start;
        var valid = repetition.length == 1;
        if valid {
            valid = text[0] == 42;
            valid ||= text[0] == 43;
            valid ||= text[0] == 63;
        }
        if valid {
            term.repetition = text[0];
        } else {
            return syntax_reader_detail(reader, "Unknown grammar repetition: ", text, repetition.length, "");
        }
    }
    return true;
}

fn syntax_reader_sequence(reader: SyntaxReader*, node: void*): bool {
    var sequence = syntax_reader_attach(reader, node, 4);
    var failed = sequence == null;
    if failed {
        return false;
    }
    loop {
        var count = entity_child_count(node);
        if count == 0 {
            break;
        }
        var term = syntax_reader_required(reader, node, "term");
        var previous = syntax_reader_required(reader, node, "previous");
        failed = reader.error != null;
        if failed {
            return false;
        }
        var ok = syntax_reader_term(reader, term);
        if ok {
            ok = vector_push(&sequence.items, term);
            ok = syntax_reader_ok(reader, ok);
        }
        if !ok {
            return false;
        }
        node = previous;
    }
    syntax_reader_reverse(&sequence.items);
    return true;
}

fn syntax_reader_attribute_value(reader: SyntaxReader*, node: void*): bool {
    var source = syntax_reader_member(node, "name");
    var kind = SyntaxKind.AttributeName;
    if source == null { source = syntax_reader_member(node, "string"); kind = SyntaxKind.AttributeString; }
    if source == null { source = syntax_reader_member(node, "integer"); kind = SyntaxKind.AttributeInteger; }
    if source == null {
        source = node;
        loop {
            var span = syntax_reader_span(reader, source);
            if span == null { return false; }
            if grammar_attribute_equal(&span.label, "Identifier") { kind = SyntaxKind.AttributeName; break; }
            if grammar_attribute_equal(&span.label, "String") { kind = SyntaxKind.AttributeString; break; }
            if grammar_attribute_equal(&span.label, "Number") { kind = SyntaxKind.AttributeInteger; break; }
            if span.rule == AttributeTerminalRule && span.length != 0 {
                var first = reader.source.text.data[span.start];
                if first == AttributeSingleQuote || first == AttributeDoubleQuote { kind = SyntaxKind.AttributeString; }
                else {
                    if first >= AttributeDecimalZero && first <= AttributeDecimalNine { kind = SyntaxKind.AttributeInteger; }
                    else { kind = SyntaxKind.AttributeName; }
                }
                break;
            }
            if entity_child_count(source) != 1 {
                return syntax_reader_fail(reader, "Grammar attribute requires a name, string or integer argument");
            }
            source = entity_child_at(source, 0);
        }
    }
    var value = syntax_reader_attach(reader, node, convert(u32, kind));
    if value == null { return false; }
    if kind == SyntaxKind.AttributeString { return syntax_reader_quoted(reader, source, &value.text); }
    return syntax_reader_name(reader, source, &value.text);
}

fn syntax_reader_expression_attribute(reader: SyntaxReader*, expression: void*, value: SyntaxNode*): bool {
    var node = expression;
    loop {
        var span = syntax_reader_span(reader, node);
        if span == null { return false; }
        if grammar_attribute_equal(&span.label, "Identifier") { return syntax_reader_name(reader, node, &value.name); }
        if span.rule == AttributeTerminalRule { return syntax_reader_name(reader, node, &value.name); }
        if grammar_attribute_equal(&span.label, "CoreCall") { break; }
        if entity_child_count(node) != 1 { return syntax_reader_fail(reader, "Grammar attribute requires a name or named call"); }
        node = entity_child_at(node, 0);
    }
    if !syntax_reader_name(reader, syntax_reader_required(reader, node, "name"), &value.name) { return false; }
    var pending: vector(void*) = default;
    defer vector_dispose(&pending);
    var arguments = syntax_reader_member(node, "args");
    if arguments != null && !syntax_reader_ok(reader, vector_push(&pending, arguments)) { return false; }
    while pending.length != 0 {
        var argument = pending.data[--pending.length];
        var span = syntax_reader_span(reader, argument);
        if span == null { return false; }
        if grammar_attribute_equal(&span.label, "CoreCallArgument") {
            if !syntax_reader_attribute_value(reader, argument)
                || !syntax_reader_ok(reader, vector_push(&value.items, argument)) { return false; }
        } else {
            var count = entity_child_count(argument);
            while count != 0 {
                if !syntax_reader_ok(reader, vector_push(&pending, entity_child_at(argument, --count))) { return false; }
            }
        }
    }
    return true;
}

fn syntax_reader_attributes(reader: SyntaxReader*, node: void*, owner: SyntaxNode*): bool {
    var attributes = syntax_reader_member(node, "attributes");
    var list = syntax_reader_member(attributes, "list");
    if list != null { attributes = list; }
    while attributes != null {
        var attribute = syntax_reader_member(attributes, "attribute");
        if attribute == null { break; }
        var value = syntax_reader_attach(reader, attribute, convert(u32, SyntaxKind.Attribute));
        if value == null { return false; }
        var expression = syntax_reader_member(attribute, "value");
        if expression != null {
            if !syntax_reader_expression_attribute(reader, expression, value) { return false; }
        } else {
            if !syntax_reader_name(reader, syntax_reader_required(reader, attribute, "name"), &value.name) { return false; }
            var arguments = syntax_reader_member(attribute, "args");
            while arguments != null {
                var argument = syntax_reader_required(reader, arguments, "argument");
                if argument == null || !syntax_reader_attribute_value(reader, argument)
                    || !syntax_reader_ok(reader, vector_push(&value.items, argument)) { return false; }
                arguments = syntax_reader_member(arguments, "previous");
            }
            syntax_reader_reverse(&value.items);
        }
        if !syntax_reader_ok(reader, vector_push(&owner.attributes, attribute)) { return false; }
        attributes = syntax_reader_member(attributes, "previous");
    }
    syntax_reader_reverse(&owner.attributes);
    return true;
}

fn syntax_reader_attribute_node(reader: SyntaxReader*, entity: void*): SyntaxNode* {
    return bits(SyntaxNode*, entity_component_data(entity_component_get(entity, reader.syntax_kind)));
}

fn syntax_reader_attribute_precedence(reader: SyntaxReader*, attribute: SyntaxNode*, owner: SyntaxNode*): bool {
    if owner.kind != convert(u32, SyntaxKind.Rule) { return syntax_reader_fail(reader, "Precedence applies only to parse declarations"); }
    if owner.precedence != 0 { return syntax_reader_fail(reader, "Duplicate grammar precedence"); }
    if attribute.items.length != 2 { return syntax_reader_fail(reader, "precedence requires a positive integer and associativity"); }
    var number = syntax_reader_attribute_node(reader, attribute.items.data[0]);
    var direction = syntax_reader_attribute_node(reader, attribute.items.data[1]);
    if number.kind != convert(u32, SyntaxKind.AttributeInteger) { return syntax_reader_fail(reader, "Grammar precedence requires decimal digits"); }
    var maximum = ~convert(u32, 0);
    foreach(var digit in &number.text) {
        if digit < AttributeDecimalZero || convert(u32, digit - AttributeDecimalZero) >= AttributeDecimalBase {
            return syntax_reader_fail(reader, "Grammar precedence requires decimal digits");
        }
        var value = convert(u32, digit - AttributeDecimalZero);
        if owner.precedence > (maximum - value) / AttributeDecimalBase { return syntax_reader_fail(reader, "Grammar precedence exceeds u32"); }
        owner.precedence = owner.precedence * AttributeDecimalBase + value;
    }
    if owner.precedence == 0 { return syntax_reader_fail(reader, "Grammar precedence must be positive"); }
    owner.associativity = convert(u32, grammar_attribute_direction(&direction.text));
    if owner.associativity == convert(u32, GrammarAssociativity.None) { return syntax_reader_fail(reader, "Unknown grammar associativity"); }
    return true;
}

fn syntax_reader_apply_attributes(reader: SyntaxReader*, owner: SyntaxNode*, explicit_style: bool): bool {
    foreach(var entity in &owner.attributes) {
        var attribute = syntax_reader_attribute_node(reader, entity);
        var kind = grammar_attribute_kind(&attribute.name);
        if kind == GrammarAttributeKind.Unknown {
            return syntax_reader_detail(reader, "Unknown grammar attribute '", attribute.name.data, attribute.name.length, "'");
        }
        if kind == GrammarAttributeKind.Precedence {
            if !syntax_reader_attribute_precedence(reader, attribute, owner) { return false; }
            continue;
        }
        if owner.kind != convert(u32, SyntaxKind.Token) && owner.kind != convert(u32, SyntaxKind.Skip) {
            return syntax_reader_fail(reader, "Lexical attributes apply only to token and skip declarations");
        }
        if kind == GrammarAttributeKind.Contextual {
            if attribute.items.length != 0 { return syntax_reader_fail(reader, "contextual takes no arguments"); }
            if owner.contextual { return syntax_reader_fail(reader, "Duplicate contextual attribute"); }
            if owner.kind == convert(u32, SyntaxKind.Skip) { return syntax_reader_fail(reader, "Skip rules cannot be contextual"); }
            owner.contextual = true;
            continue;
        }
        if explicit_style { return syntax_reader_fail(reader, "Duplicate highlight style"); }
        explicit_style = true;
        var text = &attribute.name;
        if grammar_attribute_equal(text, "style") {
            if attribute.items.length != 1 { return syntax_reader_fail(reader, "style requires one name or string"); }
            var argument = syntax_reader_attribute_node(reader, attribute.items.data[0]);
            if argument.kind == convert(u32, SyntaxKind.AttributeInteger) { return syntax_reader_fail(reader, "style requires one name or string"); }
            text = &argument.text;
        } else { if attribute.items.length != 0 { return syntax_reader_fail(reader, "Highlight markers take no arguments"); } }
        if !syntax_reader_ok(reader, bytes_assign_text(&owner.style, text.data, text.length)) { return false; }
    }
    return true;
}

fn syntax_reader_rule(reader: SyntaxReader*, node: void*): bool {
    var name = syntax_reader_required(reader, node, "name");
    var assignment = syntax_reader_required(reader, node, "op");
    var alternatives = syntax_reader_required(reader, node, "alternatives");
    var replacement = syntax_reader_required(reader, node, "replacement");
    var failed = reader.error != null;
    if failed {
        return false;
    }
    var rule = syntax_reader_attach(reader, node, 1);
    failed = rule == null;
    if failed {
        return false;
    }
    var ok = syntax_reader_name(reader, name, &rule.name);
    if !ok {
        return false;
    }
    if rule.name.length == 0 {
        return syntax_reader_fail(reader, "Rule name cannot be empty");
    }
    var op = syntax_reader_span(reader, assignment);
    failed = op == null;
    if failed {
        return false;
    }
    var text = reader.source.text.data + op.start;
    var valid = op.length == 1;
    valid &&= text[0] == 61;
    if !valid {
        valid = op.length == 2;
        valid &&= text[0] == 124;
        valid &&= text[1] == 61;
        rule.append = valid;
    }
    if !valid {
        return syntax_reader_detail(reader, "Unknown grammar assignment: ", text, op.length, "");
    }
    var annotation = syntax_reader_member(node, "precedence");
    var level = syntax_reader_member(annotation, "level");
    if level != null {
        var span = syntax_reader_span(reader, level);
        if span == null {
            return false;
        }
        for(var cursor: usize = 0; cursor != span.length; cursor++) {
            var offset = span.start + cursor;
            var digit = convert(u32, reader.source.text.data[offset]);
            digit = digit - 48;
            if digit > 9 {
                return syntax_reader_fail(reader, "Grammar precedence requires decimal digits");
            }
            var overflow = rule.precedence > 429496729;
            if !overflow {
                if rule.precedence == 429496729 {
                    overflow = digit > 5;
                }
            }
            if overflow {
                return syntax_reader_fail(reader, "Grammar precedence exceeds u32");
            }
            rule.precedence = rule.precedence * 10;
            rule.precedence = rule.precedence + digit;
        }
        if rule.precedence == 0 {
            return syntax_reader_fail(reader, "Grammar precedence must be positive");
        }
        var direction = syntax_reader_member(annotation, "direction");
        span = syntax_reader_span(reader, direction);
        if span == null {
            return false;
        }
        var spelling = reader.source.text.data + span.start;
        if syntax_bytes_compare(spelling, span.length, "left", 4) == 0 {
            rule.associativity = 1;
        }
        if syntax_bytes_compare(spelling, span.length, "L>R", 3) == 0 {
            rule.associativity = 1;
        }
        if syntax_bytes_compare(spelling, span.length, "right", 5) == 0 {
            rule.associativity = 2;
        }
        if syntax_bytes_compare(spelling, span.length, "R<L", 3) == 0 {
            rule.associativity = 2;
        }
        if syntax_bytes_compare(spelling, span.length, "nonassoc", 8) == 0 {
            rule.associativity = 3;
        }
        if rule.associativity == 0 {
            return syntax_reader_fail(reader, "Unknown grammar associativity");
        }
    }
    if !syntax_reader_attributes(reader, node, rule) || !syntax_reader_apply_attributes(reader, rule, false) { return false; }
    loop {
        if alternatives == null {
            break;
        }
        var sequence = syntax_reader_required(reader, alternatives, "sequence");
        failed = sequence == null;
        if failed {
            return false;
        }
        ok = syntax_reader_sequence(reader, sequence);
        if ok {
            var component = entity_component_get(sequence, reader.syntax_kind);
            var data = bits(SyntaxNode*, entity_component_data(component));
            data.precedence = rule.precedence;
            data.associativity = rule.associativity;
        }
        if ok {
            ok = vector_push(&rule.items, sequence);
            ok = syntax_reader_ok(reader, ok);
        }
        if !ok {
            return false;
        }
        alternatives = syntax_reader_member(alternatives, "previous");
    }
    syntax_reader_reverse(&rule.items);
    var body = syntax_reader_member(replacement, "body");
    if body != null {
        var span = syntax_reader_span(reader, body);
        failed = span == null;
        if failed {
            return false;
        }
        if span.length < 2 {
            return syntax_reader_fail(reader, "Replacement body must contain opening and closing delimiters");
        }
        var value = syntax_reader_attach(reader, body, 6);
        failed = value == null;
        if failed {
            return false;
        }
        value.start = span.start + 1;
        var length = span.length -2;
        value.end = value.start + length;
        text = reader.source.text.data + value.start;
        ok = bytes_assign_text(&value.text, text, length);
        if !ok {
            return syntax_reader_ok(reader, false);
        }
        syntax_node_replacement(rule, body);
        foreach(var & item in &rule.items) {
            var component = entity_component_get(*item, reader.syntax_kind);
            var alternative = bits(SyntaxNode*, entity_component_data(component));
            syntax_node_replacement(alternative, body);
        }
    }
    return true;
}

export fn syntax_read_rule(node: void*, source: SyntaxSource*, match_kind: void*, syntax_kind: void*, error: vector(u8)*): bool {
    var reader: SyntaxReader = { source: source, match_kind: match_kind, syntax_kind: syntax_kind, ..default };
    syntax_reader_rule(&reader, node);
    return syntax_reader_finish(&reader, error);
}

fn syntax_reader_token(reader: SyntaxReader*, node: void*, skipped: bool): bool {
    var name = syntax_reader_required(reader, node, "name");
    var pattern = syntax_reader_required(reader, node, "pattern");
    var style = syntax_reader_required(reader, node, "style");
    var failed = reader.error != null;
    if failed {
        return false;
    }
    var kind: u32 = 2;
    if skipped {
        kind = 3;
    }
    var value = syntax_reader_attach(reader, node, kind);
    failed = value == null;
    if failed {
        return false;
    }
    var ok = syntax_reader_name(reader, name, &value.name);
    if !ok {
        return false;
    }
    if value.name.length == 0 {
        return syntax_reader_fail(reader, "Token name cannot be empty");
    }
    var label = syntax_reader_member(style, "kind");
    var present = label != null;
    if present {
        ok = syntax_reader_name(reader, label, &value.style);
    } else {
        if !skipped {
            ok = node_text_set(&value.style, "identifier");
            ok = syntax_reader_ok(reader, ok);
        }
    }
    if !ok {
        return false;
    }
    var span = syntax_reader_span(reader, pattern);
    failed = span == null;
    if failed {
        return false;
    }
    if span.length < 2 {
        return syntax_reader_fail(reader, "Token pattern must contain opening and closing delimiters");
    }
    var start = span.start + 1;
    var length = span.length -2;
    var text = reader.source.text.data + start;
    ok = bytes_assign_text(&value.text, text, length);
    if !ok {
        return syntax_reader_ok(reader, false);
    }
    var mode = syntax_reader_member(node, "mode");
    present = mode != null;
    if present {
        span = syntax_reader_span(reader, mode);
        failed = span == null;
        if failed {
            return false;
        }
        value.contextual = span.length != 0;
    }
    if skipped {
        if value.contextual {
            return syntax_reader_fail(reader, "Skip rules cannot be contextual");
        }
    }
    return syntax_reader_attributes(reader, node, value) && syntax_reader_apply_attributes(reader, value, label != null);
}

export fn syntax_read_token(node: void*, source: SyntaxSource*, match_kind: void*, syntax_kind: void*, skipped: bool, error: vector(u8)*): bool {
    var reader: SyntaxReader = { source: source, match_kind: match_kind, syntax_kind: syntax_kind, ..default };
    syntax_reader_token(&reader, node, skipped);
    return syntax_reader_finish(&reader, error);
}

import tower;
import frontend_revision_types;
import lr_tree;
import parser_nodes;
import regex_lowering;
import syntax_emission;
import syntax_expansion_types;
import syntax_nodes;
import syntax_replacement_types;
import syntax_reader;
import syntax_revision;
import syntax_types;
import syntax_validation;
import .library.vector;

struct SyntaxReplacementOwner {
    host: void*;
    emission: SyntaxEmission*;
    kind: void*;
    current: SyntaxReplacement;
    sequence: void*;
    selected: void*;
    category: vector(u8);
    uses: vector(usize);
    entries: vector(SyntaxReplacement);
    productions: vector(usize);
    captures: vector(SyntaxExpansionCapture);
    rules: vector(SyntaxExpansionRule);
    index: vector(SyntaxExpansionRule*);
    input: SyntaxExpansionInput;
    diagnostic: vector(u8);
    failed: bool;
    frozen: bool;
}

fn replacement_release(node: void*): void {
    if node is not null {
        entity_release(node);
    }
}

fn replacement_dispose(value: SyntaxReplacement*): void {
    replacement_release(value.tree);
    foreach(var & capture in &value.captures) {
        replacement_release(capture.source);
        vector_dispose(&capture.name);
    }
    vector_dispose(&value.captures);
    vector_dispose(&value.rule);
    vector_dispose(&value.category);
    *value = default;
}

export fn syntax_replacement_owner_create(host: void*, emission: SyntaxEmission*, kind: void*, match_kind: void*): SyntaxReplacementOwner* {
    var value = alloc(SyntaxReplacementOwner, 1);
    if value is null {
        return null;
    }
    *value = default;
    value.host = host;
    value.emission = emission;
    value.kind = kind;
    value.input.match_kind = match_kind;
    return value;
}

export fn syntax_replacement_owner_destroy(value: SyntaxReplacementOwner*): void {
    if value is null {
        return;
    }
    replacement_dispose(&value.current);
    replacement_release(value.sequence);
    replacement_release(value.selected);
    foreach(var & entry in &value.entries) {
        replacement_dispose(entry);
    }
    vector_dispose(&value.entries);
    vector_dispose(&value.productions);
    vector_dispose(&value.captures);
    vector_dispose(&value.rules);
    vector_dispose(&value.index);
    vector_dispose(&value.category);
    vector_dispose(&value.uses);
    vector_dispose(&value.diagnostic);
    free(value);
}

export fn syntax_replacement_begin(context: void*, name: u8*, sequence: void*, start: usize, end: usize): void {
    var value = bits(SyntaxReplacementOwner*, context);
    if value.frozen {
        return;
    }
    replacement_dispose(&value.current);
    replacement_release(value.sequence);
    replacement_release(value.selected);
    value.selected = null;
    value.sequence = sequence;
    if sequence is not null {
        entity_retain(sequence);
    }
    value.current.start = start;
    value.current.end = end;
    value.current.error_offset = start;
    value.failed ||= !node_text_set(&value.current.rule, name);
    value.uses.length = 0;
    value.category.length = 0;
}

export fn syntax_replacement_capture(context: void*, name: u8*, source: void*): void {
    var value = bits(SyntaxReplacementOwner*, context);
    if value.failed || value.frozen {
        return;
    }
    var captures = &value.current.captures;
    var length = syntax_text_length(name);
    var index: usize = 0;
    for(; index < captures.length; ++index) {
        var previous = &captures.data[index];
        var order = syntax_bytes_compare(previous.name.data, previous.name.length, name, length);
        if order == 0 {
            entity_retain(source);
            replacement_release(previous.source);
            previous.source = source;
            return;
        }
        if order > 0 {
            break;
        }
    }
    var capture: SyntaxReplacementCapture = default;
    if !node_text_set(&capture.name, name) || !vector_reserve(captures, captures.length + 1) {
        vector_dispose(&capture.name);
        value.failed = true;
        return;
    }
    capture.source = source;
    entity_retain(source);
    for(var i = captures.length; i > index; --i) {
        copy(&captures.data[i], &captures.data[i -1], sizeof(SyntaxReplacementCapture));
    }
    copy(&captures.data[index], &capture, sizeof(SyntaxReplacementCapture));
    captures.length++;
}

// The temporary parser borrows this mutable candidate only during preparation.
export fn syntax_replacement_candidate(value: SyntaxReplacementOwner*, category: u8*): SyntaxReplacement* {
    if value.failed || value.frozen {
        return null;
    }
    value.failed = !node_text_set(&value.current.category, category);
    if value.failed {
        return null;
    }
    value.diagnostic.length = 0;
    if value.diagnostic.data is not null {
        value.diagnostic.data[0] = 0;
    }
    value.current.error_offset = value.current.start;
    foreach(var & capture in &value.current.captures) {
        (*capture).uses = 0;
    }
    return &value.current;
}

export fn syntax_replacement_host(value: SyntaxReplacementOwner*): void* {
    return value.host;
}

export fn syntax_replacement_sequence(value: SyntaxReplacementOwner*): void* {
    return value.sequence;
}

// Adopt the parser's one owned tree reference, replacing any previous attempt.
export fn syntax_replacement_tree(value: SyntaxReplacementOwner*, tree: void*): void {
    replacement_release(value.current.tree);
    value.current.tree = tree;
}

export fn syntax_replacement_error(value: SyntaxReplacementOwner*, text: u8*): void {
    value.failed ||= !node_text_set(&value.diagnostic, text);
}

export fn syntax_replacement_diagnostic(context: void*): u8* {
    var value = bits(SyntaxReplacementOwner*, context);
    return value.failed ? "Unable to allocate replacement preparation storage": node_text_get(&value.diagnostic);
}

export fn syntax_replacement_offset(context: void*): usize {
    var value = bits(SyntaxReplacementOwner*, context);
    return value.current.error_offset;
}

export fn syntax_replacement_select(context: void*): void {
    var value = bits(SyntaxReplacementOwner*, context);
    if value.failed || value.frozen {
        return;
    }
    var captures = &value.current.captures;
    value.failed = !node_text_set(&value.category, node_text_get(&value.current.category)) || !vector_reserve(&value.uses, captures.length);
    if value.failed {
        return;
    }
    value.uses.length = captures.length;
    for(var i: usize = 0; i < captures.length; ++i) {
        value.uses.data[i] = captures.data[i].uses;
    }
    replacement_release(value.selected);
    value.selected = value.current.tree;
    value.current.tree = null;
}

// Production order, like capture-name order, is derived and deterministic.
export fn syntax_replacement_commit(context: void*, alternative: usize): void {
    var value = bits(SyntaxReplacementOwner*, context);
    if value.failed || value.frozen {
        return;
    }
    var current = &value.current;
    var production = syntax_emission_find_name(value.emission, node_text_get(&current.rule), alternative);
    var index: usize = 0;
    for(; index < value.productions.length; ++index) {
        if value.productions.data[index] >= production {
            break;
        }
    }
    if index < value.productions.length && value.productions.data[index] == production {
        return;
    }
    value.failed = !vector_reserve(&value.entries, value.entries.length + 1) || !vector_reserve(&value.productions, value.productions.length + 1);
    if value.failed {
        return;
    }
    replacement_release(current.tree);
    current.tree = value.selected;
    value.selected = null;
    vector_move(&current.category, &value.category);
    for(var i: usize = 0; i < current.captures.length; ++i) {
        current.captures.data[i].uses = value.uses.data[i];
    }
    for(var i = value.entries.length; i > index; --i) {
        copy(&value.entries.data[i], &value.entries.data[i -1], sizeof(SyntaxReplacement));
        value.productions.data[i] = value.productions.data[i -1];
    }
    copy(&value.entries.data[index], current, sizeof(SyntaxReplacement));
    fill(current, 0, sizeof(SyntaxReplacement));
    value.productions.data[index] = production;
    value.entries.length++;
    value.productions.length++;
}

export fn syntax_replacement_freeze(value: SyntaxReplacementOwner*): bool {
    if value.failed {
        return false;
    }
    if value.frozen {
        return true;
    }
    var total: usize = 0;
    foreach(var & entry in &value.entries) {
        var count =(*entry).captures.length;
        if count > ~convert(usize, 0) -total {
            return false;
        }
        total += count;
    }
    var count = value.entries.length;
    var slots = count == 0 ? 0: value.productions.data[count -1] + 1;
    if count != 0 && slots == 0 {
        return false;
    }
    if !vector_reserve(&value.captures, total) ||
    !vector_reserve(&value.rules, count) ||
    !vector_reserve(&value.index, slots) {
        return false;
    }
    fill(value.index.data, 0, slots *sizeof(SyntaxExpansionRule*));
    var offset: usize = 0;
    for(var i: usize = 0; i < count; ++i) {
        var entry = &value.entries.data[i];
        var rule = &value.rules.data[i];
        rule.tree = entry.tree;
        rule.rule = node_text_get(&entry.rule);
        rule.category = node_text_get(&entry.category);
        rule.start = entry.start;
        rule.end = entry.end;
        rule.count = entry.captures.length;
        rule.captures = rule.count == 0 ? null: &value.captures.data[offset];
        for(var j: usize = 0; j < rule.count; ++j) {
            var capture = &entry.captures.data[j];
            var view = &value.captures.data[offset++];
            view.name = node_text_get(&capture.name);
            view.uses = capture.uses;
            var node = bits(SyntaxNode*, entity_component_data(entity_component_get(capture.source, value.kind)));
            view.repeated = node.repetition != 0;
        }
        value.index.data[value.productions.data[i]] = rule;
    }
    value.captures.length = total;
    value.rules.length = count;
    value.index.length = slots;
    value.input.rules = value.index.data;
    value.input.count = slots;
    value.host = null;
    value.frozen = true;
    return true;
}

export fn syntax_replacement_input(value: SyntaxReplacementOwner*): SyntaxExpansionInput* {
    return &value.input;
}

export fn syntax_replacement_count(value: SyntaxReplacementOwner*): usize {
    return value.entries.length;
}

export fn syntax_replacement_inspect(value: SyntaxReplacementOwner*, grammar: FrontendRevision*, body: void*): SyntaxReplacement* {
    if value is null {
        return null;
    }
    for(var i: usize = 0; i < value.entries.length; ++i) {
        var production = syntax_emission_find_index(value.emission, value.productions.data[i]);
        if production is null {
            continue;
        }
        var rule = syntax_revision_rule(grammar, production.name, syntax_text_length(production.name));
        if rule is null || production.alternative >= rule.count {
            continue;
        }
        var node = bits(SyntaxNode*, entity_component_data(entity_component_get(rule.alternatives[production.alternative], value.kind)));
        if node.replacement == body {
            return &value.entries.data[i];
        }
    }
    return null;
}

import tower;
import .library.vector;

// Owned leases on shared source/template entities, not a second syntax graph.
struct SyntaxReplacementCapture {
    name: vector(u8);
    source: void*;
    uses: usize;
}

struct SyntaxReplacement {
    rule: vector(u8);
    category: vector(u8);
    start: usize;
    end: usize;
    error_offset: usize;
    tree: void*;
    captures: vector(SyntaxReplacementCapture);
}

import syntax_view;
import tower;
import lr_analysis;
import parser_nodes;
import regex_lowering;
import syntax_reader;
import syntax_types;
import syntax_validation;
import .library.vector;

// Validate replacements when their rules become reachable from Statement.
// Nearest unit-rule ancestors provide inferred destinations; ordinary parsing
// never searches or backtracks through these candidate destinations.
struct SyntaxReplacementPlan {
    rules: SyntaxRuleView*;
    count: usize;
    kind: void*;
    host: void*;
    error: vector(u8);
    offset: usize;
}

extern fn syntax_replacement_begin(host: void*, name: u8*, sequence: void*, start: usize, end: usize): void;

extern fn syntax_replacement_capture(host: void*, name: u8*, source: void*): void;

// 1 success, 2 parser-table conflict, 0 other failure. The candidate owns its
// tree; selecting/committing transfers it within the revision storage facade.
extern fn syntax_replacement_attempt(host: void*, category: u8*): u32;

extern fn syntax_replacement_diagnostic(host: void*): u8*;

extern fn syntax_replacement_offset(host: void*): usize;

extern fn syntax_replacement_select(host: void*): void;

extern fn syntax_replacement_commit(host: void*, alternative: usize): void;

struct ReplacementRuleState {
    parents: vector(usize);
    reachable: bool;
    visited: usize;
}

struct ReplacementPlanState {
    plan: SyntaxReplacementPlan*;
    rules: vector(ReplacementRuleState);
    pending: vector(usize);
    tried: vector(usize);
    original: vector(u8);
    epoch: usize;
    allocated: bool;
}

fn replacement_node(state: ReplacementPlanState*, node: void*): SyntaxNode* {
    var component = entity_component_get(node, state.plan.kind);
    return bits(SyntaxNode*, entity_component_data(component));
}

fn replacement_find(state: ReplacementPlanState*, name: u8*, length: usize): usize {
    return syntax_rule_find(state.plan.rules, state.plan.count, name, length);
}

fn replacement_append(state: ReplacementPlanState*, source: u8*, length: usize): void {
    state.allocated &&= bytes_append(&state.plan.error, source, length);
}

fn replacement_text(state: ReplacementPlanState*, text: u8*): void {
    replacement_append(state, text, syntax_text_length(text));
}

fn replacement_queue(state: ReplacementPlanState*, index: usize): bool {
    state.allocated = vector_push(&state.pending, index);
    return state.allocated;
}

fn replacement_reachable(state: ReplacementPlanState*): bool {
    var first = replacement_find(state, "Statement", 9);
    var present = first != lr_none();
    if present {
        replacement_queue(state, first);
    }
    loop {
        if !state.allocated {
            return false;
        }
        if state.pending.length == 0 {
            return true;
        }
        state.pending.length--;
        var index = state.pending.data[state.pending.length];
        if state.rules.data[index].reachable {
            continue;
        }
        state.rules.data[index].reachable = true;
        var rule = &state.plan.rules[index];
        var alternative: usize = 0;
        loop {
            var done = alternative == rule.count;
            if done {
                break;
            }
            var sequence = replacement_node(state, rule.alternatives[alternative]);
            var item: usize = 0;
            loop {
                done = item == sequence.items.length;
                if done {
                    break;
                }
                var term = replacement_node(state, sequence.items.data[item]);
                if !term.literal {
                    var target = replacement_find(state, term.text.data, term.text.length);
                    present = target != lr_none();
                    if present {
                        if !replacement_queue(state, target) {
                            return false;
                        }
                    }
                }
                item++;
            }
            alternative++;
        }
    }
}

fn replacement_parents(state: ReplacementPlanState*): bool {
    var index: usize = 0;
    loop {
        var done = index == state.plan.count;
        if done {
            return true;
        }
        if state.rules.data[index].reachable {
            var rule = &state.plan.rules[index];
            var alternative: usize = 0;
            loop {
                done = alternative == rule.count;
                if done {
                    break;
                }
                var sequence = replacement_node(state, rule.alternatives[alternative]);
                var eligible = sequence.items.length == 1;
                if eligible {
                    var term = replacement_node(state, sequence.items.data[0]);
                    eligible = !term.literal;
                    eligible &&= term.repetition == 0;
                    if eligible {
                        var target = replacement_find(state, term.text.data, term.text.length);
                        if target != lr_none() {
                            var parents = &state.rules.data[target].parents;
                            var count = parents.length;
                            var duplicate = count != 0;
                            if duplicate {
                                var last = count -1;
                                duplicate = parents.data[last] == index;
                            }
                            if !duplicate {
                                state.allocated = vector_push(parents, index);
                                if !state.allocated {
                                    return false;
                                }
                            }
                        }
                    }
                }
                alternative++;
            }
        }
        index++;
    }
}

fn replacement_space(value: u8): bool {
    var blank = value == 32;
    if blank {
        return true;
    }
    blank = value == 10;
    if blank {
        return true;
    }
    blank = value == 13;
    if blank {
        return true;
    }
    blank = value == 9;
    return blank;
}

fn replacement_excerpt(state: ReplacementPlanState*, source: vector(u8)*): void {
    var first: usize = 0;
    var last = source.length;
    for(; first != last; first++) {
        var blank = replacement_space(source.data[first]);
        if !blank {
            break;
        }
    }
    loop {
        if first == last {
            break;
        }
        var index = last -1;
        var blank = replacement_space(source.data[index]);
        if !blank {
            break;
        }
        last = index;
    }
    if first == last {
        replacement_text(state, "<empty>");
        return;
    }
    var end = first + 160;
    if end > last {
        end = last;
    }
    for(; end != last; end--) {
        var byte = source.data[end] &192;
        if !(byte == 128) {
            break;
        }
    }
    replacement_text(state, "\"");
    var index = first;
    for(; index != end; index++) {
        var character = source.data[index];
        var selected = character == 10;
        if selected {
            replacement_text(state, "\\n");
        } else {
            selected = character == 13;
            if selected {
                replacement_text(state, "\\r");
            } else {
                selected = character == 9;
                if selected {
                    replacement_text(state, "\\t");
                } else {
                    selected = character == 92;
                    if selected {
                        replacement_text(state, "\\\\");
                    } else {
                        selected = character == 34;
                        if selected {
                            replacement_text(state, "\\\"");
                        } else {
                            replacement_append(state, &character, 1);
                        }
                    }
                }
            }
        }
    }
    if end < last {
        replacement_text(state, "...");
    }
    replacement_text(state, "\"");
}

fn replacement_invalid(state: ReplacementPlanState*, name: u8*, body: SyntaxNode*, grammar_failed: bool): void {
    replacement_text(state, "Replacement for ");
    replacement_text(state, name);
    replacement_text(state, " must produce ");
    var single = state.tried.length == 1;
    if single {
        replacement_text(state, "a valid ");
        var first = state.tried.data[0];
        replacement_text(state, state.plan.rules[first].name);
    } else {
        replacement_text(state, "one of these syntax categories: ");
        for(var index: usize = 0; index != state.tried.length; index++) {
            if index != 0 {
                replacement_text(state, ", ");
            }
            var target = state.tried.data[index];
            replacement_text(state, state.plan.rules[target].name);
        }
    }
    replacement_text(state, ". ");
    if grammar_failed {
        replacement_text(state, "Could not validate ");
    }
    replacement_excerpt(state, &body.text);
    if grammar_failed {
        replacement_text(state, ".");
    } else {
        if single {
            replacement_text(state, " is not a valid ");
            var first = state.tried.data[0];
            replacement_text(state, state.plan.rules[first].name);
            replacement_text(state, ".");
        } else {
            replacement_text(state, " is not valid in any of these categories.");
        }
    }
    replacement_text(state, "\n");
    replacement_append(state, state.original.data, state.original.length);
}

fn replacement_prepare_one(state: ReplacementPlanState*, index: usize, alternative: usize): bool {
    var rule = &state.plan.rules[index];
    var source = rule.alternatives[alternative];
    var sequence = replacement_node(state, source);
    var body = replacement_node(state, sequence.replacement);
    syntax_replacement_begin(state.plan.host, rule.name, source, body.start, body.end);
    foreach(var entity in &sequence.items) {
        var term = replacement_node(state, entity);
        if term.capture.length != 0 {
            syntax_replacement_capture(state.plan.host, node_text_get(&term.capture), entity);
        }
    }
    state.pending.length = 0;
    state.tried.length = 0;
    state.original.length = 0;
    state.plan.offset = body.start;
    state.epoch++;
    var grammar_failed = false;
    var ok = replacement_queue(state, index);
    var cursor: usize = 0;
    loop {
        if !ok {
            return false;
        }
        var done = cursor == state.pending.length;
        if done {
            replacement_invalid(state, rule.name, body, grammar_failed);
            return false;
        }
        var end = state.pending.length;
        var selected = false;
        loop {
            done = cursor == end;
            if done {
                break;
            }
            var category = state.pending.data[cursor];
            cursor++;
            var visited = state.rules.data[category].visited == state.epoch;
            if visited {
                continue;
            }
            state.rules.data[category].visited = state.epoch;
            state.allocated = vector_push(&state.tried, category);
            if !state.allocated {
                return false;
            }
            var status = syntax_replacement_attempt(state.plan.host, state.plan.rules[category].name);
            if status == 1 {
                if selected {
                    replacement_text(state, "Ambiguous replacement destination for ");
                    replacement_text(state, rule.name);
                    replacement_text(state, "; attach the handler to its destination rule");
                    state.plan.offset = body.start;
                    return false;
                }
                syntax_replacement_select(state.plan.host);
                selected = true;
            } else {
                if state.original.length == 0 {
                    state.allocated = node_text_set(&state.original, syntax_replacement_diagnostic(state.plan.host));
                    if !state.allocated {
                        return false;
                    }
                    state.plan.offset = syntax_replacement_offset(state.plan.host);
                }
            }
            if status == 2 {
                grammar_failed = true;
            }
            var parents = &state.rules.data[category].parents;
            var parent: usize = 0;
            loop {
                done = parent == parents.length;
                if done {
                    break;
                }
                ok = replacement_queue(state, parents.data[parent]);
                if !ok {
                    return false;
                }
                parent++;
            }
        }
        if selected {
            syntax_replacement_commit(state.plan.host, alternative);
            return true;
        }
    }
}

fn replacement_prepare_all(state: ReplacementPlanState*): bool {
    var any = false;
    var scan: usize = 0;
    loop {
        var done = scan == state.plan.count;
        if done {
            break;
        }
        var rule = &state.plan.rules[scan];
        var alternative: usize = 0;
        loop {
            done = alternative == rule.count;
            if done {
                break;
            }
            var sequence = replacement_node(state, rule.alternatives[alternative]);
            any = sequence.replacement != null;
            if any {
                break;
            }
            alternative++;
        }
        if any {
            break;
        }
        scan++;
    }
    if !any {
        return true;
    }
    state.allocated = vector_reserve(&state.rules, state.plan.count);
    if !state.allocated {
        return false;
    }
    var bytes = state.plan.count *sizeof(ReplacementRuleState);
    fill(state.rules.data, 0, bytes);
    state.rules.length = state.plan.count;
    var ok = replacement_reachable(state);
    ok &&= replacement_parents(state);
    if !ok {
        return false;
    }
    var index: usize = 0;
    loop {
        var done = index == state.plan.count;
        if done {
            return true;
        }
        if state.rules.data[index].reachable {
            var rule = &state.plan.rules[index];
            var alternative: usize = 0;
            loop {
                done = alternative == rule.count;
                if done {
                    break;
                }
                var sequence = replacement_node(state, rule.alternatives[alternative]);
                var replacement = sequence.replacement != null;
                if replacement {
                    ok = replacement_prepare_one(state, index, alternative);
                    if !ok {
                        return false;
                    }
                }
                alternative++;
            }
        }
        index++;
    }
}

export fn syntax_replacements_prepare(plan: SyntaxReplacementPlan*): bool {
    var state: ReplacementPlanState = default;
    state.plan = plan;
    state.allocated = true;
    var ok = replacement_prepare_all(&state);
    foreach(var & rule in &state.rules) {
        vector_dispose(&(*rule).parents);
    }
    vector_dispose(&state.rules);
    vector_dispose(&state.pending);
    vector_dispose(&state.tried);
    vector_dispose(&state.original);
    if !state.allocated {
        vector_dispose(&plan.error);
    }
    return ok;
}

export fn syntax_replacements_dispose(plan: SyntaxReplacementPlan*): void {
    vector_dispose(&plan.error);
}

import tower;
import frontend_cache;
import frontend_revision_types;
import lr_analysis;
import lr_tree;
import regex_lowering;
import syntax_nodes;
import syntax_reader;
import syntax_tags;
import syntax_types;
import syntax_validation;
import syntax_view;
import .library.vector;

// Retained, immutable indexes over shared declaration entities. Construction and
// publication belong to the session coordinator. Readers borrow views only while
// their owner is pinned; neither lookup nor filtering mutates an existing owner.
var SyntaxRevisionTokenLimit: usize = 64;

fn syntax_revision_node(entity: void*, kind: void*): SyntaxNode* {
    return bits(SyntaxNode*, entity_component_data(entity_component_get(entity, kind)));
}

export fn syntax_revision_create(rules: SyntaxRuleView*, count: usize, tokens: void**, token_count: usize): FrontendRevision* {
    var revision = frontend_revision_create(rules, count, tokens, token_count);
    if revision is null {
        return null;
    }
    // Module traversal supplies declaration order; consumers require name order.
    // Move only views: their names/alternatives already have stable allocations.
    for(var i: usize = 1; i < count; ++i) {
        var item: SyntaxRuleView;
        copy(&item, &revision.rules.data[i], sizeof(SyntaxRuleView));
        var at = i;
        while at != 0 {
            var previous = &revision.rules.data[at -1];
            if syntax_bytes_compare(previous.name, previous.name_length, item.name, item.name_length) <= 0 {
                break;
            }
            copy(&revision.rules.data[at], previous, sizeof(SyntaxRuleView));
            --at;
        }
        copy(&revision.rules.data[at], &item, sizeof(SyntaxRuleView));
    }
    return revision;
}

export fn syntax_revision_rule(revision: FrontendRevision*, name: u8*, length: usize): SyntaxRuleView* {
    if revision is null {
        return null;
    }
    var index = syntax_rule_find(revision.rules.data, revision.rules.length, name, length);
    return index == lr_none() ? null: &revision.rules.data[index];
}

fn syntax_revision_token(tokens: void**, count: usize, name: u8*, length: usize, kind: void*): usize {
    for(var i: usize = 0; i < count; ++i) {
        var node = syntax_revision_node(tokens[i], kind);
        if syntax_bytes_compare(node.name.data, node.name.length, name, length) == 0 {
            return i;
        }
    }
    return count;
}

// Overlay replaces complete rule bindings. Token overrides retain their old
// lexical priority; new tokens append in input order. Inputs remain untouched
// even if allocation fails at any point. No temporary vector owns entities.
export fn syntax_revision_overlay(base: FrontendRevision*, rules: SyntaxRuleView*, count: usize,
tokens: void**, token_count: usize, kind: void*): FrontendRevision* {
    if count == 0 && token_count == 0 && base is not null {
        return frontend_revision_retain(base);
    }
    var selected: vector(SyntaxRuleView);
    var lexical: vector(void*);
    vector_init(&selected);
    vector_init(&lexical);
    var before = base ?. rules.length ?? 0;
    var before_tokens = base ?. tokens.length ?? 0;
    var total = before + count;
    var total_tokens = before_tokens + token_count;
    var ok = total >= before && total_tokens >= before_tokens;
    ok &&= vector_reserve(&selected, total);
    ok &&= vector_reserve(&lexical, total_tokens);
    if ok {
        for(var i: usize = 0; i < before; ++i) {
            copy(&selected.data[i], &base.rules.data[i], sizeof(SyntaxRuleView));
        }
        selected.length = before;
        for(var i: usize = 0; i < count; ++i) {
            var at: usize = 0;
            while at < selected.length {
                var old = &selected.data[at];
                if syntax_bytes_compare(old.name, old.name_length, rules[i].name, rules[i].name_length) == 0 {
                    break;
                }
                ++at;
            }
            if at == selected.length {
                ++selected.length;
            }
            copy(&selected.data[at], &rules[i], sizeof(SyntaxRuleView));
        }
        for(var i: usize = 0; i < before_tokens; ++i) {
            lexical.data[i] = base.tokens.data[i];
        }
        lexical.length = before_tokens;
        for(var i: usize = 0; i < token_count; ++i) {
            var node = syntax_revision_node(tokens[i], kind);
            var at = syntax_revision_token(lexical.data, lexical.length, node.name.data, node.name.length, kind);
            if at == lexical.length {
                ++lexical.length;
            }
            lexical.data[at] = tokens[i];
        }
    }
    var revision: FrontendRevision* = null;
    if ok {
        revision = syntax_revision_create(selected.data, selected.length, lexical.data, lexical.length);
    }
    vector_dispose(&selected);
    vector_dispose(&lexical);
    return revision;
}

fn syntax_revision_error(error: vector(u8)*, message: u8*, name: u8*, length: usize): void {
    error.length = 0;
    if !bytes_append(error, message, syntax_text_length(message)) || !bytes_append(error, name, length) {
        error.length = 0;
    }
}

// A caller publishes the candidate only after validation/table construction.
// Undefined |= and lexical collisions are checked against the local revision,
// before adding the inherited Bedrock view, as at the original boundary.
export fn syntax_revision_declare(base: FrontendRevision*, entity: void*, kind: void*, error: vector(u8)*): FrontendRevision* {
    var node = syntax_revision_node(entity, kind);
    var previous = syntax_revision_rule(base, node.name.data, node.name.length);
    if node.kind != SyntaxRule {
        if previous is not null {
            syntax_revision_error(error, "Name already defines a parse rule: ", node.name.data, node.name.length);
            return null;
        }
        var count = base ?. tokens.length ?? 0;
        var tokens = base ?. tokens.data;
        if count >= SyntaxRevisionTokenLimit && syntax_revision_token(tokens, count, node.name.data, node.name.length, kind) == count {
            syntax_revision_error(error, "Token rule limit is 64", null, 0);
            return null;
        }
        return syntax_revision_overlay(base, null, 0, &entity, 1, kind);
    }
    if node.append && previous is null {
        syntax_revision_error(error, "Cannot extend undefined rule: ", node.name.data, node.name.length);
        return null;
    }
    var alternatives: vector(void*);
    vector_init(&alternatives);
    var before = node.append ? previous.count: 0;
    var total = before + node.items.length;
    var ok = total >= before && vector_reserve(&alternatives, total);
    var result: FrontendRevision* = null;
    if ok {
        for(var i: usize = 0; i < before; ++i) {
            alternatives.data[i] = previous.alternatives[i];
        }
        for(var i: usize = 0; i < node.items.length; ++i) {
            alternatives.data[before + i] = node.items.data[i];
        }
        var rule: SyntaxRuleView = { name: node.name.data, name_length: node.name.length, alternatives: alternatives.data, count: total };
        result = syntax_revision_overlay(base, &rule, 1, null, 0, kind);
    }
    vector_dispose(&alternatives);
    return result;
}

export fn syntax_revision_ready(base: FrontendRevision*, waiting: void**): FrontendRevision* {
    var count: usize = 0;
    for(var i: usize = 0; i < base.rules.length; ++i) {
        if waiting[i] is null {
            ++count;
        }
    }
    if count == base.rules.length {
        return frontend_revision_retain(base);
    }
    var rules: vector(SyntaxRuleView);
    vector_init(&rules);
    var result: FrontendRevision* = null;
    if vector_reserve(&rules, count) {
        for(var i: usize = 0; i < base.rules.length; ++i) {
            if waiting[i] is null {
                copy(&rules.data[rules.length], &base.rules.data[i], sizeof(SyntaxRuleView));
                ++rules.length;
            }
        }
        result = frontend_revision_create(rules.data, count, base.tokens.data, base.tokens.length);
    }
    vector_dispose(&rules);
    return result;
}

export fn syntax_revision_document(document: void*, kind: void*): FrontendRevision* {
    var node = syntax_revision_node(document, kind);
    var revision = syntax_revision_create(null, 0, null, 0);
    var error: vector(u8);
    vector_init(&error);
    var i: usize = 0;
    while revision is not null && i < node.items.length {
        var next = syntax_revision_declare(revision, node.items.data[i], kind, &error);
        frontend_revision_release(revision);
        revision = next;
        ++i;
    }
    vector_dispose(&error);
    return revision;
}

export fn syntax_revision_reference(revision: FrontendRevision*, name: u8*, length: usize,
index: usize, count: usize*, kind: void*): void* {
    *count = 0;
    if revision is null {
        return null;
    }
    var rule = syntax_revision_rule(revision, name, length);
    if rule is not null {
        *count = rule.count;
        return index < rule.count ? rule.alternatives[index]: null;
    }
    var at = syntax_revision_token(revision.tokens.data, revision.tokens.length, name, length, kind);
    if at == revision.tokens.length {
        return null;
    }
    *count = 1;
    return index == 0 ? revision.tokens.data[at]: null;
}

export fn syntax_revision_bedrock_error(revision: FrontendRevision*, kind: void*): u8* {
    foreach(var & alternative in &revision.alternatives) {
        if syntax_revision_node(*alternative, kind).replacement is not null {
            return "Bedrock declaration rules cannot use replacement handlers yet";
        }
    }
    var index = syntax_revision_token(revision.tokens.data, revision.tokens.length, "Identifier", 10, kind);
    if index == revision.tokens.length || syntax_revision_node(revision.tokens.data[index], kind).kind != SyntaxToken {
        return "Bedrock must define token Identifier";
    }
    return "";
}

