    name: vector(u8);
    text: vector(u8);
}

struct SyntaxPattern {
    references: usize;
    table: LexerTable*;
    grammar: void*;
}

struct SyntaxNode {
    kind: u32;
    name: vector(u8);
    text: vector(u8);
    capture: vector(u8);
    style: vector(u8);
    source: SyntaxSource*;
    literal: bool;
    append: bool;
