// Shared request ownership; only platform transport remains in this host.
fn driver_execution_close(execution: ExecutionSession*): void {
    execution_session_close(execution);
}

fn driver_execution_compile(execution: ExecutionSession*, text: u8*, length: usize, width: u32, modules: void*): bool {
    return execution_session_compile(execution, text, length, width, modules);
}

fn driver_execution_start(execution: ExecutionSession*): bool {
    return execution_session_start(execution);
}

fn driver_execution_fast(execution: ExecutionSession*): bool {
    return execution_session_fast(execution);
}

fn driver_execution_flush(execution: ExecutionSession*): void {
    driver_platform_write(1, execution.output.data, execution.output.length);
    execution.output.length = 0;
}

export fn im_pointer_bytes(machine: IMState*): usize {
    return convert(usize, bits(ExecutionSession*, machine).program.pointer_bytes);
}

export fn im_root(machine: IMState*): void* {
    return bits(ExecutionSession*, machine).program.root;
}

export fn im_has_foreign(machine: IMState*): bool {
    return true;
}

export fn im_fail(machine: IMState*, text: u8*, offset: usize): void {
    execution_session_fail(bits(ExecutionSession*, machine), text, offset);
}

extern fn abort(): void;

export fn im_missing_foreign(machine: IMState*, node: void*, offset: usize): void {
    var text: ByteBuffer = default;
    var function = sem_get(node);
    var ok = driver_text(&text, "No interpreter implementation registered for external function '");
    ok &&= bytes_append(&text, function.name.data, function.name.length);
    ok &&= driver_text(&text, "'");
    ok &&= host_text_terminate(&text);
    im_fail(machine, ok ? text.data: "Unable to allocate interpreter diagnostic", offset);
    bytes_dispose(&text);
}

export fn im_append(machine: IMState*, text: u8*, count: usize): void {
    execution_session_append(bits(ExecutionSession*, machine), text, count);
}

extern fn memcmp(left: u8*, right: u8*, count: usize): i32;

extern fn driver_platform_write_result(fd: i32, data: u8*, length: usize): bool;

export fn im_foreign(machine: IMState*, node: void*, args: u64*, count: usize): u64 {
    var function = sem_get(node);
    if function.name.length != 14 || memcmp(function.name.data, "platform_write", 14) != 0 || count != 3 {
        var text: ByteBuffer = default;
        var ok = driver_text(&text, "No native interpreter binding for '");
        ok &&= bytes_append(&text, function.name.data, function.name.length);
        ok &&= driver_text(&text, "'");
        ok &&= host_text_terminate(&text);
        im_fail(machine, ok ? text.data: "Unable to allocate interpreter diagnostic", 0);
        bytes_dispose(&text);
        return 0;
    }
    if args[0] != 1 && args[0] != 2 {
        return ~convert(u64, 0);
    }
    var data = interpreter_bytes(machine, args[1], convert(usize, args[2]), 0);
    if data == null {
        return ~convert(u64, 0);
    }
    driver_execution_flush(bits(ExecutionSession*, machine));
    if driver_platform_write_result(convert(i32, args[0]), data, convert(usize, args[2])) {
        return args[2];
    }
    return ~convert(u64, 0);
}

import tower;
import .compiler.host_text;
import .library.bytes_interface;
import .library.bytes_types;

// Opaque libc file handles are temporary platform services, not Tower values or
// program storage. Paths and bytes are explicit inputs; no host file is read
// during constant evaluation. The CLI calls these at its execution stage.
extern fn fopen(path: u8*, mode: u8*): void*;

extern fn fread(data: u8*, size: usize, count: usize, file: void*): usize;

extern fn fwrite(data: u8*, size: usize, count: usize, file: void*): usize;

extern fn ferror(file: void*): i32;

extern fn feof(file: void*): i32;

extern fn fclose(file: void*): i32;

// Success replaces out atomically, including the terminating NUL view. Failure
// leaves its old contents intact and closes the file on every path.
export fn driver_read_file(path: u8*, out: ByteBuffer*): bool {
    var file = fopen(path, "rb");
    if file == null {
        return false;
    }
    var next: ByteBuffer = default;
    var chunk: u8[16384];
    var ok = true;
    loop {
        var count = fread(&chunk[0], 1, 16384, file);
        ok = bytes_append(&next, &chunk[0], count);
        if !ok {
            break;
        }
        if ferror(file) != 0 {
            ok = false;
            break;
        }
        if feof(file) != 0 {
            break;
        }
        if count == 0 {
            ok = false;
            break;
        }
    }
    if !(fclose(file) == 0) {
        ok = false;
    }
    ok &&= host_text_terminate(&next);
    if ok {
        bytes_dispose(out);
        out.data = next.data;
        out.length = next.length;
        out.capacity = next.capacity;
    } else {
        bytes_dispose(&next);
    }
    return ok;
}

// Output is binary (including NUL). A write/close failure is reported; callers
// must not treat a partial output file as a successful compiler artifact.
export fn driver_write_file(path: u8*, data: u8*, count: usize): bool {
    var file = fopen(path, "wb");
    if file == null {
        return false;
    }
    var written: usize = 0;
    var ok = true;
    loop {
        if written == count {
            break;
        }
        var next = data + written;
        var remaining = count -written;
        var amount = fwrite(next, 1, remaining, file);
        if amount == 0 {
            ok = false;
            break;
        }
        written = written + amount;
    }
    if ferror(file) != 0 {
        ok = false;
    }
    if !(fclose(file) == 0) {
        ok = false;
    }
    return ok;
}

import tower;
import .library.bytes_types;
import .library.bytes_interface;
import driver_support;
import driver_timing;
import driver_platform;

struct DriverLink {
    target: u8*;
    cc: u8*;
    linker: u8*;
    sysroot: u8*;
    output: u8*;
    root: u8*;
    wasm: bool;
    windows: bool;
    timing: DriverTiming*;
    timings: bool;
    program: ByteBuffer;
    runtime: ByteBuffer;
    allowed: ByteBuffer;
    imports: ByteBuffer;
    exports: DriverArguments;
    inputs: DriverArguments;
    ok: bool;
}

export fn driver_link_open(target: u8*, cc: u8*, linker: u8*, sysroot: u8*, output: u8*, root: u8*, wasm: bool, windows: bool, timing: DriverTiming*, timings: bool): DriverLink* {
    var link = alloc(DriverLink, 1);
    if link == null {
        driver_error("Unable to allocate link storage", "");
        return null;
    }
    *link = default;
    link.target = target;
    link.cc = cc;
    link.linker = linker;
    link.sysroot = sysroot;
    link.output = output;
    link.root = root;
    link.wasm = wasm;
    link.windows = windows;
    link.timing = timing;
    link.timings = timings;
    driver_arguments_init(&link.exports);
    driver_arguments_init(&link.inputs);
    link.ok = driver_text(&link.imports, "tower_print\ntower_trap\n");
    return link;
}

export fn driver_link_import(link: DriverLink*, name: u8*): void {
    link.ok &&= driver_text(&link.imports, name);
    link.ok &&= driver_text(&link.imports, "\n");
}

export fn driver_link_export(link: DriverLink*, name: u8*): void {
    driver_argument(&link.exports, "", name);
}

export fn driver_link_input(link: DriverLink*, name: u8*): void {
    driver_argument(&link.inputs, "", name);
}

fn driver_link_compile_arguments(link: DriverLink*, args: DriverArguments*): void {
    driver_argument(args, "", link.cc);
    driver_argument(args, "--target=", link.target);
    driver_argument(args, "", "-O2");
    driver_argument(args, "", "-ffreestanding");
    driver_argument(args, "", "-fno-builtin");
    driver_argument(args, "", "-c");
    driver_argument(args, link.root, driver_runtime_resource(link.target));
    driver_argument(args, "", "-o");
    driver_argument(args, "", link.runtime.data);
    if link.sysroot[0] != 0 {
        driver_argument(args, "--sysroot=", link.sysroot);
    }
    driver_argument(args, "", "-mllvm");
    driver_argument(args, "", "-disable-loop-idiom-all");
    driver_argument(args, "", "-Wno-override-module");
}

extern fn strstr(text: u8*, part: u8*): u8*;

fn driver_runtime_resource(target: u8*): u8* {
    if strstr(target, "wasm32") == target {
        return "/runtime-wasm32.ll";
    }
    var arm = strstr(target, "aarch64") == target;
    arm ||= strstr(target, "arm64") == target;
    var x64 = strstr(target, "x86_64") == target;
    var supported = arm;
    if x64 {
        supported = true;
    }
    if !supported {
        return null;
    }
    if strstr(target, "windows") != null {
        if arm {
            return "/runtime-windows-arm64.ll";
        }
        return "/runtime-windows-x64.ll";
    }
    if strstr(target, "apple") != null {
        if arm {
            return "/runtime-macos-arm64.ll";
        }
        return "/runtime-macos-x64.ll";
    }
    if arm {
        return "/runtime-host-linux-arm64.ll";
    }
    return "/runtime-host-linux-x64.ll";
}

fn driver_link_arguments(link: DriverLink*, args: DriverArguments*): void {
    var linker = link.linker;
    if linker[0] == 0 {
        linker = link.cc;
        if link.windows {
            linker = "lld-link-19";
        }
        if link.wasm {
            linker = "wasm-ld-19";
        }
    }
    driver_argument(args, "", linker);
    if link.wasm {
        driver_argument(args, "", "--no-entry");
        driver_argument(args, "", "--export=tower_main");
        driver_argument(args, "", "--export-memory");
        driver_argument(args, "--allow-undefined-file=", link.allowed.data);
        driver_argument(args, "", "--stack-first");
        driver_argument(args, "", "-z");
        driver_argument(args, "", "stack-size=4194304");
        driver_argument(args, "", "--max-memory=268435456");
    } else {
        if link.windows {
            driver_argument(args, "", "/entry:mainCRTStartup");
            driver_argument(args, "", "/subsystem:console");
            driver_argument(args, "/out:", link.output);
        } else {
            driver_argument(args, "--target=", link.target);
        }
    }
    driver_argument(args, "", link.program.data);
    driver_argument(args, "", link.runtime.data);
    var exports = link.wasm;
    if link.windows {
        exports = true;
    }
    if exports {
        var prefix = "--export=";
        if link.windows {
            prefix = "/export:";
        }
        for(var i: usize = 0; i < link.exports.values.length; i++) {
            driver_argument(args, prefix, link.exports.values.data[i]);
        }
    } else {
        if link.sysroot[0] != 0 {
            driver_argument(args, "--sysroot=", link.sysroot);
        }
    }
    for(var i: usize = 0; i < link.inputs.values.length; i++) {
        driver_argument(args, "", link.inputs.values.data[i]);
    }
    if !link.windows {
        driver_argument(args, "", "-o");
        driver_argument(args, "", link.output);
    }
}

fn driver_link_execute(link: DriverLink*, data: u8*, length: usize): i32 {
    var runtime = driver_runtime_resource(link.target);
    if runtime == null {
        driver_error("No bundled executable runtime profile for target: ", link.target);
        return 1;
    }
    var ok = link.ok;
    ok &&= link.exports.ok;
    ok &&= link.inputs.ok;
    if !ok {
        driver_error("Unable to allocate link arguments", "");
        return 1;
    }
    if !driver_platform_temporary(&link.program) {
        return 1;
    }
    if !driver_platform_temporary(&link.runtime) {
        return 1;
    }
    if !driver_platform_temporary(&link.allowed) {
        return 1;
    }
    if !driver_write_file(link.program.data, data, length) {
        return 1;
    }
    var compile: DriverArguments;
    driver_arguments_init(&compile);
    driver_link_compile_arguments(link, &compile);
    var result = driver_command(&compile);
    driver_arguments_dispose(&compile);
    if result != 0 {
        return result;
    }
    driver_timing_mark(link.timing, link.timings, "runtimeCompile");
    if link.wasm {
        if !driver_write_file(link.allowed.data, link.imports.data, link.imports.length) {
            driver_error("Cannot write linker import list", "");
            return 1;
        }
    }
    var args: DriverArguments;
    driver_arguments_init(&args);
    driver_link_arguments(link, &args);
    result = driver_command(&args);
    driver_arguments_dispose(&args);
    driver_timing_mark(link.timing, link.timings, "link");
    return result;
}

fn driver_temporary_dispose(path: ByteBuffer*): void {
    if path.length != 0 {
        driver_platform_remove(path.data);
    }
    bytes_dispose(path);
}

export fn driver_link_close(link: DriverLink*): void {
    if link == null {
        return;
    }
    driver_temporary_dispose(&link.program);
    driver_temporary_dispose(&link.runtime);
    driver_temporary_dispose(&link.allowed);
    bytes_dispose(&link.imports);
    driver_arguments_dispose(&link.exports);
    driver_arguments_dispose(&link.inputs);
    free(link);
}

// The owning wrapper releases every temporary on all ordinary failure paths.
export fn driver_link_run(link: DriverLink*, data: u8*, length: usize): i32 {
    var result = driver_link_execute(link, data, length);
    driver_link_close(link);
    return result;
}

export fn driver_write_ir(raw_path: u8*, raw: u8*, raw_count: usize, optimized_path: u8*, optimized: u8*, optimized_count: usize): bool {
    var ok = true;
    var requested = raw_path[0] != 0;
    if requested {
        ok = driver_write_file(raw_path, raw, raw_count);
    }
    requested = optimized_path[0] != 0;
    if ok {
        if requested {
            ok = driver_write_file(optimized_path, optimized, optimized_count);
        }
    }
    if !ok {
        driver_error("Cannot write LLVM output", "");
    }
    return ok;
}

import tower;
import driver_posix;
import driver_support;
import .library.bytes_types;
import .library.bytes_interface;

extern fn __errno_location(): i32*;

extern fn readlink(path: u8*, output: u8*, capacity: usize): i64;

export fn driver_platform_executable(out: ByteBuffer*): bool {
    var capacity: usize = 256;
    loop {
        if !bytes_reserve(out, capacity) {
            return false;
        }
        var count = readlink("/proc/self/exe", out.data, capacity);
        if count < 0 {
            return false;
        }
        var length = convert(usize, count);
        if length < capacity {
            out.length = length;
            return host_text_terminate(out);
        }
        var maximum: usize = 0;
        maximum = maximum - 1;
        var limit = maximum / 2;
        if capacity > limit {
            return false;
        }
        capacity = capacity * 2;
    }
}

export fn driver_errno(): i32* {
    return __errno_location();
}

export fn driver_monotonic_clock(): i32 {
    return 1;
}

extern fn read(fd: i32, data: u8*, length: usize): i64;

extern fn pipe2(descriptors: i32*, flags: i32): i32;

var DriverCloseOnExec: i32 = 524288;

extern fn fork(): i32;

extern fn execv(file: u8*, argv: u8**): i32;

extern fn _exit(code: i32): void;

extern fn waitpid(pid: i32, status: i32*, flags: i32): i32;

export fn driver_posix_execute(executable: u8*, argv: u8**): i32 {
    // A close-on-exec pipe distinguishes exec failure from a tool returning 127.
    // The child only invokes libc async-signal-safe operations before exec/_exit.
    var descriptors: i32[2];
    if pipe2(&descriptors[0], DriverCloseOnExec) != 0 {
        driver_error("Cannot start tool: ", strerror(driver_error_code()));
        return 1;
    }
    var pid = fork();
    if pid == 0 {
        close(descriptors[0]);
        execv(executable, argv);
        var error = driver_error_code();
        write(descriptors[1], bits(u8*, &error), sizeof(i32));
        _exit(127);
    }
    var fork_error = driver_error_code();
    close(descriptors[1]);
    if pid < 0 {
        close(descriptors[0]);
        driver_error("Cannot start tool: ", strerror(fork_error));
        return 1;
    }
    var error: i32 = 0;
    var received: usize = 0;
    while received < sizeof(i32) {
        var data = bits(u8*, &error) + received;
        var remaining = sizeof(i32) -received;
        var count = read(descriptors[0], data, remaining);
        if count < 0 {
            if driver_error_code() == 4 {
                continue;
            }
            error = 5;
            break;
        }
        if count == 0 {
            break;
        }
        received = received + convert(usize, count);
    }
    close(descriptors[0]);
    var status: i32 = 0;
    loop {
        var waited = waitpid(pid, &status, 0);
        if waited == pid {
            break;
        }
        if driver_error_code() == 4 {
            continue;
        }
        driver_error("Cannot wait for tool: ", strerror(driver_error_code()));
        return 1;
    }
    if error != 0 {
        if error == 2 {
            driver_error("Cannot find tool: ", argv[0]);
        }
        else {
            driver_error("Cannot execute tool: ", strerror(error));
        }
        return 1;
    }
    if status == 0 {
        return 0;
    }
    return 1;
}

