export fn driver_platform_exists(path: u8*): bool {
    var exists = access(path, 0) == 0;
    return exists;
}

export fn driver_platform_separator(byte: u8): bool {
    var separator = byte == 47;
    return separator;
}

fn driver_error_code(): i32 {
    var slot = driver_errno();
    return *slot;
}

export fn driver_clock(): u64 {
    var time: DriverTimespec;
    if clock_gettime(driver_monotonic_clock(), &time) != 0 {
        return 0;
    }
    var seconds = convert(u64, time.seconds) *1000000000;
    var result = seconds + convert(u64, time.nanoseconds);
    return result;
}

export fn driver_platform_write(fd: i32, data: u8*, length: usize): void {
    driver_platform_write_result(fd, data, length);
}

export fn driver_platform_write_result(fd: i32, data: u8*, length: usize): bool {
    while length != 0 {
        var count = write(fd, data, length);
        if count < 0 {
            if driver_error_code() == 4 {
                continue;
            }
            return false;
        }
        if count == 0 {
            return false;
        }
        var done = convert(usize, count);
        data = data + done;
        length = length - done;
    }
    return true;
}

export fn driver_platform_remove(path: u8*): void {
    unlink(path);
}

export fn driver_platform_temporary(out: ByteBuffer*): bool {
    var directory = getenv("TMPDIR");
    var missing_directory = directory == null;
    if missing_directory {
        directory = getenv("TMP");
    }
    missing_directory = directory == null;
    if missing_directory {
        directory = getenv("TEMP");
    }
    missing_directory = directory == null;
    if missing_directory {
        directory = getenv("TEMPDIR");
    }
    missing_directory = directory == null;
    if missing_directory {
        directory = "/tmp";
    }
    var ok = driver_text(out, directory);
    if directory[0] != 0 {
        ok &&= driver_text(out, "/");
    }
    ok &&= driver_text(out, "tower-XXXXXX");
    ok &&= host_text_terminate(out);
    if !ok {
        out.length = 0;
        return false;
    }
    var fd = mkstemp(out.data);
    if fd < 0 {
        driver_error("Cannot create temporary file: ", strerror(driver_error_code()));
        out.length = 0;
        return false;
    }
    if close(fd) != 0 {
        driver_platform_remove(out.data);
        out.length = 0;
        return false;
    }
    return true;
}

fn driver_find_tool(out: ByteBuffer*, name: u8*): bool {
    var i: usize = 0;
    for(; name[i] != 0; i++) {
        if name[i] == 47 {
            var ok = driver_text(out, name);
            ok &&= host_text_terminate(out);
            ok &&= access(out.data, 1) == 0;
            return ok;
        }
    }
    var path = getenv("PATH");
    if path == null {
        return false;
    }
    var begin: usize = 0;
    i = 0;
    loop {
        var c = path[i];
        var boundary = c == 58;
        var end = c == 0;
        if end {
            boundary = true;
        }
        if boundary {
            out.length = 0;
            var count = i -begin;
            var segment = path + begin;
            var ok = bytes_append(out, segment, count);
            if count != 0 {
                ok &&= driver_text(out, "/");
            }
            ok &&= driver_text(out, name);
            ok &&= host_text_terminate(out);
            if !ok {
                return false;
            }
            if access(out.data, 1) == 0 {
                return true;
            }
            if end {
                return false;
            }
            begin = i + 1;
        }
        i++;
    }
    return false;
}

export fn driver_platform_run(argv: u8**): i32 {
    var executable: ByteBuffer = default;
    var result: i32 = 1;
    if driver_find_tool(&executable, argv[0]) {
        var original = argv[0];
        argv[0] = executable.data;
        result = driver_posix_execute(executable.data, argv);
        argv[0] = original;
    } else {
        driver_error("Cannot find tool: ", argv[0]);
    }
    bytes_dispose(&executable);
    return result;
}

