    var id = GuestWindowsStdout;
    if stream == 2 {
        id = GuestWindowsStderr;
    }
    else {
        if !(stream == 1) {
            return -1;
        }
    }
    var total: usize = 0;
    while total < count {
        var remaining = count -total;
        if remaining > GuestWindowsWriteLimit {
            remaining = GuestWindowsWriteLimit;
        }
