extern fn compiler_node_type(node: void*, kind: u32): void*;

enum IdePackageError: u32 { CacheMismatch = 9 }
var IdePackageHeaderBytes: usize = 56;
var IdePackageNarrowPointerBytes: u32 = 4;
var IdePackageWidePointerBytes: u32 = 8;

fn ide_program_format(session: IdeExecution*, formatted: FormatResult*): void {
    *formatted = default;
    var present = session != null;
    present &&= session.program.error.length == 0;
    if present {
        format_entity(formatted, session.program.root, compiler_node_type(session.program.root, CompilerSyntax),
            null, compiler_node_type(session.program.root, CompilerParserMatch));
    }
}

fn ide_emit(handle: u32, flags: u32, roku: bool): u8* {
    var session = ide_execution(handle);
    if session == null {
        ide_error("Invalid execution handle");
        return null;
    }
    var output: ByteBuffer;
    var error: ByteBuffer;
    output = default;
    error = default;
    var bit = flags &1;
    var comments = bit == 0;
    if roku {
        roku_emit(&output, &error, session.program.root, session.program.pointer_bytes, comments);
    }
    else {
        c_emit(&output, &error, session.program.root, session.program.pointer_bytes, comments);
    }
    if error.length != 0 {
        ide_error(ide_result(&error));
        bytes_dispose(&output);
        bytes_dispose(&error);
        return null;
    }
    var state = ide_state();
    ide_require(bytes_assign_text(&state.execution, output.data, output.length));
    bytes_dispose(&output);
    bytes_dispose(&error);
    return ide_result(&state.execution);
}

export fn tw_exec_c(handle: u32, flags: u32): u8* {
    return ide_emit(handle, flags, false);
}

export fn tw_exec_roku(handle: u32, flags: u32): u8* {
    return ide_emit(handle, flags, true);
}

export fn tw_exec_strip_comments(handle: u32): void {
    var session = ide_execution(handle);
    if session != null {
        semantic_strip_comments(session.program.root);
    }
}

fn ide_package_reset(): void {
    var state = ide_state();
    bytecode_free(state.bytecode);
    state.bytecode = null;
    state.bytecode_size = 0;
    ide_error("");
}

// Check the exact Foundation bytes stored in the envelope once. Encoding and
// verification use that graph; an external package loader reconstructs the same
// text independently. The returned session owns fresh guest storage and nodes.
fn ide_prepare_package_text(source: u8*, length: usize, width: u32, profile: u32): IdeExecution* {
    var state = ide_state();
    var canonical = ide_execution_text(source, length, width, true);
    var failed = canonical.error.length != 0;
    if failed {
        ide_error(ide_result(&canonical.error));
    }
    else {
        if ide_execution_fast(canonical) {
            state.bytecode = bytecode_encode(canonical.fast, source, length, convert(usize, width), profile, &state.bytecode_size);
        }
        failed = state.bytecode == null;
        if failed {
            ide_error("Cannot allocate .towerbc package");
        }
    }
    if !failed {
        var invalid = bytecode_validate(state.bytecode, state.bytecode_size);
        if invalid != 0 {
            ide_error(bytecode_error(invalid));
            failed = true;
        } else {
            if !bytecode_matches(canonical.fast, state.bytecode) {
                ide_error(bytecode_error(convert(u32, IdePackageError.CacheMismatch)));
                failed = true;
            }
        }
    }
    if failed {
        ide_execution_close(canonical);
        bytecode_free(state.bytecode);
        state.bytecode = null;
        state.bytecode_size = 0;
        return null;
    }
    return canonical;
}

// A handle may already have executed or contain noncanonical source. Preserve
// its snapshot contract by formatting and reconstructing independent storage.
fn ide_prepare_package(handle: u32, profile: u32): IdeExecution* {
    ide_package_reset();
    var session = ide_execution(handle);
    if session is null || session.program.error.length != 0 {
        ide_error("Cannot package an invalid program");
        return null;
    }
    var formatted: FormatResult;
    ide_program_format(session, &formatted);
    defer format_dispose(&formatted);
    if formatted.failed {
        ide_error("Cannot format .towerbc Foundation source");
        return null;
    }
    return ide_prepare_package_text(formatted.text.data, formatted.text.length, session.program.pointer_bytes, profile);
}

// LLVM already supplies Foundation through the shared formatter. Accept that
// interchange text directly instead of compiling, formatting and parsing it
// again. No checked graph, execution cache or mutable world crosses workers.
export fn tw_exec_prepare_foundation_package(source: u8*, length: usize, width: u32, profile: u32): u32 {
    ide_package_reset();
    if !ide_valid(source, length) { return 0; }
    if width != IdePackageNarrowPointerBytes && width != IdePackageWidePointerBytes {
        ide_error("Unsupported target pointer width");
        return 0;
    }
    if !ide_execution_capacity() { return 0; }
    var canonical = ide_prepare_package_text(source, length, width, profile);
    if canonical is null { return 0; }
    return ide_execution_publish(canonical);
}

export fn tw_exec_prepare_package(handle: u32, profile: u32): u32 {
    if !ide_execution_capacity() { return 0; }
    var canonical = ide_prepare_package(handle, profile);
    if canonical == null { return 0; }
    return ide_execution_publish(canonical);
}

export fn tw_exec_bytecode_size(): usize {
    return ide_state().bytecode_size;
}

export fn tw_exec_bytecode_options(handle: u32, profile: u32): usize {
    var canonical = ide_prepare_package(handle, profile);
    if canonical == null { return 0; }
    ide_execution_close(canonical);
    var state = ide_state();
    return state.bytecode_size;
}

export fn tw_exec_bytecode(handle: u32): usize {
    return tw_exec_bytecode_options(handle, 0);
}

export fn tw_exec_bytecode_data(): u8* {
    var state = ide_state();
    return state.bytecode;
}

export fn tw_exec_load_bytecode(data: u8*, size: usize): u32 {
    if !ide_execution_capacity() {
        return 0;
    }
    ide_error("");
    var invalid = bytecode_validate(data, size);
    var rejected = invalid != 0;
    if rejected {
        ide_error(bytecode_error(invalid));
        return 0;
    }
    var source = data + IdePackageHeaderBytes;
    var length = bytecode_source_size(data);
    for(var i: usize = 0; i < length; i++) {
        rejected = source[i] == 0;
        if rejected {
            ide_error("NUL in .towerbc Foundation source");
            return 0;
        }
    }
    var session = ide_execution_text(source, length, convert(u32, bytecode_pointer_bytes(data)), true);
    rejected = session.error.length != 0;
    if rejected {
        ide_error(ide_result(&session.error));
        ide_execution_close(session);
        return 0;
    }
    var ready = ide_execution_fast(session);
    ready &&= bytecode_matches(session.fast, data);
    if !ready {
        ide_error(bytecode_error(convert(u32, IdePackageError.CacheMismatch)));
        ide_execution_close(session);
        return 0;
    }
    return ide_execution_publish(session);
}

fn ide_type_name(out: ByteBuffer*, type: FoundationType*): void {
    var name: vector(u8);
    vector_init(&name);
    semantic_format_type(type, &name);
    ide_quote_bytes(out, name.data, name.length);
    vector_dispose(&name);
}

export fn tw_exec_foundation(handle: u32): u8* {
    var session = ide_execution(handle);
    var formatted: FormatResult;
    ide_program_format(session, &formatted);
    var state = ide_state();
    var out = &state.execution;
    ide_assign(out, "{\"source\":");
    if formatted.failed {
        ide_quote(out, "");
        ide_spans(out, null, 0);
    }
    else {
        ide_quote_bytes(out, formatted.text.data, formatted.text.length);
        ide_spans(out, formatted.spans.data, formatted.spans.length);
    }
    ide_text(out, ",\"types\":[");
    var present = session != null;
    present &&= session.program.error.length == 0;
    if present {
        var i: usize = 0;
        for(; i < session.program.types.length; i++) {
            var type = sem_get(session.program.types.data[i]);
            ide_comma(out, i);
            ide_text(out, "{\"name\":");
            ide_quote_bytes(out, type.name.data, type.name.length);
            var kind: u8* = "scalar";
            var array = type.type.scalar == SArray;
            var record = type.type.scalar == SStruct;
            var empty = type.type.scalar == SVoid;
            if array {
                kind = "array";
            }
            if record {
                kind = "struct";
            }
            if empty {
                kind = "void";
            }
            ide_string(out, "kind", kind);
            if array {
                ide_key(out, "element");
                ide_type_name(out, &type.element);
                ide_field(out, "length", type.length);
            }
            ide_field(out, "size", type.size);
            ide_field(out, "alignment", type.alignment);
            ide_text(out, ",\"fields\":[");
            var j: usize = 0;
            for(; j < type.items.length; j++) {
                var member = sem_get(type.items.data[j]);
                ide_comma(out, j);
                ide_text(out, "{\"name\":");
                ide_quote_bytes(out, member.name.data, member.name.length);
                ide_key(out, "type");
                ide_type_name(out, &member.type);
                ide_field(out, "offset", member.byte_offset);
                ide_field(out, "size", semantic_size(&member.type));
                ide_field(out, "alignment", semantic_alignment(&member.type));
                ide_text(out, "}");
            }
            ide_text(out, "]}");
        }
    }
    ide_text(out, "]}");
    format_dispose(&formatted);
    return ide_result(out);
}

import tower;
import ide_api;
import ide_state;
import ide_text;
import ide_syntax;
import .compiler.syntax_session_types;
import .compiler.syntax_types;
import .library.vector;

fn ide_consume(syntax: void*): void {
    for(var i: usize = 0; i < 1024; i++) {
        var root = syntax_next(syntax);
        if root == null {
            break;
        }
        entity_release(root);
    }
}

export fn tw_complete(source: u8*, bytes: usize, cursor: usize, mode: u32, files: u8**, lengths: usize*, count: usize): u8* {
    var valid = ide_valid(source, bytes);
    var bad = cursor > bytes;
    if bad {
        valid = false;
    }
    bad = mode > 2;
    if bad {
        valid = false;
    }
    bad = count > 1024;
    if bad {
        valid = false;
    }
    if count != 0 {
        bad = files == null;
        if bad {
            valid = false;
        }
        bad = lengths == null;
        if bad {
            valid = false;
        }
    }
    if !valid {
        return "{\"error\":\"Invalid completion request\"}";
    }
    if cursor < bytes {
        var prefix = source[cursor] &192;
        bad = prefix == 128;
        if bad {
            return "{\"error\":\"Completion cursor must be a UTF-8 boundary\"}";
        }
    }
    var total = bytes;
    var i: usize = 0;
    for(; i < count; i++) {
        var left = 8388608 -total;
        bad = lengths[i] > left;
        if !bad {
            valid = ide_valid(files[i], lengths[i]);
            bad = !valid;
        }
        if bad {
            return "{\"error\":\"Invalid completion project source\"}";
        }
        total = total + lengths[i];
    }
    var text = ide_copy(source, bytes);
    var original = syntax_completion_create(text, mode);
    free(text);
    ide_consume(original);
    var listing: SyntaxHighlights = default;
    ide_require(syntax_session_lexemes(original, &listing));
    var lexemes = listing.items.data;
    var size = listing.items.length;
    var spans = alloc(IdeCompletionSpan, size);
    var allocated = spans != null;
    if size == 0 {
        allocated = true;
    }
    ide_require(allocated);
    i = 0;
    for(; i < size; i++) {
        spans[i].start = lexemes[i].start;
        spans[i].end = lexemes[i].end;
        spans[i].opaque = lexemes[i].opaque;
    }
    syntax_highlights_dispose(&listing);
    var query = completion_begin(source, bytes, cursor, spans, size);
    free(spans);
    if query == null {
        syntax_destroy(original);
        return "{\"error\":\"Cannot allocate completion query\"}";
    }
    text = ide_copy(source, completion_from(query));
    var active = syntax_completion_create(text, mode);
    free(text);
    syntax_completion_enable(active);
    ide_consume(active);
    completion_analyze(query, active, mode, files, lengths, count);
    completion_symbols(query);
    // Preserve offering order and priority from the public completion contract.
    size = syntax_session_keyword_count(active);
    i = 0;
    for(; i < size; i++) {
        completion_offer(query, syntax_session_keyword(active, i), "keyword", "active grammar", 0);
    }
    size = syntax_session_rule_count(active);
    i = 0;
    for(; i < size; i++) {
        completion_offer(query, syntax_session_rule(active, i).name, "type", "grammar rule", 2);
    }
    size = syntax_session_token_count(active);
    i = 0;
    for(; i < size; i++) {
        var item = syntax_session_token(active, i);
        if item.kind != convert(u32, SyntaxKind.Skip) {
            completion_offer(query, item.name.data, "type", "token rule", 2);
        }
    }
    var state = ide_state();
    ide_assign(&state.completion, completion_end(query));
    completion_dispose(query);
    syntax_destroy(active);
    syntax_destroy(original);
    return ide_result(&state.completion);
}

import tower;
import ide_types;
import ide_api;
import ide_state;
import ide_text;
import syntax_baseline_api;
import .compiler.syntax_version_types;
import .library.bytes_types;
import .library.bytes_interface;
import .library.vector;
import .compiler.interpreter_types;
import .compiler.semantic_program_types;
import .compiler.foundation_types;

// Each execution owns its root, typed program indexes, cache and guest storage.
// Destruction takes the handle first; a stale handle cannot reach freed state.
fn ide_execution_close(session: IdeExecution*): void {
    if session.fast != null {
        fast_interpreter_dispose(session.fast);
    }
    interpreter_storage_dispose(&session.machine);
    semantic_program_dispose(&session.program);
    entity_release(session.program.root);
    bytes_dispose(&session.error);
    bytes_dispose(&session.output);
    free(session);
}

fn ide_execution_compile(sources: FrontendSource*, count: usize, width: u32, foundation: bool): IdeExecution* {
    var session = alloc(IdeExecution, 1);
    var exists = session != null;
    ide_require(exists);
    *session = default;
    semantic_initialize(&session.program, tower_node_create(), width);
    var state = ide_state();
    var rejected = false;
    if foundation {
        rejected = state.foundation_error.length != 0;
    }
    if rejected {
        ide_require(bytes_assign_text(bits(ByteBuffer*, &session.program.error), state.foundation_error.data, state.foundation_error.length));
    }
    else {
        // Retain a normal frontend session lease while borrowing its environment.
        // This is the existing module loader, including caller-supplied inputs.
        var lease = syntax_completion_create("", 0);
        var environment = frontend_module_environment(syntax_completion_module(lease));
        frontend_compile_sources(&session.program, sources, count, environment);
        syntax_destroy(lease);
    }
    ide_require(bytes_assign_text(&session.error, session.program.error.data, session.program.error.length));
    session.machine.error_offset = session.program.error_offset;
    session.machine.failed = session.error.length != 0;
    session.machine.done = session.machine.failed;
    session.machine.stack = 16;
    session.machine.heap = 4194304;
    interpreter_init(&session.machine);
    return session;
}

fn ide_execution_text(source: u8*, length: usize, width: u32, foundation: bool): IdeExecution* {
    var text = ide_copy(source, length);
    var input: FrontendSource;
    input.data = text;
    input.length = length;
    var session = ide_execution_compile(&input, 1, width, foundation);
    free(text);
    return session;
}

fn ide_execution_publish(session: IdeExecution*): u32 {
    var state = ide_state();
    var handle = host_handles_insert(&state.handles, 1, bits(void*, session));
    if handle == 0 {
        ide_execution_close(session);
        ide_error("Cannot allocate execution handle");
    } else {
        session.handle = handle;
    }
    return handle;
}

fn ide_execution_capacity(): bool {
    var state = ide_state();
    if host_handles_count(&state.handles, 1) >= 8 {
        ide_error("Too many execution sessions");
        return false;
    }
    return true;
}

fn ide_execution_fast(session: IdeExecution*): bool {
    if session.machine.steps != 0 {
        return false;
    }
    if session.fast == null {
        session.fast = fast_interpreter_create(&session.machine);
    }
    var ready = session.fast != null;
    return ready;
}

export fn tw_exec_create_target(source: u8*, bytes: usize, width: u32): u32 {
    if !ide_valid(source, bytes) {
        return 0;
    }
    var valid = width == 4;
    if width == 8 {
        valid = true;
    }
    if !valid {
        ide_error("Unsupported target pointer width");
        return 0;
    }
    if !ide_execution_capacity() {
        return 0;
    }
    return ide_execution_publish(ide_execution_text(source, bytes, width, false));
}

export fn tw_exec_create(source: u8*, bytes: usize): u32 {
    return tw_exec_create_target(source, bytes, 4);
}

export fn tw_exec_create_foundation(source: u8*, bytes: usize): u32 {
    if !ide_valid(source, bytes) {
        return 0;
    }
    if !ide_execution_capacity() {
        return 0;
    }
    return ide_execution_publish(ide_execution_text(source, bytes, 4, true));
}

export fn tw_exec_create_files(sources: u8**, lengths: u32*, count: u32, width: u32): u32 {
    var valid = sources != null;
    var bad = lengths == null;
    if bad {
        valid = false;
    }
    bad = count == 0;
    if bad {
        valid = false;
    }
    bad = count > 1024;
    if bad {
        valid = false;
    }
    var allowed = width == 4;
    if width == 8 {
        allowed = true;
    }
    if !allowed {
        valid = false;
    }
    var state = ide_state();
    bad = host_handles_count(&state.handles, 1) >= 8;
    if bad {
        valid = false;
    }
    if !valid {
        ide_error("Invalid project compilation request");
        return 0;
    }
    var total: usize = 0;
    var i: usize = 0;
    for(; i < convert(usize, count); i++) {
        if !ide_valid(sources[i], convert(usize, lengths[i])) {
            return 0;
        }
        total = total + convert(usize, lengths[i]);
        bad = total > 8388608;
        if bad {
            ide_error("Project compilation limit is 8 MiB");
            return 0;
        }
    }
    var inputs = alloc(FrontendSource, convert(usize, count));
    var ok = inputs != null;
    ide_require(ok);
    i = 0;
    for(; i < convert(usize, count); i++) {
        inputs[i].data = ide_copy(sources[i], convert(usize, lengths[i]));
        inputs[i].length = convert(usize, lengths[i]);
    }
    var session = ide_execution_compile(inputs, convert(usize, count), width, false);
    i = 0;
    for(; i < convert(usize, count); i++) {
        free(inputs[i].data);
    }
    free(inputs);
    return ide_execution_publish(session);
}

export fn tw_exec_destroy(handle: u32): void {
    var state = ide_state();
    var session = bits(IdeExecution*, host_handles_take(&state.handles, 1, handle));
    if session != null {
        ide_execution_close(session);
    }
}

export fn tw_exec_fast(handle: u32): i32 {
    var session = ide_execution(handle);
    if session == null {
        return 0;
    }
    if ide_execution_fast(session) {
        return 1;
    }
    return 0;
}

export fn tw_exec_memory(handle: u32): u8* {
    var session = ide_execution(handle);
    if session == null {
        return null;
    }
    return session.machine.memory.data;
}

export fn tw_exec_memory_size(handle: u32): usize {
    var session = ide_execution(handle);
    if session == null {
        return 0;
    }
    return session.machine.memory.length;
}

export fn tw_exec_allocate(handle: u32, size: u32): u32 {
    var session = ide_execution(handle);
    if session == null {
        return 0;
    }
    return convert(u32, interpreter_allocate(&session.machine, convert(usize, size)));
}

export fn tw_exec_deallocate(handle: u32, address: u32): void {
    var session = ide_execution(handle);
    if session != null {
        interpreter_deallocate(&session.machine, convert(u64, address));
    }
}

export fn tw_exec_fail(handle: u32, error: u8*, length: usize): void {
    var session = ide_execution(handle);
    if session == null {
        return;
    }
    if session.error.length == 0 {
        ide_require(bytes_assign_text(&session.error, error, length));
        session.machine.failed = true;
        session.machine.error_offset = 0;
    }
}

export fn tw_exec_output(handle: u32, data: u8*, length: usize): void {
    var session = ide_execution(handle);
    if session == null {
        return;
    }
    var left = 65536 -session.machine.output_bytes;
    if length > left {
        session.machine.output_truncated = true;
        return;
    }
    ide_require(bytes_append(&session.output, data, length));
    session.machine.output_bytes = session.machine.output_bytes + length;
}

export fn tw_exec_step(handle: u32, budget: u32): u8* {
    var session = ide_execution(handle);
    if session == null {
        return "{\"status\":\"error\",\"error\":\"Invalid execution handle\"}";
    }
    if budget > 100000 {
        budget = 100000;
    }
    session.machine.failed = session.error.length != 0;
    var fast = session.fast != null;
    if fast {
        fast_interpreter_step(&session.machine, session.fast, convert(usize, budget));
    }
    else {
        interpreter_step(&session.machine, convert(usize, budget));
    }
    var state = ide_state();
    var out = &state.execution;
    ide_require(host_execution_json(out, session.error.data, session.error.length, session.machine.error_offset, session.machine.done, session.output.data, session.output.length, session.machine.steps, session.machine.output_truncated));
    session.output.length = 0;
    return ide_result(out);
}

export fn tw_exec_fast_stats(handle: u32): u8* {
    var session = ide_execution(handle);
    var missing = session == null;
    if missing {
        return "{}";
    }
    missing = session.fast == null;
    if missing {
        return "{}";
    }
    var state = ide_state();
    var out = &state.execution;
    ide_assign(out, "{");
    var names: u8*[5];
    names[0] = "codeBytes";
    names[1] = "instructions";
    names[2] = "wideInstructions";
    names[3] = "registerCapacityBytes";
    names[4] = "cacheCapacityBytes";
    for(var i: usize = 0; i < 5; i++) {
        ide_comma(out, i);
        ide_quote(out, names[i]);
        ide_text(out, ":");
        ide_number(out, fast_interpreter_stat(session.fast, i));
    }
    ide_text(out, "}");
    return ide_result(out);
}

export fn tw_set_foundation(source: u8*, bytes: usize): i32 {
    var bad = source == null;
    if bad {
        return 0;
    }
    bad = bytes > 131072;
    if bad {
        return 0;
    }
    var text = ide_copy(source, bytes);
    var error: SyntaxVersionDiagnostic = default;
    defer syntax_version_diagnostic_dispose(&error);
    syntax_host_install(compiler_host_world(), text, true, &error);
    free(text);
    var state = ide_state();
    var diagnostic = syntax_version_diagnostic_text(&error);
    ide_assign(&state.foundation_error, diagnostic);
    return 1;
}

// Interpreter callbacks bind the existing portable engines to this request's
// owner. Host invocation is the only transport-dependent execution operation.
extern fn tw_foreign_call(handle: u32, request: u8*): u64;

export fn im_pointer_bytes(machine: IMState*): usize {
    var session = bits(IdeExecution*, machine);
    return convert(usize, session.program.pointer_bytes);
}

export fn im_root(machine: IMState*): void* {
    var session = bits(IdeExecution*, machine);
    return session.program.root;
}

export fn im_has_foreign(machine: IMState*): bool {
    return true;
}

export fn im_fail(machine: IMState*, text: u8*, offset: usize): void {
    var session = bits(IdeExecution*, machine);
    if session.error.length == 0 {
        ide_assign(&session.error, text);
        machine.failed = true;
        machine.error_offset = offset;
    }
}

export fn im_missing_foreign(machine: IMState*, node: void*, offset: usize): void {
    var text: ByteBuffer = default;
    ide_text(&text, "No interpreter implementation registered for external function '");
    var function = sem_get(node);
    ide_require(bytes_append(&text, function.name.data, function.name.length));
    ide_text(&text, "'");
    im_fail(machine, ide_result(&text), offset);
    bytes_dispose(&text);
}

export fn im_append(machine: IMState*, text: u8*, count: usize): void {
    var session = bits(IdeExecution*, machine);
    ide_require(bytes_append(&session.output, text, count));
    machine.output_bytes = machine.output_bytes + count;
}

export fn im_foreign(machine: IMState*, node: void*, args: u64*, count: usize): u64 {
    var session = bits(IdeExecution*, machine);
    var function = sem_get(node);
    var request: ByteBuffer = default;
    ide_text(&request, "{\"name\":");
    ide_quote_bytes(&request, function.name.data, function.name.length);
    ide_field(&request, "pointerBytes", convert(usize, session.program.pointer_bytes));
    ide_text(&request, ",\"types\":[");
    var type: ByteBuffer = default;
    // Return bits cross the same transport as argument bits. Floating host
    // values require an explicit representation conversion at that boundary.
    var result_type: ByteBuffer = default;
    semantic_format_type(&function.type, bits(vector(u8)*, &result_type));
    var i: usize = 0;
    for(; i < function.parameters.length; i++) {
        var parameter = sem_get(function.parameters.data[i]);
        semantic_format_type(&parameter.type, bits(vector(u8)*, &type));
        ide_comma(&request, i);
        ide_quote_bytes(&request, type.data, type.length);
    }
    bytes_dispose(&type);
    ide_text(&request, "],\"args\":[");
    i = 0;
    for(; i < count; i++) {
        ide_comma(&request, i);
        ide_text(&request, "\"");
        ide_require(host_json_unsigned(&request, args[i]));
        ide_text(&request, "\"");
    }
    ide_text(&request, "],\"returnType\":");
    ide_quote_bytes(&request, result_type.data, result_type.length);
    bytes_dispose(&result_type);
    ide_text(&request, "}");
    var result = tw_foreign_call(session.handle, ide_result(&request));
    bytes_dispose(&request);
    machine.failed = session.error.length != 0;
    return result;
}

