    var literal_distances: u32 = 4;
    var distances_per_group: u32 = 2;
    var distance_width: u32 = 5;
    var base: u32 = 1;
    for (var code: u32 = 0; code < distance_codes; code++) {
        var extra: u32 = code < literal_distances ? 0 : code / distances_per_group - 1;
        var span: u32 = 1 << extra;
        if convert(u32, distance) < base + span {
            deflate_code(writer, code, distance_width);
            deflate_put(writer, convert(u32, distance) - base, extra);
            break;
        }
        base += span;
    }
}

fn deflate_hash(data: u8*): usize {
    var multiplier: usize = 251;
    return ((convert(usize, data[0]) * multiplier + convert(usize, data[1])) * multiplier
        + convert(usize, data[2])) & (DeflateHashBuckets - 1);
}

fn deflate_fixed(data: u8*, length: usize, limit: usize, out: ByteBuffer*): DeflateAttempt {
    var heads = alloc(usize, DeflateHashBuckets);
    if heads == null { return DeflateAttempt.AllocationFailure; }
    defer free(heads);
    var previous = alloc(usize, DeflateWindow);
    if previous == null { return DeflateAttempt.AllocationFailure; }
    defer free(previous);
    var absent = ~convert(usize, 0);
    for (var index: usize = 0; index < DeflateHashBuckets; index++) { heads[index] = absent; }
    for (var index: usize = 0; index < DeflateWindow; index++) { previous[index] = absent; }
    var writer: DeflateBits = { limit: limit, ok: true, ..default };
    defer bytes_dispose(&writer.output);
    var fixed_final: u32 = 3;
    var block_header_bits: u32 = 3;
    deflate_put(&writer, fixed_final, block_header_bits);
    var position: usize = 0;
    while position < length && writer.ok && !writer.larger {
        var matched: usize = 0;
        var distance: usize = 0;
        if length - position >= DeflateMinimumMatch {
            var candidate = heads[deflate_hash(data + position)];
            var maximum = length - position;
            if maximum > DeflateMaximumMatch { maximum = DeflateMaximumMatch; }
            var attempts: usize = 0;
            while candidate != absent && candidate < position && position - candidate <= DeflateWindow
                && attempts < DeflateSearchLimit {
                var count: usize = 0;
                while count < maximum && data[candidate + count] == data[position + count] { count++; }
                if count > matched && count >= DeflateMinimumMatch {
                    matched = count;
                    distance = position - candidate;
                    if count == maximum { break; }
                }
                var next = previous[candidate & (DeflateWindow - 1)];
                if next >= candidate { break; }
                candidate = next;
                attempts++;
            }
        }
        var advance: usize = 1;
        if matched >= DeflateMinimumMatch {
            deflate_match(&writer, matched, distance);
            advance = matched;
        } else { deflate_symbol(&writer, convert(u32, data[position])); }
        // Index all consumed starts, including positions inside an emitted match.
        // Each ring link holds an absolute input offset; stale/future links stop
        // traversal and cannot create a cycle after the window wraps.
        for (var step: usize = 0; step < advance; step++) {
            var at = position + step;
            if length - at < DeflateMinimumMatch { break; }
            var hash = deflate_hash(data + at);
            previous[at & (DeflateWindow - 1)] = heads[hash];
            heads[hash] = at;
        }
        position += advance;
    }
    deflate_symbol(&writer, DeflateEndCode);
    if writer.ok && !writer.larger && writer.count != 0 { deflate_put(&writer, 0, DeflateByteBits - writer.count); }
    if !writer.ok { return DeflateAttempt.AllocationFailure; }
    if writer.larger { return DeflateAttempt.Larger; }
    bytes_dispose(out);
    *out = writer.output;
    writer.output = default;
    return DeflateAttempt.Ok;
}

fn deflate_short(out: ByteBuffer*, value: u32): bool {
    var byte_mask = convert(u32, ~convert(u8, 0));
    return bytes_push(out, convert(u8, value & byte_mask))
        && bytes_push(out, convert(u8, (value >> DeflateByteBits) & byte_mask));
}

fn deflate_stored(data: u8*, length: usize, out: ByteBuffer*): bool {
    var position: usize = 0;
    loop {
        var count = length - position;
        if count > DeflateStoredLimit { count = DeflateStoredLimit; }
        var final_block = count == length - position;
        var final_bit: u8 = final_block ? 1 : 0;
        if !bytes_push(out, final_bit) || !deflate_short(out, convert(u32, count))
            || !deflate_short(out, ~convert(u32, count)) || !bytes_append(out, data + position, count) { return false; }
        position += count;
        if final_block { return true; }
    }
}

// Complete immutable byte input; output publication is atomic and can replace a
// buffer borrowed by input. Deterministic nearest-match tie breaking and fixed
// limits are compression policy, not format/language limits. Expansion is at
// most five bytes per stored block (including one block for an empty input).
fn deflate_compress(data: u8*, length: usize, out: ByteBuffer*): bool {
    if length != 0 && data == null { return false; }
    var blocks: usize = length == 0 ? 1 : (length - 1) / DeflateStoredLimit + 1;
    if blocks > (~convert(usize, 0) - length) / DeflateStoredOverhead { return false; }
    var stored_size = length + blocks * DeflateStoredOverhead;
    var next: ByteBuffer = default;
    defer bytes_dispose(&next);
    var result = deflate_fixed(data, length, stored_size, &next);
    if result == DeflateAttempt.AllocationFailure { return false; }
    if result == DeflateAttempt.Larger && !deflate_stored(data, length, &next) { return false; }
    bytes_dispose(out);
    *out = next;
    next = default;
    return true;
}

import tower;
import entity_types;

var EntityComponentPageBytes: usize = 16384;
var EntityComponentPageRows: usize = 64;

// The owning Tower program supplies its lifecycle dispatch; zero means none.
// IDs belong to that program, not to a process-wide native callback registry.
extern fn tower_entity_finalize(lifecycle: usize, component: EntityComponent*, data: u8*): void;

export fn entity_store_create(): EntityStore* {
    var store = alloc(EntityStore, 1);
    if store != null {
        *store = default;
    }
    return store;
}

export fn entity_store_set_context(store: EntityStore*, context: void*): bool {
    if store.entity_count != 0 || store.views != 0 || store.context != null { return false; }
    store.context = context;
    return true;
}

export fn entity_context(node: Entity*): void* {
    if node == null { return null; }
    return node.store.context;
}

// The store is borrowed by its entities and cannot be disposed while any live.
export fn entity_store_dispose(store: EntityStore*): bool {
    var occupied = store.entity_count != 0;
    occupied ||= store.views != 0;
    occupied ||= store.storage.first != null;
    if occupied {
        return false;
    }
    free(store);
    return true;
}

export fn entity_create(store: EntityStore*): Entity* {
    if store.views != 0 {
        return null;
    }
    var next = store.next_id + 1;
    if next == 0 {
        return null;
    }
    var entity = alloc(Entity, 1);
    if entity == null {
        return null;
    }
    *entity = default;
    entity.store = store;
    entity.id = store.next_id;
    entity.references = 1;
    store.next_id = next;
    store.entity_count++;
    return entity;
}

export fn entity_retain(entity: Entity*): usize {
    if entity.stage != null { return 0; }
    entity.references++;
    return entity.references;
}

// Allocate an unattached entity in an existing entity's store.
export fn entity_create_related(entity: Entity*): Entity* {
    return entity_create(entity.store);
}

// Ownership must be acyclic. Query cursors are invalidated by structural edits.
export fn entity_release(entity: Entity*): usize {
    if entity.stage != null { return 0; }
    entity.references--;
    var remaining = entity.references;
    if remaining != 0 {
        return remaining;
    }
    var pinned = entity.store.views != 0;
    pinned ||= entity.queued;
    if pinned {
        if !entity.queued {
            entity.deferred = entity.store.deferred;
            entity.store.deferred = entity;
            entity.queued = true;
        }
    } else {
        entity_reclaim(entity);
    }
    return 0;
}

fn entity_reclaim(entity: Entity*): void {
    var store = entity.store;
    store.reclaiming++;
    entity_table_remove_row(entity);
    var i: usize = 0;
    for(; i != entity.child_count; i++) {
        var child = entity.children[i].entity;
        child.parent = null;
        free(entity.children[i].name);
        entity_release(child);
    }
    i = 0;
    for(; i != entity.component_count; i++) {
        entity_component_dispose(entity.components[i]);
    }
    free(entity.children);
    free(entity.components);
    free(entity.instances);
    store.entity_count--;
    free(entity);
    store.reclaiming--;
}

// Opening a view is an owning operation on the store's lifetime. The anchor
// need not be the root; every type index in this same store becomes stable.
// Close exactly once, after all borrowed queries/workers finish.
export fn entity_view_open(anchor: Entity*): EntityView* {
    var missing = anchor == null;
    if missing {
        return null;
    }
    if anchor.stage != null { return null; }
    var store = anchor.store;
    var reclaiming = store.reclaiming != 0;
    if reclaiming {
        return null;
    }
    var next = store.views + 1;
    if next == 0 {
        return null;
    }
    var view = alloc(EntityView, 1);
    missing = view == null;
    if missing {
        return null;
    }
    view.store = store;
    view.queries = null;
    store.views = next;
    return view;
}

export fn entity_view_close(view: EntityView*): void {
    var store = view.store;
    while view.queries != null {
        var query = view.queries;
        view.queries = query.next;
        entity_table_query_dispose(query);
    }
    free(view);
    store.views--;
    if store.views != 0 {
        return;
    }
    while store.deferred != null {
        var entity = store.deferred;
        store.deferred = entity.deferred;
        entity.deferred = null;
        entity.queued = false;
        if entity.references == 0 {
            entity_reclaim(entity);
        }
    }
}

// A borrowed dense pointer range over the authoritative stable payloads.
// Empty/end batches succeed, invalid/cross-world ranges preserve the output.
export fn entity_view_query(view: EntityView*, type: Entity*, first: usize, count: usize, result: EntityQuery*): bool {
    var invalid = type.store != view.store;
    if invalid {
        return false;
    }
    invalid = first > type.instance_count;
    if invalid {
        return false;
    }
    var remaining = type.instance_count -first;
    invalid = count > remaining;
    if invalid {
        return false;
    }
    var data: EntityComponent** = null;
    if count != 0 {
        data = type.instances + first;
    }
    result.data = data;
    result.length = count;
    return true;
}

// Component types are ordinary entities with a consistent layout/lifecycle.
export fn entity_register(type: Entity*, size: usize, alignment: usize, lifecycle: usize): bool {
    if type.stage != null { return false; }
    var zero = alignment == 0;
    if zero {
        return false;
    }
    var mask = alignment -1;
    var bits = alignment &mask;
    if bits != 0 {
        return false;
    }
    if type.registered {
        var same = type.data_size == size;
        same &&= type.data_alignment == alignment;
        same &&= type.lifecycle == lifecycle;
        return same;
    }
    if type.store.views != 0 {
        return false;
    }
    type.data_size = size;
    type.data_alignment = alignment;
    type.lifecycle = lifecycle;
    type.registered = true;
    return true;
}

// Published membership only. This never reads a worker's mutable private
// component list. Borrow under a view across dispatch; payload access still
// requires the scheduler's declared permissions.
export fn entity_component_published(owner: Entity*, type: Entity*): EntityComponent* {
    if type == null || type.store != owner.store || type.stage != null { return null; }
    var table = owner.table;
    if table == null { return null; }
    var column = entity_table_column(table, type.id);
    if column == table.arity { return null; }
    return table.columns[column * table.capacity + owner.table_row];
}

export fn entity_component_get(owner: Entity*, type: Entity*): EntityComponent* {
    var published = entity_component_published(owner, type);
    if published != null || (owner.stage == null && owner.table != null) { return published; }
    // A stage can see its own additions before publication. Reclamation removes
    // the row before invoking finalizers; keep their existing local lookup path.
    var i: usize = 0;
    loop {
        if i == owner.component_count {
            return null;
        }
        var component = owner.components[i];
        if component.type == type {
            return component;
        }
        i++;
    }
}

// Reserve helpers keep indexes separate from component payloads.
fn entity_reserve_components(data: EntityComponent***, capacity: usize*, count: usize): bool {
    if count < *capacity {
        return true;
    }
    var next = *capacity *2;
    if next < *capacity {
        return false;
    }
    if next < 4 {
        next = 4;
    }
    var memory = realloc(EntityComponent*, *data, next);
    if memory == null {
        return false;
    }
    *data = memory;
    *capacity = next;
    return true;
}

fn entity_component_page_detach(page: EntityComponentPage*): void {
    if page.pool == null { return; }
    if page.previous != null { page.previous.next = page.next; }
    else { page.pool.first = page.next; }
    if page.next != null { page.next.previous = page.previous; }
    page.pool = null;
    page.previous = null;
    page.next = null;
}

// After publication every page remains owned by its live components. No pointer
// to a destroyed stage's allocation pool may survive that boundary.
fn entity_component_pool_detach(pool: EntityComponentPool*): void {
    while pool.first != null { entity_component_page_detach(pool.first); }
}

fn entity_component_allocate(owner: Entity*, type: Entity*): EntityComponent* {
    var alignment = type.data_alignment;
    var pointer_size = sizeof(EntityComponent*);
    if alignment < pointer_size { alignment = pointer_size; }
    var mask = alignment - 1;
    var maximum = ~convert(usize, 0);
    if type.data_size > maximum - pointer_size { return null; }
    var bytes = type.data_size + pointer_size;
    if bytes > maximum - mask { return null; }
    var stride = (bytes + mask) & ~mask;
    if stride > maximum - sizeof(EntityComponent) { return null; }
    var slot = stride + sizeof(EntityComponent);
    var capacity = EntityComponentPageBytes / slot;
    if capacity > EntityComponentPageRows { capacity = EntityComponentPageRows; }
    var component: EntityComponent* = null;
    var data: u8* = null;
    if capacity >= 2 {
        var pool = owner.storage;
        if owner.stage != null && pool == null { return null; }
        if pool == null { pool = &owner.store.storage; }
        var page = pool.first;
        while page != null && page.type_id != type.id { page = page.next; }
        if page == null {
            // capacity*slot is bounded by the page byte policy. Header/alignment
            // overhead is also bounded here because at least two slots fit.
            bytes = sizeof(EntityComponentPage) + capacity * slot + pointer_size + mask;
            var allocation = alloc(u8, bytes);
            if allocation == null { return null; }
            page = bits(EntityComponentPage*, allocation);
            fill(page, 0, sizeof(EntityComponentPage));
            page.pool = pool;
            page.type_id = type.id;
            page.capacity = capacity;
            page.stride = stride;
            page.components = bits(EntityComponent*, allocation + sizeof(EntityComponentPage));
            var start = bits(usize, page.components + capacity) + pointer_size;
            page.data = bits(u8*, (start + mask) & ~mask);
            page.next = pool.first;
            if pool.first != null { pool.first.previous = page; }
            pool.first = page;
        }
        component = &page.components[page.used];
        data = page.data + page.used * page.stride;
        component.allocation = bits(u8*, page);
        component.page = page;
        page.used++;
        page.live++;
        if page.used == page.capacity { entity_component_page_detach(page); }
    } else {
        // Large or highly aligned payloads preserve the individually allocated
        // path; never reserve multiple large objects just to fill a page.
        if bytes + mask > maximum - sizeof(EntityComponent) { return null; }
        var allocation = alloc(u8, bytes + mask + sizeof(EntityComponent));
        if allocation == null { return null; }
        component = bits(EntityComponent*, allocation);
        var start = bits(usize, allocation + sizeof(EntityComponent)) + pointer_size;
        data = bits(u8*, (start + mask) & ~mask);
        component.allocation = allocation;
        component.page = null;
    }
    var back = bits(EntityComponent**, data);
    back--;
    *back = component;
    component.owner = owner;
    component.type = type;
    component.data = data;
    return component;
}

// Called only by the coordinator, or when discarding a joined private stage.
// Active partial pages unlink before their last component frees the allocation.
fn entity_component_free(component: EntityComponent*): void {
    var page = component.page;
    if page == null { free(component.allocation); return; }
    page.live--;
    if page.live == 0 {
        entity_component_page_detach(page);
        free(page);
    }
}

export fn entity_component_add(owner: Entity*, type: Entity*): EntityComponent* {
    var present = entity_component_get(owner, type);
    if present != null {
        return present;
    }
    var staged = owner.stage != null;
    var pinned = owner.store.views != 0 && !staged;
    if pinned {
        return null;
    }
    if owner.store != type.store {
        return null;
    }
    var unregistered = !type.registered || type.stage != null;
    if unregistered {
        return null;
    }
    var ok = entity_reserve_components(&owner.components, &owner.component_capacity, owner.component_count);
    if !staged {
        ok &&= entity_reserve_components(&type.instances, &type.instance_capacity, type.instance_count);
    }
    var reserve_failed = !ok;
    if reserve_failed {
        return null;
    }
    var component = entity_component_allocate(owner, type);
    if component == null { return null; }
    if !staged && !entity_table_prepare(owner, type, null) {
        entity_component_free(component);
        return null;
    }
    component.type_index = type.instance_count;
    if staged { component.type_index = ~convert(usize, 0); }
    owner.components[owner.component_count] = component;
    owner.component_count++;
    if !staged {
        type.instances[type.instance_count] = component;
        type.instance_count++;
        entity_retain(type);
        owner.store.component_count++;
        entity_table_publish(owner);
    }
    return component;
}

fn entity_component_dispose(component: EntityComponent*): void {
    var type = component.type;
    type.instance_count--;
    var last = type.instances[type.instance_count];
    type.instances[component.type_index] = last;
    last.type_index = component.type_index;
    if type.lifecycle != 0 {
        tower_entity_finalize(type.lifecycle, component, component.data);
    }
    var store = type.store;
    store.component_count--;
    entity_component_free(component);
    entity_release(type);
}

export fn entity_component_remove(owner: Entity*, type: Entity*): bool {
    if owner.stage != null { return false; }
    var pinned = owner.store.views != 0;
    if pinned {
        return false;
    }
    var i: usize = 0;
    loop {
        if i == owner.component_count {
            return false;
        }
        var component = owner.components[i];
        if component.type == type {
            if !entity_table_prepare(owner, null, type) { return false; }
            owner.component_count--;
            var following = i + 1;
            var count = owner.component_count -i;
            var bytes = count *sizeof(EntityComponent*);
            copy(&owner.components[i], &owner.components[following], bytes);
            entity_table_publish(owner);
            entity_component_dispose(component);
            return true;
        }
        i++;
    }
}

export fn entity_component_data(component: EntityComponent*): u8* {
    if component == null {
        return null;
    }
    return component.data;
}

export fn entity_component_from_data(data: u8*): EntityComponent* {
    if data == null {
        return null;
    }
    var back = bits(EntityComponent **, data);
    back--;
    return *back;
}

export fn entity_query_count(type: Entity*): usize {
    return type.instance_count;
}

export fn entity_query_at(type: Entity*, index: usize): EntityComponent* {
    if index >= type.instance_count {
        return null;
    }
    return type.instances[index];
}

fn entity_name_equal(left: u8*, right: u8*): bool {
    var missing = left == null;
    if missing {
        var both_missing = right == null;
        return both_missing;
    }
    missing = right == null;
    if missing {
        return false;
    }
    var i: usize = 0;
    loop {
        if left[i] != right[i] {
            return false;
        }
        if left[i] == 0 {
            return true;
        }
        i++;
    }
}

export fn entity_child_index(parent: Entity*, child: Entity*): usize {
    var i: usize = 0;
    loop {
        if i == parent.child_count {
            var invalid: usize = 0;
            invalid--;
            return invalid;
        }
        if parent.children[i].entity == child {
            return i;
        }
        i++;
    }
}

export fn entity_member_index(parent: Entity*, name: u8*): usize {
    var i: usize = 0;
    loop {
        if i == parent.child_count {
            var invalid: usize = 0;
            invalid--;
            return invalid;
        }
        if entity_name_equal(parent.children[i].name, name) {
            return i;
        }
        i++;
    }
}

fn entity_unlink(child: Entity*): void {
    var parent = child.parent;
    var index = entity_child_index(parent, child);
    free(parent.children[index].name);
    parent.child_count--;
    var following = index + 1;
    var count = parent.child_count -index;
    var bytes = count *sizeof(EntityChild);
    copy(&parent.children[index], &parent.children[following], bytes);
    child.parent = null;
}

// Ordered, named containment owns children. Other semantic links remain borrowed.
// Reserve/copy before changing ownership; a failed allocation leaves links intact.
export fn entity_attach(child: Entity*, parent: Entity*, name: u8*): bool {
    if child.stage != null || (parent != null && parent.stage != null) { return false; }
    var pinned = child.store.views != 0;
    if pinned {
        return false;
    }
    if child == parent {
        return false;
    }
    var named: u8* = null;
    var attaching = parent != null;
    if attaching {
        if parent.store != child.store {
            return false;
        }
        if parent.child_count == parent.child_capacity {
            var capacity = parent.child_capacity *2;
            if capacity < parent.child_capacity {
                return false;
            }
            if capacity < 4 {
                capacity = 4;
            }
            var next = realloc(EntityChild, parent.children, capacity);
            var failed = next == null;
            if failed {
                return false;
            }
            parent.children = next;
            parent.child_capacity = capacity;
        }
        var has_name = name != null;
        has_name &&= *name != 0;
        if has_name {
            var length: usize = 0;
            for(; !(name[length] == 0); length++) {}
            length++;
            named = alloc(u8, length);
            var failed = named == null;
            if failed {
                return false;
            }
            copy(named, name, length);
        }
    }
    var attached = child.parent != null;
    if attached {
        // Transfer the old parent's reference directly to the new relationship.
        entity_unlink(child);
    } else {
        if attaching {
            entity_retain(child);
        }
    }
    if attaching {
        var has_name = named != null;
        if has_name {
            var previous = entity_member_index(parent, named);
            if previous < parent.child_count {
                var replaced = parent.children[previous].entity;
                entity_unlink(replaced);
                entity_release(replaced);
            }
        }
        parent.children[parent.child_count].entity = child;
        parent.children[parent.child_count].name = named;
        parent.child_count++;
        child.parent = parent;
    } else {
        if attached {
            entity_release(child);
        }
    }
    return true;
}

export fn entity_replace_child(parent: Entity*, index: usize, replacement: Entity*): bool {
    if parent.stage != null || (replacement != null && replacement.stage != null) { return false; }
    var pinned = parent.store.views != 0;
    if pinned {
        return false;
    }
    var invalid = index >= parent.child_count;
    if invalid {
        return false;
    }
    invalid = replacement.parent != null;
    if invalid {
        return false;
    }
    invalid = replacement == parent;
    if invalid {
        return false;
    }
    invalid = replacement.store != parent.store;
    if invalid {
        return false;
    }
    var previous = parent.children[index].entity;
    entity_retain(replacement);
    replacement.parent = parent;
    parent.children[index].entity = replacement;
    previous.parent = null;
    entity_release(previous);
    return true;
}

export fn entity_take_last_child(parent: Entity*): Entity* {
    if parent.stage != null { return null; }
    var pinned = parent.store.views != 0;
    if pinned {
        return null;
    }
    if parent.child_count == 0 {
        return null;
    }
    parent.child_count--;
    var child = parent.children[parent.child_count].entity;
    free(parent.children[parent.child_count].name);
    child.parent = null;
    return child;
}

