// Derived archetype membership. Columns point at stable canonical components;
// they do not copy payloads or introduce another semantic graph. Only published
// membership is indexed, and all table mutation happens without pinned views.
fn entity_table_column(table: EntityTable*, id: usize): usize {
    var low: usize = 0;
    var high = table.arity;
    while low < high {
        var middle = low + (high - low) / 2;
        if table.types[middle] < id { low = middle + 1; }
        else { high = middle; }
    }
    if low < table.arity && table.types[low] == id { return low; }
    return table.arity;
}

fn entity_table_hash(id: usize): usize {
    id ^= id >> 16;
    id *= 73244475;
    id ^= id >> 16;
    return id;
}

fn entity_table_prune(table: EntityTable*): void {
    if table == null || table.length != 0 || table.pending != 0 { return; }
    var store = table.store;
    var bucket = table.hash & 255;
    var link = &store.tables[bucket];
    while *link != table { link = &(*link).next; }
    *link = table.next;
    free(table.rows);
    free(table.types);
    free(table);
}

fn entity_table_reserve(table: EntityTable*, count: usize): bool {
    if count <= table.capacity { return true; }
    var maximum = ~convert(usize, 0);
    if table.arity == maximum { return false; }
    var columns = table.arity + 1;
    if columns > maximum / sizeof(void*) { return false; }
    var stride = columns * sizeof(void*);
    if count > maximum / stride { return false; }
    var capacity = table.capacity;
    if capacity < 4 { capacity = 4; }
    while capacity < count {
        if capacity > maximum / 2 { capacity = count; break; }
        capacity *= 2;
    }
    if capacity > maximum / stride { capacity = count; }
    var memory = alloc(u8, capacity * stride);
    if memory == null { return false; }
    var rows = bits(Entity**, memory);
    var data = bits(EntityComponent**, rows + capacity);
    if table.length != 0 {
        copy(rows, table.rows, table.length * sizeof(Entity*));
        for(var i: usize = 0; i < table.arity; i++) {
            copy(data + i * capacity, table.columns + i * table.capacity,
                table.length * sizeof(EntityComponent*));
        }
    }
    free(table.rows);
    table.rows = rows;
    table.columns = data;
    table.capacity = capacity;
    return true;
}

fn entity_table_matches(table: EntityTable*, owner: Entity*, added: Entity*, removed: Entity*): bool {
    if added != null && entity_table_column(table, added.id) == table.arity { return false; }
    for(var i: usize = 0; i < owner.component_count; i++) {
        var type = owner.components[i].type;
        if type != removed && entity_table_column(table, type.id) == table.arity { return false; }
    }
    return true;
}

// Reserve a destination without changing published rows or canonical membership.
// Pending reservations protect empty destination tables throughout a stage batch.
fn entity_table_prepare(owner: Entity*, added: Entity*, removed: Entity*): bool {
    var count = owner.component_count;
    if added != null { count++; }
    if removed != null { count--; }
    if count == 0 { owner.pending_table = null; return true; }
    if count > ~convert(usize, 0) / sizeof(usize) { return false; }
    var hash: usize = 0;
    for(var i: usize = 0; i < owner.component_count; i++) {
        var type = owner.components[i].type;
        if type != removed { hash += entity_table_hash(type.id); }
    }
    if added != null { hash += entity_table_hash(added.id); }
    var store = owner.store;
    var bucket = hash & 255;
    var table = store.tables[bucket];
    while table != null {
        if table.hash == hash && table.arity == count && entity_table_matches(table, owner, added, removed) { break; }
        table = table.next;
    }
    if table == null {
        table = alloc(EntityTable, 1);
        if table == null { return false; }
        *table = default;
        table.types = alloc(usize, count);
        if table.types == null { free(table); return false; }
        table.store = store;
        table.hash = hash;
        table.arity = count;
        var next: usize = 0;
        for(var i: usize = 0; i < owner.component_count; i++) {
            var type = owner.components[i].type;
            if type != removed { table.types[next++] = type.id; }
        }
        if added != null { table.types[next] = added.id; }
        for(var i: usize = 1; i < count; i++) {
            var id = table.types[i];
            var j = i;
            while j != 0 && table.types[j - 1] > id {
                table.types[j] = table.types[j - 1];
                j--;
            }
            table.types[j] = id;
        }
        table.next = store.tables[bucket];
        store.tables[bucket] = table;
    }
    var maximum = ~convert(usize, 0);
    if table.pending == maximum || table.length > maximum - table.pending - 1
        || !entity_table_reserve(table, table.length + table.pending + 1) {
        entity_table_prune(table);
        return false;
    }
    table.pending++;
    owner.pending_table = table;
    return true;
}

fn entity_table_unprepare(owner: Entity*): void {
    var table = owner.pending_table;
    owner.pending_table = null;
    if table != null { table.pending--; entity_table_prune(table); }
}

fn entity_table_remove_row(owner: Entity*): void {
    var table = owner.table;
    if table == null { return; }
    table.length--;
    var row = owner.table_row;
    if row != table.length {
        var moved = table.rows[table.length];
        table.rows[row] = moved;
        moved.table_row = row;
        for(var i: usize = 0; i < table.arity; i++) {
            var column = table.columns + i * table.capacity;
            column[row] = column[table.length];
        }
    }
    owner.table = null;
    owner.table_row = 0;
    entity_table_prune(table);
}

// Membership is committed only after every allocation succeeds. Empty entities
// have no table; nonempty entities have exactly one full component signature.
fn entity_table_publish(owner: Entity*): void {
    var table = owner.pending_table;
    if table == owner.table { entity_table_unprepare(owner); return; }
    entity_table_remove_row(owner);
    owner.pending_table = null;
    if table == null { return; }
    table.pending--;
    owner.table = table;
    owner.table_row = table.length;
    table.rows[table.length] = owner;
    for(var i: usize = 0; i < owner.component_count; i++) {
        var component = owner.components[i];
        var column = entity_table_column(table, component.type.id);
        table.columns[column * table.capacity + table.length] = component;
    }
    table.length++;
}
// Query plans are immutable once returned and cached only inside their owning
// pin. Closing the view releases every plan, so structural edits cannot leave
// dangling cached table pointers. The coordinator builds plans before dispatch.
fn entity_table_query_matches(table: EntityTable*, terms: Entity**, count: usize): bool {
    for(var i: usize = 0; i < count; i++) {
        if entity_table_column(table, terms[i].id) == table.arity { return false; }
    }
    return true;
}

fn entity_table_query_dispose(query: EntityTableQuery*): void {
    free(query.types);
    free(query.matches);
    free(query.columns);
    free(query);
}

export fn entity_view_tables(view: EntityView*, terms: Entity**, count: usize): EntityTableQuery* {
    if count == 0 || count > ~convert(usize, 0) / sizeof(usize) || terms == null { return null; }
    for(var i: usize = 0; i < count; i++) {
        var type = terms[i];
        if type == null || type.store != view.store || !type.registered || type.stage != null { return null; }
        for(var j: usize = 0; j < i; j++) { if terms[j] == type { return null; } }
    }
    var query = view.queries;
    while query != null {
        var same = query.arity == count;
        for(var i: usize = 0; same && i < count; i++) { same = query.types[i] == terms[i].id; }
        if same { return query; }
        query = query.next;
    }
    query = alloc(EntityTableQuery, 1);
    if query == null { return null; }
    *query = default;
    query.arity = count;
    query.types = alloc(usize, count);
    if query.types == null { entity_table_query_dispose(query); return null; }
    for(var i: usize = 0; i < count; i++) { query.types[i] = terms[i].id; }
    var maximum = ~convert(usize, 0);
    for(var bucket: usize = 0; bucket < 256; bucket++) {
        var table = view.store.tables[bucket];
        while table != null {
            if table.length != 0 && entity_table_query_matches(table, terms, count) {
                if query.length > maximum - table.length || query.count == maximum {
                    entity_table_query_dispose(query); return null;
                }
                query.length += table.length;
                query.count++;
            }
            table = table.next;
        }
    }
    if query.count != 0 {
        if query.count > maximum / count / sizeof(usize) || query.count > maximum / sizeof(EntityTableMatch) {
            entity_table_query_dispose(query); return null;
        }
        query.matches = alloc(EntityTableMatch, query.count);
        query.columns = alloc(usize, query.count * count);
        if query.matches == null || query.columns == null { entity_table_query_dispose(query); return null; }
    }
    var next: usize = 0;
    var first: usize = 0;
    for(var bucket: usize = 0; bucket < 256; bucket++) {
        var table = view.store.tables[bucket];
        while table != null {
            if table.length != 0 && entity_table_query_matches(table, terms, count) {
                var entry = &query.matches[next];
                entry.table = table;
                entry.first = first;
                entry.columns = query.columns + next * count;
                for(var i: usize = 0; i < count; i++) { entry.columns[i] = entity_table_column(table, terms[i].id); }
                first += table.length;
                next++;
            }
            table = table.next;
        }
    }
    query.next = view.queries;
    view.queries = query;
    return query;
}

export fn entity_table_query_count(query: EntityTableQuery*): usize { return query.length; }
export fn entity_table_query_ranges(query: EntityTableQuery*): usize { return query.count; }

export fn entity_table_query_range(query: EntityTableQuery*, index: usize, first: usize, count: usize,
    result: EntityTableRange*): bool {
    if index >= query.count { return false; }
    var entry = &query.matches[index];
    if first > entry.table.length || count > entry.table.length - first { return false; }
    result.table = entry.table;
    result.columns = entry.columns;
    result.arity = query.arity;
    result.first = first;
    result.length = count;
    return true;
}

export fn entity_table_range_column(range: EntityTableRange*, term: usize): EntityComponent** {
    if term >= range.arity || range.length == 0 { return null; }
    return range.table.columns + range.columns[term] * range.table.capacity + range.first;
}

export fn entity_table_range_rows(range: EntityTableRange*): Entity** {
    if range.length == 0 { return null; }
    return range.table.rows + range.first;
}

export fn entity_table_query_component(query: EntityTableQuery*, row: usize, term: usize): EntityComponent* {
    if row >= query.length || term >= query.arity { return null; }
    var low: usize = 0;
    var high = query.count;
    while low + 1 < high {
        var middle = low + (high - low) / 2;
        if query.matches[middle].first <= row { low = middle; }
        else { high = middle; }
    }
    var entry = &query.matches[low];
    return entry.table.columns[entry.columns[term] * entry.table.capacity + row - entry.first];
}

export fn entity_table_query_range_count(query: EntityTableQuery*, index: usize): usize {
    if index >= query.count { return 0; }
    return query.matches[index].table.length;
}

export fn entity_table_query_column(query: EntityTableQuery*, index: usize, term: usize): EntityComponent** {
    if index >= query.count || term >= query.arity { return null; }
    var entry = &query.matches[index];
    return entry.table.columns + entry.columns[term] * entry.table.capacity;
}

import tower;
import entity_types;

// Typed declarations for separately compiled clients of the shared Tower ECS.
// The owning program links entities.tower once; this file owns no implementation.
extern fn entity_store_create(): EntityStore*;
extern fn entity_store_set_context(store: EntityStore*, context: void*): bool;
extern fn entity_store_dispose(store: EntityStore*): bool;
extern fn entity_create(store: EntityStore*): Entity*;
extern fn entity_release(entity: Entity*): usize;
extern fn entity_register(type: Entity*, size: usize, alignment: usize, lifecycle: usize): bool;
extern fn entity_component_add(owner: Entity*, type: Entity*): EntityComponent*;
extern fn entity_component_get(owner: Entity*, type: Entity*): EntityComponent*;
extern fn entity_component_data(component: EntityComponent*): u8*;
extern fn entity_member_index(parent: Entity*, name: u8*): usize;
extern fn entity_child_at(entity: Entity*, index: usize): Entity*;
extern fn entity_attach(child: Entity*, parent: Entity*, name: u8*): bool;
extern fn entity_view_open(anchor: Entity*): EntityView*;
extern fn entity_view_close(view: EntityView*): void;

import tower;
import entities;
import entity_types;
import vector;

// A worker owns these actual canonical entities, not a shadow graph or commands
// containing another node model. Existing parent links and dense type indexes
// remain unchanged until the coordinator publishes after all readers join.
struct EntityStage {
    anchor: Entity*;
    nodes: vector(EntityStageNode);
    references: vector(Entity*);
    held: usize;
    leases: vector(EntityStageLease);
    storage: EntityComponentPool;
}

struct EntityStageNode {
    node: Entity*;
    name: u8*;
}

struct EntityStageLease {
    node: Entity*;
    components: usize;
}

struct EntityStageCount {
    entity: Entity*;
    children: usize;
    instances: usize;
}

fn entity_stage_init(stage: EntityStage*, anchor: Entity*): bool {
    *stage = default;
    if anchor == null || anchor.stage != null { return false; }
    stage.anchor = anchor;
    entity_retain(anchor);
    return true;
}

export fn entity_stage_open(anchor: Entity*): EntityStage* {
    var stage = alloc(EntityStage, 1);
    if stage == null { return null; }
    if !entity_stage_init(stage, anchor) { free(stage); return null; }
    return stage;
}

// Coordinator-only, before pinning. The scheduler must own exclusive access to
// this entity's component list and writable payloads for the entire lease. Its
// existing identity/containment/type indexes remain published and stable. New
// attachments are visible through this owner's lookup only, not typed queries.
export fn entity_stage_lease(stage: EntityStage*, node: Entity*): bool {
    if stage.anchor == null || node == null || node.store != stage.anchor.store
        || node.store.views != 0 || node.registered { return false; }
    if node.stage == bits(void*, stage) { return true; }
    if node.stage != null { return false; }
    if !vector_reserve(EntityStageLease, &stage.leases, stage.leases.length + 1) { return false; }
    var lease = &stage.leases.data[stage.leases.length];
    lease.node = node;
    lease.components = node.component_count;
    stage.leases.length++;
    node.stage = bits(void*, stage);
    node.storage = &stage.storage;
    return true;
}

// Only the owning worker calls create/component_add on its staged nodes.
// No retain/release/attach/register/remove is permitted until publication.
// Queue payload-owned shared references with entity_stage_references instead.
export fn entity_stage_create(stage: EntityStage*, parent: Entity*): Entity* {
    if stage.anchor == null || parent == null || parent.store != stage.anchor.store { return null; }
    if parent.stage != null && parent.stage != bits(void*, stage) { return null; }
    if !vector_reserve(EntityStageNode, &stage.nodes, stage.nodes.length + 1) { return null; }
    var node = alloc(Entity, 1);
    if node == null { return null; }
    *node = default;
    node.store = parent.store;
    node.references = 1;
    node.parent = parent; // Borrowed for provenance, not yet parent containment.
    node.stage = bits(void*, stage);
    node.storage = &stage.storage;
    stage.nodes.data[stage.nodes.length].node = node;
    stage.nodes.data[stage.nodes.length].name = null;
    stage.nodes.length++;
    return node;
}

fn entity_stage_count(counts: vector(EntityStageCount)*, node: Entity*): EntityStageCount* {
    var hash = bits(usize, node) / 16;
    hash ^= hash >> 16;
    var mask = counts.length - 1;
    var index = hash & mask;
    while counts.data[index].entity != null && counts.data[index].entity != node {
        index = (index + 1) & mask;
    }
    counts.data[index].entity = node;
    return &counts.data[index];
}

// Failure in preparation leaves all semantic identities/links/index lengths
// unchanged. Capacity may grow, so publication requires an unpinned store even
// when preparation fails. No fallible allocation remains after preparation.
fn entity_stage_prepare(stage: EntityStage*): bool {
    var store = stage.anchor.store;
    if store.views != 0 || !entity_stage_names(stage) { return false; }
    var count = stage.nodes.length;
    if count > ~convert(usize, 0) - store.next_id { return false; }
    var components: usize = 0;
    for(var i: usize = 0; i < count; ++i) {
        var node = stage.nodes.data[i].node;
        if node.component_count > ~convert(usize, 0) - components { return false; }
        components += node.component_count;
    }
    for(var i: usize = 0; i < stage.leases.length; ++i) {
        var lease = &stage.leases.data[i];
        var added = lease.node.component_count - lease.components;
        if added > ~convert(usize, 0) - components { return false; }
        components += added;
    }
    if components > ~convert(usize, 0) - store.component_count { return false; }
    if components > ~convert(usize, 0) - count { return false; }
    var entries = components + count;
    if entries > ~convert(usize, 0) / 2 { return false; }
    var capacity: usize = 8;
    while capacity < entries * 2 {
        if capacity > ~convert(usize, 0) / 2 { return false; }
        capacity *= 2;
    }
    var counts: vector(EntityStageCount);
    vector_init(EntityStageCount, &counts);
    if !vector_reserve(EntityStageCount, &counts, capacity) { return false; }
    counts.length = capacity;
    fill(counts.data, 0, capacity * sizeof(EntityStageCount));
    for(var i: usize = 0; i < count; ++i) {
        var node = stage.nodes.data[i].node;
        entity_stage_count(&counts, node.parent).children++;
        for(var j: usize = 0; j < node.component_count; ++j) {
            entity_stage_count(&counts, node.components[j].type).instances++;
        }
    }
    for(var i: usize = 0; i < stage.leases.length; ++i) {
        var lease = &stage.leases.data[i];
        for(var j = lease.components; j < lease.node.component_count; ++j) {
            entity_stage_count(&counts, lease.node.components[j].type).instances++;
        }
    }
    var success = true;
    for(var i: usize = 0; i < capacity && success; ++i) {
        var entry = &counts.data[i];
        var node = entry.entity;
        if node == null { continue; }
        if entry.children > ~convert(usize, 0) - node.child_count
            || entry.instances > ~convert(usize, 0) - node.instance_count { success = false; break; }
        var children = node.child_count + entry.children;
        if children > node.child_capacity {
            var memory = realloc(EntityChild, node.children, children);
            if memory == null { success = false; break; }
            node.children = memory;
            node.child_capacity = children;
        }
        var instances = node.instance_count + entry.instances;
        if instances > node.instance_capacity {
            var memory = realloc(EntityComponent*, node.instances, instances);
            if memory == null { success = false; break; }
            node.instances = memory;
            node.instance_capacity = instances;
        }
    }
    vector_dispose(EntityStageCount, &counts);
    if !success { return false; }
    for(var i: usize = 0; success && i < stage.nodes.length; i++) {
        success = entity_table_prepare(stage.nodes.data[i].node, null, null);
    }
    for(var i: usize = 0; success && i < stage.leases.length; i++) {
        success = entity_table_prepare(stage.leases.data[i].node, null, null);
    }
    if !success {
        foreach(var &entry in &stage.nodes) { entity_table_unprepare(entry.node); }
        foreach(var &lease in &stage.leases) { entity_table_unprepare(lease.node); }
    }
    return success;
}

fn entity_stage_components(node: Entity*, first: usize): void {
    for(var j = first; j < node.component_count; ++j) {
        var component = node.components[j];
        var type = component.type;
        component.type_index = type.instance_count;
        type.instances[type.instance_count] = component;
        type.instance_count++;
        entity_retain(type);
        node.store.component_count++;
    }
}

export fn entity_stage_publish(stage: EntityStage*): bool {
    if stage.anchor == null || !entity_stage_prepare(stage) { return false; }
    entity_stage_hold(stage);
    var store = stage.anchor.store;
    for(var i: usize = 0; i < stage.nodes.length; ++i) {
        var node = stage.nodes.data[i].node;
        node.id = store.next_id;
        store.next_id++;
        store.entity_count++;
        node.stage = null;
        node.storage = null;
        entity_stage_components(node, 0);
        entity_table_publish(node);
        // Transfer the stage's one reference into its parent's ownership.
        var parent = node.parent;
        parent.children[parent.child_count].entity = node;
        parent.children[parent.child_count].name = stage.nodes.data[i].name;
        parent.child_count++;
    }
    for(var i: usize = 0; i < stage.leases.length; ++i) {
        var lease = &stage.leases.data[i];
        lease.node.stage = null;
        lease.node.storage = null;
        entity_stage_components(lease.node, lease.components);
        entity_table_publish(lease.node);
    }
    vector_dispose(EntityStageNode, &stage.nodes);
    vector_dispose(Entity*, &stage.references);
    vector_dispose(EntityStageLease, &stage.leases);
    entity_component_pool_detach(&stage.storage);
    entity_release(stage.anchor);
    stage.anchor = null;
    free(stage);
    return true;
}

// Call only after the owning worker joins. Finalizers run on the coordinator;
// discarded payloads must not have escaped into an existing published payload.
export fn entity_stage_discard(stage: EntityStage*): void {
    entity_stage_hold(stage);
    for(var i: usize = 0; i < stage.nodes.length; ++i) {
        var node = stage.nodes.data[i].node;
        for(var j: usize = 0; j < node.component_count; ++j) {
            var component = node.components[j];
            if component.type.lifecycle != 0 {
                tower_entity_finalize(component.type.lifecycle, component, component.data);
            }
            entity_component_free(component);
        }
        free(node.components);
        free(node.children);
        free(node.instances);
        free(stage.nodes.data[i].name);
        free(node);
    }
    for(var i: usize = 0; i < stage.leases.length; ++i) {
        var lease = &stage.leases.data[i];
        var node = lease.node;
        for(var j = lease.components; j < node.component_count; ++j) {
            var component = node.components[j];
            if component.type.lifecycle != 0 {
                tower_entity_finalize(component.type.lifecycle, component, component.data);
            }
            entity_component_free(component);
        }
        node.component_count = lease.components;
        node.stage = null;
        node.storage = null;
    }
    vector_dispose(EntityStageNode, &stage.nodes);
    vector_dispose(Entity*, &stage.references);
    vector_dispose(EntityStageLease, &stage.leases);
    entity_component_pool_detach(&stage.storage);
    if stage.anchor != null { entity_release(stage.anchor); }
    stage.anchor = null;
    free(stage);
}

// Names are owned by the stage until publication transfers them into containment.
// Collision checks and shared parent updates happen only on the coordinator.
export fn entity_stage_create_named(stage: EntityStage*, parent: Entity*, name: u8*): Entity* {
    if name == null || *name == 0 { return entity_stage_create(stage, parent); }
    var length: usize = 0;
    while name[length] != 0 { length++; }
    if length == ~convert(usize, 0) { return null; }
    var owned = alloc(u8, length + 1);
    if owned == null { return null; }
    copy(owned, name, length + 1);
    var node = entity_stage_create(stage, parent);
    if node == null { free(owned); return null; }
    stage.nodes.data[stage.nodes.length - 1].name = owned;
    return node;
}

struct EntityStageNameIndex { parent: Entity*; name: u8*; }

fn entity_stage_names(stage: EntityStage*): bool {
    var count: usize = 0;
    foreach(var &entry in &stage.nodes) { if entry.name != null { count++; } }
    if count == 0 { return true; }
    var maximum = ~convert(usize, 0);
    if count > maximum / 2 { return false; }
    var capacity: usize = 4;
    while capacity < count * 2 {
        if capacity > maximum / 2 { return false; }
        capacity *= 2;
    }
    if capacity > maximum / sizeof(EntityStageNameIndex) { return false; }
    var names = alloc(EntityStageNameIndex, capacity);
    if names == null { return false; }
    defer free(names);
    fill(names, 0, capacity * sizeof(EntityStageNameIndex));
    var mask = capacity - 1;
    foreach(var &entry in &stage.nodes) {
        if entry.name == null { continue; }
        var parent = entry.node.parent;
        if entity_member_index(parent, entry.name) < parent.child_count { return false; }
        var hash = bits(usize, parent) / sizeof(Entity*);
        for(var i: usize = 0; entry.name[i] != 0; i++) { hash = (hash * 33) ^ convert(usize, entry.name[i]); }
        var index = hash & mask;
        while names[index].parent != null {
            if names[index].parent == parent && entity_name_equal(names[index].name, entry.name) { return false; }
            index = (index + 1) & mask;
        }
        names[index].parent = parent;
        names[index].name = entry.name;
    }
    return true;
}

// Queue exactly the references owned by completed private payloads. Their
// ordinary finalizers release these references on destruction/discard. Inputs
// must remain live until hold: keep their source owner alive or retain the pin.
// The worker only changes its stage; it never touches shared reference counts.
export fn entity_stage_references(stage: EntityStage*, nodes: Entity**, count: usize): bool {
    if stage.anchor == null || count > ~convert(usize, 0) - stage.references.length { return false; }
    for(var i: usize = 0; i < count; i++) {
        var node = nodes[i];
        if node != null && (node.store != stage.anchor.store || node.stage != null) { return false; }
    }
    if !vector_reserve(&stage.references, stage.references.length + count) { return false; }
    for(var i: usize = 0; i < count; i++) {
        if nodes[i] != null { stage.references.data[stage.references.length++] = nodes[i]; }
    }
    return true;
}

// Coordinator only, after the worker joins and before releasing the last input
// pin. This transfers queued ownership into references without publishing rows.
// Publication retries do not retain twice; discard retains before finalization.
export fn entity_stage_hold(stage: EntityStage*): void {
    while stage.held < stage.references.length {
        entity_retain(stage.references.data[stage.held]);
        stage.held++;
    }
}

import tower;

// Shared compiler entities. Raw pointers are valid only while their owner lives.
// Components keep stable addresses; type indexes support component-wise queries.
struct EntityStore {
    next_id: usize;
    entity_count: usize;
    component_count: usize;
    views: usize;
    deferred: Entity*;
    reclaiming: usize;
    // Borrowed owner context, installed before the first entity is created.
    // The store does not interpret or destroy it; compiler worlds use it to
    // resolve node-local component identities without an ambient singleton.
    context: void*;
    storage: EntityComponentPool;
    tables: EntityTable*[256];
}

// Allocation indexes only. Canonical component identity/payloads stay on entities.
// A coordinator owns the store pool; a worker owns its stage's separate pool.
struct EntityComponentPool { first: EntityComponentPage*; }
struct EntityComponentPage {
    pool: EntityComponentPool*;
    previous: EntityComponentPage*;
    next: EntityComponentPage*;
    type_id: usize;
    used: usize;
    live: usize;
    capacity: usize;
    stride: usize;
    components: EntityComponent*;
    data: u8*;
}

struct EntityChild {
    entity: Entity*;
    name: u8*;
}

struct Entity {
    store: EntityStore*;
    id: usize;
    references: usize;
    parent: Entity*;
    children: EntityChild*;
    child_count: usize;
    child_capacity: usize;
    components: EntityComponent**;
    component_count: usize;
    component_capacity: usize;
    instances: EntityComponent**;
    instance_count: usize;
    instance_capacity: usize;
    registered: bool;
    queued: bool;
    data_size: usize;
    data_alignment: usize;
    lifecycle: usize;
    deferred: Entity*;
    // A private new entity, or an existing entity exclusively leased to one
    // stage. Component indexes publish after pinned readers join. A lease owns
    // the owner's component list; unrelated readers may only use pinned indexes.
    stage: void*;
    storage: EntityComponentPool*;
    table: EntityTable*;
    table_row: usize;
    pending_table: EntityTable*;
}

// The coordinator opens/closes views and owns refcounts. Workers borrow the
// view and query ranges until they join; no worker mutates this bookkeeping.
// Payload access still needs declared read/write permissions. A view pins
// structure and lifetime, not arbitrary writes through Foundation raw pointers.
struct EntityView {
    store: EntityStore*;
    queries: EntityTableQuery*;
}

struct EntityQuery {
    data: EntityComponent**;
    length: usize;
}

struct EntityComponent {
    owner: Entity*;
    type: Entity*;
    allocation: u8*;
    data: u8*;
    type_index: usize;
    page: EntityComponentPage*;
