    table: EntityTable*;
    columns: usize*;
    arity: usize;
    first: usize;
    length: usize;
}

import tower;

// Strict binary floating-point operations over their exact storage bits. These
// ordinary Tower functions are shared by runtime execution and staged evaluation.
// No host floating environment, allocation, global state or exception flags.
var Float32Width: u32 = 32;
var Float64Width: u32 = 64;
var Float32Fraction: u32 = 23;
var Float64Fraction: u32 = 52;
var Float32Bias: i32 = 127;
var Float64Bias: i32 = 1023;
var Float32Sign: u64 = 2147483648;
var Float64Sign: u64 = 9223372036854775808;
var Float32Infinity: u64 = 2139095040;
var Float64Infinity: u64 = 9218868437227405312;
var FloatGuardBits: u32 = 3;
var FloatLimbBits: u32 = 32;
var FloatLimbMask: u64 = 4294967295;

enum FloatClass: u32 { Zero, Finite, Infinity, NaN }
enum FloatOrder: i32 { Less = -1, Equal = 0, Greater = 1, Unordered = 2 }
// Shared operation ordering with Foundation's scalar binary operations.
enum FloatOperation: u32 { Add = 0, Subtract = 1, Multiply = 2, Divide = 3, Equal = 8, NotEqual = 9, Less = 10, LessEqual = 11, Greater = 12, GreaterEqual = 13 }

struct FloatLayout { fraction: u32; bias: i32; sign: u64; infinity: u64; }
struct FloatParts { negative: bool; category: FloatClass; significand: u64; exponent: i32; }
struct FloatProduct { low: u64; high: u64; }

fn float_layout(width: u32): FloatLayout {
    if width == Float32Width {
        return { fraction: Float32Fraction, bias: Float32Bias, sign: Float32Sign, infinity: Float32Infinity };
    }
    if width == Float64Width {
        return { fraction: Float64Fraction, bias: Float64Bias, sign: Float64Sign, infinity: Float64Infinity };
    }
    trap("Unsupported floating-point width", 0);
    return default;
}

fn float_nan(layout: FloatLayout): u64 {
    return layout.infinity | (convert(u64, 1) << (layout.fraction - 1));
}

fn float_signed(magnitude: u64, negative: bool, layout: FloatLayout): u64 {
    return magnitude | (negative ? layout.sign : 0);
}

fn float_unpack(raw: u64, layout: FloatLayout): FloatParts {
    var hidden = convert(u64, 1) << layout.fraction;
    var fraction = raw & (hidden - 1);
    var exponent = raw & layout.infinity;
    var result: FloatParts = { negative: (raw & layout.sign) != 0,
        category: FloatClass.Finite, significand: fraction, exponent: 1 - layout.bias };
    if exponent == layout.infinity {
        result.category = fraction == 0 ? FloatClass.Infinity : FloatClass.NaN;
        return result;
    }
    if exponent != 0 {
        result.significand |= hidden;
        result.exponent = convert(i32, exponent >> layout.fraction) - layout.bias;
    } else {
        if fraction == 0 { result.category = FloatClass.Zero; return result; }
        while result.significand < hidden { result.significand <<= 1; result.exponent--; }
    }
    return result;
}

// Every discarded nonzero bit contributes to the final sticky bit. Counts at
// or above the storage width must not inherit Tower's masked shift semantics.
fn float_shift_jam(value: u64, count: u32): u64 {
    if count == 0 { return value; }
    if count >= Float64Width { return convert(u64, value != 0); }
    var lost = value & ((convert(u64, 1) << count) - 1);
    return (value >> count) | convert(u64, lost != 0);
}

// extended has three guard/round/sticky bits. Normalize and round exactly once,
// including the normal/subnormal boundary and carry into the exponent.
fn float_pack(negative: bool, exponent: i32, extended: u64, layout: FloatLayout): u64 {
    if extended == 0 { return float_signed(0, negative, layout); }
    var hidden = convert(u64, 1) << layout.fraction;
    var normal = hidden << FloatGuardBits;
    var minimum = 1 - layout.bias;
    while extended >= (normal << 1) { extended = float_shift_jam(extended, 1); exponent++; }
    while extended < normal && exponent > minimum { extended <<= 1; exponent--; }
    if exponent < minimum { extended = float_shift_jam(extended, convert(u32, minimum - exponent)); exponent = minimum; }
    var significand = extended >> FloatGuardBits;
    var half = convert(u64, 1) << (FloatGuardBits - 1);
    var remainder = extended & ((half << 1) - 1);
    if remainder > half || (remainder == half && (significand & 1) != 0) { significand++; }
    if significand >= (hidden << 1) { significand >>= 1; exponent++; }
    if exponent > layout.bias { return float_signed(layout.infinity, negative, layout); }
    var encoded: u64 = 0;
    if significand >= hidden { encoded = convert(u64, exponent + layout.bias) << layout.fraction; }
    return float_signed(encoded | (significand & (hidden - 1)), negative, layout);
}

fn float_add_bits(a: u64, b: u64, layout: FloatLayout): u64 {
    var left = float_unpack(a, layout);
    var right = float_unpack(b, layout);
    if left.category == FloatClass.NaN || right.category == FloatClass.NaN { return float_nan(layout); }
    if left.category == FloatClass.Infinity {
        if right.category == FloatClass.Infinity && left.negative != right.negative { return float_nan(layout); }
        return float_signed(layout.infinity, left.negative, layout);
    }
    if right.category == FloatClass.Infinity { return float_signed(layout.infinity, right.negative, layout); }
    if left.category == FloatClass.Zero && right.category == FloatClass.Zero {
        return float_signed(0, left.negative && right.negative, layout);
    }
    if left.category == FloatClass.Zero { return b & ((layout.sign - 1) | layout.sign); }
    if right.category == FloatClass.Zero { return a & ((layout.sign - 1) | layout.sign); }
    if left.exponent < right.exponent || (left.exponent == right.exponent && left.significand < right.significand) {
        var swap = left; left = right; right = swap;
    }
    var x = left.significand << FloatGuardBits;
    var y = float_shift_jam(right.significand << FloatGuardBits, convert(u32, left.exponent - right.exponent));
    var sum = left.negative == right.negative ? x + y : x - y;
    if sum == 0 { return 0; }
    return float_pack(left.negative, left.exponent, sum, layout);
}

fn float_product(a: u64, b: u64): FloatProduct {
    var low = (a & FloatLimbMask) * (b & FloatLimbMask);
    var middle = (a >> FloatLimbBits) * (b & FloatLimbMask);
    var other = (a & FloatLimbMask) * (b >> FloatLimbBits);
    var high = (a >> FloatLimbBits) * (b >> FloatLimbBits);
    var next = low + (middle << FloatLimbBits);
    high += (middle >> FloatLimbBits) + convert(u64, next < low);
    low = next;
    next = low + (other << FloatLimbBits);
    high += (other >> FloatLimbBits) + convert(u64, next < low);
    return { low: next, high: high };
}

fn float_multiply_bits(a: u64, b: u64, layout: FloatLayout): u64 {
    var left = float_unpack(a, layout);
    var right = float_unpack(b, layout);
    var negative = left.negative != right.negative;
    if left.category == FloatClass.NaN || right.category == FloatClass.NaN { return float_nan(layout); }
    if left.category == FloatClass.Infinity || right.category == FloatClass.Infinity {
        if left.category == FloatClass.Zero || right.category == FloatClass.Zero { return float_nan(layout); }
        return float_signed(layout.infinity, negative, layout);
    }
    if left.category == FloatClass.Zero || right.category == FloatClass.Zero { return float_signed(0, negative, layout); }
    var product = float_product(left.significand, right.significand);
    var shift = layout.fraction - FloatGuardBits;
    var extended = (product.high << (Float64Width - shift)) | float_shift_jam(product.low, shift);
    return float_pack(negative, left.exponent + right.exponent, extended, layout);
}

fn float_divide_bits(a: u64, b: u64, layout: FloatLayout): u64 {
    var left = float_unpack(a, layout);
    var right = float_unpack(b, layout);
    var negative = left.negative != right.negative;
    if left.category == FloatClass.NaN || right.category == FloatClass.NaN { return float_nan(layout); }
    if (left.category == FloatClass.Infinity && right.category == FloatClass.Infinity)
        || (left.category == FloatClass.Zero && right.category == FloatClass.Zero) { return float_nan(layout); }
    if left.category == FloatClass.Infinity || right.category == FloatClass.Zero {
        return float_signed(layout.infinity, negative, layout);
    }
    if left.category == FloatClass.Zero || right.category == FloatClass.Infinity { return float_signed(0, negative, layout); }
    var exponent = left.exponent - right.exponent;
    var remainder = left.significand;
    if remainder < right.significand { remainder <<= 1; exponent--; }
    var quotient: u64 = 1;
    remainder -= right.significand;
    for(var bit: u32 = 0; bit < layout.fraction + FloatGuardBits; bit++) {
        remainder <<= 1;
        quotient <<= 1;
        if remainder >= right.significand { remainder -= right.significand; quotient |= 1; }
    }
    quotient |= convert(u64, remainder != 0);
    return float_pack(negative, exponent, quotient, layout);
}

fn float_order(a: u64, b: u64, layout: FloatLayout): FloatOrder {
    var left = float_unpack(a, layout);
    var right = float_unpack(b, layout);
    if left.category == FloatClass.NaN || right.category == FloatClass.NaN { return FloatOrder.Unordered; }
    var mask = layout.sign - 1;
    var x = a & mask;
    var y = b & mask;
    if x == 0 && y == 0 { return FloatOrder.Equal; }
    if left.negative != right.negative { return left.negative ? FloatOrder.Less : FloatOrder.Greater; }
    if x == y { return FloatOrder.Equal; }
    return (x < y) != left.negative ? FloatOrder.Less : FloatOrder.Greater;
}

fn tower_float_binary(a: u64, b: u64, operation: u32, width: u32): u64 {
    var layout = float_layout(width);
    var op = convert(FloatOperation, operation);
    if op == FloatOperation.Add { return float_add_bits(a, b, layout); }
    if op == FloatOperation.Subtract { return float_add_bits(a, b ^ layout.sign, layout); }
    if op == FloatOperation.Multiply { return float_multiply_bits(a, b, layout); }
    if op == FloatOperation.Divide { return float_divide_bits(a, b, layout); }
    var order = float_order(a, b, layout);
    if op == FloatOperation.Equal { return convert(u64, order == FloatOrder.Equal); }
    if op == FloatOperation.NotEqual { return convert(u64, order != FloatOrder.Equal); }
    if op == FloatOperation.Less { return convert(u64, order == FloatOrder.Less); }
    if op == FloatOperation.LessEqual { return convert(u64, order == FloatOrder.Less || order == FloatOrder.Equal); }
    if op == FloatOperation.Greater { return convert(u64, order == FloatOrder.Greater); }
    if op == FloatOperation.GreaterEqual { return convert(u64, order == FloatOrder.Greater || order == FloatOrder.Equal); }
    trap("Unsupported floating-point operation", 0);
    return 0;
}

fn float_integer_mask(width: u32): u64 {
    return width == Float64Width ? ~convert(u64, 0) : (convert(u64, 1) << width) - 1;
}

fn tower_float_from_integer(raw: u64, integer_width: u32, signed: bool, width: u32): u64 {
    var layout = float_layout(width);
    var mask = float_integer_mask(integer_width);
    raw &= mask;
    var negative = signed && (raw & ((mask >> 1) + 1)) != 0;
    var magnitude = negative ? (convert(u64, 0) - raw) & mask : raw;
    if magnitude == 0 { return 0; }
    var exponent: u32 = 0;
    var scan = magnitude;
    while scan > 1 { scan >>= 1; exponent++; }
    var precision = layout.fraction + FloatGuardBits;
    var extended = exponent > precision ? float_shift_jam(magnitude, exponent - precision) : magnitude << (precision - exponent);
    return float_pack(negative, convert(i32, exponent), extended, layout);
}

fn tower_float_convert(raw: u64, source_width: u32, width: u32): u64 {
    var source = float_layout(source_width);
    var layout = float_layout(width);
    var value = float_unpack(raw, source);
    if value.category == FloatClass.NaN { return float_nan(layout); }
    if value.category == FloatClass.Infinity { return float_signed(layout.infinity, value.negative, layout); }
    if value.category == FloatClass.Zero { return float_signed(0, value.negative, layout); }
    var precision = layout.fraction + FloatGuardBits;
    var extended = source.fraction > precision ? float_shift_jam(value.significand, source.fraction - precision)
        : value.significand << (precision - source.fraction);
    return float_pack(value.negative, value.exponent, extended, layout);
}

// Checked truncation toward zero. A negative fraction that truncates to zero is
// representable even in an unsigned destination; NaN/infinity are never integers.
fn tower_float_to_integer(raw: u64, width: u32, integer_width: u32, signed: bool, ok: bool*): u64 {
    *ok = false;
    var layout = float_layout(width);
    var value = float_unpack(raw, layout);
    if value.category == FloatClass.NaN || value.category == FloatClass.Infinity { return 0; }
    var magnitude: u64 = 0;
    if value.category != FloatClass.Zero && value.exponent >= 0 {
        if value.exponent >= convert(i32, Float64Width) { return 0; }
        var exponent = convert(u32, value.exponent);
        magnitude = exponent > layout.fraction ? value.significand << (exponent - layout.fraction)
            : value.significand >> (layout.fraction - exponent);
    }
    var mask = float_integer_mask(integer_width);
    var limit = signed ? (mask >> 1) + convert(u64, value.negative) : mask;
    if magnitude > limit || (!signed && value.negative && magnitude != 0) { return 0; }
    *ok = true;
    return (value.negative ? convert(u64, 0) - magnitude : magnitude) & mask;
}

import tower;
import float_bits;

// Decimal conversion uses bounded, caller-local scratch, never the host's
// locale, floating environment or strtod. The bound is a diagnostic resource
// limit on a single literal, not a limit on representable floating values.
var FloatDecimalDigitLimit: usize = 4096;
var FloatDecimalExponentLimit: i32 = 100000;
var FloatDecimalCertainRange: i32 = 350;
fn float_big_storage(): type { return u32[512]; }
fn float_text_buffer(): type { return u8[32]; }
fn float_exact_decimal_storage(): type { return u8[1200]; }
var FloatBigLimbs = sizeof(float_big_storage()) / sizeof(u32);
var FloatTextCapacity = sizeof(float_text_buffer());
var Float32DecimalDigits: usize = 9;
var Float64DecimalDigits: usize = 17;
var FloatDecimalBase: u32 = 10;
var FloatDecimalOddFactor: u32 = 5;
var FloatDecimalZero: u8 = 48;
var FloatDecimalNine: u8 = 57;
var FloatDecimalPoint: u8 = 46;
var FloatDecimalMinus: u8 = 45;
var FloatDecimalPlus: u8 = 43;
var FloatDecimalExponent: u8 = 101;
var FloatDecimalUpperExponent: u8 = 69;

enum FloatParseStatus: u32 { Valid, Invalid, Overflow, DigitLimit }
struct FloatBig { limbs: float_big_storage(); length: usize; }

fn float_big_set(value: FloatBig*, number: u64): void {
    value.length = number == 0 ? 0 : 1;
    value.limbs[0] = convert(u32, number & FloatLimbMask);
    if number > FloatLimbMask { value.limbs[1] = convert(u32, number >> FloatLimbBits); value.length = 2; }
}

fn float_big_multiply(value: FloatBig*, factor: u32, extra: u32): void {
    var carry = convert(u64, extra);
    for (var i: usize = 0; i < value.length; i++) {
        var product = convert(u64, value.limbs[i]) * convert(u64, factor) + carry;
        value.limbs[i] = convert(u32, product & FloatLimbMask);
        carry = product >> FloatLimbBits;
    }
    if carry != 0 {
        if value.length == FloatBigLimbs { trap("Floating decimal scratch limit", 0); }
        value.limbs[value.length++] = convert(u32, carry);
    }
}

fn float_big_bits(value: FloatBig*): u32 {
    if value.length == 0 { return 0; }
    var result = convert(u32, value.length - 1) * FloatLimbBits;
    var top = value.limbs[value.length - 1];
    while top != 0 { result++; top >>= 1; }
    return result;
}

fn float_big_shift(value: FloatBig*, count: u32): void {
    if value.length == 0 || count == 0 { return; }
    var words = convert(usize, count / FloatLimbBits);
    var bits_count = count % FloatLimbBits;
    if value.length + words + 1 > FloatBigLimbs { trap("Floating decimal scratch limit", 0); }
    var carry: u32 = 0;
    for (var i: usize = 0; i < value.length; i++) {
        var combined = (convert(u64, value.limbs[i]) << bits_count) | convert(u64, carry);
        value.limbs[i] = convert(u32, combined & FloatLimbMask);
        carry = convert(u32, combined >> FloatLimbBits);
    }
    if carry != 0 { value.limbs[value.length++] = carry; }
    var index = value.length;
    while index != 0 { index--; value.limbs[index + words] = value.limbs[index]; }
    for (var i: usize = 0; i < words; i++) { value.limbs[i] = 0; }
    value.length += words;
}

fn float_big_compare(a: FloatBig*, b: FloatBig*): i32 {
    if a.length != b.length { return a.length < b.length ? -1 : 1; }
    var i = a.length;
    while i != 0 {
        i--;
        if a.limbs[i] != b.limbs[i] { return a.limbs[i] < b.limbs[i] ? -1 : 1; }
    }
    return 0;
}

fn float_big_subtract(a: FloatBig*, b: FloatBig*): void {
    var borrow: u64 = 0;
    for (var i: usize = 0; i < a.length; i++) {
        var right = borrow + (i < b.length ? convert(u64, b.limbs[i]) : 0);
        var left = convert(u64, a.limbs[i]);
        a.limbs[i] = convert(u32, (left - right) & FloatLimbMask);
        borrow = convert(u64, left < right);
    }
    while a.length != 0 && a.limbs[a.length - 1] == 0 { a.length--; }
}

fn float_big_half(value: FloatBig*): void {
    var carry: u32 = 0;
    var i = value.length;
    while i != 0 {
        i--;
        var next = value.limbs[i] << (FloatLimbBits - 1);
        value.limbs[i] = (value.limbs[i] >> 1) | carry;
        carry = next;
    }
    if value.length != 0 && value.limbs[value.length - 1] == 0 { value.length--; }
}

fn float_big_decimal(value: FloatBig*): u8 {
    var carry: u64 = 0;
    var i = value.length;
    while i != 0 {
        i--;
        var number = (carry << FloatLimbBits) | convert(u64, value.limbs[i]);
        value.limbs[i] = convert(u32, number / convert(u64, FloatDecimalBase));
        carry = number % convert(u64, FloatDecimalBase);
    }
    if value.length != 0 && value.limbs[value.length - 1] == 0 { value.length--; }
    return FloatDecimalZero + convert(u8, carry);
}

fn float_decimal_digit(byte: u8): bool { return byte >= FloatDecimalZero && byte <= FloatDecimalNine; }

fn float_parse(text: u8*, width: u32, status: FloatParseStatus*): u64 {
    *status = FloatParseStatus.Invalid;
    var layout = float_layout(width);
    var index: usize = 0;
    var negative = text[index] == FloatDecimalMinus;
    if negative || text[index] == FloatDecimalPlus { index++; }
    var numerator: FloatBig = default;
    float_big_set(&numerator, 0);
    var digits: usize = 0;
    var any = false;
    var point = false;
    var fraction: i32 = 0;
    loop {
        var byte = text[index];
        if byte == FloatDecimalPoint && !point { point = true; index++; continue; }
        if !float_decimal_digit(byte) { break; }
        any = true;
        if point {
            if fraction == FloatDecimalExponentLimit { *status = FloatParseStatus.DigitLimit; return 0; }
            fraction++;
        }
        if numerator.length != 0 || byte != FloatDecimalZero {
            if digits == FloatDecimalDigitLimit { *status = FloatParseStatus.DigitLimit; return 0; }
            digits++;
            float_big_multiply(&numerator, FloatDecimalBase, convert(u32, byte - FloatDecimalZero));
        }
        index++;
    }
    if !any { return 0; }
    var exponent: i32 = 0;
    if text[index] == FloatDecimalExponent || text[index] == FloatDecimalUpperExponent {
        index++;
        var minus = text[index] == FloatDecimalMinus;
        if minus || text[index] == FloatDecimalPlus { index++; }
        if !float_decimal_digit(text[index]) { return 0; }
        while float_decimal_digit(text[index]) {
            if exponent < FloatDecimalExponentLimit { exponent = exponent * convert(i32, FloatDecimalBase) + convert(i32, text[index] - FloatDecimalZero); }
            index++;
        }
        if minus { exponent = -exponent; }
    }
    if text[index] != 0 { return 0; }
    *status = FloatParseStatus.Valid;
    if numerator.length == 0 { return float_signed(0, negative, layout); }
    var power = exponent - fraction;
    var order = convert(i32, digits) + power - 1;
    if order > FloatDecimalCertainRange { *status = FloatParseStatus.Overflow; return 0; }
    if order < -FloatDecimalCertainRange { return float_signed(0, negative, layout); }
    var denominator: FloatBig = default;
    float_big_set(&denominator, 1);
    var count = power < 0 ? -power : power;
    for (var i: i32 = 0; i < count; i++) {
        if power < 0 { float_big_multiply(&denominator, FloatDecimalOddFactor, 0); }
        else { float_big_multiply(&numerator, FloatDecimalOddFactor, 0); }
    }
    var difference = convert(i32, float_big_bits(&numerator)) - convert(i32, float_big_bits(&denominator));
    var comparison = numerator;
    var divisor = denominator;
    if difference < 0 { float_big_shift(&comparison, convert(u32, -difference)); }
    else { float_big_shift(&divisor, convert(u32, difference)); }
    if float_big_compare(&comparison, &divisor) < 0 { difference--; }
    var scale = convert(i32, layout.fraction + FloatGuardBits) - difference;
    if scale >= 0 { float_big_shift(&numerator, convert(u32, scale)); }
    else { float_big_shift(&denominator, convert(u32, -scale)); }
    divisor = denominator;
    var bit = layout.fraction + FloatGuardBits;
    float_big_shift(&divisor, bit);
    var quotient: u64 = 0;
    loop {
        if float_big_compare(&numerator, &divisor) >= 0 {
            float_big_subtract(&numerator, &divisor);
            quotient |= convert(u64, 1) << bit;
        }
        if bit == 0 { break; }
        bit--; float_big_half(&divisor);
    }
    if numerator.length != 0 { quotient |= 1; }
    var raw = float_pack(negative, difference + power, quotient, layout);
    if (raw & layout.infinity) == layout.infinity { *status = FloatParseStatus.Overflow; }
    return raw;
}

// Caller supplies FloatTextCapacity bytes. Scientific spelling always contains
// a decimal point, so reparsing preserves floating literal inference.
fn float_text_digits(output: u8*, digits: u8*, length: usize, exponent: i32, negative: bool): usize {
    var end: usize = 0;
    if negative { output[end++] = FloatDecimalMinus; }
    output[end++] = digits[0];
    output[end++] = FloatDecimalPoint;
    if length == 1 { output[end++] = FloatDecimalZero; }
    for (var i: usize = 1; i < length; i++) { output[end++] = digits[i]; }
    if exponent != 0 {
        output[end++] = FloatDecimalExponent;
        if exponent < 0 { output[end++] = FloatDecimalMinus; exponent = -exponent; }
        var start = end;
        loop {
            output[end++] = FloatDecimalZero + convert(u8, exponent % convert(i32, FloatDecimalBase));
            exponent /= convert(i32, FloatDecimalBase);
            if exponent == 0 { break; }
        }
        var i = start;
        var j = end - 1;
        while i < j { var byte = output[i]; output[i++] = output[j]; output[j--] = byte; }
    }
    output[end] = 0;
    return end;
}

fn float_text(raw: u64, width: u32, output: u8*): usize {
    var layout = float_layout(width);
    var value = float_unpack(raw, layout);
    if value.category == FloatClass.Zero { return float_text_digits(output, "0", 1, 0, value.negative); }
    if value.category == FloatClass.NaN || value.category == FloatClass.Infinity {
        var text = value.category == FloatClass.NaN ? "nan" : (value.negative ? "-inf" : "inf");
        var end: usize = 0;
        while text[end] != 0 { output[end] = text[end]; end++; }
        output[end] = 0; return end;
    }
    var number: FloatBig;
    float_big_set(&number, value.significand);
    var binary_power = value.exponent - convert(i32, layout.fraction);
    var scale: i32 = 0;
    if binary_power >= 0 { float_big_shift(&number, convert(u32, binary_power)); }
    else {
        scale = -binary_power;
        for (var i: i32 = 0; i < scale; i++) { float_big_multiply(&number, FloatDecimalOddFactor, 0); }
    }
    var exact: float_exact_decimal_storage();
    var count: usize = 0;
    loop { exact[count++] = float_big_decimal(&number); if number.length == 0 { break; } }
    var exponent = value.category == FloatClass.Zero ? 0 : convert(i32, count) - scale - 1;
    var limit = width == Float32Width ? Float32DecimalDigits : Float64DecimalDigits;
    var length = count < limit ? count : limit;
    var digits: float_text_buffer();
    for (var i: usize = 0; i < length; i++) { digits[i] = exact[count - i - 1]; }
    if count > length {
        var last = count - length - 1;
        var half = FloatDecimalZero + convert(u8, FloatDecimalBase / 2);
        var up = exact[last] > half;
        if exact[last] == half {
            up = (digits[length - 1] & 1) != 0;
            for (var i: usize = 0; i < last; i++) { up ||= exact[i] != FloatDecimalZero; }
        }
        if up {
            var i = length;
            while i != 0 && digits[i - 1] == FloatDecimalNine { digits[--i] = FloatDecimalZero; }
            if i == 0 { digits[0] = FloatDecimalZero + 1; exponent++; }
            else { digits[i - 1]++; }
        }
    }
    while length > 1 && digits[length - 1] == FloatDecimalZero { length--; }
    return float_text_digits(output, &digits[0], length, exponent, value.negative);
}

import tower;
import bytes;
import bytes_types;
import crc32;
import deflate;

// Deterministic RFC 1952 single-member envelope around the existing raw encoder.
// No filename, comment, timestamp or host identity. No file/platform capability.
var GzipHeaderBytes: usize = 10;
var GzipWordBytes: usize = 4;
var GzipByteBits: u32 = 8;
var GzipMagicFirst: u8 = 31;
var GzipMagicSecond: u8 = 139;
var GzipDeflateMethod: u8 = 8;
var GzipPortableOS: u8 = 255;

fn gzip_word(out: ByteBuffer*, value: u32): bool {
    var byte_mask = convert(u32, ~convert(u8, 0));
    for(var at: usize = 0; at < GzipWordBytes; at++) {
        if !bytes_push(out, convert(u8, value & byte_mask)) { return false; }
        value >>= GzipByteBits;
    }
    return true;
}

// Publish only a complete member; input may borrow the previous output buffer.
// ISIZE is the input size modulo 2^32 as required by gzip, not a language limit.
fn gzip_compress(data: u8*, length: usize, out: ByteBuffer*): bool {
    if data == null && length != 0 { return false; }
    var compressed: ByteBuffer = default; var next: ByteBuffer = default;
    defer bytes_dispose(&compressed); defer bytes_dispose(&next);
    if !deflate_compress(data, length, &compressed) || !bytes_reserve(&next, GzipHeaderBytes) { return false; }
    fill(next.data, 0, GzipHeaderBytes); next.length = GzipHeaderBytes;
    var magic_first_offset: usize = 0; var magic_second_offset: usize = 1;
    var method_offset: usize = 2; var os_offset: usize = 9;
    next.data[magic_first_offset] = GzipMagicFirst; next.data[magic_second_offset] = GzipMagicSecond;
    next.data[method_offset] = GzipDeflateMethod; next.data[os_offset] = GzipPortableOS;
    var size_mask = convert(usize, ~convert(u32, 0));
    if !bytes_append(&next, compressed.data, compressed.length)
        || !gzip_word(&next, crc32_update(0, data, length))
        || !gzip_word(&next, convert(u32, length & size_mask)) { return false; }
    bytes_dispose(out); *out = next; next = default;
    return true;
}

