import tower;

// Concrete arena and map helpers; byte buffers live in bytes.tower.
// Callers initialize these structs, check allocation results, and own disposal.
// A byte arena with 16-byte allocation alignment. Reset invalidates its views.
struct ByteArena {
    data: u8*;
    used: usize;
    capacity: usize;
}

export fn arena_init(arena: ByteArena*, capacity: usize): bool {
    arena.data = alloc(u8, capacity);
    arena.used = 0;
    arena.capacity = capacity;
    var ok: bool = arena.data != null;
    return ok;
}

export fn arena_take(arena: ByteArena*, count: usize): u8* {
    if arena.data == null {
        return null;
    }
    var rounded: usize = count + 15;
    if rounded < count {
        return null;
    }
    rounded = rounded / 16;
    rounded = rounded * 16;
    var left: usize = arena.capacity -arena.used;
    if rounded > left {
        return null;
    }
    var result: u8* = arena.data + arena.used;
    arena.used = arena.used + rounded;
    return result;
}

export fn arena_reset(arena: ByteArena*): void {
    arena.used = 0;
}

export fn arena_dispose(arena: ByteArena*): void {
    free(arena.data);
    arena.data = null;
    arena.used = 0;
    arena.capacity = 0;
}

// Concrete u32 -> i32 open-addressed map. All u32 keys are available; no deletes.
struct IntMapSlot {
    key: u32;
    value: i32;
    occupied: bool;
}

struct IntMap {
    slots: IntMapSlot*;
    count: usize;
    capacity: usize;
}

export fn map_init(map: IntMap*): void {
    map.slots = null;
    map.count = 0;
    map.capacity = 0;
}

fn map_index(key: u32, capacity: usize): usize {
    var hash: u32 = key *2654435761;
    var wide: usize = convert(usize, hash);
    wide = wide % capacity;
    return wide;
}

fn map_insert(map: IntMap*, key: u32, value: i32): void {
    var index: usize = map_index(key, map.capacity);
    loop {
        if !map.slots[index].occupied {
            map.slots[index].key = key;
            map.slots[index].value = value;
            map.slots[index].occupied = true;
            map.count++;
            return;
        }
        if map.slots[index].key == key {
            map.slots[index].value = value;
            return;
        }
        index++;
        index = index % map.capacity;
    }
}

export fn map_set(map: IntMap*, key: u32, value: i32): bool {
    var half: usize = map.capacity / 2;
    if map.count >= half {
        var capacity: usize = map.capacity *2;
        if capacity < map.capacity {
            return false;
        }
        if capacity == 0 {
            capacity = 8;
        }
        var slots: IntMapSlot* = alloc(IntMapSlot, capacity);
        if slots == null {
            return false;
        }
        var size: usize = sizeof(IntMapSlot);
        var bytes: usize = capacity *size;
        fill(slots, 0, bytes);
        var old: IntMapSlot* = map.slots;
        var length: usize = map.capacity;
        map.slots = slots;
        map.capacity = capacity;
        map.count = 0;
        var i: usize = 0;
        loop {
            if i == length {
                break;
            }
            if old[i].occupied {
                map_insert(map, old[i].key, old[i].value);
            }
            i++;
        }
        free(old);
    }
    map_insert(map, key, value);
    return true;
}

export fn map_get(map: IntMap*, key: u32, result: i32*): bool {
    if map.capacity == 0 {
        return false;
    }
    var index: usize = map_index(key, map.capacity);
    loop {
        if !map.slots[index].occupied {
            return false;
        }
        if map.slots[index].key == key {
            *result = map.slots[index].value;
            return true;
        }
        index++;
        index = index % map.capacity;
    }
}

export fn map_dispose(map: IntMap*): void {
    free(map.slots);
    map_init(map);
}

import tower;

// Raw, explicitly owned storage. Initialize/dispose once; growth invalidates
// element pointers. Push currently accepts scalar/pointer elements, not copies
// of aggregate values. Type construction and specialization use shared nodes.
fn vector(T: type): type {
    struct Result {
        data: T*;
        length: usize;
        capacity: usize;
    }
    return Result;
}

fn vector_init(T: type, value: vector(T)*): void {
    value.data = null;
    value.length = 0;
    value.capacity = 0;
}

fn vector_reserve(T: type, value: vector(T)*, needed: usize): bool {
    if needed <= value.capacity {
        return true;
    }
    var maximum: usize = 0;
    maximum--;
    var size = sizeof(T);
    if size == 0 {
        return false;
    }
    var limit = maximum / size;
    if needed > limit {
        return false;
    }
    var capacity = value.capacity *2;
    if capacity < value.capacity {
        capacity = needed;
    }
    var small = capacity < 8;
    if small {
        capacity = 8;
    }
    small = capacity < needed;
    if small {
        capacity = needed;
    }
    if capacity > limit {
        capacity = needed;
    }
    var next = realloc(T, value.data, capacity);
    if next == null {
        return false;
    }
    value.data = next;
    value.capacity = capacity;
    return true;
}

fn vector_push(T: type, value: vector(T)*, element: T): bool {
    var needed = value.length + 1;
    if needed == 0 {
        return false;
    }
    var ok = vector_reserve(value, needed);
    if ok {
        value.data[value.length] = element;
        value.length = needed;
    }
    return ok;
}

fn vector_dispose(T: type, value: vector(T)*): void {
    free(value.data);
    vector_init(value);
}

// Empty/null-output failure preserves both storage and the output value.
// Output must be valid T storage outside the remaining live elements.
fn vector_pop(T: type, value: vector(T)*, output: T*): bool {
    if value.length == 0 {
        return false;
    }
    if output == null {
        return false;
    }
    var last = value.length -1;
    *output = value.data[last];
    value.length = last;
    return true;
}

// Both values must be initialized independent owners (or the same owner).
// Transfer replaces/disposes destination storage and empties the source.
// Scalar/pointer elements have no implicit destruction or deep ownership here.
fn vector_move(T: type, destination: vector(T)*, source: vector(T)*): void {
    if destination == source {
        return;
    }
    vector_dispose(destination);
    destination.data = source.data;
    destination.length = source.length;
    destination.capacity = source.capacity;
    vector_init(source);
}

// Finite borrowed traversal. Structural mutation, disposal, or growth of the
// owner invalidates the view; element writes through a borrow are permitted.
// State is ordinary local storage and iteration performs no allocation.
fn vector_iteration(T: type): type {
    struct Result {
        data: T*;
        length: usize;
        index: usize;
    }
    return Result;
}

fn vector_iterate_begin(T: type, source: vector(T)*, state: vector_iteration(T)*): void {
    state.data = source.data;
    state.length = source.length;
    state.index = 0;
}

fn vector_iterate_next(T: type, source: vector(T)*, state: vector_iteration(T)*): bool {
    if state.index == state.length {
        return false;
    }
    state.index++;
    return true;
}

fn vector_iterate_element(T: type, source: vector(T)*, state: vector_iteration(T)*): T* {
    return &state.data[state.index -1];
}

fn vector_iterate_end(T: type, source: vector(T)*, state: vector_iteration(T)*): void {}

import tower;
import vector;

// A derived dependency/execution index, never a second semantic graph. Subjects
// are borrowed shared entities; their payloads remain owned by the caller.
// Exactly one coordinator mutates this index. Workers receive immutable tickets
// and isolated inputs, then return owned results for coordinator publication.
// These functions do not make the entity store or arbitrary payloads thread safe.
enum WorkState: u32 {
    Building, Waiting, Ready, Running, Succeeded, Failed, Cancelled
}
enum WorkError: u32 {
    None, Memory, Invalid
}

enum WorkAccessMode: u32 {
    Read, Write, Structure
}

// Domain and component are caller-assigned identities, never host addresses in
// transported tickets. Ranges are half-open row/byte ranges in that component.
// Structure excludes every access in the same domain, including other types.
struct WorkAccess {
    domain: u64;
    component: u64;
    first: usize;
    end: usize;
    mode: WorkAccessMode;
    next: usize;
}

struct WorkTask {
    subject: void*;
    query: u32;
    argument: u64;
    state: WorkState;
    demanded: bool;
    blocked: bool;
    dependencies: usize;
    consumers: usize;
    remaining: usize;
    visit: u64;
    active: bool;
    access: usize;
    dispatch: u64;
}

struct WorkEdge {
    consumer: usize;
    dependency: usize;
    next_dependency: usize;
    next_consumer: usize;
}

struct WorkTicket {
    task: usize;
    revision: u64;
    profile: u64;
    dispatch: u64;
}

struct WorkFrame {
    task: usize;
    edge: usize;
}

struct WorkGraph {
    tasks: vector(WorkTask);
    edges: vector(WorkEdge);
    task_index: vector(usize);
    edge_index: vector(usize);
    ready: vector(usize);
    scratch: vector(usize);
    frames: vector(WorkFrame);
    accesses: vector(WorkAccess);
    executing: vector(usize);
    head: usize;
    running: usize;
    revision: u64;
    profile: u64;
    sweep: u64;
    cancelled: bool;
    error: WorkError;
}

fn work_init(g: WorkGraph*, revision: u64, profile: u64): void {
    *g = default;
    g.revision = revision;
    g.profile = profile;
    g.error = WorkError.None;
}

fn work_dispose(g: WorkGraph*): void {
    vector_dispose(&g.tasks);
    vector_dispose(&g.edges);
    vector_dispose(&g.task_index);
    vector_dispose(&g.edge_index);
    vector_dispose(&g.ready);
    vector_dispose(&g.scratch);
    vector_dispose(&g.frames);
    vector_dispose(&g.accesses);
    vector_dispose(&g.executing);
    *g = default;
}

// Reuse scheduling storage only after every task completed and the executor
// joined. A different identity prevents old tickets from matching reused rows.
// Cancelled executors must drain and dispose through their ownership boundary.
fn work_reset(g: WorkGraph*, revision: u64, profile: u64): bool {
    if g.running != 0 || g.cancelled || (revision == g.revision && profile == g.profile) { return false; }
    for(var i: usize = 0; i < g.tasks.length; i++) {
        var state = g.tasks.data[i].state;
        if state != WorkState.Succeeded && state != WorkState.Failed { return false; }
    }
    g.tasks.length = 0;
    g.edges.length = 0;
    g.task_index.length = 0;
    g.edge_index.length = 0;
    g.ready.length = 0;
    g.scratch.length = 0;
    g.frames.length = 0;
    g.accesses.length = 0;
    g.executing.length = 0;
    g.head = 0;
    g.sweep = 0;
    g.revision = revision;
    g.profile = profile;
    g.error = WorkError.None;
    return true;
}

fn work_ok(g: WorkGraph*): bool {
    if g.cancelled {
        return false;
    }
    var ok = g.error == WorkError.None;
    return ok;
}

fn work_memory(g: WorkGraph*, ok: bool): bool {
    if !ok {
        g.error = WorkError.Memory;
    }
    return ok;
}

// Handles are one-based, stable across storage growth. No pointers into the
// task/edge arrays survive a call that may grow them. Hash order is never output
// order; tasks and edges retain deterministic coordinator insertion order.
fn work_task(g: WorkGraph*, id: usize): WorkTask* {
    var invalid = id == 0;
    invalid ||= id > g.tasks.length;
    if invalid {
        return null;
    }
    var index = id -1;
    return &g.tasks.data[index];
}

fn work_mix(hash: u64, value: u64): u64 {
    var result = hash ^ value;
    result = result * 1099511628211;
    var high = result / 4294967296;
    result = result ^ high;
    return result;
}

fn work_key(subject: void*, query: u32, argument: u64): u64 {
    var address = bits(usize, subject);
    var hash = work_mix(14695981039346656037, convert(u64, address));
    hash = work_mix(hash, convert(u64, query));
    return work_mix(hash, argument);
}

fn work_edge_key(consumer: usize, dependency: usize): u64 {
    var hash = work_mix(14695981039346656037, convert(u64, consumer));
    return work_mix(hash, convert(u64, dependency));
}

fn work_bucket(hash: u64, count: usize): usize {
    var mask = count -1;
    var index = hash &convert(u64, mask);
    return convert(usize, index);
}

fn work_index(g: WorkGraph*, edges: bool): bool {
    var index = &g.task_index;
    var count = g.tasks.length;
    if edges {
        index = &g.edge_index;
        count = g.edges.length;
    }
    var limit = index.length / 2;
    if count < limit {
        return true;
    }
    var size = index.length *2;
    if size < index.length {
        g.error = WorkError.Memory;
        return false;
    }
    if size < 16 {
        size = 16;
    }
    if !work_memory(g, vector_reserve(index, size)) {
        return false;
    }
    index.length = size;
    var bytes = size *sizeof(usize);
    fill(index.data, 0, bytes);
    var i: usize = 0;
    for(; i < count; i++) {
        var hash: u64 = 0;
        if edges {
            var edge = &g.edges.data[i];
            hash = work_edge_key(edge.consumer, edge.dependency);
        } else {
            var task = &g.tasks.data[i];
            hash = work_key(task.subject, task.query, task.argument);
        }
        var at = work_bucket(hash, size);
        while index.data[at] != 0 {
            at++;
            at = work_bucket(convert(u64, at), size);
        }
        index.data[at] = i + 1;
    }
    return true;
}

// All key fields compare exactly. A graph's explicit profile covers target,
// semantics and capability policy; callers must not reuse it for another profile.
fn work_find(g: WorkGraph*, subject: void*, query: u32, argument: u64): usize {
    if g.task_index.length == 0 { return 0; }
    var at = work_bucket(work_key(subject, query, argument), g.task_index.length);
    while g.task_index.data[at] != 0 {
        var id = g.task_index.data[at];
        var task = work_task(g, id);
        if task.subject == subject && task.query == query && task.argument == argument { return id; }
        at = work_bucket(convert(u64, at + 1), g.task_index.length);
    }
    return 0;
}

fn work_request(g: WorkGraph*, subject: void*, query: u32, argument: u64): usize {
    if !work_ok(g) {
        return 0;
    }
    if !work_index(g, false) {
        return 0;
    }
    var hash = work_key(subject, query, argument);
    var at = work_bucket(hash, g.task_index.length);
    while g.task_index.data[at] != 0 {
        var id = g.task_index.data[at];
        var task = work_task(g, id);
        var same = task.subject == subject;
        same &&= task.query == query;
        same &&= task.argument == argument;
        if same {
            return id;
        }
        at++;
        at = work_bucket(convert(u64, at), g.task_index.length);
    }
    var size = g.tasks.length + 1;
    if size == 0 {
        g.error = WorkError.Memory;
        return 0;
    }
    if !work_memory(g, vector_reserve(&g.tasks, size)) {
        return 0;
    }
    var task = &g.tasks.data[g.tasks.length];
    fill(task, 0, sizeof(WorkTask));
    task.subject = subject;
    task.query = query;
    task.argument = argument;
    task.state = WorkState.Building;
    g.tasks.length = size;
    g.task_index.data[at] = size;
    return size;
}

// Edges may only be declared before a consumer is sealed. Duplicate reads do not
// grow the graph, including high-fan-in queries. No per-query adjacency allocation.
fn work_depend(g: WorkGraph*, consumer: usize, dependency: usize): bool {
    if !work_ok(g) {
        return false;
    }
    var task = work_task(g, consumer);
    var input = work_task(g, dependency);
    var invalid = task == null;
    invalid ||= input == null;
    invalid ||= task.state != WorkState.Building;
    if invalid {
        g.error = WorkError.Invalid;
        return false;
    }
    if !work_index(g, true) {
        return false;
    }
    var hash = work_edge_key(consumer, dependency);
    var at = work_bucket(hash, g.edge_index.length);
    while g.edge_index.data[at] != 0 {
        var index = g.edge_index.data[at] -1;
        var edge = &g.edges.data[index];
        var same = edge.consumer == consumer;
        same &&= edge.dependency == dependency;
        if same {
            return true;
        }
        at++;
        at = work_bucket(convert(u64, at), g.edge_index.length);
    }
    var size = g.edges.length + 1;
    if size == 0 {
        g.error = WorkError.Memory;
        return false;
    }
    if !work_memory(g, vector_reserve(&g.edges, size)) {
        return false;
    }
    var edge = &g.edges.data[g.edges.length];
    edge.consumer = consumer;
    edge.dependency = dependency;
    edge.next_dependency = task.dependencies;
    edge.next_consumer = input.consumers;
    task.dependencies = size;
    input.consumers = size;
    g.edges.length = size;
    g.edge_index.data[at] = size;
    return true;
}

fn work_enqueue(g: WorkGraph*, id: usize): bool {
    var task = work_task(g, id);
    var ready = task.state == WorkState.Waiting;
    ready &&= task.remaining == 0;
    ready &&= task.demanded;
    if ready {
        if !work_memory(g, vector_push(&g.ready, id)) {
            return false;
        }
        task.state = WorkState.Ready;
    }
    return true;
}

// Declare the complete access set before sealing. Empty sets mean entirely
// private work, not permission to mutate a shared world. These leases protect
// only declared accesses; the executor must also pin inputs and own scratch.
fn work_access(g: WorkGraph*, id: usize, domain: u64, component: u64, first: usize, count: usize, mode: WorkAccessMode): bool {
    if !work_ok(g) {
        return false;
    }
    var task = work_task(g, id);
    var valid = task != null;
    valid &&= task.state == WorkState.Building;
    var end = first + count;
    valid &&= end > first;
    if valid {
        valid = mode == WorkAccessMode.Read;
        valid ||= mode == WorkAccessMode.Write;
        valid ||= mode == WorkAccessMode.Structure;
    }
    if !valid {
        g.error = WorkError.Invalid;
        return false;
    }
    var size = g.accesses.length + 1;
    if size == 0 {
        g.error = WorkError.Memory;
        return false;
    }
    if !work_memory(g, vector_reserve(&g.accesses, size)) {
        return false;
    }
    var access = &g.accesses.data[g.accesses.length];
    access.domain = domain;
    access.component = component;
    access.first = first;
    access.end = end;
    access.mode = mode;
    access.next = task.access;
    task.access = size;
    g.accesses.length = size;
    return true;
}

fn work_access_conflict(a: WorkAccess*, b: WorkAccess*): bool {
    var different = a.domain != b.domain;
    if different {
        return false;
    }
    var structural = a.mode == WorkAccessMode.Structure;
    structural ||= b.mode == WorkAccessMode.Structure;
    if structural {
        return true;
    }
    different = a.component != b.component;
    if different {
        return false;
    }
    var readers = a.mode == WorkAccessMode.Read;
    readers &&= b.mode == WorkAccessMode.Read;
    if readers {
        return false;
    }
    var overlap = a.first < b.end;
    overlap &&= b.first < a.end;
    return overlap;
}

fn work_access_available(g: WorkGraph*, task: WorkTask*): bool {
    var a = task.access;
    while a != 0 {
        var ai = a -1;
        var access = &g.accesses.data[ai];
        foreach(var & executing_item in &g.executing) {
            var other = work_task(g, *executing_item);
            var b = other.access;
            while b != 0 {
                var bi = b -1;
                var held = &g.accesses.data[bi];
                if work_access_conflict(access, held) {
                    return false;
                }
                b = held.next;
            }
        }
        a = access.next;
    }
    return true;
}

fn work_seal(g: WorkGraph*, id: usize): bool {
    if !work_ok(g) {
        return false;
    }
    var task = work_task(g, id);
    var invalid = task == null;
    invalid ||= task.state != WorkState.Building;
    if invalid {
        g.error = WorkError.Invalid;
        return false;
    }
    task.state = WorkState.Waiting;
    task.remaining = 0;
    var blocked = task.blocked;
    var at = task.dependencies;
    while at != 0 {
        var index = at -1;
        var edge = &g.edges.data[index];
        var input = work_task(g, edge.dependency);
        if input.state == WorkState.Failed {
            blocked = true;
        }
        if input.state != WorkState.Succeeded {
            task.remaining++;
        }
        at = edge.next_dependency;
    }
    if blocked {
        return work_fail(g, id);
    }
    return work_enqueue(g, id);
}

fn work_demand(g: WorkGraph*, id: usize): bool {
    if !work_ok(g) {
        return false;
    }
    g.scratch.length = 0;
    if !work_memory(g, vector_push(&g.scratch, id)) {
        return false;
    }
    var current: usize = 0;
    while vector_pop(&g.scratch, &current) {
        var task = work_task(g, current);
        var invalid = task == null;
        invalid ||= task.state == WorkState.Building;
        if invalid {
            g.error = WorkError.Invalid;
            return false;
        }
        if task.demanded {
            continue;
        }
        task.demanded = true;
        if task.state == WorkState.Failed {
            continue;
        }
        var at = task.dependencies;
        while at != 0 {
            var index = at -1;
            var edge = &g.edges.data[index];
            if !work_memory(g, vector_push(&g.scratch, edge.dependency)) {
                return false;
            }
            at = edge.next_dependency;
        }
        if !work_enqueue(g, current) {
            return false;
        }
    }
    return true;
}

// Taking up to N tickets gives an executor a ready batch; the queue itself is
// coordinator-owned. Publish results in semantic/source order when order matters,
// never in worker completion order. Ticket failure preserves the output.
fn work_take(g: WorkGraph*, output: WorkTicket*): bool {
    return work_take_matching(g, output, false, 0, 0);
}

fn work_take_query(g: WorkGraph*, output: WorkTicket*, query: u32): bool {
    return work_take_matching(g, output, true, query, 0);
}

// Select a requested structural job without consuming earlier independent work.
// Readiness, access exclusions and ticket validation remain the ordinary path.
fn work_take_task(g: WorkGraph*, output: WorkTicket*, task: usize): bool {
    if task == 0 { return false; }
    return work_take_matching(g, output, false, 0, task);
}

fn work_ready_sift(values: usize*, count: usize, parent: usize): void {
    var value = values[parent];
    while parent < count / 2 {
        var child = parent * 2 + 1;
        if child + 1 < count && values[child] < values[child + 1] { child++; }
        if values[child] <= value { break; }
        values[parent] = values[child];
        parent = child;
    }
    values[parent] = value;
}

// At a joined phase boundary, restore coordinator request order after parallel
// completions released consumers in timing-dependent order. This only orders
// the derived ready index; task identities, claims and receipts stay intact.
// Ordinary dispatch remains FIFO unless its phase explicitly requests ordering.
fn work_order_ready(g: WorkGraph*): bool {
    if !work_ok(g) || g.running != 0 { return false; }
    var count: usize = 0;
    var ordered = true;
    for(var i = g.head; i < g.ready.length; i++) {
        var id = g.ready.data[i];
        if id == 0 || work_task(g, id).state != WorkState.Ready { continue; }
        if count != 0 && g.ready.data[count - 1] > id { ordered = false; }
        g.ready.data[count++] = id;
    }
    g.head = 0;
    g.ready.length = count;
    if ordered { return true; }
    for(var parent = count / 2; parent != 0;) {
        work_ready_sift(g.ready.data, count, --parent);
    }
    for(var end = count; end > 1;) {
        end--;
        var value = g.ready.data[end];
        g.ready.data[end] = g.ready.data[0];
        g.ready.data[0] = value;
        work_ready_sift(g.ready.data, end, 0);
    }
    return true;
}

fn work_take_matching(g: WorkGraph*, output: WorkTicket*, filtered: bool, query: u32, wanted: usize): bool {
    if !work_ok(g) {
        return false;
    }
    if output == null {
        return false;
    }
    var i = g.head;
    while i < g.ready.length {
        var at = i;
        var id = g.ready.data[at];
        i++;
        if id == 0 {
            if at == g.head {
                g.head = i;
            }
            continue;
        }
        if wanted != 0 && wanted != id { continue; }
        var task = work_task(g, id);
        if filtered && task.query != query { continue; }
        var ready = task.state == WorkState.Ready;
        if ready {
            if !work_access_available(g, task) {
                continue;
            }
            var dispatch = task.dispatch + 1;
            if dispatch == 0 {
                g.error = WorkError.Invalid;
                return false;
            }
            var shared = task.access != 0;
            if shared {
                if !work_memory(g, vector_push(&g.executing, id)) {
                    return false;
                }
            }
            g.ready.data[at] = 0;
            task.state = WorkState.Running;
            task.dispatch = dispatch;
            g.running++;
            output.task = id;
            output.revision = g.revision;
            output.profile = g.profile;
            output.dispatch = dispatch;
            return true;
        }
        g.ready.data[at] = 0;
    }
    if g.head == g.ready.length {
        g.ready.length = 0;
        g.head = 0;
    }
    return false;
}

// A failed task blocks every dependent task without invoking it. Recoverable
// language results belong in task payloads, not in this infrastructure status.
fn work_fail(g: WorkGraph*, id: usize): bool {
    g.scratch.length = 0;
    if !work_memory(g, vector_push(&g.scratch, id)) {
        return false;
    }
    var current: usize = 0;
    while vector_pop(&g.scratch, &current) {
        var task = work_task(g, current);
        var failed = task.state == WorkState.Failed;
        var building = task.state == WorkState.Building;
        if building {
            failed = task.blocked;
        }
        if failed {
            continue;
        }
        task.blocked = true;
        if !building {
            task.state = WorkState.Failed;
        }
        var at = task.consumers;
        while at != 0 {
            var index = at -1;
            var edge = &g.edges.data[index];
            if !work_memory(g, vector_push(&g.scratch, edge.consumer)) {
                return false;
            }
            at = edge.next_consumer;
        }
    }
    return true;
}

// A receipt belongs to one dispatch, not merely to a task in a revision. A
// suspended query can run again before a delayed receipt from its old dispatch.
fn work_ticket_valid(g: WorkGraph*, ticket: WorkTicket*): bool {
    if !work_ok(g) {
        return false;
    }
    if ticket == null {
        return false;
    }
    var task = work_task(g, ticket.task);
    var valid = task != null;
    valid &&= task.state == WorkState.Running;
    valid &&= ticket.revision == g.revision;
    valid &&= ticket.profile == g.profile;
    valid &&= ticket.dispatch == task.dispatch;
    return valid;
}

// Record a value actually read from an already-published query. The executor
// must keep that input immutable for the read and join its worker before this
// coordinator call. This adds provenance without suspending/replaying work or
// releasing its access claims. Unavailable inputs require work_suspend instead.
fn work_observe(g: WorkGraph*, ticket: WorkTicket*, dependency: usize): bool {
    if !work_ticket_valid(g, ticket) { return false; }
    var input = work_task(g, dependency);
    if input == null || input.state != WorkState.Succeeded { return false; }
    var task = work_task(g, ticket.task);
    task.state = WorkState.Building;
    var attached = work_depend(g, ticket.task, dependency);
    task.state = WorkState.Running;
    return attached;
}

fn work_release(g: WorkGraph*, id: usize): void {
    g.running--;
    for(var i: usize = 0; i < g.executing.length; i++) {
        var found = g.executing.data[i] == id;
        if found {
            g.executing.length--;
            g.executing.data[i] = g.executing.data[g.executing.length];
            break;
        }
    }
}

// Suspend at an executor-owned continuation after discovering another input.
// The worker must have relinquished its borrowed views/leases before this call.
// The coordinator alone adds the edge, releases access claims, and demands the
// dependency. The payload/continuation stays on the subject's shared components;
// this derived scheduler never copies it or repeats already-observed effects.
// Seal a newly discovered dependency before suspending its consumer.
fn work_suspend(g: WorkGraph*, ticket: WorkTicket*, dependency: usize): bool {
    return work_suspend_access(g, ticket, dependency, 0, 0, 0, 0, WorkAccessMode.Read);
}

// Discover a payload range together with its dependency. The new claim applies
// on readmission, after the dependency publishes; it cannot block that producer.
// A zero count preserves the ordinary suspension contract without another claim.
fn work_suspend_access(g: WorkGraph*, ticket: WorkTicket*, dependency: usize,
    domain: u64, component: u64, first: usize, count: usize, mode: WorkAccessMode): bool {
    if !work_ticket_valid(g, ticket) {
        return false;
    }
    var input = work_task(g, dependency);
    if input == null || input.state == WorkState.Building {
        return false;
    }
    var task = work_task(g, ticket.task);
    task.state = WorkState.Building;
    var attached = work_depend(g, ticket.task, dependency);
    if attached && count != 0 { attached = work_access(g, ticket.task, domain, component, first, count, mode); }
    if !attached {
        task.state = WorkState.Running;
        return false;
    }
    work_release(g, ticket.task);
    if !work_seal(g, ticket.task) {
        return false;
    }
    return work_demand(g, dependency);
}

// Cooperative bounded execution retains its payload but gets a new receipt on
// readmission. It releases every access claim exactly like dependency suspension.
fn work_yield(g: WorkGraph*, ticket: WorkTicket*): bool {
    if !work_ticket_valid(g, ticket) { return false; }
    work_release(g, ticket.task);
    work_task(g, ticket.task).state = WorkState.Building;
    return work_seal(g, ticket.task);
}

fn work_finish(g: WorkGraph*, ticket: WorkTicket*, success: bool): bool {
    if !work_ticket_valid(g, ticket) {
        return false;
    }
    var task = work_task(g, ticket.task);
    work_release(g, ticket.task);
    if !success {
        return work_fail(g, ticket.task);
    }
    task.state = WorkState.Succeeded;
    var at = task.consumers;
    while at != 0 {
        var index = at -1;
        var edge = &g.edges.data[index];
        var consumer = work_task(g, edge.consumer);
        if consumer.state == WorkState.Waiting {
            consumer.remaining--;
            if !work_enqueue(g, edge.consumer) {
                return false;
            }
        }
        at = edge.next_consumer;
    }
    return true;
}

// Cancellation invalidates all outstanding receipts. Workers must still release
// their own unpublished results; this index neither frees nor mutates payloads.
fn work_cancel(g: WorkGraph*): void {
    g.cancelled = true;
    g.running = 0;
    g.ready.length = 0;
    g.head = 0;
    g.executing.length = 0;
    foreach(var & task in &g.tasks) {
        if task.state != WorkState.Succeeded {
            task.state = WorkState.Cancelled;
        }
    }
}

fn work_frame(g: WorkGraph*, id: usize): bool {
    var size = g.frames.length + 1;
    if !work_memory(g, vector_reserve(&g.frames, size)) {
        return false;
    }
    var task = work_task(g, id);
    var frame = &g.frames.data[g.frames.length];
    frame.task = id;
    frame.edge = task.dependencies;
    task.visit = g.sweep;
    task.active = true;
    g.frames.length = size;
    return true;
}

// Iterative DFS reports the actual closed cycle, without a host-stack or fixed
// nesting limit. Ready/running work is not a cycle. The returned handles borrow
// subjects from this graph; the caller owns the output vector.
fn work_cycle(g: WorkGraph*, root: usize, output: vector(usize)*): bool {
    output.length = 0;
    if !work_ok(g) {
        return false;
    }
    if work_task(g, root) == null {
        g.error = WorkError.Invalid;
        return false;
    }
    g.sweep++;
    if g.sweep == 0 {
        foreach(var & task in &g.tasks) {
            (*task).visit = 0;
        }
        g.sweep = 1;
    }
    g.frames.length = 0;
    if !work_frame(g, root) {
        return false;
    }
    while g.frames.length != 0 {
        var top = g.frames.length -1;
        var frame = &g.frames.data[top];
        if frame.edge == 0 {
            var task = work_task(g, frame.task);
            task.active = false;
            g.frames.length = top;
            continue;
        }
        var index = frame.edge -1;
        var edge = &g.edges.data[index];
        frame.edge = edge.next_dependency;
        var task = work_task(g, edge.dependency);
        if task.state != WorkState.Waiting {
            continue;
        }
        if task.visit == g.sweep {
            if task.active {
                var i: usize = 0;
                for(; g.frames.data[i].task != edge.dependency; i++) {}
                for(; i < g.frames.length; i++) {
                    if !work_memory(g, vector_push(output, g.frames.data[i].task)) {
                        return false;
                    }
                }
                return work_memory(g, vector_push(output, edge.dependency));
            }
        } else {
            if !work_frame(g, edge.dependency) {
                return false;
            }
        }
    }
    return false;
}

import tower;

// The platform implements only thread and semaphore primitives. All admission,
// ownership and dispatch are Tower. Jobs borrow pinned component payloads. The
// coordinator owns busy/count; workers only access a slot between handoffs.
extern fn work_thread_available(): bool;
extern fn work_thread_capacity(): usize;
// True only when keeping idle threads cannot exhaust a fixed host worker set
// needed by another world or phase. This controls lifetime, not job semantics.
extern fn work_thread_retention(): bool;
extern fn work_thread_open(argument: void*): void*;
// Native services may select a separately linked Tower callback. The callback
// still uses this pool's slot handoff, completion and cancellation protocol.
extern fn work_thread_open_named(argument: void*, posix_entry: u8*, windows_entry: u8*): void*;
extern fn work_thread_close(thread: void*): void;
extern fn work_signal_open(): void*;
extern fn work_signal_close(signal: void*): void;
extern fn work_signal_post(signal: void*): void;
extern fn work_signal_wait(signal: void*): void;
extern fn work_signal_try(signal: void*): bool;
extern fn work_kernel_execute(job: void*): void;

struct WorkSlot {
    thread: void*;
    start: void*;
    finished: void*;
    completion: void*;
    job: void*;
    execute: function(void, void*);
    busy: bool;
}

struct WorkPool {
    slots: WorkSlot*;
    count: usize;
    running: usize;
    peak: usize;
    completion: void*;
    threaded: bool;
    execute: function(void, void*);
}

var WorkPoolMaximumCapacity: usize = 256;

fn work_pool_wait(slot: WorkSlot*): void* {
    work_signal_wait(slot.start);
    return slot.job;
}

fn work_pool_complete(slot: WorkSlot*): void {
    work_signal_post(slot.finished);
    work_signal_post(slot.completion);
}

fn work_pool_entry(argument: void*): void* {
    var slot = bits(WorkSlot*, argument);
    loop {
        var job = work_pool_wait(slot);
        if job == null {
            return null;
        }
        slot.execute(job);
        // finished publishes this slot's payload; completion wakes the owner.
        // Never read job/busy again until the next start semaphore acquisition.
        work_pool_complete(slot);
    }
}

fn work_pool_open(pool: WorkPool*, capacity: usize): bool {
    return work_pool_open_named(pool, capacity, null, null);
}

fn work_pool_open_named(pool: WorkPool*, capacity: usize, entry: u8*, windows_entry: u8*): bool {
    return work_pool_open_impl(pool, capacity, entry, windows_entry, work_kernel_execute);
}

// Typed kernels share the ordinary platform entry and semaphore handoff. The
// callback is a noncapturing function; job owns/borrows its explicit context.
fn work_pool_open_kernel(pool: WorkPool*, capacity: usize, execute: function(void, void*)): bool {
    if execute == null { return false; }
    return work_pool_open_impl(pool, capacity, null, null, execute);
}

fn work_pool_open_impl(pool: WorkPool*, capacity: usize, entry: u8*, windows_entry: u8*, execute: function(void, void*)): bool {
    *pool = default;
    pool.execute = execute;
    if capacity == 0 || capacity > WorkPoolMaximumCapacity {
        return false;
    }
    // A caller's budget is an upper bound, not permission to exhaust a fixed
    // transport. Browser workers report one lane inside a worker so nested
    // phases execute inline instead of waiting on their occupied outer slots.
    var available = work_thread_capacity();
    if available == 0 { return false; }
    if capacity > available { capacity = available; }
    pool.threaded = work_thread_available() && capacity > 1;
    if !pool.threaded {
        capacity = 1;
    }
    pool.slots = alloc(WorkSlot, capacity);
    if pool.slots == null {
        return false;
    }
    fill(pool.slots, 0, capacity * sizeof(WorkSlot));
    for (var at: usize = 0; at < capacity; at++) { pool.slots[at].execute = execute; }
    if !pool.threaded {
        pool.count = 1;
        return true;
    }
    pool.completion = work_signal_open();
    if pool.completion == null {
        work_pool_close(pool);
        return false;
    }
    while pool.count < capacity {
        var slot = &pool.slots[pool.count];
        slot.completion = pool.completion;
        slot.start = work_signal_open();
        slot.finished = work_signal_open();
        pool.count++;
        if slot.start == null || slot.finished == null {
            work_pool_close(pool);
            return false;
        }
        slot.thread = entry == null && windows_entry == null ? work_thread_open(bits(void*, slot))
            : work_thread_open_named(bits(void*, slot), entry, windows_entry);
        if slot.thread == null {
            work_pool_close(pool);
            return false;
        }
    }
    return true;
}

// Admission only. A serial caller executes its own kernel before receiving;
// threaded slots execute through the callback selected when opening the pool.
fn work_pool_admit(pool: WorkPool*, job: void*): bool {
    if job == null || pool.running == pool.count {
        return false;
    }
    var index: usize = 0;
    while index < pool.count {
        var slot = &pool.slots[index];
        if !slot.busy {
            slot.job = job;
            slot.busy = true;
            pool.running++;
            if pool.running > pool.peak {
                pool.peak = pool.running;
            }
            if pool.threaded {
                work_signal_post(slot.start);
            }
            return true;
        }
        index++;
    }
    return false;
}

fn work_pool_submit(pool: WorkPool*, job: void*): bool {
    if !work_pool_admit(pool, job) { return false; }
    if !pool.threaded { pool.execute(job); }
    return true;
}

// Exactly one consumed completion token accounts for one returned result. A
// worker may finish in any order; callers publish in semantic order if needed.
fn work_pool_receive(pool: WorkPool*, wait: bool): void* {
    if pool.running == 0 {
        return null;
    }
    if pool.threaded {
        if wait {
            work_signal_wait(pool.completion);
        } else {
            if !work_signal_try(pool.completion) {
                return null;
            }
        }
    }
    var index: usize = 0;
    while index < pool.count {
        var slot = &pool.slots[index];
        if slot.busy && (!pool.threaded || work_signal_try(slot.finished)) {
            var job = slot.job;
            slot.job = null;
            slot.busy = false;
            pool.running--;
            return job;
        }
        index++;
    }
    trap("Worker completion has no owning slot", 0);
    return null;
}

fn work_pool_close(pool: WorkPool*): void {
    // Cancellation drains already admitted finite kernels before reclaiming
    // their views. It must not kill threads or free a payload still in use.
    while pool.running != 0 {
        work_pool_receive(pool, true);
    }
    var index: usize = 0;
    while index < pool.count {
        var slot = &pool.slots[index];
        if slot.thread != null {
            slot.job = null;
            work_signal_post(slot.start);
            work_thread_close(slot.thread);
        }
        work_signal_close(slot.start);
        work_signal_close(slot.finished);
        index++;
    }
    work_signal_close(pool.completion);
    free(pool.slots);
    *pool = default;
}

import tower;
import bytes;
import bytes_types;
import crc32;

// ZIP32 single-disk writer. Compression is an explicit caller capability:
// Deflate entries borrow a complete raw DEFLATE stream and its original bytes.
// Entries/order/metadata stay immutable during the call. No host clock, file
// access, filename encoding conversion or compression library is hidden here.
enum ZipMethod: u32 { Stored = 0, Deflate = 8 }
enum ZipResult: i32 { Ok, InvalidName, DuplicateName, Unsupported, Limit, AllocationFailure }
enum ZipSignature: u32 { Local = 67324752, Central = 33639248, End = 101010256 }
enum ZipNameByte: u8 { Nul = 0, Dot = 46, Slash = 47, Colon = 58, Backslash = 92 }
var ZipShortMax: u32 = 65535;

struct ZipEntry {
    name: u8*;
    name_length: usize;
    content: u8*;
    length: usize;
    compressed: u8*;
    compressed_length: usize;
    method: ZipMethod;
    flags: u32;
    made_by: u32;
    dos_time: u32;
    dos_date: u32;
    external_attributes: u32;
}

fn zip_u16(out: ByteBuffer*, value: u32): bool {
    var byte_bits: u32 = 8;
    var byte_mask = convert(u32, ~convert(u8, 0));
    return bytes_push(out, convert(u8, value & byte_mask))
        && bytes_push(out, convert(u8, (value >> byte_bits) & byte_mask));
}

fn zip_u32(out: ByteBuffer*, value: u32): bool {
    var half_bits: u32 = 16;
    return zip_u16(out, value) && zip_u16(out, value >> half_bits);
}

fn zip_name_valid(data: u8*, length: usize): bool {
    if length == 0 || data == null || data[0] == convert(u8, ZipNameByte.Slash) { return false; }
    var component: usize = 0;
    for (var at: usize = 0; at <= length; at++) {
        if at != length {
            var byte = data[at];
            if byte == convert(u8, ZipNameByte.Nul) || byte == convert(u8, ZipNameByte.Backslash)
                || byte == convert(u8, ZipNameByte.Colon) { return false; }
            if byte != convert(u8, ZipNameByte.Slash) { continue; }
        }
        var count = at - component;
        if count == 0 || count == 1 && data[component] == convert(u8, ZipNameByte.Dot)
            || count == 2 && data[component] == convert(u8, ZipNameByte.Dot)
                && data[component + 1] == convert(u8, ZipNameByte.Dot) { return false; }
        component = at + 1;
    }
    return true;
}

fn zip_same_name(left: ZipEntry*, right: ZipEntry*): bool {
    if left.name_length != right.name_length { return false; }
    for (var at: usize = 0; at < left.name_length; at++) {
        if left.name[at] != right.name[at] { return false; }
    }
    return true;
}

// Limit includes every local record, name, payload, central record and trailer.
// Reject before reading payload bytes if counts/sizes cannot fit. Failure leaves
// out's ownership and contents intact. On success out owns the completed archive;
// inputs may borrow its old contents because publication is the final operation.
fn zip32_write(entries: ZipEntry*, count: usize, limit: usize, out: ByteBuffer*): ZipResult {
    var local_header: usize = 30;
    var central_header: usize = 46;
    var end_header: usize = 22;
    var max_field = convert(usize, ZipShortMax);
    var max_offset = convert(u64, ~convert(u32, 0));
    var utf8_flag: u32 = 2048;
    var extract_version: u32 = 20;
    if count > max_field || count != 0 && entries == null { return ZipResult.Limit; }
    var total = convert(u64, end_header);
    for (var index: usize = 0; index < count; index++) {
        var entry = &entries[index];
        if entry.name_length > max_field || convert(u64, entry.length) > max_offset
            || convert(u64, entry.compressed_length) > max_offset { return ZipResult.Limit; }
        if !zip_name_valid(entry.name, entry.name_length) { return ZipResult.InvalidName; }
        if (entry.flags & ~utf8_flag) != 0 || entry.method != ZipMethod.Stored && entry.method != ZipMethod.Deflate {
            return ZipResult.Unsupported;
        }
        if entry.made_by > ZipShortMax || entry.dos_time > ZipShortMax || entry.dos_date > ZipShortMax { return ZipResult.Limit; }
        if entry.length != 0 && entry.content == null { return ZipResult.Unsupported; }
        var encoded_length = entry.method == ZipMethod.Stored ? entry.length : entry.compressed_length;
        if entry.method == ZipMethod.Deflate && (encoded_length == 0 || entry.compressed == null) {
            return ZipResult.Unsupported;
        }
        for (var prior: usize = 0; prior < index; prior++) {
            if zip_same_name(entry, &entries[prior]) { return ZipResult.DuplicateName; }
        }
        total += convert(u64, local_header + central_header) + convert(u64, entry.name_length) * 2
            + convert(u64, encoded_length);
        if total > convert(u64, limit) || total > max_offset { return ZipResult.Limit; }
    }
    if total > convert(u64, limit) { return ZipResult.Limit; }
    var archive: ByteBuffer = default;
    defer bytes_dispose(&archive);
    if !bytes_reserve(&archive, convert(usize, total)) { return ZipResult.AllocationFailure; }
    var ok = true;
    for (var index: usize = 0; index < count; index++) {
        var entry = &entries[index];
        var encoded = entry.method == ZipMethod.Stored ? entry.content : entry.compressed;
        var encoded_length = entry.method == ZipMethod.Stored ? entry.length : entry.compressed_length;
        ok &&= zip_u32(&archive, convert(u32, ZipSignature.Local)) && zip_u16(&archive, extract_version)
            && zip_u16(&archive, entry.flags) && zip_u16(&archive, convert(u32, entry.method))
            && zip_u16(&archive, entry.dos_time) && zip_u16(&archive, entry.dos_date)
            && zip_u32(&archive, crc32_update(0, entry.content, entry.length))
            && zip_u32(&archive, convert(u32, encoded_length)) && zip_u32(&archive, convert(u32, entry.length))
            && zip_u16(&archive, convert(u32, entry.name_length)) && zip_u16(&archive, 0)
            && bytes_append(&archive, entry.name, entry.name_length) && bytes_append(&archive, encoded, encoded_length);
    }
    var directory_start = archive.length;
    var offset: usize = 0;
    for (var index: usize = 0; index < count; index++) {
        var entry = &entries[index];
        var encoded_length = entry.method == ZipMethod.Stored ? entry.length : entry.compressed_length;
        ok &&= zip_u32(&archive, convert(u32, ZipSignature.Central)) && zip_u16(&archive, entry.made_by)
            && zip_u16(&archive, extract_version) && zip_u16(&archive, entry.flags)
            && zip_u16(&archive, convert(u32, entry.method)) && zip_u16(&archive, entry.dos_time)
            && zip_u16(&archive, entry.dos_date) && zip_u32(&archive, crc32_update(0, entry.content, entry.length))
            && zip_u32(&archive, convert(u32, encoded_length)) && zip_u32(&archive, convert(u32, entry.length))
            && zip_u16(&archive, convert(u32, entry.name_length)) && zip_u16(&archive, 0)
            && zip_u16(&archive, 0) && zip_u16(&archive, 0) && zip_u16(&archive, 0)
            && zip_u32(&archive, entry.external_attributes) && zip_u32(&archive, convert(u32, offset))
            && bytes_append(&archive, entry.name, entry.name_length);
        offset += local_header + entry.name_length + encoded_length;
    }
    var directory_size = archive.length - directory_start;
    ok &&= zip_u32(&archive, convert(u32, ZipSignature.End)) && zip_u16(&archive, 0) && zip_u16(&archive, 0)
        && zip_u16(&archive, convert(u32, count)) && zip_u16(&archive, convert(u32, count))
        && zip_u32(&archive, convert(u32, directory_size)) && zip_u32(&archive, convert(u32, directory_start))
        && zip_u16(&archive, 0);
    if !ok || convert(u64, archive.length) != total { return ZipResult.AllocationFailure; }
    bytes_dispose(out);
    *out = archive;
    archive = default;
    return ZipResult.Ok;
}

import tower;
import .compiler.interpreter;
import .compiler.interpreter_context_types;
import .compiler.foundation_types;
import .compiler.foundation_tags;
import .library.vector;

extern fn tower_node_create(): void*;
extern fn sem_create(parent: void*): void*;
extern fn sem_attach(node: void*, kind: u32): FoundationNode*;
extern fn sem_get(node: void*): FoundationNode*;
extern fn entity_release(node: void*): usize;

fn invocation_test_node(parent: void*, kind: u32, width: u32): void* {
    var entity = sem_create(parent);
    var node = sem_attach(entity, kind);
    node.type.scalar = SI32;
    node.type.pointer_bytes = width;
    return entity;
}

fn invocation_test_run(invocation: IMInvocation*, budget: usize): void {
    while !invocation.state.done {
        interpreter_invocation_step(invocation, budget);
    }
}

// These are ordinary Foundation entities, with the same checked components the
// frontend produces. The harness deliberately changes one condition at a time
// between completed invocations; no worker observes a mutable input graph.
export fn interpreter_invocation_tests(width: u32): u32 {
    var root = tower_node_create();
    var function = invocation_test_node(root, KFunction, width);
    var definition = sem_get(function);
    definition.frame_size = 16;
    var body = invocation_test_node(function, KBlock, width);
    definition.body = body;
    var parameter = invocation_test_node(function, KParameter, width);
    vector_push(void*, &definition.parameters, parameter);
    var input = invocation_test_node(body, KOperand, width);
    sem_get(input).binding = parameter;
    var one = invocation_test_node(body, KOperand, width);
    sem_get(one).constant = true;
    sem_get(one).bits = 1;
    var sum = invocation_test_node(body, KBinary, width);
    sem_get(sum).left = input;
    sem_get(sum).right = one;
    sem_get(sum).op = OAdd;
    var returned = invocation_test_node(body, KReturn, width);
    sem_get(returned).value = sum;
    vector_push(void*, &sem_get(body).items, returned);
    var a: IMInvocation;
    var b: IMInvocation;
    var argument: u64 = 41;
    var failures: u32 = 0;
    if !interpreter_invocation_init(&a, function, convert(usize, width), &argument, 1, true, 100) {
        failures++;
    }
    argument = 18446744073709551615;
    if !interpreter_invocation_init(&b, function, convert(usize, width), &argument, 1, true, 100) {
        failures++;
    }
    while !a.state.done || !b.state.done {
        interpreter_invocation_step(&b, 1);
        interpreter_invocation_step(&a, 3);
    }
    if a.state.failed || !a.context.returned || a.context.result != 42 {
        failures++;
    }
    if b.state.failed || !b.context.returned || b.context.result != 0 {
        failures++;
    }
    interpreter_invocation_dispose(&a);
    interpreter_invocation_dispose(&b);

    // Reading a local never initialized by this invocation is a stage error.
    var local = invocation_test_node(body, KDeclare, width);
    sem_get(local).byte_offset = 4;
    sem_get(input).binding = local;
    interpreter_invocation_init(&a, function, convert(usize, width), &argument, 1, true, 100);
    invocation_test_run(&a, 1);
    if !a.state.failed || a.context.error.length == 0 {
        failures++;
    }
    interpreter_invocation_dispose(&a);
    sem_get(input).binding = parameter;

    // Budget chunking cannot bypass deterministic total fuel.
    interpreter_invocation_init(&a, function, convert(usize, width), &argument, 1, true, 0);
    invocation_test_run(&a, 1);
    if !a.state.failed || a.state.steps != 0 {
        failures++;
    }
    interpreter_invocation_dispose(&a);

    sem_get(parameter).global = true;
    if interpreter_invocation_init(&a, function, convert(usize, width), &argument, 1, true, 100) {
        failures++;
    }
    interpreter_invocation_dispose(&a);
    sem_get(parameter).global = false;

    sem_get(returned).kind = KPrint;
    interpreter_invocation_init(&a, function, convert(usize, width), &argument, 1, true, 100);
    invocation_test_run(&a, 1);
    if !a.state.failed || a.context.output.length != 0 {
        failures++;
    }
    interpreter_invocation_dispose(&a);

    // An explicit ordinary invocation keeps runtime output behavior.
    argument = 41;
    interpreter_invocation_init(&a, function, convert(usize, width), &argument, 1, false, 0);
    invocation_test_run(&a, 1);
    if a.state.failed || a.context.output.length != 3 {
        failures++;
    } else {
        if a.context.output.data[0] != 52 || a.context.output.data[1] != 50 || a.context.output.data[2] != 10 {
            failures++;
        }
    }
    interpreter_invocation_dispose(&a);
    entity_release(root);
    return failures;
}

